Task:
Each delivery route from our depots carries a cargo weight in tonnes. A truck may only be dispatched when its load is at least 2 tonnes and at most 8 tonnes on the same leg. Check every depot and print which routes qualify for dispatch.

```jac
"""Delivery routes: check every depot and flag routes whose load is in [2, 8] tonnes."""

node Route {
    has destination: str = "";
    has weight: float = 0.0;
}

node Depot {
    has name: str = "";

    def qualifies(r: Route) -> bool {
        return r.weight >= 2.0 and r.weight <= 8.0;
    }
}

edge Serves { has since: str = ""; }

walker Dispatcher {
    has approved: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can survey with Depot entry {
        print(f"Depot: {here.name}");
        visit [->:Serves:->];
    }

    can inspect with Route entry {
        dest = here.destination;
        w = here.weight;
        ok = w >= 2.0 and w <= 8.0;
        verdict = "DISPATCH" if ok else "HOLD";
        line = f"  [{verdict}] {dest} ({w}t)";
        print(line);
        if ok {
            self.approved.append(dest);
        }
    }
}

with entry {
    north = Depot(name="North");
    south = Depot(name="South");
    root ++> north ++> south;

    north +>:Serves(since="2024-01"):+> Route(destination="Riverside", weight=3.5);
    north +>:Serves(since="2024-01"):+> Route(destination="Hilltop", weight=1.2);
    north +>:Serves(since="2024-01"):+> Route(destination="Lakeside", weight=7.8);

    south +>:Serves(since="2024-03"):+> Route(destination="Coastal", weight=9.0);
    south +>:Serves(since="2024-03"):+> Route(destination="Plains", weight=5.0);
    south +>:Serves(since="2024-03"):+> Route(destination="Mines", weight=2.0);

    d = Dispatcher();
    root spawn d;

    print(f"Approved routes: {d.approved}");
}
```

