Task:
We run several depots that each serve a set of stores. Instead of checking depots one by one, anchor one combined query from the whole list of depot nodes at once, find every store within reach, and flag the ones whose stock has dropped below 20 units.

```jac
"""Depot-to-store inventory audit: anchor a combined query at root, traverse every depot, and flag understocked stores (below 20 units)."""

node Depot {
    has name: str = "";
}

node Store {
    has name: str = "";
    has stock: int = 0;

    def is_low_stock() -> bool {
        return self.stock < 20;
    }
}

edge Supplies {
    has route: str = "";
}

walker Auditor {
    has low_stock_count: int = 0;

    can start with Root entry {
        print("Auditing depots from root...");
        visit [-->];
    }

    can audit_depot with Depot entry {
        print(f"Scanning depot: {here.name}");
        visit [->:Supplies:->];
    }

    can inspect_store with Store entry {
        if here.is_low_stock() {
            label = "LOW";
            self.low_stock_count += 1;
        } else {
            label = "OK";
        }
        print(f"  [{label}] {here.name}: {here.stock} units");
    }
}

walker Report {
    has total_low: int = 0;

    can start with Root entry {
        print("--- Inventory Audit Report ---");
        visit [-->];
    }

    can scan_depot with Depot entry {
        visit [->:Supplies:->];
    }

    can tally_store with Store entry {
        if here.is_low_stock() {
            self.total_low += 1;
            print(f"  FLAGGED: {here.name} ({here.stock} units)");
        }
    }
}

with entry {
    d1 = Depot(name="North Depot");
    d2 = Depot(name="South Depot");
    d3 = Depot(name="East Depot");

    root ++> d1 ++> d2 ++> d3;

    d1 +>:Supplies(route="Truck-A"):+> Store(name="Store 101", stock=45);
    d1 +>:Supplies(route="Truck-B"):+> Store(name="Store 102", stock=15);
    d1 +>:Supplies(route="Truck-C"):+> Store(name="Store 103", stock=8);

    d2 +>:Supplies(route="Truck-D"):+> Store(name="Store 201", stock=120);
    d2 +>:Supplies(route="Truck-E"):+> Store(name="Store 202", stock=3);

    d3 +>:Supplies(route="Truck-F"):+> Store(name="Store 301", stock=60);
    d3 +>:Supplies(route="Truck-G"):+> Store(name="Store 302", stock=19);
    d3 +>:Supplies(route="Truck-H"):+> Store(name="Store 303", stock=200);

    auditor = Auditor();
    root spawn auditor;
    print(f"Walk 1 found {auditor.low_stock_count} low-stock stores");

    reporter = Report();
    root spawn reporter;
    print(f"Walk 2 total flagged: {reporter.total_low}");
}
```

