"""Wildlife park feeding rounds.

The info kiosk greets every tour party regardless of who they are,
zookeepers feed each animal its species-appropriate meal, and school
groups just watch the animals.
"""

node Lion {
    has name: str = "";
    has fed: bool = False;
}

node Parrot {
    has name: str = "";
    has fed: bool = False;
}

node Rabbit {
    has name: str = "";
    has fed: bool = False;
}

# Zookeepers traverse the park and feed each animal its species-appropriate meal.
walker Zookeeper {
    has rounds_done: int = 0;

    can start with Root entry {
        print("Zookeeper beginning feeding rounds");
        visit [-->];
    }

    # Union trigger: one ability handles Lion | Parrot | Rabbit at once.
    # Every species shares `name` and `fed`, so the ability body only
    # touches fields present on the union.
    can feed with Lion | Parrot | Rabbit entry {
        species = here.__class__.__name__;
        if here is Lion {
            meal = "meat";
        } elif here is Parrot {
            meal = "seed";
        } else {
            meal = "standard feed";
        }
        here.fed = True;
        self.rounds_done += 1;
        print(f"  fed {here.name} the {species} a portion of {meal}");
        visit [-->];
    }
}

# School groups just observe — no feeding, no greeting.
walker SchoolGroup {
    has label: str = "";

    can start with Root entry {
        print(f"School group '{self.label}' arriving at the park");
        visit [-->];
    }

    can watch with Lion | Parrot | Rabbit entry {
        species = here.__class__.__name__;
        print(f"  {self.label} watches the {species} {here.name}");
        visit [-->];
    }
}

# The info kiosk greets every tour party regardless of who they are.
node InfoKiosk {
    has greeting: str = "Welcome to the wildlife park!";

    can greet with Zookeeper | SchoolGroup entry {
        print(self.greeting + f" Hello, {type(visitor).__name__}!");
        visitor.info_stops += 1;
