        ++> thumper;

    zookeeper = Zookeeper();
    root spawn zookeeper;

    group = SchoolGroup(label="Class 4B");
    root spawn group;

    print(f"Zookeeper completed {zookeeper.rounds_done} feedings");
    print(f"School group made {group.info_stops} kiosk stops");
}
