Task:
A maintainer on the project NPJigaK/twitch-follower-checker (TypeScript) filed this issue about hand-rolled graph machinery causing pain:

Issue #217: [P1][performance] Make follower retrieval and diff calculation linear, bounded, and rate-limit aware

## Background

Because every cursor is fetched sequentially without an upper bound and a bidirectional `Array.includes()` diff is then performed, API request count, CPU usage, and memory usage can all grow without bound for large channels.

## Current path

- [`lib/accessTwitch.ts`](https://github.com/NPJigaK/twitch-follower-checker/blob/37c0a40dc67d70110448d28ca7f6acae600b45ce/lib/accessTwitch.ts#L63-L83): recursively fetches pages with `first=100` until the cursor is exhausted
- [`lib/accessTwitch.ts`](https://github.com/NPJigaK/twitch-follower-checker/blob/37c0a40dc67d70110448d28ca7f6acae600b45ce/lib/accessTwitch.ts#L89-L100): runs `includes` in both directions inside `filter`

Worst-case comparison counts:

- 10,000 items: approximately 200 million
- 25,000 items: approximately 1.25 billion
- 50,000 items: approximately 5 billion (approximately 9.2 seconds in an isolated Node measurement for disjoint sets)
- 100,000 items: approximately 20 billion

50,000 followers require at least 500 API pages, and 100,000 followers require 1,000 pages. This can lead to HTTP 429 responses, long main-thread blocking, memory growth, and an unresponsive browser tab.

## Implementation direction

- Use `Set` / `Map` ID lookups and make the diff O(N)
- Replace recursive pagination with an explicit loop
- Maintain a visited-cursor set
- Add page, item, and elapsed-time budgets
- Support cancellation through `AbortController`
- Display progress
- Handle `Ratelimit-Remaining` / `Ratelimit-Reset`
- Deduplicate by `user_id`
- Treat `total` as a diagnostic value because it changes dynamically
- Debounce the quick filter and benchmark large `rowData`
- Define the maximum supported item count as a product requirement

## Acceptance criteria

- [ ] Diff calculation is O(N) with respect to the old/current item counts
- [ ] Benchmarks for 10k / 25k / 50k / 100k fixtures are retained in CI or as performance tests
- [ ] Duplicate cursors do not cause unbounded fetching
- [ ] Duplicate users do not appear more than once in the display or diff
- [ ] No repeated requests are sent before the reset time after a 429 response
- [ ] State and baseline are not updated after cancellation
- [ ] A snapshot that exceeds the page/time budget is treated as incomplete
- [ ] Main-thread long tasks and heap usage are compared before and after the fix using a Chrome trace

## Evidence

- [Twitch API: Get Channel Followers](https://dev.twitch.tv/docs/api/reference/#get-channel-followers)
- [Twitch API: Pagination and rate limits](https://dev.twitch.tv/docs/api/guide/)
- [ECMAScript: Array.prototype.includes](https://tc39.es/ecma262/multipage/indexed-collections.html#sec-array.prototype.includes)


Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.

```jac
"""Rate-limited follower snapshot traversal with bounded pagination and deduplication."""

node Snapshot {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has page_budget: int = 4;
    has item_budget: int = 10;
    has rate_remaining: int = 10;
    has rate_reset_after: int = 30;
    has cancelled: bool = False;
    has baseline_count: int = 0;
    has observed_count: int = 0;
}

node Page {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has cursor: str = "";
    has item_count: int = 1;
}

node Follower {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has user_id: str = "";
    has display_name: str = "";
}

edge HasSnapshot { }
edge ContainsPage { }
edge IncludesFollower { }
edge FollowerPage { }

walker FollowerCollector {
    has max_pages: int = 0;
    has max_items: int = 0;
    has rate_remaining: int = 0;
    has rate_reset_after: int = 0;
    has pages_read: int = 0;
    has items_read: int = 0;
    has unique_users: int = 0;
    has cancelled: bool = False;
    has complete: bool = False;
    has reason: str = "";
    has visited_cursors: dict[str, bool] = {};
    has seen_users: dict[str, bool] = {};

    can start with Root entry {
        visit [->:HasSnapshot:->] else {
            self.reason = "no snapshot";
            disengage;
        }
    }

    can begin with Snapshot entry {
        self.max_pages = here.page_budget;
        self.max_items = here.item_budget;
        self.rate_remaining = here.rate_remaining;
        self.rate_reset_after = here.rate_reset_after;
        self.cancelled = here.cancelled;

        if self.cancelled {
            self.reason = "cancelled before retrieval";
            disengage;
        }

        visit [->:ContainsPage:->] else {
            self.reason = "empty snapshot";
            self.complete = True;
            disengage;
        }
    }

    can read_page with Page entry {
        if self.cancelled {
            self.reason = "cancelled";
            disengage;
        }

        if self.pages_read >= self.max_pages {
            self.reason = "page budget exceeded";
            disengage;
        }

        if here.cursor in self.visited_cursors {
            self.reason = "duplicate cursor detected";
            disengage;
        }

        if self.rate_remaining <= 0 {
            self.reason = f"rate limited; reset in {self.rate_reset_after} ticks";
            disengage;
        }

        if self.items_read + here.item_count > self.max_items {
            self.reason = "item budget exceeded";
            disengage;
        }

        self.visited_cursors[here.cursor] = True;
        self.pages_read = self.pages_read + 1;
        self.items_read = self.items_read + here.item_count;
        self.rate_remaining = self.rate_remaining - 1;

        print(f"page {here.cursor}: {self.pages_read} pages, "
              f"{self.items_read} items");

        visit [->:IncludesFollower:->] else {
            self.reason = "snapshot complete";
            self.complete = True;
            disengage;
        }
    }

    can record_follower with Follower entry {
        if here.user_id in self.seen_users {
            print(f"duplicate follower ignored: {here.user_id}");
        } else {
            self.seen_users[here.user_id] = True;
            self.unique_users = self.unique_users + 1;
            print(f"follower accepted: {here.display_name}");
        }

        visit [->:FollowerPage:->] else {
            self.reason = "snapshot complete";
            self.complete = True;
            disengage;
        }
    }

    can report with Root exit {
        print(f"retrieved {self.unique_users} unique followers across "
              f"{self.pages_read} pages; {self.reason}");
    }
}

with entry {
    snapshot = Snapshot(
        title="Channel follower snapshot",
        page_budget=4,
        item_budget=4,
        rate_remaining=5,
        rate_reset_after=30,
        baseline_count=2
    );

    page1 = Page(cursor="cursor-1");
    page2 = Page(cursor="cursor-2");
    page3 = Page(cursor="cursor-3");
    page4 = Page(cursor="cursor-4");

    alice = Follower(user_id="u1", display_name="Alice");
    bob = Follower(user_id="u2", display_name="Bob");
    alice_again = Follower(user_id="u1", display_name="Alice");
    cara = Follower(user_id="u3", display_name="Cara");

    root +>:HasSnapshot:+> snapshot;
    snapshot +>:ContainsPage:+> page1;
    page1 +>:IncludesFollower:+> alice;
    alice +>:FollowerPage:+> page2;
    page2 +>:IncludesFollower:+> bob;
    bob +>:FollowerPage:+> page3;
    page3 +>:IncludesFollower:+> alice_again;
    alice_again +>:FollowerPage:+> page4;
    page4 +>:IncludesFollower:+> cara;
    cara +>:FollowerPage:+> page2;

    root spawn FollowerCollector();
}
```

