Task:
Run feeding rounds at a wildlife park: the info kiosk greets every tour party regardless of who they are, zookeepers feed each animal its species-appropriate meal (meat for lions, seed for parrots, standard feed otherwise), and school groups just watch the animals.

```jac
"""Wildlife park feeding rounds.

The info kiosk greets every tour party via a union trigger; zookeepers
hand out species-appropriate meals; school groups only observe.
"""

node InfoKiosk {
    has kiosk_name: str;

    # Union trigger: fires for any tour party (zookeeper or school group).
    can greet with Zookeeper | SchoolGroup entry {
        print(f"Welcome {visitor.party_label} to the {self.kiosk_name} info kiosk!");
        visitor.kiosk_visits += 1;
    }
}

node Lion {
    has name: str;
    has fed: bool = False;

    def preferred_meal() -> str {
        return "meat";
    }
}

node Parrot {
    has name: str;
    has fed: bool = False;

    def preferred_meal() -> str {
        return "seed";
    }
}

node Zebra {
    has name: str;
    has fed: bool = False;

    def preferred_meal() -> str {
        return "standard feed";
    }
}

# Base animal node so a union ability can touch shared fields/methods.
node Animal {
    has name: str;
    has fed: bool = False;

    def preferred_meal() -> str {
        return "standard feed";
    }
}

# Lion / Parrot / Zebra inherit from Animal and override the meal rule.
node _Lion(Animal) {
    override def preferred_meal() -> str {
        return "meat";
    }
}

node _Parrot(Animal) {
    override def preferred_meal() -> str {
        return "seed";
    }
}

node _Zebra(Animal) {
    override def preferred_meal() -> str {
        return "standard feed";
    }
}

walker Zookeeper {
    has party_label: str = "Zookeepers";
    has kiosk_visits: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can approach_kiosk with InfoKiosk entry {
        visit [-->];
    }

    # Union trigger: serve any animal species with the right meal.
    can feed with _Lion | _Parrot | _Zebra entry {
        meal = here.preferred_meal();
        print(f"Zookeeper feeds {here.name} the {_Lion.__name__ if here.preferred_meal() == "meat" else _Parrot.__name__ if here.preferred_meal() == "seed" else _Zebra.__name__}: {meal}");
        here.fed = True;
        visit [-->];
    }
}

walker SchoolGroup {
    has party_label: str = "School Group";
    has kiosk_visits: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can approach_kiosk with InfoKiosk entry {
        visit [-->];
    }

    can observe with _Lion | _Parrot | _Zebra entry {
        print(f"School group watches {here.name} ({here.preferred_meal()})");
        visit [-->];
    }
}

with entry {
    kiosk = InfoKiosk(kiosk_name="Savannah");
    simba = _Lion(name="Simba");
    polly = _Parrot(name="Polly");
    ziggy = _Zebra(name="Ziggy");

    root ++> kiosk ++> simba ++> polly ++> ziggy;

    zk = Zookeeper();
    root spawn zk;
    sg = SchoolGroup();
    root spawn sg;

    print(f"Zookeeper greeted at {zk.kiosk_visits} kiosks, "
          f"School group greeted at {sg.kiosk_visits} kiosks");
    print(f"Simba fed? {simba.fed}; Polly fed? {polly.fed}; Ziggy fed? {ziggy.fed}");
}
