```jac
"""Online store checkout: polymorphic item handling and itemized receipt."""

node Product {
    has name: str = "";
    has price: float = 0.0;
    has weight: float = 0.0;

    def shipping_cost() -> float {
        return 0.0;
    }
    def handling_label() -> str {
        return "STANDARD";
    }
}

node PaperBook(Product) {
    has author: str = "";
    has stock: int = 0;
    override def shipping_cost() -> float {
        return 5.99 + 0.50 * self.weight;
    }
    override def handling_label() -> str {
        return "FRAGILE";
    }
}

node DigitalBook(Product) {
    has author: str = "";
    has file_size_mb: float = 0.0;
    override def shipping_cost() -> float {
        return 0.0;
    }
    override def handling_label() -> str {
        return "DIGITAL DELIVERY";
    }
}

node Electronics(Product) {
    has brand: str = "";
    has warranty_months: int = 0;
    override def shipping_cost() -> float {
        return 12.99 + 1.25 * self.weight;
    }
    override def handling_label() -> str {
        return "INSURED";
    }
}

node Clothing(Product) {
    has size: str = "";
    has color: str = "";
    override def shipping_cost() -> float {
        return 4.99 + 0.75 * self.weight;
    }
    override def handling_label() -> str {
        return "STANDARD";
    }
}

node Receipt {
    has subtotal: float = 0.0;
    has shipping: float = 0.0;
    has total: float = 0.0;
    has lines: list[str] = [];
}

walker Cashier {
    has receipt: Receipt = Receipt();

    can start with Root entry {
        visit [-->];
    }

    can ring with PaperBook | DigitalBook | Electronics | Clothing entry {
        item_cost = here.price;
        ship_cost = here.shipping_cost();
        handling = here.handling_label();
        self.receipt.subtotal += item_cost;
        self.receipt.shipping += ship_cost;
        line = f"  - {here.name} (${item_cost:.2f}) [{handling}] ship ${ship_cost:.2f}";
