    can print_receipt with Receipt entry {
        print("===== RECEIPT =====");
        for line in here.lines {
            print(line);
        }
        print(f"  Subtotal: ${here.subtotal:.2f}");
        print(f"  Shipping: ${here.shipping:.2f}");
        print(f"  TOTAL:    ${here.subtotal + here.shipping:.2f}");
        print("===================");
    }
}

with entry {
    cart = root ++> PaperBook(name="The Pragmatic Programmer", price=34.99, weight=1.2, author="Hunt & Thomas", stock=3);
    cart ++> DigitalBook(name="Clean Code (eBook)", price=24.99, weight=0.0, author="Robert C. Martin", file_size_mb=8.5);
    cart ++> Electronics(name="Wireless Headphones", price=149.00, weight=0.8, brand="Sony", warranty_months=24);
    cart ++> Clothing(name="Graphic Tee", price=19.50, weight=0.4, size="M", color="Black");

    receipt_node = ++> Receipt();
    cart ++> receipt_node;

    cashier = Cashier();
    root spawn cashier;
    receipt_node spawn Printer();
}
