Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.

```jac
"""Package dependency identity resolution.

Models how SwiftPM derives a dependency's identity across registry vs
source-control kinds, and how the `--use-registry-identity-for-scm` flag
flips the choice. The original code maintained several hand-rolled
computed properties (``nameForModuleDependencyResolutionOnly`` etc.) that
walked the package kind and derived URL path components. Here we lift
that machinery into typed edges and a walker that performs the
identity-resolution traversal over the graph.

Entities:
  * ``PackageDependency`` — a dependency declaration; carries an
    explicit identity, a kind (registry / source control), and a URL.
  * ``ResolvedPackage`` — the resolved node that adopts one of the
    candidate identities computed during resolution.

Relationships (typed edges):
  * ``Declares`` — root → ``PackageDependency`` declarations.
  * ``ResolvesTo`` — ``PackageDependency`` → ``ResolvedPackage``; the
    payload holds the chosen identity so the resolution step stays a
    pure graph walk.

Traversal:
  * ``IdentityResolver`` — starts at ``Root``, visits every
    ``PackageDependency``, picks an identity using the same rule the
    issue describes (explicit name wins; otherwise registry id; for SCM
    the URL last path component, unless ``use_registry_for_scm`` flips
    it), then traverses to the resolved node and reports the chosen
    identity. Demonstrates that the hand-rolled ``if/else`` ladder of
    computed properties collapses to one walker ability over typed
    edges.
"""

node PackageDependency {
    has kind: str = "sourceControl";  # "registry" | "sourceControl"
    has url: str = "";                # e.g. "https://github.com/apple/swift-argument-parser"
    has explicit_name: str = "";      # "" means no explicit override
}

node ResolvedPackage {
    has identity: str = "";
    has version: str = "";
}

edge Declares { }
edge ResolvesTo {
    has chosen_identity: str = "";
    has used_explicit: bool = False;
    has used_registry_id: bool = False;
    has used_path_component: bool = False;
}

walker IdentityResolver {
    has use_registry_for_scm: bool = False;
    has report: list[dict] = [];

    can start with Root entry {
        # Walk every declared dependency off the root via the typed edge.
        visit [->:Declares:->];
    }

    # The single traversal ability that performs the identity pick the
    # issue's hand-rolled computed properties were doing.
    can resolve with PackageDependency entry {
        dep = here;
        chosen = "";
        used_explicit = False;
        used_registry_id = False;
        used_path_component = False;

        # 1. Explicit name always wins, regardless of kind or flag.
        if dep.explicit_name != "" {
            chosen = dep.explicit_name;
            used_explicit = True;
        # 2. Registry dependencies use the identity embedded in the URL
        #    (registry ids are path components in the registry case).
        elif dep.kind == "registry" {
            chosen = dep.url.rsplit("/", 1)[-1] if dep.url != "" else "";
            used_registry_id = True;
        # 3. Source-control dependencies: pick between URL last path
        #    component and the registry identity depending on the flag.
        elif dep.kind == "sourceControl" {
            if self.use_registry_for_scm {
                # The flag flips SCM deps to use the registry-style id
                # (the URL's last path component is treated as if it
                # were a registry id).
                chosen = dep.url.rsplit("/", 1)[-1] if dep.url != "" else "";
                used_registry_id = True;
            } else {
                chosen = dep.url.rsplit("/", 1)[-1] if dep.url != "" else "";
                used_path_component = True;
            }
        }

        # Move to the resolved node along the typed edge and record the
        # choice on the edge payload.
        visit [->:ResolvesTo:->] else {
            disengage;
        }
    }

    can record with ResolvedPackage entry {
        # Find the inbound ResolvesTo edge so we can pull the chosen
        # identity the resolution step just computed.
        for e in [<-:ResolvesTo:-] {
            entry = {
                "dep_url": here_resolved_url(self),
                "identity": e.chosen_identity,
                "used_explicit": e.used_explicit,
                "used_registry_id": e.used_registry_id,
                "used_path_component": e.used_path_component,
            };
            self.report.append(entry);
        }
        visit [->:ResolvesTo:->];
    }
}

# Helper used by the recording ability so the report carries the source
# URL of the dependency, not the resolved node's identity (which is the
# *output* of the walk).
def here_resolved_url(w: IdentityResolver) -> str {
    for e in [<-:ResolvesTo:-] {
        # The declaring node is the source of the edge.
        for d in [e -->] {
            return d.url;
        }
    }
    return "";
}

with entry {
    # Build a small set of dependency declarations mirroring the
    # scenarios the issue enumerates.
    a = PackageDependency(
        kind="registry",
        url="https://packages.example/owner/ArgParser",
        explicit_name=""
    );
    b = PackageDependency(
        kind="sourceControl",
        url="https://github.com/apple/swift-argument-parser",
        explicit_name=""
    );
    c = PackageDependency(
        kind="sourceControl",
        url="https://github.com/apple/swift-collections",
        explicit_name="Collections"
    );

    # Create the resolved nodes and wire up the typed edges.
    ra = ResolvedPackage(identity="pending", version="1.2.0");
    rb = ResolvedPackage(identity="pending", version="1.1.0");
    rc = ResolvedPackage(identity="pending", version="1.0.5");

    root +>:Declares:+> a;
    root +>:Declares:+> b;
    root +>:Declares:+> c;

    a +>:ResolvesTo(chosen_identity="", used_explicit=False, used_registry_id=False, used_path_component=False):+> ra;
    b +>:ResolvesTo(chosen_identity="", used_explicit=False, used_registry_id=False, used_path_component=False):+> rb;
    c +>:ResolvesTo(chosen_identity="", used_explicit=False, used_registry_id=False, used_path_component=False):+> rc;

    # Walk the graph once with the flag OFF (default behavior).
    resolver = IdentityResolver(use_registry_for_scm=False);
    root spawn resolver;
    print("=== with use_registry_for_scm = False ===");
    for entry in resolver.report {
        print(entry);
    }

    # Now flip the flag and re-walk with a fresh resolver; the walker
    # is re-spawned on root so the traversal restarts cleanly.
    resolver2 = IdentityResolver(use_registry_for_scm=True);
    root spawn resolver2;
    print("=== with use_registry_for_scm = True ===");
    for entry in resolver2.report {
        print(entry);
    }
}
```

