Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.

```jac
"""Nexus-memory roadmap: tier-based routing of facts across embedding providers.

Models the v0.8.0 cost-aware routing scenario: facts sit in a session, are
extracted into a knowledge graph with typed relationships (supersedes,
relates_to), and a routing walker classifies each fact into a provider tier
(CHEAP/STANDARD/PREMIUM) based on its confidence and outgoing edges, then
walks the typed edges to mark downstream facts as invalidated.
"""

node Fact {
    has title: str = "";
    has content: str = "";
    has confidence: float = 0.0;
    has embedding_cost: float = 0.0;
    has provider_tier: str = "UNROUTED";
    has invalidated: bool = False;
}

edge Supersedes {
    has reason: str = "";
}

edge RelatesTo {
    has weight: float = 0.0;
}

walker CostAwareRouter {
    has tier_counts: dict[str, int] = {"CHEAP": 0, "STANDARD": 0, "PREMIUM": 0};
    has invalidations: int = 0;

    can start with Root entry {
        print(f"Starting cost-aware routing pass");
        visit [-->];
    }

    can route_fact with Fact entry {
        # Classify this fact into a provider tier based on confidence + cost.
        tier = "PREMIUM";
        if here.confidence >= 0.90 and here.embedding_cost <= 0.10 {
            tier = "CHEAP";
        } elif here.confidence >= 0.70 and here.embedding_cost <= 0.50 {
            tier = "STANDARD";
        }
        here.provider_tier = tier;
        self.tier_counts[tier] = self.tier_counts.get(tier, 0) + 1;
        print(f"  routed {here.title} -> {tier} (conf={here.confidence}, cost={here.embedding_cost})");
        visit [-->];
    }

    can cascade_invalidate with Fact entry {
        # Walk outgoing Supersedes edges; the predecessor invalidates its successors.
        superseded = [-->:Supersedes:->];
        for successor in superseded {
            if not successor.invalidated {
                successor.invalidated = True;
                self.invalidations += 1;
                print(f"  invalidated {successor.title} (superseded by {here.title})");
                # Recurse into the successor's own supersession chain.
                visitor = CostAwareRouter();
                visitor.invalidations = self.invalidations;
                successor spawn visitor;
            }
        }
    }
}

with entry {
    # Build a small knowledge graph: three facts with a supersession chain.
    f1 = Fact(title="user_lives_in_paris",
               content="User resides in Paris, France",
               confidence=0.95,
               embedding_cost=0.05);
    f2 = Fact(title="user_lives_in_lyon",
               content="User resides in Lyon, France",
               confidence=0.92,
               embedding_cost=0.08);
    f3 = Fact(title="user_favorite_cuisine",
               content="User enjoys French cuisine",
               confidence=0.60,
               embedding_cost=0.80);

    root ++> f1;
    root ++> f2;
    root ++> f3;

    # Typed edges: f1 supersedes f2 (Paris replaces Lyon); f3 relates to f1.
    f1 +>:Supersedes(reason="location_update"):+> f2;
    f3 +>:RelatesTo(weight=0.7):+> f1;

    print("=== Cost-aware routing (v0.8.0) ===");
    router = CostAwareRouter();
    root spawn router;

    print(f"\nTier distribution: {router.tier_counts}");
    print(f"Total invalidations cascaded: {router.invalidations}");

    # Show final state of each fact.
    print("\nFinal fact states:");
    for f in [f1, f2, f3] {
        state = "INVALID" if f.invalidated else "VALID";
        print(f"  [{state}] {f.title} tier={f.provider_tier} conf={f.confidence}");
    }
}
```

