```jac
"""Cargo-mutants illumos fix: dependency-graph walk after upgrading fs2 → fs4.

Models the essential scenario: package nodes connected by typed
``Depends`` edges, with attributes that mirror what the project tracks
(build status, lock behavior). A walker traverses the dependency graph,
reproducing the recursive walk the issue describes, while enforcing
cycle safety (which the original hand-rolled recursion relied on) and
reporting a topological-feasible evaluation order so an illumos-broken
dependency can be invalidated/cascade-deleted once the upgrade is in.
"""

node Package {
    has name: str = "";
    has version: str = "";
    has illumos_ok: bool = True;
    has resolved: bool = False;
}

edge Depends {
    has depth: int = 0;
}

walker DependencyAuditor {
    has visited: list[str] = [];
    has order: list[str] = [];
    has stack: list[str] = [];

    can begin with Root entry {
        print(f"starting dependency audit on {self.stack}");
        visit [-->];
    }

    can audit with Package entry {
        if here.name in self.visited {
            print(f"  cycle detected at {here.name}; disengaging");
            disengage;
        }
        if here.illumos_ok == False {
            print(f"  [INVALIDATE] {here.name} {here.version} fails on illumos");
            disengage;
        }
        self.visited.append(here.name);
        self.stack.append(here.name);
        print(f"  visiting {here.name} {here.version} (stack depth {self.stack.length})");
        visit [->:Depends:->];
    }

    can tally with Package entry {
        self.order.append(here.name);
    }
}

walker CascadeInvalidator {
    can begin with Root entry {
        visit [-->];
    }

    can invalidate with Package entry {
        if here.illumos_ok == False {
            print(f"  cascade-invalidating {here.name} dependents");
            visit [->:Depends:->];
        } else {
            visit [-->];
        }
    }
}

with entry {
    fs2 = Package(name="fs2", version="0.4.3", illumos_ok=False);
    fs4 = Package(name="fs4", version="0.8.3", illumos_ok=True);
    cargo_mutants = Package(name="cargo-mutants", version="0.5.0", illumos_ok=True);
    tempfile = Package(name="tempfile", version="3.2", illumos_ok=True);
    lockfile = Package(name="lockfile", version="0.2", illumos_ok=True);

    root ++> cargo_mutants
        +>:Depends(depth=1):+> fs2
        +>:Depends(depth=1):+> fs4
        +>:Depends(depth=1):+> tempfile
        +>:Depends(depth=1):+> lockfile;
    fs4 +>:Depends(depth=2):+> tempfile;
    fs2 +>:Depends(depth=2):+> lockfile;

    walker1 = DependencyAuditor(stack=["cargo-mutants"]);
    root spawn walker1;
    print(f"audit order: {walker1.order}");
    print(f"audit visited: {walker1.visited}");

    walker2 = CascadeInvalidator();
    root spawn walker2;
}
