Task:
Run feeding rounds at a wildlife park: the info kiosk greets every tour party regardless of who they are, zookeepers feed each animal its species-appropriate meal (meat for lions, seed for parrots, standard feed otherwise), and school groups just watch the animals.

```jac
"""Wildlife park feeding rounds.

The kiosk greets every party at the gate. Zookeepers feed each animal its
species-appropriate meal: meat for lions, seed for parrots, standard feed
otherwise. School groups just observe the animals without feeding them.
"""

node Lion {
    has name: str = "";
}

node Parrot {
    has name: str = "";
}

node Zebra {
    has name: str = "";
}

# A plain visitor (e.g. family visitor) matches no feeding rule; the
# kiosk greets them, but no animal-side ability fires for them.
walker Kiosk {
    can greet with Root entry {
        print("Welcome to the wildlife park! Enjoy your visit.");
        visit [-->];
    }

    can greet_party with Lion | Parrot | Zebra entry {
        print(f"Kiosk: Hello, party near the {type(here).__name__} enclosure!");
        visit [-->];
    }
}

walker Zookeeper {
    has meals_served: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can feed with Lion entry {
        print(f"Zookeeper: serving meat to lion {here.name}.");
        self.meals_served += 1;
        visit [-->];
    }

    can feed with Parrot entry {
        print(f"Zookeeper: serving seed to parrot {here.name}.");
        self.meals_served += 1;
        visit [-->];
    }

    can feed with Zebra entry {
        print(f"Zookeeper: serving standard feed to zebra {here.name}.");
        self.meals_served += 1;
        visit [-->];
    }
}

walker SchoolGroup {
    has animals_watched: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can watch with Lion | Parrot | Zebra entry {
        self.animals_watched += 1;
        species = type(here).__name__;
        print(f"SchoolGroup: quietly watching the {species} named {here.name}.");
        visit [-->];
    }
}

with entry {
    simba = Lion(name="Simba");
    polly = Parrot(name="Polly");
    stripes = Zebra(name="Stripes");
    root ++> simba ++> polly ++> stripes;

    print("=== Kiosk greets every party ===");
    root spawn Kiosk();

    print("\n=== Zookeeper feeding rounds ===");
    zk = Zookeeper();
    root spawn zk;
    print(f"Total meals served: {zk.meals_served}");

    print("\n=== School group on a field trip ===");
    sg = SchoolGroup();
    root spawn sg;
    print(f"Total animals watched: {sg.animals_watched}");
}
