"""Package composition, dependency closure, and verification.

Models the essential behavior from a Model.java composition extraction:
root package selection, dependency declaration, deterministic closure
ordering, duplicate/conflict handling, and cycle detection on the
dependency graph. Each validated package maps 1:1 to a SemanticModel
node; composition keeps a private closure that is NOT a second canonical
semantic IR.
"""

# ---------- Node archetypes ----------

node Package {
    has name: str = "";
    has version: str = "0";
    has identity: str = "";
}

node SemanticModel {
    has model_id: str = "";
    has compiled: bool = False;
}

# ---------- Edge archetypes ----------

# "depends on" — carries version + identity for verification
edge Depends {
    has required_version: str = "*";
    has declared_identity: str = "";
    has verified: bool = False;
}

# composition owns the link between a Package and its SemanticModel
edge CompiledTo {
    has compiled_at: str = "";
}

# ---------- Walker: Composer ----------

walker Composer {
    has root_name: str = "";
    has ordered: list[str] = [];
    has visited: list[str] = [];
    has conflicts: list[str] = [];
    has cycles: list[str] = [];
    has current_path: list[str] = [];

    can begin with Root entry {
        # 1. Select root package among candidates (first matching name wins)
        picked = None;
        for n in [-->](?:Package) {
            if n.name == self.root_name {
                picked = n;
                break;
            }
        }
        if picked is None {
            self.conflicts.append(f"NO_ROOT:{self.root_name}");
            disengage;
        }
        self.ordered.append(picked.name);
        self.visited.append(picked.identity);
        self.current_path.append(picked.identity);
        visit picked;
    }

    can descend with Package entry {
        # Walk every outgoing Depends edge from this package
        for dep in [->:Depends:->] {
            # Duplicate-dependency handling: same identity already closed
            if dep.declared_identity in self.visited {
                if dep.declared_identity != here.identity {
                    self.conflicts.append(
                        f"DUP:{here.name}->{dep.declared_identity}"
                    );
                }
                continue;
            }
            # Cycle detection (composition-specific)
            if dep.declared_identity in self.current_path {
                cycle_msg = (
                    f"CYCLE:{'->'.join(self.current_path)}->"
                    f"{dep.declared_identity}"
                );
                self.cycles.append(cycle_msg);
                continue;
            }
            # Conflict: version constraint disagrees with resolved identity
            target = None;
            for cand in [-->](?:Package) {
                if cand.identity == dep.declared_identity {
                    target = cand;
                    break;
                }
            }
            if target is None {
                self.conflicts.append(
                    f"MISSING:{here.name}->{dep.declared_identity}"
                );
                continue;
            }
            dep.verified = True;
            self.ordered.append(target.name);
            self.visited.append(target.identity);
            self.current_path.append(target.identity);
            visit target;
        }
        # Pop the recursion stack on the way back through
        self.current_path.pop();
    }

    can verify_models with Package entry {
        # Each package must have a 1:1 SemanticModel (no second canonical IR)
        models = [->:CompiledTo:->](?:SemanticModel);
        if len(models) == 0 {
            self.conflicts.append(f"NO_MODEL:{here.name}");
        } elif len(models) > 1 {
            self.conflicts.append(
                f"MULTI_MODEL:{here.name}:{len(models)}"
            );
        }
    }
}

# ---------- Walker: PackageVerifier ----------

walker PackageVerifier {
    has report_lines: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can audit with Package entry {
        ok = True;
        for dep in [->:Depends:->] {
            if not dep.verified {
                ok = False;
                self.report_lines.append(
                    f"UNVERIFIED:{here.name}:"
                    f"{dep.declared_identity}"
                );
            }
        }
        status = "OK" if ok else "FAIL";
        self.report_lines.append(
            f"[{status}] {here.name}@{here.version} "
            f"(identity={here.identity})"
        );
    }
}

# ---------- Demo wiring ----------

with entry {
    # Three packages, each with a 1:1 SemanticModel (composition keeps it that way)
    a = Package(
        name="pkg-A",
        version="1",
        identity="id-A"
    );
    a_sm = SemanticModel(model_id="sm-A", compiled=True);
    a +>:CompiledTo(compiled_at="t0"):+> a_sm;

    b = Package(
        name="pkg-B",
        version="1",
        identity="id-B"
    );
    b_sm = SemanticModel(model_id="sm-B", compiled=True);
    b +>:CompiledTo:+> b_sm;

    c = Package(
        name="pkg-C",
        version="1",
        identity="id-C"
    );
    c_sm = SemanticModel(model_id="sm-C", compiled=True);
    c +>:CompiledTo:+> c_sm;

    # A "ghost" package: declared but never instantiated (will surface as MISSING)
    # A duplicate edge: A also declares a second Depends on B (DUP path)

    # Deterministic dependency edges: A depends on B and C; B depends on C.
    a +>:Depends(required_version="1", declared_identity="id-B"):+> b;
    a +>:Depends(required_version="1", declared_identity="id-C"):+> c;
    # Duplicate declaration on A (same identity, different edge) -> DUP
    a +>:Depends(required_version="1", declared_identity="id-B"):+> b;
    # Self-loop on B -> CYCLE
    b +>:Depends(required_version="1", declared_identity="id-B"):+> b;
    # Reference to a non-existent package id-D -> MISSING
    a +>:Depends(required_version="*", declared_identity="id-D"):+> c;
    # Plain (untyped) chain just to keep root traversable
    root ++> a;

    print("=== Composer (root=pkg-A) ===");
    composer = Composer(root_name="pkg-A");
    root spawn composer;

    print("Deterministic ordering: " + ",".join(composer.ordered));
    print("Visited identities:    " + ",".join(composer.visited));
    print("Conflicts:");
    for line in composer.conflicts {
        print(f"  {line}");
    }
    print("Cycles:");
    for line in composer.cycles {
        print(f"  {line}");
    }

    print("\n=== PackageVerifier (full sweep) ===");
