Task:
A maintainer on the project yashumani/open-source-reviewer-app (JavaScript) filed this issue about hand-rolled graph machinery causing pain:

Issue #30: Resolve package-script indirection when verifying CI test execution

## Problem

The owner-wide calibration now gives ForkWise a plausible `Pilot` self-review, but the primary remaining self-review finding is:

> CI exists, but test execution was not verified.

ForkWise's Quality workflow runs `npm run validate`, while `package.json` defines `validate` so it transitively invokes `npm test`. The current analyzer appears to recognize direct test commands in workflows but does not follow bounded package-script indirection.

## Expected behavior

When a workflow invokes a local package script whose deterministic, bounded script graph reaches a recognized test command, ForkWise should treat CI test execution as observed. Dynamic or ambiguous script chains should remain unknown.

## Relevant files

- `src/analyzer.js`
- `src/inventory.js`
- `package.json` parsing logic
- `tests/analyzer.test.js`
- `docs/ANALYZER_RULES.md`

## Security boundary

Parse package scripts as inert text/JSON only. Do not invoke npm, execute scripts, install packages, expand shell substitutions, or resolve external commands.

## Acceptance criteria

- [ ] Parse local `package.json` script definitions without executing them.
- [ ] Resolve a bounded script graph, for example depth 3, for `npm run`, `pnpm run`, and `yarn` local-script references.
- [ ] Recognize a reachable test command such as `npm test`, `node --test`, `pytest`, or another already-supported test runner.
- [ ] Detect cycles and stop safely.
- [ ] Preserve `unknown` for dynamic, missing, cyclic, or shell-generated script targets.
- [ ] Add positive, indirect, cyclic, missing-script, and ambiguous-command tests.
- [ ] ForkWise self-review no longer emits `ci-present` solely because Quality uses `npm run validate` before reaching `npm test`.
- [ ] `npm run validate` and Owner Repository Calibration pass.

## Difficulty

Intermediate.

## Out of scope

Executing package scripts, installing dependencies, interpreting arbitrary shell programs, or claiming tests passed merely because a test command is configured.

Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.

```jac
"""Resolve bounded package-script indirection without executing scripts."""

node Package {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has manifest: str = "package.json";
}

node Workflow {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Script {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has command: str = "";
    has local_target: str = "";
    has dynamic: bool = False;
}

edge HasWorkflow { }
edge Invokes {
    has kind: str = "local-script";
}

walker ScriptResolver {
    has max_hops: int = 8;
    has steps: int = 0;
    has tests_observed: int = 0;
    has unknown_count: int = 0;
    has cycle_count: int = 0;
    has missing_count: int = 0;
    has seen_titles: list[str] = [];

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can enter_package with Package entry {
        visit [->:HasWorkflow:->] else {
            disengage;
        }
    }

    can inspect_workflow with Workflow entry {
        visit [->:Invokes:->] else {
            self.unknown_count += 1;
        }
    }

    can resolve_script with Script entry {
        if self.steps >= self.max_hops {
            self.unknown_count += 1;
        } elif here.title in self.seen_titles {
            self.cycle_count += 1;
            print(f"cycle stopped at {here.title}");
        } else {
            self.seen_titles.append(here.title);
            self.steps += 1;

            if here.command == "npm test"
                or here.command == "node --test"
                or here.command == "pytest" {
                self.tests_observed += 1;
                print(f"test command observed: {here.command}");
            } elif here.dynamic {
                self.unknown_count += 1;
                print(f"ambiguous script remains unknown: {here.title}");
            } elif here.local_target != "" {
                visit [->:Invokes:->] else {
                    self.missing_count += 1;
                    self.unknown_count += 1;
                    print(f"missing script target: {here.local_target}");
                }
            } else {
                self.unknown_count += 1;
                print(f"unrecognized command remains unknown: {here.command}");
            }
        }
    }
}

with entry {
    package = Package(title="ForkWise", year=2024);

    quality = Workflow(title="Quality CI");
    package +>:HasWorkflow:+> quality;

    validate = Script(
        title="validate",
        command="npm run validate",
        local_target="test"
    );
    quality +>:Invokes(kind="workflow-script"):+> validate;

    test = Script(title="test", command="npm test");
    validate +>:Invokes:+> test;

    audit = Workflow(title="Audit CI");
    package +>:HasWorkflow:+> audit;

    dynamic_script = Script(
        title="dynamic",
        command="npm run $TARGET",
        dynamic=True
    );
    audit +>:Invokes:+> dynamic_script;

    cycle_a = Script(
        title="cycle-a",
        command="npm run cycle-b",
        local_target="cycle-b"
    );
    cycle_b = Script(
        title="cycle-b",
        command="npm run cycle-a",
        local_target="cycle-a"
    );
    cycle_a +>:Invokes:+> cycle_b;
    cycle_b +>:Invokes:+> cycle_a;

    cycle_workflow = Workflow(title="Cycle CI");
    package +>:HasWorkflow:+> cycle_workflow;
    cycle_workflow +>:Invokes:+> cycle_a;

    root ++> package;
    root spawn ScriptResolver();

    print("bounded inert script resolution complete");
}
```

