Task:
Build a toll plaza collector for gate G-4: cars pay $2.50, trucks pay $2.50 plus 50 cents per ton, motorcycles pay $1.00. Print one payment line per vehicle describing it, and report the revenue collected after the sweep.

```jac
"""Toll plaza G-4 collector: charge cars, trucks, and motorcycles, then sweep and report revenue."""

node Vehicle {
    has label: str = "";
    has axles: int = 0;
    has weight_tons: float = 0.0;
}

node Car(Vehicle) {
    has label: str = "car";
    has axles: int = 2;
    has weight_tons: float = 0.0;
}

node Truck(Vehicle) {
    has label: str = "truck";
    has axles: int = 4;
    has weight_tons: float = 0.0;
}

node Motorcycle(Vehicle) {
    has label: str = "motorcycle";
    has axles: int = 2;
    has weight_tons: float = 0.0;
}

walker TollCollector {
    has revenue: float = 0.0;

    can start with Root entry {
        print("Gate G-4 sweep begins");
        visit [-->];
    }

    can collect with Car | Truck | Motorcycle entry {
        charge = 0.0;
        kind = "";
        if here instanceof Car {
            kind = "car";
            charge = 2.50;
        } elif here instanceof Truck {
            kind = "truck";
            charge = 2.50 + 0.50 * here.weight_tons;
        } elif here instanceof Motorcycle {
            kind = "motorcycle";
            charge = 1.00;
        }
        self.revenue = self.revenue + charge;
        print(f"{kind} axles={here.axles} weight={here.weight_tons}t -> paid ${charge:.2f}");
        visit [-->];
    }
}

with entry {
    root ++> Car()
        ++> Truck(weight_tons=8.0)
        ++> Motorcycle()
        ++> Truck(weight_tons=12.5)
        ++> Car();

    collector = TollCollector();
    root spawn collector;
    print(f"Gate G-4 total revenue: ${collector.revenue:.2f}");
}
