Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.

```jac
"""RiskAssessor demo: model endpoints, systems, and a blast-radius walker
that walks the target graph to count unique affected assets.

The original bug: target extraction took the last URL segment, so two
distinct systems performing the same operation type (e.g. EthernetInterfaces)
collapsed to a single "target". The walker below instead walks typed edges
from each impacted Endpoint to the distinct System it belongs to, so the
unique-asset count reflects real physical asset identity.
"""

node Endpoint {
    has url: str = "";
    has operation: str = "";
}

node System {
    has system_id: str = "";
}

edge Exposes {
    has note: str = "";
}

node Workflow {
    has name: str = "";
    has blast_multiplier: float = 1.0;
    has unique_targets: int = 0;
}

edge Touches {
}

walker BlastAuditor {
    has seen: list[str] = [];
    has unique_count: int = 0;
    has multiplier: float = 1.0;

    can start with Root entry {
        visit [-->];
    }

    can audit with Workflow entry {
        self.seen = [];
        self.unique_count = 0;
        visit [-->];
    }

    can tally with Endpoint entry {
        # Walk the typed edge to discover which System this endpoint exposes.
        visit [->:Exposes:->];
    }

    can count with System entry {
        sys_id = here.system_id;
        if sys_id not in self.seen {
            self.seen.append(sys_id);
            self.unique_count += 1;
        }
    }
}

with entry {
    # Two physically distinct systems expose the SAME operation type.
    # The old logic would treat both as one target ("EthernetInterfaces").
    sys_a = System(system_id="System.Embedded.1");
    sys_b = System(system_id="System.Embedded.2");

    ep_a = Endpoint(
        url="/redfish/v1/Systems/System.Embedded.1/EthernetInterfaces",
        operation="EthernetInterfaces",
    );
    ep_b = Endpoint(
        url="/redfish/v1/Systems/System.Embedded.2/EthernetInterfaces",
        operation="EthernetInterfaces",
    );

    wf = Workflow(name="PatchEthernet");

    root ++> wf;
    wf +>:Touches:+> ep_a;
    wf +>:Touches:+> ep_b;
    ep_a +>:Exposes(note="binding"):+> sys_a;
    ep_b +>:Exposes(note="binding"):+> sys_b;

    auditor = BlastAuditor();
    root spawn auditor;
    wf.audit_pending = True;

    # Re-run from the workflow directly so we can read out the result.
    auditor2 = BlastAuditor();
    wf spawn auditor2;

    # Apply the multiplier derived from the walk.
    wf.unique_targets = auditor2.unique_count;
    wf.blast_multiplier = 1.0 + 0.5 * auditor2.unique_count;

    print(
        f"workflow={wf.name} unique_assets={wf.unique_targets} "
        f"blast_multiplier={wf.blast_multiplier}"
    );
    print(f"seen asset ids: {auditor2.seen}");
}
```

