"""Warehouse robot route planner.

Each warehouse cell carries a movement directive (floor or stairs) that
the robot must obey. The robot walks the layout as a walker, logging
only the movement kind it actually used at each cell.
"""

node Cell {
    has label: str = "";
    has movement: str = "floor";
}

edge Next {}

walker Robot {
    has path_log: list[str] = [];

    can start with Root entry {
