"""Miner bundle packaging with raced-replacement containment.

Models the core scenario from issue #683: a per-platform bundle root is
created under a canonical release root, descendants are materialized
underneath, and any external actor that swaps the bundle path between
cleanup and child creation must be detected rather than silently followed.
The walker enforces a depth limit (cycle guard) and a typed Parent edge
so the bundle-root-to-leaf topology is explicit instead of a hand-rolled
adjacency map.
"""

# ---------- edge archetypes ----------
# A bundle root owns children via a typed Parent edge. Payload keeps
# the relative subpath the original script would have created with
# `mkdir(join(bundle, ...))`.
edge Parent {
    has subpath: str = "";
}

# The release-root boundary. Every bundle must confirm its real parent
# still matches this identity before any child write.
edge BoundTo {
    has label: str = "";
}

# ---------- node archetypes ----------
node ReleaseRoot {
    has canonical: str = "";
    has label: str = "";
}

node BundleRoot {
    has platform: str = "";
    has reserved: bool = False;
    has parent_identity: str = "";
}

node PackageFile {
    has rel_path: str = "";
    has bytes: int = 0;
    has released: bool = False;
}

# ---------- walker: MinerPackager ----------
walker MinerPackager {
    has platform: str = "linux";
    has depth_limit: int = 4;
    has seen: list[str] = [];

    can start with Root entry {
        print(f"[packager] spawning for platform={self.platform}");
        visit [-->];
    }

    # Bind the canonical release root (the bound-parent check).
    can bind_root with ReleaseRoot entry {
        print(f"[packager] bound release root: {self.label} -> {here.canonical}");
        visit [-->];
    }

    # Reserve the bundle root atomically (non-recursive exclusive create).
    # If it already exists or its parent identity drifted, fail closed.
    can reserve with BundleRoot entry {
        ok = True;
        if here.reserved {
            print(f"[packager] ABORT: bundle already reserved for {here.platform}");
            ok = False;
        }
        if here.parent_identity != "miner-release-canonical" {
            print(f"[packager] ABORT: raced parent for {here.platform}");
            ok = False;
        }
        if not ok {
            disengage;
        }
        here.reserved = True;
        print(f"[packager] reserved bundle root for {here.platform}");
        visit [-->];
    }

    # Descend into package files through typed Parent edges, with a
    # depth cap as the cycle policy (no built-in visited dedupe in 0.36.1).
    can materialize with PackageFile entry {
        if len(self.seen) >= self.depth_limit {
            print(f"[packager] depth cap hit, stopping at {here.rel_path}");
            disengage;
        }
        here.released = True;
        self.seen.append(here.rel_path);
        print(f"[packager] released {here.rel_path} ({here.bytes} bytes)");
        visit [-->];
    }
}

# ---------- demonstration graph ----------
with entry {
    release = ReleaseRoot(canonical="/srv/miner-release", label="miner-release");
    linux_bundle = BundleRoot(platform="linux", parent_identity="miner-release-canonical");
    win_bundle = BundleRoot(platform="windows", parent_identity="miner-release-canonical");
    raced_bundle = BundleRoot(platform="darwin", parent_identity="RACED");

    # Wire the release root to its per-platform bundles via a typed edge.
    release +>:BoundTo(label="linux"):+> linux_bundle;
    release +>:BoundTo(label="windows"):+> win_bundle;
    release +>:BoundTo(label="darwin"):+> raced_bundle;

    # Materialize package descendants under each bundle via typed Parent edges.
    linux_bundle +>:Parent(subpath="bin"):+> PackageFile(rel_path="bin/minerd", bytes=4096);
    linux_bundle +>:Parent(subpath="bin"):+> PackageFile(rel_path="bin/minerd.conf", bytes=512);
    linux_bundle +>:Parent(subpath="share"):+> PackageFile(rel_path="share/README", bytes=2048);

    win_bundle +>:Parent(subpath="bin"):+> PackageFile(rel_path="bin/minerd.exe", bytes=5120);

    raced_bundle +>:Parent(subpath="bin"):+> PackageFile(rel_path="bin/minerd", bytes=4096);

    # Spawn three packagers. The raced one must abort at the parent-identity
    # guard; the windows one must stop at the depth cap; linux succeeds.
    root spawn MinerPackager(platform="linux", depth_limit=8);
    print("---");
    root spawn MinerPackager(platform="windows", depth_limit=1);
    print("---");
    root spawn MinerPackager(platform="darwin", depth_limit=8);
}
