Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.

```jac
"""Recursive SPF dependency graph: model DNS records as nodes and walk the
include/redirect chain with a budget-aware walker that detects cycles."""

# An SPF record is a sequence of terms. We model the records themselves,
# the individual terms (mechanisms/modifiers), and the recursive references
# between them as typed edges so the dependency graph is first-class.

node Domain {
    has name: str = "";
}

# A Record carries the raw SPF text and metadata about the lookup budget it
# has consumed so far (per RFC 7208 §4.6.4 the cap is 10).
node Record {
    has name: str = "";
    has raw: str = "";
    has lookups_used: int = 0;
    has void_lookups: int = 0;
    has issues: list[str] = [];
}

# A Term is one mechanism or modifier inside a record (include, redirect,
# mx, a, exists, ptr, ip4, ip6, all, a macro expansion, etc.).
node Term {
    has kind: str = "";          # "include", "redirect", "mx", "a", ...
    has qualifier: str = "+";     # "+", "-", "~", "?"
    has target: str = "";         # domain or macro string
    has is_dynamic: bool = False; # macros / exists / ptr are dynamic
    has mx_count: int = 0;        # expansion budget used by mx (≤ 10)
    has a_count: int = 0;         # expansion budget used by a  (≤ 10)
    has void_count: int = 0;      # void lookups attributed to this term
}

# Typed edges carry the meaning of the dependency relationship.
edge Owns { }              # Domain -Owns-> Record
edge Contains { }          # Record -Contains-> Term (in order)
edge Refers { }            # Term -Refers-> Term (the actual mechanism link)
edge Resolves { }          # Term -Resolves-> Record (include/redirect target)

# A bounded budget the walker enforces. These are the same numbers RFC 7208
# imposes so the demo can show what happens when the budget is exceeded.
walker SpfInspector {
    has max_depth: int = 5;
    has max_lookups: int = 10;
    has max_void: int = 2;
    has max_mx: int = 10;
    has max_a: int = 10;
    has depth: int = 0;
    has cycle_log: list[str] = [];
    has dynamic_terms: list[str] = [];
    has failures: list[str] = [];
    has total_size: int = 0;

    can start with Root entry {
        # Pick up whichever domain lives on root and begin the walk.
        visit [-->];
    }

    # Union ability: a Domain, Record, or Term entry all share a `name`
    # field we can print, and we know how to continue from any of them.
    can traverse with Domain | Record | Term entry {
        print(f"[d={self.depth}] {here.name}");
        if here isa Record {
            self.total_size += len(here.raw);
            visit [-->];
            return;
        }
        if here isa Term {
            self.total_size += len(here.target);
            if here.is_dynamic {
                self.dynamic_terms.append(here.target);
            }
            visit [-->];
            return;
        }
        # Domain: fan out to its records.
        visit [-->];
    }

    # When we re-enter a Term that is an include/redirect we have already
    # visited, we have found a cycle. Record it instead of descending.
    can follow with Term entry {
        new_total = self.depth + here.lookups_used;
        if here.target in self.cycle_log {
            self.cycle_log.append(here.target);
            self.failures.append(f"cycle: {here.target}");
            visit [-->] else { disengage; };
            return;
        }
        if self.depth >= self.max_depth {
            self.failures.append(f"depth cap at {here.target}");
            visit [-->] else { disengage; };
            return;
        }
        if new_total > self.max_lookups {
            self.failures.append(f"lookup cap exceeded via {here.target}");
            visit [-->] else { disengage; };
            return;
        }
        if here.void_count > self.max_void {
            self.failures.append(f"void lookup cap via {here.target}");
            visit [-->] else { disengage; };
            return;
        }
        # Budget accepted: descend through the Resolves edge.
        self.cycle_log.append(here.target);
        self.depth += 1;
        visit [->:Resolves:->];
    }
}

# A small example domain with two records chained by an include, one
# dynamic ptr, and one deliberate cycle to prove the cycle detector fires.
with entry {
    example = Domain(name="example.com");
    sub     = Domain(name="sub.example.com");

    root ++> example ++> sub;

    main_rec  = Record(name="example.com", raw="v=spf1 include:_spf.example.com -all", lookups_used=1);
    child_rec = Record(name="_spf.example.com", raw="v=spf1 include:sub.example.com mx", lookups_used=2);
    loop_rec  = Record(name="sub.example.com", raw="v=spf1 include:_spf.example.com", lookups_used=1);

    example +>:Owns:+> main_rec;
    sub     +>:Owns:+> loop_rec;
    root    +>:Owns:+> child_rec;

    inc_term = Term(kind="include", target="_spf.example.com");
    mx_term  = Term(kind="mx", target="example.com", is_dynamic=True, mx_count=5);
    ptr_term = Term(kind="ptr", target="example.com", is_dynamic=True);
    loop_inc = Term(kind="include", target="_spf.example.com");

    main_rec  +>:Contains:+> inc_term;
    main_rec  +>:Contains:+> mx_term;
    main_rec  +>:Contains:+> ptr_term;
    child_rec +>:Contains:+> loop_inc;
    loop_rec  +>:Contains:+> loop_inc;

    # Resolves edges wire the include targets to the records they pull in.
    inc_term +>:Resolves:+> child_rec;
    loop_inc +>:Resolves:+> child_rec;

    inspector = SpfInspector(max_depth=5, max_lookups=10, max_void=2);
    root spawn inspector;

    print(f"cycles hit: {inspector.cycle_log}");
    print(f"dynamic terms: {inspector.dynamic_terms}");
    print(f"failures: {inspector.failures}");
    print(f"estimated DNS response size: {inspector.total_size} bytes");
}
