Issue #145: [P0] Constrain destructive runtime cleanup to Ralph-owned paths

## Summary

RalphDex allows `artifactRetentionPath` to resolve outside `.ralph/`, including absolute paths, but destructive runtime-maintenance paths trust the resolved directory and recursively delete from it.

Reviewed against `main` at `5c83d423f2b933cc202e0da3aa6192e6648edc7e`.

## Current behavior

`RalphStateManager.resetRuntimeState()` resolves the configured paths and then recursively removes `paths.artifactDir` along with Ralph's normal prompt/run/handoff/log directories.

Because `artifactRetentionPath` is operator-configurable and may be absolute, configurations such as:

```text
artifactRetentionPath = "."
artifactRetentionPath = ".."
artifactRetentionPath = "/shared/path"
```

can make **Reset Runtime State** recursively delete unrelated workspace or external data.

Retention cleanup has the same underlying trust problem: it scans the configured artifact root and recursively removes Ralph-looking entries such as `iteration-N` directories selected by the retention plan. If the root is not exclusively Ralph-owned, unrelated directories that match those names can be pruned.

The Reset confirmation describes Ralph runtime artifacts rather than surfacing the exact resolved destructive root, so the operator may not realize the configured artifact path broadens the deletion scope.

## Impact

- recursive deletion of unrelated repository files;
- recursive deletion outside the repository when an absolute artifact path is configured;
- retention cleanup can remove unrelated `iteration-N` directories from a shared root;
- confirmation UI can understate the actual destructive scope.

## Relevant code

- `src/ralph/stateManager.ts`
  - `resetRuntimeState`
  - `cleanupRuntimeArtifacts`
- `src/ralph/artifactRetention.ts`
- `src/ralph/pathResolver.ts`
- `src/commands/artifactCommands.ts`
- `ralphCodex.artifactRetentionPath` configuration

## Suggested direction

Introduce a managed-root ownership invariant for every destructive runtime operation.

A safe design should include:

1. resolve/canonicalize the configured artifact path;
2. require destructive targets to be an explicitly Ralph-owned directory;
3. use an ownership marker/version file or equivalent positive identification rather than trusting the directory name alone;
4. reject dangerous roots such as the workspace root, filesystem root, parent traversal, or an unowned external/shared directory;
5. show the exact resolved deletion root in destructive confirmations;
6. make retention cleanup use the same ownership guard.

## Acceptance criteria

- [ ] Reset cannot recursively delete the workspace root, a workspace parent, filesystem root, or an arbitrary unowned absolute directory.
- [ ] Cleanup/retention refuses to delete from an artifact root that is not positively identified as Ralph-owned.
- [ ] Safe custom artifact directories remain supported, including absolute paths when explicitly initialized/owned by Ralph.
- [ ] Destructive confirmations show the resolved target path.
- [ ] Add regression tests for `.`, `..`, workspace root, filesystem/root-equivalent inputs, and an external shared directory.
- [ ] Add a regression proving unrelated `iteration-N` directories in an unowned root are never pruned.
- [ ] Document the custom artifact-root ownership contract.

Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.

```jac
"""Safely clean Ralph-owned artifact roots while rejecting unowned paths."""

node Workspace {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has path: str = "";
    has parent_path: str = "";
}

node ArtifactRoot {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has canonical_path: str = "";
    has owned: bool = False;
    has marker_version: str = "";
}

node Artifact {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has canonical_path: str = "";
    has retain: bool = True;
}

edge ManagedRoot {
    has purpose: str = "runtime-artifacts";
}

edge Contains {
    has purpose: str = "artifact-child";
}

walker RuntimeCleaner {
    has workspace_path: str = "";
    has parent_path: str = "";
    has seen_paths: list[str] = [];

    can begin with Workspace entry {
        self.workspace_path = here.path;
        self.parent_path = here.parent_path;
        print(f"reset confirmation: destructive roots are checked below {here.path}");
        visit [->:ManagedRoot:->] else {
            disengage;
        }
    }

    can guard with ArtifactRoot entry {
        if here.owned == False {
            print(f"REFUSED unowned artifact root: {here.canonical_path}");
        } else if here.marker_version != "ralph-artifacts-v1" {
            print(f"REFUSED missing ownership marker: {here.canonical_path}");
        } else if here.canonical_path == self.workspace_path {
            print(f"REFUSED workspace root: {here.canonical_path}");
        } else if here.canonical_path == self.parent_path {
            print(f"REFUSED workspace parent: {here.canonical_path}");
        } else if here.canonical_path == "/" {
            print(f"REFUSED filesystem root: {here.canonical_path}");
        } else if here.canonical_path == "." {
            print(f"REFUSED unresolved current directory: {here.canonical_path}");
        } else if here.canonical_path == ".." {
            print(f"REFUSED unresolved parent directory: {here.canonical_path}");
        } else if here.canonical_path in self.seen_paths {
            print(f"REFUSED cycle at artifact root: {here.canonical_path}");
            disengage;
        } else {
            self.seen_paths.append(here.canonical_path);
            print(f"confirmed Ralph-owned deletion root: {here.canonical_path}");
            visit [->:Contains:->] else {
                disengage;
            }
        }
    }

    can prune with Artifact entry {
        if here.canonical_path in self.seen_paths {
            print(f"cycle detected; stopped at {here.canonical_path}");
            disengage;
        } else {
            self.seen_paths.append(here.canonical_path);
            if here.retain == False {
                here.available = False;
                print(f"invalidated retained artifact: {here.canonical_path}");
            } else {
                print(f"kept artifact: {here.canonical_path}");
            }
            visit [->:Contains:->] else {
                disengage;
            }
        }
    }
}

with entry {
    workspace = Workspace(
        title="RalphDex workspace",
        path="/repo/ralphdex",
        parent_path="/repo"
    );
    root ++> workspace;

    safe_root = ArtifactRoot(
        title="owned custom artifact root",
        canonical_path="/repo/ralphdex/.ralph-artifacts",
        owned=True,
        marker_version="ralph-artifacts-v1"
    );
    shared_root = ArtifactRoot(
        title="external shared directory",
        canonical_path="/shared/path",
        owned=False
    );
    workspace +>:ManagedRoot:+> safe_root;
    workspace +>:ManagedRoot:+> shared_root;

    kept = Artifact(
        title="iteration-1",
        canonical_path="/repo/ralphdex/.ralph-artifacts/iteration-1",
        retain=True
    );
    stale = Artifact(
        title="iteration-2",
        canonical_path="/repo/ralphdex/.ralph-artifacts/iteration-2",
        retain=False
    );
    cycle = Artifact(
        title="cycle-node",
        canonical_path="/repo/ralphdex/.ralph-artifacts/cycle-node",
        retain=True
    );
    safe_root +>:Contains:+> kept;
    safe_root +>:Contains:+> stale;
    stale +>:Contains:+> cycle;
    cycle +>:Contains:+> stale;

    unrelated = Artifact(
        title="iteration-99",
        canonical_path="/shared/path/iteration-99",
        retain=False
    );
    shared_root +>:Contains:+> unrelated;

    workspace spawn RuntimeCleaner();
}
