Guests at our hotel walk past service desks (spa session, room-service dinner, express laundry); each desk adds its price to whichever guest is currently passing by. Print each charge as it happens and what each guest owes at checkout.

```jac
"""Hotel service-charge ledger: guests walk past desks and each desk adds its price."""

node Guest {
    has name: str = "";
    has total: float = 0.0;
}

node ServiceDesk {
    has service: str = "";
    has price: float = 0.0;
}

walker GuestWalker {
    has guest_name: str = "";

    can start with Root entry {
        visit [-->];
    }

    can pass_desk with Guest entry {
        self.guest_name = here.name;
        visit [-->];
    }

    can charge with ServiceDesk entry {
        if self.guest_name != "" {
            label = f"{here.service} charge";
            print(f"{self.guest_name} incurred {label} of ${here.price}");
            target = [-->](?Guest);
            if target.length > 0 {
                target[0].total = target[0].total + here.price;
            }
        }
        visit [-->];
    }
}

with entry {
    alice = Guest(name="Alice");
    bob = Guest(name="Bob");

    spa = ServiceDesk(service="Spa session", price=85.0);
    dinner = ServiceDesk(service="Room-service dinner", price=42.5);
    laundry = ServiceDesk(service="Express laundry", price=18.0);

    root ++> alice ++> spa;
    root ++> bob ++> dinner ++> laundry;

    alice_walker = GuestWalker();
    root spawn alice_walker;
    bob_walker = GuestWalker();
    root spawn bob_walker;

    print("--- Checkout ---");
    print(f"Alice owes ${alice.total}");
    print(f"Bob owes ${bob.total}");
}
```

