Task:
Patrol two factory zones with one monitoring routine that handles both temperature sensors (alert above 75 C) and smoke sensors (alert above 50 ppm). Print every reading as nominal or an alert, and summarize the alert list at the end.

```jac
"""Factory zone patrol: one monitoring routine serves both temperature and smoke sensors."""

node Sensor {
    has label: str = "";
    has reading: float = 0.0;

    def kind() -> str;
    def is_alert() -> bool;
}

node TempSensor(Sensor) {
    override def kind() -> str {
        return "temperature";
    }
    override def is_alert() -> bool {
        return self.reading > 75.0;
    }
}

node SmokeSensor(Sensor) {
    override def kind() -> str {
        return "smoke";
    }
    override def is_alert() -> bool {
        return self.reading > 50.0;
    }
}

node Zone {
    has name: str = "";
}

edge DeployedIn {
    has since: str = "";
}

walker Patrol {
    has alert_count: int = 0;

    can start with Root entry {
        print("Beginning factory patrol...");
        visit [->:DeployedIn:->];
    }

    can sweep with Zone entry {
        print(f"Entering zone: {here.name}");
        visit [->:DeployedIn:->];
    }

    can inspect with TempSensor | SmokeSensor entry {
        status = "ALERT" if here.is_alert() else "nominal";
        line = f"[{status}] {here.kind()} sensor '{here.label}' reading={here.reading}";
        if here.is_alert() {
            self.alert_count += 1;
            print(line);
        } else {
            print(line);
        }
    }
}

walker AlertSummary {
    has alert_count: int = 0;

    can start with Root entry {
        print(f"--- Patrol complete: {self.alert_count} alert(s) flagged ---");
        visit [->:DeployedIn:->] else { disengage; }
    }
}

with entry {
    zone_a = Zone(name="Assembly");
    zone_b = Zone(name="Packaging");

    root +>:DeployedIn(since="2024-Q1"):+> zone_a;
    root +>:DeployedIn(since="2024-Q2"):+> zone_b;

    zone_a +>:DeployedIn:+> TempSensor(label="T-A1", reading=68.0);
    zone_a +>:DeployedIn:+> TempSensor(label="T-A2", reading=91.5);
    zone_a +>:DeployedIn:+> SmokeSensor(label="S-A1", reading=12.0);

    zone_b +>:DeployedIn:+> TempSensor(label="T-B1", reading=74.5);
    zone_b +>:DeployedIn:+> SmokeSensor(label="S-B1", reading=63.0);
    zone_b +>:DeployedIn:+> SmokeSensor(label="S-B2", reading=40.0);

    patrol = Patrol();
    root spawn patrol;

    summary = AlertSummary(alert_count=patrol.alert_count);
    root spawn summary;
}
```

