walker Hiker {
    has trail_name: str = "Alpine Loop";
    has stops_seen: int = 0;
    has target_stops: int = 5;

    can start with Root entry {
        print(f"Setting out on the {self.trail_name}");
        visit [-->] else { disengage; }
