        self.stops_seen += 1;
        here.stop_number = self.stops_seen;
        print(f"Stop #{here.stop_number}: reached waypoint {self.stops_seen} of {self.target_stops}");
        if self.stops_seen >= self.target_stops {
            print(f"Trail complete! {self.stops_seen} waypoints passed on {self.trail_name}");
            disengage;
        }
        visit [-->] else { disengage; }
    }
}

with entry {
    w1 = Waypoint();
    w2 = Waypoint();
    w3 = Waypoint();
    w4 = Waypoint();
