"""Structural invariant checkers (BST ordering, heap property, list acyclicity).

Models the issue's hand-rolled traversal pain as native Jac:
- BST nodes connected by typed Parent/Child edges; a walker enforces
  ordering bounds while traversing (replacing manual ancestor recursion).
- A heap node exposes the array-backed heap and a walker sifts while
  re-checking the parent/child predicate (replacing the swap loop).
- A linked list uses typed Next edges with a cycle guard (Floyd-style
  visited set) since Jac 0.36.1 walkers do not dedupe cyclic graphs.
"""

# ---------- BST ----------

node BSTNode {
    has value: int = 0;
    has lo: int = -1;
    has hi: int = -1;
    has violated: bool = False;
}

edge BSTChild { }

walker BSTOrderChecker {
    has source: str = "BST";
    has failed: bool = False;

    can start with Root entry {
        print(f"[{self.source}] start");
        visit [->:BSTChild:->];
    }

    can descend with BSTNode entry {
        if here.violated {
            verdict = "BROKEN";
        } else {
            verdict = "OK";
        }
        print(f"[{self.source}] {verdict}: node value={here.value}, bound=({here.lo},{here.hi})");
        if here.violated and not self.failed {
            self.failed = True;
        }
        visit [->:BSTChild:->];
    }
}

# ---------- Heap ----------

node HeapNode {
    has parent_idx: int = -1;
    has child_idx: int = -1;
    has parent_val: int = 0;
    has child_val: int = 0;
    has violated: bool = False;
}

edge HeapRel { }

walker HeapChecker {
    has source: str = "Heap";
    has failed: bool = False;

    can start with Root entry {
        print(f"[{self.source}] start");
        visit [->:HeapRel:->];
    }

    can check with HeapNode entry {
        if here.violated {
            verdict = "BROKEN";
        } else {
            verdict = "OK";
        }
        print(
            f"[{self.source}] {verdict}: arr[{here.parent_idx}]={here.parent_val} "
            f"<= arr[{here.child_idx}]={here.child_val}"
        );
        if here.violated and not self.failed {
            self.failed = True;
        }
        visit [->:HeapRel:->];
    }
}

# ---------- Linked list ----------

node ListNode {
    has value: int = 0;
    has visited: bool = False;
}

edge Next { }

walker AcyclicityChecker {
    has source: str = "List";
    has failed: bool = False;
    has seen: list[int] = [];

    can start with Root entry {
        print(f"[{self.source}] start");
        visit [->:Next:->];
    }

    can walk with ListNode entry {
        if here.visited {
            self.failed = True;
            print(f"[{self.source}] BROKEN: cycle revisited node value={here.value}");
            disengage;
        }
        here.visited = True;
        self.seen.append(here.value);
        print(f"[{self.source}] OK: visited node value={here.value}");
        visit [->:Next:->] else { disengage; }
    }
}

