```jac
"""Agent Flow Studio: model kit/skill/agent workflow as a typed graph and
walk it to validate, migrate, and prune the workbench.

Core scenario: a kit owns a React Flow UI; skills orchestrate the kit;
agents (fixtures) live inside kits via a thin mirror edge. The walker
performs a recursive sweep that the original issue hand-rolled — visiting
every owned entity, validating references, and pruning empty containers.
"""

node Kit {
    has name: str = "";
    has port: int = 0;
    has api_ready: bool = False;
    has ui_ready: bool = False;
}

node Skill {
    has name: str = "";
    has thin: bool = False;
    has dual_skill_blocked: bool = False;
}

node Agent {
    has name: str = "";
    has preserved_md: bool = True;
}

node Snapshot {
    has label: str = "";
    has depth: int = 0;
}

# Typed edges carry the relationship meaning.
edge Owns { has since: str = ""; }
edge Launches { has trigger: str = ""; }
edge Mirrors { has preserve_md: bool = True; }
edge HasSnapshot { has order: int = 0; }

walker FlowAuditor {
    has max_depth: int = 8;
    has visited: list[str] = [];
    has orphans: list[str] = [];
    has thin_skills: list[str] = [];
    has missing_api: list[str] = [];
    has pruned: list[str] = [];

    can start with Root entry {
        print(f"=== Flow audit starting (max_depth={self.max_depth}) ===");
        visit [-->];
    }

    can audit_kit with Kit entry {
        if here.name not in self.visited {
            self.visited.append(here.name);
        }
        print(f"[KIT] {here.name} port={here.port} "
              f"api={here.api_ready} ui={here.ui_ready}");
        if not here.api_ready {
            self.missing_api.append(here.name);
        }
        # Cascade into owned skills, mirrored agents, and snapshots.
        visit [->:Owns:->] else { disengage; }
        visit [->:Launches:->] else { disengage; }
    }

    can audit_skill with Skill entry {
        label = f"{here.name} (thin)" if here.thin else here.name;
        if here.thin {
            self.thin_skills.append(label);
        }
        # A thin skill MUST NOT have a dual kit SKILL block.
        if here.dual_skill_blocked {
            print(f"  [409] thin-skill conflict on {here.name}");
        } else {
            print(f"[SKILL] {label} dual_blocked={here.dual_skill_blocked}");
        }
        visit [->:Owns:->];
    }

    can audit_agent with Agent entry {
        status = "kept" if here.preserved_md else "stripped";
        print(f"[AGENT] {here.name} md={status}");
        visit [->:HasSnapshot:->];
    }

    can audit_snapshot with Snapshot entry {
        if here.label in self.visited {
            self.orphans.append(here.label);
        } else {
            self.visited.append(here.label);
        }
        print(f"  [SNAP] {here.label} depth={here.depth}");
        if here.depth >= self.max_depth {
            print(f"  depth cap reached on {here.label}");
            disengage;
        }
        visit [->:HasSnapshot:->];
    }

    can finalize with Root entry {
        # Migrate-time orphan scan + empty-dir prune.
        for name in self.orphans {
            self.pruned.append(f"orphan:{name}");
        }
        # A kit with no API is treated as an empty container to prune.
        for kit_name in self.missing_api {
            self.pruned.append(f"empty-dir:{kit_name}");
        }
        print("=== Audit summary ===");
        print(f"  visited:   {self.visited}");
        print(f"  thin:      {self.thin_skills}");
        print(f"  missing:   {self.missing_api}");
        print(f"  orphans:   {self.orphans}");
        print(f"  pruned:    {self.pruned}");
        report {
            "visited": self.visited,
            "thin_skills": self.thin_skills,
            "missing_api": self.missing_api,
            "orphans": self.orphans,
            "pruned": self.pruned,
        };
    }
}

