        self.visited.append(here.name);
        # Explicit cycle policy: track visited houses so a mutual link
        # can't bounce the walker back and forth forever.
        here_targets = [n for n in [-->] if n.name not in self.visited];
        if here_targets {
            visit here_targets;
        }
