"""License audit dependency graph.

Models a package and its transitive dependencies with typed edges carrying
license + version metadata. An auditor walker cascades through the graph,
detects GPL/AGPL/OSL violations against an MIT allowlist, flags unknown
licenses, and refuses to descend through an offending node (cycle + illegal
subtree handling).
"""

node Package {
    has name: str = "";
    has version: str = "";
    has license: str = "";
    has violations: list[str] = [];
    has scanned: bool = False;
}

edge DependsOn {
    has constraint: str = "";
}

edge BlockedBy {
    has reason: str = "";
}

walker LicenseAuditor {
    has allowlist: list[str] = [];
    has forbidden: list[str] = [];
    has report: list[str] = [];
    has pending: list[str] = [];

    can start with Root entry {
        print(f"Auditing transitive dependencies (allowlist: {self.allowlist})");
        visit [-->];
    }

    can audit with Package entry {
        if here.scanned {
            visit [-->];
            return;
        }
        here.scanned = True;

        is_ok = False;
        for lic in self.allowlist {
            if here.license == lic {
                is_ok = True;
                break;
            }
        }
        if is_ok {
            note = f"OK   {here.name}@{here.version} ({here.license})";
            self.report.append(note);
            print(note);
            visit [-->];
            return;
        }

        is_forbidden = False;
        for lic in self.forbidden {
            if here.license == lic {
                is_forbidden = True;
                break;
            }
        }
        if is_forbidden {
            tag = "FORBIDDEN";
            note = f"FAIL {here.name}@{here.version} ({here.license}) [{tag}]";
            self.report.append(note);
            print(note);
            visit [-->] else { disengage; };
            return;
        }

        note = f"UNKNOWN {here.name}@{here.version} ({here.license}) - reviewer approval required";
        self.report.append(note);
        print(note);
        visit [-->];
    }

    can summarize with Root entry {
        print("--- audit summary ---");
        for line in self.report {
            print(line);
        }
        print(f"total packages reviewed: {len(self.report)}");
    }
}

walker DependencyCascade {
    has visited: list[str] = [];
    has depth_limit: int = 4;
    has current_depth: int = 0;

    can start with Root entry {
        print("Cascading dependency invalidation (depth-limited, cycle-safe)");
        visit [-->];
    }

    can cascade with Package entry {
        seen = False;
        for v in self.visited {
            if v == here.name {
                seen = True;
                break;
            }
        }
        if seen {
            print(f"[cycle guard] already visited {here.name}, stopping branch");
            visit [-->] else { disengage; };
            return;
        }
        self.visited.append(here.name);

        if self.current_depth >= self.depth_limit {
            print(f"[depth cap] reached limit at {here.name}");
            visit [-->] else { disengage; };
            return;
        }
        self.current_depth += 1;
        print(f"[depth {self.current_depth}] invalidating {here.name}@{here.version}");
        visit [-->];
    }
}

