"""Pet-aware friend recommender: walk a social graph and suggest only adult humans."""

node Profile {
    has name: str = "";
    has species: str = "human";
    has age: int = 0;
}

walker Recommender {
    has raw_count: int = 0;
    has kept_count: int = 0;
    has visited: list = [];

    can start with Root entry {
        visit [-->];
    }

    can recurse with Profile entry {
        if here.name in self.visited {
            visit [-->];
            return;
        }
        self.visited.append(here.name);
        self.raw_count = 0;
        self.kept_count = 0;
        for nbr in [-->] {
            self.raw_count += 1;
            if nbr.species == "human" and nbr.age >= 18 {
                self.kept_count += 1;
                print(f"  suggest {nbr.name} (human, {nbr.age}) to {here.name}");
            } else {
                reason = "pet" if nbr.species != "human" else "minor";
                print(f"  skip {nbr.name} ({reason}) for {here.name}");
            }
        }
        print(f"{here.name} saw {self.raw_count} raw neighbour(s), {self.kept_count} survived filters");
        visit [-->];
    }
}

