Task:
A maintainer on the project Ledger-Lenz/Ledgerlens-core (Python) filed this issue about hand-rolled graph machinery causing pain:

Issue #613: Build a Reorg-Safe Cross-Chain Correlation Pipeline for Stellar, EVM, and Solana Activity

## Overview

The repository already contains Stellar, EVM bridge, and Solana ingestion components, but lacks a unified event-time pipeline that can reliably correlate activity across chains with different finality models and detect wash cycles that traverse chains. Naive address- or timestamp-based matching would create false links and fail under reorgs, delayed bridge settlement, or duplicated provider events. This issue calls for building a reorg-safe, cross-chain correlation pipeline.

## Use Cases

- **Canonical event modeling:** Define a canonical cross-chain event envelope containing: chain ID, block/ledger identity, event time, observed time, finality state, transaction/log identity, asset identity, and provenance.
- **Idempotent ingestion with reorg compensation:** Implement idempotent ingestion and reorg compensation for EVM/Solana, while preserving Stellar checkpoint semantics.
- **Asset normalization:** Normalize wrapped/bridged assets through an explicitly versioned asset registry.
- **Confidence-scored linking:** Produce confidence-scored wallet/transfer links using verifiable bridge evidence; heuristic identity must never be treated as fact.
- **Multi-hop cycle detection:** Add event-time windows, watermarks, late-arrival handling, and bounded state for multi-hop wash-cycle detection.
- **Shadow scoring:** Feed cross-chain features into shadow scoring before enabling them in production weighting.

## Acceptance Criteria

- Duplicate delivery and provider failover do not duplicate features (idempotency).
- Reorged events are retracted; affected correlations/scores are recomputed or invalidated.
- Every link exposes evidence, confidence, and provenance.
- Tests cover: delayed finality, reorgs, clock skew, bridge retries, asset-decimal mismatch, and incomplete paths.
- Offline evaluation reports false-link rate and detection lift.
- Operational metrics expose: lag, watermark, unresolved assets, retractions, and state size.

## Pain

- No unified event-time pipeline exists across the three chains, so cross-chain activity cannot be reliably correlated.
- Naive matching (address or timestamp) generates false links.
- Reorgs, delayed bridge settlement, and duplicated provider events break naive approaches.

Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.

```jac
"""Cross-chain correlation pipeline: event-time walker that detects multi-hop
wash cycles across Stellar, EVM, and Solana chains with reorg-safe invalidation.

Models a tiny slice of Ledgerlens-core's correlation pipeline as an OSP graph:
canonical events are nodes, asset/wallet links are typed edges, and a walker
walks the event-time windowed frontier to detect wash cycles and retract
reorged events.
"""

node CanonicalEvent {
    has chain: str = "";
    has block_or_ledger: str = "";
    has event_time_ms: int = 0;
    has tx_id: str = "";
    has asset: str = "";
    has amount: float = 0.0;
    has finality: str = "pending";
    has retracted: bool = False;
}

node Wallet {
    has address: str = "";
    has chain: str = "";
}

node Asset {
    has symbol: str = "";
    has decimals: int = 0;
}

edge BelongsTo {
    has confidence: float = 1.0;
    has evidence: str = "";
}

edge BridgeLink {
    has bridge: str = "";
    has confidence: float = 1.0;
    has evidence: str = "";
}

walker Correlation {
    has horizon_ms: int = 100000;
    has cycles_found: int = 0;
    has retracted_count: int = 0;
    has visited: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can correlate with CanonicalEvent entry {
        if here.retracted {
            visit [-->];
            return;
        }
        seen = False;
        for vid in self.visited {
            if vid == here.tx_id {
                seen = True;
            }
        }
        if seen {
            return;
        }
        self.visited.append(here.tx_id);
        if here.event_time_ms > self.horizon_ms {
            visit [-->];
            return;
        }
        print(f"[event] chain={here.chain} asset={here.asset} "
              f"amount={here.amount} finality={here.finality}");
        visit [->:BelongsTo:->];
    }

    can follow_wallet with Wallet entry {
        print(f"  -> wallet {here.address} on {here.chain}");
        visit [-->];
    }

    can cycle_scan with Asset entry {
        print(f"  :: asset {here.symbol} (decimals={here.decimals})");
        if here.symbol == "USDC" {
            self.cycles_found += 1;
            print(f"     [CYCLE] suspicious wash loop on {here.symbol}");
        }
        visit [-->];
    }
}

walker Reorg {
    can start with Root entry {
        visit [-->];
    }

    can retract with CanonicalEvent entry {
        if here.chain == "EVM" and here.finality == "pending" {
            here.retracted = True;
            print(f"[reorg] retracting {here.chain}/{here.tx_id} "
                  f"at block {here.block_or_ledger}");
            self.invalidations += 1;
        }
        visit [-->];
    }

    has invalidations: int = 0;
}

with entry {
    usdc = Asset(symbol="USDC", decimals=6);
    weth = Asset(symbol="WETH", decimals=18);
    root ++> usdc ++> weth;

    stellar_wallet = Wallet(address="GABC...", chain="stellar");
    evm_wallet = Wallet(address="0xDEAD", chain="evm");
    solana_wallet = Wallet(address="So1..", chain="solana");
    root ++> stellar_wallet ++> evm_wallet ++> solana_wallet;

    e1 = CanonicalEvent(
        chain="Stellar", block_or_ledger="L1234",
        event_time_ms=1000, tx_id="tx-stellar-1",
        asset="USDC", amount=500.0, finality="final"
    );
    e2 = CanonicalEvent(
        chain="EVM", block_or_ledger="0xABC",
        event_time_ms=3000, tx_id="tx-evm-2",
        asset="USDC", amount=495.0, finality="pending"
    );
    e3 = CanonicalEvent(
        chain="Solana", block_or_ledger="slot-9",
        event_time_ms=5000, tx_id="tx-sol-3",
        asset="USDC", amount=510.0, finality="confirmed"
    );
    e4 = CanonicalEvent(
        chain="EVM", block_or_ledger="0xDEF",
        event_time_ms=2000, tx_id="tx-evm-4",
        asset="WETH", amount=1.2, finality="final"
    );

    root ++> e1 ++> e2 ++> e3 ++> e4;

    e1 +>:BelongsTo(confidence=1.0, evidence="native-holding"):+> stellar_wallet;
    e2 +>:BelongsTo(confidence=1.0, evidence="native-holding"):+> evm_wallet;
    e3 +>:BelongsTo(confidence=1.0, evidence="native-holding"):+> solana_wallet;
    e4 +>:BelongsTo(confidence=1.0, evidence="native-holding"):+> evm_wallet;

    stellar_wallet +>:BridgeLink(
        bridge="wormhole", confidence=0.92,
        evidence="wormhole-vaa-0xfeed"
    ):+> solana_wallet;

    solana_wallet +>:BridgeLink(
        bridge="allbridge", confidence=0.88,
        evidence="allbridge-tx-0xbeef"
    ):+> evm_wallet;

    print("=== Correlation pass ===");
    root spawn Correlation(horizon_ms=6000);

    print("\n=== Reorg pass (retract pending EVM) ===");
    root spawn Reorg();

    print("\n=== Re-run correlation after reorg ===");
    c2 = Correlation(horizon_ms=6000);
    root spawn c2;

    print(f"\ncycles_found={c2.cycles_found} "
          f"retracted={c2.retracted_count} "
          f"visited={len(c2.visited)}");
}
