```jac
"""Reverse dependency reachability with cycle-safe in-process traversal."""

node GraphItem {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Artifact(GraphItem) {
    has category: str = "";
}

node Revision(GraphItem) {
    has revision_number: int = 0;
}

edge DependsOn {
    has tier: int = 0;
    has reason: str = "";
}

walker BlastRadiusAudit {
    has depth_limit: int = 8;
    has visited_titles: list[str] = [];
    has affected_count: int = 0;
    has incident_lookups: int = 0;

    can start with Root entry {
        print("Starting reverse reachability audit");
        visit [-->] else {
            disengage;
        }
    }

    can inspect with Artifact | Revision entry {
        if here.title in self.visited_titles {
            print(f"Cycle detected at {here.title}; stopping this branch");
            disengage;
        } else {
            self.visited_titles.append(here.title);
            self.affected_count += 1;
            self.incident_lookups += 1;

            status = "available" if here.available else "stale";
            print(f"Visited {here.title} ({status})");

            if self.affected_count >= self.depth_limit {
                print("Depth limit reached");
                disengage;
            } else {
                visit [<--:DependsOn:--] else {
                    disengage;
                }
            }
        }
    }
}

with entry {
    platform = Artifact(
        title="Platform",
        year=2024,
        category="runtime"
    );
    api = Artifact(
        title="Public API",
        year=2024,
        category="interface"
    );
    release = Revision(
        title="Release 7",
        year=2025,
        revision_number=7,
        available=False
    );

    root ++> platform;
    api +>:DependsOn(tier=1, reason="public API uses runtime"):+> platform;
    release +>:DependsOn(tier=2, reason="release packages API"):+> api;
    platform +>:DependsOn(tier=9, reason="intentional cycle for audit"):+> release;

    audit = BlastRadiusAudit(depth_limit=6);
    root spawn audit;

    print(
        f"Reachable entities: {audit.affected_count}; "
        f"incident lookups: {audit.incident_lookups}"
    );
}
