Run feeding rounds at a wildlife park: the info kiosk greets every tour party regardless of who they are, zookeepers feed each animal its species-appropriate meal (meat for lions, seed for parrots, standard feed otherwise), and school groups just watch the animals.

```jac
"""Wildlife park feeding rounds: kiosk greets everyone; zookeepers feed by species; school groups just observe."""

node Kiosk {
    has name: str = "Main Kiosk";

    # Union trigger: fires for ANY tour party - zookeeper OR school group.
    can greet with Zookeeper | SchoolGroup entry {
        party_label = "staff" if isinstance(visitor, Zookeeper) else "school group";
        print(f"  [Kiosk {self.name}] Welcome, {party_label}! Enjoy your visit.");
    }
}

node Animal {
    has species: str = "";
    has name: str = "";

    can feed_standard with Zookeeper entry {
        print(f"    {visitor.badge} gives standard feed to {self.name} the {self.species}.");
    }
}

node Lion(Animal) {
    override can feed_standard with Zookeeper entry {
        print(f"    {visitor.badge} feeds raw meat to {self.name} the lion.");
    }
}

node Parrot(Animal) {
    override can feed_standard with Zookeeper entry {
        print(f"    {visitor.badge} feeds seed mix to {self.name} the parrot.");
    }
}

walker Zookeeper {
