```jac
"""Anonymous reading-club poll.

Three walkers cooperate over a small graph of book option nodes and a
shared counter node:

* ``PollSetup``  - configures the ballot by attaching the books to root.
* ``CastVote``   - records one anonymous vote against the chosen option.
* ``Tally``      - reports the live tallies back as the response.

No login, no accounts: each tap is a fresh walker spawn.
"""

node Book {
    has title: str = "";
    has author: str = "";
}

node Counter {
    has label: str = "";
    has count: int = 0;
}

edge Option {
    # Typed edge that connects a poll option (Book) to its tally node.
    has note: str = "";
}

walker PollSetup {
    # Configures the ballot. Spawned on root; walks to each Book and
    # ensures a Counter is wired so votes have somewhere to land.
    can start with Root entry {
        print("Setting up the poll...");
        visit [-->];
    }

    can wire_counter with Book entry {
        tally = Counter(label=here.title);
        here +>:Option(note="ballot")+:> tally;
        print(f"  option ready: {here.title} by {here.author}");
        visit [-->];
    }
}

walker CastVote {
    # One anonymous tap. Walks to a Book, finds its Counter, increments.
    has pick: str = "";

    can start with Root entry {
        print(f">>> anonymous vote arriving for {self.pick!r}");
        # Walk only to Book nodes whose title matches the pick.
        visit [-->[?:Book]];
    }

    can record_vote with Book entry {
        if here.title != self.pick {
            visit [-->];
            return;
        }
        # Find the counter attached via an Option edge and bump it.
        next_target = null;
        for n in [->:Option:->] {
            if isinstance(n, Counter) {
                next_target = n;
            }
        }
        if next_target is not None {
            next_target.count += 1;
            print(f"  +1 -> {here.title} (now {next_target.count})");
        } else {
            print(f"  no counter for {here.title}");
        }
        disengage;
    }
}

walker Tally {
    # Reports the live tallies. Visits every Counter node and prints
    # a single consolidated report.
    has report: list = [];

    can start with Root entry {
        visit [-->];
    }

    can visit_book with Book entry {
        visit [-->];
    }

    can visit_counter with Counter entry {
        self.report.append((here.label, here.count));
        visit [-->];
    }
}

with entry {
    # ---- wire the ballot -------------------------------------------------
    root ++> Book(title="Dune", author="Herbert")
        ++> Book(title="Neuromancer", author="Gibson")
        ++> Book(title="Circe", author="Miller");

    PollSetup() spawn root;

    # ---- simulate anonymous clicks ---------------------------------------
    votes = ["Dune", "Circe", "Dune", "Neuromancer", "Dune", "Circe"];
    for pick in votes {
        CastVote(pick=pick) spawn root;
    }

    # ---- collect and report ----------------------------------------------
    tally = Tally();
    root spawn tally;

    print("");
    print("=== Final tally ===");
    for (label, count) in tally.report {
        print(f"  {label}: {count}");
    }
}
