```jac
"""Roster cap: model deterministic cap membership over a pool of tied players.

Demonstrates the issue where cap membership is non-deterministic when several
players share the same score. The fix is two-fold:
  1. The input pool must be sorted by a total key (score DESC, then player_id
     ASC) so ties break stably.
  2. Each per-position floor list must itself be sorted by the same total key
     before slicing, otherwise identical inputs in different orders yield
     different survivor sets.

We model Players, their Position, and a RosterCap walker that walks the pool,
applies per-position floors, then fills the remaining budget cross-position,
all with a stable total ordering.
"""

node Player {
    has player_id: int = 0;
    has vbd_score: float = 0.0;
    has position: str = "";
}

edge PlaysPosition {
    has slot: int = 0;
}

node RosterConfig {
    has cap: int = 0;
    has remaining_budget: int = 0;
    has per_position_min: int = 0;
}

walker RosterCap {
    has config: RosterConfig;
    has survivors: list[Player] = [];

    can start with Root entry {
        visit [-->];
    }

    can cap with Player entry {
        self.survivors.append(here);
        visit [-->];
    }
}

def stable_sort(players: list[Player]) -> list[Player] {
    return sorted(players, key=lambda (p: Player) -> tuple { (-p.vbd_score, p.player_id) });
}

def apply_floor(by_position: dict, per_position_min: int) -> list[Player] {
    floored: list[Player] = [];
    for pos in by_position.keys() {
        group = by_position[pos];
        ordered = sorted(group, key=lambda (p: Player) -> tuple { (-p.vbd_score, p.player_id) });
        n = per_position_min;
        if n > len(ordered) {
            n = len(ordered);
        }
        floored = floored + ordered[:n];
    }
    return floored;
}

def fill_remaining(floored: list[Player], budget: int) -> list[Player] {
    floored_ids: list[int] = [p.player_id for p in floored];
    remaining_pool: list[Player] = [];
    # Caller's responsibility: pass an already-stable pool. We re-sort here
    # so the walker-driven traversal order never perturbs cap membership.
    remaining_pool = sorted(floored, key=lambda (p: Player) -> tuple { (-p.vbd_score, p.player_id) });
    n = budget;
    if n > len(remaining_pool) {
        n = len(remaining_pool);
    }
    return remaining_pool[:n];
}

def run_cap(all_players: list[Player], config: RosterConfig) -> list[Player] {
    stable_pool: list[Player] = stable_sort(all_players);

    by_position: dict = {};
    for p in stable_pool {
        bucket = by_position.get(p.position, []);
        bucket.append(p);
        by_position[p.position] = bucket;
    }

    floored: list[Player] = apply_floor(by_position, config.per_position_min);
    capped: list[Player] = fill_remaining(floored, config.remaining_budget);
    capped = sorted(capped, key=lambda (p: Player) -> tuple { (-p.vbd_score, p.player_id) });

    if len(capped) > config.cap {
        capped = capped[:config.cap];
    }
    return capped;
}

