Issue #312: [Maintenance] CI/CD: License audit on transitive dependencies (dotnet-licenses / FOSSA)

## Scope

Dependabot tracks dependency *versions* (and CVE alerts). It does not check the *licenses* of transitive dependencies. A new transitive dependency with an incompatible license (GPL, AGPL, OSL, business-source) silently leaks into a derivative work distributed under MIT — a real procurement / legal exposure for downstream consumers.

The deferred work is a license-audit workflow using `dotnet-licenses` / FOSSA / Snyk Open Source / similar that enumerates every transitive package, captures its declared license, and fails the build on incompatible / unknown licenses.

## Acceptance criteria

- A `license-audit.yaml` workflow runs on PR + scheduled.
- Findings produce a `THIRD-PARTY-NOTICES.md` (or similar) generated automatically per release; license attribution is shipped in the NuGet package per the licenses' requirements.
- A documented allowlist (MIT / Apache-2.0 / BSD-2-Clause / BSD-3-Clause / similar) gates new packages; anything else needs explicit reviewer approval recorded in the PR.
- A baseline scan of the current `main` documents current dependencies + licenses.

## Notes

- Tier-1 follow-up. Required for procurement at most enterprises; goes beyond Dependabot's surface.
- Originated as part of the IAsyncEnumerable-Extensions thorough-review pass; tracked fleet-wide.
- Board: https://github.com/users/Chris-Wolfgang/projects/6

Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.

```jac
"""License audit on transitive dependencies.

Models the CI/CD concern from issue #312: a NuGet-style project whose
direct and transitive dependencies carry licenses, and an auditor walker
that traverses the full dependency closure to verify every shipped
package sits inside an allowlist.

Graph shape:

    Package
       |
       | DependsOn (transitive, payload: depth + resolved_license)
       v
    Package

A *LicenseAllowlist* node owns the set of permitted SPDX identifiers; a
*PolicyViolation* node is materialised by the auditor whenever the walker
descends into a dependency whose license is not allowed (or unknown).

Traversal: the auditor descends the dependency tree via typed
``DependsOn`` edges. Because Jac walkers have no built-in cycle guard,
the walker maintains an explicit visited set keyed on the current node
identity; revisiting a node is a domain-meaningful cycle (the same
package reached via two paths) and is reported, not silently followed.
The walker stops cleanly when no more ``DependsOn`` edges remain via
``visit ... else { disengage; }``.
"""

node Package {
    has name: str = "";
    has version: str = "";
    has license: str = "";   # SPDX id, e.g. "MIT", "GPL-3.0-or-later", "UNKNOWN"
    has depth: int = 0;       # 0 = direct dependency, >0 = transitive
    has transitive: list[Package] = [];   # kept for legacy inspection only;
                                            # the real traversal goes via edges
}

edge DependsOn {
    has depth: int = 0;
}

node LicenseAllowlist {
    has name: str = "";
    has allowed: list[str] = [];   # SPDX ids permitted for distribution
}

node PolicyViolation {
    has package_name: str = "";
    has license: str = "";
    has reason: str = "";
}

walker LicenseAuditor {
    has allowlist_ref: str = "default";
    has visited: list[str] = [];          # explicit cycle guard (Jac 0.36.1
                                           # walkers have no built-in dedup)
    has violations: list[PolicyViolation] = [];
    has reachable: list[Package] = [];

    can start with Root entry {
        # Pick up the allowlist node by name and remember it.
        for n in [-->] {
            if isinstance(n, LicenseAllowlist) and n.name == self.allowlist_ref {
                self.allowlist_node = n;
                break;
            }
        }
        visit [-->];
    }

    can audit with Package entry {
        # Cycle policy: same package reached twice via two paths is
        # recorded as a note, not re-walked.
        if here.name in self.visited {
            print(f"[cycle] re-entered {here.name}@{here.version}; skipping");
            disengage;
        }
        self.visited.append(here.name);
        self.reachable.append(here);

        # Look the license up against the allowlist carried on the walker.
        allow: list[str] = self.allowlist_node.allowed;
        verdict = "ok";
        if here.license == "UNKNOWN" {
            verdict = "unknown";
        } elif not (here.license in allow) {
            verdict = "blocked";
        }

        if verdict != "ok" {
            reason = (
                "license not in allowlist"
                if verdict == "blocked"
                else "license unresolved"
            );
            v = PolicyViolation(
                package_name=here.name + "@" + here.version,
                license=here.license,
                reason=reason,
            );
            self.violations.append(v);
            root +>:Flagged:+> v;
            print(f"[VIOLATION] {v.package_name} ({v.license}): {v.reason}");
        } else {
            print(f"[ok] {here.name}@{here.version} ({here.license}, depth={here.depth})");
        }

        # Keep descending the dependency closure via the typed edge.
        visit [->:DependsOn:->] else {
            disengage;
        };
    }
}

edge Flagged { }

with entry {
    # --- Allowlist: the procurement gate ----------------------------------
    allowlist = LicenseAllowlist(
        name="default",
        allowed=["MIT", "Apache-2.0", "BSD-2-Clause", "BSD-3-Clause"],
    );

    # --- Direct + transitive dependency graph ----------------------------
    # project -> autofac (MIT) -> ...
    autofac = Package(name="Autofac", version="7.1.0", license="MIT", depth=0);

    # a clean chain: everything MIT / BSD / Apache-2.0
    newtonsoft = Package(name="Newtonsoft.Json", version="13.0.3",
                         license="MIT", depth=1);
    moq = Package(name="Moq", version="4.20.70", license="BSD-3-Clause", depth=1);

    # a forbidden leaf (GPL) — must trip the auditor
    gpl_leaf = Package(name="GPLHelper", version="1.0.0",
                       license="GPL-3.0-or-later", depth=2);

    # an unknown leaf — license metadata missing on NuGet.org
    unknown_leaf = Package(name="ObscureLib", version="0.4.1",
                           license="UNKNOWN", depth=2);

    # a cyclic reference (nuget transitive graphs do this): gpl_leaf also
    # pulls Autofac back in. The auditor must not loop forever.
    root ++> autofac
        +>:DependsOn(depth=1):+> newtonsoft
        +>:DependsOn(depth=1):+> moq;
    autofac +>:DependsOn(depth=2):+> gpl_leaf;
    autofac +>:DependsOn(depth=2):+> unknown_leaf;
    gpl_leaf +>:DependsOn(depth=3):+> autofac;   # deliberate cycle

    # --- Run the auditor -------------------------------------------------
    auditor = LicenseAuditor(allowlist_ref="default");
    # Pre-load the allowlist lookup onto the walker via a normal field;
    # the entry ability also resolves it by walking from root.
    auditor.allowlist_node = allowlist;
    root spawn auditor;

    print("---");
    print(f"reachable packages: {len(auditor.reachable)}");
    for p in auditor.reachable {
        print(f"  - {p.name}@{p.version} [{p.license}] depth={p.depth}");
    }
    print(f"violations found : {len(auditor.violations)}");
    for v in auditor.violations {
        print(f"  ! {v.package_name}: {v.license} ({v.reason})");
    }
}
