```jac
"""Barber referral network: model clients as nodes and walk the referral
tree with a walker that handles cycles and accumulates reward status."""

node Client {
    has name: str = "";
    has reward: bool = False;
    has visited: bool = False;
}

edge ReferredBy {
    has weight: int = 1;
}

walker ReferralWalker {
    has trail: list[str] = [];
    has reward_count: int = 0;
    has client_count: int = 0;

    can start with Root entry {
        print(f"Starting referral walk from root");
        visit [-->];
    }

    can gather with Client entry {
        if here.visited {
            print(f"[CYCLE GUARD] skipping already-seen {here.name}");
            disengage;
        }
        here.visited = True;
        self.client_count += 1;
        if here.reward {
            self.reward_count += 1;
        }
        self.trail.append(here.name);
        print(f"visited {here.name} (reward={here.reward})");
        visit [->:ReferredBy:->];
    }
}

walker NetworkAuditor {
    can start with Root entry {
        print(f"Auditing referral network");
        visit [-->];
