"""Propstore merge-report: model the merge-commit-report scenario natively.

The issue complains that the app's report is rebuilt by scanning the committed
tree and re-querying live branches, instead of consuming a typed result returned
by the exact committed plan. We model that here:

  * A MergeManifest records the exact committed plan for a merge event
    (target branch, pinned tips, claimed paths, semantic candidate count,
    and a manifest id). One merge event mints one MergeManifest, even when
    two merges legitimately share identical content.
  * The MergeCommit walker *returns* the typed MergeManifest from the exact
    committed plan (no tree scan, no live-branch re-read).
  * The ReportConsumer walks the target branch's chain of MergeManifests and
    prints them in commit order — verifying that the newest merge is reported,
    not whatever happens to lexically sort first in the tree.
  * Advancing a source branch after commit must NOT change a reported field,
    because the MergeManifest is owned by the committed event, not by the
    branch state at report time.
"""

node Branch {
    has name: str = "";
    has tip: str = "";
    has extra_commits: int = 0;
}

node MergeManifest {
    has manifest_id: str = "";
    has merge_commit: str = "";
    has target: str = "";
    has parent_a: str = "";
    has parent_b: str = "";
    has claim_paths: list[str] = [];
    has claim_ids: list[str] = [];
    has semantic_candidate_count: int = 0;
    has reused_content: bool = False;
}

edge OnBranch {
    has position: int = 0;
}

edge AuthoredMerge {
    has order: int = 0;
}

walker MergeCommit {
    has target_name: str = "";
    has tip_a: str = "";
    has tip_b: str = "";
    has claim_paths: list[str] = [];
    has claim_ids: list[str] = [];
    has semantic_candidate_count: int = 0;
    has preflight_failed: bool = False;

    can perform with Branch entry {
        if self.preflight_failed {
            print(f"[abort] preflight failed on {here.name}; no commit produced");
            report None;
            disengage;
        }

        merge_sha = f"merge-{here.name}-{self.target_name}";
        manifest_id = f"ps:merge:{merge_sha[:6]}";
        content_reused = bool(self.claim_ids) and self.claim_ids[0].startswith("shared:");

        manifest = MergeManifest(
            manifest_id=manifest_id,
            merge_commit=merge_sha,
            target=self.target_name,
            parent_a=self.tip_a,
            parent_b=self.tip_b,
            claim_paths=list(self.claim_paths),
            claim_ids=list(self.claim_ids),
            semantic_candidate_count=self.semantic_candidate_count,
            reused_content=content_reused
        );

        here +>:AuthoredMerge(order=here.extra_commits):+> manifest;
        here.extra_commits = here.extra_commits + 1;

        print(
            f"[commit] target={self.target_name} "
            f"parents=[{self.tip_a},{self.tip_b}] "
            f"manifest={manifest_id} candidates={self.semantic_candidate_count}"
        );

        report manifest;
        disengage;
    }
}

walker ReportConsumer {
    has verbose: bool = True;

    can scan with Branch entry {
        print(f"== report for branch {here.name} ==");
        visit [->:AuthoredMerge:->];
    }

    can show with MergeManifest entry {
        marker = "(reused content)" if here.reused_content else "";
        print(
            f"  [{here.target}] commit={here.merge_commit} "
            f"parents=[{here.parent_a},{here.parent_b}] "
            f"manifest={here.manifest_id} candidates={here.semantic_candidate_count} {marker}"
        );
        print(f"    claim_paths={here.claim_paths}");
        print(f"    claim_ids={here.claim_ids}");
        visit [->:AuthoredMerge:->];
    }
}

walker AdvanceBranch {
    has new_tip: str = "";

    can act with Branch entry {
        prior_tip = here.tip;
        here.tip = self.new_tip;
        print(f"[advance] {here.name} {prior_tip} -> {here.tip} (reported fields unchanged)");
        disengage;
    }
}

