"""ATLANTIS release-gate walk: model the 7-day operational alpha as a graph
of stages traversed by a gatekeeper walker that enforces policy and
collects evidence."""

# ── Entity archetypes (release stages / artifacts / controls) ─────────────
node Stage {
    has title: str = "";
    has day: int = 0;
    has complete: bool = False;
}

node Artifact {
    has title: str = "";
    has kind: str = "";
    has sealed: bool = False;
}

node Control {
    has title: str = "";
    has passed: bool = False;
}

node Threat {
    has title: str = "";
    has severity: str = "low";
}

# ── Edge archetypes (relationships that carry meaning) ─────────────────────
edge Follows { has order: int = 0; }          # stage ordering
edge Produces { has evidence_id: str = ""; }  # stage -> artifact
edge Governs { has gate: str = ""; }          # control -> stage
edge Blocks { has reason: str = ""; }         # threat -> stage

# ── Walker: walks the release graph, enforces gates, reports once ─────────
walker Gatekeeper {
    has blocked_count: int = 0;
    has passed_count: int = 0;
    has visited_ids: list = [];
    has release_ready: bool = True;
    has trace: list = [];

    can start with Root entry {
        visit [-->];
    }

    can walk_stage with Stage entry {
        already = False;
        for nid in self.visited_ids {
            if nid == here.jid {
                already = True;
            }
        }
        if already {
            disengage;
        }
        self.visited_ids.append(here.jid);
        status = "OK" if here.complete else "PENDING";
        self.trace.append(f"[day {here.day}] {here.title} -> {status}");
        if not here.complete {
            self.release_ready = False;
        }
        visit [-->];
    }

    can walk_artifact with Artifact entry {
        if here.sealed {
            self.trace.append(f"  evidence: {here.kind}/{here.title} SEALED");
            self.passed_count += 1;
        } else {
            self.trace.append(f"  evidence: {here.kind}/{here.title} unsealed");
        }
        visit [-->];
    }

    can walk_control with Control entry {
        if here.passed {
            self.trace.append(f"  gate PASS: {here.title}");
            self.passed_count += 1;
        } else {
            self.trace.append(f"  gate FAIL: {here.title}");
            self.release_ready = False;
            self.blocked_count += 1;
        }
        visit [-->];
    }

    can walk_threat with Threat entry {
        if here.severity == "critical" {
            self.trace.append(f"  THREAT critical: {here.title}");
            self.release_ready = False;
            self.blocked_count += 1;
        } else {
            self.trace.append(f"  threat noted: {here.title}");
        }
        visit [-->];
    }
}

# ── Cycle-policy walker: detects cycles among Follows edges (no built-in
#    once-per-node dedupe in jac 0.36, so the guard is explicit). ──────────
walker CycleDetector {
    has path: list = [];
    has cycle_found: bool = False;

    can start with Root entry {
