The issue: import statements were modeled as full-blown Elements and got
embedded alongside real Parts/Requirements, polluting vector-search
resolution. The idiomatic fix: imports are NOT nodes at all — they live
as a list on the importing Package, so embedding/traversal code that
walks nodes never even sees them.
"""

node Package {
    has name: str = "";
    has doc: str | None = None;
    # Unresolved import paths — recorded but not modeled as nodes.
    # This matches the "unresolved, just recorded" framing in CLAUDE.md.
    has imports: list[str] = [];
}

node Element {
    has kind: str = "";
    has name: str = "";
    has qualified_name: str = "";
    has doc: str | None = None;
}

node PartDefinition(Element) {
    has kind: str = "PartDefinition";
}

node RequirementDefinition(Element) {
    has kind: str = "RequirementDefinition";
}

# Package CONTAINS its real elements.
edge Contains { }

