def element_text(elem: Element) -> str {
    return f"{elem.kind} - {elem.name}";
}

def package_text(pkg: Package) -> str {
    # Imports intentionally excluded: they are not part of the search
    # index. An import path can collide with a real element name without
    # ever winning a vector-search match.
