Issue #23: Add local source packages referenced by manifest

## Overview

Add a lightweight local source-package concept to the CX build system: projects can reference package manifests from a root `cx.toml`, and those packages contribute source files to the build without introducing a registry or binary package format.

## Proposed manifest model

Root `cx.toml` references package manifests directly:

```toml
name = "app"
sources = ["src"]
packages = [
  "packages/php/php.toml",
  "../shared/logging/logging.toml",
]
```

A package manifest is location-independent and resolves all paths relative to itself:

```toml
name = "php"
version = "0.1.0"
sources = ["src"]
packages = ["../common/common.toml"]
```

- Packages contribute source files only. The root project continues to own build kind, output, compiler/linker options, and entry points.
- CX `module`/`import` semantics remain responsible for symbol visibility.

## Use Cases

- Reusable source-distribution units so projects can compose source trees instead of copying library files or listing every external source path directly.
- Consume a package unchanged (e.g., PHP bindings) from the demo project.

## Initial scope

- Parse a `packages` array from manifests.
- Resolve package-manifest paths relative to the declaring manifest.
- Recursively load transitive source packages.
- Resolve each package's `sources` and exclusions relative to that package manifest.
- Canonicalize manifest paths and load each package once.
- Diagnose package-reference cycles with the reference chain.
- Diagnose conflicting package names/manifests.
- Merge package sources into normal compiler input without changing module semantics.
- Include package sources in build, check, test, transpile, and language-server project loading.
- Add manifest-loader and end-to-end integration tests.
- Extract the PHP binding experiment into a package and consume it unchanged from the demo.

## Deferred

- Remote registries/downloads
- Version solving or lock files
- Binary packages
- Package aliases
- Package-controlled build/output/linker settings

Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.

```jac
"""Local source-package resolver for the CX build system.

Models the issue's manifest graph: a root project references package
manifests, each of which may reference further packages. A walker
recursively loads transitive packages over typed ``References`` edges,
detects cycles and duplicate package names, and emits a single exit
``report`` describing every resolved package with its sources.
"""

node Manifest {
    has name: str = "";
    has sources: list[str] = [];
    has base_dir: str = ".";
}

node Package {
    has name: str = "";
    has version: str = "0.0.0";
    has sources: list[str] = [];
    has base_dir: str = ".";
}

edge References {
    has rel_path: str = "";
}

walker Loader {
    has chain: list[str] = [];
    has seen_manifests: list[str] = [];
    has seen_names: list[str] = [];
    has resolved: list[str] = [];

    can start with Root entry {
        self.chain = [];
        self.seen_manifests = [];
        self.seen_names = [];
        self.resolved = [];
        visit [-->];
    }

    can load_root with Manifest entry {
        print(f"root project: {here.name} sources={here.sources}");
        self.chain = self.chain + [here.name];
        visit [->:References:->];
    }

    can load_pkg with Package entry {
        # Cycle detection: if this package's manifest path was already
        # seen along the chain, we have a cycle.
        manifest_key = f"{here.base_dir}::{here.name}";
        if manifest_key in self.seen_manifests {
            cycle = self.chain + [here.name];
            print(f"CYCLE detected: {' -> '.join(cycle)}");
            disengage;
        }

        # Conflicting package name detection: if a different package
        # already claimed this name, that is a conflict.
        if here.name in self.seen_names {
            count = 0;
            for n in self.seen_names {
                if n == here.name {
                    count = count + 1;
                }
            }
            if count > 0 {
                print(f"CONFLICT: package name '{here.name}' already loaded");
                disengage;
            }
        }

        # Otherwise, resolve the package: record it and continue.
        self.seen_manifests = self.seen_manifests + [manifest_key];
        self.seen_names = self.seen_names + [here.name];
        label = f"{here.name}@{here.version} (sources={here.sources})";
        self.resolved = self.resolved + [label];
        print(f"resolved package: {label}");

        self.chain = self.chain + [here.name];
        visit [->:References:->] else {
            # Dead end after recording this leaf package.
            self.chain = self.chain[:-1] if len(self.chain) > 0 else [];
            disengage;
        };
    }

    can descend with Package entry {
        # Returning from a child traversal: pop the chain.
        self.chain = self.chain[:-1] if len(self.chain) > 0 else [];
        visit [-->];
    }
}

walker Summary {
    can start with Root entry {
        print("--- resolution summary ---");
        visit [-->];
    }

    can summarize with Manifest entry {
        print(f"project '{here.name}' is built on top of these packages");
        visit [->:References:->];
    }

    can count with Package entry {
        # Traversal falls through to Loader.load_pkg via the same
        # union ability, so we just continue.
        visit [-->];
    }
}

with entry {
    # Root manifest: the demo "app" project.
    app = Manifest(name="app", sources=["src"], base_dir=".");

    # Package manifests form a small DAG with one branch that would
    # cycle if we re-entered through "common".
    php_pkg = Package(name="php", version="0.1.0",
                      sources=["src/php"], base_dir="packages/php");
    logging_pkg = Package(name="logging", version="0.2.0",
                          sources=["src/logging"], base_dir="../shared/logging");
    common_pkg = Package(name="common", version="0.0.1",
                         sources=["src/common"], base_dir="packages/common");
    extras_pkg = Package(name="extras", version="0.0.1",
                         sources=["src/extras"], base_dir="packages/extras");

    # Another logging package at a different path: same name, different
    # location. The loader should flag the conflict.
    alt_logging = Package(name="logging", version="0.3.0",
                          sources=["src/alt_logging"],
                          base_dir="../other/logging");

    # Wire the reference graph with typed References edges whose
    # ``rel_path`` payload mirrors the manifest's ``packages`` entry.
    app +>:References(rel_path="packages/php/php.toml"):+> php_pkg;
    app +>:References(rel_path="../shared/logging/logging.toml"):+> logging_pkg;
    app +>:References(rel_path="../other/logging/logging.toml"):+> alt_logging;
    php_pkg +>:References(rel_path="../common/common.toml"):+> common_pkg;
    logging_pkg +>:References(rel_path="../common/common.toml"):+> common_pkg;
    common_pkg +>:References(rel_path="../extras/extras.toml"):+> extras_pkg;

    # This edge deliberately closes a cycle back to ``logging`` so the
    # loader's cycle guard has something real to catch.
    extras_pkg +>:References(rel_path="../logging/logging.toml"):+> logging_pkg;

    root ++> app;
    print("=== first pass: recursive resolution ===");
    root spawn Loader();
    print("=== second pass: summary walk ===");
    root spawn Summary();
}
```

