"""Knowledge graph evaluation for WISPACE retrieval (roadmap issue #412).

Models the discovery task: a small knowledge graph of Concept, Skill,
Prerequisite, and Source nodes connected by typed edges (PREREQUISITE,
SOURCED_FROM). A walker (GraphAuditor) traverses the graph to evaluate
retrieval use cases, walking prerequisites, detecting cycles, and
emitting a single report. Retrieved graph content is treated as
untrusted and never overrides learner facts.
"""

# ── Entity archetypes ───────────────────────────────────────────────
node Concept {
    has title: str = "";
    has description: str = "";
    has confidence: float = 0.0;
    has stale: bool = False;
}

node Skill {
    has name: str = "";
    has difficulty: int = 0;
}

node Source {
    has url: str = "";
    has version: str = "";
    has trust: float = 0.0;
}

# ── Typed edges (relationships carry meaning) ───────────────────────
edge Prerequisite {
    has weight: float = 1.0;
}

edge SourcedFrom {
    has retrieved_at: str = "";
}

# ── Walker: evaluates graph retrieval, detects cycles, reports ──────
walker GraphAuditor {
    has report_lines: list[str] = [];
    has visited_ids: set[str] = set();
    has max_depth: int = 8;

    can start with Root entry {
        self.report_lines.append("=== Graph retrieval evaluation ===");
        self.report_lines.append("Treating retrieved content as UNTRUSTED.");
        visit [-->];
    }

    can audit with Concept entry {
        # Cycle guard: explicit visited set (jac 0.36 walkers have no
        # built-in dedup).
        key = here.title;
        if key in self.visited_ids {
            self.report_lines.append(f"[CYCLE] revisited {key}");
            disengage;
        }
        self.visited_ids.add(key);
        if self.max_depth <= 0 {
            self.report_lines.append("[DEPTH-LIMIT] pruning walk");
            disengage;
        }

        # Invalidate stale entries (cascade invalidation semantics).
        if here.stale {
            self.report_lines.append(f"[STALE] skipping {here.title}");
            visit [-->];
        } else {
            tag = "OK" if here.confidence >= 0.5 else "LOW-CONF";
            self.report_lines.append(f"[{tag}] concept {here.title} c={here.confidence}");
        }

        # Walk prerequisites only (typed edge traversal).
        visit [->:Prerequisite:->];
    }

    can audit_skill with Skill entry {
        self.report_lines.append(f"[SKILL] {here.name} d={here.difficulty}");
        visit [-->];
    }

    can audit_source with Source entry {
        self.report_lines.append(f"[SOURCE] {here.url} v={here.version} trust={here.trust}");
        visit [-->];
    }

    # Fallback when frontier is empty.
    can dead_end with Concept | Skill | Source entry {
        disengage;
    }

    can finish with Root entry {
        # Single exit report.
        for (i, line) in enumerate(self.report_lines) {
            print(line);
        }
    }
}

# ── Demo wiring ─────────────────────────────────────────────────────
with entry {
    # Source of truth for the knowledge snippets.
    src1 = Source(url="docs://algebra.md", version="1.0", trust=0.9);
    src2 = Source(url="docs://calculus.md", version="2.1", trust=0.8);

    # Core concepts with prerequisites (typed Prerequisite edges).
    algebra = Concept(title="algebra", confidence=0.95);
    calculus = Concept(title="calculus", confidence=0.9);
    analysis = Concept(title="real-analysis", confidence=0.7, stale=True);

    # Skills linked to concepts.
    algebra_skill = Skill(name="solve-equations", difficulty=2);
    calculus_skill = Skill(name="differentiate", difficulty=4);

    # Wire the graph.
    root ++> algebra ++> calculus ++> analysis;
    root ++> algebra_skill ++> calculus_skill;

    # Typed prerequisite edges (weight = difficulty of jump).
    algebra +>:Prerequisite(weight=1.0):+> analysis;
    algebra +>:Prerequisite(weight=0.8):+> calculus;

    # SourcedFrom edges carry retrieval provenance.
    algebra +>:SourcedFrom(retrieved_at="2026-01-15"):+> src1;
    calculus +>:SourcedFrom(retrieved_at="2026-01-15"):+> src2;

    # Cycle: analysis points back to algebra (will trip guard).
    analysis +>:Prerequisite(weight=0.5):+> algebra;

    # Spawn the auditor on the root.
    root spawn GraphAuditor(max_depth=6);
}
```

