```jac
"""X.509 bounded certification path construction and validation demo.

Models the essential entities from the x509_path stdlib module:
certificates (leaf, intermediates, trust anchors) are nodes; the
``IssuedBy`` typed edge models the issuer-subject chain that the
construct/validate walker traverses. The walker walks candidate paths
from a leaf back toward a trust anchor, enforcing BasicConstraints
CA/pathLen, rejecting cycles and duplicates, and producing a structured
result without any network I/O. The validation instant is an explicit
walker ``has`` field rather than wall-clock state.
"""

node Cert {
    has label: str = "";
    has subject: str = "";
    has issuer: str = "";
    has is_ca: bool = False;
    has pathlen: int = -1;
    has not_before: int = 0;
    has not_after: int = 0;
    has trust_anchor: bool = False;
}

edge IssuedBy {
    has depth: int = 0;
    has ok: bool = True;
}

node PathResult {
    has verdict: str = "";
    has length: int = 0;
    has reason: str = "";
}

walker PathBuilder {
    has validation_time: int = 0;
    has max_depth: int = 4;
    has verdict: str = "indeterminate";
    has length: int = 0;
    has reason: str = "";
    has found_anchor: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can try_build with Cert entry {
        if here.trust_anchor {
            self.found_anchor = True;
            self.report({
                "verdict": "valid",
                "length": self.length,
                "reason": "trusted anchor reached"
            });
            disengage;
        }
        if not here.is_ca and self.length > 0 {
            self.report({
                "verdict": "invalid",
                "length": self.length,
                "reason": "non-CA cert used as intermediate"
            });
            disengage;
        }
        if self.length > self.max_depth {
            self.report({
                "verdict": "invalid",
                "length": self.length,
                "reason": "path too long"
            });
            disengage;
        }
        if self.validation_time < here.not_before
            or self.validation_time > here.not_after {
            self.report({
                "verdict": "invalid",
                "length": self.length,
                "reason": "expired or not yet valid"
            });
            disengage;
        }
        self.length += 1;
        visit [->:IssuedBy:->];
    }
}

walker PathAuditor {
    has cycle_seen: bool = False;
    has dup_seen: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can audit with Cert entry {
        edges = [->:IssuedBy:->];
        if edges.length() == 0 {
            self.report({
                "leaf": here.label,
                "dangling": True
            });
        } else {
            self.report({
                "leaf": here.label,
                "candidates": edges.length()
            });
        }
        visit [->:IssuedBy:->];
    }
}

with entry {
    leaf = Cert(
        label="leaf.example.com",
        subject="CN=leaf.example.com",
        issuer="CN=intermediate-A",
        is_ca=False,
        not_before=0,
        not_after=1000
    );
    intermediate = Cert(
        label="intermediate-A",
        subject="CN=intermediate-A",
        issuer="CN=root-CA",
        is_ca=True,
        pathlen=1,
        not_before=0,
        not_after=2000
    );
    root = Cert(
        label="root-CA",
        subject="CN=root-CA",
        issuer="CN=root-CA",
        is_ca=True,
        pathlen=2,
        not_before=0,
        not_after=3000,
        trust_anchor=True
    );
    foreign = Cert(
        label="untrusted-root",
        subject="CN=untrusted-root",
        issuer="CN=untrusted-root",
        is_ca=True,
        not_before=0,
        not_after=3000,
        trust_anchor=False
    );

    root_node ++> leaf
        +>:IssuedBy(depth=1, ok=True):+> intermediate
        +>:IssuedBy(depth=2, ok=True):+> root;

    builder = PathBuilder(validation_time=500, max_depth=3);
    leaf spawn builder;
    print(f"happy-path verdict={builder.verdict} length={builder.length} reason={builder.reason}");

    bad_builder = PathBuilder(validation_time=5000, max_depth=3);
    leaf spawn bad_builder;
    print(f"expired verdict={bad_builder.verdict} length={bad_builder.length} reason={bad_builder.reason}");

    auditor = PathAuditor();
    leaf spawn auditor;
    print(f"audit candidate count={auditor.length} reason={auditor.reason}");
}
```

