Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.

```jac
"""Performance test policy for complex-dependency nui4 documents.

Models the essential scenario from SAY-31 / Issue #208:
- Documents are nodes; dependencies between documents are typed edges.
- A document carries a list of declared anchors and a manifest of compiled
  outputs that must be invalidated when a dependency is re-evaluated.
- Performance evaluation requires: (1) traversal order of the dependency
  graph, (2) cascade invalidation of downstream artifacts, (3) cycle
  detection that aborts compilation rather than hanging.
- Heavy timing work is opt-in; this demo only models the graph machinery.
"""

node Document {
    has title: str = "";
    has anchors: list[str] = [];
    has compiled: bool = True;
    has invalid: bool = False;
}

edge DependsOn {
    has weight: int = 1;
}

edge Produces {
    has artifact: str = "";
}

walker PerformanceProbe {
    has visited: list[str] = [];
    has order: list[str] = [];
    has cycles: list[str] = [];

    can start with Root entry {
        visit [->:DependsOn:->];
    }

    can traverse with Document entry {
        key = f"{here.title}";
        for v in self.visited {
            if v == key {
                cycle_msg = f"CYCLE detected at {key}";
                self.cycles.append(cycle_msg);
                print(cycle_msg);
                disengage;
            }
        }
        self.visited.append(key);
        self.order.append(key);

        if here.invalid {
            invalidate_msg = f"invalidating downstream of {key}";
            print(invalidate_msg);
        }

        visit [->:DependsOn:->];
    }
}

walker CascadeInvalidator {
    has targets: list[str] = [];
    can start with Root entry {
        visit [->:DependsOn:->];
    }
    can invalidate with Document entry {
        here.invalid = True;
        here.compiled = False;
        self.targets.append(here.title);
        print(f"[INVALID] {here.title} cleared {len(here.anchors)} anchors");
        visit [->:DependsOn:->];
    }
}

with entry {
    a = Document(title="A", anchors=["#hdr-a"], compiled=True);
    b = Document(title="B", anchors=["#hdr-b1", "#hdr-b2"], compiled=True);
    c = Document(title="C", anchors=["#hdr-c"], compiled=True);
    d = Document(title="D", anchors=["#hdr-d"], compiled=True);

    root +>:DependsOn(weight=2):+> a;
    a +>:DependsOn(weight=1):+> b;
    b +>:DependsOn(weight=1):+> c;
    c +>:DependsOn(weight=3):+> d;
    d +>:DependsOn(weight=1):+> b;

    a +>:Produces(artifact="compiled/a.bin"):+> a;
    b +>:Produces(artifact="compiled/b.bin"):+> b;

    print("--- PerformanceProbe (cycle-safe traversal) ---");
    probe = PerformanceProbe();
    root spawn probe;
    print(f"visit order: {probe.order}");
    print(f"cycles seen: {probe.cycles}");

    print("--- CascadeInvalidator (downstream invalidation) ---");
    cascade = CascadeInvalidator();
    root spawn cascade;
    print(f"invalidated: {cascade.targets}");
}
```

