```jac
"""Project dashboard demo with typed relationships and bounded graph traversal."""

node Project {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has project_name: str = "";
}

node Cycle {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has stage: str = "HISTORICAL";
}

node Action {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has owner: str = "";
    has due_date: str | None = None;
    has status: str = "DRAFT";
    has confirmed: bool = False;
}

edge ContainsCycle { }
edge OriginatesAction { }
edge DependsOn { }

walker DashboardWalker {
    has viewer: str = "";
    has hop_budget: int = 12;
    has open_count: int = 0;

    can begin with Root entry {
        visit [-->] else { disengage; }
    }

    can inspect_project with Project entry {
        print(f"Project dashboard: {here.project_name}");
        visit [->:ContainsCycle:->] else { disengage; }
    }

    can inspect_cycle with Cycle entry {
        print(f"Cycle: {here.title} [{here.stage}]");
        if (self.hop_budget <= 0) {
            print("Traversal stopped at the cycle-safety limit");
            disengage;
        } else {
            self.hop_budget -= 1;
            visit [->:OriginatesAction:->] else { disengage; }
        }
    }

    can inspect_action with Action entry {
        if (here.status == "OPEN" && here.confirmed) {
            self.open_count += 1;
            if (here.due_date is None) {
                print(f"OPEN action: {here.title} | owner={here.owner} | due=undated");
            } else {
                print(f"OPEN action: {here.title} | owner={here.owner} | due={here.due_date}");
            }
        }

        if (self.hop_budget <= 0) {
            print("Traversal stopped while following action dependencies");
            disengage;
        } else {
            self.hop_budget -= 1;
            visit [->:DependsOn:->] else { disengage; }
        }
    }
}

with entry {
    project = Project(
        project_name="Retro Loop",
        title="Retro Loop dashboard",
        year=2025
    );
    collecting = Cycle(
        title="Current collection",
        stage="COLLECTING",
        year=2025
    );
    discussion = Cycle(
        title="Previous discussion",
        stage="DISCUSS",
        year=2025
    );

    draft = Action(
        title="Draft action excluded from dashboard",
        owner="member-2",
        status="DRAFT",
        confirmed=False
    );
    open_action = Action(
        title="Publish the project summary",
        owner="member-7",
        due_date="2025-06-20",
        status="OPEN",
        confirmed=True
    );
    carried_action = Action(
        title="Review recurring feedback",
        owner="member-4",
        status="OPEN",
        confirmed=True
    );
    done_action = Action(
        title="Archive the old board",
        owner="member-3",
        status="DONE",
        confirmed=True
    );

    root ++> project;
    project +>:ContainsCycle:+> collecting;
    project +>:ContainsCycle:+> discussion;

    collecting +>:OriginatesAction:+> draft;
    collecting +>:OriginatesAction:+> open_action;
    discussion +>:OriginatesAction:+> carried_action;
    discussion +>:OriginatesAction:+> done_action;

    open_action +>:DependsOn:+> carried_action;
    carried_action +>:DependsOn:+> open_action;

    root spawn DashboardWalker(viewer="member-7", hop_budget=10);
}
