"""Bug tracker: connect-and-grab ticket creation via walrus assignment."""

node Ticket {
    has title: str = "";
    has priority: str = "low";
    has available: bool = True;
}

walker Triage {
    has label: str = "Default";

    can start with Root entry {
        print(f"Filing tickets for {self.label} project");
        visit [-->];
