Task:
A maintainer on the project maheshsingh20/YumDee-MCP-Studio (TypeScript) filed this issue about hand-rolled graph machinery causing pain:

Issue #3: [FEATURE] Implement LocalJsonStorage for persistent session files

## Describe the Feature

Implement LocalJsonStorage in packages/core/src/storage/index.ts to persist McpSession objects as JSON files under ~/.mcp-studio/sessions/.

## Why is This Needed?

InMemoryStorage loses all recorded sessions on process restart. Without persistent storage, users cannot replay sessions, run regression tests, or browse session history in the Inspector UI.

## Proposed Solution

- Expand ~ to the OS home directory using os.homedir()
- Create the base directory if it does not exist (fs.mkdirSync with recursive)
- save(): write session as <id>.json with JSON.stringify
- load(): read and parse <id>.json, validate with McpSessionSchema
- list(): glob *.json, parse each, apply filter (serverName, tags, date range)
- delete(): fs.unlink the file
- update(): load, merge updates, save back
- export(): load and return JSON or JSONL string

## Alternatives Considered

SQLite gives better query performance (tracked in a separate issue), but JSON files are zero-dependency and sufficient for v1.

## Additional Context

Default path should be ~/.mcp-studio/sessions/ with an option to override via constructor argument.

Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.

```jac
"""Local session storage demo using typed edges and a bounded audit walker."""

node SessionStore {
    has title: str = "Local session store";
    has year: int = 0;
    has available: bool = True;
    has expanded_path: str = "~/.mcp-studio/sessions/";
}

node McpServer {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has name: str = "";
    has version: str = "";
}

node McpSession {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has session_id: str = "";
    has server_name: str = "";
    has file_name: str = "";
    has tags: str = "";
    has started_at: int = 0;
}

node SessionEntry {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has sequence: int = 0;
    has kind: str = "";
    has payload: str = "";
}

edge RegistersServer { }
edge HostsSession { }
edge ContainsEntry { }

walker SessionAuditor {
    has max_hops: int = 8;
    has hops: int = 0;
    has session_count: int = 0;
    has entry_count: int = 0;

    can start with Root entry {
        print("Starting local session storage audit");
        visit [-->] else {
            disengage;
        }
    }

    can inspect with SessionStore entry {
        print(f"Storage path: {here.expanded_path}");
        if self.hops >= self.max_hops {
            print("Traversal limit reached at storage root");
            disengage;
        }
        self.hops += 1;
        visit [->:RegistersServer:->] else {
            disengage;
        }
        self.hops -= 1;
    }

    can inspect with McpServer entry {
        print(f"Server: {here.name} ({here.version})");
        if self.hops >= self.max_hops {
            print("Traversal limit reached at server");
            disengage;
        }
        self.hops += 1;
        visit [->:HostsSession:->] else {
            disengage;
        }
        self.hops -= 1;
    }

    can inspect with McpSession entry {
        self.session_count += 1;
        status = "valid" if here.available else "invalidated";
        print(f"Session {here.session_id}: {status}, tags={here.tags}");

        if self.hops >= self.max_hops {
            print(f"Traversal limit reached at session {here.session_id}");
            disengage;
        }
        self.hops += 1;
        visit [->:ContainsEntry:->] else {
            disengage;
        }
        self.hops -= 1;
    }

    can inspect with SessionEntry entry {
        self.entry_count += 1;
        print(f"  entry {here.sequence}: {here.kind} -> {here.payload}");
    }
}

with entry {
    store = SessionStore(expanded_path="~/.mcp-studio/sessions/");

    server = McpServer(
        name="demo-server",
        version="1.0.0"
    );

    first = McpSession(
        session_id="sess-001",
        server_name="demo-server",
        file_name="sess-001.json",
        tags="regression,inspector",
        started_at=20250101
    );

    second = McpSession(
        session_id="sess-002",
        server_name="demo-server",
        file_name="sess-002.json",
        tags="failed-replay",
        started_at=20250102,
        available=False
    );

    first_request = SessionEntry(
        sequence=1,
        kind="request",
        payload="tools/list"
    );

    first_response = SessionEntry(
        sequence=2,
        kind="response",
        payload="200 OK"
    );

    second_request = SessionEntry(
        sequence=1,
        kind="request",
        payload="resources/read"
    );

    root ++> store;
    store +>:RegistersServer:+> server;
    server +>:HostsSession:+> first;
    server +>:HostsSession:+> second;
    first +>:ContainsEntry:+> first_request;
    first +>:ContainsEntry:+> first_response;
    second +>:ContainsEntry:+> second_request;

    auditor = SessionAuditor(max_hops=8);
    root spawn auditor;

    print(f"Audited {auditor.session_count} sessions and "
          f"{auditor.entry_count} stored entries");
}
```

