```jac
"""Multi-user deployment layout inspector.

Walks the deployment graph from each root, tallies direct children by node
type, and reports the single-served-root invariant (one root outside the
served environment plus one root per served user).
"""

node User {
    has username: str = "";
}

node Workspace {
    has label: str = "";
}

node Served {
    has region: str = "";
}

edge Owns { has since: str = ""; }

walker LayoutAuditor {
    has user_counts: dict = {};
    has workspace_counts: dict = {};
    has served_roots: int = 0;
    has free_roots: int = 0;

    can start with Root entry {
        # Walk every edge group; the typed trigger below handles nodes.
        visit [-->];
    }

    can audit with Root | User | Workspace | Served entry {
        kind_name = type(here).__name__;
        if kind_name == "Root" {
            # Count this root by whether it sits inside a served region.
            served_parent = here-->[?:Served];
            if served_parent {
                self.served_roots += 1;
            } else {
                self.free_roots += 1;
            }
        } elif kind_name == "User" {
            current = self.user_counts.get(kind_name, 0);
            self.user_counts[kind_name] = current + 1;
        } elif kind_name == "Workspace" {
            current = self.workspace_counts.get(kind_name, 0);
            self.workspace_counts[kind_name] = current + 1;
        }
        visit [-->];
    }
}

with entry {
