```jac
"""Component graph linter — traverse the import graph of `shell/components/graph/`,
flag orphan components, and report which ones are safe to delete.

Models the dead-code detection scenario from issue #52 of cnotv/dashboard:
- Four Vue component files have zero in-repo importers and should be removed.
- Two component files have importers and must be kept.
A walker sweeps the import graph starting from a file the user knows is
"live" (it is imported elsewhere) and reports the unreached orphans.
"""

# ---------- Nodes: file archetypes ----------

node ComponentFile {
    has path: str = "";
    has kind: str = "";          # "live" or "orphan"
}

# ---------- Typed edges: the relationships between files ----------

edge Imports { }                 # a --Imports--> b  means  "a imports b"
edge Verifies { }                # control link: a live component is verified to import b

# ---------- Walkers ----------

walker OrphanHunter {
    has visited_paths: list[str] = [];
    has orphans: list[str] = [];

    # Seed from Root: start at every component in the graph directory.
    can start with Root entry {
        self.visited_paths = [];
        self.orphans = [];
        visit [-->];
    }

    # When we step onto any ComponentFile, traverse its outgoing imports.
    can crawl with ComponentFile entry {
        already = False;
        for p in self.visited_paths {
            if p == here.path {
                already = True;
            }
        }
        if not already {
            self.visited_paths.append(here.path);
            visit [->:Imports:->];
        } else {
            visit [-->];
        }
    }

    # Once the front is exhausted, do the orphan audit.
    can audit with Root entry {
        # Re-collect every ComponentFile still in the graph (Jac has no
        # built-in graph enumeration helper we can rely on portably, so
        # the seeded list is what we audit against; the demo wires it up
        # explicitly below).
        # Dead-end branch: nothing more to visit.
        self.orphans = self.visited_paths;
    }
}

walker DependencyAuditor {
    # Walks the import chain starting from a known-live component to
    # confirm the transitive closure that the importer is reachable.
    can start with Root entry {
        print(f"[audit] starting from a known-live component");
        visit [-->];
    }

    can follow with ComponentFile entry {
        status = "LIVE" if here.kind == "live" else "ORPHAN";
        print(f"[audit] visiting {here.path} ({status})");
        visit [->:Imports:->];
    }

    can follow_via_verify with ComponentFile entry {
        # Alternate path that uses a different edge kind, demonstrating
        # that typed edges disambiguate traversal.
        print(f"[audit] (verify) {here.path}");
        visit [->:Verifies:->];
    }
}

# ---------- Demonstration wiring ----------

with entry {
