        visit [-->] else { disengage; }
    }

    can fallback with Reel entry {
        self.total += 1;
        self.default_count += 1;
        print(f"[DEFAULT] {here.title} (reel, {here.format}) — unclassified");
        visit [-->] else { disengage; }
    }
}

