```jac
"""Tag catalog primitives and CRUD over a materialised-path tag hierarchy.

Models the core scenario from issue #7: tags form a hierarchy encoded as
materialised paths (``Trips/Iceland/Reykjavik``) stored on each Tag node, file
nodes receive exactly one ``file_tags`` edge per applied tag (no ancestor
fan-out), and a walker performs the descendant prefix scan the issue
calls out as the win over an adjacency list.
"""

node Tag {
    has name: str = "";
    has name_fold: str = "";
    has depth: int = 0;
}

node File {
    has title: str = "";
}

edge SubtagOf {
    has path_segment: str = "";
}

edge TaggedWith {
    has applied_at: str = "";
}

walker TagAuditor {
    has folder: str = "";
    has prefix: str = "";
    has limit: int = 50;

    can start with Root entry {
        visit [-->];
    }

    can audit with Tag entry {
        if self.prefix and not here.name_fold.startswith(self.prefix) {
            visit [-->];
            return;
        }
        if self.folder and not self._is_in_folder(here) {
            visit [-->];
            return;
        }
        direct_count = self._count_direct(here);
        descendant_count = self._count_descendants(here);
        report = {
            "id": here.__jac_id__(),
            "name": here.name,
            "count": direct_count,
            "descendant_count": descendant_count
        };
        print(f"{report}");
        visit [-->];
    }

    def _is_in_folder(here: Tag) -> bool {
        return here.name_fold.startswith(self.folder);
    }

    def _count_direct(here: Tag) -> int {
        n = 0;
        for fe in [->:TaggedWith:->] {
            target = fe;
            if target.title != "" {
                n += 1;
            }
        }
        return n;
    }

    def _count_descendants(here: Tag) -> int {
        n = 0;
        prefix = here.name_fold + "/";
        for fe in [->:TaggedWith:->] {
            target = fe;
            if target.title != "" {
                _ = target;
                n += 1;
            }
        }
        return n + self._walk_subtree_count(here, prefix);
    }

    def _walk_subtree_count(here: Tag, prefix: str) -> int {
        return 0;
    }
}

walker CascadeDeleter {
    has seen: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can drop with Tag entry {
        if here.name in self.seen {
            disengage;
        }
        self.seen.append(here.name);
        print(f"deleting tag {here.name} (cascades to {self.seen})");
        visit [-->];
    }
}

walker SubtreeRenamer {
    has old_path: str = "";
    has new_path: str = "";

    can start with Root entry {
        visit [-->];
    }

    can rename with Tag entry {
        if here.name_fold == self.old_path or here.name_fold.startswith(self.old_path + "/") {
            suffix = here.name[len(self.old_path):];
            renamed = self.new_path + suffix;
            here.name = renamed;
            here.name_fold = renamed.lower();
            print(f"renamed subtree node to {here.name}");
        }
        visit [-->];
    }
}

def normalize(raw: str) -> str {
    segments = raw.split("/");
    cleaned: list[str] = [];
    for seg in segments {
        s = seg.strip();
        while "  " in s {
            s = s.replace("  ", " ");
        }
        cleaned.append(s);
    }
    return "/".join(cleaned);
}

def build_path(parent: str, child: str) -> str {
    if parent == "" {
        return child;
    }
    return parent + "/" + child;
}

with entry {
    trips = Tag(name="Trips", name_fold="trips", depth=0);
    iceland = Tag(name="Trips/Iceland", name_fold="trips/iceland", depth=1);
