"""Moderation sweep over game accounts.

Member accounts are audited normally, admin accounts get their
reputation boosted by 5, and the welcome desk greets every bot passing
through no matter what kind of walker it is.
"""

node Account {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Member(Account) {
    has reputation: int = 0;
    has violation_count: int = 0;

    def audit() -> str {
        verdict = "CLEAN" if here.violation_count == 0 else "FLAGGED";
        return f"[{verdict}] member {here.title} rep={here.reputation}";
    }
}

node Admin(Account) {
    has reputation: int = 0;
    has violation_count: int = 0;

    def audit() -> str {
        boosted = here.reputation + 5;
        verdict = "CLEAN" if here.violation_count == 0 else "FLAGGED";
        return f"[{verdict}] admin {here.title} rep={boosted} (boosted +5)";
    }
}

