    can sweep with WelcomeDesk | Member | Admin entry {
        if here instanceof WelcomeDesk {
            visit [-->];
        } else {
            print(here.audit());
            visit [-->];
        }
    }
}

walker Greeter {
    has kind: str = "greeter";
