    has name: str = "";
    has refs: list = [];

    def add_ref(target) -> None {
        self.refs.append(target);
    }
}

node BusinessRegistryConfig {
    has name: str = "";
    has refs: list = [];

    def add_ref(target) -> None {
        self.refs.append(target);
    }
}

# Typed edge whose meaning is "this schema references that schema".
# Empty payload is fine — the relationship itself carries meaning.
edge References { }

walker CycleDetector {
    has visited_ids: list = [];
    has cycle_found: bool = False;
    has depth: int = 0;

    can start with Root entry {
