    # Two mutually recursive schemas: each holds a typed-edge
    # reference to the other, exactly like the OpenAPI generator
    # problem the issue describes.
    api = ApiConfig(name="ApiConfigurationRead");
    biz = BusinessRegistryConfig(name="BusinessRegistryConfigurationRead");

