    biz +>:References:+> api;

    # A non-cyclic sibling chain, so the walker has something to walk
    # past too (mirrors the wider spec the user was generating).
    lone = BusinessRegistryConfig(name="LoneConfig");
    biz +>:References:+> lone;

    root ++> api;
    root ++> biz;
    root ++> lone;

    detector = CycleDetector();
    root spawn detector;

    if detector.cycle_found {
        print(f"result: cycle present; "
              f"order traversed = {detector.visited_ids}; "
