    can audit_partition with Partitions entry {
        gate_here = [g for g in [-->](?:RenderGate)][0] if [g for g in [-->](?:RenderGate)] else None;
        print(f"partition: total={here.total} raster={here.raster_len} tail={here.tail_len}");
        if gate_here is not None {
            actual_branch = "PARALLEL" if here.raster_len >= gate_here.threshold else "SERIAL";
            claimed_branch = gate_here.branch_taken;
            ok = "ok" if actual_branch == claimed_branch else "MISMATCH";
            print(f"  gate={gate_here.gate_name} threshold={gate_here.threshold} "
                  f"branch={actual_branch} (claimed={claimed_branch}) [{ok}]");
        }
        visit [-->];
    }

    can audit_metric with AuditedBy entry {
        if here.measured_total != 0 {
            self.missing_columns.append(here.metric_name);
            print(f"  recorded metric '{here.metric_name}'={here.measured_total} "
                  f"measures whole array, NOT raster prefix");
        }
        visit [-->];
    }

    can review_gate with RenderGate entry {
        print(f"gate '{here.gate_name}' threshold={here.threshold} "
              f"branch_taken='{here.branch_taken}' (unfalsifiable from bench)");
        visit [-->];
    }
}

with entry {
    root ++> RenderGate(gate_name="DRAW_SORT_PARALLEL", threshold=3000, branch_taken="PARALLEL");

    gate = [g for g in [-->](?:RenderGate)][0];
    cmds = [];
    for i in range(500) {
        cull_flag = True if i < 150 else False;
        cmds.append(DrawCommand(label=f"d{i}", cull=cull_flag));
    }
    for c in cmds {
