```jac
"""Toll plaza collector for gate G-4: cars pay $2.50, trucks pay $2.50 plus
50 cents per ton, motorcycles pay $1.00. The TollTaker walker sweeps the
queue, prints one payment line per vehicle, and reports total revenue."""

node Vehicle {
    has kind: str = "";
    has tons: float = 0.0;
}

walker TollTaker {
    has gate: str = "G-4";
    has revenue: float = 0.0;

    can start with Root entry {
        print(f"Gate {self.gate} is open. Collecting tolls...");
        visit [-->] else { disengage; }
    }

    can collect with Vehicle entry {
        charged = self.charge(here.kind, here.tons);
        self.revenue += charged;
        if here.kind == "truck" {
            print(f"  truck ({here.tons} tons): ${charged:.2f}");
        } elif here.kind == "car" {
            print(f"  car: ${charged:.2f}");
        } else {
            print(f"  motorcycle: ${charged:.2f}");
        }
        visit [-->] else { disengage; }
    }

    def charge(kind: str, tons: float) -> float {
        if kind == "car" {
            return 2.50;
        }
        if kind == "truck" {
            return 2.50 + 0.50 * tons;
        }
        return 1.00;
    }
}

