# Core entity archetypes
node Phase {
    has name: str = "";
    has story_points: int = 0;
}

node Ticket {
    has title: str = "";
    has ticket_id: int = 0;
    has status: str = "open";
    has deliverables: list[str] = [];
}

node Deliverable {
    has name: str = "";
    has completed: bool = False;
}

# Walker that audits a phase: visits its tickets via BelongsTo, then each
# ticket's dependent tickets (DependsOn) and the deliverables (Produces)
# it owns. Detects cycles in the dependency graph explicitly because
# Jac 0.36.1 walkers have no built-in visited-set dedupe.
walker PhaseAuditor {
    has phase_label: str = "";
    has seen: list[int] = [];
    has cycle_found: bool = False;

    can start with Root entry {
        print(f"=== Auditing phase: {self.phase_label} ===");
        visit [-->];
    }

    can audit_phase with Phase entry {
        if here.name != self.phase_label {
            visit [-->];
            return;
        }
        print(f"Phase '{here.name}' [{here.story_points} pts] contains tickets:");
        visit [here->:BelongsTo:->];
    }

    can audit_ticket with Ticket entry {
        tid = here.ticket_id;
        already = False;
        for (i, x) in enumerate(self.seen) {
            if x == tid {
                already = True;
            }
        }
        if already {
            print(f"  [CYCLE] ticket #{tid} revisited via dependency");
            self.cycle_found = True;
            disengage;
        }
        self.seen.append(tid);
        remaining = "";
        deliverable_count = len(here.deliverables);
        last = deliverable_count - 1;
        for (i, d) in enumerate(here.deliverables) {
            done_marker = "x" if here.status == "closed" else " ";
            line = f"  [{done_marker}] {d}";
            if i < last {
                line = line + ",";
            }
            remaining = remaining + line + "\n";
        }
        header = (
            f"  Ticket #{tid}: {here.title} (status={here.status})\n"
            f"  deliverables:\n"
        );
        print(header + remaining + "  depends on:");
        visit [here->:DependsOn:->];
    }

    can list_produced with Deliverable entry {
        marker = "[DONE]" if here.completed else "[TODO]";
        print(f"    {marker} {here.name}");
    }
}

# Walker that closes a deliverable by name, then cascade-invalidates every
# dependent ticket. Demonstrates the cascade-invalidation traversal pattern
# that the issue complains about being hand-rolled in the codebase.
walker DeliverableCompleter {
    has target: str = "";

    can start with Root entry {
        print(f"\n=== Completing deliverable: '{self.target}' ===");
        visit [-->];
    }

    can find_target with Deliverable entry {
        if here.name == self.target {
            here.completed = True;
            print(f"marked '{here.name}' as completed");
            disengage;
        }
        visit [-->];
    }

    can visit_phase with Phase entry {
        visit [here->:BelongsTo:->];
    }

    can visit_ticket with Ticket entry {
        print(f"  invalidating dependents of ticket #{here.ticket_id} '{here.title}'");
        visit [here->:DependsOn:->];
    }
}

