Task:
A maintainer on the project mrilikecoding/llm-orc (unknown) filed this issue about hand-rolled graph machinery causing pain:

Issue #130: Compose-at-runtime primitive (ADR-047's four named gaps; subsumes #79)

Roadmap WS-7 enabling rung (docs/serving-roadmap.md); ADR-047 §Deferred. Built when a flow demonstrably needs a shape the catalog lacks (AS-11), TDD like guard/loop/dispatch.

The four gaps named by the runtime-composition feasibility spike: single-target dispatch; scalar-only ${dep.field} resolver (this is #79); DAG frozen after parse; no runtime-spec → EnsembleConfig path. AS-2 (validate-before-load) admits every materialized sub-DAG; acceptance stays deterministic, never trust-accumulation.

Downstream (not this issue): composer ensembles composing from the registry's validated parts, with the capable-model-composed baseline vs ensemble-composed compose step as the open ADR-047 pillar-c hypothesis.

Exit gate: one ladder task that refuses today runs on a runtime-composed shape and passes its gate.

Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.

```jac
"""Runtime-composed ensemble registry.

Models ADR-047's four named gaps as a graph:
  - SubDAG nodes hold a frozen dependency graph (single-target dispatch,
    scalar-only resolver, parse-time frozen DAG).
  - Validator enforces AS-2 (validate-before-load) before a sub-DAG can be
    admitted into the registry.
  - Composer walks the registry and, when a requested shape is missing,
    materializes one by composing validated parts at runtime.
  - The four gaps appear as typed edges that the composer traverses.

Walks the composer over the registry, prints gap status, and refuses to
admit any sub-DAG that fails validation.
"""

node SubDAG {
    has name: str = "";
    has frozen: bool = True;
    has validated: bool = False;
    has depends_on: list[str] = [];
}

node Validator {
    has gate_name: str = "AS-2";
}

node Composer {
    has requested_shape: str = "";
    has composed: bool = False;
}

node Registry {
    has capacity: int = 16;
}

# Typed edges: each gap from ADR-047 becomes a relationship the composer
# traverses, so the dispatch/resolver/freeze/registry path is the graph.
edge GapSingleTarget {}
edge GapScalarResolver {}
edge GapFrozenDAG {}
edge GapRegistryAdmission {}
edge Validates {}
edge Composes {}
edge PartOf {}

walker Auditor {
    has report: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can audit_subdag with SubDAG entry {
        # Cycle policy: every sub-DAG must be frozen at parse time and
        # validated before it can be admitted. We keep both checks as
        # explicit gates — they are domain logic, not scaffolding.
        line = f"{here.name}: frozen={here.frozen} validated={here.validated}";
        self.report.append(line);
        if not here.frozen {
            self.report.append(f"REJECT {here.name}: DAG not frozen at parse");
            disengage;
        }
        if not here.validated {
            self.report.append(f"REJECT {here.name}: fails AS-2 validate-before-load");
            disengage;
        }
        visit [->:GapFrozenDAG:->];
    }

    can note_gaps with SubDAG entry {
        # The four ADR-047 gaps are reachable from any admitted sub-DAG.
        self.report.append(f"  gap: {here.name} exposes single-target dispatch");
        visit [->:GapSingleTarget:->];
        visit [->:GapScalarResolver:->];
    }

    can audit_validator with Validator entry {
        self.report.append(f"validator {here.gate_name} active");
        visit [->:Validates:->];
    }

    can audit_registry with Registry entry {
        self.report.append(f"registry capacity={here.capacity}");
        visit [->:PartOf:->];
    }

    can audit_composer with Composer entry {
        # The composer composes only from validated parts — that's the
        # trust-accumulation guard. If no part covers the requested
        # shape, refuse to materialize (no runtime spec -> EnsembleConfig
        # path means we stop here, we don't fabricate one).
        self.report.append(f"composer requested: {here.requested_shape}");
        visit [->:Composes:->];
    }
}

with entry {
    # Two validated sub-DAGs, one that fails the freeze gate (DAG mutated
    # after parse) and one that fails AS-2 (admitted without validation).
    # Both must be refused by the auditor.
    dag_a = SubDAG(name="A", frozen=True, validated=True, depends_on=["B"]);
    dag_b = SubDAG(name="B", frozen=True, validated=True, depends_on=[]);
    dag_unfrozen = SubDAG(name="C", frozen=False, validated=True, depends_on=[]);
    dag_unvalidated = SubDAG(name="D", frozen=True, validated=False, depends_on=[]);

    validator = Validator(gate_name="AS-2");
    composer = Composer(requested_shape="compose-at-runtime");
    registry = Registry(capacity=16);

    # Wire the graph: root -> registry -> validator -> sub-DAGs,
    # sub-DAGs expose the four named gaps as typed edges,
    # composer composes from validated parts.
    root ++> registry
        +>:PartOf:+> validator
        +>:Validates:+> dag_a
        +>:Validates:+> dag_b
        +>:Validates:+> dag_unfrozen
        +>:Validates:+> dag_unvalidated;

    dag_a +>:GapFrozenDAG:+> dag_b;
    dag_a +>:GapSingleTarget:+> composer;
    dag_a +>:GapScalarResolver:+> composer;
    dag_b +>:GapFrozenDAG:+> composer;

    # Unvalidated parts are still in the graph but carry no edges into
    # the composer — they cannot compose anything (trust-accumulation
    # guard survives as a structural rule, not a runtime check).
    composer +>:Composes:+> dag_a;
    composer +>:Composes:+> dag_b;

    # Walk the auditor from root. It refuses to follow an unvalidated
    # sub-DAG into the gaps because disengage; fires on rejection.
    auditor = Auditor();
    root spawn auditor;

    for line in auditor.report {
        print(line);
    }
}
