- Do not collect or interpret Gate 0 behavior until #15 resolves the meaning and acceptable accuracy of displayed travel time.
- Do not start mobile tasks from the historical mixed Orca Run.
- Real-time transport, restaurant recommendations, chat, payment, and automatic location remain out of scope unless a later approved issue changes that boundary.
- Execution docs live under `docs/loop` and `docs/runbooks`.
- Coordinator continues through ready implementation tasks and stops at #9, #10, or #11 for real behavior data.


Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.

```jac
"""GatiGo execution loop walker — models the Loop 0 / Loop 1 / Loop 2 DAG,
the gating rule that only a resolved gate unlocks the next loop, and the
holdback that blocks behavioral data collection until #15 resolves."""

node Task {
    has issue_id: int = 0;
    has title: str = "";
    has done: bool = False;
    has in_loop: int = 0;
}

node Gate {
    has gate_id: int = 0;
    has label: str = "";
    has resolved: bool = False;
    has unlocks_loop: int = 0;
}

edge BelongsTo {
    has order: int = 0;
}

edge Blocks {
    has reason: str = "";
}

walker Coordinator {
    has start_loop: int = 0;
    has max_loop: int = 2;
    has stop_at_gate: int = -1;
    has log: list[str] = [];

    can start with Root entry {
        print(f"Coordinator activating at loop {self.start_loop}");
        visit [-->];
    }

    can traverse with Task | Gate entry {
        if self.stop_at_gate != -1 and self._seen_gate >= self.stop_at_gate + 1 {
            # Already stopped at a prior gate this run.
            disengage;
        }
        if self._is_blocked(here) {
            # Loop activation rule: cannot enter a loop whose gate is unresolved.
            # Do not advance through the task; the recursion guard sees this
            # as a dead-end and the walker falls back to disengage below.
            return;
        }
        self._record(here);
        # Recurse via typed edges that carry meaning: BelongsTo (loop membership)
        # and Blocks (gate → next-loop task dependency).
        visit [->:BelongsTo:->];
        visit [->:Blocks:->];
    }

    can finalize with Root entry {
        print("Coordinator report:");
        for line in self.log {
            print(f"  - {line}");
        }
    }

    # ---- helpers (walker-local, but called via self so they're explicit) ----
    def _is_blocked(n: Task | Gate) -> bool {
        # Rule: cannot collect or interpret behavior for a loop whose gate is
        # unresolved. Also: a task in a higher loop than its gate allows is
        # blocked. Tasks in the starting loop are always reachable.
        gate_for_loop = 0;
        if isinstance(n, Task) {
            gate_for_loop = n.in_loop - 1;
            if gate_for_loop < 0 {
                return False;
            }
            # We rely on the walker having visited gates of lower loops first
            # because the gate node itself is connected to its loop's tasks
            # via BelongsTo with the lower loop index. If no gate info has
            # been recorded yet for that loop, we conservatively allow it
            # (the start_loop is the only loop that's free of gate gating).
            if gate_for_loop < self.start_loop {
                return False;
            }
            # Did we already see an unresolved gate for this loop?
            for line in self.log {
                if f"gate #{n.in_loop - 1}" in line and "UNRESOLVED" in line {
                    return True;
                }
            }
            return False;
        }
        return False;
    }

    def _record(n: Task | Gate) -> None {
        if isinstance(n, Task) {
            mark = "DONE" if n.done else "PENDING";
            entry = f"task #{n.issue_id} [{mark}] {n.title} (loop {n.in_loop})";
        } else {
            mark = "RESOLVED" if n.resolved else "UNRESOLVED";
            entry = f"gate #{n.gate_id} [{mark}] unlocks loop {n.unlocks_loop} -- {n.label}";
            self._seen_gate = self._seen_gate + 1 if hasattr(self, "_seen_gate") else 1;
        }
        self.log.append(entry);
        print(f"  >> {entry}");
    }
}

