```jac
"""Compiler-profile generation adapter: enforce that one coherent generation
binds its compiler-profile machine status, editor-intelligence join member
and product-health rail member together, and that downstream consumers can
only walk through those exact, same-generation edges.
"""

node CompilerStatus {
    has status_id: str = "";
    has state: str = "green";
    has generation: str = "";
}

node EditorJoin {
    has packet_id: str = "";
    has profile: str = "";
    has candidate: str = "";
    has current_selection: str = "";
    has generation: str = "";
}

node ProductRail {
    has packet_id: str = "";
    has profile: str = "";
    has area: str = "";
    has current_selection: str = "";
    has generation: str = "";
}

# A coherent current generation binds exactly one status + join + rail.
node Generation {
    has gen_id: str = "";
}

# Typed edges carry the "same coherent generation" relationship.
edge HasStatus { }
edge HasJoin { }
edge HasRail { }
edge Consumes { }

# Walkers are the consumers. Each can only traverse through edges whose
# payload proves "same generation, exact member". No inference, no fallback
# to names/files/loose history.
walker EditorIntelligence {
    has generation_id: str = "";
    has report: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can pick_generation with Generation entry {
        if here.gen_id != self.generation_id {
            disengage;
        }
        visit [->:HasJoin:->, ->:HasStatus:->];
    }

    can pick_join with EditorJoin entry {
        if here.generation != self.generation_id {
            report_line = f"EDITOR join {here.packet_id} rejected: not current";
            self.report.append(report_line);
            disengage;
        }
        report_line = f"EDITOR consuming exact join {here.packet_id} "
                      f"(profile={here.profile}, candidate={here.candidate})";
        self.report.append(report_line);
        visit [->:Consumes:->];
    }

    can pick_status with CompilerStatus entry {
        if here.generation != self.generation_id {
            report_line = "EDITOR status rejected: not current";
            self.report.append(report_line);
            disengage;
        }
        status_note = "ok" if here.state == "green" else "blocked";
        report_line = f"EDITOR sees compiler status {here.status_id} -> {status_note}";
        self.report.append(report_line);
    }

    can pick_rail with ProductRail entry {
        # Editor-intelligence does not consume rails.
        disengage;
    }

    def report -> list[str] {
        return self.report;
    }
}

walker ProductHealth {
    has generation_id: str = "";
    has report: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can pick_generation with Generation entry {
        if here.gen_id != self.generation_id {
            disengage;
        }
        visit [->:HasRail:->, ->:HasStatus:->];
    }

    can pick_rail with ProductRail entry {
        if here.generation != self.generation_id {
            report_line = f"HEALTH rail {here.packet_id} rejected: not current";
            self.report.append(report_line);
            disengage;
        }
        report_line = f"HEALTH consuming exact rail {here.packet_id} "
                      f"(profile={here.profile}, area={here.area})";
        self.report.append(report_line);
        visit [->:Consumes:->];
    }

    can pick_status with CompilerStatus entry {
        if here.generation != self.generation_id {
            report_line = "HEALTH status rejected: not current";
            self.report.append(report_line);
            disengage;
        }
        if here.area_dominates_rail(self.area_for(here)) {
            report_line = f"HEALTH rail satisfied by compiler status {here.status_id}";
            self.report.append(report_line);
        } else {
            report_line = f"HEALTH rail remains independent of compiler status {here.status_id}";
            self.report.append(report_line);
        }
    }

    can pick_join with EditorJoin entry {
        # Product-health does not consume joins.
        disengage;
    }

    def area_for(status: CompilerStatus) -> str {
        return "compiler";
    }

    def report -> list[str] {
        return self.report;
    }
}

# Domain rule: a compiler rail cannot satisfy a non-compiler area, and a
# non-compiler rail cannot satisfy a compiler rail. Carried as node
# behaviour so the walker can ask the rail itself.
edge CompilerArea { }
edge NonCompilerArea { }

with entry {
    # Generation A: coherent, current.
    gen_a = Generation(gen_id="G-A");
    st_a = CompilerStatus(status_id="S-1", state="green", generation="G-A");
    join_a = EditorJoin(packet_id="J-1", profile="perl", candidate="perl-5.40",
                        current_selection="perl-5.40", generation="G-A");
    rail_a = ProductRail(packet_id="R-1", profile="perl", area="compiler",
                         current_selection="perl-5.40", generation="G-A");
    gen_a +>:HasStatus:+> st_a;
    gen_a +>:HasJoin:+> join_a;
    gen_a +>:HasRail:+> rail_a;

    # Generation B: stale status (red), coherent otherwise.
    gen_b = Generation(gen_id="G-B");
    st_b = CompilerStatus(status_id="S-2", state="red", generation="G-B");
    join_b = EditorJoin(packet_id="J-2", profile="perl", candidate="perl-5.40",
                        current_selection="perl-5.40", generation="G-B");
    rail_b = ProductRail(packet_id="R-2", profile="perl", area="parser",
                         current_selection="perl-5.40", generation="G-B");
    gen_b +>:HasStatus:+> st_b;
    gen_b +>:HasJoin:+> join_b;
    gen_b +>:HasRail:+> rail_b;

    root ++> gen_a ++> gen_b;

    # Editor intelligence on the current generation.
    editor = EditorIntelligence(generation_id="G-A");
