# A layout's `load` may redirect instead of returning; we model that
# outcome as a sentinel on the layout's own state.
node Layout {
    has name: str = "";
    has loaded: bool = False;
    has redirected: bool = False;
    has visited_order: int = 0;
}

# Pages live beneath layouts and are what the user actually requests.
