"""Agent parent-chain cycle: native walker traversal with visited-set + depth-cap guards.

Models the cadis-core `agent_depth` scenario. Agents are nodes, the
parent reference is a typed edge, and the walker that follows the chain
carries an explicit cycle policy (visited set + depth cap) so it can
never hang on a cyclic parent reference.
"""

node Agent {
    has name: str = "";
    has depth_cached: int = -1;
}

edge Parents {
    has since: str = "";
}

walker DepthWalker {
    has start_agent: Agent | None = None;
    has max_depth: int = 100;
    has visited: list = [];
    has depth: int = 0;
    has cycle_detected: bool = False;

    can begin with Root entry {
        if self.start_agent is not None {
            visit [self.start_agent];
        } else {
            disengage;
        }
    }

    can follow with Agent entry {
        if here in self.visited {
            self.cycle_detected = True;
            print(f"[WARN] cycle detected at agent '{here.name}'; breaking parent chain");
            disengage;
        }
        self.visited.append(here);
        here.depth_cached = self.depth;
        print(f"visited agent '{here.name}' at depth {self.depth}");

        if self.depth >= self.max_depth {
            print(f"[WARN] depth cap {self.max_depth} reached; breaking chain");
            disengage;
        }

        self.depth += 1;
        parents = [here->:Parents:->];
        if parents.length > 0 {
            visit parents;
        } else {
            disengage;
        }
    }
}

walker RecoveryAuditor {
    has start_agent: Agent | None = None;
    has visited: list = [];
    has cycle_found: bool = False;

    can begin with Root entry {
        if self.start_agent is not None {
            visit [self.start_agent];
        } else {
            disengage;
        }
    }

    can audit with Agent entry {
        if here in self.visited {
            self.cycle_found = True;
            print(f"[RECOVER] cycle detected at '{here.name}'; truncating cyclic parent reference");
            here del ->:Parents:-> [here->:Parents:->][0];
