edge GatesFor { }       # ReviewGate covers a given tier level.
edge Affects { }        # ChangedPath is touched by this PR.
edge Matches { }        # ChangedPath matches this PathPattern.
edge Triggers { }       # Finding is triggered by a gate for a path.

