"""Mandate hierarchy: query signed descendants durably from spawned_by receipts.

Models a delegation graph where authority flows only through parent-signed
mandate receipts whose DID signatures verify. Walks descendants via typed
spawned_by edges with an explicit visited set (cycle-safe) and a signature
authority gate (unsigned/ambiguous/tampered edges are dropped).
"""

node Mandate {
    has title: str = "";
    has did: str = "";
    has signed: bool = False;
    has signature_ok: bool = False;
    has parent_did: str = "";
    has depth: int = 0;
    has reachable: bool = False;
}

edge SpawnedBy {
    has parent_did: str = "";
    has child_did: str = "";
    has signature_ok: bool = False;
    has unsigned_legacy: bool = False;
    has ambiguous: bool = False;
    has tampered: bool = False;
    has wrong_parent: bool = False;
}

walker DescendantQuery {
    has root_did: str = "";
    has ordered: list[str] = [];
    has seen: list[str] = [];

    can begin with Root entry {
        for child in [-->] {
            visit child;
        }
    }

    can collect with Mandate entry {
        if here.did in self.seen {
            stop;
        }
        self.seen.append(here.did);
        if here.reachable and here.signed and here.signature_ok {
            self.ordered.append(here.did);
        }
        for child in [-->] {
            visit child;
        }
    }

    def query(root_did: str) -> list[str] {
        self.root_did = root_did;
        self.ordered = [];
        self.seen = [];
        return self.ordered;
    }
}

walker AuthorityWalker {
    has root_mandate: str = "";
    has verified: list[str] = [];

    can begin with Root entry {
        target = Mandate(did=self.root_mandate);
        for child in [-->] {
            if isinstance(child, Mandate) {
                child.reachable = self._is_authority(child, target.did);
            }
        }
    }

    can walk with Mandate entry {
        for child in [-->] {
            if isinstance(child, Mandate) {
                child.reachable = self._is_authority(child, here.did);
                visit child;
            }
        }
    }

    def _is_authority(child: Mandate, parent_did: str) -> bool {
        if not child.signed {
            return False;
        }
        if not child.signature_ok {
            return False;
        }
        if child.parent_did != parent_did {
            return False;
        }
        return True;
    }
}

