"""Cloud-harness agent supervision: model bounded coding subagents and their
parent/child cancellation graph. A maintainer spawns tasks; each task has a
TTL and budget; children inherit the principal/workspace of their parent and
are cancelled deterministically when the parent terminates (close, TTL
exceeded, or budget breach). The supervisor walker enforces isolation,
idempotency, and cascade cancellation across the lineage."""

node Principal {
    has name: str = "";
    has workspace: str = "";
    has budget_tokens: int = 0;
}

node Agent {
    has agent_id: str = "";
    has task: str = "";
    has ttl_remaining: int = 0;
    has tokens_used: int = 0;
    has status: str = "live";
    has idempotency_key: str = "";

    def is_alive() -> bool {
        return self.status == "live";
    }

    def breach() -> bool {
        return self.tokens_used > self.budget_tokens or self.ttl_remaining <= 0;
    }
}

edge Owns {
    has granted_at: str = "";
}

edge Spawned {
    has since: str = "";
}

edge Sibling {
    has note: str = "";
