```jac
"""Materialized-path tree with cascade path refresh.

Models the issue's scenario: documents live in a parent/child tree identified
by ``parentId`` and cached by a materialized ``path`` string. When a node is
moved (its ``parentId`` changes) we must refresh its own path and recursively
re-stamp every descendant's path. The walker ``PathRefresher`` does exactly
that, traversing typed ``ParentOf`` edges from the moved node downward, with
an explicit visited-set cycle guard (jac 0.36.1 walkers do not dedupe).
"""

node TreeNode {
    has label: str = "";
    has parent_id: str = "";
    has path: str = "";
}

edge ParentOf {
    has weight: int = 0;
}

walker PathRefresher {
    has moved_id: str = "";
    has root_parent_id: str = "";
    has visited: list[str] = [];

    can start with Root entry {
        for n in [-->(?:TreeNode)] {
            if n.parent_id == "" {
                visit [->:ParentOf:->];
            }
        }
        visit [-->] else { disengage; }
    }

    can refresh with TreeNode entry {
        if here.parent_id == self.moved_id {
            parent_node = None;
            for candidate in [-->](?:TreeNode) {
                if candidate.label == here.parent_id {
                    parent_node = candidate;
                }
            }
            if parent_node is not None {
                here.path = parent_node.path + "/" + here.label;
            }
            if here.label in self.visited {
                disengage;
            }
            self.visited.append(here.label);
            visit [->:ParentOf:->];
        } else {
            visit [-->] else { disengage; }
        }
    }
}

with entry {
    a = TreeNode(label="A", parent_id="", path="/A");
    b = TreeNode(label="B", parent_id="A", path="/A/B");
    c = TreeNode(label="C", parent_id="B", path="/A/B/C");
    d = TreeNode(label="D", parent_id="A", path="/A/D");
    e = TreeNode(label="E", parent_id="C", path="/A/B/C/E");

    root ++> a;
    a +>:ParentOf:+> b;
    b +>:ParentOf:+> c;
    a +>:ParentOf:+> d;
    c +>:ParentOf:+> e;

    print("Before move:");
    for n in [-->](?:TreeNode) {
        print(f"  {n.label} path={n.path} parent={n.parent_id}");
    }

    c.parent_id = "D";
    c.path = "/A/D/C";
    a del ->:ParentOf:-> b;
    d +>:ParentOf:+> c;

    refresher = PathRefresher(moved_id="D");
    root spawn refresher;

    print("After move + cascade refresh:");
    for n in [-->](?:TreeNode) {
        print(f"  {n.label} path={n.path} parent={n.parent_id}");
    }
}
