Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.

```jac
"""Evidence summary walker: model RIPR's test-evidence summary producer.

The issue describes a traceability graph where each Rust test/fixture is
connected to its source, oracle, and requirements via purpose-bearing
edges. The hand-rolled pain is that the producer must walk the graph to
collect evidence for a selected test, guarding against cycles in the
ownership/relation graph and against revisiting nodes already summarised.

We model the core entity types as archetypes, the relationships as typed
edges, and the summary traversal as a walker with an explicit cycle guard
(no built-in visited-set in jac 0.36.1).
"""

# --- Entities ----------------------------------------------------------------

node Requirement {
    has name: str = "";
    has needs_variant: bool = True;
}

node TestTarget {
    has name: str = "";
    # True when the test asserts an exact error variant (e.g. Error::Boundary);
    # False when it only does a broad check like is_err().
    has exact_variant_asserted: bool = False;
}

node Oracle {
    has text: str = "";
    has strength: str = "broad";
}

node Limitation {
    has kind: str = "";
    has detail: str = "";
}

# --- Typed edges (the relationships carry meaning) ---------------------------

# What the test appears to target (production owner candidates).
edge Targets {
    has confidence: float = 0.0;
    has reason: str = "";
}

# A test asserts through an oracle; the assertion range belongs to the oracle.
edge Asserts {
    has source_range: str = "";
}

# The test stands in for a requirement; missing/variant mismatches live here.
edge Serves {
}

# The summary may carry bounded limitations attached to the test.
edge HasLimit {
}

# --- Walker: build a TestEvidenceSummaryV1 by walking the evidence graph ----

walker EvidenceSummary {
    has target_name: str = "";
    has produced: dict = {};
    has seen: list = [];

    can start with Root entry {
        # Pick the test of interest from root's outgoing Targets/Asserts/Serves
        # edges. We locate it by walking to TestTarget nodes that match.
        visit [->:Targets:->];
    }

    can select with TestTarget entry {
        if here.name == self.target_name {
            self.produced["selector"] = here.name;
            self.produced["exact_variant_asserted"] = here.exact_variant_asserted;
            if here.name not in self.seen {
                self.seen.append(here.name);
            }
            # From the test, walk outgoing typed edges to oracles,
            # requirements, and limitations.
            visit [->:Asserts:->];
            visit [->:Serves:->];
            visit [->:HasLimit:->];
        } else {
            # Not the test we want; keep walking to find it.
            visit [->:Targets:->] else { disengage; }
        }
    }

    can collect_oracle with Oracle entry {
        key = here.text;
        # Cycle/duplicate guard for oracles (no built-in visited-set).
        if key in self.seen {
            disengage;
        }
        self.seen.append(key);
        if "oracles" not in self.produced {
            self.produced["oracles"] = [];
        }
        self.produced["oracles"].append(
            {"text": here.text, "strength": here.strength}
        );
    }

    can collect_req with Requirement entry {
        key = here.name;
        if key in self.seen {
            disengage;
        }
        self.seen.append(key);
        # Detect a real gap: requirement needs an exact variant but the
        # test only does a broad is_err()-style assertion.
        miss = "missing_exact_error_variant";
        if here.needs_variant and not self.produced.get(
            "exact_variant_asserted", False
        ) {
            if "negative" not in self.produced {
                self.produced["negative"] = [];
            }
            self.produced["negative"].append(miss);
        }
    }

    can collect_limit with Limitation entry {
        key = here.kind + ":" + here.detail;
        if key in self.seen {
            disengage;
        }
        self.seen.append(key);
        if "limitations" not in self.produced {
            self.produced["limitations"] = [];
        }
        self.produced["limitations"].append(
            {"kind": here.kind, "detail": here.detail}
        );
    }

    can finish with Root entry {
        print(f"TestEvidenceSummaryV1 for {self.target_name}:");
        for k in self.produced.keys() {
            print(f"  {k}: {self.produced[k]}");
        }
    }
}

# --- Demo graph --------------------------------------------------------------

with entry {
    # A boundary-validation test that only does is_err() — a real evidence
    # gap when the requirement needs the exact Error::Boundary variant.
    rejects_boundary = TestTarget(
        name="tests::rejects_boundary", exact_variant_asserted=False
    );
    accepts_well_formed = TestTarget(
        name="tests::accepts_well_formed", exact_variant_asserted=True
    );

    # Oracles attached to each test.
    broad_oracle = Oracle(text="is_err()", strength="broad");
    exact_oracle = Oracle(text="assert_eq!(err, Error::Boundary)", strength="exact");

    # Requirements the tests serve.
    boundary_req = Requirement(name="reject out-of-range input", needs_variant=True);
    happy_path_req = Requirement(name="accept well-formed input", needs_variant=False);

    # Bounded limitations the producer must carry forward.
    macro_lim = Limitation(kind="macro/generated test opacity", detail="assert! macro expanded inline");
    helper_lim = Limitation(kind="custom helper unresolved", detail="custom_match! helper opaque");

    # Wire the graph. Typed edges carry the relationship meaning.
    root +>:Targets(confidence=0.9, reason="name proximity"):+> rejects_boundary;
    root +>:Targets(confidence=0.7, reason="module path"):+> accepts_well_formed;

    rejects_boundary +>:Asserts(source_range="tests/boundary.rs:42-44"):+> broad_oracle;
    accepts_well_formed +>:Asserts(source_range="tests/happy.rs:10-12"):+> exact_oracle;

    rejects_boundary +>:Serves:+> boundary_req;
    accepts_well_formed +>:Serves:+> happy_path_req;

    rejects_boundary +>:HasLimit:+> macro_lim;
    rejects_boundary +>:HasLimit:+> helper_lim;

    # Spawn the producer walker against the weak test to expose the gap.
    root spawn EvidenceSummary(target_name="tests::rejects_boundary");
    # And against the strong test for a clean summary.
    root spawn EvidenceSummary(target_name="tests::accepts_well_formed");
}
