Task:
A maintainer on the project astral-sh/uv (unknown) filed this issue about hand-rolled graph machinery causing pain:

Issue #16286: cached versions of packages

### Summary

## How Your Idea Would Work
The workflow you're proposing would be a huge quality-of-life improvement. It might look something like this:
Your pyproject.toml has an unpinned dependency like "torch".
You run uv sync.
uv checks its global cache and sees that the last version of torch you installed from the nightly source was 2.7.0.dev20251012.
It then quickly checks the online repository and sees that a newer version, 2.7.0.dev20251013, is available.
Instead of just automatically downloading the new one, it prompts you:
Found a recent version of 'torch' (2.7.0.dev20251012) in your cache.
The latest version available is 2.7.0.dev20251013.

Use the cached version and skip the download? [Y/n]:
## Why It's a Great Suggestion
It Promotes Stability by Default: This makes your environment's versions "sticky." They won't change unless you explicitly tell them to, which is much safer than automatically grabbing the latest, potentially broken, nightly build.
It Saves Time and Bandwidth: It directly avoids the slow dependency resolution and re-download process for minor updates.
It's User-Centric: It makes the tool feel more like an intelligent assistant that understands your workflow, rather than just a command executor.

### Example

_No response_

Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.

```jac
"""Cached package versions: model a dependency cache and check whether the
cached version should be preferred over the latest remote version.

Scenario (from astral-sh/uv issue #16286): when `uv sync` runs for an
unpinned dependency like "torch", it compares the last cached version
(seen during a previous install) against the latest version available
from the upstream index. The user is then prompted whether to reuse the
cached version or download the newer one.

This demo lifts that hand-rolled lookup into a native Jac graph:

  Index ----HasVersion----> Package ----HasVersion----> Version
                                              \--CachedFrom---> Version

Walkers `CacheInspector` and `ResolutionPrompt` traverse the `HasVersion`
typed edges to enumerate a package's known versions and decide whether
the cached version is recent enough to skip the download.
"""

node Index {
    has name: str = "";
}

node Package {
    has name: str = "";
}

node Version {
    has label: str = "";
    has build_date: str = "";
    has source: str = "";   # "remote" or "cache"
}

edge HasVersion {
    has channel: str = "";  # "remote" or "cache"
}

edge CachedFrom {
    has last_used: str = "";
}

walker CacheInspector {
    can start with Root entry {
        visit [-->];
    }

    can walk_index with Index entry {
        print(f"[index] {here.name}");
        visit [->:HasVersion:->];
    }

    can show_pkg with Package entry {
        print(f"[pkg] {here.name}");
        visit [->:HasVersion:->];
    }

    can show_ver with Version entry {
        chan = "remote" if here.source == "remote" else "cached";
        print(f"  - {here.label} ({here.build_date}) [{chan}]");
        visit [->:CachedFrom:->];
    }
}

walker ResolutionPrompt {
    can start with Root entry {
        visit [-->];
    }

    can walk_index with Index entry {
        visit [->:HasVersion:->];
    }

    can pick_pkg with Package entry {
        cached: Version | None = None;
        remote: Version | None = None;

        # Two-phase enumeration of typed edges off the Package.
        # First find any version connected via a HasVersion edge whose
        # channel is "cache"; then any whose channel is "remote".
        kids = [->:HasVersion:->];
        for v in kids {
            if v.channel == "cache" and cached is None {
                cached = v;
            } elif v.channel == "remote" and remote is None {
                remote = v;
            }
        }

        if cached is None {
            print(f"{here.name}: no cached version, will download "
                  f"{remote.label if remote is not None else 'unknown'}");
            return;
        }
        if remote is None {
            print(f"{here.name}: only cached version available "
                  f"({cached.label})");
            return;
        }

        cached_date = cached.build_date;
        remote_date = remote.build_date;
        cached_is_recent = cached_date >= remote_date;

        if cached_is_recent {
            print(f"{here.name}: cached {cached.label} ({cached_date}) is "
                  f"as recent as remote {remote.label} ({remote_date}); "
                  f"reuse cache and skip download");
        } else {
            print(f"{here.name}: remote {remote.label} ({remote_date}) is "
                  f"newer than cached {cached.label} ({cached_date}); "
                  f"download the new build");
        }
    }
}

with entry {
    pypi = Index(name="pypi");

    torch = Package(name="torch");
    pypi +>:HasVersion:+> torch;

    torch_cached = Version(
        label="2.7.0.dev20251012",
        build_date="2025-10-12",
        source="cache",
    );
    torch_remote = Version(
        label="2.7.0.dev20251013",
        build_date="2025-10-13",
        source="remote",
    );
    torch +>:HasVersion(channel="cache"):+> torch_cached;
    torch +>:HasVersion(channel="remote"):+> torch_remote;

    # Encode the cache lineage: the cached entry was reused from the
    # earlier nightly that lived in the cache before the new one arrived.
    torch_cached +>:CachedFrom(last_used="2025-10-12"):+> torch_remote;

    # A second package with only a cached version to exercise the
    # "no remote available" branch.
    numpy = Package(name="numpy");
    pypi +>:HasVersion:+> numpy;
    numpy +>:HasVersion(channel="cache"):+> Version(
        label="2.1.0",
        build_date="2024-12-08",
        source="cache",
    );

    print("=== cache inspector walk ===");
    pypi spawn CacheInspector();

    print("");
    print("=== resolution prompt walk ===");
    pypi spawn ResolutionPrompt();
}
```

