"""Package cache freshness check: model a uv-style cache-vs-index comparison.

A small dependency graph where each Package node carries a cached version and a
remote version. A typed ``Cached`` edge marks the cache hit, a ``Listed`` edge
marks the registry listing. The ``CacheAuditor`` walker traverses the graph
and reports, for each package, whether the cache is fresh or stale — the very
comparison uv would do before deciding to prompt the user about a re-download.
"""

node Package {
    has name: str = "";
    has cached_version: str = "";
    has remote_version: str = "";
}

# Typed edges so the relationship meaning (cache vs index) is encoded in the
# graph, not in ad-hoc dicts.
edge Cached { has since: str = ""; }
edge Listed { has source: str = ""; }
edge Depends { }

walker CacheAuditor {
    has report: list[str] = [];

    can start with Root entry {
        # Walk the dependency tree along the typed ``Depends`` edges so we
        # inspect every package the project transitively pulls in.
        visit [->:Depends:->];
    }

    can audit with Package entry {
        # Freshness check: does the cache match the latest remote version?
        fresh = "fresh" if here.cached_version == here.remote_version else "stale";
        line = f"{here.name}: cache={here.cached_version}, remote={here.remote_version} -> {fresh}";
        self.report.append(line);
        visit [->:Depends:->];
    }

    can summarize with Root exit {
        print("=== Cache freshness report ===");
        for entry in self.report {
            print(entry);
        }
        print(f"Inspected {len(self.report)} package(s).");
    }
}

with entry {
    # Wire a small dependency graph: root -> torch -> numpy (transitive).
    torch = Package(name="torch", cached_version="2.7.0.dev20251012", remote_version="2.7.0.dev20251013");
    numpy = Package(name="numpy", cached_version="2.2.0", remote_version="2.2.0");
    requests = Package(name="requests", cached_version="2.32.3", remote_version="2.32.4");

    root +>:Cached(since="2025-10-12"):+> torch;
    root +>:Listed(source="pypi"):+> torch;
    torch +>:Depends:+> numpy;
    root +>:Depends:+> requests;

    auditor = CacheAuditor();
    root spawn auditor;
}

