```jac
"""CI gate parity model: ambient vs parity-venv check outcomes.

Models the scenario from issue #2154 — a CI gate records the outcome of
running a known-slow semantic-duplicate check under two interpreters
(ambient python and the parity venv), and a Walker collects the gate
records into a verdict for the pre-PR run.
"""

# ---- Entity archetypes ----------------------------------------------------

node Check {
    has name: str = "";
    has family: str = "";
    has expected_seconds: float = 0.0;
    has budget_seconds: float = 0.0;
}

node Interpreter {
    has label: str = "";
    has kind: str = "";
    has multiplier: float = 1.0;
}

node CheckRun {
    has observed_seconds: float = 0.0;
    has verdict: str = "";
}

node GateRecord {
    has mode: str = "";
    has overall_status: str = "";
}

# ---- Typed edges ----------------------------------------------------------

edge Covers { }
edge ExecutedBy { }
edge Records { }
edge Joins { }

# ---- Walker: collect every CheckRun under a GateRecord and roll up --------

walker Verdict {
    has passed: int = 0;
    has unknown: int = 0;
    has failed: int = 0;

    can start with Root entry {
        visit [->:Records:->];
    }

    can tally with GateRecord entry {
        print(f"GateRecord mode={here.mode} status={here.overall_status}");
        visit [->:Joins:->];
    }

    can score with CheckRun entry {
        bucket = "passed" if here.verdict == "passed" else (
            "unknown" if here.verdict == "unknown" else "failed"
        );
        if bucket == "passed" {
            self.passed += 1;
        } elif bucket == "unknown" {
            self.unknown += 1;
        } else {
            self.failed += 1;
        }
        label = "PASS" if here.verdict == "passed" else (
            "TIMEOUT" if here.verdict == "unknown" else "FAIL"
        );
        print(f"  [{label}] check run observed={here.observed_seconds:.1f}s");
        visit [-->];
    }
}

# ---- Walker: walk checks forward, scoring each interpreter's run ----------

walker TimeCheck {
    can start with Root entry {
        visit [-->];
    }

    can scan with Check entry {
        print(f"check {here.name} ({here.family}) budget={here.budget_seconds:.0f}s");
        visit [-->];
    }
}

# ---- Demo wiring ----------------------------------------------------------

with entry {
    sem_dup = Check(
        name="semantic_dup",
        family="qa",
        expected_seconds=86.0,
        budget_seconds=600.0,
    );
    root +>:Covers:+> sem_dup;

    ambient = Interpreter(label="ambient", kind="system", multiplier=1.0);
    parity = Interpreter(label="parity_venv", kind="venv", multiplier=9.0);
    sem_dup +>:ExecutedBy:+> ambient;
    sem_dup +>:ExecutedBy:+> parity;

    ambient_run = CheckRun(observed_seconds=86.0, verdict="passed");
    parity_run = CheckRun(observed_seconds=774.0, verdict="unknown");
    ambient +>:Records:+> ambient_run;
    parity +>:Records:+> parity_run;

    pre_pr = GateRecord(mode="pre-pr", overall_status="mixed");
    ambient_run +>:Joins:+> pre_pr;
    parity_run +>:Joins:+> pre_pr;

    pre_pr +>:Covers:+> Check(name="lint", family="qa", budget_seconds=120.0);
    pre_pr +>:Covers:+> Check(name="typecheck", family="qa", budget_seconds=180.0);

    print("== TimeCheck walker sweep ==");
    TimeCheck() spawn root;

    print("== Verdict walker rollup ==");
    v = Verdict();
    pre_pr spawn v;
    print(f"result: passed={v.passed} unknown={v.unknown} failed={v.failed}");
    print("expected: ambient 86s -> PASS, parity 774s -> TIMEOUT (budget 600s)");
}
