            here.elapsed_s = 12.0 * 60.0 + 54.0;
        } else {
            here.elapsed_s = ambient_s;
        }
        self.total_elapsed = self.total_elapsed + here.elapsed_s;

        # Reproduce the gate's hardcoded 600s subprocess timeout.
        if here.elapsed_s > here.timeout_s {
            here.status = "unknown/TimeoutExpired";
            self.log.append(
                f"[FAIL] {here.name}: {here.elapsed_s:.0f}s > timeout {here.timeout_s:.0f}s -> {here.status}"
            );
        } else {
            here.status = "pass";
            self.log.append(
                f"[OK]   {here.name}: {here.elapsed_s:.0f}s within {here.timeout_s:.0f}s"
            );
        }

        visit [-->];
    }
}

