```jac
"""R0 Tag protection: model the acceptance gate and tag-creation policy as a typed graph.

Core scenario: a Release (R0) gate decides whether an acceptance tag may be
created. If the gate is not accepted OR its outcome is not 'continue', the tag
must NOT be created. A walker walks the dependency chain (the recursive
plumbing the issue complains about) and reports the final verdict.
"""

node Task {
    has task_id: str = "";
    has state: str = "ready";
    has required: bool = False;
}

node R0Gate {
    has gate_id: str = "R0";
    has accepted: bool = False;
    has outcome: str = "halt";
}

node AcceptanceTag {
    has tag_name: str = "";
    has created: bool = False;
}

edge DependsOn { }
edge Governs { }
edge Produces { }

walker DependencyAuditor {
    has seen: list[str] = [];
    has blocked: bool = False;

    can start with Root entry {
        visit [->:Governs:->];
    }

    can audit_gate with R0Gate entry {
        if here.gate_id in self.seen {
            visit [-->];
            return;
        }
        self.seen.append(here.gate_id);
        # AC-2: gate must be accepted AND outcome must be 'continue'.
        if not here.accepted or here.outcome != "continue" {
            self.blocked = True;
            print(f"  [BLOCK] R0 gate {here.gate_id} rejected: "
                  f"accepted={here.accepted}, outcome={here.outcome}");
            visit [-->];
            return;
        }
        print(f"  [PASS]  R0 gate {here.gate_id} cleared");
        visit [->:Governs:->];
    }

    can audit_task with Task entry {
        if here.task_id in self.seen {
            visit [-->];
            return;
        }
        self.seen.append(here.task_id);
        if here.required and here.state != "done" {
            self.blocked = True;
            print(f"  [BLOCK] required task {here.task_id} not done "
                  f"(state={here.state})");
        } else {
            print(f"  [OK]    task {here.task_id} state={here.state}");
        }
        visit [->:DependsOn:->];
    }
}

walker TagEnforcer {
    can start with Root entry {
        # Find the R0 gate and the acceptance tag, then enforce policy.
        gate = [root --> (`?R0Gate)];
        tags = [root --> (`?AcceptanceTag)];
        if not gate or not tags {
            print("  [ERROR] missing R0Gate or AcceptanceTag in graph");
            disengage;
        }
        g = gate[0];
        t = tags[0];
        auditor = DependencyAuditor();
        g spawn auditor;
        verdict = "ALLOW" if not auditor.blocked else "DENY";
        print(f"\nFinal R0 verdict: {verdict}");
        if verdict == "ALLOW" {
            t.created = True;
            print(f"  -> acceptance tag '{t.tag_name}' CREATED");
        } else {
            print(f"  -> acceptance tag '{t.tag_name}' NOT created "
                  f"(AC-2 enforced)");
        }
        report {"verdict": verdict, "tag": t.tag_name, "created": t.created};
    }
}

with entry {
    # Demo A: gate accepted, outcome=continue, all required tasks done
    #         -> tag SHOULD be created.
    print("=== Scenario A: clean path ===");
    gate_a = R0Gate(gate_id="R0", accepted=True, outcome="continue");
    tag_a = AcceptanceTag(tag_name="acceptance-v1.0");
    t1 = Task(task_id="TASK-OPS-002", state="done", required=True);
    t2 = Task(task_id="TASK-DOC-002", state="done", required=True);
    root +>:Governs:+> gate_a;
    gate_a +>:DependsOn:+> t1;
    t1 +>:DependsOn:+> t2;
    root ++> tag_a;
    root spawn TagEnforcer();

    # Demo B: gate NOT accepted, outcome=halt
    #         -> tag MUST NOT be created (AC-2).
    print("\n=== Scenario B: gate rejected ===");
    gate_b = R0Gate(gate_id="R0", accepted=False, outcome="halt");
    tag_b = AcceptanceTag(tag_name="acceptance-v0.9");
    t3 = Task(task_id="TASK-OPS-002", state="done", required=True);
    root +>:Governs:+> gate_b;
    gate_b +>:DependsOn:+> t3;
    root ++> tag_b;
    root spawn TagEnforcer();

    # Demo C: gate accepted, outcome=continue, but a required task still
    #         'ready' -> tag MUST NOT be created (cascade invalidation).
    print("\n=== Scenario C: required task incomplete ===");
    gate_c = R0Gate(gate_id="R0", accepted=True, outcome="continue");
    tag_c = AcceptanceTag(tag_name="acceptance-v0.8");
    t4 = Task(task_id="TASK-OPS-002", state="ready", required=True);
    t5 = Task(task_id="TASK-DOC-002", state="done", required=True);
    root +>:Governs:+> gate_c;
    gate_c +>:DependsOn:+> t4;
    t4 +>:DependsOn:+> t5;
    root ++> tag_c;
    root spawn TagEnforcer();
}
