Issue #585: Opt-in JIT-compiled formatter for the read path

## Summary

Add an opt-in JIT-compiled formatter that replaces ElectroDB's interpreted item-formatting path with a per-schema compiled function, reducing per-item overhead on reads.

## Motivation

Every item returned by `get`, `query`, `scan`, and `parse` is shaped by the formatter: applying getters, unwrapping sets, walking nested maps/lists, filtering to requested attributes, and enforcing ownership. Today this runs through an interpreted path that re-walks the schema for **every item**. On large queries/scans this per-item, per-attribute traversal is pure repeated work — the schema is known and fixed at `Entity` construction time.

## Proposal

Compile a formatter specialized to a single entity's schema once (at construction) and use it in place of the interpreted path.

Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.

```jac
"""ElectroDB-style read-path JIT formatter demo.

Models the per-item formatting pipeline that the issue complains about:
a schema is fixed at entity construction, but every read re-walks it.
We model an Entity (with attributes and nested sub-models), a ReadItem,
a typed Format edge, and a JitFormatter walker that walks the schema
once per item — analogous to ElectroDB's repeated per-attribute schema
traversal on the read path.
"""

# ---------- Edge archetype ----------
edge Format {
    has role: str = "";
}

# ---------- Entity: the model whose schema is walked per item ----------
node Entity {
    has name: str = "";
    has attributes: list[str] = [];
    has owned: list[str] = [];
}

# ---------- SubModel: nested shape inside an Entity ----------
node SubModel {
    has key: str = "";
    has fields: list[str] = [];
}

# ---------- ReadItem: one row pulled from the store ----------
node ReadItem {
    has label: str = "";
    has payload: dict[str, object] = {};
}

# ---------- Compiled schema node: produced once at Entity construction ----------
node CompiledSchema {
    has entity_name: str = "";
    has attribute_count: int = 0;
    has nested_count: int = 0;
}

# ---------- JitFormatter: walker that performs the read-path formatting ----------
walker JitFormatter {
    has formatted_count: int = 0;
    has visited_schemas: list[str] = [];
    has visited_edges: set[str] = {};

    can start with Root entry {
        # Cycle guard: walker will see CompiledSchema nodes multiple times
        # on shared sub-models. Track schemas we have walked already.
        visit [->:Format:->];
    }

    can shape with CompiledSchema entry {
        # Per-schema work: count attributes and nested sub-models once.
        if here.entity_name not in self.visited_schemas {
            self.visited_schemas.append(here.entity_name);
        }
        visit [here->:Format:->];
    }

    can collect_attr with Entity entry {
        if (here.name + "#entity") not in self.visited_edges {
            self.visited_edges.add(here.name + "#entity");
            self.formatted_count += len(here.attributes);
        }
        visit [here->:Format:->];
    }

    can collect_nested with SubModel entry {
        edge_tag = here.key + "#nested";
        if edge_tag not in self.visited_edges {
            self.visited_edges.add(edge_tag);
            self.formatted_count += len(here.fields);
        }
    }

    can apply with ReadItem entry {
        # One item flows through the compiled schema once.
        # Walk the Format edges attached to this item.
        visit [here->:Format:->];
    }

    # Union ability: a single routine handles the three schema shapes
    # that the read path formats over. The body only touches fields
    # that exist on every type in the union (here.name / here.key /
    # here.entity_name are all strings).
    can finalize with CompiledSchema | Entity | SubModel entry {
        # No-op finalizer; presence of union ability documents that
        # one routine handles multiple node kinds on the read path.
        if False {
            print("unreachable");
        }
    }
}

# ---------- CascadeInvalidator: walker that drops cached formatters ----------
# Models the cascade-delete-style invalidation: dropping an Entity
# invalidates every compiled schema + every in-flight ReadItem that
# was being shaped against it.
walker CascadeInvalidator {
    has invalidated: int = 0;

    can start with Root entry {
        visit [->:Format:->];
    }

    can drop_schema with CompiledSchema entry {
        self.invalidated += 1;
        visit [-->];
    }

    can drop_item with ReadItem entry {
        self.invalidated += 1;
        visit [-->];
    }

    can drop_sub with SubModel entry {
        self.invalidated += 1;
        visit [-->];
    }

    can drop_entity with Entity entry {
        self.invalidated += 1;
        # End walk: no further Format edges from an Entity in this demo.
        visit [-->] else { disengage; }
    }
}

# ---------- Demo wiring ----------
with entry {
    # Build a User entity with two nested sub-models.
    user_schema = CompiledSchema(entity_name="User", attribute_count=6, nested_count=2);
    user_email = SubModel(key="email", fields=["addr", "verified"]);
    user_addr = SubModel(key="address", fields=["city", "zip"]);
    user = Entity(name="User", attributes=["id", "name", "email", "city", "zip", "role"],
                  owned=["id", "name"]);

    # Build an Order entity that shares the address sub-model.
    order_schema = CompiledSchema(entity_name="Order", attribute_count=4, nested_count=1);
    order_addr = SubModel(key="address", fields=["city", "zip"]);
    order = Entity(name="Order", attributes=["id", "total", "city", "zip"], owned=["id"]);

    # Read items being shaped.
    item_a = ReadItem(label="row-1", payload={"id": "u1", "name": "Ada"});
    item_b = ReadItem(label="row-2", payload={"id": "o1", "total": 42.0});

    # Typed-edge wiring: Format edges carry the role of each relation.
    user +>:Format(role="compiles"):+> user_schema;
    user_schema +>:Format(role="owns"):+> user_email;
    user_schema +>:Format(role="owns"):+> user_addr;
    item_a +>:Format(role="shapes"):+> user_schema;

    order +>:Format(role="compiles"):+> order_schema;
    order_schema +>:Format(role="owns"):+> order_addr;
    item_b +>:Format(role="shapes"):+> order_schema;

    # Root chains in everything so a single spawn reaches the graph.
    root ++> user ++> order ++> item_a ++> item_b;

    # Run the JIT read-path formatter.
    fmt = JitFormatter();
    root spawn fmt;
    print(f"[jit] formatted {fmt.formatted_count} attribute slots "
          f"across {len(fmt.visited_schemas)} compiled schemas");

    # Now invalidate: dropping an entity must cascade.
    inv = CascadeInvalidator();
    root spawn inv;
    print(f"[cascade] invalidated {inv.invalidated} cached entries");
}
```

