Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.

```jac
"""Role-Based Access Control: model users, permissions, and roles as a graph.

Entities (nodes) carry relationships via typed edges. A walker audits a
user's effective permissions by traversing the role graph, walks the
hierarchy to topological-order role inheritance, and demonstrates cascade
revocation when a role is deleted.
"""

# ---------------------------------------------------------------------------
# Nodes
# ---------------------------------------------------------------------------

node Permission {
    has name: str = "";
    has label: str = "";
}

node Role {
    has name: str = "";
    has level: int = 0;
}

node User {
    has username: str = "";
    has active: bool = True;
}

# ---------------------------------------------------------------------------
# Typed edges (the relationships carry meaning, so each is an archetype)
# ---------------------------------------------------------------------------

edge Grants {
    has granted_at: str = "";
}

edge Inherits {
    # A role Inherits from another (more senior) role.
}

edge Assigned {
    has assigned_at: str = "";
    has temporary: bool = False;
}

edge Denies {
    # An explicit denial from a senior role overrides inheritance.
}

# ---------------------------------------------------------------------------
# Walker 1: PermissionAuditor
#   Walks the inheritance chain from a user's roles, collects grants and
#   denials, and resolves the effective permission list. Includes an
#   explicit visited-set (jac 0.36.1 walkers do not dedupe on cycles).
# ---------------------------------------------------------------------------

walker PermissionAuditor {
    has username: str = "";
    has collected_grants: list[str] = [];
    has collected_denials: list[str] = [];
    has seen_roles: list[str] = [];

    can start with Root entry {
        # Find the target user and start auditing from their role assignments.
        for u in [-->](?:User) {
            if u.username == self.username {
                visit [->:Assigned:->];
            }
        }
    }

    can audit_user with User entry {
        # Already on the user — fall through to roles.
        visit [->:Assigned:->];
    }

    can audit_role with Role entry {
        if here.name in self.seen_roles {
            # Cycle guard: stop walking this branch.
            disengage;
        }
        self.seen_roles.append(here.name);

        # Direct grants from this role.
        for g in [->:Grants:->] {
            if g.name not in self.collected_grants {
                self.collected_grants.append(g.name);
            }
        }

        # Direct denials from this role.
        for d in [->:Denies:->] {
            if d.name not in self.collected_denials {
                self.collected_denials.append(d.name);
            }
        }

        # Walk inheritance upward — but a denial from any ancestor sticks.
        visit [->:Inherits:->];
    }

    can finish with Root entry {
        effective = [];
        for p in self.collected_grants {
            if p not in self.collected_denials and p not in effective {
                effective.append(p);
            }
        }
        report {
            "user": self.username,
            "roles_visited": self.seen_roles,
            "grants": self.collected_grants,
            "denials": self.collected_denials,
            "effective_permissions": effective,
        };
    }
}

# ---------------------------------------------------------------------------
# Walker 2: RoleHierarchyOrder
#   Performs a topological walk over Inherits edges so that each role is
#   processed after the roles it inherits from. Implements Kahn-style
#   ordering: find roots (no incoming Inherits), emit, drop their outgoing
#   edges, repeat — purely with walkers and edge deletes.
# ---------------------------------------------------------------------------

walker FindRoots {
    can start with Root entry {
        # Pick roles that have NO incoming Inherits edge as roots.
        candidates = [];
        for r in [-->](?:Role) {
            has_incoming = false;
            for other in [-->](?:Role) {
                if other ->:Inherits:-> r {
                    has_incoming = true;
                }
            }
            if not has_incoming {
                candidates.append(r);
            }
        }
        report {"roots": candidates};
    }
}

walker EmitRole {
    has order: list[str] = [];
    can start with Root entry {
        for r in [-->](?:Role) {
            if r.name not in self.order {
                self.order.append(r.name);
            }
        }
    }
}

# ---------------------------------------------------------------------------
# Walker 3: CascadeRevoke
#   When a role is removed (here we just detach its grants/denials and
#   sever inheritance), downstream users lose access. Demonstrates the
#   cascade: walk from a role through Inherits edges to dependents, then
#   through Assigned edges to affected users, printing impact.
# ---------------------------------------------------------------------------

walker CascadeRevoke {
    has role_name: str = "";
    has affected_users: list[str] = [];

    can start with Root entry {
        target = None;
        for r in [-->](?:Role) {
            if r.name == self.role_name {
                target = r;
            }
        }
        if target is not None {
            visit [->:Inherits:->];
        }
    }

    can cascade_role with Role entry {
        # Roles that inherit from the revoked role are also impacted.
        for u in [->:Assigned:->] {
            if u.username not in self.affected_users {
                self.affected_users.append(u.username);
            }
        }
        visit [->:Inherits:->];
    }

    can report_users with User entry {
        if here.username not in self.affected_users {
            self.affected_users.append(here.username);
        }
    }

