Task:
Patrol two factory zones with one monitoring routine that handles both temperature sensors (alert above 75 C) and smoke sensors (alert above 50 ppm). Print every reading as nominal or an alert, and summarize the alert list at the end.

```jac
"""Factory zone monitoring.

Patrol two zones that contain a mix of temperature and smoke sensors.
A single monitoring ability handles both sensor types via a union
trigger, prints each reading as nominal or an alert, and the walker
reports the final alert list when it disengages.
"""

node Zone {
    has name: str = "";
}

node Sensor {
    has label: str = "";

    def is_alert() -> bool {
        return False;
    }
}

node TempSensor(Sensor) {
    has celsius: float = 0.0;

    override def is_alert() -> bool {
        return self.celsius > 75.0;
    }
}

node SmokeSensor(Sensor) {
    has ppm: float = 0.0;

    override def is_alert() -> bool {
        return self.ppm > 50.0;
    }
}

edge DeployedIn {
    has since: str = "";
}

walker Patrol {
    has alerts: list[str] = [];

    can start with Root entry {
        visit [->:DeployedIn:->];
    }

    can sweep with Zone entry {
        print(f"-- patrolling zone: {here.name} --");
        visit [->:DeployedIn:->];
    }

    can inspect with TempSensor | SmokeSensor entry {
        if here.is_alert() {
            tag = "ALERT";
            self.alerts.append(f"{here.label} = {here}");
        } else {
            tag = "nominal";
        }
        print(f"[{tag}] {here.label}: {here}");
    }

    can finish with Root entry {
        print("---- alert summary ----");
        if self.alerts {
            for entry in self.alerts {
                print(entry);
            }
        } else {
            print("(none)");
        }
        report self.alerts;
    }
}

