```sql
CREATE TABLE parts (
  id   BIGSERIAL PRIMARY KEY,
  name text      NOT NULL,
  category_id BIGSERIAL
);

CREATE TABLE part_categories (
  id   BIGSERIAL PRIMARY KEY,
  name text      NOT NULL,
  parent_id BIGSERIAL
);
