Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.

```jac
"""Review lifecycle after the SDD clean break.

Models the live atomic compact-v2 review lifecycle and the cascade-deletion
sweep that retires orphaned review surfaces. A walker walks the lifecycle
phases as a graph, and a Sweeper walker cascades through provider → consumer
edges to remove orphaned authority.
"""

# --- Entity archetypes ----------------------------------------------------

node Phase {
    has name: str = "";
    has label: str = "";
}

node Candidate {
    has title: str = "";
    has binding_immutable: bool = True;
}

node Reviewer {
    has badge: str = "";
    has admitted: bool = False;
}

node Correction {
    has bounded: bool = True;
    has used: bool = False;
}

node Validator {
    has evidence: str = "";
}

# --- Relationship edges ----------------------------------------------------

# Phase → next phase along the live atomic lifecycle.
edge NextPhase { }

# Phase holds the artifact it consumes (candidate, reviewer, correction,
# validator). The payload records the role name from the issue.
edge Holds {
    has role: str = "";
}

# Provider ships a capability; Consumer depends on it. Sweeper walks these
# in reverse (consumer → provider) to detect orphaned authority.
edge Provider {
    has capability: str = "";
}

edge Consumer {
    has capability: str = "";
}

# --- Walkers --------------------------------------------------------------

# Lifecycle walker: traces the live compact-v2 review pipeline and prints
# each phase. This is the traversal the issue wants preserved.
walker Lifecycle {
    can start with Root entry {
        visit [->:NextPhase:->];
    }

    can trace with Phase entry {
        print(f"[phase] {here.name} :: {here.label}");
        visit [->:NextPhase:->];
    }
}

# Audit walker: reports the contents of any lifecycle node type via a
# single union ability. Demonstrates typed traversal of artifact edges.
walker Audit {
    can start with Root entry {
        visit [->:Holds:->];
    }

    can read with Candidate | Reviewer | Correction | Validator entry {
        print(f"[holds/{here}] -> {here}");
        visit [-->];
    }
}

# Sweeper walker: cascades from a deleted consumer to its providers. When
# a provider has no remaining live consumers it is purged (orphaned). The
# walker carries an explicit visited set because Jac 0.36 has no built-in
# cycle protection on visit.
walker Sweeper {
    has visited: list[str] = [];
    has purged: list[str] = [];

    can start with Root entry {
        # Walk every Consumer edge off root to find deletion roots.
        visit [->:Consumer:->];
    }

    can cascade with Consumer entry {
        target_id = str(here);
        if target_id in self.visited {
            disengage;
        }
        self.visited.append(target_id);
        print(f"[sweep] consumer {target_id} deleted; cascading providers");
        # Every provider that fed this consumer is now a candidate for
        # orphaning. Walk back via the Consumer → Provider edges.
        visit [->:Provider:->];
    }

    can orphan with Provider entry {
        prov_id = str(here);
        if prov_id in self.visited {
            disengage;
        }
        self.visited.append(prov_id);
        # If a provider has no remaining Consumer edges it is orphaned.
        remaining_consumers = [->:Consumer:->];
        if remaining_consumers.length == 0 {
            self.purged.append(prov_id);
            print(f"[sweep] purged orphan provider {prov_id} ({here.capability})");
            del here;
        } else {
            print(f"[sweep] retained {prov_id} ({here.capability}); "
                  f"still has {remaining_consumers.length} consumer(s)");
        }
    }
}

# --- Demo wiring ----------------------------------------------------------

with entry {
    # Live compact-v2 lifecycle phases (the retained scenario).
    consent    = Phase(name="consent",    label="candidate consent");
    freeze     = Phase(name="freeze",     label="freeze");
    lenses     = Phase(name="lenses",     label="admitted lenses");
    correction = Phase(name="correction", label="at most one bounded correction");
    validation = Phase(name="validation", label="targeted validation");
    approval   = Phase(name="approval",   label="approval and burn");

    # Walk the live lifecycle forward.
    consent +>:NextPhase:+> freeze;
    freeze  +>:NextPhase:+> lenses;
    lenses  +>:NextPhase:+> correction;
    correction +>:NextPhase:+> validation;
    validation +>:NextPhase:+> approval;

    # Artifacts each phase holds (typed Holds edges with role payloads).
    cand   = Candidate(title="RFC-001 atomic review");
    rev    = Reviewer(badge="R-42");
    corr   = Correction(bounded=True, used=False);
    valid  = Validator(evidence="sha256:deadbeef");

    consent    +>:Holds(role="candidate"):+> cand;
    lenses     +>:Holds(role="reviewer"):+> rev;
    correction +>:Holds(role="correction"):+> corr;
    validation +>:Holds(role="validator"):+> valid;

    print("=== lifecycle trace ===");
    root spawn Lifecycle();

    print("\n=== artifact audit ===");
    root spawn Audit();

    # Orphan-cascade demonstration: two consumers, one provider. When both
    # consumers are deleted (by skipping them off root), the provider has
    # no live consumers and is purged by Sweeper.
    legacy_receipt = Validator(evidence="legacy-v1 receipt");
    legacy_format  = Validator(evidence="legacy-v1 format reader");

    # Provider edges feed the legacy artifacts; Consumer edges link root
    # to the deletion roots (the consumers being removed).
    root +>:Consumer(capability="legacy_receipt"):+> legacy_receipt;
    legacy_receipt +>:Provider(capability="legacy_receipt"):+> legacy_format;

    print("\n=== orphan sweep ===");
    sw = Sweeper();
    root spawn sw;
    print(f"sweeper purged: {sw.purged}");
}
```

