"""Root Vex Operations: Windows-VexLife scope walker traversing the capability lineage."""

# Core entity archetypes for the VexLife completion scope.
node Capability {
    has title: str = "";
    has acceptance_state: str = "";
}

node CompletionGroup {
    has code: str = "";
    has description: str = "";
}

node Scope {
    has name: str = "";
    has completion_state: str = "";
    has target: str = "";
}

# Typed edges: GroupContains for hierarchy, DependsOn for prerequisites, Supervises for scope oversight.
edge GroupContains { }
edge DependsOn { }
edge Supervises { }

# Walker that traverses the dependency graph of a scope, guarding against cycles.
walker CapabilityAuditor {
    has visited_titles: list[str] = [];
    has cycle_detected: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can audit with Scope entry {
        print(f"Scope: {here.name}");
        print(f"  state = {here.completion_state}");
        print(f"  target = {here.target}");
        visit [->:Supervises:->];
    }

    can audit_group with CompletionGroup entry {
        print(f"  Group {here.code}: {here.description}");
        visit [->:GroupContains:->];
    }

    can audit_cap with Capability entry {
        if here.title in self.visited_titles {
            self.cycle_detected = True;
            print(f"  [CYCLE] already saw {here.title}");
            disengage;
        }
        self.visited_titles.append(here.title);
        status = "ACCEPTED" if here.acceptance_state == "accepted" else "PENDING";
        print(f"    [{status}] {here.title}");
        visit [->:DependsOn:->];
    }
}

