"""Fighter advancements view: model the N+1 prefetch gap with native graph traversal.

The original Django view fetches a fighter and then triggers an extra query
when the template touches the fighter's content_fighter. The idiomatic Jac
model uses a walker that traverses the typed Fighter -> ContentFighter edge
once during the visit and accumulates the result, so the "prefetch" is
explicit in the graph walk rather than implicit in a query hint.
"""

# --- Entity archetypes -------------------------------------------------------

node ContentFighter {
    has name: str = "";
    has house: str = "";
    has fighter_type: str = "";
}

node Skill {
    has name: str = "";
    has xp_cost: int = 0;
}

node CampaignAction {
    has name: str = "";
    has xp_cost: int = 0;
}

node Fighter {
    has name: str = "";
    has list_id: int = 0;
    has archived: bool = False;
}

node Advancement {
    has description: str = "";
    has awarded_xp: int = 0;
}

# --- Relationship archetypes -------------------------------------------------

edge Models { }       # ContentFighter -- Fighter       (the template-needed link)
edge Granted { }      # Fighter -- Advancement          (owning fighter -> advancement)
edge OfSkill { }      # Advancement -- Skill            (optional skill reference)
edge OfAction { }     # Advancement -- CampaignAction   (optional action reference)

# --- Walker ------------------------------------------------------------------

walker ListAdvancements {
    has fighter_id: int = 0;
    has results: list = [];

    can start with Root entry {
        visit [-->];
    }

    can locate with Fighter entry {
        # Match the requested fighter (mimics get_object_or_404 lookup).
        if here.list_id != self.fighter_id or here.archived {
            visit [-->];
            return;
        }
        # "Prefetch" by traversing the Models edge once, exactly as the
        # template would when it touches content_fighter fields. In idiomatic
        # Jac the relationship is a first-class edge, so there is no N+1:
        # one visit, one hop, content in hand.
        visit [->:Models:->];
    }

    can gather with ContentFighter entry {
        # We have arrived at the prefetched content_fighter. Record its data
        # and then walk the fighter's advancements through the Fighter we
        # came from.
        self.results.append({
            "content_name": here.name,
            "content_house": here.house,
            "content_type": here.fighter_type,
        });
        # Back-track: the Grantede edge lives between Fighter and Advancement,
        # so we move to a Fighter first by following the reverse Models edge.
        visit [<--:Models:--];
    }

    can accumulate with Fighter entry {
        # Now visit all advancements granted to this fighter.
        visit [->:Granted:->];
    }

    can record with Advancement entry {
        entry: dict = {"desc": here.description, "xp": here.awarded_xp};
        if here --> OfSkill {
            sk = here ->[?:OfSkill]->[0];
            entry["skill"] = sk.name;
            entry["skill_xp"] = sk.xp_cost;
        }
        if here --> OfAction {
            ac = here ->[?:OfAction]->[0];
            entry["action"] = ac.name;
            entry["action_xp"] = ac.xp_cost;
        }
        self.results.append(entry);
    }

    def report() -> list {
        return self.results;
    }
}

# --- Demonstration wiring ----------------------------------------------------

with entry {
    # A small content fighter catalogue.
    ganger = ContentFighter(name="Ganger", house="Delaque", fighter_type="Gang Member");
    champ = ContentFighter(name="Champion", house="Cawdor", fighter_type="Leader");

    # Two list-fighters (archived flag mimics the archived_at__isnull filter).
    f1 = Fighter(name="Slink", list_id=42, archived=False);
    f2 = Fighter(name="Vex", list_id=42, archived=False);

    # Skills and campaign actions.
    sk_stealth = Skill(name="Stealth", xp_cost=3);
    sk_ballistic = Skill(name="Ballistics", xp_cost=4);
    ac_promote = CampaignAction(name="Promote", xp_cost=5);
    ac_territory = CampaignAction(name="Hold Territory", xp_cost=2);

    # Advancements with their optional references.
    a1 = Advancement(description="Learned to move unseen", awarded_xp=3);
    a2 = Advancement(description="Sharpened aim", awarded_xp=4);
    a3 = Advancement(description="Promoted to Champion", awarded_xp=5);
    a4 = Advancement(description="Held a scrap patch", awarded_xp=2);

    # Wire the graph:
        # ContentFighter <-Models-- Fighter <-Granted-- Advancement
        #                                  ^----OfSkill---- Skill
        #                                  ^----OfAction--- CampaignAction
    f1 +>:Models:+> ganger;
    f2 +>:Models:+> champ;
    f1 +>:Granted:+> a1;
    a1 +>:OfSkill:+> sk_stealth;
    f1 +>:Granted:+> a2;
    a2 +>:OfSkill:+> sk_ballistic;
    f2 +>:Granted:+> a3;
    a3 +>:OfAction:+> ac_promote;
    f2 +>:Granted:+> a4;
    a4 +>:OfAction:+> ac_territory;

    # Make the fighters reachable from root so the walker can find them.
    root ++> f1 ++> f2;

    # Spawn the walker on the requested fighter (mimics the view entry point).
    root spawn ListAdvancements(fighter_id=42);

    # Note: in the original Django view the template would silently trigger
    # one extra SQL query per fighter to fetch content_fighter. Here the
    # walker visits the Models edge explicitly and accumulates the prefetched
    # data on the walker itself, with no extra hops.
}
