"""Generic constraint dependency graph: monomorphize items and resolve
their `where`-clause constraints in declaration order, detecting cyclic
constraints and cascading invalidation when a dependency fails.
"""

node Item {
    has name: str = "";
    has kind: str = "";          # "fn", "struct", "enum"
    has valid: bool = True;
    has constraint_expr: str = ""; # symbolic constraint text
}

edge Depends {
    # typed edge: Item A depends on Item B for its `where` clause
    has weight: int = 1;
}

walker ConstraintResolver {
    has report: list = [];
    has visiting: list = [];     # path stack for cycle detection
    has seen: list = [];         # nodes already resolved this pass

    def push(node) {
        self.report.append(f"resolving {node.name} ({node.kind})");
        if node.name in self.visiting {
            cycle = " -> ".join(self.visiting) + " -> " + node.name;
            self.report.append(f"  CYCLE DETECTED: {cycle}");
            node.valid = False;
            self.invalidate_upstream(node);
            return;
        }
        if node.name in self.seen {
            self.report.append(f"  already resolved");
            return;
        }
        self.visiting.append(node.name);
