        visit [here ->:Depends:->];
        # After dependencies are processed, validate self
        self.visiting.pop();
        self.seen.append(node.name);
        if node.valid {
            self.report.append(
                f"  OK: {node.constraint_expr} -> Constraint::Valid"
            );
        } else {
            self.report.append(
                f"  FAIL: {node.constraint_expr} -> Constraint::Invalid"
            );
        }
    }

    def invalidate_upstream(node) {
        # Cascade invalidation: any item depending (directly or
        # transitively, walked backwards) on `node` is also invalid.
        visit [<--];
    }

