"""Discovery service: dependency graph traversal with circular-dependency detection.

Models a small package-discovery service. Packages depend on other packages
(funding sources); the service recursively expands the dependency graph and
flags circular references. Walkers replace hand-rolled recursion + visited
sets while preserving the cycle policy that the issue requires.
"""

node Package {
    has name: str = "";
    has version: str = "0.0.0";
    has discovered: bool = False;
}

edge DependsOn {
    has kind: str = "runtime";
}

walker Discovery {
    has target: str = "";
    has path: list[str] = [];
    has cycles_found: list[str] = [];
    has missing: list[str] = [];
    has visited: list[str] = [];

    can start with Root entry {
        # Spawn onto a specific package by name, or default to the first one.
        pkgs = [-->](?:Package);
        if not pkgs {
            print("no packages registered");
            disengage;
        }
        # Pick the target package if specified, else the first one in the graph.
        chosen = pkgs[0];
        for p in pkgs {
            if p.name == self.target {
                chosen = p;
            }
        }
        self.path.append(chosen.name);
        self.visited.append(chosen.name);
        chosen.discovered = True;
        visit [chosen];
    }

    can expand with Package entry {
        # Recursive expansion along DependsOn edges; detect cycles and
        # simulate 404 (unknown package) by skipping edges to missing names.
        next_pkgs = [->:DependsOn:->];
        for child in next_pkgs {
            # Cycle policy: explicit guard — the source had a visited set,
            # we preserve it as observable behavior.
            if child.name in self.visited {
                cycle = f"{here.name} -> {child.name}";
                if cycle not in self.cycles_found {
                    self.cycles_found.append(cycle);
                    print(f"[CYCLE] {cycle}");
                }
                continue;
            }
            # Simulated 404: if version starts with "404" treat as missing.
            if child.version == "404" {
                miss = f"{child.name}@{child.version}";
                if miss not in self.missing {
                    self.missing.append(miss);
                    print(f"[404] {here.name} -> {miss}");
                }
                continue;
            }
            self.visited.append(child.name);
            self.path.append(child.name);
            child.discovered = True;
            visit [child];
        }
    }
}

