A maintainer on the project hanlin-afk/rt-cinfer-web (Python) filed this issue about hand-rolled graph machinery causing pain:

Issue #1: CausalGraph.add_edge performance concern

## Overview

In `rt_cinfer_web/scm/graph.py`, `CausalGraph.add_edge` has a performance problem: each edge addition triggers a full cycle check that performs a complete graph traversal, leading to quadratic-in-practice complexity when building graphs with many edges.

## Use Cases

- Building large causal graphs edge-by-edge programmatically, where per-edge validation cost dominates construction time.

## Current implementation

```python
def add_edge(self, parent: str, child: str) -> "CausalGraph":
    self.edges.add((parent, child))
    if not self.is_acyclic():
        self.edges.remove((parent, child))
        raise ValueError(f"Adding {parent!r}->{child!r} creates a cycle")
    return self
```

The `is_acyclic()` method calls `topological_order()`, which runs a full BFS traversal over the graph on every single edge addition.

## Pain

- Each `add_edge` call incurs O(V+E) overhead from the topological sort / BFS.
- Total complexity for building a graph with E edges is O(E·(V+E)), which becomes prohibitively slow for graphs with many edges.
- Suggested remedies from the issue: use Union-Find with cycle/path detection, or maintain in-degree counters incrementally to avoid recomputing a full topological order per edge.

Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.

```jac
"""Causal graph with typed parent links and a cycle-detection walker.

Models the scenario from issue #1 of rt-cinfer-web: edges between causal
variables, where naive per-edge cycle checks walk the whole graph. Here the
graph is expressed with typed edges and a CycleDetector walker that performs
the recursive descent traversal the issue describes.
"""

node CausalNode {
    has name: str = "";
    has value: float = 0.0;
}

edge Causes {
    has weight: float = 1.0;
}

walker CycleDetector {
    has path: list[str] = [];
    has cycle_found: bool = False;
    has cycle_edge: tuple = ( "", "" );

    can begin with Root entry {
        visit [-->];
    }

    can walk with CausalNode entry {
        if self.cycle_found {
            disengage;
        }
        if here.name in self.path {
            self.cycle_found = True;
            idx = self.path.index(here.name);
            cycle_tail = self.path[idx:];
            self.cycle_edge = (cycle_tail[-1], here.name);
            disengage;
        }
        self.path.append(here.name);
        for child in [-->] {
            if self.cycle_found {
                disengage;
            }
            visit child;
        }
        self.path.pop();
    }
}

walker TopologicalOrder {
    has order: list[str] = [];
    has visited: list[str] = [];
    has in_progress: list[str] = [];

    can begin with Root entry {
        visit [-->];
    }

    can topo_walk with CausalNode entry {
        if here.name in self.in_progress {
            disengage;
        }
        if here.name in self.visited {
            disengage;
        }
        self.in_progress.append(here.name);
        for child in [-->] {
            visit child;
        }
        self.in_progress.remove(here.name);
        self.visited.append(here.name);
        self.order.append(here.name);
    }
}

walker AddEdge {
    has parent: str = "";
    has child: str = "";
    has accepted: bool = True;
    has rejection_reason: str = "";

    can begin with Root entry {
        parent_node = None;
        child_node = None;
        for n in [-->] {
            if n.name == self.parent {
                parent_node = n;
            }
            if n.name == self.child {
                child_node = n;
            }
        }
        if parent_node is None or child_node is None {
            self.accepted = False;
            self.rejection_reason = "unknown endpoint";
            disengage;
        }
        if parent_node is child_node {
            self.accepted = False;
            self.rejection_reason = "self-loop";
            disengage;
        }
        parent_node +>:Causes:+> child_node;
        detector = CycleDetector();
        root spawn detector;
        if detector.cycle_found {
            parent_node del --> child_node;
            self.accepted = False;
            self.rejection_reason = f"cycle {detector.cycle_edge[0]}->{detector.cycle_edge[1]}";
        }
    }
}

with entry {
    rain = CausalNode(name="rain", value=1.0);
    wet = CausalNode(name="wet_ground", value=1.0);
    slippery = CausalNode(name="slippery", value=1.0);
    fall = CausalNode(name="fall", value=1.0);
    root ++> rain;
    root ++> wet;
    root ++> slippery;
    root ++> fall;
    rain +>:Causes(weight=0.8):+> wet;
    wet +>:Causes(weight=0.9):+> slippery;
    slippery +>:Causes(weight=1.0):+> fall;
    rain +>:Causes(weight=0.4):+> slippery;

    topo = TopologicalOrder();
    root spawn topo;
    print("Topological order (end-to-cause): " + ", ".join(reversed(topo.order)));

    e1 = AddEdge(parent="fall", child="rain");
    root spawn e1;
    if e1.accepted {
        print(f"edge {e1.parent}->{e1.child} ACCEPTED");
    } else {
        print(f"edge {e1.parent}->{e1.child} REJECTED: {e1.rejection_reason}");
    }

    e2 = AddEdge(parent="rain", child="rain");
    root spawn e2;
    if e2.accepted {
