```jac
"""Issue lifecycle: live refresh, grounding, and safe delivery routing.

Models the per-issue gate described in issue #272:
  1. Live refresh -- the issue is re-checked against its current state.
  2. Read-only grounding -- the issue is anchored against its dependencies.
  3. Complexity routing -- actionable issues go through 0-3 implementation or
     4-5 decomposition; already-resolved issues require fresh concrete
     verification evidence.
A `needs_attention` flag records the decision + fingerprint without closing
the issue, and unresolved / uncertain verification is a non-completion
failure (never an automatic closure).
"""

# ---------------------------------------------------------------------------
# Entity archetypes
# ---------------------------------------------------------------------------

node Issue {
    has title: str = "";
    has state: str = "open";          # open | resolved | failed
    has complexity: int = 0;          # 0..5
    has fingerprint: str = "";        # freshness fingerprint
    has needs_attention: bool = False;
    has verification: str = "";       # "" | "fresh" | "stale" | "uncertain"
}

node Dependency {
    has title: str = "";
    has satisfied: bool = False;
}

# Typed edges -- the relationships carry meaning.
edge DependsOn { }
edge GroundedBy { }
edge RoutedTo { }
edge VerifiedBy { }

# ---------------------------------------------------------------------------
# Walker: LifecycleGate -- the per-issue gate described in the issue.
# ---------------------------------------------------------------------------

walker LifecycleGate {
    has decisions: list[dict] = [];

    # Start at the root, fan out to the issue we are gating.
    can start with Root entry {
        visit [-->];
    }

    # 1) Live refresh on an Issue.
    can refresh with Issue entry {
        # If the issue is already marked needs_attention, skip refresh --
        # the fingerprint has already been recorded.
        if not here.needs_attention {
            here.fingerprint = f"fp:{here.title}:{here.state}";
        }
        visit [->:GroundedBy:->];
    }

    # 2) Read-only grounding -- walk dependencies and record whether they
    # are satisfied. Grounding never mutates the dependency nodes.
    can ground with Dependency entry {
        if here.satisfied {
            report = f"grounded: {here.title} (satisfied)";
        } else {
            report = f"grounded: {here.title} (UNSATISFIED)";
        }
        visit [->:DependsOn:->];
    }

    # 3) Complexity routing -- once grounded, route the issue.
    can route with Issue entry {
        decision = "";
        if here.state == "resolved" {
            # Already-resolved: require fresh concrete verification evidence.
            if here.verification == "fresh" {
                decision = "close";
            } elif here.verification == "uncertain" or here.verification == "" {
                # Non-completion failure -- never an automatic closure.
                here.needs_attention = True;
                decision = "fail:verification";
            } else {
                # stale evidence is also a non-completion failure
                here.needs_attention = True;
                decision = "fail:stale";
            }
        } else {
            # Actionable: 0-3 implementation, 4-5 decomposition.
            if here.complexity <= 3 {
                decision = "implement";
            } else {
                decision = "decompose";
            }
        }

        self.decisions.append({
            "issue": here.title,
            "complexity": here.complexity,
            "state": here.state,
            "verification": here.verification,
            "decision": decision,
            "needs_attention": here.needs_attention,
        });

        # Traverse onward through any routing edges.
        visit [->:RoutedTo:->];
    }

    # Verifications are leaves -- nothing to traverse.
    can verify with Dependency entry {
        visit [->:VerifiedBy:->] else { disengage; }
    }
}

# ---------------------------------------------------------------------------
# Walker: SafeSkipAuditor -- proves the safe-skip behavior described in the
# issue: decision + fingerprint recorded, source stays open, queue may
# continue, no `lgtm` closure, no PR/feature-branch delivery.
# ---------------------------------------------------------------------------

walker SafeSkipAuditor {
    has safe_skips: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can audit with Issue entry {
        if here.needs_attention {
            # Source issue stays open -- safe skip must NOT mutate state.
            assert here.state == "open";
            self.safe_skips.append(here.title);
        }
        visit [-->];
    }
}

# ---------------------------------------------------------------------------
# Demonstration
# ---------------------------------------------------------------------------

with entry {
    # Issue A: actionable, low complexity -> implement.
    issue_a = Issue(title="A", state="open", complexity=2);

    # Issue B: actionable, high complexity -> decompose.
    issue_b = Issue(title="B", state="open", complexity=5);

    # Issue C: already-resolved with fresh evidence -> safe to close.
    issue_c = Issue(title="C", state="resolved", verification="fresh");

    # Issue D: already-resolved but uncertain -> non-completion failure,
    # safe skip (no closure, no PR delivery).
    issue_d = Issue(
        title="D",
        state="resolved",
        verification="uncertain",
        needs_attention=True,
    );

    # Dependencies for grounding.
    dep_x = Dependency(title="dep-X", satisfied=True);
    dep_y = Dependency(title="dep-Y", satisfied=True);
    dep_z = Dependency(title="dep-Z", satisfied=False);

    # Wire the gate topology: Root -> Issue -> GroundedBy -> Dependency
    # -> DependsOn -> ... -> RoutedTo -> Issue (re-visit for routing).
    root ++> issue_a +>:GroundedBy:+> dep_x +>:DependsOn:+> dep_x;
    root ++> issue_b +>:GroundedBy:+> dep_y +>:DependsOn:+> dep_y;
    root ++> issue_c +>:GroundedBy:+> dep_z +>:DependsOn:+> dep_z;
    root ++> issue_d;

    # Link routing back to the original issue so the walker can route.
    issue_a +>:RoutedTo:+> issue_a;
    issue_b +>:RoutedTo:+> issue_b;
    issue_c +>:RoutedTo:+> issue_c;
    issue_d +>:RoutedTo:+> issue_d;

    # Run the per-issue lifecycle gate.
    gate = LifecycleGate();
    root spawn gate;
    for d in gate.decisions {
        print(f"{d['issue']} -> {d['decision']} "
              f"(state={d['state']}, cx={d['complexity']}, "
              f"ver={d['verification']}, na={d['needs_attention']})");
    }

    # Run the safe-skip auditor to confirm safe-skip semantics.
    auditor = SafeSkipAuditor();
    root spawn auditor;
    print(f"safe skips recorded (issue stays open, no closure): "
          f"{auditor.safe_skips}");
}
