```jac
"""Factory patrol: one monitoring routine handles both temperature and smoke sensors, printing readings and summarizing alerts."""

node Sensor {
    has label: str = "";
    def is_alert() -> bool;
}

node TempSensor(Sensor) {
    has celsius: float = 0.0;
    def is_alert() -> bool;
}

node SmokeSensor(Sensor) {
    has ppm: float = 0.0;
    def is_alert() -> bool;
}

node Zone {
    has zone_name: str = "";
}

edge DeployedIn {
    has since: str = "";
}

walker Patrol {
    has alert_count: int = 0;

    can start with Root entry {
        print("=== Beginning factory patrol ===");
        visit [->:DeployedIn:->];
    }

    can sweep with Zone entry {
        print(f"--- Sweeping zone: {here.zone_name} ---");
        visit [->:DeployedIn:->];
    }

    can inspect with TempSensor | SmokeSensor entry {
        if here.is_alert() {
            print(f"[ALERT] {here.label}: reading exceeds threshold");
            self.alert_count += 1;
        } else {
            print(f"nominal: {here.label} reading within range");
        }
    }
}

