    has display_id: str = "";
    has label: str = "";
    has pinned: bool = False;
}

# ---------- relationship archetypes ----------

# Each typed edge has a payload field for the kind of work the layer did.
edge Next {
    has work: int = 0;  # O(n) cost units charged for this hop
}

# Marks a node as part of the "prefix" that should be reused as-is.
edge Reused {
    has reason: str = "";
}

# ---------- the four-layer pipeline ----------
# root --> Block --> Message --> MergedMessage --> DisplayItem --> Visible

node Visible {
    has visible_id: str = "";
    has final_text: str = "";
}

edge Finalized {}  # terminal marker from DisplayItem into Visible

