"""Event polling with concurrency control.

Models the issue's core concern: a 10-second poll loop where overlapping
requests stack up. The idiomatic Jac form makes the poll chain a walker
traversal: one poll is in-flight at a time, the next visit only starts
after the current one reports, and failures trigger exponential backoff
tracked on the walker itself.
"""

# ---- Entity archetypes -----------------------------------------------------

node EventSource {
    has name: str = "";
    has endpoint: str = "";
    has payload: str = "ok";
    has fail_streak: int = 0;
    has max_streak: int = 2;
}

node PollTick {
    has label: str = "";
    has fired: bool = False;
}

node BackoffState {
    has current_delay_ms: int = 10000;
    has attempt: int = 0;
}

# ---- Relationship archetypes ----------------------------------------------

edge Polls {
    has interval_ms: int = 10000;
}

edge Follows {
    has gap_ms: int = 0;
}

# ---- Walker: one in-flight poll at a time, recursive-setTimeout style -----

walker Poller {
    has poll_count: int = 0;
    has total_failures: int = 0;
    has max_polls: int = 5;
    has base_interval_ms: int = 10000;
    has max_delay_ms: int = 60000;

    can begin with Root entry {
        print(f"poller armed: base={self.base_interval_ms}ms cap={self.max_polls} polls");
        visit [-->];
    }

    # Tick fires once per poll slot. Reads the next edge's interval
    # (a "delay") and then forwards to the EventSource it polls.
    can tick with PollTick entry {
        if here.fired {
            disengage;
        }
        here.fired = True;
        edge_gap = 0;
        for (_, e) in [-->]:Polls {
            edge_gap = e.interval_ms;
        }
        print(f"  tick '{here.label}' scheduled after {edge_gap}ms");
        visit [-->];
    }

    # The actual fetch + backoff decision lives here. Mirrors the issue's
    # recursive setTimeout pattern: next visit starts only after this one
    # reports, failures multiply the next delay up to a cap.
    can fetch with EventSource entry {
        self.poll_count += 1;
        will_fail = here.fail_streak < here.max_streak;
        if will_fail {
            self.total_failures += 1;
            here.fail_streak += 1;
