```jac
"""Factory zone monitoring with a single patrol routine for both sensor types.

One walker ability handles two sensor archetypes via a union trigger,
printing each reading as nominal or an alert, and summarizing the
alerts at the end.
"""

node Sensor {
    has label: str = "";
    has reading: float = 0.0;

    def is_alert() -> bool {
        return False;
    }

    def kind() -> str {
        return "Sensor";
    }
}

node TempSensor(Sensor) {
    has celsius: float = 0.0;

    override def is_alert() -> bool {
        return self.celsius > 75.0;
    }

    override def kind() -> str {
        return "TempSensor";
    }
}

node SmokeSensor(Sensor) {
    has ppm: float = 0.0;

    override def is_alert() -> bool {
        return self.ppm > 50.0;
    }

    override def kind() -> str {
        return "SmokeSensor";
    }
}

node Zone {
    has name: str = "";
}

edge DeployedIn {
    has since: str = "";
}

walker Patrol {
    has alert_log: list[str] = [];
    has nominal_count: int = 0;
    has alert_count: int = 0;

    can start with Root entry {
        visit [->:DeployedIn:->];
    }

    can sweep with Zone entry {
        print(f"--- Patrolling zone: {here.name} ---");
        visit [->:DeployedIn:->];
    }

    can inspect with TempSensor | SmokeSensor entry {
        reading_label = "alert" if here.is_alert() else "nominal";
        if here.is_alert() {
            self.alert_count += 1;
            line = f"[ALERT]   {here.kind()} '{here.label}' -> {here.reading}";
            self.alert_log.append(line);
        } else {
            self.nominal_count += 1;
            line = f"[nominal] {here.kind()} '{here.label}' -> {here.reading}";
        }
        print(line);
    }
}

