```jac
"""ECS lock-order tracker: model the held-others snapshot and the
enabled-check fast path that the issue says is documented as
"one relaxed load" but in debug builds allocates first.

The walker mirrors the hand-rolled recursion the bug report
describes: a LockTracker walks the held-locks map (here, a
typed edge `HeldBy` connecting Lock nodes to the resources
currently held), building a snapshot Vec *before* it checks
whether the order checker is even enabled. The demo shows
both the misordered path and the hoisted fix.
"""

# ---- entities ------------------------------------------------------------

node LockResource {
    # Mirrors the &'static str type_name used by the tracker.
    has type_name: str = "";
}

node LockTracker {
    has debug_mode: bool = True;
    has enabled: bool = False;
    # Snapshot materialised by the buggy path; empty == fast path elided.
    has snapshot: list[tuple[str, str]] = [];
    # Number of times the snapshot allocator actually ran.
    has allocations: int = 0;
    # Did the walker short-circuit on emptiness / disabled flag?
    has short_circuited: bool = False;
    # Did the walker do the (cheap) "one relaxed load" fast path?
    has fast_path: bool = False;
}

# Typed edge: Tracker --HeldBy--> LockResource. Carries no payload here;
# the relationship itself (a resource currently held) is what matters.
edge HeldBy { }

# ---- walkers -------------------------------------------------------------

walker AcquireLock {
    # Walker-local state: the resource it wants to acquire this step.
    has target: str = "";

    can start with Root entry {
        # Find a tracker on Root and grab the first held lock from it.
        visit [-->];
    }

    can land with LockTracker entry {
        # ---- BUGGY PATH (mirrors lock_tracker.rs:115-122) -------------
        # Materialise the snapshot BEFORE checking enabled.
        snap = self.snapshot_held(here);
        # ---- FIXED PATH (mirrors the issue's "Suggested Fix") -----------
        # Hoist both checks above the snapshot.
        if snap is not None and len(snap) > 0 and here.enabled {
            here.snapshot = snap;
            here.allocations += 1;
            print(f"[buggy]   allocated snapshot of {len(here.snapshot)} held locks for acquire({self.target})");
        } else if len(snap) == 0 or not here.enabled {
            here.fast_path = True;
            here.short_circuited = True;
            reason = "empty" if len(snap) == 0 else "disabled";
            print(f"[fast]    one relaxed load -> short-circuit ({reason}) for acquire({self.target})");
        }
        # Recurse into held locks (mirrors recursion over locks.borrow().iter()).
        visit [->:HeldBy:->];
    }

    can scan with LockResource entry {
        # Touching a held resource is just bookkeeping; the recursion
        # is the point. No further visit: leaves return on their own.
        return;
    }

    def snapshot_held(tracker: LockTracker) -> list[tuple[str, str]] {
        # Pretend this is the heap-allocating collect.
        if tracker.debug_mode and tracker.snapshot == [] {
            return [("Transform", "Transform"), ("NameIndex", "NameIndex")];
        }
        return [];
    }
}

walker Inspector {
    can start with Root entry {
        visit [-->];
    }

    can audit with LockTracker entry {
        status = "BUG" if here.allocations > 0 else "OK";
        print(f"[audit] tracker debug={here.debug_mode} enabled={here.enabled} "
              f"allocations={here.allocations} fast_path={here.fast_path} -> {status}");
        visit [-->];
    }
}

# ---- demo ----------------------------------------------------------------

with entry {
    # Two trackers: one with checker disabled (the issue's default
    # `BYRO_LOCK_ORDER_CHECK` unset), one with it on. Both run in debug.
    off_tracker = LockTracker(debug_mode=True, enabled=False);
    on_tracker = LockTracker(debug_mode=True, enabled=True);

    # Held resources, connected via typed edges -- the relationship
    # "this tracker currently holds these locks" carries meaning.
    transform = LockResource(type_name="Transform");
    name_idx = LockResource(type_name="NameIndex");
    anim_clip = LockResource(type_name="AnimationClipRegistry");

    off_tracker +>:HeldBy:+> transform;
    off_tracker +>:HeldBy:+> name_idx;

    on_tracker +>:HeldBy:+> transform;
    on_tracker +>:HeldBy:+> name_idx;
    on_tracker +>:HeldBy:+> anim_clip;

    root ++> off_tracker ++> on_tracker;

    # Spawn an acquisition walker per tracker; the walker reaches into
    # the tracker via typed-edge traversal and (mis)orders the snapshot
    # allocation the way the Rust code does today.
    root spawn AcquireLock(target="Transform");
    root spawn AcquireLock(target="AnimationClipRegistry");

    # Audit both trackers to make the bug visible: the disabled one
    # should report allocations=0 with fast_path=True; the enabled one
    # is allowed to allocate.
    Inspector() spawn root;
}
```

