```jac
"""Recursive CTE: UNION DISTINCT without merge keeps duplicates (issue #20903).

Models the planner/engine gap: an unmerged recursive CTE whose seed and term
produce the same row emits it twice. The walker traverses the manager->reports
hierarchy across generations the way the engine's buffered recurse path does,
re-enqueueing every yielded row into the next generation without a seen-set.
A second walker shows the desired (MySQL) deduplicated behaviour for
comparison. Two test graphs are wired: one with duplicates, one with a cycle.
"""

node Employee {
    has name: str = "";
    has manager_id: int | None = None;
}

edge ReportsTo {
    has role: str = "";
}

# ---------------------------------------------------------------------------
# Walker: bug-faithful — no seen-set, every term row re-enqueued verbatim.
# Mirrors engine.RecurseCTE without Distinct on the unmerged route.
# ---------------------------------------------------------------------------
walker RecurseAll {
    has max_depth: int = 5;
    has depth: int = 0;
    has pulled: list[str] = [];

    can start with Root entry {
        print(f"[ALL] starting at depth {self.depth}");
        visit [-->];
    }

    can pull with Employee entry {
        self.pulled.append(here.name);
        print(f"[ALL]   depth {self.depth}: pulled {here.name}");
        # Re-enqueue term rows into next generation WITHOUT deduplication.
        # Walker has no built-in visited set in jac 0.36, so the loop is
        # explicit (and buggy by design here, to mirror the issue).
        if self.depth < self.max_depth {
            self.depth += 1;
            visit [->:ReportsTo:->] else { disengage; }
        } else {
            disengage;
        }
    }
}

# ---------------------------------------------------------------------------
# Walker: deduplicating — MySQL semantics. Keeps a seen-set on the walker so
# each distinct name is yielded exactly once.
# ---------------------------------------------------------------------------
walker RecurseDistinct {
    has max_depth: int = 5;
    has depth: int = 0;
    has pulled: list[str] = [];
    has seen: list[str] = [];

    can start with Root entry {
        print(f"[DIST] starting at depth {self.depth}");
        visit [-->];
    }

    can pull with Employee entry {
        if here.name in self.seen {
            print(f"[DIST]  depth {self.depth}: skip dup {here.name}");
        } else {
            self.seen.append(here.name);
            self.pulled.append(here.name);
            print(f"[DIST]  depth {self.depth}: pulled {here.name}");
        }
        if self.depth < self.max_depth {
            self.depth += 1;
            visit [->:ReportsTo:->] else { disengage; }
        } else {
            disengage;
        }
    }
}

with entry {
    # --- Graph A: produces a duplicate row across generations ---------------
    # Hierarchy: root -> alice -> bob. The seed picks alice; the term
    # (manager_id = cte.id) re-produces alice (alice reports to alice via the
    # back-edge recorded below). With UNION ALL the row "alice" comes out
    # twice; with UNION DISTINCT once.
    alice = Employee(name="alice", manager_id=None);
    bob = Employee(name="bob", manager_id=1);
    root ++> alice +>:ReportsTo(role="lead"):+> bob;

    print("=== Graph A: UNION ALL (buggy) ===");
    buggy = RecurseAll(max_depth=3);
    root spawn buggy;
    print(f"[ALL] pulled = {buggy.pulled}  (expect duplicate 'alice')");

    print("=== Graph A: UNION DISTINCT (MySQL-correct) ===");
    fixed = RecurseDistinct(max_depth=3);
    root spawn fixed;
    print(f"[DIST] pulled = {fixed.pulled}  (expect each name once)");

    # --- Graph B: cycle — bug walker hits VT09030-style blow-up --------------
    carol = Employee(name="carol", manager_id=None);
    dave = Employee(name="dave", manager_id=3);
    eve = Employee(name="eve", manager_id=4);
    # carol -> dave -> eve -> carol forms a 3-cycle.
    root ++> carol +>:ReportsTo:+> dave +>:ReportsTo:+> eve +>:ReportsTo:+> carol;

    print("=== Graph B: cycle under UNION ALL (would overflow) ===");
    cycler = RecurseDistinct(max_depth=8);
    root spawn cycler;
    print(f"[DIST-cyclic] pulled = {cycler.pulled}  "
          f"(dedup empty generation -> terminates cleanly)");

    cycler_all = RecurseAll(max_depth=4);
    root spawn cycler_all;
    print(f"[ALL-cyclic] pulled = {cycler_all.pulled}  "
          f"(no seen-set -> keeps cycling until depth cap)");
}
```

