"""Delivery route dispatch checker.

Each route carries a cargo weight in tonnes. A truck may only be dispatched
when its load is at least 2 tonnes and at most 8 tonnes on the same leg.
A dispatcher walker walks the routes from each depot and reports which
routes qualify for dispatch.
"""

node Route {
    has destination: str = "";
    has weight: float = 0.0;

    def qualifies() -> bool {
        return self.weight >= 2.0 and self.weight <= 8.0;
    }
}

node Depot {
    has name: str = "";

    can dispatch with Route entry {
        if here.qualifies() {
            print(f"[DISPATCH] {self.name} -> {here.destination} ({here.weight}t)");
        } else {
            print(f"[SKIP] {self.name} -> {here.destination} ({here.weight}t out of range)");
        }
        visit [-->];
    }
}

walker Dispatcher {
    has dispatch_count: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can at_depot with Depot entry {
        visit [-->];
    }

    can check_route with Route entry {
        if here.qualifies() {
            self.dispatch_count += 1;
            print(f"[DISPATCH] {here.destination} ({here.weight}t qualifies)");
        } else {
            print(f"[SKIP] {here.destination} ({here.weight}t out of 2-8t range)");
        }
        visit [-->] else { disengage; }
    }
}

with entry {
    north = Depot(name="North Depot");
    south = Depot(name="South Depot");
    root ++> north ++> Route(destination="Springfield", weight=5.5)
                 ++> Route(destination="Shelbyville", weight=1.2)
                 ++> Route(destination="Capital City", weight=7.8);
    root ++> south ++> Route(destination="Ogdenville", weight=3.0)
                 ++> Route(destination="North Haverbrook", weight=9.5)
                 ++> Route(destination="Brockway", weight=2.0);

    d = Dispatcher();
    root spawn d;
    print(f"\nTotal routes dispatched: {d.dispatch_count}");
}
