Task:
A maintainer on the project nano-step/nano-brain (unknown) filed this issue about hand-rolled graph machinery causing pain:

Issue #378: feat(graph): track reverse import edges for impact analysis

## Problem

`memory_impact` cannot answer \"who imports this file/package?\" — the knowledge graph only tracks forward edges.

**Observed behavior** (tested live against nano-brain itself):

```
memory_impact(node="internal/watcher/filter.go::newFileFilter", max_depth=3)
→ {"count":1, "impacted":[{"node":"internal/watcher/filter.go", "edge_type":"contains"}]}
```

Only returns the containing file. Does not surface the 5 callers that actually import `internal/watcher`:
- `cmd/nano-brain/main.go`
- `internal/server/server.go`
- `internal/server/handlers/collection.go`
- `internal/server/handlers/reindex.go`
- `internal/server/handlers/workspace.go`

**Root cause:** The graph stores `file → imports → package` edges (outbound only). The `in` direction query returns 0 results for any file/package node because reverse edges are not stored.

## Use case

This is the core value proposition for multi-repo users:

> "I'm changing the redis key prefix from `latest:` to `later:` in repo A. Which other repos in my workspace use this key?"

Currently, `memory_impact` cannot answer this. `memory_search` can find text matches but doesn't traverse the dependency graph.

## Expected behavior

```
memory_impact(node="internal/watcher/filter.go", direction="in")
→ [
    "cmd/nano-brain/main.go",          -- imports watcher
    "internal/server/server.go",       -- imports watcher
    "internal/server/handlers/collection.go",
    "internal/server/handlers/reindex.go",
    "internal/server/handlers/workspace.go"
  ]
```

## Implementation sketch

During symbol extraction, when processing `file A` that contains `import "pkg/B"`, store **both** edges:
- `A → imports → B` (already done)
- `B ← imported_by ← A` (missing)

The `memory_impact` traversal (reverse lookup) then queries `imported_by` edges to find all dependents at each depth level.

This also enables cross-repo impact analysis when multiple repos are indexed under the same workspace (e.g. a monorepo root or a parent directory of related projects).

Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.

```jac
"""Impact analysis demo: model files/packages as nodes with bidirectional
import edges, then traverse reverse edges to find every dependent of a
changed module — the scenario from issue #378 of nano-brain.

Graph shape:
    root
     |-- FileA --imports--> PkgB
     |   ^
     |   +--imported_by--+
     |                   |
     |-- FileC --imports--+
     |   ^
     |   +--imported_by--+
     |                   |
     |-- FileD --imports--+

The ImpactAnalyst walker spawns on a target package node and walks
imported_by edges outward to discover all dependents (forward direction:
"who imports me?"). This is exactly the missing reverse-traversal the
issue describes.
"""

node CodeNode {
    has name: str = "";
    has kind: str = "";
}

node FileNode(CodeNode) {
    has path: str = "";
}

node PackageNode(CodeNode) {
    has import_path: str = "";
}

edge Imports {
    has depth: int = 1;
}

edge ImportedBy {
    has depth: int = 1;
}

walker ImpactAnalyst {
    has target_name: str = "";
    has max_depth: int = 3;
    has dependents: list[str] = [];
    has seen: list[str] = [];

    can start with Root entry {
        # Find the target package, then begin reverse traversal.
        for child in [-->] {
            if child.name == self.target_name {
                visit [child];
                return;
            }
        }
        print(f"Target {self.target_name} not found in graph");
        disengage;
    }

    can begin_reverse with PackageNode entry {
        self.seen.append(here.name);
        print(f"Analyzing impact for package: {here.name}");
        visit [->:ImportedBy:->];
    }

    can begin_reverse with FileNode entry {
        # Reverse traversal can also begin from a file target.
        self.seen.append(here.name);
        print(f"Analyzing impact for file: {here.name}");
        visit [->:ImportedBy:->];
    }

    can collect with PackageNode entry | FileNode entry {
        if here.name not in self.seen {
            self.seen.append(here.name);
            self.dependents.append(here.name);
            print(f"  [depth <= {self.max_depth}] dependent: {here.name} ({here.kind})");
        }
        visit [->:ImportedBy:->];
    }
}

with entry {
    # Build the nano-brain watcher scenario.
    watcher = PackageNode(name="internal/watcher", kind="package", import_path="internal/watcher");
    filter_file = FileNode(name="internal/watcher/filter.go", kind="file", path="internal/watcher/filter.go");

    main_go = FileNode(name="cmd/nano-brain/main.go", kind="file", path="cmd/nano-brain/main.go");
    server_go = FileNode(name="internal/server/server.go", kind="file", path="internal/server/server.go");
    collection_go = FileNode(name="internal/server/handlers/collection.go", kind="file", path="internal/server/handlers/collection.go");
    reindex_go = FileNode(name="internal/server/handlers/reindex.go", kind="file", path="internal/server/handlers/reindex.go");
    workspace_go = FileNode(name="internal/server/handlers/workspace.go", kind="file", path="internal/server/handlers/workspace.go");

    # Wire the graph: file contains package, files import package,
    # and every forward Imports edge is mirrored by a reverse ImportedBy edge.
    root ++> filter_file ++> watcher;

    root ++> main_go +>:Imports:+> watcher;
    root ++> server_go +>:Imports:+> watcher;
    root ++> collection_go +>:Imports:+> watcher;
    root ++> reindex_go +>:Imports:+> watcher;
    root ++> workspace_go +>:Imports:+> watcher;

    watcher +>:ImportedBy:+> main_go;
    watcher +>:ImportedBy:+> server_go;
    watcher +>:ImportedBy:+> collection_go;
    watcher +>:ImportedBy:+> reindex_go;
    watcher +>:ImportedBy:+> workspace_go;

    # Spawn the reverse-traversal walker on the target package.
    analyst = ImpactAnalyst(target_name="internal/watcher", max_depth=3);
    analyst spawn root;

    print("");
    print(f"Reverse impact complete: {len(analyst.dependents)} dependents found");
    for dep in analyst.dependents {
        print(f"  - {dep}");
    }
}
