I'm modeling a small flight network in Jac where each flight leg is an edge storing its ticket price. The edge type should have its own method that normalizes a price against the most expensive fare in the network. Have a scout walker collect all the prices into reports, then in the main block call that method on every leg to print what fraction of the top fare it costs.

```jac
"""Flight network: ticket prices on FlightLeg edges; Scout gathers fares to normalize each leg against the peak."""

node Airport {
    has code: str = "";
}

edge FlightLeg {
    has price: float = 0.0;
    has label: str = "";

    def fare_fraction(max_fare: float) -> float {
        if max_fare <= 0.0 {
            return 0.0;
        }
        return self.price / max_fare;
    }
}

walker Scout {
    has fares: list[float] = [];

    can start with Root entry {
        visit [-->];
    }

    can scan with Airport entry {
        visit [->:FlightLeg:->] else { disengage; };
    }

    can tally with FlightLeg entry {
        self.fares.append(here.price);
        visit [-->];
    }
}

with entry {
    jfk = Airport(code="JFK");
    lax = Airport(code="LAX");
    sfo = Airport(code="SFO");
    root ++> jfk;
    leg_jfk_lax = jfk +>:FlightLeg(price=450.0, label="JFK-LAX"):+> lax;
    leg_lax_sfo = lax +>:FlightLeg(price=320.0, label="LAX-SFO"):+> sfo;
    leg_jfk_sfo = jfk +>:FlightLeg(price=380.0, label="JFK-SFO"):+> sfo;

    scout = root spawn Scout();

    max_fare = 0.0;
    for fare in scout.fares {
        peak = fare if fare > max_fare else max_fare;
        max_fare = peak;
    }

    network_legs = [leg_jfk_lax, leg_lax_sfo, leg_jfk_sfo];
    for leg in network_legs {
        share = leg.fare_fraction(max_fare);
        print(f"{leg.label}: {share:.2f} of peak fare (${leg.price} / ${max_fare})");
    }
}
