Task:
A maintainer on the project ShovalBenjer/agenteval-bench (unknown) filed this issue about hand-rolled graph machinery causing pain:

Issue #13: Docs RFC: documentation structure & content priorities

## Goal
We are overhauling the agenteval-bench documentation (README, `docs/spec.md`, roadmap, repo hygiene). Before finalizing, we want community input on **structure** and **content priorities** so the docs serve real users (adopters, contributors, and CI integrators).

> Note: This repo does not have GitHub Discussions enabled, so this RFC is opened as an issue instead. Please comment here.

## Proposed documentation set
- **README.md** — overview, architecture diagram, install, quickstart, API reference, contributing, changelog link, license. Badges: CI, PyPI, license, Python versions.
- **docs/spec.md** — motivation, goals, non-goals, architecture, data flow, API contract, extension points, security, performance. Unimplemented features marked `planned` with milestones.
- **TODO.md → roadmap** — vision, quarterly objectives, key results, dependency graph, risk register. Closed items archived under `docs/archive/`.
- **CODEOWNERS / .gitignore** — ownership + hygiene audit.

## Questions for the community
1. What sections are missing or most needed (e.g. a "Migrating from LangSmith/Manual scripts" guide, a scoring-cookbook, a "Writing golden replay suites" tutorial)?
2. Should the README stay a complete entry point, or link out more aggressively to `docs/spec.md`?
3. Which unimplemented features (LLM-as-judge, `compare`, `report`, typer CLI, plugins) should be prioritized and documented as `planned`?
4. Any conventions/terminology you'd like standardized across docs?

## How to give feedback
Comment below with: what you'd add/remove/reorder, and the single most important doc you wish existed. We'll incorporate the top themes before merging the overhaul.

Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.

```jac
"""agenteval-bench docs RFC: model the documentation overhaul plan as a graph.

Entities are DocSection, SectionStatus, and Feature nodes connected by typed
edges. A DocsAuditor walker traverses the dependency graph to perform the
exact kind of traversal a hand-rolled implementation would have done:
reachability, cycle detection across section dependencies, and cascading
invalidation when a section's status changes (planned -> drafted -> published).
"""

# --- node archetypes --------------------------------------------------------

node DocSection {
    has title: str = "";
    has doc_kind: str = "";      # "readme" | "spec" | "roadmap" | "hygiene"
    has status: str = "planned"; # "planned" | "drafted" | "published"
}

node SectionStatus {
    has label: str = "";
    has severity: int = 0;       # higher = more critical for release
}

node Feature {
    has name: str = "";
    has priority: int = 0;       # community-ranked priority for the RFC
    has planned: bool = True;
}

# --- typed edges (relationship carries meaning) -----------------------------

edge DependsOn {
    has reason: str = "";
}

edge Documents {
    has section_kind: str = "";
}

edge Targets {
    has audience: str = "";
}

# --- the auditor walker -----------------------------------------------------

walker DocsAuditor {
    has visited_titles: list[str] = [];
    has cycle_detected: bool = False;
    has depth_cap: int = 8;
    has depth: int = 0;

    can start with Root entry {
        print(f"=== Docs RFC audit starting (depth cap {self.depth_cap}) ===");
        visit [-->];
    }

    can audit_doc with DocSection | SectionStatus | Feature entry {
        # Mark this node visited via its title/label/name; explicit cycle
        # policy because walkers have no built-in dedupe in jac 0.36.1.
        key = here.title if here.title != "" else (
              here.label if here.label != "" else here.name);
        if key in self.visited_titles {
            self.cycle_detected = True;
            print(f"[CYCLE] revisit of '{key}' — cycle policy fired");
            disengage;
        }
        self.visited_titles.append(key);
        self.depth += 1;

        if self.depth > self.depth_cap {
            print(f"[DEPTH CAP] exceeded {self.depth_cap}; disengaging");
            disengage;
        }

        # Domain logic preserved: cascading invalidation when a doc section
        # moves out of `published`. Anything documented by it must be
        # re-flagged as planned.
        if here.status == "published" {
            print(f"[OK]    published doc: '{here.title}'");
        } elif here.status == "drafted" {
            print(f"[WIP]   drafted doc:   '{here.title}'");
        } else {
            print(f"[TODO]  planned doc:   '{here.title}'");
        }

        visit [->:DependsOn:->] else { disengage; }
    }
}

walker PriorityRanker {
    can start with Root entry {
        print("=== Community priority ranking ===");
        visit [-->];
    }

    can rank with Feature entry {
        badge = "P0" if here.priority >= 8 else (
                "P1" if here.priority >= 5 else "P2");
        state = "planned" if here.planned else "shipped";
        print(f"[{badge}] {here.name} ({state})");
        visit [-->];
    }
}

# --- demo wiring ------------------------------------------------------------

with entry {
    # Doc sections the maintainer proposed in the RFC.
    readme     = DocSection(title="README.md",        doc_kind="readme",  status="drafted");
    spec       = DocSection(title="docs/spec.md",     doc_kind="spec",    status="planned");
    roadmap    = DocSection(title="docs/roadmap.md",  doc_kind="roadmap", status="planned");
    hygiene    = DocSection(title="CODEOWNERS/.gitignore", doc_kind="hygiene", status="published");

    # Section statuses (separate nodes so the union ability can hit them).
    s_drafted  = SectionStatus(label="drafted",   severity=2);
    s_planned  = SectionStatus(label="planned",   severity=1);
    s_publish  = SectionStatus(label="published", severity=3);

    # Community-ranked features the RFC asks the community to prioritize.
    f_llm_judge   = Feature(name="LLM-as-judge", priority=9, planned=True);
    f_compare     = Feature(name="compare",     priority=8, planned=True);
    f_report      = Feature(name="report",      priority=6, planned=True);
    f_typer_cli   = Feature(name="typer CLI",   priority=5, planned=True);
    f_plugins     = Feature(name="plugins",     priority=3, planned=False);

    # Wire the documentation dependency graph with typed edges. The
    # DependsOn edges encode "this doc can't be finalized until that one
    # exists" — the exact relationship the hand-rolled adjacency dict used
    # to model. README -> spec, spec -> roadmap, roadmap -> hygiene form a
    # chain; spec also depends on hygiene, so traversal naturally exercises
    # multi-parent reachability and (if reordered) cycle detection.
    root ++> readme ++> spec ++> roadmap ++> hygiene;
    spec +>:DependsOn(reason="spec references hygiene policy"):+> hygiene;
    readme +>:Documents(section_kind="overview"):+> s_publish;
    spec   +>:Documents(section_kind="contract"):+> s_planned;
    roadmap +>:Documents(section_kind="milestones"):+> s_planned;

    # Features attached to the spec node via typed Targets edges.
    spec +>:Targets(audience="adopters"):+> f_llm_judge;
    spec +>:Targets(audience="contributors"):+> f_compare;
    spec +>:Targets(audience="CI integrators"):+> f_report;
    spec +>:Targets(audience="adopters"):+> f_typer_cli;
    spec +>:Targets(audience="contributors"):+> f_plugins;

    # Spawn the auditor on the readme — it will walk the DependsOn chain.
    root spawn DocsAuditor(depth_cap=6);
    print("");
    root spawn PriorityRanker();
}
