"""TB-IR vs v1 whole-record-read parity for nested struct fields."""

node Inner {
    has a: int = 0;
}

node Outer {
    has r: int = 0;
}

node RecordType {
    has name: str = "";
}

edge NestedField { }
edge TypeDependsOn { }

walker FieldChainProbe {
    has depth: int = 0;
    has resolved: str = "";
    has value: int = 0;

    can start with Outer entry {
        self.depth = 1;
        visit [->:NestedField:->] else {
            self.resolved = "Outer";
            disengage;
        };
    }

    can at_leaf with Inner entry {
        self.depth = 2;
        self.resolved = "Inner";
        self.value = here.a;
        disengage;
    }
}

walker WholeReadParity {
    has backend: str = "v1";
    has ok: bool = False;
    has copied_a: int = 0;
    has note: str = "";

    can start with Outer entry {
        if self.backend == "tbir" {
            self.ok = False;
            self.note = "tbir rejects let d : Inner = o.inner";
            disengage;
        }
        visit [->:NestedField:->] else {
            self.note = "missing Inner field";
            disengage;
        };
    }

    can bind with Inner entry {
        self.copied_a = here.a;
        self.ok = True;
        self.note = "v1 accepts whole-record read";
        disengage;
    }
}

walker NestedFieldWrite {
    has scratch_a: int = 0;
    has wrote: bool = False;

    can start with Outer entry {
        visit [->:NestedField:->] else { disengage; };
    }

    can touch with Inner entry {
        if self.scratch_a == 0 {
            self.scratch_a = here.a;
            disengage;
        } else {
            here.a = self.scratch_a;
            self.wrote = True;
            disengage;
        }
    }
}

walker TypeEmitter {
    has inner_defined: bool = False;
    has outer_defined: bool = False;

    can start with Root entry {
        visit [-->] else { disengage; };
    }

    can define with RecordType entry {
        if here.name == "Inner" {
            self.inner_defined = True;
        } else {
            if here.name == "Outer" {
                if self.inner_defined {
                    self.outer_defined = True;
                }
            }
        }
        visit [-->] else { disengage; };
    }
}

with entry {
    inner_def = RecordType(name="Inner");
    outer_def = RecordType(name="Outer");
    root ++> inner_def ++> outer_def;
    outer_def +>:TypeDependsOn:+> inner_def;

    emitter = TypeEmitter();
    root spawn emitter;

    inner_val = Inner(a=5);
    o = Outer(r=7);
    root ++> o;
    o +>:NestedField:+> inner_val;

    p = Outer(r=0);
    p_inner = Inner(a=0);
