    o spawn probe;

    v1 = WholeReadParity(backend="v1");
    o spawn v1;

    tbir = WholeReadParity(backend="tbir");
    o spawn tbir;

    read_src = NestedFieldWrite();
    o spawn read_src;
    write_dst = NestedFieldWrite();
    write_dst.scratch_a = read_src.scratch_a;
