"""Semantic relationship model: typed source-anchored edges for a project graph.

Models the problem space of issue #8143 — replacing string relations with
typed semantic edges that carry canonical source/target identity, declared
revision, ordinal, and confidence. A walker traverses the dependency graph
with an explicit cycle policy (the source pattern's recursion has the same
risk), accumulates invalidation candidates, and reports them in one exit.
"""

# --- Subject node archetypes ---------------------------------------------------

node File {
    has path: str = "";
    has revision: str = "";
}

node Module {
    has name: str = "";
    has file_path: str = "";
}

node Package {
    has name: str = "";
    has version: str = "";
}

node ExternalBoundary {
    # "unknown / unavailable target" — represents dynamic imports, missing
    # symbols, etc. as a first-class subject rather than a dangling string.
    has reason: str = "";
}

# --- Typed semantic edge archetypes -------------------------------------------

edge DependsOn {
    # Generic dependency: file -> module/package/external.
    has kind: str = "use";          # "use" | "require" | "import"
    has ordinal: int = 0;           # source order matters for some
    has confidence: float = 1.0;
    has producer: str = "scanner";
}

edge InheritsFrom {
    has kind: str = "static";       # "static" | "dynamic"
    has ordinal: int = 0;
    has confidence: float = 1.0;
    has producer: str = "scanner";
}

edge TestsTarget {
    has ordinal: int = 0;
    has confidence: float = 1.0;
    has producer: str = "scanner";
}

# --- Traversal walker ---------------------------------------------------------

walker DependencyAuditor {
    has visited: list[str] = [];    # explicit cycle guard (no built-in dedupe)
    has invalidation: list[str] = [];  # accumulated for the single exit report
    has depth_limit: int = 8;

    can start with Root entry {
        visit [->:DependsOn:->];
    }

    can audit with File | Module | Package | ExternalBoundary entry {
        nid = here.__class__.__name__ + ":" + (
            here.path if isinstance(here, File) else (
                here.file_path if isinstance(here, Module) else (
                    here.name if isinstance(here, Package) else here.reason
                )
            )
        );
        if nid in self.visited {
            # Cycle policy: surface it, don't loop forever.
            print(f"[cycle] revisit {nid}");
            self.invalidation.append(f"cycle:{nid}");
            disengage;
        }
        if self.depth_limit <= 0 {
            print(f"[depth-cap] stopping at {nid}");
            self.invalidation.append(f"depth-cap:{nid}");
            disengage;
        }
        self.visited.append(nid);
        self.invalidation.append(nid);
        next_limit = self.depth_limit - 1;
        self.depth_limit = next_limit;
        visit [->:DependsOn:->] else {
            # Dead end — external boundary or leaf. Record it as a
            # boundary marker so callers can see what terminates a chain.
            print(f"[boundary] {nid}");
            disengage;
        }
    }

    can summarize with Root entry {
        print(f"[report] visited={len(self.visited)} "
              f"invalidations={self.invalidation}");
    }
}

walker InheritanceWalker {
    can start with Root entry {
        visit [->:InheritsFrom:->];
    }

    can trace with Module | Package entry {
        kind_label = here.__class__.__name__ + ":" + here.name;
        print(f"[inherit] {kind_label} (origin={self.cur_inherit_kind})");
        visit [->:InheritsFrom:->];
    }

    # Walker-local state read by `trace`.
    has cur_inherit_kind: str = "static";

    can summarize with Root entry {
        print(f"[report] inheritance trace complete");
    }
}

walker TestReachability {
    can start with Root entry {
        visit [->:TestsTarget:->];
    }

    can cover with File | Module | Package entry {
        nid = here.__class__.__name__ + ":" + (
            here.path if isinstance(here, File) else (
                here.file_path if isinstance(here, Module) else here.name
            )
        );
        print(f"[tests] reaches {nid}");
        visit [->:DependsOn:->] else { disengage; }
    }
}

# --- Demonstration graph ------------------------------------------------------

with entry {
    # Source-anchored files
    f_app = File(path="src/App.pm", revision="rev-1");
    f_lib = File(path="lib/Util.pm", revision="rev-1");
    f_test = File(path="t/app.t", revision="rev-1");

    # Resolved modules / packages
    m_app = Module(name="App", file_path="src/App.pm");
    m_util = Module(name="Util", file_path="lib/Util.pm");
    pkg_core = Package(name="Core", version="1.2");
    pkg_ext = ExternalBoundary(reason="dynamic require unknown module");

    # Typed semantic edges with ordinal + confidence preserved.
    f_app +>:DependsOn(kind="use", ordinal=1, confidence=0.95, producer="scanner"):+> m_app;
    f_app +>:DependsOn(kind="require", ordinal=2, confidence=0.80, producer="scanner"):+> m_util;
    m_app +>:InheritsFrom(kind="static", ordinal=0, confidence=1.0, producer="parser"):+> pkg_core;
    m_app +>:InheritsFrom(kind="dynamic", ordinal=1, confidence=0.60, producer="runtime"):+> pkg_ext;

    # A cycle: Util pulls back into App via a re-export.
    m_util +>:DependsOn(kind="use", ordinal=1, confidence=0.90, producer="scanner"):+> m_app;

    # Test -> app
    f_test +>:TestsTarget(ordinal=0, confidence=1.0, producer="scanner"):+> m_app;

    root ++> f_app ++> f_lib ++> f_test;

    print("=== DependencyAuditor (cycle-safe, depth-limited) ===");
    root spawn DependencyAuditor();
    print("");
    print("=== InheritanceWalker ===");
    root spawn InheritanceWalker();
    print("");
    print("=== TestReachability ===");
    root spawn TestReachability();
}
