    has branch: str = "main";
}

node Stage {
    has title: str = "";
    has status: str = "pending";
}

node Release {
    has version_name: str = "";
    has version_code: int = 0;
    has shipped: bool = False;
}

node Anomaly {
    has kind: str = "";
    has message: str = "";
