```jac
"""Electronics store category hierarchy: adjacency-list tree lifted to native Jac.

Models the classic Mike Hillyer example as nodes + typed Parent edges.
Walkers demonstrate the two operations that the issue calls painful in pure SQL:
    1. Recursively retrieve the full subtree under a given category (DFS).
    2. Cascade-delete a subtree when a category is removed.
A third walker demonstrates cycle detection, the safety net any hand-rolled
adjacency-list traversal must carry.
"""

node Category {
    has name: str = "";
    has category_id: int = 0;
}

# Typed edge: the parent/child pointer from the adjacency list.
edge Parent { }

# ---- Walkers ---------------------------------------------------------------

walker FullTree {
    # Accumulates the DFS ordering as the walker descends the tree.
    has visited_names: list[str] = [];
    has indent: int = 0;

    can start with Root entry {
        # Kick off by visiting every top-level (rooted) category from root.
        visit [-->[?:Category]];
    }

    can descend with Category entry {
        prefix = "  " * self.indent;
        self.visited_names.append(f"{prefix}{here.name}");
        self.indent += 1;
        # Cycle safety: every lift must carry an explicit cycle policy.
        # Here we use the standard "no child should point back to an
        # ancestor" guard implemented via a depth cap on the walker.
        if self.indent > 6 {
            self.indent -= 1;
            disengage;
        }
        # Walk down to every child via the typed Parent edge.
        visit [->:Parent:->];
        self.indent -= 1;
    }
}

walker CascadeDelete {
    # Cascade-delete a subtree rooted at a specific Category. The walker
    # walks DOWN the tree, severing edges from each parent, then deletes
    # the now-disconnected child node. Order is irrelevant because deleting
    # a node auto-purges its remaining edges (see project notes).
    has deleted: list[str] = [];

    can start with Root entry {
        # Look up the target by id among root's children.
        target = None;
        for child in [-->] {
            if isinstance(child, Category) and child.category_id == 3 {
                target = child;
            }
        }
        if target is not None {
            visit [->:Parent:->];
        } else {
            print("Target category not found");
            disengage;
        }
    }

    can sweep with Category entry {
        # Recurse first so descendants are deleted before this node.
        visit [->:Parent:->];
        self.deleted.append(here.name);
        # Disconnect from our own parent (typed edge), then destroy node.
        parents = [<-:Parent:<-];
        for p in parents {
            p del ->:Parent:-> here;
        }
        del here;
    }
}

walker CycleCheck {
    # Walks the tree accumulating ancestors; if we ever land on one we've
    # already seen going DOWN, the adjacency list is malformed (a cycle).
    has ancestors: list[str] = [];
    has cycle_found: bool = False;

    can start with Root entry {
        visit [-->[?:Category]];
    }

    can walk with Category entry {
        if here.name in self.ancestors {
            print(f"[CYCLE] re-entered {here.name} via parent pointer");
            self.cycle_found = True;
            disengage;
        }
        self.ancestors.append(here.name);
        visit [->:Parent:->];
    }
}

# ---- Demo wiring -----------------------------------------------------------

with entry {
    # Build the electronics-store hierarchy from the issue verbatim.
    electronics = Category(name="ELECTRONICS", category_id=1);
    televisions = Category(name="TELEVISIONS", category_id=2);
    tube        = Category(name="TUBE", category_id=3);
    lcd         = Category(name="LCD", category_id=4);
    plasma      = Category(name="PLASMA", category_id=5);
    portable    = Category(name="PORTABLE ELECTRONICS", category_id=6);
    mp3         = Category(name="MP3 PLAYERS", category_id=7);
    flash       = Category(name="FLASH", category_id=8);
    cd          = Category(name="CD PLAYERS", category_id=9);
    radios      = Category(name="2 WAY RADIOS", category_id=10);

    # Typed-edge connections replace the hand-rolled parent_id lookups.
    electronics +>:Parent:+> televisions;
    electronics +>:Parent:+> portable;
    televisions +>:Parent:+> tube;
    televisions +>:Parent:+> lcd;
    televisions +>:Parent:+> plasma;
    portable    +>:Parent:+> mp3;
    portable    +>:Parent:+> cd;
    portable    +>:Parent:+> radios;
    mp3         +>:Parent:+> flash;

    # Mount everything under root for spawning.
    root ++> electronics;

    # --- Demo 1: full subtree retrieval (replaces recursive SQL JOIN) -----
    print("=== Full subtree under TELEVISIONS ===");
    tv_walker = FullTree();
    tv_walker.visited_names = [];
    tv_walker.indent = 0;
    # Seed the walker by hand-spawning onto the TELEVISIONS node.
    televisions spawn tv_walker;
    for line in tv_walker.visited_names {
        print(line);
    }

    # --- Demo 2: cycle detection (the safety policy that must survive) --
    print("\n=== Cycle detection ===");
    # Inject a cycle: point FLASH's parent back at TELEVISIONS.
    flash +>:Parent:+> televisions;
    cc = CycleCheck();
    electronics spawn cc;
    if not cc.cycle_found {
        print("no cycles detected");
    }
    # Repair the cycle so later demos see a clean tree.
    # Disconnect the bad edge by walking from FLASH and removing any
    # Parent edge that points at TELEVISIONS.
    for n in [->:Parent:->] {
        if n.name == "TELEVISIONS" {
            flash del ->:Parent:-> n;
        }
    }

    # --- Demo 3: cascade delete (replaces recursive DELETE) --------------
    print("\n=== Cascade delete of MP3 PLAYERS subtree ===");
    cd_walker = CascadeDelete();
    cd_walker.deleted = [];
    mp3 spawn cd_walker;
    for name in cd_walker.deleted {
        print(f"deleted: {name}");
    }
}
