```jac
"""Mapsnap incremental fit: model pages, stages, and rung sets as a graph.

Demonstrates the cross-page coupling the issue cares about: snap's hash
for a page depends on its neighbour poses and on the volume-wide rung
set, so a single page's invalidation ripples through the neighbours
that snap consulted. A walker walks the snap dependency edges and
emits one incremental-fit plan per affected page."""

# ---- Nodes -----------------------------------------------------------------

node Page {
    has label: str = "";
    has keymap_loc: str = "";
    has stage_version: int = 0;
}

node Stage {
    has stage_name: str = "";
    has version: int = 0;
}

# Volume-level derived state that snap reads but doesn't own.
node RungSet {
    has volume: str = "";
    has fingerprint: str = "";
}

# Snap's neighbour-pose prior: a typed dependency from one page to another.
edge SnapPrior {
    has weight: float = 0.0;
}

# Stage -> Page: which page the stage ran on.
edge RanOn { }

# Page -> Page: snap consumed the neighbour's published fit.
edge ConsultedPose { }

# Page -> RungSet: snap for this page read the volume's rung set.
edge UsedRungs { }

# ---- Walker ----------------------------------------------------------------

# `FitPlanner` traverses the per-page snap dependencies. For each page it
# reaches it records why the page must be recomputed (own hash change,
# neighbour pose change, or rung-set change). One exit `report` collects
# the plan.
walker FitPlanner {
    has changed_pages: list[str] = [];
    has changed_rungs: str = "";

    can start with Root entry {
        visit [-->];
    }

    # Union ability: same logic whether we land on a Page or on a RungSet.
    can plan with Page | RungSet entry {
        reason = "";
        if here.__class__ == RungSet {
            self.changed_rungs = here.fingerprint;
            reason = "rungs=" + here.fingerprint;
        } else {
            self.changed_pages.append(here.label);
            if self.changed_rungs != "" {
                reason = "neighbour-of-rungs";
            } else {
                reason = "own-hash";
            }
        }
        print(f"[plan] {here.label if hasattr(here,'label') else here.volume}: {reason}");
        visit [-->];
    }
}

# `SnapWalker` simulates a single A/B that mutates a few pages and the
# rung set, then spawns the planner to compute which pages must re-snap.
walker SnapWalker {
    has volume: str = "";

    can start with Root entry {
        print(f"== incremental fit for volume {self.volume} ==");
        visit [-->];
    }

    can plan_volume with RungSet entry {
        print(f"rung-set fingerprint = {here.fingerprint}");
        visit [-->];
    }

    can plan_page with Page entry {
        print(f"page {here.label} keymap_loc={here.keymap_loc}");
        visit [-->];
    }
}

# ---- Demo ------------------------------------------------------------------

with entry {
    georef = Stage(stage_name="georef", version=1);
    snap = Stage(stage_name="snap", version=2);
    reconcile = Stage(stage_name="reconcile", version=1);

    rungset = RungSet(volume="nashville", fingerprint="rungs-v3");

    # Pages in a single volume; only p2 and p4 had their keymap locations
    # edited, mirroring the issue's "~10-15% of pages" example.
    p1 = Page(label="p1", keymap_loc="A1");
    p2 = Page(label="p2", keymap_loc="B7");
    p3 = Page(label="p3", keymap_loc="C3");
    p4 = Page(label="p4", keymap_loc="D9");
    p5 = Page(label="p5", keymap_loc="E2");

    # Volume-level chain: stages -> rungset -> pages.
    root ++> georef ++> snap ++> reconcile ++> rungset;
    rungset ++> p1 ++> p2 ++> p3 ++> p4 ++> p5;

    # Snap's cross-page dependencies: each page consulted its neighbours'
    # published fits (the staleness class the issue flags).
    p1 +>:SnapPrior(weight=0.9):+> p2;
    p2 +>:SnapPrior(weight=0.7):+> p3;
    p3 +>:SnapPrior(weight=0.8):+> p4;
    p4 +>:SnapPrior(weight=0.6):+> p5;

    # Pages -> stages that ran on them (typed RanOn edge).
    p1 +>:RanOn:+> georef;
    p2 +>:RanOn:+> georef;
    p3 +>:RanOn:+> georef;
    p4 +>:RanOn:+> georef;
    p5 +>:RanOn:+> georef;

    # Pages -> rung set they read during snap.
    p1 +>:UsedRungs:+> rungset;
    p2 +>:UsedRungs:+> rungset;
    p3 +>:UsedRungs:+> rungset;
    p4 +>:UsedRungs:+> rungset;
    p5 +>:UsedRungs:+> rungset;

    # Walk the volume to show what incremental fit sees.
    root spawn SnapWalker(volume="nashville");

    # Now ask the planner which pages must recompute when rungs change.
    planner = FitPlanner(changed_rungs="rungs-v3");
    root spawn planner;
}
```

