"""Agent delegation tree: parent/child task workflow with cascading pause/resume/cancel.

Models the essential scenario from the async delegation issue as a graph of
task nodes connected by `DelegatesTo` typed edges. A `LifecycleCascade` walker
traverses the delegation tree performing the cascading pause/resume/cancel
that the issue complains about being hand-rolled, plus cycle detection and
reachability checks across the parent/child relationship.
"""

node Task {
    has task_id: str = "";
    has status: str = "running";
    has paused: bool = False;
}

edge DelegatesTo {
    has propagation: str = "cascade";
}

walker LifecycleCascade {
    has action: str = "pause";
    has visited: list[str] = [];
    has order: list[str] = [];
    has cycle_detected: bool = False;

    can start with Root entry {
        self.visited = [];
        self.order = [];
        self.cycle_detected = False;
        print(f"--- cascade {self.action} ---");
        visit [->:DelegatesTo:->] else { disengage; }
    }

    can act with Task entry {
        # Cycle detection: cycle policy of the source graph is domain logic
        # and must survive the lift. Without this guard the walker would loop
        # forever on a delegation cycle (A->B->C->A), which is the exact
        # pain point called out in the issue's hand-rolled traversal.
        if here.task_id in self.visited {
            self.cycle_detected = True;
            visit [->:DelegatesTo:->] else { disengage; }
            return;
        }
        self.visited.append(here.task_id);

        # Two-phase mutation: read state, decide new state, write state. The
        # cancel action wins even if the node is currently paused.
        if self.action == "pause" {
            here.paused = True;
            here.status = "paused";
        } elif self.action == "resume" {
            here.paused = False;
            here.status = "running";
        } else {
            here.paused = False;
            here.status = "cancelled";
        }
        self.order.append(here.task_id);
        print(f"  {self.action} -> {here.task_id} (status={here.status})");

        visit [->:DelegatesTo:->] else { disengage; }
    }
}

walker Reachability {
    has origin_id: str = "";
    has reachable: list[str] = [];

    can start with Root entry {
        self.reachable = [];
        visit [->:DelegatesTo:->] else { disengage; }
    }

    can scan with Task entry {
        if here.task_id != self.origin_id and here.task_id not in self.reachable {
            self.reachable.append(here.task_id);
        }
        visit [->:DelegatesTo:->] else { disengage; }
    }
