Models the essential scenario from djm204/frankenbeast issue #4122:
  - `PlanGraph.fromTasks` validates a sub-graph (cycle detection + topo sort)
  - The buggy `_buildSubGraph` discards that validation and returns a raw
    unvalidated graph instead, allowing cyclic sub-graphs to slip through.

We model this as two node archetypes (Task, PlanSubGraph) connected by typed
edges, and two walkers that mirror the two code paths the issue contrasts:
  * `ValidatedPlanner`  — returns the validated graph (the fix)
  * `RawEdgesPlanner`   — discards validation, returns a raw-edges graph
                          (the bug; falls through without raising)
"""

node Task {
    has title: str = "";
    has depends_on_title: str = "";
}

edge DependsOn { }

node PlanSubGraph {
    has reason: str = "";
    has tasks: list = [];
    has validated: bool = False;
    has rejected_reason: str = "";
}

walker ValidatedPlanner {
    has reason: str = "recursive expansion";

    can start with Root entry {
        visit [-->];
    }

    can build with Task entry {
        # Walk dependencies, then collapse into a PlanSubGraph whose
        # `validated` flag reflects the cycle check we actually did.
        visited: list = [];
        current = here;
