```jac
"""Recursive construction walk vs iterative walker — the issue's tooth.

Models the scenario: two entrances naively use a recursive walk that blows
the stack on deep trees; the census entrance (the truthful one) does not.
The fix shape is to lift the recursive descent onto a walker using an
explicit cycle policy (visited set + depth cap) so that:

  * deep construction no longer depends on Python's call stack,
  * a node re-entering its own construction is reported as a CYCLE defect
    rather than a RecursionError (frame names cannot separate those, but
    coordinates can),
  * traversal order is deterministic-by-construction.

Two walkers demonstrate the contrast:
  * RecursiveAssembler — hand-rolled recursion (the crutch shape),
  * IterativeAssembler   — walker over typed Child edges with visited set.

Both walk the same tree; only the iterative one survives a depth that
exceeds the (simulated) default recursion budget.
"""

node Value {
    has label: str = "";
    has depth: int = 0;
}

edge Child {
    has slot: int = 0;
}

# Simulated call stack depth for the recursive walker. In CPython this is
# sys.getrecursionlimit(); the issue's point is that the iterative walk
# must not depend on it at all.
glob RECURSION_BUDGET: int = 200;

walker RecursiveAssembler {
    has seen: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can descend with Value entry {
        self.seen.append(here.label);
        if here.depth >= RECURSION_BUDGET {
            print(f"  [RECURSIVE] depth {here.depth} reached budget; "
                  f"would blow the stack here");
            disengage;
        }
        visit [-->];
    }
}

walker IterativeAssembler {
    has seen: list[str] = [];
    has cycles: list[str] = [];

    can start with Root entry {
        # The walker has no built-in once-per-node guarantee, so we keep
        # the cycle policy explicit — same posture as the source tooth.
        self.seen.append(here.label);
        visit [-->];
    }

    can descend with Value entry {
        # A coordinate the walker has already touched is a cycle, not
        # "more depth". Coordinates can separate those; frame names cannot.
        already = [label for label in self.seen if label == here.label];
        if already {
            self.cycles.append(here.label);
            print(f"  [ITERATIVE] CYCLE on {here.label} — defect in walk");
            disengage;
        }
        self.seen.append(here.label);
        visit [-->];
    }
}

# Build a deep tree whose depth is greater than RECURSION_BUDGET to
# reproduce the RecursionError the sealed board saw under the crutch
# entrances.
with entry {
    # Chain: root -> v0 -> v1 -> ... -> v(DEEP-1)
    DEEP = 350;
    root ++> Value(label="root", depth=0);
    prev = root;
    for i in range(1, DEEP + 1) {
        cur = Value(label=f"v{i}", depth=i);
        prev +>:Child(slot=i):+> cur;
        prev = cur;
    }

    print("=== RecursiveAssembler (the crutch shape) ===");
    rec = RecursiveAssembler();
    root spawn rec;
    print(f"  visited {len(rec.seen)} nodes; "
          f"stack-dependent, fails at depth {RECURSION_BUDGET}");

    print("");
    print("=== IterativeAssembler (walker over typed Child edges) ===");
    it = IterativeAssembler();
    root spawn it;
    print(f"  visited {len(it.seen)} nodes; "
          f"no stack dependency");
    if it.cycles {
        print(f"  cycles reported: {it.cycles}");
    } else {
        print("  no cycles — all-distinct coordinates, genuine depth");
    }
}
