"""Performance-test CI workflow model.

Models the essential scenario from issue #3595: hand-rolled graph machinery
for managing performance-budget tests as nodes connected by dependency and
invalidation relationships. A walker sweeps the performance-test roster,
runs a Monte Carlo timing aggregation (no single-shot budget), and detects
regressions against a recorded baseline.
"""

# --- Entities ---------------------------------------------------------------

node PerformanceTest {
    has name: str = "";
    has baseline_ms: float = 0.0;
    has last_run_ms: float = 0.0;
    has flaked: bool = False;
}

node PullRequest {
    has pr_id: str = "";
    has title: str = "";
}

node CIWorkflow {
    has workflow_name: str = "";
    has trigger: str = "";
}

# --- Relationships (typed edges) -------------------------------------------

edge DependsOn {
    # A regression hunt depends on the baseline being present.
    has reason: str = "";
}

edge Invalidates {
    # Cold-start flake invalidates the single-shot budget assertion.
    has evidence: str = "";
}

# --- Walkers ---------------------------------------------------------------

walker MonteCarloRunner {
    has iterations: int = 0;
    has samples: list[float] = [];
    has report: dict = {};

    can start with Root entry {
        visit [->:DependsOn:->];
    }

    can schedule with CIWorkflow entry {
        visit [-->];
    }

    can gather with PerformanceTest entry {
        # Monte Carlo: run the test N times and aggregate.
        self.samples = [];
        i = 0;
        while i < self.iterations {
            # Synthetic per-iteration wall-clock: stable mean + small jitter.
            jitter = 0.05;
            sample = here.baseline_ms + jitter;
            self.samples.append(sample);
            i += 1;
        }
        # Weighted average (mean) — the clean signal, not a single shot.
        total = 0.0;
        for s in self.samples {
            total += s;
        }
        mean_ms = total / float(len(self.samples));
        here.last_run_ms = mean_ms;
        here.flaked = mean_ms > (here.baseline_ms * 1.5);
        self.report[here.name] = mean_ms;
        visit [-->];
    }

    can acknowledge with PullRequest entry {
        # Performance budget is regression-detected, not single-shot blocked.
        print(f"PR {self.pr_id} acknowledged for {here.title}");
        visit [-->];
    }
}

walker RegressionDetector {
    has report: dict = {};
    has regressions: list = [];

    can start with Root entry {
        visit [->:Invalidates:->];
    }

    can enter with PerformanceTest entry {
        # Detect a regression against the recorded baseline.
        if here.last_run_ms > (here.baseline_ms * 1.25) {
            self.regressions.append(here.name);
        }
        visit [-->];
    }
}

# --- Demo wiring -----------------------------------------------------------

with entry {
    wf = CIWorkflow(workflow_name="performance-nightly", trigger="cron");
    root ++> wf;

    profile_test = PerformanceTest(
        name="test_shipped_profile_load_time",
        baseline_ms=307.0
    );
    doctrine_test = PerformanceTest(
        name="test_doctor_doctrine_json_completes_under_two_seconds",
        baseline_ms=679.0
    );
    wf +>:DependsOn(reason="baseline reference"):+> profile_test;
    wf +>:DependsOn(reason="baseline reference"):+> doctrine_test;

    pr = PullRequest(pr_id="#3593", title="operating-procedures harvest");
    root ++> pr;

    # Cold-start flake Invalidates the single-shot budget.
    profile_test +>:Invalidates(evidence="cold-start 2.24s on slow runner"):+> pr;
    doctrine_test +>:Invalidates(evidence="cold-start amplification"):+> pr;

    runner = MonteCarloRunner(iterations=5);
    pr spawn runner;
    print(f"Monte Carlo report: {runner.report}");

    detector = RegressionDetector();
    root spawn detector;
    print(f"Regressions flagged: {detector.regressions}");
}
