    profile = ProfileLoad(
        name="test_shipped_profile_load_time",
        warm_samples=[0.307, 0.310, 0.305]
    );
    doctor = DoctorDoctrineJson(
        name="test_doctor_doctrine_json_completes_under_two_seconds",
        warm_samples=[0.381, 0.679, 0.450]
