    root +>:Targets(priority=1):+> profile;
    root +>:Targets(priority=2):+> doctor;

    print("--- Phase 1: perf marker audit (warm signal) ---");
    root spawn PerfAuditor();

    print("");
    print("--- Phase 2: Monte Carlo run via typed Runs edges ---");
    root spawn PerfRunner(n_trials=5);

    print("");
    print("--- Phase 3: alert only on weighted-avg regression, never single-shot ---");
    print("policy: alert if weighted_avg >= 2.0s (NOT on single cold sample)");
