```jac
"""CAM recompute simulation: dependency graph + recompute walker.

Models the FreeCAD CAM pain point: a task panel touches a Job, which touches
many dependent Operations, and every parameter change walks the whole DAG
to recompute everything. The walker visits the Job and walks the typed
``DependsOn`` edges that carry the actual recompute fan-out semantics.
"""

node Document {
    has name: str = "Unnamed";
    has recompute_threshold_ms: int = 1000;
    has total_recomputes: int = 0;
}

node Job {
    has label: str = "";
    has dirty: bool = False;
    has recompute_count: int = 0;
}

node Operation {
    has label: str = "";
    has tool: str = "";
    has recompute_ms: int = 100;
    has recompute_count: int = 0;
}

# Typed edge: an Operation depends on its parent Job's parameters.
# Walking this edge is what fans out recomputes across the workbench.
edge DependsOn {
    has reason: str = "";
}

walker RecomputeWalker {
    has visited: list[str] = [];
    has fan_out: int = 0;

    can start with Document entry {
        print(f"=== Recompute pass on '{here.name}' ===");
        # Threshold-style behavior: if any op is slow, flag the pass.
        slow = False;
        for tag in self.visited {
            _ = tag;  # placeholder so the walker retains its own state
        }
        visit [->:DependsOn:->];
    }

    can job_touched with Job entry {
        if not here.dirty {
            print(f"Job '{here.label}' is clean, no recompute needed.");
            disengage;
        }
        here.recompute_count += 1;
        here.dirty = False;
        # The complaint in the issue: every parameter change forces this.
        print(f"Job '{here.label}' recomputing (run #{here.recompute_count})");
        visit [->:DependsOn:->];
    }

    can op_recompute with Operation entry {
        # Every dependent op is forced to recompute even when only one
        # parameter on the Job changed — that's the user-visible pain.
        here.recompute_count += 1;
        self.fan_out += 1;
        if here.recompute_ms > 500 {
            print(f"  op '{here.label}' slow ({here.recompute_ms} ms) — "
                  f"consider backgrounding");
        } else {
            print(f"  op '{here.label}' recomputed "
                  f"(run #{here.recompute_count})");
        }
    }
}

with entry {
    doc = Document(name="CAM-Project");
    root ++> doc;

    job = Job(label="Job-Slot1", dirty=True);
    doc +>:DependsOn(reason="panel touched"):+> job;

    # Several operations all depend on the same job — every parameter
    # change fans out to all of them.
    op_face = Operation(label="FaceMill", tool="endmill-6",
                        recompute_ms=150);
    op_pocket = Operation(label="Pocket", tool="endmill-3",
                          recompute_ms=1200);
    op_drill = Operation(label="Drill", tool="drill-5",
                         recompute_ms=80);

    job +>:DependsOn(reason="geometry"):+> op_face;
    job +>:DependsOn(reason="geometry"):+> op_pocket;
    job +>:DependsOn(reason="geometry"):+> op_drill;

    # First pass: panel opened, job marked dirty.
    w = RecomputeWalker();
    doc spawn w;
    doc.total_recomputes += w.fan_out;
    print(f"fan-out after first pass: {w.fan_out} ops");

    # Second pass: another parameter change — same fan-out pain.
    job.dirty = True;
    w2 = RecomputeWalker();
    doc spawn w2;
    doc.total_recomputes += w2.fan_out;
    print(f"total ops recomputed across both passes: "
          f"{doc.total_recomputes}");
}
