"""Gallery security console: log every visitor per room, and when a curator
walks in, additionally record an official inspection under their name and
tally how many rooms they inspected. A plain visitor triggers only the
generic room log; a curator triggers both the generic log and the official
inspection ability (modeled as a union trigger so the same room routine
fires for both, but the inspection counter only bumps for curators)."""

node Room {
    has room_name: str = "";
    has log: list[str] = [];

    # Generic log: every visitor (tourist or curator) is recorded.
    can log_visitor with Tourist | Curator entry {
        here.log.append(f"visitor {visitor.visitor_name} entered {here.room_name}");
        visit [-->];
    }

    # Official inspection: only the curator path. Uses `if` to branch
    # inside a union-friendly entry so we keep a single ability per room
    # trait while still doing the curator-specific work.
    can inspect with Tourist | Curator entry {
        if visitor.isinstance(Curator) {
            curator = visitor;
            here.log.append(f"OFFICIAL inspection by curator {curator.curator_name}");
            curator.rooms_inspected += 1;
        }
        visit [-->];
    }
}

walker Tourist {
    has visitor_name: str = "";

    can start with Root entry {
        visit [-->];
    }
}

walker Curator {
    has curator_name: str = "";
    has rooms_inspected: int = 0;

    can start with Root entry {
        visit [-->];
    }
}

with entry {
    room_a = Room(room_name="Gallery A");
    room_b = Room(room_name="Gallery B");
    root ++> room_a ++> room_b;

    tourist = Tourist(visitor_name="Alice");
    root spawn tourist;

    curator = Curator(curator_name="Dr. Bell");
    root spawn curator;

    print("=== Room A log ===");
    for entry_line in room_a.log {
        print(entry_line);
    }
    print("=== Room B log ===");
    for entry_line in room_b.log {
        print(entry_line);
    }
    print(f"Tourist '{tourist.visitor_name}' triggered only generic logs; "
        f"curator '{curator.curator_name}' recorded official inspections "
        f"in {curator.rooms_inspected} room(s).");
}
