```jac
"""Generic function instantiation closure walker.

Models the core scenario of the kofun-lang issue: explicit generic
function instantiations over a canonical (type-arity, ownership) tuple,
each producing one same-unit C function instance per concrete tuple,
with deterministic symbol identity and recursion policy.

Nodes:
- GenericFn: a generic function declaration holding its type binders,
  ownership modes, and body kind (so the walker can decide between
  accepted recursion and refused mutual recursion).
- Instance:  one monomorphized C-level instance, keyed by its
  canonical concrete tuple.
- Scope:     a generic call context that may yield nested generic
  calls, exercising the bounded-closure discovery rule.

Edges:
- Instantiated: GenericFn -> Instance (carries the canonical tuple).
- Invokes:      Scope/GenericFn -> GenericFn (the call graph, with
  the concrete tuple the caller is requesting).
- Hosts:        Scope -> Instance (a scope that uses a concrete tuple).

Walkers:
- InstBuilder: walks GenericFn -> Instantiated edges, gathers every
  Instance reachable from a seed and reports the closure with a
  recursion policy. Refuses mutual recursion exactly and reports
  recursion depth.
- ClosureAudit: a walker that discovers nested Invokes, expanding the
  bounded instantiation closure deterministically before reporting.
"""

node GenericFn {
    has name: str = "";
    has arity: int = 0;
    has ownership: str = "value";
    has kind: str = "id";
}

node Instance {
    has symbol: str = "";
    has concrete: str = "";
}

node Scope {
    has label: str = "";
}

edge Instantiated {
    has tuple: str = "";
}

edge Invokes {
    has tuple: str = "";
}

edge Hosts {
    has tuple: str = "";
}

walker InstBuilder {
    has max_depth: int = 5;
    has seen: list[str] = [];
    has accepted: list[str] = [];
    has refused: list[str] = [];
    has depth: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can build with GenericFn entry {
        self.seen.append(here.name);
        self.depth = self.depth + 1;
        if self.depth > self.max_depth {
            self.refused.append(here.name + ":depth-limit");
            self.depth = self.depth - 1;
            disengage;
        }
        visit [->:Instantiated:->];
    }

    can record with Instance entry {
        self.accepted.append(here.symbol);
        visit [-->];
    }

    can stop with Scope entry {
        self.depth = self.depth - 1;
    }

    can back with GenericFn exit {
        self.depth = self.depth - 1;
    }
}

walker ClosureAudit {
    has closure: list[str] = [];
    has rejected: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can audit with GenericFn entry {
        visit [->:Invokes:->];
    }

    can note with GenericFn entry {
        label = here.name + "/" + here.ownership;
        self.closure.append(label);
        visit [->:Invokes:->];
    }

    can finish with Scope entry {
        report self.closure;
        report self.rejected;
    }
}

with entry {
    identity = GenericFn(name="identity", arity=1, ownership="value", kind="id");
    pair = GenericFn(name="pair", arity=2, ownership="borrowed", kind="nontrivial");
    bad = GenericFn(name="mutual_a", arity=1, ownership="value", kind="recursion");

    id_int = Instance(symbol="identity$Int", concrete="Int");
    id_str = Instance(symbol="identity$Str", concrete="Str");
    pair_ib = Instance(symbol="pair$Int,bool", concrete="Int,bool");
    pair_bs = Instance(symbol="pair$bool,Str", concrete="bool,Str");

    call_site = Scope(label="call_site");
    nested_site = Scope(label="nested_site");

    root ++> identity ++> pair ++> bad;
    root ++> call_site ++> nested_site;

    identity +>:Instantiated(tuple="Int"):+> id_int;
    identity +>:Instantiated(tuple="Str"):+> id_str;
    pair +>:Instantiated(tuple="Int,bool"):+> pair_ib;
    pair +>:Instantiated(tuple="bool,Str"):+> pair_bs;

    call_site +>:Hosts(tuple="Int"):+> id_int;
    call_site +>:Invokes(tuple="Int"):+> identity;
    nested_site +>:Invokes(tuple="Int,bool"):+> pair;
    pair +>:Invokes(tuple="Str"):+> identity;

    builder = InstBuilder(max_depth=5);
    root spawn builder;
    print("accepted instances: " + ", ".join(builder.accepted));
    print("refused: " + ", ".join(builder.refused));

    auditor = ClosureAudit();
    root spawn auditor;
    print("closure: " + ", ".join(auditor.closure));
}
