```jac
"""Parent Task hierarchy: leaf-first execution with typed parent/child edges.

Models Glasswork's Parent Task PRD: tasks have a `type` (task | bug | parent),
a `source_kind` preserving the original ADO kind, and parent/child links that
form a forest of acyclic depth. Walkers exercise the hierarchy the issue
calls out: a recursive child collector with cycle/depth guards, a leaf-first
executor, an ancestor breadcrumb builder, and a Parent rollup summarizer.
"""

node Task {
    has title: str = "";
    has task_type: str = "task";
    has source_kind: str = "";
    has status: str = "open";
    has depth_limit: int = 32;

    def is_leaf() -> bool {
        return self.task_type == "task" or self.task_type == "bug";
    }

    def is_parent() -> bool {
        return self.task_type == "parent";
    }

    def label() -> str {
        kind = f"[{self.source_kind}]" if self.source_kind != "" else "";
        return f"{kind}{self.task_type}:{self.title}";
    }
}

edge ParentLink {
    has parent_id: str = "";
}

edge ChildLink {
    has order: int = 0;
}

walker HierarchyWalker {
    has report: list[str] = [];
    has visited: list[str] = [];
    has depth: int = 0;
    has leaf_order: list[str] = [];

    can start with Root entry {
        visit [->:ParentLink:->];
    }

    can descend_parent with Task entry {
        if self.task_type != "parent" {
            report_line = f"[skip non-parent at depth {self.depth}] {here.label()}";
            self.report.append(report_line);
            return;
        }
        self.visited.append(here.title);
        report_line = f"[parent d={self.depth}] {here.label()} status={here.status}";
        self.report.append(report_line);
        self.depth += 1;
        if self.depth > here.depth_limit {
            err_line = f"[depth-cap] exceeded {here.depth_limit} at {here.label()}";
            self.report.append(err_line);
            disengage;
        }
        visit [->:ChildLink:->];
    }

    can descend_child with Task entry {
        if here.title in self.visited {
            cycle_line = f"[cycle] revisiting {here.label()}";
            self.report.append(cycle_line);
            disengage;
        }
        self.visited.append(here.title);
        report_line = f"[child d={self.depth}] {here.label()} status={here.status}";
        self.report.append(report_line);
        if here.is_leaf() {
            self.leaf_order.append(here.title);
            leaf_line = f"[leaf] {here.label()} ready for execution";
            self.report.append(leaf_line);
        }
        visit [->:ChildLink:->];
    }

    can finalize with Root entry {
        summary = f"visited {len(self.visited)} nodes, {len(self.leaf_order)} leaves";
        self.report.append(summary);
        print("\n".join(self.report));
    }
}

walker BreadcrumbWalker {
    has crumb: list[str] = [];
    has found: str = "";

    can start with Root entry {
        self.crumb = [];
        self.found = "";
        visit [->:ParentLink:->];
    }

    can climb with Task entry {
        self.crumb.append(here.label());
        if here.title == self.found {
            done_line = f"breadcrumb for {self.found}: {' > '.join(self.crumb)}";
            print(done_line);
            disengage;
        }
        visit [->:ParentLink:->];
    }
}

walker RollupWalker {
    has total: int = 0;
    has open_count: int = 0;
    has done_count: int = 0;
    has leaf_count: int = 0;
    has visited: list[str] = [];

    can start with Root entry {
        self.total = 0;
        self.open_count = 0;
        self.done_count = 0;
        self.leaf_count = 0;
        self.visited = [];
        visit [->:ParentLink:->];
    }

    can roll with Task entry {
        if here.title in self.visited {
            revisit_line = f"[cycle] {here.label()}";
            print(revisit_line);
            disengage;
        }
        self.visited.append(here.title);
        self.total += 1;
        if here.status == "done" {
            self.done_count += 1;
        } else {
            self.open_count += 1;
        }
        if here.is_leaf() {
            self.leaf_count += 1;
        }
        if here.is_parent() {
            visit [->:ChildLink:->];
        }
    }
}

with entry {
    epic = Task(title="Epic-Q4", task_type="parent", source_kind="Epic");
    feature = Task(title="Feature-Auth", task_type="parent", source_kind="Feature");
    pbi = Task(title="PBI-Login", task_type="parent", source_kind="Product Backlog Item");
    story = Task(title="Story-OAuth", task_type="parent", source_kind="User Story");

    leaf_one = Task(title="Task-impl-token", task_type="task", source_kind="Task");
    leaf_two = Task(title="Task-impl-refresh", task_type="task", source_kind="Task");
    bug_one = Task(title="Bug-null-pointer", task_type="bug", source_kind="Bug");

    root +>:ParentLink:+> epic;
    epic +>:ChildLink(order=0):+> feature;
    feature +>:ChildLink(order=0):+> pbi;
    pbi +>:ChildLink(order=0):+> story;
    story +>:ChildLink(order=0):+> leaf_one;
    story +>:ChildLink(order=1):+> leaf_two;
    story +>:ChildLink(order=2):+> bug_one;

    print("=== HierarchyWalker: leaf-first traversal with cycle/depth guards ===");
    root spawn HierarchyWalker();

    print("\n=== BreadcrumbWalker: ancestor path for a deep leaf ===");
    bw = BreadcrumbWalker(found="Task-impl-refresh");
    leaf_two spawn bw;

    print("\n=== RollupWalker: Parent rollup without distributed child updates ===");
    roll = RollupWalker();
    epic spawn roll;
    summary_line = (
        f"rollup epic -> total={roll.total} open={roll.open_count} "
        f"done={roll.done_count} leaves={roll.leaf_count}"
    );
    print(summary_line);
}
