"""Mesh pipeline with junctions that stitch the aggregate component's last generator.

Models the moose issue #33227 scenario: components own mesh generators and
junctions stitch outputs from the aggregate component. If junctions run
*before* the aggregate component has appended its last mesh generator, the
stitch sees a stale (disconnected) mesh. A walker validates execution
ordering by walking the dependency graph and detecting cycles / missing
dependencies.
"""

# ---- Core entities --------------------------------------------------------

node MeshGenerator {
    has name: str = "";
    has registered: bool = False;
}

node Component {
    has name: str = "";
    has aggregated: bool = False;
    # The "last generator" the junctions will try to stitch to.
    has last_generator_name: str = "";
}

# A junction stitches two components' mesh outputs together.
node ComponentJunction {
    has name: str = "";
    has upstream_name: str = "";
    has downstream_name: str = "";
    # Marks whether this junction's stitch has been satisfied.
    has stitched: bool = False;
}

# ---- Typed edges ----------------------------------------------------------

# A component declares it owns a mesh generator (the generator was appended
# via addMeshGenerator).
edge OwnsGenerator {
    has order_index: int = 0;
}

# A junction points at a component it needs to stitch from.
edge TargetsComponent {
    has role: str = "";
}

# Dependency: "this thing must run after that thing".
edge DependsOn {
    has reason: str = "";
}

# ---- Traversal walker -----------------------------------------------------

walker DependencyAuditor {
    has visited: list[str] = [];
    has ordering_errors: list[str] = [];

    can begin with Root entry {
        print("Auditing mesh-pipeline execution order...");
        visit [-->];
    }

    can audit_component with Component entry {
        print(f"[component] {here.name} (aggregated={here.aggregated})");
        self.visited.append(here.name);
        visit [->:TargetsComponent:->];
    }

    can audit_generator with MeshGenerator entry {
        if not here.registered {
            self.ordering_errors.append(
                f"generator '{here.name}' was never registered via addMeshGenerator"
            );
        }
        visit [->:DependsOn:->];
    }

    can audit_junction with ComponentJunction entry {
        # The junction expects upstream to have a last generator ready.
        upstream_ready = False;
        for g in [-->] {
            if g.last_generator_name == here.upstream_name {
                upstream_ready = True;
            }
        }
        if not upstream_ready {
            self.ordering_errors.append(
                f"junction '{here.name}' stitched before "
                f"upstream '{here.upstream_name}' had a last generator"
            );
        } else {
            here.stitched = True;
            print(f"[junction] {here.name} stitched OK");
        }
        visit [->:TargetsComponent:->];
    }
}

# A second walker that performs the hand-rolled "find aggregate component
# and its last generator" traversal the issue complains about, but
# natively via typed edges.
walker LastGeneratorResolver {
    has found_name: str = "";

    can begin with Root entry {
        visit [-->];
    }

    can pick_component with Component entry {
        if here.aggregated {
            print(f"picked aggregate component: {here.name}");
            # Walk its owned generators in declared order and pick the last.
            gens: list[MeshGenerator] = [];
            for g in [->:OwnsGenerator:->] {
                gens.append(g);
            }
            if gens {
                gens.sort(key=lambda gx: gx);
                picked = gens[-1];
                self.found_name = picked.name;
                print(f"last generator on aggregate: {picked.name}");
            } else {
                self.found_name = "";
                print("aggregate component has no generators yet");
            }
        }
        visit [-->];
