"""Composer timeout configuration modeled as a graph of projects, config,
and command invocations. A walker traverses the project graph, looks up the
per-project composer timeout from the config node, and reports whether each
command would run inside or outside its window.
"""

node Project {
    has name: str = "";
    has default_timeout: int = 300;
}

node Config {
    has composer_timeout: int = 300;
}

node Command {
    has kind: str = "";
    has label: str = "";
    has explicit_timeout: int = 0;
}

edge OwnsConfig {}
edge RunsCommand {}

walker Auditor {
    can start with Root entry {
        visit [-->];
    }

    can enter_project with Project entry {
        print(f"Project: {here.name} (fallback timeout {here.default_timeout}s)");
        visit [->:OwnsConfig:->];
    }

    can load_config with Config entry {
        self.adopted_timeout = here.composer_timeout;
        visit [->:RunsCommand:->];
    }

    can check_command with Command entry {
        explicit_here = here.explicit_timeout;
        chosen = self.adopted_timeout;
        if explicit_here > 0 {
            chosen = explicit_here;
        }
        if here.kind == "composer" {
            effective = chosen;
        } else {
            effective = here.default_timeout_fallback;
        }
        verdict = "OK" if effective >= 60 else "RISK";
        print(f"  [{verdict}] {here.kind} '{here.label}' -> {effective}s");
        visit [-->];
    }
}

