Issue #15: CI Workflow

## Objective

Create the initial CI/CD workflow using GitHub Actions.

## Tasks

- Install dependencies
- Run lint
- Run tests
- Build project

## Acceptance Criteria

- Workflow runs on every Pull Request
- Failed checks block merge

Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.

```jac
"""CI Workflow: model the CI/CD pipeline as a graph and walk it for ordering.

The CI pipeline is a directed graph of pipeline stages (Checkout, Install,
Lint, Test, Build). Each stage has typed dependencies and may be required
for a Pull Request to be mergeable. A walker performs an explicit
depth-limited, cycle-guarded traversal to (a) compute a topological order
of stages, (b) detect cycles, and (c) decide whether the PR is blocked.
"""

node Stage {
    has name: str = "";
    has blocking: bool = True;
}

edge DependsOn {
    has since_pr: int = 1;
}

# A pipeline is a named holder that connects to the first stage(s).
node Pipeline {
    has name: str = "";

    can head with Stage entry {
        visit [-->];
    }
}

walker PipelineRunner {
    has pr_number: int = 42;
    has order: list[str] = [];
    has depth_limit: int = 16;
    has visited: dict[str, int] = {};
    has blocked: bool = False;
    has cycle: bool = False;

    can start with Pipeline entry {
        print(f"PR #{self.pr_number}: evaluating pipeline '{here.name}'");
        visit [-->];
    }

    # Union ability: Pipeline head stage fires; we descend into dependents.
    can descend with Stage entry {
        depth = self.visited.get(here.name, -1);
        if depth >= 0 {
            # Already on the current path -> cycle.
            self.cycle = True;
            print(f"  CYCLE detected at '{here.name}'");
            visit [-->] else { disengage; }
        }
        if self.order.index(here.name) if here.name in self.order else -1 >= 0 {
            # Already finalized -> skip.
            visit [-->] else { disengage; }
        }
        new_depth = depth + 1 if depth >= 0 else 0;
        self.visited[here.name] = new_depth;
        if new_depth >= self.depth_limit {
            self.blocked = True;
            print(f"  depth limit hit at '{here.name}'");
            visit [-->] else { disengage; }
        }
        # Recurse into stages this stage depends on.
        visit [->:DependsOn:->];
    }

    # Finalize a stage: append to topological order, mark blocked if needed.
    can finalize with Stage entry {
        idx = self.order.index(here.name) if here.name in self.order else -1;
        if idx < 0 {
            self.order.append(here.name);
        }
        if here.blocking {
            self.blocked = True;
            print(f"  blocking stage '{here.name}' keeps PR open");
        }
        # No further visit: this ability runs on leaf stages after recursion
        # has unwound through typed edges via the second `visit` in `descend`.
        visit [-->] else { disengage; }
    }
}

walker Reporter {
    can start with Root entry {
        visit [-->];
    }

    can summarize with Pipeline entry {
        runner = PipelineRunner(pr_number=99);
        here spawn runner;
        print(f"pipeline '{here.name}' order: {runner.order}");
        print(f"cycle detected: {runner.cycle}");
        print(f"PR blocked: {runner.blocked}");
        visit [-->] else { disengage; }
    }
}

with entry {
    checkout = Stage(name="checkout", blocking=False);
    install = Stage(name="install", blocking=False);
    lint = Stage(name="lint", blocking=True);
    test = Stage(name="test", blocking=True);
    build = Stage(name="build", blocking=True);

    # Typed-edge dependency graph: A +>:DependsOn:+> B means "A depends on B".
    checkout +>:DependsOn(since_pr=1):+> install;
    install +>:DependsOn(since_pr=1):+> lint;
    install +>:DependsOn(since_pr=1):+> test;
    test +>:DependsOn(since_pr=1):+> build;

    ci = Pipeline(name="ci");
    root ++> ci ++> checkout;

    root spawn Reporter();
}
```

