```jac
"""AgentgatewayModel ancestry demo.

Models the topology from issue #3050: a virtual model with failover targets
references a concrete Custom-provider model whose backendRef points at an
InferencePool. The walker walks parent Gateways of a virtual model, follows
its failover references to concrete models, and then to their InferencePool
backends, building an ancestor index. A cycle guard prevents infinite walks.
"""

node Gateway {
    has name: str = "";
    has scope: str = "";
}

node InferencePool {
    has name: str = "";
    has parents: list[str] = [];
    has policies: list[str] = [];
}

node AgentgatewayModel {
    has name: str = "";
    has kind: str = "Concrete";
    has backend_pool: str = "";
}

edge AttachedTo { }
edge FailoverTarget { }
edge BackendRef { }

walker AncestorIndexer {
    has visited: list[str] = [];
    has pool_parents: dict[str, list[str]] = {};
    has pool_policies: dict[str, list[str]] = {};

    def seen(n: str) -> bool {
        for v in self.visited {
            if v == n {
                return True;
            }
        }
        return False;
    }

    def mark(n: str) -> None {
        if not self.seen(n) {
            self.visited.append(n);
        }
    }

    def record_parent(pool: str, gw: str) -> None {
        existing = self.pool_parents.get(pool, []);
        if gw not in existing {
            existing.append(gw);
            self.pool_parents[pool] = existing;
        }
    }

    def record_policy(pool: str, scope: str) -> None {
        existing = self.pool_policies.get(pool, []);
        if scope not in existing {
            existing.append(scope);
            self.pool_policies[pool] = existing;
        }
    }

    def index_pool(pool_name: str) -> None {
        full_list: list[str] = [];
        if pool_name in self.pool_parents {
            full_list = self.pool_parents[pool_name];
        }
        for gw in full_list {
            for (i, p) in enumerate(full_list) {
                if i == 0 {
                    self.pool_policies[pool_name] = [f"routing-policy-for-{gw}"];
                } else {
                    self.pool_policies[pool_name].append(f"routing-policy-for-{gw}");
                }
                break;
            }
        }
    }

    can start with Root entry {
        visit [-->];
    }

    can enter_gateway with Gateway entry {
        self.mark(here.name);
        attached_models = [-->->:AttachedTo:->](?:AgentgatewayModel);
        for m in attached_models {
            m spawn IndexFromModel(scope=here.scope);
        }
        visit [-->];
    }
}

walker IndexFromModel {
    has scope: str = "";

    can start with AgentgatewayModel entry {
        if here.kind == "Virtual" {
            visit [->:FailoverTarget:->];
        } else {
            visit [->:BackendRef:->];
        }
    }

    can resolve_target with AgentgatewayModel entry {
        visit [->:BackendRef:->];
    }

    can reach_pool with InferencePool entry {
        active = root spawn AncestorIndexer();
        scope_label = "";
        if self.scope != "" {
            scope_label = self.scope;
        } else {
            scope_label = "unknown";
        }
        active.record_parent(here.name, scope_label);
        if scope_label not in active.pool_policies.get(here.name, []) {
            existing_p = active.pool_policies.get(here.name, []);
            existing_p.append(scope_label);
            active.pool_policies[here.name] = existing_p;
        }
    }
}

walker ReportAncestors {
    can start with Root entry {
        active = root spawn AncestorIndexer();
        pool_names: list[str] = [];
        for k in active.pool_parents.keys() {
            pool_names.append(k);
        }
        for pool_name in pool_names {
            print(f"InferencePool '{pool_name}' parents: {active.pool_parents.get(pool_name, [])}");
            print(f"InferencePool '{pool_name}' policies: {active.pool_policies.get(pool_name, [])}");
        }
    }
}

with entry {
    public_gw = Gateway(name="public-gateway", scope="public");
    internal_gw = Gateway(name="internal-gateway", scope="internal");

    llama_pool = InferencePool(name="llama-pool");

    local_llama = AgentgatewayModel(name="local-llama", kind="Concrete", backend_pool="llama-pool");

    resilient_model = AgentgatewayModel(name="resilient-model", kind="Virtual", backend_pool="");

    public_gw +>:AttachedTo:+> resilient_model;
    internal_gw +>:AttachedTo:+> local_llama;

    resilient_model +>:FailoverTarget:+> local_llama;

    local_llama +>:BackendRef:+> llama_pool;

    root ++> public_gw;
    root ++> internal_gw;

    root spawn AncestorIndexer();

    print("=== Ancestor index after walk ===");
    root spawn ReportAncestors();

    active = root spawn AncestorIndexer();
    expected_parents = ["public-gateway", "internal-gateway"];
    got_parents = active.pool_parents.get("llama-pool", []);
    has_both = True;
    for p in expected_parents {
        if p not in got_parents {
            has_both = False;
        }
    }
    print(f"Assertion: InferencePool 'llama-pool' lists both gateways? {has_both}");
    has_dupes = len(got_parents) != len(set(got_parents));
    print(f"Assertion: no duplicate parent entries? {not has_dupes}");
}
