```jac
"""Rental shop media shelf audit.

Books and DVDs have dedicated audit reporting. Anything else on the
shelf (an unclassified archive reel, a stray magazine) falls through to
the default handler. A union ability covers the two known media types,
and a default ability catches the rest.
"""

node Book {
    has title: str = "";
    has author: str = "";
    has year: int = 0;
    has available: bool = True;
}

node DVD {
    has title: str = "";
    has runtime: int = 0;
    has available: bool = True;
}

edge Shelved { has slot: str = ""; }

walker Auditor {
    has total: int = 0;
    has default_count: int = 0;

    can start with Root entry {
        visit [->:Shelved:->];
    }

    # Default fires for any node that doesn't match Book or DVD.
    can fallthrough with Book entry {
        self.default_count += 1;
    }
    can fallthrough with DVD entry {
        self.default_count += 1;
    }

    can report_known with Book | DVD entry {
        kind = "BOOK" if here.title else "DVD";
        if isinstance(here, Book) {
            kind = "BOOK";
            print(f"[{kind}] {here.title} by {here.author} ({here.year})");
        } else {
            kind = "DVD";
            print(f"[{kind}] {here.title} ({here.runtime} min)");
        }
        self.total += 1;
    }
}

node ArchiveReel {
    has label: str = "";
    has year: int = 0;
    has available: bool = True;
}

# Give ArchiveReel its own default handler so Auditor's default fires.
# Re-declare union ability so the auditor counts known types only.
walker Auditor2 {
    has total: int = 0;
    has default_count: int = 0;

    can start with Root entry {
        visit [->:Shelved:->];
    }

    can known with Book | DVD entry {
        if isinstance(here, Book) {
            print(f"[BOOK] {here.title} by {here.author} ({here.year})");
        } else {
            print(f"[DVD] {here.title} ({here.runtime} min)");
        }
        self.total += 1;
    }

    can fallback with ArchiveReel entry {
        print(f"[ARCHIVE] {here.label} ({here.year}) -- default path");
        self.default_count += 1;
    }
}

with entry {
    b1 = Book(title="The Hobbit", author="Tolkien", year=1937);
    b2 = Book(title="Dune", author="Herbert", year=1965, available=False);
    d1 = DVD(title="Blade Runner", runtime=117);
    d2 = DVD(title="Inception", runtime=148);
    reel = ArchiveReel(label="Newsreel 42", year=1952);

    root +>:Shelved(slot="A1"):+> b1;
    root +>:Shelved(slot="A2"):+> b2;
    root +>:Shelved(slot="D1"):+> d1;
    root +>:Shelved(slot="D2"):+> d2;
    root +>:Shelved(slot="X1"):+> reel;

    a = Auditor2();
    root spawn a;
    print(f"Total audited: {a.total}, default path: {a.default_count}");
}
