Task:
A maintainer on the project Chris-Wolfgang/Hawsey (unknown) filed this issue about hand-rolled graph machinery causing pain:

Issue #84: [Maintenance] CI/CD: License audit on transitive dependencies (dotnet-licenses / FOSSA)

## Scope

Dependabot tracks dependency *versions* (and CVE alerts). It does not check the *licenses* of transitive dependencies. A new transitive dependency with an incompatible license (GPL, AGPL, OSL, business-source) silently leaks into a derivative work distributed under MIT — a real procurement / legal exposure for downstream consumers.

The deferred work is a license-audit workflow using `dotnet-licenses` / FOSSA / Snyk Open Source / similar that enumerates every transitive package, captures its declared license, and fails the build on incompatible / unknown licenses.

## Acceptance criteria

- A `license-audit.yaml` workflow runs on PR + scheduled.
- Findings produce a `THIRD-PARTY-NOTICES.md` (or similar) generated automatically per release; license attribution is shipped in the NuGet package per the licenses' requirements.
- A documented allowlist (MIT / Apache-2.0 / BSD-2-Clause / BSD-3-Clause / similar) gates new packages; anything else needs explicit reviewer approval recorded in the PR.
- A baseline scan of the current `main` documents current dependencies + licenses.

## Notes

- Tier-1 follow-up. Required for procurement at most enterprises; goes beyond Dependabot's surface.
- Originated as part of the IAsyncEnumerable-Extensions thorough-review pass; tracked fleet-wide.
- Board: https://github.com/users/Chris-Wolfgang/projects/6

Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.

```jac
"""License audit on transitive dependencies.

Models a NuGet-style dependency graph and a license-audit walker that
traverses it, reports each package's declared license, and flags
incompatible / unknown licenses against an allowlist. Demonstrates
typed edges (DependsOn), walker traversal with cycle safety, and a
two-phase audit (direct deps via typed edges + transitive deps via
walker descent).
"""

node Package {
    has name: str = "";
    has version: str = "";
    has license: str = "";
    has approved: bool = False;
    has finding: str = "";
}

edge DependsOn {
    has version_req: str = "";
}

walker LicenseAuditor {
    has allowlist: list[str] = ["MIT", "Apache-2.0", "BSD-2-Clause", "BSD-3-Clause"];
    has reports: list[dict] = [];
    has visited: list[str] = [];

    can start with Root entry {
        print("License audit starting from root...");
        visit [-->];
    }

    can audit with Package entry {
        key = here.name + "@" + here.version;
        if key in self.visited {
            visit [-->] else { disengage; }
        }
        self.visited.append(key);

        verdict = "OK";
        if here.license == "" {
            verdict = "UNKNOWN";
        } elif not (here.license in self.allowlist) {
            verdict = "INCOMPATIBLE";
        }

        if verdict != "OK" {
            here.approved = False;
            here.finding = f"{verdict}: license '{here.license}' not on allowlist";
            print(f"  [FAIL] {here.name} ({here.version}) -- {here.finding}");
        } else {
            here.approved = True;
            print(f"  [PASS] {here.name} ({here.version}) -- {here.license}");
        }

        record = {
            "name": here.name,
            "version": here.version,
            "license": here.license,
            "verdict": verdict
        };
        self.reports.append(record);

        visit [->:DependsOn:->] else { disengage; }
    }
}

walker Notifier {
    can start with Root entry {
        print("\nAudit summary report:");
        visit [-->];
    }

    can notify with Package entry {
        if here.finding != "" {
            print(f"  ! {here.name}@{here.version} flagged: {here.finding}");
        }
        visit [-->];
    }
}

with entry {
    app = Package(name="MyApp", version="1.0.0", license="MIT", approved=True);
    json = Package(name="Newtonsoft.Json", version="13.0.3", license="MIT");
    restsharp = Package(name="RestSharp", version="111.0.0", license="Apache-2.0");
    copyleft = Package(name="GPLHelper", version="2.5.0", license="GPL-3.0");
    unknown = Package(name="MysteryLib", version="0.1.0", license="");
    bsd = Package(name="NLog", version="5.2.5", license="BSD-3-Clause");
    agpl = Package(name="CopyleftDB", version="1.0.0", license="AGPL-3.0");

    root ++> app;
    app +>:DependsOn(version_req=">=13.0.0"):+> json;
    app +>:DependsOn(version_req=">=110.0.0"):+> restsharp;
    app +>:DependsOn(version_req="*"):+> copyleft;
    json +>:DependsOn(version_req="*"):+> unknown;
    json +>:DependsOn(version_req=">=5.0.0"):+> bsd;
    restsharp +>:DependsOn(version_req="*"):+> agpl;

    auditor = LicenseAuditor();
    root spawn auditor;

    print("");
    print(f"Audited {len(auditor.reports)} packages "
          f"({len(auditor.visited)} unique, cycle-guarded).");

    notifier = Notifier();
    root spawn notifier;
}
