```jac
"""Wildlife park feeding rounds: kiosk greets every party, zookeepers feed animals their species-appropriate meal, and school groups just observe."""

node Animal {
    has species: str = "";
    has name: str = "";
    has fed: bool = False;

    def meal() -> str {
        return "standard feed";
    }

    def feed() -> None {
        self.fed = True;
    }
}

node Lion(Animal) {
    override def meal() -> str {
        return "meat";
    }
}

node Parrot(Animal) {
    override def meal() -> str {
        return "seed";
    }
}

# --- Walkers ---

# The info kiosk greets EVERY tour party regardless of type.
walker InfoKiosk {
    has greeted_count: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can greet with TourParty entry {
        print(f"Kiosk: welcome, {here.label}!");
        self.greeted_count += 1;
        visit [-->];
    }

    can greet_animals with Animal | Lion | Parrot entry {
        print(f"Kiosk: welcome, {here.species} named {here.name}!");
        self.greeted_count += 1;
        visit [-->];
    }
}

# Zookeepers feed each animal its species-appropriate meal.
walker Zookeeper {
    can start with Root entry {
