Issue #1237: [Feature Request] - Make subquery support Base-Query

### Reason

Hi! Sometimes, I wish the result of a CTE recursive query could be used as a subquery within another query. For example:

```SQL
WITH RECURSIVE cte AS ( 
  SELECT foo_id from tree_table where parent_id IS NULL 
  UNION ALL
  SELECT children.foo_id from tree_table children INNER JOIN cte cte_parent ON children.parent_id = cte_parent.id
)
SELECT * from foo where id IN (SELECT foo_id in cte)
```

However, Base-Query now appears to only support usage within root queries (please correct me if I'm mistaken).



### Description

Therefore, I hope subquery can support Base-Query.

### Existing solutions

Consequently, I now have to split a single query into two steps:
1. Use a recursive CTE query to generate the full list of IDs I need.
2. Process this ID list within the code and then use it as a parameter for the query.

Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.

```jac
"""Recursive CTE-like subquery: traverse a tree by walking typed parent/child
edges, then use the accumulated descendant set as an in-clause filter for a
second query node — modeling the Base-Query subquery feature request.
"""

node Foo {
    has foo_id: int = 0;
    has label: str = "";
}

node TreeTable {
    has row_id: int = 0;
}

# Base-Query / CTE: yields the recursive descendant id set.
node RecursiveCTE {
    has descendants: list[int] = [];
    has done: bool = False;
}

# Second query: filters Foo rows by the CTE's collected ids (the subquery).
node FooSubquery {
    has results: list[str] = [];
}

# Typed edge: a tree_table row's parent reference.
edge Parent {
    has parent_id: int = 0;
}

# Typed edge: links a CTE node to its anchor tree row.
edge Anchors {
}

# Typed edge: links the CTE output into the consuming subquery.
edge Consumes {
}

walker CollectDescendants {
    has guard: set[int] = {};
    has root_ids: list[int] = [];

    can start with Root entry {
        visit [-->];
    }

    can gather with RecursiveCTE entry {
        # Prime the recursion with the CTE's anchor ids.
        self.guard = {};
        visit [here->:Parent:->];
    }

    can walk_tree with TreeTable entry {
        if here.row_id in self.guard {
            # Cycle guard: domain logic preserved — bail out of this lineage.
            disengage;
        }
        self.guard.add(here.row_id);
        self.root_ids.append(here.row_id);
        visit [here->:Parent:->];
    }

    can deposit with Root entry {
        # Write the accumulated ids back into the CTE node for the subquery.
        cte = [here-->][0];
        cte.descendants = self.root_ids;
        cte.done = True;
    }
}

walker RunSubquery {
    can start with Root entry {
        cte = [here-->][0];
        sub = [here-->][1];
        if not cte.done {
            print("CTE not ready");
            disengage;
        }
        # Walk Foo rows reachable through Anchors edges.
        visit [here->:Anchors:->];
    }

    can scan with Foo entry {
        # The "IN (SELECT foo_id FROM cte)" test.
        cte = [-->][0] del -->;
        visit [here->:Consumes:->];
    }

    can project with FooSubquery entry {
        print(f"subquery matched {len(here.results)} foo row(s): {here.results}");
    }
}

with entry {
    # Build a tree_table fragment with a back-edge to make the recursion
    # policy observable.
    t1 = TreeTable(row_id=1);
    t2 = TreeTable(row_id=2);
    t3 = TreeTable(row_id=3);
    t4 = TreeTable(row_id=4);
    root ++> t1 +>:Parent(parent_id=0):+> t2;
    t2 +>:Parent(parent_id=1):+> t3;
    t3 +>:Parent(parent_id=2):+> t4;
    t4 +>:Parent(parent_id=3):+> t1;  # cycle: 1 -> 2 -> 3 -> 4 -> 1

    # Foo rows to be filtered by the subquery.
    f1 = Foo(foo_id=1, label="alpha");
    f2 = Foo(foo_id=2, label="beta");
    f3 = Foo(foo_id=3, label="gamma");
    f4 = Foo(foo_id=4, label="delta");
    f99 = Foo(foo_id=99, label="unrelated");

    # Recursive CTE node anchored at row 1.
    cte = RecursiveCTE();
    root ++> cte;
    cte +>:Anchors:+> t1;

    # Subquery node that consumes the CTE output.
    sub = FooSubquery();
    root ++> sub;
    sub +>:Consumes:+> f1;
    sub +>:Consumes:+> f2;
    sub +>:Consumes:+> f3;
    sub +>:Consumes:+> f4;
    sub +>:Consumes:+> f99;

    # First pass: walk the tree under the CTE, collecting descendant ids.
    root spawn CollectDescendants();
    print(f"CTE collected descendant ids: {cte.descendants}");

    # Second pass: feed the CTE's id set into the consuming subquery.
    root spawn RunSubquery();
}
