Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.

```jac
"""Artifact reload & rollback correctness gates.

Models the essential scenario from issue #364: cumulative publication of
physical artifacts (HF / GGUF), validation gates, rollback lineage, and
cascade invalidation when a parent is found corrupt. Relationships live
as typed edges; traversal and rollback lineage walk those edges via
walkers, replacing hand-rolled parent_id recursion.
"""

# ---------- Edge archetypes ----------

edge StagesInto { has stage_name: str = ""; }

edge ValidatedBy { has gate: str = ""; }

edge Parent { has version: int = 0; }

edge Rollback { has reason: str = ""; }


# ---------- Node archetypes ----------

node Artifact {
    has title: str = "";
    has fmt: str = "";
    has version: int = 0;
    has checksum: str = "";
    has available: bool = True;
    has corrupt: bool = False;
}

node ValidationGate {
    has title: str = "";
    has passed: bool = False;
}

node LastKnownGood {
    has title: str = "";
    has fmt: str = "";
    has version: int = 0;
    has checksum: str = "";
}


# ---------- Walkers ----------

# Validate a single artifact against its gate(s). Stamps a ValidationGate
# node reachable via ValidatedBy so downstream walkers can audit lineage.
walker Gatekeeper {
    can start with Root entry {
        visit [-->];
    }

    can inspect with Artifact entry {
        verdict = "PASS" if (here.available and not here.corrupt) else "FAIL";
        # Attach a typed-edge outcome node so the result is graph-resident,
        # not a transient print, and the audit walker can walk it later.
        gate = ValidationGate(title=f"{here.title}-v{here.version}", passed=(verdict == "PASS"));
        here +>:ValidatedBy(gate=verdict):+> gate;
        print(f"[{verdict}] {here.title} ({here.fmt} v{here.version})");
        visit [-->];
    }
}


# Walk parent lineage (typed Parent edges) to confirm every ancestor of
# an artifact is still valid. Replaces the hand-rolled parent_id recursion.
walker LineageAuditor {
    has depth_budget: int = 16;
    has depth: int = 0;
    has saw_corrupt_parent: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can audit with Artifact entry {
        self.depth += 1;
        if self.depth > self.depth_budget {
            print(f"[DEPTH-CAP] lineage of {here.title} exceeds {self.depth_budget}");
            self.saw_corrupt_parent = True;
            disengage;
        }
        if here.corrupt {
            self.saw_corrupt_parent = True;
            print(f"[CORRUPT-PARENT] {here.title} v{here.version} flagged on lineage");
        }
        visit [->:Parent:->] else {
            disengage;
        }
    }
}


# Cascade-invalidate every descendant Artifact reachable through Parent
# edges once an ancestor is declared corrupt. Replaces manual cascade
# deletes that previously lived as adjacency-dict BFS.
walker InvalidationCascade {
    has invalidated_count: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can cascade with Artifact entry {
        if here.corrupt {
            here.available = False;
            self.invalidated_count += 1;
            print(f"[INVALIDATE] {here.title} v{here.version}");
        } else {
            print(f"[KEEP] {here.title} v{here.version}");
        }
        visit [->:Parent:->] else {
            disengage;
        }
    }
}


# Walk ValidatedBy edges to report the promotion decision for every
# artifact gate. Order-insensitive: gates are independent outcomes.
walker PromotionReporter {
    can start with Root entry {
        visit [-->];
    }

    can report with Artifact entry {
        visit [->:ValidatedBy:->];
    }

    can tally with ValidationGate entry {
        verdict = "OK" if here.passed else "BLOCKED";
        print(f"[PROMOTION {verdict}] {here.title}");
        visit [-->];
    }
}


# Roll back to a LastKnownGood anchor: walk Parent edges backward from
# the current Artifact, record a Rollback edge to the anchor, and
# invalidate the descendants. Demonstrates safe-resume semantics.
walker RollbackToGood {
    has anchor: LastKnownGood | None = None;
    has rolled_back: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can descend with Artifact entry {
        # Find the anchor among outgoing Parent edges whose child matches
        # the anchor's title; attach a Rollback edge as lineage proof.
        anchor = self.anchor;
        if anchor is None {
            print(f"[ROLLBACK-NO-ANCHOR] nothing to recover");
            disengage;
        }
        if here.title == anchor.title and here.fmt == anchor.fmt {
            here +>:Rollback(reason="recovered-to-lkg"):+> anchor;
            self.rolled_back = True;
            print(f"[ROLLBACK] {here.title} v{here.version} -> LKG v{anchor.version}");
        }
        visit [->:Parent:->] else {
            disengage;
        }
    }
}


with entry {
    # Source artifact: intact baseline.
    src = Artifact(title="llama-tiny", fmt="HF", version=1, checksum="sha256:aaaa");

    # Cumulative publication: v1 -> v2 -> v3, where v3 is corrupted by
    # an interrupted write (power-loss scenario from the issue).
    v2 = Artifact(title="llama-tiny", fmt="HF", version=2, checksum="sha256:bbbb", available=False);
    v3 = Artifact(
        title="llama-tiny", fmt="HF", version=3, checksum="sha256:cccc", available=False, corrupt=True
    );

    # Wire the chain via typed Parent edges (versioned lineage).
    root +>:StagesInto(stage_name="publish"):+> src;
    src +>:Parent(version=1):+> v2;
    v2 +>:Parent(version=2):+> v3;

    # A separate, valid GGUF artifact on a sibling branch.
    gguf = Artifact(title="llama-tiny", fmt="GGUF", version=1, checksum="sha256:dddd");
    root +>:StagesInto(stage_name="publish"):+> gguf;

    # Last-known-good anchor for rollback demos.
    lkg = LastKnownGood(title="llama-tiny", fmt="HF", version=1, checksum="sha256:aaaa");
    root +>:StagesInto(stage_name="lkg"):+> lkg;

    # 1. Validation gate pass on every artifact.
    root spawn Gatekeeper();

    # 2. Lineage audit from each artifact; v3's lineage should flag v3.
    root spawn LineageAuditor();
    root spawn LineageAuditor();
    root spawn LineageAuditor();

    # 3. Cascade invalidation from the corrupt v3 downward (none below)
    #    and from src downward to mark descendants unavailable.
    root spawn InvalidationCascade();

    # 4. Promotion decision report walking the ValidatedBy edges.
    root spawn PromotionReporter();

    # 5. Rollback demo: from v3, recover toward the v1 LKG.
    rb = RollbackToGood(anchor=lkg);
    root spawn rb;
}
