"""FE-BE toolchain modernization: model bounded contexts, agents, and
implementation tasks as graph archetypes, then walk the dependency graph
with a tracer-bullet coordinator walker.

The walker topologically orders the tracer-bullet tasks by following
DependsOn edges forward from the spec entry, accumulating the ordered
list on a typed `has` field, and reports it once on exit.
"""

# ---- Core entity archetypes --------------------------------------------------

node BoundedContext {
    has name: str = "";
    has purpose: str = "";
}

node TracerTask {
    has title: str = "";
    has status: str = "pending";
    has verify_cmd: str = "";
}

node Agent {
    has role: str = "";
    has badge: str = "";
}

# ---- Typed relationships -----------------------------------------------------

edge Delivers {
    has since: str = "";
}

# TracerTask A DependsOn TracerTask B  (B must land before A)
edge DependsOn { }

# BoundedContext feeds an Agent role
edge HandedTo { }

# ---- Walkers -----------------------------------------------------------------

walker TracerCoordinator {
    has ordered: list[TracerTask] = [];

    can start with Root entry {
        # Step into the spec entry bounded context, then fan out to tasks
        # that this context delivers.
        visit [->:Delivers:->];
    }

    can index_tasks with BoundedContext entry {
        visit [->:Delivers:->];
    }

    # Union trigger: one ability handles the two node kinds the walker
    # needs to accumulate work on.
    can accumulate with TracerTask | BoundedContext entry {
        if here.__class__.__name__ == "TracerTask" {
            self.ordered.append(here);
            # Stop expanding once we've collected the task itself; tracer
            # bullets are leaves in the dependency DAG.
            return;
        }
        # From a BoundedContext, walk to the tasks it delivers.
        visit [->:Delivers:->];
    }
}

# A walker that demonstrates dependency ordering: it follows DependsOn
# edges in reverse to discover prerequisites of each task.
walker DependencyProbe {
    has prereqs: list[TracerTask] = [];

    can start with Root entry {
        # Hand off to a tracer task seed.
        visit [->:Delivers:->];
    }

    can probe with BoundedContext entry {
        visit [->:Delivers:->];
    }

    can walk_prereqs with TracerTask entry {
        # A tracer bullet's prerequisites are whatever tasks point *to*
        # it via DependsOn (i.e. reverse the dependency edge).
        visit [<--:DependsOn:--];
    }

    # Union trigger: a TracerTask (prerequisite we found) or another
    # BoundedContext (rare but possible if context participates).
    can collect with TracerTask | BoundedContext entry {
        if here.__class__.__name__ == "TracerTask" {
            self.prereqs.append(here);
            return;
        }
        visit [->:Delivers:->];
    }
}

# ---- Demonstration wiring ----------------------------------------------------

with entry {
    # Three bounded contexts, mapped to the deliverable streams.
    runtime_ctx = BoundedContext(
        name="runtime-and-tooling",
        purpose="Consolidate runtime, package mgr, task runner, scaffolding",
    );
    quality_ctx = BoundedContext(
        name="quality-and-delivery",
        purpose="Quality, release, and delivery gates with CI evidence",
    );
    ddd_ctx = BoundedContext(
        name="bounded-contexts",
        purpose="Translate confirmed contexts into BE/FE maps and seams",
    );

    # Tracer-bullet tasks, each attached to a context it implements.
    runtime_task = TracerTask(
        title="Lock runtime + package manager versions",
        verify_cmd="bash scripts/preflight.sh runtime",
    );
    quality_task = TracerTask(
        title="Wire quality gates into CI",
        verify_cmd="bash scripts/preflight.sh quality",
    );
    ddd_task = TracerTask(
        title="Publish bounded-context map",
        verify_cmd="bash scripts/preflight.sh docs",
    );

    # Connect context -> task via the meaningful Delivers typed edge.
    runtime_ctx +>:Delivers(since="S1"):+> runtime_task;
    quality_ctx +>:Delivers(since="S2"):+> quality_task;
    ddd_ctx +>:Delivers(since="S3"):+> ddd_task;

    # Dependency ordering between tracer bullets (typed DependsOn edges).
    quality_task +>:DependsOn:+> runtime_task;
    ddd_task +>:DependsOn:+> runtime_task;

    # Agents handed the bounded contexts (typed HandedTo edge).
    runtime_ctx +>:HandedTo:+> Agent(role="build-sentinel", badge="BS-01");
    quality_ctx +>:HandedTo:+> Agent(role="release-captain", badge="RC-02");
    ddd_ctx +>:HandedTo:+> Agent(role="domain-curator", badge="DC-03");

    # Build the demo graph under root.
    root ++> runtime_ctx ++> quality_ctx ++> ddd_ctx;

    # --- Demo 1: collect every tracer task in the spec.
    print("=== Tracer-bullet enumeration ===");
    coord = TracerCoordinator();
    root spawn coord;
    print(f"tracer bullets collected: {len(coord.ordered)}");
    for (i, t) in enumerate(coord.ordered) {
        print(f"  {i + 1}. {t.title}  [{t.verify_cmd}]");
    }

    # --- Demo 2: discover prerequisites of the last collected task
    # by spawning a DependencyProbe rooted at it.
    if len(coord.ordered) > 0 {
        seed = coord.ordered[-1];
        print(f"\n=== Prerequisites of: {seed.title} ===");
        probe = DependencyProbe();
        seed spawn probe;
        for p in probe.prereqs {
            print(f"  - {p.title}");
        }
    }
}
