node TracerBullet {
    has title: str = "";
    has sequence: int = 0;
    has done: bool = False;
}

# A Dependency is a typed edge: this bullet MUST complete before `target`
# can start. Carries `kind` so we can distinguish hard-block vs soft-info.
edge DependsOn {
    has kind: str = "hard";
}

# SpecWalker walks the bullet graph in dependency order, detects cycles
# (because jac 0.36.1 walkers have no built-in visited-set — the issue's
# hand-rolled machinery exists precisely because of this), and reports.
walker SpecWalker {
    has order: list[str] = [];
    has guard: list[str] = [];
