Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.

```jac
"""Skinned BLAS rebuild scheduling with per-entity stagger.

Models the lockstep rebuild spike from issue PERF-D6-2026-08-30-01. Every
animated NPC in a cohort accumulates dirty frames at the same rate; with
a single global threshold they all trip on the same frame and saturate
the BUILD pipeline. A Walker walks the cohort, advancing each entity's
refit counter by one dirty frame, then decides — per entity, with a
jittered threshold — whether to schedule a rebuild. The rebuild frame
records which entities refit so a downstream "rebuild" walker can pick
them up.
"""

node NPC {
    has name: str = "";
    has entity_id: int = 0;
    has refit_count: int = 0;
    has needs_rebuild: bool = False;
}

node Frame {
    has label: str = "";
    has dirty: bool = True;
}

edge MemberOfCohort { has cohort: str = ""; }
edge ScheduledFor { has frame_label: str = ""; }

walker TickDirtyFrames {
    can start with Root entry {
        visit [->:MemberOfCohort:->];
    }

    can tick with NPC entry {
        if here.dirty {
            here.refit_count += 1;
        }
        visit [->:MemberOfCohort:->];
    }
}

walker ScheduleRebuilds {
    has threshold: int = 600;
    has jitter: int = 47;

    can start with Root entry {
        visit [->:MemberOfCohort:->];
    }

    can evaluate with NPC entry {
        per_entity_threshold = self.threshold + (here.entity_id % self.jitter);
        if here.refit_count >= per_entity_threshold {
            here.needs_rebuild = True;
            visit [-->];
        } else {
            visit [-->];
        }
    }
}

walker ApplyRebuilds {
    can start with Root entry {
        visit [->:ScheduledFor:->];
    }

    can rebuild with NPC entry {
        if here.needs_rebuild {
            print(f"  [REBUILD] {here.name} (id={here.entity_id}, refits={here.refit_count})");
            here.needs_rebuild = False;
            here.refit_count = 0;
        }
        visit [-->];
    }
}

with entry {
    npcs = [
        NPC(name="Guard-A", entity_id=101, refit_count=0),
        NPC(name="Guard-B", entity_id=102, refit_count=0),
        NPC(name="Wanderer", entity_id=207, refit_count=0),
        NPC(name="Merchant", entity_id=358, refit_count=0),
    ];

    cohort = Frame(label="InstituteInterior");
    root ++> cohort;
    for n in npcs {
        cohort +>:MemberOfCohort(cohort="InstituteInterior"):+> n;
    }

    frame = Frame(label="rebuild-batch-0");
    root ++> frame;
    for n in npcs {
        frame +>:ScheduledFor(frame_label="rebuild-batch-0"):+> n;
    }

    print("=== Run 1: lockstep (no jitter) — every NPC hits 600 together ===");
    TickDirtyFrames() spawn cohort;
    Scheduler = ScheduleRebuilds(threshold=600, jitter=1);
    Scheduler spawn cohort;
    ApplyRebuilds() spawn frame;

    print("\n=== Run 2: jittered threshold — rebuilds spread out per entity ===");
    for n in npcs {
        n.refit_count = 0;
