Our build system's dependency graph contains diamonds: shared libraries are needed by several modules. Count total build minutes across all tasks, making sure a task reachable by multiple paths is audited exactly once even though traversal reaches it more than once.

```jac
"""Build dependency diamond audit: shared tasks reachable by multiple paths are counted exactly once.

Demonstrates a typed-edge walker that traverses a diamond-shaped build
dependency graph. Because Jac 0.36.1 walkers have no built-in
once-per-node visitation, the cycle/duplicate policy is preserved as
explicit domain logic in an explicit guard set on the walker.
"""

node Task {
    has title: str = "";
    has build_minutes: int = 0;
    has available: bool = True;
}

edge DependsOn {
    has version: str = "1.0";
}

walker BuildAuditor {
    has audited_titles: list[str] = [];
    has total_minutes: int = 0;
    has guard: list[str] = [];

    can start with Root entry {
        print(f"Starting build audit from root");
        visit [->:DependsOn:->];
    }

    can audit with Task entry {
        if here.title in self.guard {
            print(f"  skip (already audited): {here.title}");
            visit [->:DependsOn:->];
        } else {
            self.guard.append(here.title);
            self.audited_titles.append(here.title);
            self.total_minutes = self.total_minutes + here.build_minutes;
            status = "READY" if here.available else "BLOCKED";
            print(f"  [AUDIT][{status}] {here.title} (+{here.build_minutes} min)");
            visit [->:DependsOn:->];
        }
    }
}

with entry {
    # Diamond: core and utils are shared deps of app and tests;
    # app and tests both depend on core AND utils, so they are
    # reachable by two paths each. Guard set ensures once-only.
    core = Task(title="compile-core", build_minutes=10, available=True);
    utils = Task(title="link-utils", build_minutes=5, available=True);
    app = Task(title="build-app", build_minutes=20, available=True);
    tests = Task(title="run-tests", build_minutes=15, available=False);

    root +>:DependsOn(version="1.0"):+> core;
    root +>:DependsOn(version="1.0"):+> utils;

    core +>:DependsOn(version="1.0"):+> app;
    utils +>:DependsOn(version="1.0"):+> app;

    core +>:DependsOn(version="1.0"):+> tests;
    utils +>:DependsOn(version="1.0"):+> tests;

    auditor = BuildAuditor();
    root spawn auditor;

    print(f"Audited {len(auditor.audited_titles)} unique tasks: {auditor.audited_titles}");
    print(f"Total build minutes: {auditor.total_minutes}");
}
