```jac
"""Knowledge-graph vs vector-RAG multi-hop financial QA model.

Models Shah et al. (2024) "Multi-Document Financial Question Answering using
LLMs" (arXiv:2411.07264). The hypothesis: KG-RAG beats vector-RAG as the
number of hops grows. We represent a small cross-subsidiary ownership graph
as typed nodes/edges, then walk it with two traversal strategies:

  * VectorRetriever  — a flat, single-hop lookup walker (simulates vector RAG).
  * KnowledgeGraphWalker — a typed-edge multi-hop walker that traverses
    subsidiary -> parent ownership links and accumulates facts along the way.

A CycleGuard walker demonstrates the confounder from the issue: a conglomerate
whose ownership structure forms a cycle would hang a naive walker; we use an
explicit guard set to make the policy observable.
"""

# ----------------------------------------------------------------------
# Entity archetypes
# ----------------------------------------------------------------------

node Company {
    has ticker: str = "";
    has name: str = "";
    has sector: str = "";
}

node Filing {
    has company: str = "";
    has fiscal_year: int = 0;
    has revenue: float = 0.0;
    has net_income: float = 0.0;
}

# ----------------------------------------------------------------------
# Typed edges — the relationships that vector-RAG cannot natively traverse
# ----------------------------------------------------------------------

edge OwnsShare {
    has pct: float = 0.0;
    has as_of: str = "";
}

edge Filed {
    has period: str = "";
}

# ----------------------------------------------------------------------
# Walker A: vector-style retriever — one hop, no typed traversal
# ----------------------------------------------------------------------

walker VectorRetriever {
    has query_ticker: str = "";
    has facts: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can collect with Company entry {
        if here.ticker == self.query_ticker {
            facts_line = f"company: {here.name} ({here.sector})";
            self.facts.append(facts_line);
            visit [-->];
        } else {
            # vector RAG: no typed-edge awareness, still scans neighbors
            visit [-->];
        }
    }

    can collect with Filing entry {
        # vector RAG stops here — cannot follow entity relationships
        line = f"filing: {here.company} FY{here.fiscal_year} rev={here.revenue}";
        self.facts.append(line);
        visit [-->];
    }

    can report with Root entry {
        print("=== VectorRetriever (single-hop) ===");
        for f in self.facts {
            print(f"  - {f}");
        }
    }
}

# ----------------------------------------------------------------------
# Walker B: knowledge-graph retriever — typed multi-hop traversal
# --------------------------------------------------------------------==

walker KnowledgeGraphWalker {
    has origin_ticker: str = "";
    has max_hops: int = 3;
    has facts: list[str] = [];
    has visited_tickers: set[str] = set();

    can start with Root entry {
        visit [-->];
    }

    can fan_out with Company entry {
        if here.ticker in self.visited_tickers {
            visit [-->] else { disengage; }
        }
        self.visited_tickers.add(here.ticker);
        origin_match = here.ticker == self.origin_ticker;
        hop_note = f"[hop 0] origin" if origin_match else f"[hop {self.max_hops}] reached";
        line = f"{hop_note}: {here.name} ({here.ticker})";
        self.facts.append(line);

        # Walk own filings one direction
        visit [here ->:Filed:->];

        # Walk ownership graph the other direction — typed edge traversal
        if self.max_hops > 0 {
            visit [here ->:OwnsShare:->];
        } else {
            visit [-->] else { disengage; }
        }
    }

    can collect_filing with Filing entry {
        line = f"  filing FY{here.fiscal_year}: rev={here.revenue}, ni={here.net_income}";
        self.facts.append(line);
        # filings are leaves
        visit [-->] else { disengage; }
    }

    can collect_owner with Company entry {
        # We've already entered this company via fan_out; nothing more.
        visit [-->] else { disengage; }
    }

    can report with Root entry {
        print(f"=== KnowledgeGraphWalker (multi-hop, max={self.max_hops}) ===");
        for f in self.facts {
            print(f"  - {f}");
        }
    }
}

# ----------------------------------------------------------------------
# Walker C: cycle guard — demonstrates the confounder from the issue
# ----------------------------------------------------------------------

walker CycleGuard {
    has guard: set[str] = set();

    can start with Root entry {
        visit [-->];
    }

    can probe with Company entry {
        marker = here.ticker;
        if marker in self.guard {
            print(f"  [cycle detected] guard stopped recursion at {marker}");
            visit [-->] else { disengage; }
        }
        self.guard.add(marker);
        print(f"  visiting {marker} ({here.name})");
        visit [-->];
    }
}

# ----------------------------------------------------------------------
# Demo wiring
# ----------------------------------------------------------------------

with entry {
    # Build a small cross-subsidiary ownership graph
    alpha = Company(ticker="ALP", name="Alpha Holdings", sector="Energy");
    beta = Company(ticker="BET", name="Beta Energy Ltd", sector="Energy");
    gamma = Company(ticker="GAM", name="Gamma Refining", sector="Energy");
    delta = Company(ticker="DEL", name="Delta Logistics", sector="Transport");
    mega = Company(ticker="MGA", name="MegaCorp Conglomerate", sector="Conglomerate");

    # Attach filings as leaves
    beta +>:Filed(period="FY2024"):+> Filing(company="BET", fiscal_year=2024, revenue=1200.0, net_income=180.0);
    gamma +>:Filed(period="FY2024"):+> Filing(company="GAM", fiscal_year=2024, revenue=850.0, net_income=95.0);
    delta +>:Filed(period="FY2024"):+> Filing(company="DEL", fiscal_year=2024, revenue=620.0, net_income=72.0);

    # Cross-subsidiary ownership chain
    alpha +>:OwnsShare(pct=100.0, as_of="2024-12-31"):+> beta;
    beta +>:OwnsShare(pct=55.0, as_of="2024-12-31"):+> gamma;
    alpha +>:OwnsShare(pct=40.0, as_of="2024-12-31"):+> delta;
    mega +>:OwnsShare(pct=30.0, as_of="2024-12-31"):+> alpha;

    # A cycle to stress-test the guard (mega -> alpha -> beta -> gamma, no loop here,
    # but we artificially close it: gamma -> mega)
    gamma +>:OwnsShare(pct=5.0, as_of="2024-12-31"):+> mega;

    # Attach the whole subgraph under root
    root ++> alpha ++> beta ++> gamma;
    root ++> delta;
    root ++> mega;

    # --- Demonstration 1: vector retriever (single-hop) ---
    vr = VectorRetriever(query_ticker="BET");
    root spawn vr;

    print("");

    # --- Demonstration 2: KG walker (multi-hop) ---
    kg = KnowledgeGraphWalker(origin_ticker="BET", max_hops=2);
    root spawn kg;

    print("");

    # --- Demonstration 3: cycle guard through the conglomerate ---
    print("=== CycleGuard traversal of ownership graph ===");
    cg = CycleGuard();
    root spawn cg;
}
```

