"""Dead-code detector: find orphaned components after a package removal.

Models the LabelValue.vue scenario from issue #97. A Harvester package
held a small leaf component and several consumers. When the Harvester
package was removed wholesale, the leaf component was left behind with
zero remaining consumers. A walker walks every reachable component via
typed Owner edges, collects any whose consumer list is empty, and
reports them as orphaned dead code.
"""

node Component {
    has name: str = "";
    has path: str = "";
    has available: bool = True;
}

edge Owner {
    has since: str = "";
}

walker OrphanHunter {
    has visited: set[str] = set();
    has orphans: list[str] = [];

    can start with Root entry {
        print("Scanning component graph for orphaned leaf components...");
        visit [->:Owner:->];
    }

    can scan with Component entry {
        if here.name in self.visited {
            return;
        }
        self.visited.add(here.name);

        consumers = [here];
        for c in [-->] {
            if c != here {
                consumers.append(c);
            }
        }
        # A leaf component has no outgoing consumer edges.
        outgoing = [here->:Owner:->];
        if len(outgoing) == 0 {
            self.orphans.append(here.name);
            print(f"  ORPHAN: {here.name} ({here.path}) — no consumers");
        } else {
            print(f"  live :   {here.name} ({here.path}) — {len(outgoing)} consumer(s)");
        }
        visit [->:Owner:->];
    }

    can summarize with Root entry {
        print(f"\nDead-code report: {len(self.orphans)} orphaned component(s)");
        for name in self.orphans {
            print(f"  - {name}");
        }
    }
}

with entry {
    # The Harvester package was removed; LabelValue.vue was a leaf
    # component living only inside it. After removal it has no
    # consumer edges and should be flagged.
    harvester_pkg = Component(name="harvester-pkg", path="pkg/harvester/");
    label_value   = Component(name="LabelValue.vue", path="shell/components/LabelValue.vue");
    dashboard_btn = Component(name="DashboardButton.vue", path="shell/components/");
    nav_bar       = Component(name="NavBar.vue", path="shell/components/");

    # Before removal, LabelValue.vue was consumed inside the Harvester pkg.
    # The Harvester pkg itself was consumed by DashboardButton.
    # After removal of Harvester pkg, both LabelValue and NavBar are orphans.
    harvester_pkg +>:Owner(since="v1.0"):+> label_value;
    dashboard_btn +>:Owner(since="v1.2"):+> harvester_pkg;
    dashboard_btn +>:Owner(since="v1.4"):+> nav_bar;

    root ++> dashboard_btn;

    hunter = OrphanHunter();
    root spawn hunter;
    root spawn hunter;
}
