"""Sidebar collections tree: walk ordered folders and invalidate ancestors on moves."""

node Library {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Collection {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has depth: int = 0;
    has invalidated: bool = False;
}

edge Contains {
    has position: int = 0;
}

walker SidebarIndexer {
    has scanned: int = 0;
    has depth_bound_hits: int = 0;
    has max_depth: int = 6;

    can start with Library entry {
        visit [->:Contains:->] else {
