        } else {
            visit [->:Contains:->] else {
                disengage;
            }
        }
    }
}

walker MoveInvalidator {
    has touched: int = 0;

    can invalidate with Collection entry {
        here.invalidated = True;
        self.touched = self.touched + 1;
        print(f"album:move invalidated {here.title}");
        visit [<--:Contains:--] else {
            disengage;
        }
    }
}

