    indexer = SidebarIndexer(max_depth=6);
    root spawn indexer;
    print(f"album:list scanned {indexer.scanned} collections");

    mover = MoveInvalidator();
    duomo spawn mover;
    print(f"album:move touched {mover.touched} ancestors");
}
