Task:
Each delivery route from our depots carries a cargo weight in tonnes. A truck may only be dispatched when its load is at least 2 tonnes and at most 8 tonnes on the same leg. Check every depot and print which routes qualify for dispatch.

```jac
"""Delivery route dispatcher.

Each route carries a cargo weight in tonnes. A truck may only be dispatched
when its load is at least 2 tonnes and at most 8 tonnes on the same leg.
A walker inspects every depot and prints which routes qualify for dispatch.
"""

node Route {
    has name: str = "";
    has weight: float = 0.0;
}

node Depot {
    has location: str = "";

    def qualifies(r: Route) -> bool {
        return r.weight >= 2.0 and r.weight <= 8.0;
    }
}

walker Dispatcher {
    has dispatched_count: int = 0;

    can start with Root entry {
        print("Starting dispatch inspection across all depots");
        visit [-->];
    }

    can inspect_depot with Depot entry {
        print(f"Depot at {here.location}:");
        visit [-->];
    }

    can inspect_route with Route entry {
        if here.depot_ref().qualifies(here) {
            status = "DISPATCH";
            self.dispatched_count += 1;
        } else {
            status = "HOLD";
        }
        print(f"  [{status}] {here.name} ({here.weight}t)");
        if [-->] {
            visit [-->];
        } else {
            disengage;
        }
    }
}

# Provide a way for the route to ask its parent depot whether it qualifies.
# In idiomatic Jac we'd normally traverse the edge back; here we add a small
# accessor so the dispatcher's union ability stays focused on printing.
edge Serves {}

# Note: in this OSP we attach routes to depots via plain --> edges and
# the dispatcher walks them. We add a tiny helper on Route that walks
# backward to its depot to keep the union ability on a single field.
node Route {
    def depot_ref() -> Depot | None {
        parent = [here <-->];
        if parent {
            return parent[0];
        }
        return None;
    }
}

with entry {
    north = Depot(location="North");
    south = Depot(location="South");
    east = Depot(location="East");

    north ++> Route(name="N-A", weight=1.5)
        ++> Route(name="N-B", weight=3.0)
        ++> Route(name="N-C", weight=7.5)
        ++> Route(name="N-D", weight=9.0);

    south ++> Route(name="S-A", weight=2.0)
        ++> Route(name="S-B", weight=5.5)
        ++> Route(name="S-C", weight=8.0);

    east ++> Route(name="E-A", weight=0.5)
        ++> Route(name="E-B", weight=4.0)
        ++> Route(name="E-C", weight=10.0);

    root ++> north ++> south ++> east;

    d = Dispatcher();
    root spawn d;

    print(f"Total routes dispatched: {d.dispatched_count}");
}
