Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.

```jac
"""Person-following blueprint: model agents, people, and transport brokers as a graph.

Demonstrates the traversal pain from issue #3493: a "Follow person" agentic
blueprint depends on a transport broker, a vision model, and a tracker.
Hand-rolled machinery for ordering dependencies and detecting missing
configuration is replaced by typed edges + walker traversal.
"""

node Blueprint {
    has name: str = "";
    has description: str = "";
}

node Transport {
    has kind: str = "";
    has configured: bool = False;
}

node VisionModel {
    has name: str = "";
    has healthy: bool = True;
}

node Tracker {
    has name: str = "";
    has accelerator: str = "";
}

edge DependsOn {
    has required: bool = True;
}

edge Publishes {
    has channel: str = "";
}

walker BlueprintAuditor {
    has missing: list[str] = [];
    has order: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can audit with Blueprint entry {
        print(f"Auditing blueprint: {here.name} -- {here.description}");
        self.order.append(here.name);
        visit [->:DependsOn:->];
    }

    can check_transport with Transport entry {
        if not here.configured {
            self.missing.append(f"transport:{here.kind}");
        }
        self.order.append(f"transport:{here.kind}");
    }

    can check_model with VisionModel entry {
        if not here.healthy {
            self.missing.append(f"model:{here.name}");
        }
        self.order.append(f"model:{here.name}");
    }

    can check_tracker with Tracker entry {
        if here.accelerator == "" {
            self.missing.append(f"tracker:{here.name}:no-accelerator");
        }
        self.order.append(f"tracker:{here.name}");
    }
}

walker DependencyOrderer {
    has ordered: list[str] = [];
    has visiting: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can order with Blueprint entry {
        self.visiting.append(here.name);
        visit [->:DependsOn:->];
        self.ordered.append(here.name);
    }

    can pass with Transport | VisionModel | Tracker entry {
        marker = type(here).__name__ + ":" + (
            here.kind if hasattr(here, "kind") else
            here.name if hasattr(here, "name") else "?"
        );
        if marker not in self.visiting {
            self.visiting.append(marker);
        }
    }
}

with entry {
    follow_person = Blueprint(
        name="unitree-go2-follow-person",
        description="Follow person agentic blueprint"
    );

    broker = Transport(kind="broker", configured=True);
    mqtt = Transport(kind="mqtt", configured=False);
    model = VisionModel(name="qwen-vl-max", healthy=True);
    tracker = Tracker(name="edgetam-dimos", accelerator="cuda");

    root ++> follow_person;
    follow_person +>:DependsOn:+> broker;
    follow_person +>:DependsOn:+> mqtt;
    follow_person +>:DependsOn:+> model;
    follow_person +>:DependsOn:+> tracker;
    tracker +>:Publishes(channel="person-pose"):+> broker;

    auditor = BlueprintAuditor();
    root spawn auditor;
    print("Audit order: " + ", ".join(auditor.order));
    if auditor.missing {
        print("MISSING: " + ", ".join(auditor.missing));
    } else {
        print("All dependencies resolved.");
    }

    orderer = DependencyOrderer();
    root spawn orderer;
    print("Dependency order: " + ", ".join(orderer.ordered));
}
```

