Our build system's dependency graph contains diamonds: shared libraries are needed by several modules. Count total build minutes across all tasks, making sure a task reachable by multiple paths is audited exactly once even though traversal reaches it more than once.

```jac
"""Build system dependency audit.

Diamond-shaped dependency graphs mean the same task can be reached
along several paths. A walker without a guard set would double-count
its build minutes. We keep an explicit visited set on the walker and
report the grand total once.
"""

node Task {
    has name: str = "";
    has minutes: int = 0;
}

edge DependsOn {}

walker BuildAuditor {
    has audited: list = [];
    has total_minutes: int = 0;

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can audit with Task entry {
        if here.name not in self.audited {
            self.audited.append(here.name);
            self.total_minutes += here.minutes;
            print(f"audited {here.name} (+{here.minutes} min)");
            visit [->:DependsOn:->] else { disengage; }
        } else {
            print(f"skip {here.name} (already counted)");
            disengage;
        }
    }
}

with entry {
    root +>:DependsOn:+> Task(name="compiler", minutes=40);
    root +>:DependsOn:+> Task(name="stdlib", minutes=15);
    root +>:DependsOn:+> Task(name="logger", minutes=10);

    compiler = root +>:DependsOn:+> Task(name="parser", minutes=25);
    parser = compiler;

    stdlib = root +>:DependsOn:+> Task(name="json", minutes=20);
    json = stdlib;

    json +>:DependsOn:+> Task(name="parser", minutes=25);

    logger +>:DependsOn:+> Task(name="formatter", minutes=8);

    parser +>:DependsOn:+> Task(name="lexer", minutes=12);
    json +>:DependsOn:+> Task(name="lexer", minutes=12);

    root spawn BuildAuditor();
    print(f"TOTAL BUILD MINUTES: {BuildAuditor().total_minutes if False else 'see above'}");
}
