```jac
"""Game account moderation sweep.

Three archetypes in play:
  * ``Account``  - the base node carrying a reputation score and a flag for
                    whether the account holds moderator privileges.
  * ``Member``   - a regular player account.
  * ``Admin``    - a staff account whose reputation is boosted on audit.

Three walkers:
  * ``OrderAuditor`` walks the account chain from the lobby, auditing every
                    account it lands on. Member accounts are reported at
                    face value, Admin accounts have their reputation bumped
                    by +5 before the report.
  * ``Greeter``     is a welcome-desk bot. It visits every account node and
                    prints a greeting regardless of account subtype.

Typed edges are used so the audit chain is explicit (``OwnedBy``) and the
welcome desk can use a union trigger to greet Members and Admins with one
ability.
"""

node Account {
    has owner: str = "";
    has reputation: int = 0;
    has is_admin: bool = False;
}

node Member(Account) {
    override has owner: str = "";
    override has reputation: int = 0;
    override has is_admin: bool = False;
}

node Admin(Account) {
    override has owner: str = "";
    override has reputation: int = 0;
    override has is_admin: bool = False;
}

edge OwnedBy {
    has since: str = "";
}

walker OrderAuditor {
    can start with Root entry {
        print("OrderAuditor: beginning moderation sweep");
        visit [->:OwnedBy:->];
    }

    can sweep with Member | Admin entry {
        # Admin accounts get a +5 reputation boost before the audit report.
        final_rep = here.reputation;
        label = "Member";
        if here.is_admin {
            final_rep = here.reputation + 5;
            label = "Admin";
        }
        print(f"[AUDIT] {label} {here.owner} -> reputation {final_rep}");
        visit [->:OwnedBy:->];
    }
}

walker Greeter {
    has desk_name: str = "Welcome Desk";

    can start with Root entry {
        print(f"{self.desk_name}: greeting all visitors");
        visit [->:OwnedBy:->];
    }

    # One union trigger greets every account subtype as the bot passes through.
    can greet with Member | Admin entry {
        print(f"{self.desk_name}: hello, {here.owner}!");
        visit [->:OwnedBy:->];
    }
}

with entry {
    lobby = root;

    alice = Member(owner="Alice", reputation=42);
    bob = Admin(owner="Bob", reputation=80);
    carol = Member(owner="Carol", reputation=15);
    dave = Admin(owner="Dave", reputation=60);

    lobby +>:OwnedBy(since="2024-01-01"):+> alice;
