Task:
Our build system's dependency graph contains diamonds: shared libraries are needed by several modules. Count total build minutes across all tasks, making sure a task reachable by multiple paths is audited exactly once even though traversal reaches it more than once.

```jac
"""Build dependency audit: count total build minutes across a diamond DAG.

Tasks are nodes; each task has its own build minutes. A walker traverses
the dependency graph and audits every reachable task exactly once. An
explicit guard set on the walker tracks visited nodes so the diamond's
shared library is counted only once even though multiple paths reach it.
"""

node Task {
    has title: str = "";
    has build_minutes: int = 0;
}

edge DependsOn {
    has reason: str = "";
}

walker BuildAuditor {
    has visited: list = [];
    has total_minutes: int = 0;

    can start with Root entry {
        print(f"Auditing build graph from {self}");
        visit [->:DependsOn:->];
    }

    can audit with Task entry {
        if here not in self.visited {
            self.visited.append(here);
            self.total_minutes += here.build_minutes;
            print(f"  + {here.title} ({here.build_minutes} min) -> total {self.total_minutes}");
        } else {
            print(f"  . {here.title} already audited, skipping");
        }
        visit [->:DependsOn:->];
    }

    can finish with Task entry {
        visit [->:DependsOn:->] else { disengage; }
    }
}

with entry {
    # Diamond: app -> {auth, db}; both depend on the shared crypto lib.
    # crypto is reachable via two paths but should be audited once.
    app = Task(title="app", build_minutes=10);
    auth = Task(title="auth-module", build_minutes=5);
    db = Task(title="db-module", build_minutes=8);
    crypto = Task(title="shared-crypto", build_minutes=3);
    logging = Task(title="shared-logging", build_minutes=2);

    root +>:DependsOn(reason="build"):+> app;
    app +>:DependsOn(reason="link"):+> auth;
    app +>:DependsOn(reason="link"):+> db;
    auth +>:DependsOn(reason="uses"):+> crypto;
    db +>:DependsOn(reason="uses"):+> crypto;
    crypto +>:DependsOn(reason="emits"):+> logging;

    auditor = BuildAuditor();
    root spawn auditor;
    print(f"GRAND TOTAL build minutes: {auditor.total_minutes}");
}
```

