Models the scenario from issue #1349 where a rewind loop must be resilient
to a mid-loop crash: each file must be journaled (its original state captured)
BEFORE the restored content overwrites it, so a retry can replay safely.

The graph topology:

    RewindJob --(targets)--> File --(previous)--> OriginalSnapshot
                                      --(pending)--> PendingRestore

A File carries two typed edges: one to its OriginalSnapshot (the journaled
pre-rewrite bytes) and one to a PendingRestore (the content to apply on
retry). The RewindWalker walks File nodes via `targets` edges, journals the
file before overwriting, and simulates a mid-loop crash via an injected
failure on a chosen index. A second spawn on the same surviving graph
completes the job idempotently.
"""

node File {
    has title: str = "";
    has content: str = "";
    has available: bool = True;
}

node OriginalSnapshot {
    has title: str = "";
    has bytes: str = "";
    has captured: bool = False;
}

node PendingRestore {
    has title: str = "";
    has bytes: str = "";
    has applied: bool = False;
}

node RewindJob {
    has label: str = "";
    has completed: bool = False;
}

edge Targets { }
edge Previous { }
edge Pending { }
edge NextFile { }

walker RewindWalker {
    has crash_after: int = -1;
    has visited_count: int = 0;

    can start with Root entry {
        print(f"Rewind starting under job '{self.label}'"
              + (f" (crash injected after index {self.crash_after})"
                 if self.crash_after >= 0 else ""));
        visit [->:Targets:->];
    }

    can visit_job with RewindJob entry {
        print(f"  job '{here.label}': entering rewind loop");
        visit [->:Targets:->];
    }

    can visit_file with File entry {
        idx = self.visited_count;
        original_node = [-->];
        snapshot = original_node[0] if len(original_node) > 0 else None;
        pending_targets = [->:Pending:->];
        pending = pending_targets[0] if len(pending_targets) > 0 else None;

        # Step 1: journal the original bytes BEFORE overwriting.
        if snapshot is not None and not snapshot.captured {
            snapshot.captured = True;
            print(f"    [{idx}] journaled snapshot for '{here.title}'");
        }

        # Step 2: simulate a mid-loop crash at the requested index.
        if self.crash_after == idx {
            print(f"    [{idx}] CRASH simulated after journal, before apply");
            disengage;
        }

        # Step 3: apply the pending restore (only on a non-crashing run).
        if pending is not None and not pending.applied {
            pending.applied = True;
            here.content = pending.bytes;
            print(f"    [{idx}] applied restore to '{here.title}'");
        }

        self.visited_count = self.visited_count + 1;
        visit [->:NextFile:->];
    }
}

walker MarkCompleted {
    can start with Root entry {
        visit [->:Targets:->];
    }

    can visit_job with RewindJob entry {
        here.completed = True;
        print(f"job '{here.label}' marked completed");
        visit [->:Targets:->];
    }
}

with entry {
    # Build the chain of files that the rewind loop must walk.
    job = RewindJob(label="workspace-rewind-#42");

    f1 = File(title="alpha.cfg", content="original-alpha");
    f2 = File(title="beta.cfg", content="original-beta");
    f3 = File(title="gamma.cfg", content="original-gamma");

    snap1 = OriginalSnapshot(title="alpha.cfg", bytes="original-alpha");
    snap2 = OriginalSnapshot(title="beta.cfg", bytes="original-beta");
    snap3 = OriginalSnapshot(title="gamma.cfg", bytes="original-gamma");

    pen1 = PendingRestore(title="alpha.cfg", bytes="restored-alpha");
    pen2 = PendingRestore(title="beta.cfg", bytes="restored-beta");
    pen3 = PendingRestore(title="gamma.cfg", bytes="restored-gamma");

    root +>:Targets:+> job;
    job +>:Targets:+> f1;
    job +>:Targets:+> f2;
    job +>:Targets:+> f3;

    f1 +>:Previous:+> snap1;
    f2 +>:Previous:+> snap2;
    f3 +>:Previous:+> snap3;

    f1 +>:Pending:+> pen1;
    f2 +>:Pending:+> pen2;
    f3 +>:Pending:+> pen3;

    f1 +>:NextFile:+> f2;
    f2 +>:NextFile:+> f3;

    # First attempt: crash mid-loop after journal of index 1 (beta.cfg).
    print("=== attempt 1: crash after index 1 ===");
    walker1 = RewindWalker(label="attempt-1", crash_after=1);
    root spawn walker1;
    print(f"attempt-1 reached {walker1.visited_count} files before crash");

    # Second attempt: same graph, no crash injected -> idempotent retry.
    print("=== attempt 2: idempotent retry ===");
    walker2 = RewindWalker(label="attempt-2", crash_after=-1);
    root spawn walker2;
    print(f"attempt-2 reached {walker2.visited_count} files");

    # Finalize.
    root spawn MarkCompleted();

    print(f"job completed = {job.completed}");
    print(f"file alpha content = '{f1.content}'");
    print(f"file beta content  = '{f2.content}'");
    print(f"file gamma content = '{f3.content}'");
}
