variable along its dependency edge and folds the substitution into the live
map. Without cycle protection the walker re-visits ``PATH`` forever,
producing the runaway expansion reported in JENKINS-33239.
"""

node EnvVar {
    has name: str = "";
    has value: str = "";
    has visits: int = 0;
}

# The relationship that says "this variable's value is built on top of that
# variable's current value" -- exactly what enables runaway recursion.
edge DependsOn {
    has var_name: str = "";
}

walker Resolver {
    has env: dict[str, str] = {};
    has max_steps: int = 8;
    has steps: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can resolve with EnvVar entry {
        if self.steps >= self.max_steps {
            print(f"[STOP] cycle guard tripped after {self.steps} steps "
                  f"while resolving ${here.name}");
            disengage;
        }
        self.steps += 1;
        here.visits += 1;

        # Walk the dependency edge: if this var points back at itself (or
        # another var) we record the dependence and continue.
        for dep in [->:DependsOn:->] {
            target_name = dep.var_name;
            current = self.env.get(target_name, "");
            # Substitute $TARGET with the current live value (this is the
            # buggy fold: every step re-resolves $PATH into $PATH again).
            new_value = here.value.replace("${" + target_name + "}", current);
            here.value = new_value;
            self.env[here.name] = new_value;
            print(f"step {self.steps}: {here.name}={here.value} "
                  f"(visit #{here.visits} via ${target_name})");
            if target_name == here.name {
                # Self-reference: keep going to exhibit the runaway.
                visit [here];
            }
        }
    }
}

with entry {
    # Build a small environment graph mirroring the bug report:
    # PATH = path1:$PATH   (self-referential -> runaway)
    # LD_LIBRARY_PATH = $ORACLE_HOME/lib:$LD_LIBRARY_PATH
    path_var = EnvVar(name="PATH", value="path1:${PATH}");
    oracle_home = EnvVar(name="ORACLE_HOME", value="/opt/oracle");
    ld_path = EnvVar(name="LD_LIBRARY_PATH",
                     value="${ORACLE_HOME}/lib:${LD_LIBRARY_PATH}");

    root ++> path_var;
    root ++> oracle_home;
    root ++> ld_path;

    # Typed edges declare the self-dependencies that drive the recursion.
    path_var +>:DependsOn(var_name="PATH"):+> path_var;
    ld_path +>:DependsOn(var_name="LD_LIBRARY_PATH"):+> ld_path;
    ld_path +>:DependsOn(var_name="ORACLE_HOME"):+> oracle_home;

    print("=== PATH resolution (self-reference runaway) ===");
    root spawn Resolver(env={"PATH": "", "ORACLE_HOME": "/opt/oracle",
                             "LD_LIBRARY_PATH": ""},
                        max_steps=8);

    print("\n=== LD_LIBRARY_PATH resolution (self-reference + dep) ===");
    root spawn Resolver(env={"PATH": "", "ORACLE_HOME": "/opt/oracle",
                             "LD_LIBRARY_PATH": ""},
                        max_steps=8);
}
