```jac
"""Warehouse inventory audit: assign stable unique ids, persist each item during the walk, and dump the graph."""

import uuid;

node Item {
    has name: str = "";
    has sku: str = "";
    has qty: int = 0;
    has uid: str = "";
    has persisted: bool = False;
}

edge StoredOn {
    has shelf_id: str = "";
}

node Shelf {
    has label: str = "";
}

edge Aisle {
    has aisle_id: str = "";
}

walker AuditItem {
    has audit_log: list = [];

    can audit with Item entry {
        here.uid = str(uuid.uuid4());
        here.persisted = True;
        self.audit_log.append(here.name);
        print(f"[AUDIT] {here.name} (sku={here.sku}, qty={here.qty}) -> uid={here.uid}");
        visit [-->];
    }
}

walker DumpGraph {
    has depth: int = 0;

    can show with Root entry {
        print("ROOT");
        visit [-->];
    }

    can show with Shelf entry {
        pad = "  " * self.depth;
        print(f"{pad}- Shelf: {here.label}");
        visit [-->];
    }

    can show with Item entry {
        pad = "  " * self.depth;
        print(f"{pad}* Item: {here.name} (uid={here.uid}, persisted={here.persisted})");
    }
}

walker WarehouseAuditor {
    has audit_log: list = [];

    can start with Root entry {
        visit [-->];
    }

    can traverse_aisle with Shelf entry {
        print(f"[AISLE] entering shelf {here.label}");
        visit [-->];
    }

    can record_item with Item entry {
        here.uid = str(uuid.uuid4());
        here.persisted = True;
        self.audit_log.append(here.name);
        print(f"[PERSIST] {here.name} -> storage (uid={here.uid})");
    }
}

with entry {
    a1 = Shelf(label="A1");
    a2 = Shelf(label="A2");
    root ++> a1 ++> a2;

    a1 ++> Item(name="Drill", sku="DRL-001", qty=12)
         ++> Item(name="Hammer", sku="HMR-002", qty=30);

    a2 ++> Item(name="Saw", sku="SAW-003", qty=7)
