         ++> Item(name="Pliers", sku="PLR-005", qty=18);

    auditor = WarehouseAuditor();
    root spawn auditor;
    print(f"Audit complete: persisted {len(auditor.audit_log)} items");

    print("\n--- Graph dump ---");
    root spawn DumpGraph(depth=1);
}
