# --- Entity archetypes -------------------------------------------------------

node Release {
    has version_code: int = 0;
    has label: str = "";
    has shipped: bool = False;
    has rejected_reason: str = "";
}

node BuildArtifact {
    has commit_sha: str = "";
    has built_at: str = "";
    has static_analysis_ok: bool = False;
}

node DeployAttempt {
    has target: str = "";          # "Google Play", "Internal", ...
    has status: str = "";          # "OK" | "DEPLOY_ERROR" | "REJECTED"
    has diagnostic: str = "";
}

# --- Typed edges -------------------------------------------------------------

edge ProducedBy { has built_at: str = ""; }      # Release was produced by a build
edge Attempted { has when: str = ""; }          # Release had a deploy attempt
edge SuccessorOf {}                              # Release -> next Release candidate

# --- Walker that finds the next shippable versionCode -----------------------

walker VersionCodePlanner {
    has min_bump: int = 1;
    has report: dict = {};

    can start with Root entry {
        # Walk into the first release via the SuccessorOf lineage edges.
        visit [->:SuccessorOf:->];
    }

    can plan with Release entry {
        if here.shipped {
            # Shipped releases terminate this branch of the lineage.
            disengage;
        }
        if here.rejected_reason != "" {
            # Same versionCode was rejected: planner must recommend a bump.
            next_code = here.version_code + self.min_bump;
            self.report["current"] = here.version_code;
            self.report["reason"] = here.rejected_reason;
            self.report["next_version_code"] = next_code;
            self.report["note"] = (
                "Google Play rejected this versionCode; bump and re-commit."
            );
            disengage;
        }
        # Otherwise, follow the lineage forward looking for a rejected node.
        visit [->:SuccessorOf:->] else {
            # No rejected version in this lineage: nothing to bump.
            self.report["note"] = "no rejected versionCode in lineage";
            disengage;
        }
    }
}

