```jac
"""Kernel-API packaging benchmark protocol walker.

Models the essential scenario from the issue: a dependency graph of crates
(features and adapter implementations) where a benchmark walker must:
  1. verify disabled feature trees physically omit their dependency edges;
  2. traverse the accepted migration slice and report cohesion / boundaries;
  3. prove no cycles exist between facade and private implementation crates
     (a real correctness check the maintainer cares about).
"""

node Crate {
    has name: str = "";
    has version: str = "0.0.0";
    has publishable: bool = False;
    has enabled: bool = True;
    # Cohesion = number of dependents minus number of dependencies;
    # a facade should be depended on by many, depend on few.
    has cohesion: int = 0;
}

# Typed edge: "uses" carries the feature flag that gates the dependency.
edge Uses {
    has feature_flag: str = "";
    has verified_omitted: bool = False;
}

walker Benchmark {
    has slice_name: str = "Phase-0-baseline";
    has measurements: list = [];
    has visited: list = [];
    has cycles_found: int = 0;
    has stack: list = [];

    can start with Root entry {
        print(f"=== Benchmark slice: {self.slice_name} ===");
        visit [-->];
    }

    can inspect with Crate entry {
        name = here.name;
        if name in self.visited {
            return;
        }
        self.visited = self.visited + [name];
        status = "ENABLED" if here.enabled else "DISABLED";
        pub = "publishable" if here.publishable else "publish=false";
        print(f"  crate {name}@{here.version} [{status}, {pub}] cohesion={here.cohesion}");
        # Walk forward; collect measurements on each dependency edge.
        self.stack = self.stack + [name];
        visit [->:Uses:->];
    }

    can audit_edge with Crate entry {
        # Union trigger: same routine walks incoming + outgoing uses.
        # Outgoing edges (here -> Uses -> dep): check that if the target
        # crate is disabled, the edge must be marked omitted.
        out_edges = [here ->:Uses:->];
        for e in out_edges {
            target_name = e.name;
            flag = e.feature_flag;
            verified = e.verified_omitted;
            if flag == "" {
                continue;
            }
            if not verified {
                # A disabled-capability edge that is NOT omitted = a leak.
                # We record it as a measurement finding.
                self.measurements = self.measurements + [f"LEAK: {flag} edge not omitted"];
            } else {
                self.measurements = self.measurements + [f"ok: {flag} omitted"];
            }
        }
        # Cycle detection: re-entering a crate already on the DFS stack.
        if here.name in self.stack {
            self.cycles_found = self.cycles_found + 1;
            print(f"  CYCLE detected through {here.name}");
            return;
        }
        visit [->:Uses:->];
    }
}

with entry {
    # --- Graph: facade -> {feature-gated modules} -> {private adapters} ---
    facade = Crate(name="kernal-api", version="0.1.0", publishable=True, cohesion=4);

    proc_mod = Crate(name="kernel-process", version="0.1.0", enabled=True, cohesion=2);
    fs_mod = Crate(name="kernel-fs", version="0.1.0", enabled=True, cohesion=1);
    ipc_mod = Crate(name="kernel-ipc", version="0.1.0", enabled=False, cohesion=0);
    broker_mod = Crate(name="kernel-broker", version="0.1.0", enabled=False, cohesion=0);

    running_proc = Crate(name="running-process", version="0.0.1", enabled=True, cohesion=1);
    soldr_mod = Crate(name="soldr-cache", version="0.0.1", enabled=True, cohesion=1);

    # Wire the graph from root. The facade sits at the top; feature-gated
    # modules hang off it; the running-process substrate and soldr cache
    # are private adapters behind their feature flags.
    root ++> facade
        +>:Uses(feature_flag="process", verified_omitted=False):+> proc_mod
        +>:Uses(feature_flag="fs", verified_omitted=False):+> fs_mod
        +>:Uses(feature_flag="ipc", verified_omitted=True):+> ipc_mod
        +>:Uses(feature_flag="broker", verified_omitted=True):+> broker_mod;

    proc_mod +>:Uses(feature_flag="running-process", verified_omitted=False):+> running_proc;
    fs_mod +>:Uses(feature_flag="soldr-cache", verified_omitted=False):+> soldr_mod;

    # Spawn the benchmark walker on the facade to exercise the slice.
    bench = Benchmark(slice_name="Phase-0-facade-only");
    facade spawn bench;

    print(f"\n--- measurements ({len(bench.measurements)}) ---");
