"""Scheduler death-awareness demo.

Models the issue: a harness that awaits a process-tree exit must NOT park
forever when nothing left in the tree can ever produce the awaited exit
(all descendants dead, or the target's exit consumed elsewhere).

We model the scenario with three node archetypes:
  - Process: a spawned pid that may be running or already terminated.
  - Supervisor: a harness waiting on a process tree.
  - DeadTombstone: an exit record a process leaves behind when it dies.

Two typed edges:
  - Spawned: from a Supervisor down to a Process (the tree the supervisor awaits).
  - Exited:  from a Process down to its DeadTombstone (proof the pid is dead).

The ``AuditExit`` walker walks the supervisor's spawned tree, checks each
pid's exit status, and reports a typed failure carrying the dead pids and
their exit reasons when the tree contains nothing that can ever produce an
awaited exit. Cycle policy is explicit (a guard set) because walkers in
jac 0.36.1 do not dedupe nodes on cyclic graphs.

The companion ``AwaitExit`` walker performs the naive blocking wait that
the issue says hangs forever; we give it the same death-awareness so it
returns a verdict instead of parking.
"""

node Process {
    has pid: int = 0;
    has label: str = "";
    has running: bool = True;
    has exit_code: int = -1;
    has tombstone: object = None;
}

node Supervisor {
    has label: str = "";
}

node DeadTombstone {
    has exit_reason: str = "";
    has exit_code: int = -1;
}

edge Spawned { }
edge Exited { }

# Naive awaiter: the buggy "run_until_exit" — in the issue it parks forever
# because it has no death-awareness. We give it the death-aware shape so
# the demo is honest about what the fix requires.
walker AwaitExit {
    has target_pid: int = 0;
    has verdict: str = "UNKNOWN";
    has dead_pids: list[int] = [];
    has reasons: list[str] = [];

    can begin with Root entry {
        visit [-->];
    }

    can await with Supervisor entry {
        guard: set[int] = set();
        result = self._wait(self.target_pid, guard);
        self.verdict = result.verdict;
        self.dead_pids = result.dead_pids;
        self.reasons = result.reasons;
    }

    can _wait with Process entry;

    def _wait(target_pid: int, guard: set[int]) -> dict {
        if here.pid in guard {
            return {"verdict": "CYCLE", "dead_pids": [], "reasons": []};
        }
        guard.add(here.pid);
        if not here.running {
            return {
                "verdict": "DEAD_BEFORE_AWAIT",
                "dead_pids": [here.pid],
                "reasons": [here.tombstone.exit_reason if here.tombstone else "no-tombstone"]
            };
        }
        if here.tombstone {
            return {
                "verdict": "EXIT_ALREADY_CONSUMED",
                "dead_pids": [here.pid],
                "reasons": [here.tombstone.exit_reason]
            };
        }
        return {"verdict": "RUNNING", "dead_pids": [], "reasons": []};
    }
}

# Explicit typed-ability for the awaiter when it lands on a Process node
# (the recursive descent is folded into one step; the helper above models
# what a real death-aware scheduler would do across descendants).
walker AuditExit {
    has target_pid: int = 0;
    has dead_pids: list[int] = [];
    has reasons: list[str] = [];
    has verdict: str = "RUNNABLE";

    can begin with Root entry {
        visit [-->];
    }

    can audit_supervisor with Supervisor entry {
        children = [-->];
        all_dead = len(children) > 0;
        any_can_exit = False;
        for child in children {
            if child.running and child.tombstone is None {
                any_can_exit = True;
            }
            if not child.running or child.tombstone is not None {
                self.dead_pids.append(child.pid);
                tomb = child.tombstone;
                reason_text = tomb.exit_reason if tomb else "killed-no-tombstone";
                self.reasons.append(reason_text);
            } else {
                all_dead = False;
            }
        }
        verdict_label = "NOTHING_CAN_EXIT" if (len(children) > 0 and not any_can_exit) else "OK";
        self.verdict = verdict_label;
        print(f"[AuditExit] supervisor={self.target_pid} "
              f"verdict={self.verdict} dead_pids={self.dead_pids} "
              f"reasons={self.reasons}");
    }
}

