```jac
"""DSC resource dependency resolver: Kahn-style topological sort walker.

Models the PowerShell `Sort-DependsOn` problem from issue #23. Resource
nodes carry a `depends_on` list (resource names they wait on). A typed
`Requires` edge carries the actual dependency relationship; the walker
performs Kahn's algorithm over the typed edges, emitting a topological
order, and reports a cycle by naming the unresolvable resources.
"""

node Resource {
    has name: str = "";
    has depends_on: list[str] = [];

    def dependency_names -> list[str] {
        return self.depends_on;
    }

    def is_in_cycle(candidates: list[str]) -> bool {
        return self.name in candidates;
    }
}

edge Requires { }

walker DependencyResolver {
    has order: list[str] = [];
    has remaining: list[Resource] = [];
    has known_names: list[str] = [];
    has cycle_members: list[str] = [];

    can start with Root entry {
        if self.remaining {
            self.known_names = [r.name for r in self.remaining];
            self.report(self.topological_order());
        } else {
            self.report([]);
        }
    }

    can resolve with Resource entry {
        pending = [n for n in here.depends_on if n not in self.order];
        if not pending {
            self.order.append(here.name);
            self.remaining = [r for r in self.remaining if r.name != here.name];
            print(f"emitted {here.name}; queue drained={not self.remaining}");
        } else {
            print(f"deferring {here.name}: waiting on {pending}");
        }
        visit [->:Requires:->];
    }

    def topological_order -> list[str] {
        snapshot = [r for r in self.remaining];
        round_idx = 0;
        while self.remaining {
            round_idx += 1;
            before = len(self.order);
            self.process_round();
            if len(self.order) == before {
                self.cycle_members = [r.name for r in self.remaining];
                print(f"cycle detected among {self.cycle_members}");
                break;
            }
            print(f"-- round {round_idx} complete, emitted so far: {self.order}");
        }
        self.remaining = snapshot;
        if self.cycle_members {
            cycle_str = ", ".join(self.cycle_members);
            raise Exception(f"Dependency cycle among resources: {cycle_str}");
        }
        return [n for n in self.order];
    }

    def process_round -> None {
        next_remaining: list[Resource] = [];
        for r in self.remaining {
            pending = [n for n in r.depends_on if n not in self.order];
            if pending {
                next_remaining.append(r);
            } else {
                self.order.append(r.name);
            }
        }
        self.remaining = next_remaining;
    }

    def validate_references -> None {
        for r in self.remaining {
            missing = [n for n in r.depends_on if n not in self.known_names];
            if missing {
                missing_str = ", ".join(missing);
                raise Exception(
                    f"Resource {r.name} depends on unknown resource(s): {missing_str}"
                );
            }
        }
    }
}

def build_chain() -> list[Resource] {
    a = Resource(name="A");
    b = Resource(name="B", depends_on=["A"]);
    c = Resource(name="C", depends_on=["B"]);
    d = Resource(name="D", depends_on=["C"]);
    a +>:Requires:+> b;
    b +>:Requires:+> c;
    c +>:Requires:+> d;
    return [a, b, c, d];
}

def build_diamond() -> list[Resource] {
    a = Resource(name="A");
    b = Resource(name="B", depends_on=["A"]);
    c = Resource(name="C", depends_on=["A"]);
    d = Resource(name="D", depends_on=["B", "C"]);
    a +>:Requires:+> b;
    a +>:Requires:+> c;
    b +>:Requires:+> d;
    c +>:Requires:+> d;
    return [a, b, c, d];
}

def build_fan_in() -> list[Resource] {
    leaves = [Resource(name=f"L{i}") for i in range(5)];
    mid = Resource(name="Mid", depends_on=["L0", "L1", "L2", "L3", "L4"]);
    sink = Resource(name="Sink", depends_on=["Mid"]);
    for leaf in leaves {
        leaf +>:Requires:+> mid;
    }
    mid +>:Requires:+> sink;
    return leaves + [mid, sink];
}

def build_cycle() -> list[Resource] {
    a = Resource(name="A", depends_on=["C"]);
    b = Resource(name="B", depends_on=["A"]);
    c = Resource(name="C", depends_on=["B"]);
    a +>:Requires:+> b;
    b +>:Requires:+> c;
    c +>:Requires:+> a;
    return [a, b, c];
}

def build_missing_ref() -> list[Resource] {
    a = Resource(name="A");
    b = Resource(name="B", depends_on=["Ghost"]);
    a +>:Requires:+> b;
    return [a, b];
}

with entry {
    print("=== linear chain ===");
    chain = build_chain();
    w = DependencyResolver(remaining=chain);
    try {
        order = w.topological_order();
        print(f"topo order: {order}");
    } except Exception as exc {
