    }

    print("\n=== diamond ===");
    dia = build_diamond();
    w2 = DependencyResolver(remaining=dia);
    order2 = w2.topological_order();
    print(f"topo order: {order2}");

    print("\n=== wide fan-in ===");
    fan = build_fan_in();
    w3 = DependencyResolver(remaining=fan);
    order3 = w3.topological_order();
    print(f"topo order: {order3}");

    print("\n=== cycle ===");
    cyc = build_cycle();
    w4 = DependencyResolver(remaining=cyc);
    try {
        order4 = w4.topological_order();
        print(f"topo order: {order4}");
    } except Exception as exc {
        print(f"ERROR: {exc}");
    }

    print("\n=== missing reference ===");
    miss = build_missing_ref();
    w5 = DependencyResolver(remaining=miss);
    try {
        w5.validate_references();
        order5 = w5.topological_order();
        print(f"topo order: {order5}");
    } except Exception as exc {
