    }

    print("\n=== walker traversal over typed Requires edges (chain) ===");
    chain_root = Resource(name="ChainRoot");
    chain_root +>:Requires:+> chain[0];
    root spawn DependencyResolver(remaining=[chain_root] + chain);
}
