```jac
"""PR blast-radius analyzer modeled on liveness_primer.

Entities: CorpusRepo, Finding, PullRequest, PRRun (commit-vs-base diff).
The walker traces every finding on a PR back to the repos that produced it,
detects cycles in the finding->repo->finding graph, and reports a blast
radius summary - exactly the traversal the issue complains about being
hand-rolled.
"""

node CorpusRepo {
    has name: str = "";
    has files: int = 0;
}

node Finding {
    has kind: str = "";        # unused-variable, unreachable-code, ...
    has location: str = "";    # path:line
    has appeared: bool = True; # true if new in the PR run
}

node PullRequest {
    has title: str = "";
    has base_sha: str = "";
    has head_sha: str = "";
}

node PRRun {
    has label: str = "";       # "simulated PR 1", "simulated PR 2", ...
    has timestamp: str = "";
}

edge Hosted { }       # CorpusRepo --hosted--> Finding
edge DetectedBy { }   # Finding --detectedBy--> PRRun
edge Targets { }      # PRRun --targets--> PullRequest
edge Compares { }     # PRRun --compares--> PRRun (base <- head)
edge Mentions { }     # Finding --mentions--> Finding (related findings)

walker BlastRadius {
    has max_hops: int = 6;
    has visited: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can enter with PRRun entry {
        print(f"\n=== Blast radius for {here.label} ({here.timestamp}) ===");
        print(f"  base={here.base_sha}  head={here.head_sha}");
        self.visited = [];
        visit [->:DetectedBy:->];
    }

    can trace with Finding entry {
        sig = f"{here.kind}@{here.location}";
        if sig in self.visited {
            print(f"  [cycle] revisiting {sig} - stop");
            return;
        }
        self.visited.append(sig);
        tag = "NEW" if here.appeared else "fixed";
        print(f"  [{tag}] {sig}");
        visit [->:Hosted:->];
    }

    can reach with CorpusRepo entry {
        print(f"    -> reaches repo '{here.name}' ({here.files} files)");
        visit [->:Hosted:->];
    }
}

with entry {
    # Two PR runs forming the classic regression + fix pair
    bad_run = PRRun(
        label="simulated PR 1 (regression)",
        timestamp="2024-01-15",
        base_sha="abc123",
        head_sha="def456",
    );
    fix_run = PRRun(
        label="simulated PR 2 (fix)",
        timestamp="2024-01-20",
