        appeared=True,
    );
    f2 = Finding(
        kind="unused-variable",
        location="jendrikseipp/vulture/core.py:117",
        appeared=True,
    );
    f3 = Finding(
        kind="unreachable-code",
        location="jendrikseipp/vulture/scanner.py:88",
        appeared=True,
    );
    # Pre-existing finding the regression touches
    f4 = Finding(
