    repo_vulture +>:Hosted:+> f1;
    repo_vulture +>:Hosted:+> f2;
    repo_vulture +>:Hosted:+> f4;
    repo_requests +>:Hosted:+> f3;
    repo_flask +>:Hosted:+> f4;

    root ++> bad_run ++> fix_run;
    root ++> pr;

    root spawn BlastRadius();
}
