"""Call-path reachability demo: model symbols and `calls` edges, then walk the
graph with a BFS-style walker that visits only the current frontier instead of
materializing the full adjacency list up-front (the issue's complaint).

The walker's `visited` set is its only state — there is no precomputed
adjacency map. Each step queries outgoing `calls` edges of the current
symbol via typed-edge traversal `visit [->:Calls:->]`.
"""

node Symbol {
    has name: str = "";
    has kind: str = "";
}

edge Calls {
    has line: int = 0;
}

walker CallPath {
    has origin: str = "";
    has target: str = "";
    has max_depth: int = 32;
    has visited: list[str] = [];
    has found: bool = False;
    has path: list[str] = [];

    can start with Root entry {
        self.visited = [];
        self.found = False;
        self.path = [];
        visit [->:Calls:->];
    }

    can step with Symbol entry {
        sym_name = here.name;
        # Cycle policy: explicit guard set, since walkers don't dedupe on cycles.
        if sym_name in self.visited {
            return;
        }
        self.visited.append(sym_name);

        depth = len(self.visited);
        marker = "  " * depth;
        print(f"{marker}[d{depth}] enter {here.name} ({here.kind})");

        if here.name == self.target {
            self.found = True;
            self.path = list(self.visited);
            print(f"{marker}  -> reached target {self.target}");
            disengage;
        }

        if depth >= self.max_depth {
            print(f"{marker}  -> depth cap {self.max_depth} hit");
            disengage;
        }

        # Forward along typed Calls edges only — no full adjacency load.
        visit [->:Calls:->];
    }
}

walker Summary {
    has visited: list[str] = [];
    has target: str = "";
    has origin: str = "";

    can start with Root entry {
        # Replay the walk from origin, accumulating visited names; mirrors
        # how the demo's `with entry` block re-runs the BFS from another root.
        self.visited = [];
        visit [->:Calls:->];
    }

    can step with Symbol entry {
        if here.name in self.visited {
            return;
        }
        self.visited.append(here.name);
        reach = "target" if here.name == self.target else "transit";
        print(f"  summary[{reach}] {here.name}");
        visit [->:Calls:->];
    }
}

with entry {
    # A small call graph:
    #   main -> parse -> tokenize -> lex
    #                     \-> error
    #          \-> validate -> check
    #   unrelated_node (isolated)
    main = Symbol(name="main", kind="function");
    parse = Symbol(name="parse", kind="function");
    tokenize = Symbol(name="tokenize", kind="function");
    lex = Symbol(name="lex", kind="function");
    err = Symbol(name="error_handler", kind="function");
    validate = Symbol(name="validate", kind="function");
    check = Symbol(name="check", kind="function");
    unrelated = Symbol(name="unrelated_node", kind="function");

    # Typed edges: the relationship itself (`calls`) carries the line number.
    main +>:Calls(line=10):+> parse;
    main +>:Calls(line=12):+> validate;
    parse +>:Calls(line=24):+> tokenize;
    parse +>:Calls(line=27):+> err;
    tokenize +>:Calls(line=58):+> lex;

    # A cycle: validate <-> check (intentional, mirrors real call graphs).
    validate +>:Calls(line=71):+> check;
    check +>:Calls(line=92):+> validate;

    root ++> unrelated;

    print("== BFS from main to lex ==");
    cp = CallPath(origin="main", target="lex");
    root spawn cp;
    print(f"found={cp.found} path={cp.path}");

    print("\n== BFS from main to missing_node (dead-end) ==");
    cp2 = CallPath(origin="main", target="missing_node");
    root spawn cp2;
    print(f"found={cp2.found} visited={cp2.visited}");

    print("\n== Cycle probe: main -> check (cycle in graph) ==");
    cp3 = CallPath(origin="main", target="check", max_depth=8);
    root spawn cp3;
    print(f"found={cp3.found} path={cp3.path}");
}
```

