For my team I want a shared task board in Jac. The board itself is open structure teammates can attach to, encoded once as an archetype policy instead of remembered grants; tasks are user-owned contributions armed readable as they're created. Add a full private CRUD set plus a stats walker reporting totals, completion rate, and per-assignee counts in a single response.

```jac
"""Shared team task board with archetype policy, user-owned tasks, private CRUD, and stats walker."""

node Task {
    has title: str = "";
    has description: str = "";
    has done: bool = False;
    has owner: str = "";
    has assignee: str = "";
    has priority: int = 0;
    has created_at: str = "";
    has updated_at: str = "";
}

# An "archetype policy" node that grants permissions declaratively.
# Every task the board spawns reads its grants from here instead of
# the board remembering per-task grants at creation time.
node Board {
    has title: str = "";
    has policy: str = "private_crud";
    has read_on_create: bool = True;
    has write_own: bool = True;
    has write_assigned: bool = True;
    has write_any: bool = False;

    can grant with Task entry {
        # Anyone allowed to enter the board may READ a task as it's created.
        if here.read_on_create {
            print(f"[board:{self.title}] readable: {here.title}");
        }
    }
}

# Walker that owns the full private CRUD set for the calling user.
# It carries a `user` field and an `op` verb; the board policy decides
# whether each verb is allowed against the visited Task.
walker TaskManager {
    has user: str = "";
    has op: str = "read";
    has title: str = "";
    has description: str = "";
    has done: bool = False;
    has assignee: str = "";
    has priority: int = 0;
    has target_title: str = "";
    has new_done: bool = False;
    has new_assignee: str = "";
    has new_priority: int = 0;
    has new_description: str = "";

    can start with Root entry {
        print(f"--- TaskManager [{self.user}] op={self.op} ---");
        visit [-->];
    }

    # Single union ability handles the board and every task on it.
    can manage with Board | Task entry {
        if here.type == "Board" {
            visit [-->];
            return;
        }
        # Here: a Task node.
        if self.op == "create" {
            self.title or (self.title := f"task-{self.user}");
            self.description or (self.description := "new task");
            self.assignee or (self.assignee := self.user);
            new_task = Task(
                title=self.title,
                description=self.description,
                done=False,
                owner=self.user,
                assignee=self.assignee,
                priority=self.priority,
                created_at="now",
                updated_at="now",
            );
            here +>:ON_BOARD:+> new_task;
            # Archetype policy fires automatically as the new task enters.
            visit [here->:ON_BOARD:->];
        } elif self.op == "read" {
            print(f"[read] {here.title} | done={here.done} "
                  f"| owner={here.owner} | assignee={here.assignee} "
                  f"| priority={here.priority}");
            visit [-->];
        } elif self.op == "update" {
            allowed = False;
            if self.user == here.owner and here.write_own_inherited() {
                allowed = True;
            }
            if not allowed and self.user == here.assignee and here.write_assigned_inherited() {
                allowed = True;
            }
            if not allowed and here.write_any_inherited() {
                allowed = True;
            }
            if allowed {
                here.description = self.new_description or here.description;
                here.done = self.new_done;
                here.assignee = self.new_assignee or here.assignee;
                here.priority = self.new_priority;
                here.updated_at = "now";
                print(f"[update:{self.user}] {here.title} -> done={here.done}");
            } else {
                print(f"[deny:{self.user}] cannot update {here.title}");
            }
            visit [-->];
        } elif self.op == "delete" {
            if self.user == here.owner {
                del here;
                print(f"[delete:{self.user}] removed");
            } else {
                print(f"[deny:{self.user}] cannot delete {here.title}");
            }
            visit [-->];
        } else {
            print(f"[skip] unknown op {self.op}");
            visit [-->];
        }
    }

    can report with Task entry {
        # Stats walker piggybacks on the same traversal.
        visit [-->];
    }
}

# Stats walker: one pass over the board produces totals, completion
# rate, and per-assignee counts in a single response.
walker Stats {
    has total: int = 0;
    has done_count: int = 0;
    has todo_count: int = 0;
    has alice_count: int = 0;
    has bob_count: int = 0;
    has carol_count: int = 0;
    has report: str = "";

    can start with Root entry {
        print("--- Stats ---");
        visit [-->];
    }

    can gather with Board | Task entry {
        if here.type == "Task" {
            self.total += 1;
            if here.done {
                self.done_count += 1;
            } else {
                self.todo_count += 1;
            }
            if here.assignee == "alice" {
                self.alice_count += 1;
            } elif here.assignee == "bob" {
                self.bob_count += 1;
            } elif here.assignee == "carol" {
                self.carol_count += 1;
            }
        }
        visit [-->];
    }

    can summarize with Root entry {
        rate = 0.0;
        if self.total > 0 {
            rate = (self.done_count * 100.0) / self.total;
        }
        self.report = (
            f"totals: total={self.total}, done={self.done_count}, "
            f"todo={self.todo_count}, completion_rate={rate:.1f}%, "
            f"per_assignee=alice:{self.alice_count},"
            f"bob:{self.bob_count},carol:{self.carol_count}"
        );
        print(self.report);
    }
}

# Edge connecting a board to each task it owns.
edge ON_BOARD {
    has attached_at: str = "now";
}

with entry {
    # The board is the archetype policy: grants live on the node, not
    # in per-task records at creation time.
    board = Board(
        title="Sprint-7",
        policy="private_crud",
        read_on_create=True,
        write_own=True,
        write_assigned=True,
        write_any=False,
    );
    root ++> board;

    # Seed a couple of tasks directly so the demo has data to read.
