        title="write walkers",
        description="traversal demos",
        done=False,
        owner="bob",
        assignee="bob",
        priority=1,
        created_at="now",
        updated_at="now",
    );
    board +>:ON_BOARD:+> t1;
    board +>:ON_BOARD:+> t2;

    # --- Private CRUD demo: each actor only sees what policy allows. ---
    alice = TaskManager(
        user="alice",
        op="create",
        title="review PR",
        description="triage incoming",
        assignee="alice",
