"""MA2H §13.4 keyless consumer conformance demo.

Models the digest-recompute duty for HTTP consumers of the MA2H protocol.
The Hub-keyed MAC means a keyless consumer CANNOT recompute a verifying
digest; it compensates with structural validation (known/forbidden field
keep-lists, MAC well-formedness) and byte-verbatim forwarding to a
runtime that holds the Hub key. This walker performs that compensating
flow and reports whether the §13.4 MUST is satisfied under the keyless
carve-out.
"""

node Message {
    has payload: str = "";
    has transmitted_digest: str = "";
    has known_fields: list[str] = [];
    has forbidden_fields: list[str] = [];
    has mac: str = "";
}

node KeylessConsumer {
    has consumer_id: str = "";
    has hub_key: str = "";
}

node KeyedRuntime {
    has runtime_id: str = "";
    has hub_key: str = "";
}

node AuditReport {
    has passed: bool = False;
    has notes: list[str] = [];
}

edge Receives { has wire_bytes: str = ""; }
edge Forwards { }
edge Files { }
edge Validates { }

walker Auditor {
    has consumer: KeylessConsumer = None;

    can start with Root entry {
        visit [-->];
    }

    can audit with Message entry {
        # Keyless compensation path: structural + forwarding checks.
        notes: list[str] = [];

        well_formed = is_well_formed_mac(here.mac);
        if not well_formed {
            notes.append("MAC malformed");
        }

        # known-field keep-list: every present field MUST be in the
        # allowed set; forbidden-field list MUST be empty.
        bad_known = [f for f in here.known_fields if f not in {"agent_id", "ts", "nonce"}];
        if len(bad_known) > 0 {
            notes.append("unknown field present");
        }

        # Cannot recompute: just record inability.
        notes.append("no Hub key — cannot recompute digest");

        report = AuditReport(
            passed=well_formed and len(notes) == 1,
            notes=notes,
        );
        here +>:Files:+> report;
        visit [-->];
    }

    can forward_check with KeylessConsumer entry {
        if self.consumer is None {
            self.consumer = here;
        }
        visit [-->];
    }

    can attest with KeyedRuntime entry {
        if self.consumer is not None {
            self.consumer +>:Forwards:+> here;
        }
        visit [-->];
    }

    can review with AuditReport entry {
        verdict = "CONFORMANT" if here.passed else "NONCONFORMANT";
        print(f"[{verdict}] {self.consumer.consumer_id}: {here.notes}");
        visit [-->];
    }
}

def is_well_formed_mac(mac: str) -> bool {
    return len(mac) == 64;
}

