Task:
A maintainer on the project joongsim/fitted (unknown) filed this issue about hand-rolled graph machinery causing pain:

Issue #66: perf: pre-build venv/wheel cache in CI to speed up deploys

## Problem

During deployment, `uv sync` runs on the EC2 instance and resolves/installs dependencies at deploy time. This is slow and can fail due to PyPI unavailability or a dependency changing upstream.

## Proposed solution

Pre-build the virtual environment or a wheel cache in CI (GitHub Actions) and upload it to S3. The deploy script then downloads and unpacks it instead of running a full `uv sync` from scratch.

## Approach

1. In the CI workflow, after tests pass, run `uv sync` and either:
   - Tar the `.venv` directory and upload to S3 (keyed by `uv.lock` hash), or
   - Run `uv export` + `pip wheel` to produce a wheel cache, upload to S3
2. In `scripts/deploy.sh`, check S3 for a cache matching the current `uv.lock` hash — if present, download and unpack; fall back to `uv sync` on cache miss
3. Invalidate old cache entries when the lock file changes

## Benefits

- Faster deploys (download + unpack vs full dependency resolution and build)
- Deploys can't fail due to upstream PyPI issues
- No change to the overall deploy architecture (still EC2 + systemd)

## Notes

- Avoids the complexity of full containerization while solving the core deploy reliability/speed problem
- Cache key should be the `sha256` of `uv.lock` so it auto-invalidates on any dependency change

Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.

```jac
"""CI venv cache deployment pipeline.

Models the deploy flow from issue #66: a CI step builds a dependency
cache (wheel/venv) keyed by the lock-file hash and ships it to an
artifact store; the deploy step on the target host looks the cache
up by hash, downloads it, and falls back to a cold ``uv sync`` on a
cache miss. Old cache entries are invalidated when the lock-file
hash drifts.
"""

node LockArtifact {
    has lock_hash: str = "";
    has produced_at: str = "";
}

node WheelCache {
    has store_key: str = "";
    has size_mb: float = 0.0;
    has valid: bool = True;
}

node DeployHost {
    has hostname: str = "";
    has last_deploy: str = "";
}

edge Produces {
    has built_by: str = "ci-runner";
}

edge ShippedTo {
    has bucket: str = "s3://fitted-cache";
}

edge DeploysFrom;

walker CacheSweep {
    has expired_keys: list[str] = [];
    has reachable: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can sweep with LockArtifact | WheelCache | DeployHost entry;

    can sweep with LockArtifact entry {
        print(f"lock {here.lock_hash} produced at {here.produced_at}");
        visit [->:Produces:->];
    }

    can sweep with WheelCache entry {
        if here.valid {
            self.reachable.append(here.store_key);
        } else {
            self.expired_keys.append(here.store_key);
        }
        visit [->:ShippedTo:->];
    }

    can sweep with DeployHost entry {
        here.last_deploy = here.last_deploy;
        label = "HIT" if len(self.reachable) > 0 else "MISS";
        print(f"host {here.hostname} cache lookup: {label} "
              f"(reachable={len(self.reachable)}, "
              f"expired={len(self.expired_keys)})");
        report self.reachable;
    }
}

walker CacheInvalidator {
    has current_hash: str = "";
    has purged: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can invalidate with LockArtifact entry {
        print(f"new lock hash: {self.current_hash} (was {here.lock_hash})");
        visit [->:Produces:->];
    }

    can invalidate with WheelCache entry {
        if here.store_key != self.current_hash {
            here.valid = False;
            self.purged.append(here.store_key);
        }
        visit [->:ShippedTo:->];
    }

    can invalidate with DeployHost entry {
        here.last_deploy = here.last_deploy;
        print(f"invalidated {len(self.purged)} stale cache entries");
        report self.purged;
    }
}

with entry {
    lock = LockArtifact(lock_hash="abc123", produced_at="2026-01-15T10:00Z");
    stale1 = WheelCache(store_key="abc123", size_mb=420.0, valid=True);
    stale2 = WheelCache(store_key="old999", size_mb=380.0, valid=True);
    host = DeployHost(hostname="ec2-deploy-01", last_deploy="never");
    root ++> lock ++> stale1 ++> stale2 ++> host;
    lock +>:Produces:+> stale1;
    lock +>:Produces:+> stale2;
    stale1 +>:ShippedTo:+> host;
    stale2 +>:ShippedTo:+> host;

    print("--- CacheSweep (cache hit lookup) ---");
    root spawn CacheSweep();

    print("--- CacheInvalidator (lock hash drift) ---");
    root spawn CacheInvalidator(current_hash="def456");
}
