"""Deploy pipeline: pre-built venv/wheel cache invalidation across CI runs.

Models the essential scenario from joongsim/fitted issue #66: a CI pipeline
that produces a deploy cache keyed by the lockfile hash, a deploy job that
either consumes a matching cache or falls back to a slow install, and an
auditor walker that traverses the cache history to invalidate stale entries
when the lockfile changes.
"""

node DeployJob {
    has name: str = "";
    has lockfile_hash: str = "";
    has status: str = "pending";
}

node CacheEntry {
    has key: str = "";
    has lockfile_hash: str = "";
    has size_mb: float = 0.0;
    has built_at: str = "";
    has stale: bool = False;
}

node BuildStep {
    has label: str = "";
    has duration_s: int = 0;
}

edge Produced {
    has timestamp: str = "";
}

edge Invalidates { }

edge Step { }

walker CacheAuditor {
    has current_lock_hash: str = "";

    can start with Root entry {
        print(f"Auditing caches against lockfile hash {self.current_lock_hash}");
        visit [->:Produced:->];
    }

    can review with CacheEntry entry {
        is_match = here.lockfile_hash == self.current_lock_hash;
        verdict = "HIT" if is_match else "MISS";
        action = "reuse" if is_match else "rebuild";
        print(f"  cache[{here.key}] hash={here.lockfile_hash} -> {verdict} ({action})");
        visit [->:Invalidates:->];
    }

    can invalidate with CacheEntry entry {
        if not here.stale {
            here.stale = True;
            print(f"  ! invalidated stale cache {here.key} (lockfile drift)");
        }
        visit [->:Step:->];
    }

    can summarize with BuildStep entry {
        print(f"  step[{here.label}] took {here.duration_s}s");
        visit [-->];
    }
}

walker CacheAudit {
    has current_lock_hash: str = "";
    has hits: int = 0;
    has misses: int = 0;

    can start with Root entry {
        visit [->:Produced:->];
    }

    can tally with CacheEntry entry {
        if here.lockfile_hash == self.current_lock_hash {
            self.hits += 1;
        } else {
            self.misses += 1;
        }
        visit [->:Step:->];
    }

    can finish with BuildStep entry {
