```jac
"""Sacred-geometry cache-key + invalidation walk.

Models the Sacred Geometry engine's cache registry as a graph:
contracts, engines, algorithms, and cached renderings are nodes;
typed edges carry the relationships that drive cache-key
construction (which dimensions a cache key depends on) and
invalidation cascades (which entries must be dropped when an
upstream version changes). A walker walks the dependency graph to
compute a canonical cache key and to enumerate the entries that
must be invalidated when a source version bumps.
"""

# ----- Entities ------------------------------------------------------------

node Contract {
    has contract_id: str = "";
    has version: str = "";
}

node Engine {
    has engine_name: str = "";
    has version: str = "";
}

node Algorithm {
    has algo_name: str = "";
    has version: str = "";
}

node Source {
    has source_id: str = "";
    has version: str = "";
}

node CacheEntry {
    has entry_id: str = "";
    has key: str = "";
    has stale: bool = False;
}

# ----- Relationships (typed edges carry meaning) ----------------------------

# A cache key is composed of these four dimensions.
edge KeysBy {
    has dimension: str = "";
}

# An entry renders output for a given source.
edge RendersSource {}

# An invalidation cascade: when the tail version changes, drop the head.
edge Invalidates {}

# ----- Walker: build canonical cache key + invalidation set ----------------

walker CacheAuditor {
    has report: dict = {};
    has contract_v: str = "";
    has engine_v: str = "";
    has algo_v: str = "";
    has source_v: str = "";
    has invalidations: list = [];

    can audit with Root entry {
        # Start by walking the contract + engine + algorithm + source
        # versions that this cache region is keyed by.
        visit [->:KeysBy:->];
    }

    can read with Contract | Engine | Algorithm | Source entry {
        # Stamp the version into the canonical key, labeled by dimension.
        dimension = "";
        if here isinstance Contract {
            dimension = "contract";
            self.contract_v = here.version;
        } elif here instanceof Engine {
            dimension = "engine";
            self.engine_v = here.version;
        } elif here instanceof Algorithm {
            dimension = "algo";
            self.algo_v = here.version;
        } else {
            dimension = "source";
            self.source_v = here.version;
        }
        self.report[dimension] = here.version;
        visit [->:KeysBy:->];
    }

    can audit with CacheEntry entry {
        # When we reach a cached entry, first decide if it must be
        # invalidated by walking the Invalidates edge back to its source.
        if here.stale {
            self.invalidations.append(here.entry_id);
        }
        visit [->:RendersSource:->];
    }

    can audit with Source entry {
        # If the source we land on has a version mismatch with what
        # we recorded, every entry routed here is stale.
        if here.version != self.source_v {
            # Pull any cache entry that rendered this source.
            pass;
        }
        visit [->:Invalidates:->];
    }
}

# ----- Walker: drop stale entries along the cascade ------------------------

walker Invalidate {
    has dropped: list = [];

    can start with Root entry {
        visit [-->];
    }

    can drop with CacheEntry entry {
        if here.stale {
            self.dropped.append(here.entry_id);
            here.stale = False;
            print(f"invalidated cache entry {here.entry_id} (key={here.key})");
        } else {
            print(f"kept cache entry {here.entry_id} (key={here.key})");
        }
        visit [-->];
    }
}

# ----- Demonstration -------------------------------------------------------

with entry {
    # Build the four keying dimensions for the Sacred Geometry engine.
    c = Contract(contract_id="sacred-geo/v1", version="1.0.0");
    e = Engine(engine_name="sacred-geometry", version="2.3.1");
    a = Algorithm(algo_name="golden-ratio", version="0.9.0");
    s = Source(source_id="form:goddess", version="2024-06-01");

    # Build two cache entries: one fresh, one stale.
    fresh = CacheEntry(entry_id="E-001", key="placeholder", stale=False);
    stale = CacheEntry(entry_id="E-002", key="placeholder", stale=True);

    # Wire the keying graph: every CacheEntry depends on the four
    # dimensions (typed KeysBy edges) so the walker can compose them.
    root +>:KeysBy(dimension="contract"):+> c;
    root +>:KeysBy(dimension="engine"):+> e;
    root +>:KeysBy(dimension="algo"):+> a;
    root +>:KeysBy(dimension="source"):+> s;

    # Each entry renders one source; the stale entry renders the
    # goddess source, which will be version-bumped during the demo.
    fresh +>:RendersSource:+> s;
    stale +>:RendersSource:+> s;

    # Invalidation cascade: when the goddess source version changes,
    # these entries must be dropped.
    s +>:Invalidates:+> fresh;
    s +>:Invalidates:+> stale;

    # 1) Compose the canonical cache key by walking the keying graph.
    auditor = CacheAuditor();
    root spawn auditor;
    canonical_key = (
        f"contract={auditor.contract_v};"
        f"engine={auditor.engine_v};"
        f"algo={auditor.algo_v};"
        f"source={auditor.source_v}"
    );
    print(f"canonical cache key = {canonical_key}");

    # Stamp the composed key onto every entry so the demo can show it.
    fresh.key = canonical_key;
    stale.key = canonical_key;

    # 2) Simulate a source version bump (the trigger for invalidation).
    print("bumping goddess source 2024-06-01 -> 2025-01-15");
    s.version = "2025-01-15";

    # 3) Walk the cache entries and drop anything that renders the
    # bumped source.
    invalidator = Invalidate();
    root spawn invalidator;
    print(f"dropped entries: {invalidator.dropped}");
}
