```jac
"""Performance budget enforcement: model initial dependency graphs per tier,
then have a walker traverse and audit the graph for budget violations and
untyped remote escapes that the historical check missed.
"""

# --- Entity archetypes ---

node Dependency {
    has label: str = "";
    has kind: str = "js";          # js | css | inline_js | inline_css | remote_js
    has bytes: int = 0;            # raw bytes
    has gzip_bytes: int = 0;       # transferred gzipped size
    has query_versioned: bool = False;
    has render_critical: bool = True;
    has interactive: bool = False; # whether primary content/controls are ready
}

node Tier {
    has name: str = "";
    # public, mutable budget knobs preserved as walker state
    has js_budget_kb: int = 75;
    has css_budget_kb: int = 35;
}

# Typed edges: what relationship each dependency has to its tier / page
edge BelongsTo { has weight: float = 1.0; }
edge BlocksRender { has critical: bool = True; }

# --- Walker: BudgetAuditor ---

walker BudgetAuditor {
    has violations: list = [];

    can start with Root entry {
        # only typed BelongsTo edges count as "in-graph" — remote deps must
        # still declare themselves via BelongsTo or they escape accounting
        visit [->:BelongsTo:->];
    }

    can audit_tier with Tier entry {
        print(f"\n=== Auditing tier: {here.name} ===");
        # re-emit typed-edge traversal at the tier level
        visit [->:BelongsTo:->];
    }

    # Union trigger: one routine handles every dependency variant.
    # Each ability only touches fields shared across the union (all on Dependency).
    can inspect with Dependency entry {
        if here.kind == "remote_js" and here.render_critical {
            self.violations.append(f"render-critical remote JS: {here.label}");
        }
        if here.query_versioned and here.gzip_bytes > 20 * 1024 {
            self.violations.append(f"query-versioned oversized: {here.label}");
        }
        if here.interactive and here.gzip_bytes > 40 * 1024 {
            self.violations.append(f"hidden WebGL/init cost: {here.label}");
        }
        if here.kind == "js" and here.gzip_bytes > here.__root_tier().js_budget_kb * 1024 {
            self.violations.append(f"JS over tier budget: {here.label}");
        }
        if here.kind == "css" and here.gzip_bytes > here.__root_tier().css_budget_kb * 1024 {
            self.violations.append(f"CSS over tier budget: {here.label}");
        }
