Task:
A maintainer on the project Paco5687/GlucoPilot (unknown) filed this issue about hand-rolled graph machinery causing pain:

Issue #130: [H6] Reevaluate dedicated graph-database triggers using measured evidence

Parent: #91

**Workstream ID:** H6
**Depends on:** G3, G5, H3

## Scope

- Measure edge volume, traversal depth, recursive query latency, maintenance burden, and product demand
- Review whether multi-hop exploration, ontology integration, cohort use, or graph algorithms became core
- Update ADR with measured evidence
- If needed, propose only a derived read model with rebuild strategy

## Acceptance criteria

- [ ] ADR explicitly remains SQLite or documents proven triggers
- [ ] Operational source of truth remains canonical relational storage
- [ ] No graph database is introduced without backup/sync/failure design
- [ ] Decision cites measurements rather than architectural preference

## Delivery notes

Production changes must be staged, observable, reversible, and preserve the single-container/one-volume deployment model.

Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.

```jac
"""ADR H6 — measured evidence for multi-hop dependency walks.

Models the scenario behind issue #130: a glucose-monitoring product whose
build-time evaluation needs to chase CGM→Metric→Cohort→Threshold
relationships (parent_id chains, hand-rolled recursion, cycle hazards)
to decide which records to invalidate when a CGM device changes. The
demo replaces that recursion with native typed-edge traversal so the
ADR authors can measure depth, fan-out, and cycle exposure directly.
"""

# ---------- Edge archetypes (typed relationships) ----------

edge DependsOn {
    has weight: float = 1.0;
}

edge BelongsTo {
    has since: str = "";
}

# ---------- Node archetypes ----------

node CGMDevice {
    has device_id: str = "";
    has vendor: str = "";
    has schema_version: int = 1;
}

node Metric {
    has metric_name: str = "";
    has unit: str = "mg/dL";
}

node Cohort {
    has cohort_label: str = "";
    has min_age: int = 0;
}

node Threshold {
    has rule_name: str = "";
    has severity: str = "info";
}

# ---------- Walker: dependency traversal with cycle guard ----------

walker DependencyInspector {
    has origin_id: str = "";
    has max_depth: int = 8;
    has visited: list[str] = [];
    has depth_map: dict[str, int] = {};
    has cycle_found: bool = False;
    has reach_count: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can step with CGMDevice | Metric | Cohort | Threshold entry {
        origin = "";
        if self.origin_id == "" {
            origin = here.device_id if here isinstance CGMDevice else here.metric_name;
            self.origin_id = origin;
        } else {
            if here isinstance CGMDevice {
                origin = here.device_id;
            } elif here isinstance Metric {
                origin = here.metric_name;
            } elif here isinstance Cohort {
                origin = here.cohort_label;
            } else {
                origin = here.rule_name;
            }
        }
        self.depth_map[origin] = self.visited.length;
        if origin in self.visited {
            self.cycle_found = True;
            disengage;
        }
        self.visited.append(origin);
        self.reach_count += 1;
        if self.visited.length > self.max_depth {
            disengage;
        }
        visit [->:DependsOn:->];
    }
}

# ---------- Walker: cascade-invalidation reachability ----------

walker CascadeInvalidator {
    has invalid_count: int = 0;
    has affected_ids: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can collect with CGMDevice | Metric | Cohort | Threshold entry {
        target = "";
        if here instanceof CGMDevice {
            target = here.device_id;
        } elif here instanceof Metric {
            target = here.metric_name;
        } elif here instanceof Cohort {
            target = here.cohort_label;
        } else {
            target = here.rule_name;
        }
        self.affected_ids.append(target);
        self.invalid_count += 1;
        visit [->:DependsOn:->];
    }
}

# ---------- Walker: cohort membership traversal ----------

walker CohortMember {
    has cohort_label: str = "";
    has members: list[str] = [];

    can start with Root entry {
        visit [->:BelongsTo:->];
    }

    can walk_cohort with Cohort entry {
        if here.cohort_label == self.cohort_label {
            visit [->:BelongsTo:->];
        } else {
            disengage;
        }
    }

    can record_member with CGMDevice | Metric entry {
        target = here.device_id if here instanceof CGMDevice else here.metric_name;
        self.members.append(target);
        visit [->:BelongsTo:->];
    }
}

# ---------- Demonstration graph + spawning ----------

with entry {
    dexcom = CGMDevice(device_id="DEX-G6-001", vendor="Dexcom", schema_version=3);
