node AppPackage(Entity) {
    has package_path: str = "";
    has allowed_paths: list[str] = [];
}

node SourceModule(Entity) {
    has path: str = "";
    has extension: str = ".py";
}

node ImportSpec(Entity) {
    has module_name: str = "";
    has member: str = "";
    has star: bool = False;

    def normalized() -> str {
        candidate = self.module_name;
        if self.member != "" {
            if self.member != "*" {
                candidate = f"{self.module_name}.{self.member}";
            }
        }
        return candidate;
