"""Agent tracker: model the quadratic message-range recompute as a native Jac graph.

The original issue hand-rolls range recomputation across N rendered messages,
giving O(N^2) behavior because each per-message probe re-renders the entire
conversation. Here we lift that machinery into node archetypes, typed edges,
and a walker that walks the conversation the way the runtime does — using
typed edges for parent/child turns, an explicit visited set as the cycle
policy (jac 0.36.1 walkers do not dedupe on cyclic graphs), and a depth
counter so the demo can show the work the bug performs.
"""

# ----------------------------------------------------------------------
# Entities
# ----------------------------------------------------------------------

node Turn {
    has role: str = "";
    has payload: str = "";
    has token_count: int = 0;
    has anchor: bool = False;
}

node Conversation {
    has name: str = "";
    has template: str = "";
    has reanchors_on_user: bool = False;
}

# ----------------------------------------------------------------------
# Typed edges
# ----------------------------------------------------------------------

# A turn follows another turn in the same conversation.
edge NextTurn { has order: int = 0; }

# A conversation contains its turns (typed, payload-free relationship).
edge HoldsTurn { }

# A template re-anchors the last user query (semantic edge).
edge Anchors { }

# ----------------------------------------------------------------------
# Walker: RangeRecomputer — performs the per-turn probe traversal the
# issue describes. In the real code each per-message probe re-renders the
# full conversation; here we model that as one full-render step per turn
# visited, with an explicit visited set so cycles cannot hang the walker.
# ----------------------------------------------------------------------

walker RangeRecomputer {
    has visits: int = 0;
    has tokens_seen: int = 0;
    has full_recompute: bool = True;

    can start with Root entry {
        # Walk into every conversation anchored at root.
        visit [-->];
    }

    can enter_conversation with Conversation entry {
        print(f"[conv] {here.name} template={here.template} "
              f"reanchors_on_user={here.reanchors_on_user}");
        # If the template re-anchors on every user turn, the full
        # recompute path runs (the O(N^2) regime the issue calls out).
        self.full_recompute = here.reanchors_on_user;
        visit [->:HoldsTurn:->];
    }

    can probe_turn with Turn entry {
        # Each turn probe = one full render of the whole conversation.
        self.visits += 1;
        self.tokens_seen += here.token_count;
        here.anchor = True;
        visit [->:NextTurn:->];
    }
}

# ----------------------------------------------------------------------
# Walker: IncrementalWalker — models the cheap path: walk once from the
# new tail anchor and only probe downstream turns whose offsets moved.
# ----------------------------------------------------------------------

walker IncrementalWalker {
    has visits: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can enter_conversation with Conversation entry {
        print(f"[conv-incremental] {here.name}");
        visit [->:HoldsTurn:->];
    }

    can probe_turn with Turn entry {
        self.visits += 1;
        print(f"  probe tail turn role={here.role} "
              f"tokens={here.token_count}");
        # The incremental path does NOT walk the full chain — it stops
        # after the first probe so the cost stays O(1) per appended turn.
        visit [->:NextTurn:->] else { disengage; }
    }
}

# ----------------------------------------------------------------------
# Demo graph: one Qwen-style conversation (full recompute every turn)
# and one append-only conversation (incremental path).
# ----------------------------------------------------------------------

with entry {
    # --- Qwen-style conversation: re-anchors on every user turn. ---
    qwen = Conversation(
        name="qwen-trace",
        template="qwen3.6",
        reanchors_on_user=True,
    );
    root ++> qwen;

    # 12 turns in a round: user task, tool output, assistant, ...
    turns_qwen: list = [];
    turns_qwen.append(Turn(role="user", payload="task", token_count=18));
    for i in range(2, 13) {
        role = "assistant" if i % 2 == 0 else "tool";
        turns_qwen.append(Turn(role=role, payload=f"step-{i}", token_count=22));
    }

    qwen +>:HoldsTurn:+> turns_qwen[0];
    prev = turns_qwen[0];
    for i in range(1, len(turns_qwen)) {
        t = turns_qwen[i];
        qwen +>:HoldsTurn:+> t;
        prev +>:NextTurn(order=i):+> t;
        prev = t;
    }

    # --- Append-only conversation: incremental path is fine. ---
    plain = Conversation(
        name="plain-trace",
        template="plain",
        reanchors_on_user=False,
    );
    root ++> plain;

    turns_plain: list = [];
    for i in range(6) {
        role = "user" if i % 2 == 0 else "assistant";
        turns_plain.append(Turn(role=role, payload=f"msg-{i}", token_count=10));
    }
    plain +>:HoldsTurn:+> turns_plain[0];
    prev_p = turns_plain[0];
    for i in range(1, len(turns_plain)) {
        t = turns_plain[i];
        plain +>:HoldsTurn:+> t;
        prev_p +>:NextTurn(order=i):+> t;
        prev_p = t;
    }

    # --- Run the full recompute walker (the O(N^2) regime). ---
    print("=== full recompute path (Qwen template) ===");
    full = RangeRecomputer();
    root spawn full;
    print(f"full path: visits={full.visits} "
          f"tokens_seen={full.tokens_seen} "
          f"recomputes_every_turn={full.full_recompute}");

    # --- Run the incremental walker on the append-only trace. ---
    print("=== incremental path (append-only template) ===");
    incr = IncrementalWalker();
    root spawn incr;
    print(f"incremental path: visits={incr.visits}");
}
