```jac
"""Direct randomized experiment launch controller — day-1 model.

Models the essential scenario from issue #642: a randomized experiment that
must traverse a fixed delivery pipeline (selector → assignment → execution →
exposure → freezer) while preserving cycle safety, exclusive-writer semantics,
and rollback lineage. The walker advances the experiment along typed edges,
records lineage, and refuses to re-enter a node it has already sealed.
"""

node Stage {
    has name: str = "";
    has sealed: bool = False;
}

edge Next {
    has order: int = 0;
    has label: str = "";
}

walker LaunchController {
    has trial_id: str = "";
    has lineage: list[str] = [];
    has depth: int = 0;
    has max_depth: int = 10;

    can start with Root entry {
        self.lineage.append("root");
        visit [->:Next:->] else { disengage; }
    }

    can advance with Stage entry {
        # Cycle / depth guard — domain logic preserved explicitly.
        if self.depth >= self.max_depth {
            print(f"[{self.trial_id}] depth cap reached, halting");
            disengage;
        }
        if here.sealed {
            print(f"[{self.trial_id}] {here.name} already sealed, disengaging");
            disengage;
        }
        here.sealed = True;
        self.lineage.append(here.name);
        print(f"[{self.trial_id}] sealed {here.name} at depth {self.depth}");
        self.depth = self.depth + 1;
        # Forward along typed edges; typed fallback disengages the walker.
        visit [here ->:Next:->] else { disengage; }
    }
}

with entry {
    selector = Stage(name="selector");
    assignment = Stage(name="assignment");
    execution = Stage(name="execution");
    exposure = Stage(name="exposure");
    freezer = Stage(name="freezer");

    # Typed edges carry the pipeline ordering as payload.
    root +>:Next(order=1, label="pick"):+> selector;
    selector +>:Next(order=2, label="assign"):+> assignment;
    assignment +>:Next(order=3, label="execute"):+> execution;
    execution +>:Next(order=4, label="expose"):+> exposure;
    exposure +>:Next(order=5, label="freeze"):+> freezer;

    # A second trial shares the graph; the sealed flag on each Stage
    # prevents re-entry (cycle / double-seal guard).
    root spawn LaunchController(trial_id="T-001");
    print("--- second trial ---");
    root spawn LaunchController(trial_id="T-002", max_depth=3);
}
