```jac
"""Apex Log Lifecycle tracer: refresh an org, fetch an Apex log, materialize
the local file, and route it to a raw editor — modeled as a walker traversal.

The issue's complaint is hand-rolled graph plumbing: a Logs tab holds rows of
ApexLog entities, each row points to a lifecycle-owned local file, the file
is rooted under an org, and the org wraps a Salesforce connection. Rather
than chasing those relationships through id-keyed maps, the walker follows
typed edges Org -> ApexLog -> LocalFile -> Editor and reports the chain it
observed, aborting with disengage when the org's connection is stale or the
materialized file has been invalidated.
"""

# --- Entity archetypes --------------------------------------------------------

node Org {
    has alias: str = "";
    has connection_fresh: bool = True;
}

node ApexLog {
    has log_id: str = "";
    has operation: str = "";
    has duration_ms: int = 0;
    has status_code: int = 0;
    has body_requested: bool = False;
}

node LocalFile {
    has path: str = "";
    has canonical_name: str = "";
    has materialized: bool = False;
    has invalidated: bool = False;
}

node RawEditor {
    has editor_name: str = "IntelliJ Standard Text Editor";
    has opened: bool = False;
}

# --- Relationship archetypes (typed edges) ------------------------------------

edge BelongsTo { }      # ApexLog -> Org
edge Stores { }         # LocalFile -> ApexLog
edge OwnerOrg { }       # LocalFile -> Org
edge RoutedTo { }       # LocalFile -> RawEditor

# --- Walker: the lifecycle tracer --------------------------------------------

walker LogLifecycle {
    has trace: list[str] = [];
    has skip_org: bool = False;

    # Detect a stale Salesforce connection (analog: auth refresh failure) and
    # abort the whole traversal cleanly.
    can check_org with Org entry {
        if not here.connection_fresh {
            self.skip_org = True;
            self.trace.append(f"ORG[{here.alias}] auth-stale -> disengage");
            disengage;
        }
        self.trace.append(f"ORG[{here.alias}] fresh, refresh ok");
        visit [-->];
    }

    # One ability handles both Org (root fan-out) and ApexLog (per-row work)
    # using a union trigger — same shape as the reference corpus pattern.
    can inspect with Org | ApexLog entry {
        if self.skip_org {
            disengage;
        }
        # Follow typed edges: from Org -> ApexLog (BelongsTo), from
        # ApexLog -> LocalFile (Stores).
        visit [->:BelongsTo:->];
        visit [->:Stores:->];
    }

    can fetch with ApexLog entry {
        # Cancel before issuing the Tooling-equivalent request.
        if here.log_id == "" {
            self.trace.append(f"APEXLOG[{here.operation}] skipped: empty id");
            disengage;
        }
        here.body_requested = True;
        self.trace.append(
            f"APEXLOG[{here.log_id}] {here.operation} "
            f"({here.duration_ms}ms, http {here.status_code}) body fetched"
        );
        visit [-->];
    }

    can materialize with LocalFile entry {
        # Domain rule: a invalidated lifecycle file is no longer the source
        # of truth — propagate the cancel and stop this branch.
        if here.invalidated {
            self.trace.append(
                f"FILE[{here.canonical_name}] invalidated -> cancel branch"
            );
            disengage;
        }
        here.materialized = True;
        self.trace.append(
            f"FILE[{here.canonical_name}] materialized at {here.path}"
        );
        visit [->:RoutedTo:->];
    }

    can open with RawEditor entry {
        here.opened = True;
        self.trace.append(f"EDITOR[{here.editor_name}] opened raw log");
    }

    # Final report: a single exit summary, order-stable.
    can summarize with Root entry {
        print("=== Apex Log Lifecycle trace ===");
        for line in self.trace {
            print(line);
        }
        print("=== end trace ===");
    }
}

# --- Demonstration graph ------------------------------------------------------

with entry {
    prod = Org(alias="prod", connection_fresh=True);
    staging = Org(alias="staging", connection_fresh=False);  # stale -> disengage

    # prod org owns two Apex logs, only one is fully wired through.
    log_a = ApexLog(
        log_id="07LAA000000X1",
        operation="ApexTrigger__c",
        duration_ms=412,
        status_code=200,
    );
    log_b = ApexLog(
        log_id="07LAA000000X2",
        operation="BatchApex__c",
        duration_ms=987,
        status_code=200,
    );

    file_a = LocalFile(
        path="/logs/prod/07LAA000000X1.log",
        canonical_name="07LAA000000X1.log",
    );
    file_b = LocalFile(
        path="/logs/prod/07LAA000000X2.log",
        canonical_name="07LAA000000X2.log",
        invalidated=True,  # simulates cancellation / partial completion
    );
    editor = RawEditor();

    # Wire the graph with typed edges.
    prod +>:BelongsTo:+> log_a;
    prod +>:BelongsTo:+> log_b;
    log_a +>:Stores:+> file_a;
    log_b +>:Stores:+> file_b;
    file_a +>:OwnerOrg:+> prod;
    file_b +>:OwnerOrg:+> prod;
    file_a +>:RoutedTo:+> editor;

    # Spawn one walker per org so the disengage on the stale one is observable.
    root ++> prod ++> staging;
    root spawn LogLifecycle();
}
