Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.

```jac
"""HIER benchmark core: ontology nodes, multi-parent DAG, and a hierarchy
walker that traverses parent edges, reports depth/order stats, and detects
cycles — modeling the traversal machinery the HIER issue complains about
without any external ontology I/O."""

# --- Node archetypes ----------------------------------------------------

node Concept {
    has label: str = "";
    has width_at_level: int = 0;
}

node Ontology {
    has name: str = "";
    has verdict: str = "";
}

# --- Typed edges (relationships that carry meaning) ----------------------

edge IsA {
    has source_id: str = "";
}

edge BelongsTo {
    has since: str = "";
}

# --- Walker: traverses parent edges, mirrors the PLL/2-hop baseline ----

walker HierarchyInspector {
    has ontology_name: str = "GO";
    has max_depth: int = 0;
    has node_count: int = 0;
    has cycle_found: bool = False;
    has visited: list[str] = [];
    has decline_paths: list[str] = [];

    can begin with Root entry {
        print(f"HIER inspection of '{self.ontology_name}' starting");
        visit [-->];
    }

    can catalog with Ontology entry {
        print(f"[ontology] {here.name} -> verdict: {here.verdict}");
        visit [-->];
    }

    can descend with Concept entry {
        self.node_count += 1;
        if here.label not in self.visited {
            self.visited.append(here.label);
        } else {
            self.cycle_found = True;
            print(f"[cycle] re-entered {here.label}");
            disengage;
        }
        # Width approaching leaf count -> the GO decline path the
        # issue calls out as the loudest one to publish.
        if here.width_at_level > 50 {
            self.decline_paths.append(here.label);
            print(
                f"[decline] {here.label} width={here.width_at_level} "
                f"> threshold; 2-hop index territory"
            );
        }
        visit [->:IsA:->] else { disengage; }
    }
}

# --- Walker: cascade-style invalidation along IsA edges ----------------

walker CascadeInvalidator {
    has origin: str = "";
    has invalidated: list[str] = [];

    can start with Root entry {
        print(f"Cascade invalidation rooted at {self.origin}");
        visit [-->];
    }

    can invalidate with Concept entry {
        self.invalidated.append(here.label);
        print(f"[invalidate] {here.label}");
        visit [->:IsA:->] else { disengage; }
    }
}

# --- Demo wiring -------------------------------------------------------

with entry {
    # Build a small DAG that mirrors the GO-shaped decline the issue
    # describes: a wide level > 50 near the leaves, plus a cycle to
    # exercise the cycle guard and a back-edge to exercise the walker.
    go = Ontology(name="Gene Ontology", verdict="decline_at_leaf");
    root +>:BelongsTo(since="2024-Q1"):+> go;

    # Mid-level concept with fan-out 60 (> threshold 50).
    mid = Concept(label="GO:0008150_biological_process", width_at_level=60);
    go +>:IsA(source_id="root"):+> mid;

    # Three children at leaf level (wide fan-in target).
    leaf_a = Concept(label="GO:0009987_cellular_process", width_at_level=3);
    leaf_b = Concept(label="GO:0008152_metabolic_process", width_at_level=3);
    leaf_c = Concept(label="GO:0050896_response_to_stimulus", width_at_level=3);
    mid +>:IsA:+> leaf_a;
    mid +>:IsA:+> leaf_b;
    mid +>:IsA:+> leaf_c;

    # Multi-parent edge: leaf_a also reachable from a sibling concept.
    alt = Concept(label="GO:0005575_cellular_component", width_at_level=4);
    alt +>:IsA:+> leaf_a;

    # Back-edge creating a cycle so the guard fires.
    leaf_a +>:IsA:+> mid;

    inspector = HierarchyInspector(ontology_name="GO-shard");
    root spawn inspector;

    print(
        f"inspected {inspector.node_count} concepts, "
        f"max_depth={inspector.max_depth}, "
        f"cycle_found={inspector.cycle_found}, "
        f"decline_paths={inspector.decline_paths}"
    );

    # Second walker: cascade invalidation from the wide mid-level node.
    cascader = CascadeInvalidator(origin=mid.label);
    root spawn cascader;
    print(f"cascade invalidated {len(cascader.invalidated)} concepts: {cascader.invalidated}");
}
