"""City guide: stations connect to hotels and attractions; a walker from each station
shortlists only attractions rated 4 stars or higher and prints the itinerary."""

node Station {
    has name: str = "";
}

node Hotel {
    has name: str = "";
    has nightly_rate: float = 0.0;
}

node Attraction {
    has name: str = "";
    has stars: int = 0;
}

edge ConnectsTo {}

walker Tourist {
    can start with Root entry {
        visit [-->];
    }

    can arrive with Station entry {
        print(f"Arrived at station: {here.name}");
        visit [-->];
    }

    # Union trigger: only attractions and hotels have a `name`; stations
    # carry a `name` too but the union is restricted to leaves.
    can review with Attraction | Hotel entry {
        # Skip hotels entirely.
        if not isinstance(here, Attraction) {
            print(f"  (skipping hotel: {here.name})");
            visit [-->];
            disengage;
        }
        # Only attractions with 4+ stars make the shortlist.
        status = "SHORTLIST" if here.stars >= 4 else "PASS";
        print(f"  [{status}] {here.name} ({here.stars}★)");
        visit [-->];
    }
}

