Task:
A maintainer on the project nanvix/nanvix (unknown) filed this issue about hand-rolled graph machinery causing pain:

Issue #2254: [syscall] Optimize dlfcn lookup cycle detection with graph coloring

## Summary

The visited set introduced in #2093 (PR #2253) uses a heap-allocated `BTreeSet<usize>` per lookup call. This works correctly but allocates on every `lookup()` invocation and has O(log n) per-node checks. A graph coloring scheme could eliminate the allocation and provide O(1) visited checks.

## Proposed Approach

Replace the per-lookup `BTreeSet` with an atomic generation counter stored directly in each dependency node:

1. **Add an atomic epoch field outside the mutex**, accessible without locking:
   ```rust
   struct DlNode {
       lib: Mutex<DynamicLibrary>,
       last_visited_epoch: AtomicU64,
   }
   ```

2. **A global atomic epoch counter** incremented at the start of each `lookup()` call.

3. **Check-and-stamp before locking** each dependency:
   ```rust
   let epoch = CURRENT_EPOCH.load(Relaxed);
   if dlnode.last_visited_epoch.swap(epoch, AcqRel) == epoch {
       continue; // already visited this epoch
   }
   ```

## Trade-offs

| Aspect | BTreeSet (current) | Graph coloring |
|---|---|---|
| Allocation | One BTreeSet per lookup | None |
| Per-node cost | O(log n) | O(1) atomic CAS |
| Concurrency | Naturally per-thread | Needs care with concurrent lookups sharing epochs |
| Structural change | None | Requires wrapping `Arc<Mutex<DynamicLibrary>>` in a new `Arc<DlNode>` type |

## Affected Files

- `src/libs/syscall/src/dlfcn/syscall/dynlib.rs` — dependency storage type and lookup logic
- `src/libs/syscall/src/dlfcn/syscall/dlopen.rs` — dependency construction and binding

## References

- #2093 — original bug (visited set fix)
- #2253 — PR implementing the BTreeSet approach

Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.

```jac
"""Dynamic library dependency lookup with cycle-safe walker traversal.

Models the essential scenario from the nanvix/nanvix issue #2254: a lookup
walker traverses a graph of dynamic-library dependency nodes, and must
detect cycles without allocating a per-call visited container. The
walker stamps an epoch counter onto each node (instead of using a
heap-allocated set) and skips nodes whose epoch already matches the
current generation. This is the "graph coloring" idea: instead of
remembering who we have visited in a side-car collection, we mark the
node itself.
"""

# ----------------------------------------------------------------------
# Node archetypes
# ----------------------------------------------------------------------

node DlNode {
    has name: str = "";
    # The "graph coloring" stamp: a node whose stamp already equals
    # CURRENT_EPOCH has been visited during this lookup and must be
    # skipped to break the cycle. Stored as plain ints (the issue uses
    # AtomicU64, but the in-memory demo is single-threaded).
    has last_visited_epoch: int = -1;
    # Optional payload so the demo can show what each node represents.
    has so_path: str = "";
}

node LookupRoot {
    has query: str = "";
}

# ----------------------------------------------------------------------
# Edge archetype
# ----------------------------------------------------------------------

# A dependency edge carries the name of the library required by the
# source node. Typed edges here because the relationship is the whole
# point of the model.
edge DependsOn {
    has required_lib: str = "";
}

# ----------------------------------------------------------------------
# Walker: the lookup walker that traverses dependencies.
# ----------------------------------------------------------------------

walker Lookup {
    # The current generation. Bumped once at the start of every lookup
    # so the walker never needs to allocate a fresh visited set.
    has current_epoch: int = 0;
    has hits: list[str] = [];
    has query: str = "";

    can begin with LookupRoot entry {
        # Start the traversal from the root node, following DependsOn
        # edges outward. The union trigger below lets us visit the
        # dependency targets without dispatching on Root again.
        print(f"[epoch {self.current_epoch}] lookup start, query={self.query}");
        visit [->:DependsOn:->];
    }

    # One union ability handles every dependency target: it stamps the
    # node, then either reports a hit or recurses into the node's own
    # dependencies. The cycle guard is the epoch swap itself: if the
    # node was already stamped this epoch we disengage the descent.
    can traverse with DlNode entry {
        prior = here.last_visited_epoch;
        here.last_visited_epoch = self.current_epoch;
        if prior == self.current_epoch {
            # Already visited this generation — cycle detected, bail
            # out of this subtree without recursing.
            print(f"  [cycle] skip {here.name} (already visited epoch {self.current_epoch})");
            disengage;
        }
        if here.name == self.query {
            self.hits.append(here.name);
            print(f"  [hit ] {here.name} -> {here.so_path}");
            # Match found — no need to keep walking this branch.
            disengage;
        }
        visit [->:DependsOn:->] else {
            disengage;
        }
    }
}

# ----------------------------------------------------------------------
# Walker: bumps the epoch so we can re-run lookups against the same
# graph without rebuilding it.
# ----------------------------------------------------------------------

walker EpochReset {
    has next_epoch: int = 0;
    can begin with Root entry {
        # Walkers don't share state; in a real port the epoch is a
        # global. We simulate that by handing it out via a node field.
        epoch_node = LookupRoot(query="__epoch__");
        epoch_node.last_epoch = self.next_epoch;
        root ++> epoch_node;
        epoch_node spawn Lookup(current_epoch=self.next_epoch, query="libc.so.6");
    }
}

# ----------------------------------------------------------------------
# Helper: expose a way to run two lookups in succession on the same
# graph so the demo shows the epoch stamping both runs share storage.
# ----------------------------------------------------------------------

node EpochGate {
    has last_epoch: int = 0;
    has hits: list[str] = [];
    has query: str = "";
}

walker TwoPassAudit {
    can begin with Root entry {
        visit [-->];
    }
    can run with EpochGate entry {
        # Run a lookup, then re-run it; the second pass should still
        # correctly detect the cycle because the epoch advances.
        epoch = here.last_epoch;
        first = Lookup(current_epoch=epoch, query=here.query);
        second = Lookup(current_epoch=epoch + 1, query=here.query);
        # Just print the plan; actual spawn happens in `with entry`.
        print(f"plan: run epoch {epoch}, then epoch {epoch + 1}");
