"""Dependency resolution failure walk.

Models sbt's hand-rolled resolver: modules depend on other modules via
transitive edges, a resolver walker traverses the graph looking up local
and remote artifacts, and a failed lookup cascades an invalidation
upward through the dependency chain.
"""

# ----- Node archetypes -----------------------------------------------------

node Module {
    has name: str = "";
    has artifact_id: str = "";
    has local_ok: bool = False;
    has remote_ok: bool = False;

    def is_resolved() -> bool {
        return self.local_ok or self.remote_ok;
    }
}

node Repo {
    has url: str = "";
}

# ----- Typed edges ----------------------------------------------------------

edge DependsOn {
    has version: str = "";
    has scope: str = "compile";
}

edge HostedIn { }

# ----- Walkers --------------------------------------------------------------

walker Resolver {
    has failures: list = [];
    has visited: list = [];
    has depth_limit: int = 8;
    has depth: int = 0;

    can start with Root entry {
        print("=== Resolving zinc module dependencies ===");
        self.visited = [];
        self.failures = [];
        visit [-->];
    }

    can probe_repos with Module entry {
        # cycle policy: guard set, no built-in dedup in jac 0.36.1
        if self.depth > self.depth_limit {
            disengage;
        }
        if self.visited.count(here) > 0 {
            disengage;
        }
        self.visited.append(here);

        # First check the local repo, then the remote one.
        local_repo = [here --> ->:HostedIn:->][0] if here --> ->:HostedIn:-> else None;
        remote_repo = [here --> ->:HostedIn:->][1] if here --> ->:HostedIn:-> and (here --> ->:HostedIn:->).count > 1 else None;

        # Simulate lookup: a module is "found" if it has an artifact id.
        if here.artifact_id != "" {
            here.local_ok = here.local_ok or (local_repo is not None);
            here.remote_ok = here.remote_ok or (remote_repo is not None);
        }

        status = "RESOLVED" if here.is_resolved() else "MISSING";
        prefix = "  " * self.depth;
        if status == "MISSING" {
            print(f"{prefix}[{status}] {here.name}:{here.artifact_id}");
            self.failures.append(here);
        } else {
            print(f"{prefix}[{status}] {here.name}:{here.artifact_id}");
        }

        # Recurse into transitive dependencies.
        self.depth = self.depth + 1;
        visit [->:DependsOn:->];
        self.depth = self.depth - 1;
    }

    can finish with Root entry {
        # After traversal, cascade invalidation upward: if any failure
        # occurred, mark the whole compilation context as broken.
        if self.failures.count > 0 {
            print("");
            print(f"FAIL: {self.failures.count} unresolved dependency(s):");
            for f in self.failures {
                print(f"  - {f.name} -> {f.artifact_id}");
            }
            print("Cascading invalidation: compilerBridge will not be built.");
        } else {
            print("All dependencies resolved.");
        }
    }
}

# ----- Demo wiring ---------------------------------------------------------

