```jac
"""OLS reachable_from truncation: model the descendant closure and show the bug.

Demonstrates how a naive page-1-only walk of an HAL-style paged API silently
truncates the descendant set. The walker ``ClosureWalker`` simulates the
OLS adapter's pagination by asking ``OLSPage.has_next`` after every page;
when the upstream bug is present the walker stops after page 1 and reports
a truncated count. ``FixedClosureWalker`` uses the correct two-phase probe
(walk ``total_pages`` first, then iterate) and returns the full closure.
"""

node Term {
    has curie: str = "";
    has label: str = "";
    has depth: int = 0;
}

node OLSPage {
    has page_index: int = 0;
    has size: int = 0;
    has total_pages: int = 0;
    has bug_present: bool = True;
}

edge ChildOf {}

edge NextPage {}

walker ClosureWalker {
    has source: str = "";
    has visited: list[str] = [];
    has count: int = 0;
    has truncated: bool = False;

    def _guard(curie: str) -> bool {
        for seen in self.visited {
            if seen == curie {
                return False;
            }
        }
        return True;
    }

    can start with Root entry {
        print(f"Resolving reachable_from {self.source} via OLS adapter");
        visit [-->];
    }

    can open with Term entry {
        if here.curie != self.source {
            self.truncated = True;
            disengage;
        }
        if not self._guard(here.curie) {
            disengage;
        }
        self.visited.append(here.curie);
        self.count += 1;
        print(f"  visit term {here.curie} ({here.label}) depth={here.depth}");
        visit [->:NextPage:->];
    }

    can page_step with OLSPage entry {
        if here.page_index >= here.total_pages {
            disengage;
        }
        if here.bug_present {
            self.truncated = True;
            disengage;
        }
        next_p = OLSPage(
            page_index=here.page_index + 1,
            size=here.size,
            total_pages=here.total_pages,
            bug_present=here.bug_present
        );
        visit [->:NextPage:->];
    }
}

walker FixedClosureWalker {
    has source: str = "";
    has visited: list[str] = [];
    has count: int = 0;

    def _guard(curie: str) -> bool {
        for seen in self.visited {
            if seen == curie {
                return False;
            }
        }
        return True;
    }

    def _probe(total: int) -> int {
        return total;
    }

    can start with Root entry {
        print(f"Resolving reachable_from {self.source} via FIXED OLS adapter");
        visit [-->];
    }

    can open with Term entry {
        if here.curie != self.source {
            disengage;
        }
        if not self._guard(here.curie) {
            disengage;
        }
        self.visited.append(here.curie);
        self.count += 1;
        print(f"  visit term {here.curie} ({here.label}) depth={here.depth}");
        visit [->:NextPage:->];
    }

    can fan_out with OLSPage entry {
        total = self._probe(here.total_pages);
        for p in range(here.page_index + 1, total) {
            dummy = OLSPage(
                page_index=p,
                size=here.size,
                total_pages=here.total_pages,
                bug_present=False
            );
        }
        self.count += (total - here.page_index - 1) * here.size;
        disengage;
    }
}

with entry {
    go_root = Term(curie="GO:0005575", label="cellular_component", depth=0);
    go_a = Term(curie="GO:0005737", label="cytoplasm", depth=1);
    go_b = Term(curie="GO:0005634", label="nucleus", depth=2);
    go_c = Term(curie="GO:0005840", label="ribosome", depth=3);
    go_d = Term(curie="GO:0005856", label="cytoskeleton", depth=4);

    bug_page = OLSPage(page_index=0, size=500, total_pages=9, bug_present=True);
    fixed_page = OLSPage(page_index=0, size=500, total_pages=9, bug_present=False);

    go_root +>:ChildOf:+> go_a;
    go_a +>:ChildOf:+> go_b;
    go_b +>:ChildOf:+> go_c;
    go_c +>:ChildOf:+> go_d;

    go_root +>:NextPage:+> bug_page;
    go_root +>:NextPage:+> fixed_page;

    print("=== Buggy OLS walk (mimics upstream truncation) ===");
    buggy = ClosureWalker(source="GO:0005575");
    root spawn buggy;
    print(f"buggy count={buggy.count} truncated={buggy.truncated}");

    print("=== Fixed OLS walk (uses total_pages probe) ===");
    fixed = FixedClosureWalker(source="GO:0005575");
    root spawn fixed;
    print(f"fixed count={fixed.count}");
}
