"""Context-aware compiler: walk the Rego compile pipeline stages with
explicit cancellation checks so that a canceled request stops the
walk instead of hanging it. Mirrors the OPA issue where long-running
recursive stages (e.g. WalkRules) need to honor ctx.Done().
"""

# ---------- Entity archetypes ----------

node Stage {
    has name: str = "";
    # How many recursions this stage is allowed before we treat it as a hang.
    has budget: int = 5;
    # Current recursion depth into this stage's dependents.
    has depth: int = 0;
}

node Bundle {
    has name: str = "";
    # Was the bundle already activated (compiled)?
    has activated: bool = False;
}

# ---------- Edge archetypes ----------
# A "feeds" edge models the compile pipeline order: stages feed each other
# (e.g. Parse -> CheckTypes -> WalkRules -> Compile).
edge Feeds { has order: int = 0; }

# ---------- Walker: context-aware compiler ----------
walker Compiler {
    # The request context. When this is True the walk must stop.
    has canceled: bool = False;
    # Collected status for each stage we ran.
    has report: list[str] = [];

    # Entry: start the compile pipeline from the bundle.
    can activate with Bundle entry {
        label = "ACTIVATED" if here.activated else "PENDING";
        print(f"bundle {here.name}: {label}");
        if not here.activated {
            here.activated = True;
            self.report.append(f"activated bundle {here.name}");
        }
        visit [->:Feeds:->];
    }

    # Recursive stage handler: respects ctx cancellation each iteration,
    # and recurses through dependent stages along Feeds edges.
    can compile with Stage entry {
        if self.canceled {
            disengage;
        }
        verdict = "OK" if here.depth < here.budget else "TIMEOUT";
        print(f"  stage {here.name} depth={here.depth} -> {verdict}");
        self.report.append(f"{here.name}:{verdict}");

        # Bail if we exceeded this stage's budget (mirrors the issue's
        # complaint about long-running loops ignoring cancellation).
        if here.depth >= here.budget {
            self.canceled = True;
            disengage;
        }

        # Recurse: bump depth and descend through the Feeds edges.
        here.depth = here.depth + 1;
        visit [->:Feeds:->];
    }

    # Root entry: ignore — we always spawn on a Bundle.
    can start with Root entry {
        visit [-->];
    }
}

# ---------- Demo wiring ----------
with entry {
    # Build a small compile graph:
    #   Parse -> CheckTypes -> WalkRules -> Compile
    parse_stage = Stage(name="Parse", budget=3);
    check_stage = Stage(name="CheckTypes", budget=2);
    walk_stage = Stage(name="WalkRules", budget=4);
    compile_stage = Stage(name="Compile", budget=2);

    bundle = Bundle(name="user-policy.rego");

    bundle +>:Feeds(order=0):+> parse_stage;
    parse_stage +>:Feeds(order=1):+> check_stage;
    check_stage +>:Feeds(order=2):+> walk_stage;
    walk_stage +>:Feeds(order=3):+> compile_stage;

    # First run: normal, bounded by stage budgets (good path).
    print("--- run 1: full pipeline ---");
    Compiler() spawn bundle;

    # Second run: simulate ctx cancel right at the start.
    print("--- run 2: ctx canceled before stage 2 ---");
    bundle2 = Bundle(name="huge-policy.rego");
    bundle2 +>:Feeds:+> Stage(name="Parse", budget=3);
    bundle2 +>:Feeds:+> Stage(name="CheckTypes", budget=2);
    bundle2 +>:Feeds:+> Stage(name="WalkRules", budget=4);
    bundle2 +>:Feeds:+> Stage(name="Compile", budget=2);
    Compiler(canceled=True) spawn bundle2;
}

