```jac
"""Factory zone monitoring: one patrol walker inspects both temperature and smoke sensors."""

node Sensor {
    has label: str = "";

    def reading() -> str {
        return self.label;
    }
}

node TempSensor(Sensor) {
    has celsius: float = 0.0;

    def is_alert() -> bool {
        return self.celsius > 75.0;
    }
}

node SmokeSensor(Sensor) {
    has ppm: float = 0.0;

