Issue #1352: [B4] Meta ownership guard for EnsureConversationMeta

[parent] #1337
## Problem
`conversation_store_sqlite.go` ~502: EnsureConversationMeta ON CONFLICT overwrites ownership fields that PreserveConversationMeta guards (workspace repoint race).
## Outcome
Apply same CASE guards so second run with different repo path doesn't repoint workspace.
## Acceptance criteria
- Second run with different repo path does not repoint workspace.
## Test-first plan
Test: meta ownership preserved across EnsureConversationMeta (expected red).
## Impact analysis
SQLite write path only; no schema change.

Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.

```jac
"""Meta ownership guard for EnsureConversationMeta.

Models the bug from issue #1352: a second EnsureConversationMeta call with
a different repo path must NOT repoint the workspace ownership fields that
PreserveConversationMeta guards. The naive ON CONFLICT overwrite races on
workspace ownership. The fix applies CASE guards so existing ownership wins.
"""

node Workspace {
    has name: str = "";
    has owner: str = "";
    has repo: str = "";
    has branch: str = "";
    has initialized: bool = False;
}

node Conversation {
    has title: str = "";
    has summary: str = "";
    has linked_workspace: str = "";
}

edge Owns {
    has since: str = "";
}

edge References {
    has role: str = "primary";
}

walker EnsureConversationMeta {
    has incoming_repo: str = "";
    has incoming_branch: str = "";
    has report: dict = {};

    can start with Root entry {
        # Walk every conversation and ensure its meta, but only with
        # ownership-preserving semantics (the issue's acceptance criterion).
        visit [-->];
    }

    can preserve with Conversation entry {
        ws_name = here.linked_workspace;
        if ws_name == "" {
            # No linked workspace — nothing to preserve against.
            self.report[here.title] = "no-workspace-skip";
            disengage;
        }

        # The next hop is the owned Workspace (typed edge traversal).
        visit [here ->:Owns:->];
    }

    can apply_guards with Workspace entry {
        # CASE-guard semantics: existing ownership fields win on conflict.
        # The "second run with different repo path" must NOT repoint
        # workspace.name, workspace.owner, or workspace.branch.
        original_repo = here.repo;
        original_branch = here.branch;
        original_name = here.name;

        # Simulate the second call arriving with a different repo/branch.
        would_repoint = False;
        if here.initialized and here.repo != "" and here.repo != self.incoming_repo {
            would_repoint = True;
        }
        if here.initialized and here.branch != "" and here.branch != self.incoming_branch {
            would_repoint = True;
        }

        if would_repoint {
            # Guard fires: keep existing ownership, only update non-ownership
            # bookkeeping. This is the PreserveConversationMeta contract.
            self.report[original_name] = (
                f"preserved owner={here.owner} repo={here.repo} "
                f"branch={here.branch}; rejected incoming "
                f"repo={self.incoming_repo} branch={self.incoming_branch}"
            );
        } else {
            # First-time init or matching repo/branch: safe to take it.
            here.repo = self.incoming_repo;
            here.branch = self.incoming_branch;
            here.initialized = True;
            self.report[original_name] = (
                f"initialized repo={here.repo} branch={here.branch}"
            );
        }
    }
}

walker Audit {
    has report: list = [];

    can start with Root entry {
        visit [-->];
    }

    can list_convo with Conversation entry {
        self.report.append(f"conversation={here.title} -> ws={here.linked_workspace}");
        visit [-->];
    }

    can list_ws with Workspace entry {
        self.report.append(
            f"workspace={here.name} owner={here.owner} "
            f"repo={here.repo} branch={here.branch} init={here.initialized}"
        );
    }
}

with entry {
    # Two workspaces with distinct ownership already established.
    alpha = Workspace(
        name="alpha",
        owner="alice",
        repo="github.com/alice/core",
        branch="main",
        initialized=True,
    );
    beta = Workspace(
        name="beta",
        owner="bob",
        repo="github.com/bob/utils",
        branch="dev",
        initialized=True,
    );
    gamma = Workspace(
        name="gamma",
        owner="",
        repo="",
        branch="",
        initialized=False,
    );

    root ++> alpha;
    root ++> beta;
    root ++> gamma;

    convo1 = Conversation(title="design-review", linked_workspace="alpha");
    convo2 = Conversation(title="bug-triage", linked_workspace="beta");
    convo3 = Conversation(title="kickoff", linked_workspace="gamma");
    convo_orphan = Conversation(title="scratch", linked_workspace="");
    root ++> convo1;
    root ++> convo2;
    root ++> convo3;
    root ++> convo_orphan;

    # Typed edges: conversation OWNS its workspace reference.
    convo1 +>:Owns(since="2024-01"):+> alpha;
    convo2 +>:Owns(since="2024-03"):+> beta;
    convo3 +>:Owns(since="2024-05"):+> gamma;
    convo_orphan +>:References(role="none"):+> alpha;

    # First run: benign, matches existing ownership.
    print("=== first EnsureConversationMeta (matching) ===");
    root spawn EnsureConversationMeta(
        incoming_repo="github.com/alice/core",
        incoming_branch="main",
    );
    first = EnsureConversationMeta(incoming_repo="github.com/alice/core", incoming_branch="main");
    root spawn first;

    # Audit the state after the first run.
    audit1 = Audit();
    root spawn audit1;
    print("after first run:");
    for line in audit1.report {
        print(f"  {line}");
    }

    # Second run: different repo path on alpha must NOT repoint.
    print("=== second EnsureConversationMeta (repont attempt) ===");
    second = EnsureConversationMeta(
        incoming_repo="github.com/mallory/shadow",
        incoming_branch="evil-branch",
    );
    root spawn second;
    print("guard decisions:");
    for (k, v) in second.report.items() {
        print(f"  [{k}] {v}");
    }

    # Final audit: alpha must still belong to alice / original repo.
    audit2 = Audit();
    root spawn audit2;
    print("after second run (acceptance check):");
    for line in audit2.report {
        print(f"  {line}");
    }
}
