```jac
"""Order auditor: invalid orders are skipped but the walk continues,
while fraud-flagged orders halt the entire walk on the spot.

This program demonstrates two flavors of early-return working side by side:
``disengage;`` (terminate the walker) and ``continue;``-style ``visit [-->];``
skip (carry on to the next order after a quick report on this one).
"""

node Order {
    has label: str = "";
    has amount: int = 0;
    has valid: bool = True;
    has fraud: bool = False;
}

walker OrderAuditor {
    has report: list[str] = [];

    can start with Root entry {
        print(f"Auditor {self} begins sweep");
        visit [-->];
    }

    can audit with Order entry {
        # Fraud trumps everything: halt the whole walk immediately.
        if here.fraud {
            line = f"HALT (fraud) on {here.label} amount={here.amount}";
            self.report.append(line);
            print(line);
            disengage;
        }

        # Invalid orders are skipped but the audit keeps going.
        if not here.valid {
            line = f"SKIP (invalid) on {here.label} amount={here.amount}";
            self.report.append(line);
            print(line);
            visit [-->];
        }

        # Healthy order: record and move forward.
        line = f"OK on {here.label} amount={here.amount}";
        self.report.append(line);
        print(line);
        visit [-->];
    }
}

