"""Type alias cycle detection: model self-referencing and mutual typealiases
as nodes, traverse with a walker that detects cycles the way the checker
must — by carrying an explicit guard set, since walkers have no built-in
once-per-node visitation in Jac 0.36.1. Nominal recursive types remain
resolvable because the recursion terminates on a named boundary."""

# --- Node archetypes ---------------------------------------------------------

node AliasDecl {
    has name: str = "";
    # The "shape" being aliased: a payload label so we can distinguish
    # structural aliases (which must terminate, no infinite shape) from
    # nominal aliases (which terminate at the named boundary).
    has kind: str = "structural";   # "structural" or "nominal"
}

node TypeRef {
    has name: str = "";
}

# --- Edges -------------------------------------------------------------------

# `aliases` carries the alias declaration to the type it expands to.
edge Aliases { }

# `expands` marks the structural expansion: a typealias to a record-of-types.
# Following this edge is what overflows the checker when cycles exist.
edge Expands { }

# --- Walkers -----------------------------------------------------------------

walker AliasChecker {
    # Explicit guard set — Jac walkers do NOT dedupe, so we carry one.
    has on_path: list[str] = [];
    has cycle_found: bool = False;

    can start with Root entry {
        visit [-->];
    }

    # When we step onto an alias declaration, begin expansion tracking.
    can enter_alias with AliasDecl entry {
        # Re-entering the same alias while it is already on the path
        # is exactly the cycle the original checker crashed on.
        if here.name in self.on_path {
            self.cycle_found = True;
            cycle = self.on_path + [here.name];
            print(f"ERROR: typealias cycle detected: {' -> '.join(cycle)}");
            disengage;
        }
        self.on_path = self.on_path + [here.name];

        # Nominal aliases terminate at their named boundary; structural
        # aliases must still be expanded one more level.
        if here.kind == "nominal" {
            print(f"OK: nominal alias '{here.name}' resolves at named boundary");
            self.on_path = self.on_path[:-1];
            disengage;
        }
        visit [->:Expands:->];
    }

    # A TypeRef we arrive at via Expands: record it, then descend.
    can resolve_ref with TypeRef entry {
        if here.name in self.on_path {
            self.cycle_found = True;
            cycle = self.on_path + [here.name];
            print(f"ERROR: typealias cycle detected: {' -> '.join(cycle)}");
            disengage;
        }
        print(f"  expanding into {here.name}");
        visit [->:Expands:->];
    }
}

# --- Demo graph --------------------------------------------------------------

with entry {
    # Case 1: structural self-reference
    #   typealias Tree = { l: Tree, r: Tree }
    # The original checker recursed Tree -> Tree -> Tree ... and overflowed.
    tree_self = AliasDecl(name="Tree", kind="structural");
    tree_self_ref = TypeRef(name="Tree");
    root +>:Aliases:+> tree_self +>:Expands:+> tree_self_ref +>:Expands:+> tree_self_ref;

    # Case 2: a two-step mutual cycle
    #   typealias A = B
    #   typealias B = A
    a_decl = AliasDecl(name="A", kind="structural");
    b_decl = AliasDecl(name="B", kind="structural");
    a_ref = TypeRef(name="B");
    b_ref = TypeRef(name="A");
    root +>:Aliases:+> a_decl +>:Expands:+> a_ref;
    root +>:Aliases:+> b_decl +>:Expands:+> b_ref;
    a_decl +>:Expands:+> b_ref;

    # Case 3: a nominal recursive type — must still check and build.
    #   type Tree = { l: Tree, r: Tree }   (nominal; recursion terminates on the name)
    nom_decl = AliasDecl(name="Tree", kind="nominal");
    nom_ref = TypeRef(name="Tree");
    root +>:Aliases:+> nom_decl +>:Expands:+> nom_ref +>:Expands:+> nom_ref;

    print("=== Checking structural self-referencing typealias ===");
    c1 = AliasChecker();
    root spawn c1;

    print("=== Checking mutual two-step typealias cycle ===");
    c2 = AliasChecker();
    root spawn c2;

    print("=== Checking nominal recursive type (should be OK) ===");
    c3 = AliasChecker();
    root spawn c3;
}

