```jac
"""Workflow execution crash-recovery demo.

Models the durable-claim half of issue #4113: a workflow execution walks
its graph of side-effect nodes, each guarded by an idempotency key and a
lease that must not survive a worker kill forever. A CrashRecovery walker
traverses the execution, detects nodes whose lease has expired, and
re-claims them — exactly the traversal the issue says was missing.
"""

node Workflow {
    has name: str = "";
    has runs: bool = True;
}

node SideEffectNode {
    has title: str = "";
    has idempotency_key: str = "";
    has lease_until: int = 0;
    has status: str = "pending";
}

edge Owns { has role: str = "executor"; }
edge NextStep {}

walker CrashRecovery {
    has now: int = 0;
    has swept: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can audit with Workflow entry {
        visit [->:NextStep:->];
    }

    can recover with SideEffectNode entry {
        if here.status == "running" and here.lease_until < self.now {
            here.status = "pending";
            self.swept.append(here.title);
            print(f"[SWEEP] re-claimed '{here.title}' "
                  f"(idempotency={here.idempotency_key})");
        } else {
            print(f"[OK] {here.title} status={here.status}");
