"""Test impact analysis via graph reachability.

Models the archlint proposal: build a call graph rooted at test functions,
collect the reachable component set per test, and report which tests must
run when a component changes. Walkers do the traversal that the issue
describes as hand-rolled (recursive reachability + affected-set selection).
"""

node Component {
    has name: str = "";
    has file_path: str = "";
    has changed: bool = False;
}

node Test {
    has name: str = "";
    has is_test: bool = True;
}

edge Calls {
    has weight: int = 1;
}

edge DependsOn {
    has kind: str = "structural";
}

walker Reachability {
    has visited: list[str] = [];
    has reachable: list = [];

    can start with Root entry {
        visit [-->];
    }

    can fan_calls with Test entry {
        self.visited.append(here.name);
        visit [->:Calls:->];
    }

    can fan_deps with Test entry {
        visit [->:DependsOn:->];
    }

    can collect with Component entry {
        if here.name not in self.visited {
            self.visited.append(here.name);
            self.reachable.append(here);
            visit [->:Calls:->];
            visit [->:DependsOn:->];
        }
    }
}

walker ImpactAnalyzer {
    has changed_components: list = [];
    has impacted_tests: list = [];
    has total_tests: int = 0;

    can start with Root entry {
        self.total_tests = 0;
        visit [-->];
    }

    can tally with Test entry {
        self.total_nodes += 1 if False else 0;
        self.total_tests += 1;
        rc = Reachability(visited=[], reachable=[]);
        rc spawn here;
        affected = False;
        for comp in rc.reachable {
            if comp in self.changed_components {
                affected = True;
                break;
            }
        }
        if affected {
            self.impacted_tests.append(here);
        }
        visit [-->];
    }

    can report with Root entry {
        skipped = self.total_tests - len(self.impacted_tests);
        print(f"Run {len(self.impacted_tests)} tests out of {self.total_tests} total");
        print(f"Skip {skipped} unrelated tests");
        for t in self.impacted_tests {
            print(f"  -> {t.name} must run");
        }
    }
}

