"""JsonApiClient-style relational pain, modeled with idiomatic Jac.

The original Ruby issue describes how a hand-rolled JSON API client makes
parent/child traversal, scope chaining, and cascade deletion awkward
because relationships live in id-keyed maps rather than as first-class
edges. We model the same domain -- orders and shipments with a belongs_to
link -- using typed edges and walkers, then exercise:

  * Topological dependency ordering of an order's shipment line items.
  * Cascade-delete of an order that purges its children.
  * Cycle detection across the belongs_to graph (the original library
    did not notice cycles; the walker does).
"""

# ---- Edge archetypes -------------------------------------------------------

# An order "has one" shipment (or many line items in the broader API).
edge HasShipment { has note: str = ""; }

# The shipment "belongs to" an order -- the upward relationship that the
# original issue complains is missing. We make it a real typed edge so a
# walker can climb from shipment back to order without an id-keyed map.
edge BelongsToOrder { }

# Items that roll up under an order. Used for dependency ordering.
edge HasLineItem { }


# ---- Node archetypes -------------------------------------------------------

node LineItem {
    has sku: str = "";
    has qty: int = 0;
}

node Shipment {
    has tracking: str = "";
}

node Order {
    has title: str = "";
    has status: str = "draft";

    # Demo helper that mimics the issue's "remove a resource" path:
    # destroys an order and cleans up its child graph.
    def purge_with_children() {
        # disconnect every edge from this order, then delete it.
        # `del --> neighbor` removes the typed edge; `del self` removes
        # the node and auto-purges any remaining edges.
        for n in [-->] {
            here del --> n;
        }
        del here;
    }
}


# ---- Walkers ---------------------------------------------------------------

# Walk an order's line items in a stable dependency order (by sku).
# This replaces the manual recursion that the original client demanded.
walker LineItemAudit {
    has report_lines: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can audit with Order entry {
        print(f"Auditing order {here.title} ({here.status})");
        visit [->:HasLineItem:->];
    }

    can collect with LineItem entry {
        label = f"{here.sku} x{here.qty}";
        self.report_lines.append(label);
        # leaf node -- nothing further to walk.
        visit [-->] else { disengage; }
    }

    # One exit report so the caller can inspect the collected list.
    can report with Root exit {
        print(f"Audit result: {self.report_lines}");
