# Cascade-delete walker: spawn on an Order, walk its children, then
# delete the root order itself. This is the scenario the issue
# describes as broken (`order.shipment.destroy` failing because the
# relationship linker cannot walk upward).
walker CascadePurge {
    can start with Root entry {
        visit [->:HasShipment:->];
    }

    can purge_shipment with Shipment entry {
        print(f"Deleting shipment {here.tracking}");
        # remove the belongs_to edge back to the order so the order
        # is not orphaned by the link, then drop the shipment node.
        here del ->:BelongsToOrder:-> [-->];
        del here;
        visit [-->] else { disengage; }
    }

    can purge_order with Order entry {
        print(f"Purging order {here.title}");
        here.purge_with_children();
        # Once the root order is gone the walk has no frontier.
        visit [-->] else { disengage; }
    }
