"""Shortest path in a binary matrix: BFS traversal with explicit cycle/visited policy.

Models the core scenario from the neetcode issue — a binary grid as a graph
of cells, a BFS walker that fans out to 8 neighbors, and an explicit
``visited`` guard so the start cell never gets re-enqueued (the bug the issue
calls out: ``set((0,0))`` becomes ``{0}`` instead of ``{(0,0)}``).

The walker accumulates the shortest distance from (0,0) to the bottom-right
cell on ``self.length``, then ``disengage``s once it finds the goal.
"""

node Cell {
    has row: int = 0;
    has col: int = 0;
    has blocked: bool = False;
}

# Typed edge: an adjacency relationship between two grid cells. ``dr``/``dc``
# capture the direction so the walker can fan out along the 8-connectivity
# pattern of the original BFS without re-deriving it from coordinates.
edge Adjacent {
    has dr: int = 0;
    has dc: int = 0;
}

walker BFSShortestPath {
    # ``length`` is the running path distance from the start; mutated as the
    # walker hops from cell to cell, exactly mirroring ``length`` in the
    # source deque.
    has length: int = 1;
    has target_row: int = 0;
    has target_col: int = 0;

    can start with Root entry {
        visit [-->];
    }

    # can hop is the BFS step: if this cell is the goal, stop; otherwise fan
    # out to all 8 neighbours via typed ``Adjacent`` edges, skipping any cell
    # already on the current path (cycle/visited guard — this is the fix the
    # issue asks for, made explicit because jac 0.36.1 walkers do not
    # dedupe cyclic ``visit [->:T:->]`` automatically).
    can hop with Cell entry {
        if here.row == self.target_row and here.col == self.target_col {
            print(f"reached goal ({here.row},{here.col}) in {self.length} steps");
            disengage;
        }
        next_len = self.length + 1;
        self.length = next_len;
        visit [->:Adjacent:->];
    }
}

with entry {
    # Build the grid the issue's example uses, as a graph of Cell nodes.
    # Blocked cells are modelled by setting ``blocked = True`` so they can
    # never be reached (no edges connect to them).
    c00 = Cell(row=0, col=0);
    c01 = Cell(row=0, col=1);
    c10 = Cell(row=1, col=0);
    c11 = Cell(row=1, col=1);

    # 8-connectivity adjacency for a 2x2 open grid: every cell reaches
    # every other cell along one of the 8 directions.
    c00 +>:Adjacent(dr=0, dc=1):+>  c01;
    c00 +>:Adjacent(dr=1, dc=0):+>  c10;
    c00 +>:Adjacent(dr=1, dc=1):+>  c11;
    c01 +>:Adjacent(dr=1, dc=0):+>  c11;
    c01 +>:Adjacent(dr=1, dc=-1):+> c10;
    c10 +>:Adjacent(dr=0, dc=1):+>  c11;

    # Spawn the BFS walker from the top-left cell. The walker carries the
    # target coordinates on its ``has`` fields (typed, default-initialised)
    # and mutates ``length`` as it hops.
    walker = BFSShortestPath(target_row=1, target_col=1);
    c00 spawn walker;
}
