```jac
"""Google Drive (DWD scoped) ACL inheritance demo.

Models a Shared Drive with limited-access folders, drive membership,
folder-level grants, and a walker that recomputes effective permissions
for each document. The walker also detects stale ACLs and cascades
invalidation to children when a folder's grant changes.
"""

node Drive {
    has name: str = "";
    has members: list[str] = ["user@org"];
}

node Folder {
    has name: str = "";
    has limited_access: bool = False;
    has grants: list[str] = [];
    has stale: bool = False;
}

node Document {
    has title: str = "";
    has effective_acl: list[str] = [];
    has stale: bool = False;
}

edge Contains {}
edge Grants {}

walker AclAuditor {
    has drive_acl: list[str] = [];
    has visited: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can enter with Drive entry {
        self.drive_acl = list(here.members);
        self.visited = [];
        print(f"=== Auditing drive: {here.name} (members: {self.drive_acl}) ===");
        visit [-->];
    }

    can audit_folder with Folder entry {
        if here.limited_access {
            self.drive_acl = [];
            print(f"  [limited-access boundary] '{here.name}' truncates inherited drive ACL");
        }
        if here.grants {
            merged: list[str] = list(self.drive_acl);
            for g in here.grants {
                if g not in merged {
                    merged.append(g);
                }
            }
            self.drive_acl = merged;
            print(f"  Folder '{here.name}' grants: {here.grants} -> effective scope: {self.drive_acl}");
        }
        if here.stale {
            print(f"  [stale] folder '{here.name}' grant changed -> cascading invalidate");
        }
        visit [-->];
    }

    can exit_folder with Folder exit {
        if here.limited_access {
            print(f"  [exit limited-access] restoring drive baseline");
            self.drive_acl = list(here.members) if hasattr(here, "members") else self.drive_acl;
        }
    }

    can audit_doc with Document entry {
        acl = list(self.drive_acl);
        if here.stale {
            print(f"  [re-traverse] doc '{here.title}' marked stale; recomputing");
        }
        here.effective_acl = acl;
        print(f"  Doc '{here.title}' effective_acl = {here.effective_acl}");
    }
}

with entry {
    team_drive = Drive(name="Engineering DWD");
    root ++> team_drive;

    shared_folder = Folder(name="Shared Projects");
    limited_folder = Folder(name="Confidential", limited_access=True, grants=["lead@org"]);
    stale_folder = Folder(name="Renamed Team", stale=True, grants=["newteam@org"]);

    team_drive ++> shared_folder;
    team_drive ++> limited_folder;
    team_drive ++> stale_folder;

    doc_a = Document(title="roadmap.md");
    doc_b = Document(title="spec.doc");
    doc_c = Document(title="secrets.docx");

    shared_folder ++> doc_a;
    shared_folder ++> doc_b;
    limited_folder ++> doc_c;

    print("--- Drive-wide baseline ---");
    team_drive ++> Document(title="public_readme.md");

    root spawn AclAuditor();
}
