Task:
Health-inspect a restaurant kitchen line (grill, fryer, cold prep): check each station's temperature, flagging anything above 40 C as a violation, and separately log every station visit. Both checks must run at every station.

```jac
"""Restaurant kitchen line health inspection.

Walks a kitchen line (grill, fryer, cold prep) and runs two checks at every
station: a temperature violation check (flag anything above 40 C) and a
visit log entry (record every station visited). Both checks must run at every
station regardless of station type, so a union trigger on a shared base node
dispatches a single ability for all station variants.
"""

node Station {
    has name: str = "";
    has temperature: float = 0.0;

    def is_violation() -> bool {
        return False;
    }
}

node Grill(Station) {
    override def is_violation() -> bool {
        return self.temperature > 40.0;
    }
}

node Fryer(Station) {
    override def is_violation() -> bool {
        return self.temperature > 40.0;
    }
}

node ColdPrep(Station) {
    override def is_violation() -> bool {
        return self.temperature > 40.0;
    }
}

walker Inspector {
    has visited_stations: list[str] = [];
    has violations: list[str] = [];
    has station_count: int = 0;

    can start with Root entry {
        print(f"Inspector beginning kitchen line walk");
        visit [-->];
    }

    can inspect_station with Grill | Fryer | ColdPrep entry {
        self.station_count += 1;
        station_label = f"{type(here).__name__}:{here.name}";
        self.visited_stations.append(station_label);

        if here.is_violation() {
            alert = f"VIOLATION at {station_label} ({here.temperature} C)";
            self.violations.append(alert);
            print(f"  [ALERT] {alert}");
        } else {
            print(f"  [OK]    {station_label} at {here.temperature} C");
        }

        visit [-->];
    }
}

with entry {
    grill = Grill(name="Charbroiler", temperature=180.0);
    fryer = Fryer(name="Deep Fryer", temperature=175.0);
    cold = ColdPrep(name="Salad Station", temperature=4.0);
    warm_cold = ColdPrep(name="Dessert Display", temperature=22.0);

    root ++> grill ++> fryer ++> cold ++> warm_cold;

    inspector = Inspector();
    root spawn inspector;

    print(f"\n--- Inspection Summary ---");
    print(f"Stations visited: {inspector.station_count}");
    print(f"Visit log: {inspector.visited_stations}");
    print(f"Violations found: {len(inspector.violations)}");
    for v in inspector.violations {
        print(f"  - {v}");
    }
}
```

