Issue #65: [S4-04] Remove orphaned template components and browser key config

**Problem**
`Map.tsx`, `AIChatBox.tsx`, and `ManusDialog.tsx` have no production importers. `Map.tsx` constructs a browser request containing `VITE_FRONTEND_FORGE_API_KEY`, while `AIChatBox.tsx` documents a nonexistent `trpc.ai.chat` example. `.env.example` still advertises the browser-facing key. These template remnants create misleading capabilities and a future secret-exposure trap.

**Fix**
Delete the unused components and browser-key configuration, or wire an explicitly required feature only through an existing server-side authenticated provider route. Do not preserve dead template code behind another flag.

**Acceptance Criteria**
- [ ] No production bundle or environment contract references `VITE_FRONTEND_FORGE_API_KEY`
- [ ] Orphaned components and nonexistent API examples are removed
- [ ] Type-check and production build pass with no replacement client-side secret path

Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.

```jac
"""Cleanup of orphaned template components and browser key config.

Models the scenario from issue #65: a codebase graph where some components
have no production importers, some reference a browser-facing secret, and
some document a nonexistent API. A walker traverses the graph, identifies
the orphans, removes them, and reports what was cleaned up.
"""

node Component {
    has name: str = "";
    has path: str = "";
    has has_production_importers: bool = True;
    has exposes_browser_key: bool = False;
    has references_nonexistent_api: bool = False;
}

node EnvContract {
    has var_name: str = "";
    has required: bool = True;
}

edge Imports {
    has weight: int = 1;
}

walker Cleaner {
    has visited: list[str] = [];
    has removed: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can sweep with Component entry {
        self.visited.append(here.name);

        # Find each outbound import edge once.
        imports = [here->:Imports:->];

        # Cascade-delete components with zero production importers.
        if not here.has_production_importers {
            for imp in imports:
                here del ->:Imports:-> imp;
            del here;
            self.removed.append("orphan component (cascade-deleted)");
        } else {
            visit [-->];
        }
    }

    can sweep with EnvContract entry {
        self.visited.append(here.var_name);

        # Any env var that fronts a browser-facing key is dropped.
        if here.var_name == "VITE_FRONTEND_FORGE_API_KEY" {
            self.removed.append(
                "browser-facing env contract " + here.var_name
            );
            del here;
        } else {
            visit [-->];
        }
    }

    can sweep with Root entry {
        # Bounded walk — terminates because each visit removes at least one
        # unreachable node or exits the subgraph.
        if len(self.removed) == 0 {
            disengage;
        }
    }
}

walker Auditor {
    has found: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can audit with Component entry {
        if here.exposes_browser_key {
            self.found.append(
                here.name + " exposes a browser-facing secret"
            );
        }
        if here.references_nonexistent_api {
            self.found.append(
                here.name + " documents a nonexistent API"
            );
        }
        visit [-->];
    }

    can audit with EnvContract entry {
        if here.var_name == "VITE_FRONTEND_FORGE_API_KEY" {
            self.found.append(
                "env contract " + here.var_name
                    + " is browser-facing"
            );
        }
        visit [-->];
    }
}

with entry {
    # Orphaned template components (no production importers).
    map_comp = Component(
        name="Map.tsx",
        path="src/Map.tsx",
        has_production_importers=False,
        exposes_browser_key=True
    );
    chat_comp = Component(
        name="AIChatBox.tsx",
        path="src/AIChatBox.tsx",
        has_production_importers=False,
        references_nonexistent_api=True
    );
    manus_comp = Component(
        name="ManusDialog.tsx",
        path="src/ManusDialog.tsx",
        has_production_importers=False
    );

    # Production component (kept).
    dashboard = Component(
        name="Dashboard.tsx",
        path="src/Dashboard.tsx",
        has_production_importers=True
    );

    # Env contracts.
    browser_key = EnvContract(
        var_name="VITE_FRONTEND_FORGE_API_KEY",
        required=True
    );
    server_key = EnvContract(
        var_name="VITE_SERVER_FORGE_API_KEY",
        required=True
    );

    root ++> dashboard
        ++> browser_key
        ++> server_key
        ++> map_comp
        ++> chat_comp
        ++> manus_comp;

    # First pass: audit what is unsafe.
    print("--- Audit pass ---");
    root spawn Auditor();
    print("issues found:");
    for item in Auditor().found:
        # Fresh list each iteration via reassignment-safe construction.
        print(f"  - {item}");

    # Second pass: clean up.
    print("--- Cleanup pass ---");
    cleaner = Cleaner();
