Each delivery route from our depots carries a cargo weight in tonnes. A truck may only be dispatched when its load is at least 2 tonnes and at most 8 tonnes on the same leg. Check every depot and print which routes qualify for dispatch.

```jac
"""Delivery route eligibility: dispatch trucks only when cargo is 2-8 tonnes."""

node Route {
    has label: str = "";
    has cargo_tonnes: float = 0.0;
}

node Depot {
    has name: str = "";

    def qualifies(cargo: float) -> bool {
        return cargo >= 2.0 and cargo <= 8.0;
    }
}

edge Serves {
    has cargo_tonnes: float = 0.0;
}

walker Dispatcher {
    has eligible_count: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can audit with Depot entry {
        print(f"Depot {here.name} routes:");
        visit [->:Serves:->];
    }

    can check_route with Route entry {
        cargo = here.cargo_tonnes;
        status = "DISPATCH" if Depot().qualifies(cargo) else "HOLD";
        if status == "DISPATCH" {
            self.eligible_count += 1;
        }
        print(f"  [{status}] {here.label}: {cargo}t");
        visit [-->];
    }
}

with entry {
    north = Depot(name="North");
    south = Depot(name="South");

    north +>:Serves(cargo_tonnes=3.5):+> Route(label="N-A", cargo_tonnes=3.5);
    north +>:Serves(cargo_tonnes=9.0):+> Route(label="N-B", cargo_tonnes=9.0);
    north +>:Serves(cargo_tonnes=1.5):+> Route(label="N-C", cargo_tonnes=1.5);
    south +>:Serves(cargo_tonnes=6.0):+> Route(label="S-A", cargo_tonnes=6.0);
    south +>:Serves(cargo_tonnes=8.0):+> Route(label="S-B", cargo_tonnes=8.0);

    root ++> north ++> south;

    d = Dispatcher();
    root spawn d;
    print(f"Eligible routes for dispatch: {d.eligible_count}");
}
