Task:
A maintainer on the project stephenlclarke/container (unknown) filed this issue about hand-rolled graph machinery causing pain:

Issue #91: [Bug] Docker CLI can deadlock before start when wait acknowledgement is deferred

## Observed behavior

A Docker CLI `run --rm` uses the sequence:

1. attach
2. `POST /containers/{id}/wait?condition=removed`
3. wait for the HTTP response headers
4. `POST /containers/{id}/start`

The Engine implementation previously withheld the wait response until the
container reached the requested terminal state. Docker therefore waited for the
response before sending start, creating a liveness deadlock.

## Local correction and evidence

- Container source: `d843dd598fa086c8572e5df8a71eece56ad7b576`
- Engine API source: `afb8a8f68ed56829b669c95cbddb488a68dc9175`
- Focused Container and Engine API regressions pass.
- A marker-protected, isolated macOS runtime candidate ran Docker CLI 29.7.1
  successfully. Its trace proves `/wait?condition=removed` -> HTTP 200 ->
  `/start`; the Alpine workload printed its marker and exited 0.
- The candidate's debug-build performance warning was non-blocking. No hang
  occurred.

## Current status

The fix is locally verified but not yet publishable through the ordinary
dependency graph. The normal Container pin still resolves Engine API 0.3.5,
and the exact Containerization revision used by the candidate must be published
before it can become a normal remote pin.

## Closure criteria

1. Publish/review the Engine API change and update Container's dependency pin.
2. Publish/review the required Containerization revision and advance that pin.
3. Re-run the focused Docker CLI proof from the normal resolved graph.
4. Add the final evidence comment here and close this issue.

No push, pull request, or Apple upstream publication has been made for this
issue.

Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.

```jac
"""Docker CLI deadlock modeling: Engine /wait deferral + Container /start dependency.

The issue describes a deadlock in the Docker CLI `run --rm` sequence:
attach -> POST /wait?condition=removed -> wait for response -> POST /start.
The Engine previously withheld the /wait response until the container reached
the requested terminal state, so Docker never sent /start, and the container
never reached the removed state: classic liveness deadlock.

We model the essential scenario with node archetypes (Client, Engine, Container,
Task) and typed edges (Depends, WaitsFor, AcknowledgedBy) and use a walker that
performs the dependency-ordered traversal the issue complains about: starting
the container depends on having acknowledged the wait; the wait is gated on
reaching the terminal state; the terminal state is reached only by starting.
A cycle guard keeps the walker from looping; a deadlock detector reports when
the graph state fails to make forward progress.
"""

node Client {
    has name: str = "";
    has sent_start: bool = False;
}

node Engine {
    has name: str = "";
    has wait_deferred: bool = True;
}

node Container {
    has name: str = "";
    has started: bool = False;
    has terminal_reached: bool = False;
}

node Task {
    has name: str = "";
    has completed: bool = False;
}

edge Depends {
    has order: int = 0;
}

edge WaitsFor {
    has condition: str = "";
}

edge AcknowledgedBy {
    has status: int = 200;
}

walker RunSequence {
    has steps: list[str] = [];
    has deadlock: bool = False;
    has visited: list[str] = [];

    can start with Root entry {
        print(f"[{self.steps}] beginning Docker CLI run --rm sequence");
        visit [-->];
    }

    can at_client with Client entry {
        if here.name not in self.visited {
            self.visited.append(here.name);
        }
        self.steps = self.steps + ["attach"];
        print(f"[{self.steps}] Client '{here.name}' attached");
        visit [-->];
    }

    can at_engine with Engine entry {
        self.steps = self.steps + ["POST /wait?condition=removed"];
        if here.wait_deferred {
            print(f"[{self.steps}] Engine '{here.name}' DEFERRED /wait response (bug)");
            self.deadlock = True;
            visit [<--];
        } else {
            print(f"[{self.steps}] Engine '{here.name}' acknowledged /wait -> 200 (fixed)");
            visit [-->];
        }
    }

    can at_container with Container entry {
        self.steps = self.steps + ["POST /start"];
        if not here.started {
            here.started = True;
            print(f"[{self.steps}] Container '{here.name}' started -> exit 0");
            here.terminal_reached = True;
        } else {
            print(f"[{self.steps}] Container '{here.name}' already started");
        }
        visit [-->];
    }

    can at_task with Task entry {
        self.steps = self.steps + [f"task:{here.name}"];
        if here.completed {
            print(f"[{self.steps}] Task '{here.name}' already completed");
        } else {
            here.completed = True;
            print(f"[{self.steps}] Task '{here.name}' ran to completion");
        }
        visit [-->];
    }
}

walker DeadlockDetector {
    has report: str = "";

    can start with Root entry {
        self.report = self.report + "scanning graph: ";
        visit [-->];
    }

    can inspect with Client | Engine | Container | Task entry {
        state = "";
        if here.type == Client {
            state = f"client.start_sent={here.sent_start}";
        } elif here.type == Engine {
            state = f"engine.wait_deferred={here.wait_deferred}";
        } elif here.type == Container {
            state = f"container.started={here.started},terminal={here.terminal_reached}";
        } else {
            state = f"task.completed={here.completed}";
        }
        self.report = self.report + f"{here.name}({state}) ";
        visit [-->];
    }
}

with entry {
    client = Client(name="docker-cli");
    engine = Engine(name="engine-daemon", wait_deferred=True);
    container = Container(name="alpine-workload");
    task = Task(name="alpine-marker-print");

    root ++> client;
    client +>:Depends(order=1):+> engine;
    engine +>:WaitsFor(condition="removed"):+> container;
    container +>:Depends(order=2):+> task;
    engine +>:AcknowledgedBy(status=200):+> container;

    print("=== Buggy run (wait deferred) ===");
    buggy = RunSequence();
    root spawn buggy;
    print(f"steps recorded: {buggy.steps}");
    print(f"deadlock detected: {buggy.deadlock}");
    print(f"visited: {buggy.visited}");

    print("");
    print("=== Fixed run (wait acknowledged eagerly) ===");
    engine.wait_deferred = False;
    fixed = RunSequence();
    root spawn fixed;
    print(f"steps recorded: {fixed.steps}");
    print(f"deadlock detected: {fixed.deadlock}");

    print("");
    print("=== Final graph snapshot ===");
    detector = DeadlockDetector();
    root spawn detector;
    print(detector.report);
}
```

