**TypeScript Version:**  2.1.0

I'm using ts-loader and Webpack to compile my .ts files. In My Webpack config I have the following configuration:

```
resolve: {
  modulesDirectories: ['shared', 'node_modules']
}
```

This allows me to import a component that lives in the shared directory without spelling out the full relative path. Example: 
`import Button from 'components/Button'`

Webpack will walk up the directory tree and use the first `shared` directory it finds (the same way it does with the `node_modules` directories). This way, the component can live in the `../../shared/components/Buttton.tsx` and Webpack will find it and bundle it.

My files compile fine because I am using ts-loader but I am getting `can not find module` errors in my editor.

Is there a way to tell the TS compiler to recursively look for the component in the shared directories?

I noticed the new `baseUrl` and `paths` configuration option but to my knowledge you can not use `paths` to recursively look for a directory.


Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.

```jac
"""Module resolution walker.

Models the TypeScript issue: a `shared` directory acts like `node_modules` —
the resolver walks up the project tree until it finds the first directory
named `shared` and resolves the import from there. We capture the same
behavior with typed edges and a walker that climbs the parent chain.
"""

node Module {
    has name: str = "";
    has kind: str = "";          # "shared" or "project"
}

edge Contains {
    has file: str = "";
}

edge Child {
    has relative_path: str = "";
}

walker Resolver {
    has query: str = "";
    has found: Module | None = None;

    can start with Root entry {
        # Step into the project node where the import originated.
        visit [-->];
    }

    can search_project with Module entry {
        if here.kind == "shared" {
            # We hit a shared directory while climbing — try to find the
            # requested component directly inside it.
            visit [-->];
            return;
        }
        # First check this project directory's own shared folder (if any),
            # then walk up to the parent project.
        visit [-->] else {
            visit [<--];
        }
    }

    can climb with Module entry {
        # Walk upward through parent projects until we find a shared dir.
        visit [<--] else {
            # No more parents: stop walking.
            disengage;
        }
    }

    can locate with Module entry {
        # We are standing inside a "shared" directory — look for the file.
        for child in [-->] {
            c = child;
            edge_file = [here->:Contains:->c->file][0] if [here->:Contains:->c] else "";
            if edge_file == self.query {
                self.found = c;
                disengage;
            }
        }
        # Not in this shared dir — keep climbing parents.
        visit [<--] else {
            disengage;
        }
    }
}

with entry {
    # Build the directory tree:
    #   root -> projectA (kind="project")
    #           -> projectA/shared (kind="shared")  contains Button.tsx
    #           -> parentProject (kind="project")
    #           -> parentProject/shared (kind="shared") contains Button.tsx
    #
    # The resolver must climb from projectA up to its parent and find
    # Button.tsx in the FIRST shared directory it encounters.

    proj_a = Module(name="projectA", kind="project");
    proj_a_shared = Module(name="shared", kind="shared");
    proj_parent = Module(name="parentProject", kind="project");
    proj_parent_shared = Module(name="shared", kind="shared");
    button = Module(name="Button", kind="file");

    root ++> proj_a;
    proj_a +>:Child(relative_path="."):+> proj_a_shared;
    proj_a_shared +>:Contains(file="components/Button"):+> button;

    proj_a +>:Child(relative_path=".."):+> proj_parent;
    proj_parent +>:Child(relative_path="."):+> proj_parent_shared;
    proj_parent_shared +>:Contains(file="components/Button"):+> Module(name="Button", kind="file");

    r = Resolver(query="components/Button");
    root spawn r;

    if r.found is not None {
        print(f"Resolved components/Button to {r.found.name} "
              f"in the first shared directory encountered while climbing.");
    } else {
        print("components/Button could not be resolved.");
    }
}
