Task:
A maintainer on the project matteobortolazzo/cenci (unknown) filed this issue about hand-rolled graph machinery causing pain:

Issue #1064: flow(refine): emit a stack layout for ordered split children

## Problem

`/cenci:refine` already computes everything a stack needs and then throws the ordering away at the branch level. For an M/L ticket it produces numbered children as native sub-issues, links them with `gh issue edit --add-blocked-by`, writes a `Depends on #<n>` prose line into each dependent child's body, and appends an `### Execution Order` note to the parent when the children are not all independent.

That execution order *is* the stack order. Nothing currently records which branch each child should build on, so every child branches from `main` and the ordering is enforced by serialization instead.

## Goal

Have refine emit an explicit stack layout for ordered split children, so each child ticket carries the base it should be implemented on.

## Acceptance criteria

- [ ] When a split's children have real ordering, refine records each child's base — the preceding layer's branch for a dependent child, `main` for the bottom layer.
- [ ] Children the split marks as independent are **not** stacked: they keep `main` as their base and remain genuinely parallel. Stacking a set of independent children would serialize work that is currently already parallel — a regression, not a feature.
- [ ] A design-only first child is never a stack layer — it produces a committed design spec, not a PR, so nothing can target its branch.
- [ ] Split depth stays one; a stack is a layout over existing children and never mints grandchild tickets (`docs/ticket-sizing.md`).
- [ ] The layout is visible to a human on the parent, alongside the existing `### Execution Order` note, not only in machine-readable form.
- [ ] The Confirmation Gate renders the proposed stack before any GitHub write, and declining performs zero writes — consistent with every other refine write path.
- [ ] When the `gh stack` capability probe reports absent, refine emits no stack layout and the split behaves exactly as it does today.
- [ ] Tests cover: an ordered split producing a layout, an all-independent split producing none, a design-first split, and the capability-absent path.

## Dependencies

Gated on the spike's decision doc and on the base-ref plumbing (the layout has nowhere to be consumed until a ticket can carry a base). Pairs with the Blocked-Dependency Gate's stackable path — the layout is what that gate reads.

## Size estimate

M — one new output from an existing split computation, plus the gate's rendering and the four test paths.

Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.

```jac
"""Stack layout for ordered split children.

Models the /cenci:refine scenario: a parent ticket splits into child
tickets. Some children are independent (parallel), some are ordered
(depend on a previous layer). A walker traverses the split, lays out a
stack (each dependent child's base = the preceding layer's branch,
independent children branch from main, a design-only first child is
never a stack layer), and the layout is rendered to the parent before
any "write" happens.
"""

# ---------- Edge archetypes -----------------------------------------------

edge Split {
    has layer: int = 0;
}

edge Blocks {
    has note: str = "";
}

# ---------- Node archetypes -----------------------------------------------

node Ticket {
    has title: str = "";
    has kind: str = "code";
    has base: str = "";
    has executed: bool = True;
}

node SplitGroup {
    has title: str = "";
    has ordered: bool = False;
}

# ---------- Capability probe ----------------------------------------------

node CapabilityProbe {
    has stack_available: bool = True;
}

# ---------- Walker --------------------------------------------------------

walker StackRefine {
    has stack_layers: list[list[str]] = [];
    has wrote_anything: bool = False;

    can probe with CapabilityProbe entry {
        if not here.stack_available {
            print("[probe] gh stack capability ABSENT — no stack layout");
            self.wrote_anything = True;
            disengage;
        }
        visit [-->];
    }

    can plan with SplitGroup entry {
        print(f"[split] {here.title} ordered={here.ordered}");
        # Walk children in source order, group by layer number on the edge.
        layers: dict[int, list[object]] = {};
        for child in [-->] {
            layer_no = 0;
            for e in [edge src ->> (child,) on Split] {
                layer_no = e.layer;
            }
            if not (layer_no in layers) {
                layers[layer_no] = [];
            }
            layers[layer_no].append(child);
        }
        ordered_keys: list[int] = [];
        for k in layers.keys() {
            ordered_keys.append(k);
        }
        ordered_keys.sort();

        for k in ordered_keys {
            kids = layers[k];
            # Independent children: no stack layer; base stays "main".
            if not here.ordered {
                for child in kids {
                    if not child.executed {
                        # design-only first child: never a stack layer
                        continue;
                    }
                    child.base = "main";
                    print(f"  - {child.title} (independent, base=main)");
                }
                continue;
            }

            # Ordered split: each dependent child's base = preceding layer's branch.
            prev_branch: str = "main";
            if k > 0 {
                prev_kids = layers[k - 1];
                if len(prev_kids) > 0 {
                    prev_branch = f"layer-{k - 1}/" + prev_kids[0].title.lower().replace(" ", "-");
                }
            }
            for child in kids {
                if not child.executed {
                    print(f"  - {child.title} (design-only, skipped as layer)");
                    continue;
                }
                child.base = prev_branch if k > 0 else "main";
                print(f"  - {child.title} base={child.base}");
            }
        }

        # Render the layout visibly on the parent (before any write).
        print(f"### Stack Layout for {here.title}");
        for k in ordered_keys {
            kids = layers[k];
            for child in kids {
                if not child.executed {
                    continue;
                }
                layer_branch = (
                    f"layer-{k}/" + child.title.lower().replace(" ", "-")
                    if here.ordered
                    else "main"
                );
                print(f"  - layer {k}: {child.title} -> {layer_branch}");
            }
        }

        # Confirmation Gate: declined -> zero writes.
        declined = False;
        if declined {
            print("[gate] declined — zero writes performed");
            disengage;
        }

        # Commit phase: lay down the Blocked edges (the actual write).
        for k in ordered_keys {
            kids = layers[k];
            for i in range(1, len(kids)) {
                kids[i - 1] +>:Blocks(note="stack"):+> kids[i];
            }
        }
        self.wrote_anything = True;
        disengage;
    }

    can audit with Ticket entry {
        print(f"  ticket {here.title} kind={here.kind} base={here.base}");
    }
}

# ---------- Demo ----------------------------------------------------------

with entry {
    # Ordered split: A -> B -> C, where B depends on A, C depends on B.
    ordered = SplitGroup(title="auth-refactor", ordered=True);
    a = Ticket(title="Schema A", kind="code");
    b = Ticket(title="Schema B", kind="code");
    c = Ticket(title="Schema C", kind="code");
    ordered +>:Split(layer=0):+> a;
    ordered +>:Split(layer=1):+> b;
    ordered +>:Split(layer=2):+> c;
    root ++> ordered;

    # All-independent split: no stack layout should be emitted.
    indep = SplitGroup(title="parallel-tweaks", ordered=False);
    t1 = Ticket(title="Tweak A", kind="code");
    t2 = Ticket(title="Tweak B", kind="code");
    indep +>:Split(layer=0):+> t1;
    indep +>:Split(layer=0):+> t2;
    root ++> indep;

    # Design-first split: first child is design-only, never a stack layer.
    design = SplitGroup(title="design-then-build", ordered=True);
    d0 = Ticket(title="Design Spec", kind="design", executed=False);
    d1 = Ticket(title="Impl X", kind="code");
