    can recheck with Report entry {
        g2_ok = here.g2_seconds <= here.owner.g2_budget;
        g3_ok = here.g3_ms <= here.owner.g3_budget;
        here.owner.g2_within_budget = g2_ok;
        here.owner.g3_within_budget = g3_ok;
        here.owner.regression = (not g2_ok) or (not g3_ok);
        verdict = "GREEN" if (g2_ok and g3_ok) else "RED";
        print(
