    can roll_up with Phase entry {
        verdict = "GREEN" if not here.regression else "RED";
        evidence = "evidence attached" if here.evidence_pasted else "MISSING evidence";
        print(
            f"  {here.gate} ({here.name}) -> {verdict}; {evidence}; "
            f"G2={here.g2_seconds:.2f}s, G3={here.g3_ms:.1f}ms"
        );
