"""Reconciliation semantics demo.

Models the essential scenario from the issue: a set of tasks with
parent/descendant lineage, stale review artifacts, and a reconciliation
walker that classifies each task as eligible or ineligible for terminal
mutation based on durable evidence — without hand-rolled recursion.
"""

node Task {
    has title: str = "";
    has lane: str = "backlog";
    has version: int = 0;
    has completed: bool = False;
    has blocked: bool = False;
    has verdict: str = "unknown";
    has author_kind: str = "human";
    has eligible: bool = False;
    has reason: str = "";
}

edge ParentOf {
    has version_at_link: int = 0;
}

walker Reconciler {
    has covered_root: str = "";
    has covered_root_version: int = 0;
    has apply: bool = False;
    has mutations: int = 0;

    can start with Root entry {
        print("Reconciler: dry-run pass over descendant task chain");
        visit [-->];
    }

    can inspect with Task entry {
        # A union-ish guard: compute eligibility from shared fields only.
        current_lane = here.lane;
        completed = here.completed;
        blocked = here.blocked;
        verdict_ok = here.verdict in ["approved", "merged", "evidence_only"];
        author_chain_ok = here.author_kind in ["engineer", "system", "human"];
        stale = current_lane in ["review", "fix", "backlog", "superseded"];
        lineage_ok = here.version == 0;

        # Decision is per-task and atomic.
        if completed and not blocked and verdict_ok and author_chain_ok and stale and lineage_ok {
            here.eligible = True;
            here.reason = "structured evidence + lineage + author chain all present";
        } else {
            here.eligible = False;
            here.reason = "missing gate: " + (
                "blocked " if blocked else
                "verdict=" + here.verdict + " " if not verdict_ok else
                "author=" + here.author_kind + " " if not author_chain_ok else
                "lane=" + current_lane + " " if not stale else
                "version-drift "
            );
        }

        # Apply recomputes the full plan before any write; only eligible
        # rows enter mutation, and the count derives from observed Done.
        if self.apply and here.eligible {
            new_lane = "done" if current_lane != "done" else current_lane;
            here.lane = new_lane;
            self.mutations = self.mutations + 1;
        }

        print(f"[{here.lane}] {here.title} -> eligible={here.eligible} ({here.reason})");
        visit [-->];
    }
}

with entry {
    # A covered root that stays put; reconciliation must not touch it.
    root_task = Task(title="TORQUE:1205", lane="done", completed=True, verdict="merged", author_kind="system");

    # The four stale residue tasks described in the issue.
    t1185 = Task(title="TORQUE:1185", lane="review", completed=True, verdict="approved", author_kind="engineer");
    t1185_1 = Task(title="TORQUE:1185:1", lane="fix", completed=True, verdict="approved", author_kind="system");
    t1200_3 = Task(title="TORQUE:1200:3", lane="backlog", completed=True, verdict="evidence_only", author_kind="system");
    t1208_ask = Task(title="TORQUE:1208-reviewer-ask", lane="superseded", completed=True, verdict="merged", author_kind="system");

    # One ineligible task to prove the dry-run does not suppress others.
    blocked_one = Task(title="TORQUE:1300", lane="review", completed=True, blocked=True, verdict="approved", author_kind="engineer");

    # Wire the lineage as typed edges; the root is the covering evidence.
    root ++> root_task;
    root_task +>:ParentOf(version_at_link=3):+> t1185;
    root_task +>:ParentOf(version_at_link=3):+> t1185_1;
    root_task +>:ParentOf(version_at_link=2):+> t1200_3;
    root_task +>:ParentOf(version_at_link=1):+> t1208_ask;
    root_task +>:ParentOf(version_at_link=0):+> blocked_one;

    # Phase 1: dry-run (apply=false) — must mutate nothing.
    print("=== DRY RUN (apply=false) ===");
    dry = Reconciler(covered_root="TORQUE:1205", covered_root_version=3, apply=False);
    root spawn dry;
    print(f"dry-run mutations observed: {dry.mutations} (expected 0)\n");

    # Phase 2: apply (apply=true) — only eligible rows move.
