Enforce clearance levels in our data center: each server room posts the level required, technicians walking the corridor are granted or denied per room, and anyone denied ends their walkthrough immediately without reaching deeper rooms. Report how many rooms each technician reached.

```jac
"""Data center clearance enforcement.

Server rooms post a clearance level they require. Technicians carry a
granted clearance level; they are admitted to a room only when their
level meets the requirement. A denial ends the walkthrough immediately,
so a technician that is refused at one room never reaches any deeper
room in the corridor. The final report counts how many rooms each
technician successfully entered.
"""

node Room {
    has label: str = "";
    has required_level: int = 0;
}

edge LeadsTo {
    has label: str = "";
}

walker Technician {
    has name: str = "";
    has clearance: int = 0;
    has rooms_visited: int = 0;
    has denied: bool = False;

    can start with Root entry {
        visit [->:LeadsTo:->];
    }

    can walk with Room entry {
        if self.denied {
            # Already refused at an earlier room; corridor ends here.
            disengage;
        }
        if self.clearance >= here.required_level {
            self.rooms_visited += 1;
            print(f"{self.name} admitted to {here.label} (needs {here.required_level})");
            visit [->:LeadsTo:->];
        } else {
            self.denied = True;
            print(f"{self.name} DENIED at {here.label} (needs {here.required_level}, has {self.clearance})");
            disengage;
        }
    }
}

with entry {
    # Build the corridor: ServerA -> ServerB -> Vault -> ColdStorage
    server_a = Room(label="ServerA", required_level=1);
    server_b = Room(label="ServerB", required_level=2);
    vault = Room(label="Vault", required_level=3);
    cold = Room(label="ColdStorage", required_level=4);
    root +>:LeadsTo:+> server_a +>:LeadsTo:+> server_b +>:LeadsTo:+> vault +>:LeadsTo:+> cold;

    # Junior: cleared for level 1 only -> stopped at ServerB.
    junior = Technician(name="Junior", clearance=1);
    root spawn junior;
    print(f"{junior.name} reached {junior.rooms_visited} room(s)");

    # Mid: cleared for level 3 -> into the Vault, stopped at ColdStorage.
    mid = Technician(name="Mid", clearance=3);
    root spawn mid;
    print(f"{mid.name} reached {mid.rooms_visited} room(s)");

    # Senior: cleared for everything -> reaches every room.
    senior = Technician(name="Senior", clearance=5);
    root spawn senior;
    print(f"{senior.name} reached {senior.rooms_visited} room(s)");
}
