Issue #624: Memory usage with recursive file list

When using "s3cmd ls --recursive" on a path with a huge number of files (for example, 1 million files), the process seems to fetch all the data into memory before writing to stdout. This is works well until the oom-killer kills the process due to excessive memory consumption.

Would it be possible to add a new option to write the list directly stdout after each API request is completed?

Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.

```jac
"""Streaming S3-style listing: bucket contains folders, folders contain objects.

Models the s3cmd issue where a recursive list of a huge prefix fetched every
object into memory before printing. The naive walker accumulates the whole
tree on its `has collected: list` field, mimicking the OOM behavior. The
streaming walker emits each object as it is visited, never holding the full
list, mimicking the requested fix.
"""

node Bucket {
    has name: str = "";
}

node Folder {
    has prefix: str = "";
}

node Object {
    has key: str = "";
    has size: int = 0;
}

edge Contains {
    has child_kind: str = "";
}


walker NaiveLister {
    # The buggy behavior: drain the whole tree into one in-memory list.
    has collected: list = [];

    can start with Root entry {
        visit [->:Contains:->];
    }

    can descend with Bucket | Folder entry {
        visit [->:Contains:->];
    }

    can collect with Object entry {
        self.collected.append((here.key, here.size));
    }
}


walker StreamingLister {
    # The fix: print each object as the walker reaches it, no accumulation.
    has emitted: int = 0;

    can start with Root entry {
        visit [->:Contains:->];
    }

    can descend with Bucket | Folder entry {
        visit [->:Contains:->];
    }

    can stream with Object entry {
        self.emitted += 1;
        print(f"  -> {here.key} ({here.size} bytes)");
    }
}


with entry {
    # Build a small but representative prefix tree.
    photos = Folder(prefix="photos/");
    vacation = Folder(prefix="photos/vacation/");
    work = Folder(prefix="photos/work/");

    root +>:Contains(child_kind="bucket"):+> Bucket(name="my-bucket")
        +>:Contains(child_kind="folder"):+> photos
        +>:Contains(child_kind="folder"):+> vacation
        +>:Contains(child_kind="folder"):+> work;

    photos +>:Contains(child_kind="object"):+> Object(key="photos/cat.jpg", size=2048);
    vacation +>:Contains(child_kind="object"):+> Object(key="photos/vacation/beach.jpg", size=5400);
    vacation +>:Contains(child_kind="object"):+> Object(key="photos/vacation/sunset.jpg", size=3200);
    work +>:Contains(child_kind="object"):+> Object(key="photos/work/report.pdf", size=88000);

    print("=== Naive recursive listing (holds everything in memory) ===");
    naive = NaiveLister();
    root spawn naive;
    print(f"Naive: held {len(naive.collected)} entries in a list at once "
          f"(this is what OOMs on 1M objects).");
    for (k, s) in naive.collected {
        print(f"  buffered: {k} ({s} bytes)");
    }

    print("");
    print("=== Streaming recursive listing (emit per object) ===");
    stream = StreamingLister();
    root spawn stream;
    print(f"Streaming: emitted {stream.emitted} objects without buffering the full list.");
}
