Task:
A maintainer on the project robertsreberski/bujo-with-ai (unknown) filed this issue about hand-rolled graph machinery causing pain:

Issue #28: [Architecture] Enforce one-way server layer dependencies

Tracks #18 as a post-release architecture hardening follow-up.

## Problem
The current cycle test proves file acyclicity inside the domain folder, but folder-level direction is still bidirectional: domain imports database and contracts, while database and contract facades import domain errors, parsing, or search normalization. The BeforeCommitPort seam is also declared separately from the concrete transaction participant path.

## Acceptance criteria
- Shared parsing, normalization, and errors live in a neutral layer with one-way imports.
- Domain access to persistence is expressed through a domain-facing port; database adapters implement it without importing feature orchestration.
- Transaction participants use one real before-commit port or the unused abstraction is removed.
- A whole-server layer-direction test detects cross-folder cycles and forbidden back-imports.
- Public API/MCP contracts and migration behavior remain unchanged.
- Server typecheck, unit, integration, release-tool, and browser gates remain green.

Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.

```jac
"""Server layer dependency demo: model one-way server layer dependencies as a typed graph.

Entities are server layers (Domain, Persistence, Parsing, Contracts). Edges model
the allowed import direction: 'Allowed' edges point from a layer to a layer it may
import; 'Forbidden' edges mark reverse (back-import) relationships that should
never appear. The DependencyAuditor walker performs a depth-limited traversal
following Allowed edges, detects cross-folder cycles via a guard set, and reports
any Forbidden back-edges observed while walking — the whole-server layer-direction
check the issue calls for.
"""

node Layer {
    has name: str = "";
    has depth_cap: int = 5;
    has visited: list[str] = [];
    has found_cycles: list[list[str]] = [];
    has forbidden_back_imports: list[tuple[str, str]] = [];

    def record_visit(seen: list[str]) -> None {
        if self.name not in seen {
            seen.append(self.name);
        }
    }
}

edge Allowed {
    has reason: str = "";
}

edge Forbidden {
    has reason: str = "";
}

walker DependencyAuditor {
    has path: list[str] = [];
    has depth: int = 0;
    has seen: list[str] = [];
    has cycles: list[list[str]] = [];
    has violations: list[tuple[str, str]] = [];

    can start with Root entry {
        visit [-->];
    }

    can audit with Layer entry {
        self.path.append(here.name);
        self.depth += 1;
        here.record_visit(self.seen);

        cycle = self.path[:];
        if self.depth > here.depth_cap {
            label = "DEPTH_CAP";
            print(f"[{label}] stopping at {here.name} (depth={self.depth})");
            self.cycles.append(cycle);
            visit [->:Allowed:->] else { disengage; }
        }

        forbidden_neighbours = [here ->:Forbidden:->];
        for bad in forbidden_neighbours {
            pair = (here.name, bad[0].name);
            self.violations.append(pair);
            print(f"[VIOLATION] forbidden back-import: {pair[0]} -> {pair[1]} ({bad[1].reason})");
        }

        visit [->:Allowed:->] else { disengage; }
    }
}

walker CascadeInvalidator {
    has invalid_prefix: str = "domain";

    can start with Root entry {
        visit [-->];
    }

    can invalidate with Layer entry {
        if here.name.startswith(self.invalid_prefix) {
            print(f"[INVALIDATE] purging {here.name} and downstream");
        }
        visit [->:Allowed:->] else { disengage; }
    }
}

with entry {
    domain = Layer(name="domain", depth_cap=5);
    parsing = Layer(name="parsing");
    persistence = Layer(name="persistence");
    contracts = Layer(name="contracts");
    errors = Layer(name="errors");

    root ++> domain ++> parsing ++> errors;
    root ++> domain ++> persistence ++> errors;
    root ++> domain ++> contracts ++> errors;

    domain +>:Allowed(reason="uses parsers"):+> parsing;
    domain +>:Allowed(reason="uses repos"):+> persistence;
    domain +>:Allowed(reason="uses contracts"):+> contracts;
    parsing +>:Allowed(reason="raises"):+> errors;
    persistence +>:Allowed(reason="raises"):+> errors;
    contracts +>:Allowed(reason="raises"):+> errors;

    persistence +>:Forbidden(reason="should not import domain logic"):+> domain;
    contracts +>:Forbidden(reason="should not import domain logic"):+> domain;

    auditor = DependencyAuditor();
    root spawn auditor;
    print(f"detected {auditor.cycles.__len__()} depth-cap events, "
          f"{auditor.violations.__len__()} forbidden back-imports");

    invalidator = CascadeInvalidator(invalid_prefix="domain");
    root spawn invalidator;
}
```

