```jac
"""Shared team task board: open-attach archetype with user-owned, readable contributions and a stats walker."""

node TeamMember {
    has name: str = "";
    has role: str = "";
}

node Task {
    has title: str = "";
    has owner: str = "";
    has priority: int = 1;
    has status: str = "pending";  // pending | done | cancelled
    has hours: float = 0.0;
}

# Open-attach archetype policy: any team member may attach and detach tasks freely.
node Board {
    has title: str = "";
    has archived: bool = False;

    can attach with TeamMember entry {
        new_task = Task(
            title=visitor_payload("title", "Untitled"),
            owner=here.name,
            priority=visitor_payload("priority", 1),
            status=visitor_payload("status", "pending"),
            hours=visitor_payload("hours", 0.0),
        );
        here +>:OpenAttach:+> new_task;
        print(f"[CREATE] {new_task.title} owned by {new_task.owner} (status={new_task.status})");
        visit [-->];
    }

    can read_board with TeamMember entry {
        print(f"--- Board '{here.title}' as seen by {visitor.name} ---");
        for t in [-->](?Task) {
            label = "[X]" if t.status == "done" else "[ ]";
            print(f"  {label} {t.title} | owner={t.owner} | priority={t.priority} | hours={t.hours} | status={t.status}");
        }
        visit [-->];
    }

    can update_task with Task entry {
        new_title = visitor_payload("title", here.title);
        new_priority = visitor_payload("priority", here.priority);
        new_status = visitor_payload("status", here.status);
        new_hours = visitor_payload("hours", here.hours);
        print(f"[UPDATE] {here.title} -> '{new_title}' pri={new_priority} status={new_status} hrs={new_hours}");
        here.title = new_title;
        here.priority = new_priority;
        here.status = new_status;
        here.hours = new_hours;
        visit [<--];
    }

    can delete_task with Task entry {
        print(f"[DELETE] removing task '{here.title}' (owner={here.owner})");
        del here;
        visit [<--];
    }
}

# Edge archetype declaring the board is an open-attachment policy (encoded once, not per grant).
edge OpenAttach {
    has note: str = "open-attach policy: any member may add tasks here";
}

# Reusable payload carrier so walkers can carry CRUD inputs.
walker Visitor {
    has payload: dict = {};
}

# CRUD: Create -----------------------------------------------------------
walker CreateTask {
    has title: str = "Untitled";
    has priority: int = 1;
    has status: str = "pending";
    has hours: float = 0.0;

    can drop with Root entry {
        visit [-->];
    }

    can land_on_board with Board entry {
        print(f"[CREATE] '{self.title}' attached to board '{here.title}'");
        task_node = Task(
            title=self.title,
            owner=visitor_name,
            priority=self.priority,
            status=self.status,
            hours=self.hours,
        );
        here +>:OpenAttach:+> task_node;
        visit [-->];
    }
}

# CRUD: Read -------------------------------------------------------------
walker ReadBoard {
    can start with Root entry {
        visit [-->];
    }

    can show with Board entry {
        print(f"=== Board: {here.title} ===");
        for t in [-->](?Task) {
            label = "[X]" if t.status == "done" else "[ ]";
            print(f"  {label} {t.title} | owner={t.owner} | pri={t.priority} | hrs={t.hours} | {t.status}");
        }
        visit [-->];
    }
}

# CRUD: Update -----------------------------------------------------------
walker UpdateTask {
    has title: str = "";
    has priority: int = -1;     // -1 sentinel = leave unchanged
    has status: str = "";
    has hours: float = -1.0;    // -1 sentinel = leave unchanged

    can start with Root entry {
        visit [-->];
    }

    can edit with Task entry {
        new_title = self.title if self.title != "" else here.title;
        new_priority = self.priority if self.priority != -1 else here.priority;
        new_status = self.status if self.status != "" else here.status;
        new_hours = self.hours if self.hours != -1.0 else here.hours;
        print(f"[UPDATE] {here.title} -> '{new_title}' pri={new_priority} status={new_status} hrs={new_hours}");
        here.title = new_title;
        here.priority = new_priority;
        here.status = new_status;
        here.hours = new_hours;
        visit [-->] else { disengage; }
    }
}

# CRUD: Delete -----------------------------------------------------------
walker DeleteTask {
    has title: str = "";

    can start with Root entry {
        visit [-->];
    }

    can remove with Task entry {
        if self.title == "" or here.title == self.title {
            print(f"[DELETE] removing '{here.title}'");
            del here;
            visit [-->] else { disengage; }
        } else {
            visit [-->] else { disengage; }
        }
    }
}

# Stats walker: one pass, totals + completion rate + per-assignee breakdown.
walker BoardStats {
    can start with Root entry {
        visit [-->];
    }

    can summarize with Board entry {
        tasks = [-->](?Task);
        total = len(tasks);
        done = 0;
        cancelled = 0;
        total_hours = 0.0;
        per_owner: dict = {};

        for t in tasks {
            total_hours = total_hours + t.hours;
            if t.status == "done" {
                done = done + 1;
            }
            if t.status == "cancelled" {
                cancelled = cancelled + 1;
            }
            current = per_owner.get(t.owner, 0);
            per_owner[t.owner] = current + 1;
        }

        active = total - cancelled;
        completion_rate = 0.0;
        if active > 0 {
            completion_rate = (done * 100.0) / active;
        }

        print(f"=== STATS: {here.title} ===");
        print(f"  total tasks      : {total}");
        print(f"  done             : {done}");
        print(f"  cancelled        : {cancelled}");
        print(f"  completion rate  : {completion_rate:.1f}% (over {active} active)");
        print(f"  total hours      : {total_hours}");
        print(f"  per-assignee counts:");
        for owner, count in per_owner.items() {
            print(f"    - {owner}: {count}");
        }
        visit [-->] else { disengage; }
    }
}

