"""MCP lazy-require cleanup: model loaders as walkers over a typed dependency graph.

The original issue describes four MCP tool entry-points (`loadServerUtilities`,
`loadResources`, `loadRequestTarget`, `loadItcHandlers`) that pull Harper
internals through lazy `require()` inside try/catch to dodge a circular /
boot-order dependency graph. Each has a test-seam override and a silent
no-op-on-failure path.

This demo lifts that machinery to native Jac OSP:

  * Entity archetypes (the MCP tool entry-points and the Harper modules they
    lazily reach) become `node`s with typed `has` fields.
  * The hand-rolled dependency graph becomes typed `edge`s: `DependsOn` for
    the eager-init relationship, `Overrides` for the test-seam override,
    and `NoOpFallback` for the silent "not in a Harper process" path.
  * The traversal that the issue asks us to fix (reach every loader,
    follow its dependency, decide if the dependency is wired or silently
    masked) becomes a `walker` that visits along typed edges and reports
    exactly one verdict per loader.

A walker in jac 0.36.1 has no built-in once-per-node visitation, so we keep
an explicit cycle guard on the walker itself (semantics the source carries).
"""

# ---------------------------------------------------------------------------
# Entity archetypes
# ---------------------------------------------------------------------------

# A Harper internal module that MCP tool entry-points depend on.
node HarperModule {
    has name: str = "";
    # True when this module has been booted in the current process.
    has booted: bool = False;
}

# An MCP tool loader: the entry-point that used to do a lazy require().
node McpLoader {
    has name: str = "";
    # True when the loader has been migrated to a top-level static import.
    has migrated: bool = False;
    # Counter for how many times this loader has been visited during the
    # current audit.  Used to detect cycle re-entry.
    has visits: int = 0;
}

# The Harper process that hosts everything; gives us a place to spawn the
# audit walker from.
node HarperProcess {
    has pid: int = 0;
}

# ---------------------------------------------------------------------------
# Typed edges (the relationship carries meaning)
# ---------------------------------------------------------------------------

edge DependsOn {
    has weight: int = 1;
}

edge Overrides {
    has reason: str = "";
}

edge NoOpFallback {
    has symptom: str = "";
}

# ---------------------------------------------------------------------------
# Walker
# ---------------------------------------------------------------------------

walker LoaderAuditor {
    has started_at: str = "Root";
    has guarded: list[str] = [];
    has report: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    # Union trigger: fires for either kind of node we land on from Root.
    can descend with McpLoader | HarperModule entry {
        if here.name in self.guarded {
            return;
        }
        self.guarded.append(here.name);

        if isinstance(here, McpLoader) {
            here.visits += 1;
            verdict = self.audit_loader(here);
            self.report.append(verdict);
        } else {
            self.report.append(f"module {here.name} booted={here.booted}");
        }

        visit [->:DependsOn:->] + [->:Overrides:->];
    }

    can dead_end with McpLoader entry {
        self.report.append(f"{here.name}: ONLY a NoOpFallback - smells like masking");
        disengage;
    }

    # Walker-side helper: operate on `self` / `here`.
    def audit_loader(loader: McpLoader) -> str {
        # Inspect outgoing typed edges directly via the graph.
        dep_targets = [loader->:DependsOn:->];
        override_targets = [loader->:Overrides:->];
        fallback_targets = [loader->:NoOpFallback:->];

        note = "migrated" if loader.migrated else "still lazy";

        if dep_targets {
            dep = dep_targets[0];
            booted_state = "booted" if dep.booted else "NOT booted";
            return f"{loader.name}: {note}, DependsOn {dep.name} ({booted_state})";
        }
        if override_targets {
            ov = override_targets[0];
            return f"{loader.name}: Overrides -> {ov.name} (test seam)";
        }
        if fallback_targets {
            return f"{loader.name}: {note}, only NoOpFallback wired - masking risk";
        }
        return f"{loader.name}: {note}, no dependency wired";
    }
}

# ---------------------------------------------------------------------------
# Demo wiring
# ---------------------------------------------------------------------------

with entry {
    proc = HarperProcess(pid=4242);
    root ++> proc;

    # The four real MCP loaders from the issue.
    server_utils = McpLoader(name="loadServerUtilities", migrated=True);
    resources    = McpLoader(name="loadResources",       migrated=True);
    req_target   = McpLoader(name="loadRequestTarget",   migrated=True);
    itc_handlers = McpLoader(name="loadItcHandlers",     migrated=False);

    proc ++> server_utils ++> resources ++> req_target ++> itc_handlers;

    # Harper internals they lazily reach.
    server_utilities_mod = HarperModule(name="serverUtilities", booted=True);
    resources_mod        = HarperModule(name="Resources",       booted=True);
    request_target_mod   = HarperModule(name="RequestTarget",   booted=True);
    itc_handlers_mod     = HarperModule(name="serverHandlers",  booted=False);

    # Eager-init typed edges.
    server_utils +>:DependsOn:+> server_utilities_mod;
    resources    +>:DependsOn:+> resources_mod;
    req_target   +>:DependsOn:+> request_target_mod;
    itc_handlers +>:DependsOn:+> itc_handlers_mod;

    # The cycle the issue hints at: Resources and RequestTarget share init.
    resources +>:DependsOn:+> request_target_mod;
    req_target +>:DependsOn:+> resources_mod;

    # A test-seam override that survives migration (genuinely needed).
    itc_handlers +>:Overrides(reason="isolation"):+> itc_handlers_mod;

    # The smell: a loader that ONLY has a silent no-op fallback.
    itc_handlers +>:NoOpFallback(symptom="looks like wiring failure"):+> itc_handlers_mod;

    auditor = LoaderAuditor(started_at="boot");
    root spawn auditor;

    print("---- LoaderAuditor report ----");
    for line in auditor.report {
        print(line);
    }
    print(f"---- total guarded: {len(auditor.guarded)} ----");
    print("---- end ----");
}

