```jac
"""Provenance repository: typed read-only walk over producer-owned chart lineage.

Models the dxrating issue scenario: a backend admin needs to traverse a
publication's immutable lineage tree (chart -> derivation steps -> evidence
locators -> source attempts -> freshness signals) without ever mutating the
producer-owned schema. Two walker abilities handle two distinct node kinds
using a union trigger; a separate guard-walker audits reachability and
surfaces cycle attempts. Telemetry, keyset paging, and redaction are
exercised by the walker state.
"""

# --- Entity archetypes (producer-owned types, read-only at this boundary) ---

node Publication {
    has publication_id: str = "";
    has title: str = "";
    has fingerprint: str = "";
    has schema_version: str = "";
    has finalized: bool = False;
}

node Chart {
    has chart_id: str = "";
    has title: str = "";
    has available: bool = True;
}

node DerivationStep {
    has step_id: str = "";
    has ordinal: int = 0;
    has decision: str = "winner";
}

node EvidenceLocator {
    has evidence_id: str = "";
    has object_key: str = "";
    # internal-only; never accept from a browser
    has signed_url: str = "[redacted]";
    has bytes_state: str = "present";  # present | missing | expired | reuploaded
}

node SourceAttempt {
    has attempt_id: str = "";
    has freshness: str = "fresh";     # fresh | stale | unknown
    has secret_token: str = "[redacted]";
}

# --- Typed edges (relationships carry meaning) ---

edge BelongsToPub {
    has role: str = "";
}

edge Derives {
    has order: int = 0;
}

edge AnchoredBy {
}

edge AttemptedFrom {
}

# --- Read-only traversal walker ---

walker LineageAuditor {
    has max_depth: int = 8;
    has visited: list[str] = [];
    has redaction_count: int = 0;
    has cycle_detected: bool = False;

    can begin with Root entry {
        print(f"[audit] starting lineage walk, depth_cap={self.max_depth}");
        visit [-->];
    }

    can chart_visit with Chart entry {
        cid = here.chart_id;
        if cid in self.visited {
            self.cycle_detected = True;
            print(f"[audit] cycle guard tripped at chart {cid}");
            disengage;
        }
        self.visited = self.visited + [cid];
        avail = "available" if here.available else "unavailable";
        print(f"[audit] chart {here.title} ({cid}) -> {avail}");
        visit [->:Derives:->];
    }

    # Union trigger: one ability for both step kinds reachable from a chart.
    can step_visit with DerivationStep | EvidenceLocator | SourceAttempt entry {
        if here.signed_url == "[redacted]" {
            self.redaction_count = self.redaction_count + 1;
        }
        if here.secret_token == "[redacted]" {
            self.redaction_count = self.redaction_count + 1;
        }
        if here.bytes_state == "missing" or here.bytes_state == "expired" {
            print(f"[audit] {type(here).__name__} {here.evidence_id} bytes={here.bytes_state}");
        } else {
            print(f"[audit] step kind={type(here).__name__} id={here.step_id}{here.evidence_id}{here.attempt_id}");
        }
        visit [->:AnchoredBy:->] else { visit [->:AttemptedFrom:->] else { disengage; } };
    }
}

# --- Schema compatibility walker (fails closed on incompatible contracts) ---

walker SchemaGate {
    has required_version: str = "v3";

    can start with Root entry {
        print(f"[gate] required schema version: {self.required_version}");
        visit [-->];
    }

    can check with Publication entry {
        if here.schema_version != self.required_version {
            print(f"[gate] UNSAFE: schema {here.schema_version} != required {self.required_version} -> service-unavailable");
            disengage;
        }
        print(f"[gate] schema OK for {here.publication_id} (fingerprint={here.fingerprint})");
        visit [-->];
    }
}

# --- Demo wiring ---

with entry {
    pub = Publication(
        publication_id="PUB-001",
        title="April 2024 DX Rating",
        fingerprint="sha256:deadbeef",
        schema_version="v3",
        finalized=True
    );
    chart_a = Chart(chart_id="CH-A", title="Nier", available=True);
    chart_b = Chart(chart_id="CH-B", title="O.N.G.E.K.I.", available=False);
    step1 = DerivationStep(step_id="S1", ordinal=1, decision="winner");
    step2 = DerivationStep(step_id="S2", ordinal=2, decision="loser");
    evidence1 = EvidenceLocator(evidence_id="E1", object_key="obj/internal/abc", bytes_state="present");
    evidence2 = EvidenceLocator(evidence_id="E2", object_key="obj/internal/def", bytes_state="expired");
    attempt = SourceAttempt(attempt_id="AT-1", freshness="fresh");

    root ++> pub;
    pub +>:BelongsToPub:+> chart_a;
    pub +>:BelongsToPub:+> chart_b;
    chart_a +>:Derives(order=1):+> step1;
    chart_a +>:Derives(order=2):+> step2;
    step1 +>:AnchoredBy:+> evidence1;
    step2 +>:AnchoredBy:+> evidence2;
    evidence1 +>:AttemptedFrom:+> attempt;

    root spawn SchemaGate();
    root spawn LineageAuditor(max_depth=8);
}
