        visit [-->];
    }

    can find_js_dep with JsDep entry {
        if here.uses_trust_lockfile {
            self.js_broken_flag.append(here.package);
            print(f"  [JS BAD FLAG] {here.package} invoked --trust-lockfile (unknown pnpm option)");
        }
        visit [-->];
