    can inspect_app with BackendApp entry {
        if self.py_missing {
            print(f"  [BLOCK] {here.module_name} cannot import: {self.py_missing}");
        }
        if self.js_broken_flag {
            print(f"  [BLOCK] {here.module_name} vitest: not found (pnpm install aborted)");
        }
        visit [-->];
    }
}

