"""Tilt-series re-run: per-TS top-up across a pipeline of jobs.

Models the core scenario from the issue: a tilt-series fails to align in
one job, the job still exits SUCCESS, and the failed TS is silently dropped
from the downstream manifest. A walker traverses the job chain and reports
which TS are reachable, which are missing, and which are eligible for a
targeted re-run.
"""

node TiltSeries {
    has name: str = "";
    has status: str = "UNKNOWN";   # OK, FAILED, DROPPED
    has muted: bool = False;
    has task_marker: str = "";     # .ok / .fail / .skip file
}

node Job {
    has job_id: str = "";
    has job_type: str = "";
    has exit_status: str = "PENDING";  # SUCCESS / FAILED
    has expected_count: int = 0;
    has actual_count: int = 0;
}

edge PipelineFlow { }   # forward dependency: job A flows into job B
edge HasSeries   { }    # a job owns a tilt-series record

walker ManifestAuditor {
    has seen: list[str] = [];
    has missing: list[str] = [];
    has eligible: list[str] = [];
    has depth: int = 0;
    has max_depth: int = 8;

    can start with Root entry {
        visit [-->];
    }

    can audit_job with Job entry {
        marker = f"{here.job_id}:{here.job_type}:exit={here.exit_status}";
        if marker in self.seen {
            disengage;
        }
        self.seen = self.seen + [marker];
        if len(self.seen) > self.max_depth {
            disengage;
        }
        gap = here.expected_count - here.actual_count;
        if here.exit_status == "SUCCESS" and gap > 0 {
            report = f"{here.job_id} ({here.job_type}) exited SUCCESS but produced {here.actual_count}/{here.expected_count} TS";
        } else {
            report = f"{here.job_id} ({here.job_type}) {here.exit_status} {here.actual_count}/{here.expected_count}";
        }
        print(report);
        visit [->:PipelineFlow:->];
    }

    can audit_series with TiltSeries entry {
        if here.name in self.seen {
            disengage;
        }
        self.seen = self.seen + [here.name];
        if here.status == "DROPPED" {
            self.missing = self.missing + [here.name];
            self.eligible = self.eligible + [here.name];
            print(f"  ! {here.name} was silently dropped — eligible for targeted re-run");
        } elif here.status == "FAILED" {
            if not here.muted {
                self.eligible = self.eligible + [here.name];
                print(f"  ~ {here.name} failed (marker={here.task_marker}) — eligible for retry");
            } else {
