"""Per-TS top-up: re-run one tilt-series without recomputing the whole job.

Models the crboost_server issue where a tilt-series that fails one stage
(alignment) is silently dropped from downstream manifests, and only a
targeted re-run can bring it back. Two central entities:

  - JobNode: a stage in the pipeline (alignment, ctf, ...).
  - TiltSeries: a per-tilt-series record with status.

The job's `results.ok` set is the *emitted manifest* — downstream jobs
derive their inputs from it. A TS in `failed` is no longer a candidate;
the only way it returns to the chain is via a targeted top-up run on the
failing job. The walker below reproduces that flow.
"""

node TiltSeries {
    has name: str = "";
    has status: str = "pending";   # ok | failed | missing
}

node JobNode {
    has job_type: str = "";
    has exit_status: str = "SUCCESS";   # SUCCESS | FAILED
    has ok: list[str] = [];             # emitted manifest
    has failed: list[str] = [];         # failed but recorded
    has missing: list[str] = [];        # absent from manifest
}

edge RunsOn { has order: int = 0; }
edge Emits { }

walker TopUp {
    has target_ts: str = "";
    has recovered: bool = False;
    has visited_jobs: list[str] = [];

    can start with Root entry {
        print(f"=== Top-up requested for TS '{self.target_ts}' ===");
        visit [-->];
    }

    can plan with JobNode entry {
        self.visited_jobs.append(here.job_type);
        print(f"  visiting job '{here.job_type}' "
              f"(exit={here.exit_status}, "
              f"ok={here.ok}, failed={here.failed})");

        # Policy from drivers/ts_alignment.py: only a *total* wipeout
        # (nothing aligned) is fatal. Partial success is normal.
        if here.ok == [] and here.failed != [] {
            print(f"    FATAL: total wipeout at '{here.job_type}'; "
                  f"cannot top-up");
            disengage;
        }

        # Targeted re-run only fires when the TS is in `failed` here
        # — i.e. it was emitted as failing-but-recorded by this stage.
        # If it was silently dropped (not even in `failed`), the only
        # way to surface it is via this walker's pre-pass that re-runs
        # the upstream stage that still knows the TS name.
        if self.target_ts in here.failed {
            print(f"    [TOP-UP] re-aligning '{self.target_ts}' "
                  f"in job '{here.job_type}'");
            here.failed = [n for n in here.failed if n != self.target_ts];
            here.ok = here.ok + [self.target_ts];
            self.recovered = True;
            disengage;
        }

        # Dead-end: nothing left to follow for this branch.
        visit [->:RunsOn:->] else {
            disengage;
        }
    }
}

walker AuditManifest {
    has seen_ts: list[str] = [];

    can start with Root entry {
        print("=== Auditing emitted manifests ===");
        visit [-->];
    }

    can read with JobNode entry {
        print(f"  job '{here.job_type}' emits: {here.ok}");
        for ts_name in here.ok {
            self.seen_ts.append(ts_name);
        }
        visit [-->];
    }
}

with entry {
    # Build the chain: alignment (job004-like) -> ctf (job005-like).
    alignment = JobNode(
        job_type="tsAlignment",
        exit_status="SUCCESS",
        ok=["Position_1_1", "Position_1_2", "Position_1_4",
            "Position_1_5", "Position_1_6"],
        failed=["Position_1_3"],   # failed but recorded
        missing=[]
    );
    ctf = JobNode(
        job_type="tsCtf",
        exit_status="SUCCESS",
        ok=["Position_1_1", "Position_1_2", "Position_1_4",
            "Position_1_5", "Position_1_6"],
        failed=[],
        missing=[]   # Position_1_3 absent — silently dropped
    );

    root +>:RunsOn(order=1):+> alignment;
    alignment +>:RunsOn(order=2):+> ctf;

    # First, show the gap: Position_1_3 is missing from ctf's manifest.
    AuditManifest() spawn root;

    # Now perform the targeted top-up: re-run only Position_1_3.
    topup = TopUp(target_ts="Position_1_3");
    topup spawn root;

    print(f"recovered={topup.recovered}, "
          f"visited={topup.visited_jobs}");
    print(f"alignment.ok now = {alignment.ok}");
    print(f"ctf.ok still    = {ctf.ok}  (top-up must propagate downstream)");
}

