```jac
"""Dependency and provenance views using typed edges and cycle-safe walkers."""

node ModelObject {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has kind: str = "";
    has context: str = "";

    def usage_label() -> str {
        return f"{self.kind}: {self.title} ({self.context})";
    }
}

node Measure(ModelObject) {
    has expression: str = "";
}

node Column(ModelObject) {
    has data_type: str = "";
}

node ReportBinding(ModelObject) {
    has report: str = "";
    has page: str = "";
    has location: str = "";
}

edge Focus { }

edge Uses {
    has provenance: str = "";
}

walker ForwardDependencies {
    has seen: list[str] = [];

    can start with Root entry {
        print("Forward dependencies:");
        visit [->:Focus:->] else {
            disengage;
        }
    }

    can inspect with Measure | Column | ReportBinding entry {
        if here.title in self.seen {
            print(f"cycle ignored at {here.usage_label()}");
            disengage;
        }

        self.seen.append(here.title);
        print(f"reads {here.usage_label()}");
        visit [->:Uses:->] else {
            disengage;
        }
    }
}

walker ReverseConsumers {
    has seen: list[str] = [];

    can start with Root entry {
        print("Reverse consumers:");
        visit [->:Focus:->] else {
            disengage;
        }
    }

    can inspect with Measure | Column | ReportBinding entry {
        if here.title in self.seen {
            print(f"cycle ignored at {here.usage_label()}");
            disengage;
        }

        self.seen.append(here.title);
        print(f"used by {here.usage_label()}");
        visit [<--:Uses:--] else {
            disengage;
        }
    }
