"""Threaded comments with depth limit and cascade invalidation.

Models the issue's concern: recursion over parent/child comment chains
is hand-rolled, and replies beyond a small depth should be capped (Reddit
"Load More" style). We use typed edges for the reply relationship and a
walker that enforces the depth policy while walking the reply forest.
"""

node Article {
    has title: str = "";
}

node Comment {
    has author: str = "";
    has body: str = "";
    has depth: int = 0;
    has open: bool = True;
}

edge ReplyTo {
    has order: int = 0;
}

walker ReplyCrawler {
    has max_depth: int = 2;
    has visited: list[str] = [];
    has report: list[dict] = [];

    can start with Root entry {
        visit [-->];
    }

    can open_article with Article entry {
        print(f"Article: {here.title}");
        print(f"Reply cap depth: {self.max_depth}");
        visit [->:ReplyTo:->];
    }

    can walk_comments with Comment entry {
        key = f"{here.author}:{here.depth}:{id(here)}";
        if key in self.visited {
            disengage;
        }
        self.visited.append(key);

        marker = "+" if here.depth <= self.max_depth else "x";
        state = "open" if here.open else "closed";
        self.report.append({
            "author": here.author,
            "depth": here.depth,
            "state": state,
            "marker": marker
        });
        print(f"  {marker} [d={here.depth} {state}] {here.author}: {here.body}");

        if here.depth < self.max_depth {
            visit [->:ReplyTo:->];
        } else {
            print(f"  -> replies beyond depth {self.max_depth} require 'Load More' page");
        }
    }
}

walker CascadeInvalidator {
    has reason: str = "author edited";
    has touched: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can pick_article with Article entry {
        print(f"Invalidating reply caches for '{here.title}' ({self.reason})");
        visit [->:ReplyTo:->];
    }

    can invalidate with Comment entry {
        if here.open {
            here.open = False;
            self.touched += 1;
            print(f"  closed reply by {here.author} (depth {here.depth})");
        }
        visit [->:ReplyTo:->];
    }
}

