```jac
"""Substrait-to-SQLGlot outbound projection: walk a typed Substrait recipe graph
and emit a governed PostgreSQL SELECT, modeling the VTX2.3 first projection."""

# ---------------------------------------------------------------------------
# Authorities / recipe nodes (Substrait operators as typed archetypes)
# ---------------------------------------------------------------------------
node Plan {
    has label: str = "";
}

node ReadRel {
    has table: str = "";
}

node ProjectRel {
    has output_aliases: list[str] = [];
}

# Source field reference: produced by a ProjectRel, holds the column name.
node FieldRef {
    has column: str = "";
}

# Expression node that wraps another inner expression (e.g. trim(field(x))).
node ExprCall {
    has func: str = "";
    has alias: str = "";
}

# An output column of the projection: a slot the user wants in SELECT.
node OutputSlot {
    has alias: str = "";
}

# ---------------------------------------------------------------------------
# Edge archetypes (typed relationships)
# ---------------------------------------------------------------------------
# Plan -> top-level top-level operators (reads, projects, ...).
edge RootOp { }

# ProjectRel -> its output slot descriptors.
edge ProducesSlot { }

# OutputSlot -> the expression that computes its value.
edge ComputedBy { }

# ExprCall -> the inner expression it wraps (Function(arg)).
edge ArgOf { }

# ExprCall -> a reference to a source column.
edge ReadsColumn { }

# ---------------------------------------------------------------------------
# Walker: project the Substrait recipe into PostgreSQL via SQLGlot-style AST.
# ---------------------------------------------------------------------------
walker SqlProjector {
    has dialect: str = "postgres";
    has lines: list[str] = [];
    has unsupported: list[str] = [];

    can start with Root entry {
        visit [->:RootOp:->];
    }

    # A ReadRel just declares the FROM target.
    can read with ReadRel entry {
        self.lines.append(f"FROM {here.table}");
        visit [-->];
    }

    # A ProjectRel collects its output slots first, then opens SELECT.
    can project with ProjectRel entry {
        self.lines.append(f"SELECT plan[{here.output_aliases}]");
        visit [->:ProducesSlot:->];
    }

    # Each output slot: visit its expression subtree, then print the alias.
    can slot with OutputSlot entry {
        visit [->:ComputedBy:->];
        self.lines.append(f"  AS {here.alias}");
    }

    # ExprCall: render func(arg) where arg is itself a subtree.
    can call with ExprCall entry {
        self.lines.append(f"{here.func}(");
        visit [->:ArgOf:->] else { self.unsupported.append("ExprCall with no arg"); }
        self.lines.append(")");
    }

    # FieldRef: the leaf — a column name.
    can field with FieldRef entry {
        self.lines.append(here.column);
    }

    can done with Root entry {
        rendered = " ".join(self.lines);
        print(f"--- {self.dialect} projection ---");
        print(rendered);
        if self.unsupported {
            print(f"UNSUPPORTED: {self.unsupported}");
        }
    }
}

# ---------------------------------------------------------------------------
# Demo: build the recipe proven by #2598 and project it.
# ---------------------------------------------------------------------------
with entry {
    plan = Plan(label="customers_read_project");
    read = ReadRel(table="customers");
    proj = ProjectRel(output_aliases=["customer_name", "email", "country"]);

    # Output slots with aliases.
    s1 = OutputSlot(alias="customer_name");
    s2 = OutputSlot(alias="email");
    s3 = OutputSlot(alias="country");

    # Expressions for each slot.
    # customer_name = upper(trim(name))
    upper = ExprCall(func="upper", alias="customer_name");
    trim = ExprCall(func="trim", alias="trim");
    name_ref = FieldRef(column="name");
    email_ref = FieldRef(column="email");
    country_ref = FieldRef(column="country");

    # Wire the recipe graph using typed edges.
    plan +>:RootOp:+> read;
    plan +>:RootOp:+> proj;

    proj +>:ProducesSlot:+> s1;
    proj +>:ProducesSlot:+> s2;
    proj +>:ProducesSlot:+> s3;

    s1 +>:ComputedBy:+> upper;
    s2 +>:ComputedBy:+> email_ref;
    s3 +>:ComputedBy:+> country_ref;

    upper +>:ArgOf:+> trim;
    trim +>:ArgOf:+> name_ref;

    root ++> plan;

    projector = SqlProjector(dialect="postgres");
    root spawn projector;
}
