```jac
"""Fleet MDM Windows profile failure surfacing + dismiss demo.

Models the host -> Windows profiles graph and the failed-remove rows
that admins need to (1) see on the OS settings tab and (2) dismiss
once they have investigated. The walker traverses failed-removal rows
along a typed Removes edge, marks them dismissed, and prunes the
edges (cascade cleanup) — exactly the operation the Fleet issue
#50525 is asking for.
"""

node Host {
    has hostname: str = "";
}

node WindowsProfile {
    has profile_id: str = "";
    has name: str = "";
    has operation_type: str = "remove";
}

node FailedRemoval {
    has detail: str = "";
    has status: str = "failed";
    has dismissed: bool = False;
}

edge OwnsProfile {}

edge Removes {
    has attempted_at: str = "";
}

walker SurfaceFailed {
    has report: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can survey with Host entry {
        visit [->:OwnsProfile:->];
    }

    can find_failures with WindowsProfile entry {
        visit [->:Removes:->];
    }

    can collect with FailedRemoval entry {
        if not here.dismissed {
            entry = f"[FAILED] {here.detail} | status={here.status}";
            self.report.append(entry);
        }
        visit [-->];
    }
}

walker DismissFailed {
    has target_detail: str = "";
    has cleared: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can walk_host with Host entry {
        visit [->:OwnsProfile:->];
    }

    can walk_profile with WindowsProfile entry {
        visit [->:Removes:->];
    }

    can dismiss with FailedRemoval entry {
        if not here.dismissed and (self.target_detail == "" or here.detail == self.target_detail) {
            here.dismissed = True;
            self.cleared += 1;
        }
        visit [-->];
    }
}

with entry {
