```jac
"""Quantum threat modeler: Grover impact analysis over a graph of crypto components.

This module models a tiny quantum-threat knowledge base as a graph of
crypto component nodes connected by typed edges that express "uses",
"protects", and "is-analyzed-by" relationships. A walker traverses the
graph, classifies each component's effective security under Grover's
quadratic speedup, and emits a per-component upgrade recommendation.
"""

# ----------------------------------------------------------------------
# Core node archetypes
# ----------------------------------------------------------------------

node Component {
    has name: str = "";
    has kind: str = "";
    has classical_bits: int = 0;
    has effective_bits: int = 0;
    has recommendation: str = "";

    def apply_grover() -> None {
        # Quadratic speedup halves the bit security (floor).
        self.effective_bits = self.classical_bits // 2;
    }
}

# Convenience: an analyzed component is one whose Grover impact report
# has already been computed by the walker.

# ----------------------------------------------------------------------
# Typed edge archetypes
# ----------------------------------------------------------------------

# "uses" — a system depends on this primitive.
edge Uses { has purpose: str = ""; }

# "protects" — a recommendation/protection relationship from the
# recommended primitive to a vulnerable one.
edge Protects { has rationale: str = ""; }

# "analyzes" — the walker (analysis pass) tags the component as audited.
edge Analyzes { has run_id: str = ""; }

# ----------------------------------------------------------------------
# Walker: traverse the graph, run the Grover report, recommend upgrades
# ----------------------------------------------------------------------

walker Auditor {
    has run_id: str = "grover-1";
    has visited: list = [];

    can start with Root entry {
        # Enter the catalog from the root and walk typed `Uses` edges.
        self.visited = [];
        visit [->:Uses:->];
    }

    can audit with Component entry {
        # Cycle policy: walkers don't dedupe in jac 0.36, so guard here.
        if here.name in self.visited {
            disengage;
        }
        self.visited.append(here.name);

        here.apply_grover();

        # Classify the effective bit strength and recommend an upgrade.
        verdict = "SAFE";
        rec = "no change";
        if here.kind == "symmetric" {
            if here.effective_bits < 128 {
                verdict = "VULNERABLE";
                rec = "upgrade to AES-256";
            } elif here.effective_bits == 128 {
                verdict = "MARGINAL";
                rec = "consider AES-256";
            }
        } elif here.kind == "hash" {
            if here.effective_bits < 128 {
                verdict = "VULNERABLE";
                rec = "upgrade to SHA-384+";
            } elif here.effective_bits < 192 {
                verdict = "MARGINAL";
                rec = "consider SHA-384";
            }
        } elif here.kind == "hmac" {
            if here.effective_bits < 128 {
                verdict = "VULNERABLE";
                rec = "use 256-bit keys";
            } else {
                verdict = "SAFE";
                rec = "key length OK";
            }
        }

        here.recommendation = f"{verdict} -> {rec}";

        # Stamp the audit edge from current component back to the
        # walker (as a typed graph mark) by recording on `here`.
        print(
            f"[{here.kind}] {here.name}: classical={here.classical_bits}"
            f" -> effective={here.effective_bits}"
            f" | {here.recommendation}"
        );

        # Continue traversal across "uses" and "protects" edges.
        visit [->:Uses:->];
        visit [->:Protects:->];
    }
}

# ----------------------------------------------------------------------
# Demonstration graph
# ----------------------------------------------------------------------

with entry {
    # Symmetric primitives
    aes128 = Component(name="AES-128", kind="symmetric", classical_bits=128);
    aes192 = Component(name="AES-192", kind="symmetric", classical_bits=192);
    aes256 = Component(name="AES-256", kind="symmetric", classical_bits=256);

    # Hash primitives
    sha256 = Component(name="SHA-256", kind="hash", classical_bits=256);
    sha384 = Component(name="SHA-384", kind="hash", classical_bits=384);
    sha512 = Component(name="SHA-512", kind="hash", classical_bits=512);

    # HMAC constructions
    hmac_sha256 = Component(name="HMAC-SHA256", kind="hmac", classical_bits=256);
    hmac_sha512 = Component(name="HMAC-SHA512", kind="hmac", classical_bits=512);

    # Wire the catalog: the root "system" uses a mix of components,
    # and explicit `Protects` edges encode the upgrade recommendations.
    root +>:Uses(purpose="encryption"):+> aes128;
    root +>:Uses(purpose="encryption"):+> aes192;
    root +>:Uses(purpose="encryption"):+> aes256;

    root +>:Uses(purpose="hashing"):+> sha256;
    root +>:Uses(purpose="hashing"):+> sha384;
    root +>:Uses(purpose="hashing"):+> sha512;

    root +>:Uses(purpose="authentication"):+> hmac_sha256;
    root +>:Uses(purpose="authentication"):+> hmac_sha512;

    # Upgrade recommendations: AES-256 protects against AES-128's
    # weakness; SHA-384 protects against SHA-256's marginality.
    aes256 +>:Protects(rationale="AES-128 effective < 128 bits"):+> aes128;
    sha384 +>:Protects(rationale="SHA-256 effective < 192 bits"):+> sha256;

    # Spawn the auditor on the root; it walks Uses and Protects edges.
    Auditor(run_id="grover-pass-1") spawn root;
}
