Task:
A maintainer on the project jsenecal/netbox-wdm (unknown) filed this issue about hand-rolled graph machinery causing pain:

Issue #70: [Feature]: Impact/blast-radius query for device and module failure

### Problem statement

Wavelength paths are auto-traced and persisted, and the cable detail panel already answers "what rides on this cable." But there's no equivalent for equipment failure: "which wavelength paths and circuits are affected if this device (or this module/card) fails?" Today that requires iterating every wavelength path client-side and checking membership.

### Proposed solution

An impact endpoint on nodes and modules, e.g. `GET /api/plugins/wdm/wdm-nodes/{id}/impact/` (and a module equivalent), returning affected `WdmWavelengthPath`s and their `WdmCircuit`s. The data is already in `WdmWavelengthPathChannel` — this is aggregation, not new tracing.

### Alternatives considered

Client-side iteration over the wavelength-paths API (works, but N+1 and easy to get wrong). A UI-only panel (API access is the primary need for tooling integration).

### Additional context

Impact analysis was rated critical by several DWDM working group respondents. On-call engineers want blast radius for a failed DWDM card without leaving their tooling. Happy to collaborate on the API shape or contribute a PR.

Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.

```jac
"""DWDM blast-radius impact query.

Models the essential scenario from issue #70: when a device or module
fails, which wavelength paths (and the circuits that ride them) are
affected? Hand-rolled client-side iteration over every wavelength path
is replaced by a typed-edge walker that does the aggregation natively.

Graph shape
-----------
    WdmNode (device)
      +>:Hosts:+>
        WdmModule (line card)
          +>:Carries:+>
            WdmWavelengthPathChannel
              +>:BelongsTo:+>
                WdmWavelengthPath
                  +>:CarriesCircuit:+>
                    WdmCircuit
"""

node WdmNode {
    has name: str = "";
    has site: str = "";
}

node WdmModule {
    has name: str = "";
    has slot: int = 0;
}

node WdmWavelengthPathChannel {
    has channel_id: str = "";
    has frequency_thz: float = 0.0;
}

node WdmWavelengthPath {
    has path_id: str = "";
    has a_end: str = "";
    has z_end: str = "";
}

node WdmCircuit {
    has circuit_id: str = "";
    has customer: str = "";
}

edge Hosts {
    has installed_on: str = "";
}

edge Carries {
    has since: str = "";
}

edge BelongsTo {
    has order: int = 0;
}

edge CarriesCircuit {
    has role: str = "primary";
}

walker ImpactQuery {
    has failed_target: str = "";
    has report: list = [];
    has visited: set = {};

    can start with Root entry {
        visit [-->];
    }

    can inspect_device with WdmNode entry {
        if here.name == self.failed_target {
            print(f"[FAIL] device {here.name} at {here.site} is down");
            self.report.append(("DEVICE", here.name));
            visit [->:Hosts:->];
        } else {
            visit [-->];
        }
    }

    can inspect_module with WdmModule entry {
        if here.name == self.failed_target {
            print(f"[FAIL] module {here.name} (slot {here.slot}) is down");
            self.report.append(("MODULE", here.name));
            visit [->:Carries:->];
        } else {
            visit [-->];
        }
    }

    can collect_channel with WdmWavelengthPathChannel entry {
        if self.failed_target in self.visited {
            disengage;
        }
        self.visited.add(self.failed_target);
        print(f"  -> channel {here.channel_id} @ {here.frequency_thz} THz");
        self.report.append(("CHANNEL", here.channel_id));
        visit [->:BelongsTo:->];
    }

    can collect_path with WdmWavelengthPath entry {
        print(f"  -> wavelength path {here.path_id} ({here.a_end} -> {here.z_end})");
        self.report.append(("PATH", here.path_id));
        visit [->:CarriesCircuit:->];
    }

    can collect_circuit with WdmCircuit entry {
        print(f"  -> circuit {here.circuit_id} for {here.customer}");
        self.report.append(("CIRCUIT", here.circuit_id));
    }

    can ignore_other with WdmWavelengthPathChannel | WdmWavelengthPath | WdmCircuit entry {
        # Fallback for nodes reachable via plain --> walks that we don't
        # care about; just keep moving.
        visit [-->];
    }
}

with entry {
    # Two devices, each hosting a line card with channels riding paths.
    dev_a = WdmNode(name="core-rtr-1", site="NYC");
    dev_b = WdmNode(name="core-rtr-2", site="CHI");
    root ++> dev_a ++> dev_b;

    mod_a1 = WdmModule(name="dwdm-card-a1", slot=3);
    mod_a2 = WdmModule(name="dwdm-card-a2", slot=7);
    dev_a +>:Hosts(installed_on="2023-04-12"):+> mod_a1;
    dev_a +>:Hosts(installed_on="2023-04-12"):+> mod_a2;

    mod_b1 = WdmModule(name="dwdm-card-b1", slot=3);
    dev_b +>:Hosts:+> mod_b1;

    ch_a1a = WdmWavelengthPathChannel(channel_id="ch-1A", frequency_thz=191.35);
    ch_a1b = WdmWavelengthPathChannel(channel_id="ch-1B", frequency_thz=191.40);
    ch_a2a = WdmWavelengthPathChannel(channel_id="ch-2A", frequency_thz=191.45);
    ch_b1a = WdmWavelengthPathChannel(channel_id="ch-1A", frequency_thz=191.35);
    mod_a1 +>:Carries:+> ch_a1a;
    mod_a1 +>:Carries:+> ch_a1b;
