    ch_a2a +>:BelongsTo(order=1):+> wp_beta;
    ch_b1a +>:BelongsTo(order=2):+> wp_alpha;

    ckt_acme = WdmCircuit(circuit_id="CKT-ACME-100G", customer="ACME");
