Task:
Audit a rental shop's media shelf: books are shelved showing title and author, DVDs show title and runtime, and anything unclassified (like an old archive reel) falls through to default handling. Count total items audited and how many needed the default path.

```jac
"""Rental shop shelf audit.

Books and DVDs each have a typed ability that fires for their kind.
Anything else (e.g. an unclassified archive reel) falls through to a
default union ability and is counted separately.
"""

node Book {
    has title: str = "";
    has author: str = "";
    has year: int = 0;
    has available: bool = True;
}

node DVD {
    has title: str = "";
    has runtime: int = 0;
    has available: bool = True;
}

node ArchiveReel {
    has label: str = "";
    has year: int = 0;
    has available: bool = True;
}

# Base node so a single union ability can touch the common payload.
node Media {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;

    def media_title() -> str;
    def media_year() -> int;
}

# A common base lets the default path handle anything unclassified
# (e.g. ArchiveReel) without per-type branching in the walker.

walker Auditor {
    has total: int = 0;
    has defaulted: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can shelf_book with Book entry {
        self.total += 1;
        print(f"Book: '{here.title}' by {here.author} ({here.year})");
        visit [-->];
    }

    can shelf_dvd with DVD entry {
        self.total += 1;
        print(f"DVD: '{here.title}', {here.runtime} min ({here.year})");
        visit [-->];
    }

    # Default path: anything not matched as Book or DVD lands here.
    can shelve_other with ArchiveReel | Media entry {
        self.total += 1;
        self.defaulted += 1;
        print(f"[default] '{here.title}' ({here.year}) — unclassified");
        visit [-->];
    }
}

