Task:
I'm modeling a vending machine controller for a hardware simulator. It has states like idle, waiting, and vend, and inputs like inserting a coin or pressing a button move it between them. I'd like to feed in a sequence of inputs and print which state we end in, following the matching transition for each input step by step.

```jac
"""Vending machine controller: model states as nodes and feed a sequence of inputs as a walker."""

node VendingState {
    has name: str = "";
    has accepting: bool = True;
    has dispensing: bool = False;
}

walker VendingMachine {
    has inputs: list[str] = [];
    has step: int = 0;

    can start with Root entry {
        print(f"Starting from {here.name}");
        visit [-->];
    }

    can step_input with VendingState entry {
        if self.step >= len(self.inputs) {
            print(f"No more inputs; resting in {here.name}");
            disengage;
        }
        incoming = self.inputs[self.step];
        self.step += 1;
        next_node = [-->];
        picked: object = None;
        for child in next_node {
            label = child.name;
            if label == incoming {
                picked = child;
            }
        }
        if picked is None {
            print(f"[{here.name}] no transition for input '{incoming}'; halting");
            disengage;
        }
        print(f"[{here.name}] --{incoming}--> {picked.name}");
        visit [picked];
    }
}

with entry {
    idle = VendingState(name="idle", accepting=True);
    waiting = VendingState(name="waiting", accepting=True);
    vend = VendingState(name="vend", accepting=False, dispensing=True);
    error = VendingState(name="error", accepting=False);

    root ++> idle ++> waiting ++> vend;
    idle ++> error;
    waiting ++> error;

    sequence = ["coin", "select", "dispense", "coin"];
    controller = VendingMachine(inputs=sequence);
    root spawn controller;

    print(f"Final state after sequence: {sequence}");
}
