        incoming: str = self.inputs[self.step];
        self.step += 1;
        picked: VendingState | None = None;
        for child in [-->] {
            if isinstance(child, VendingState) and child.name == incoming {
                picked = child;
            }
        }
        if picked is None {
            print(f"[{here.name}] no transition for input '{incoming}'; halting");
            disengage;
        }
        print(f"[{here.name}] --{incoming}--> {picked.name}");
        visit [picked];
    }
}

with entry {
    idle = VendingState(name="idle", accepting=True);
    waiting = VendingState(name="waiting", accepting=True);
    vend = VendingState(name="vend", accepting=False, dispensing=True);
    error = VendingState(name="error", accepting=False);

    root ++> idle ++> waiting ++> vend;
    idle ++> error;
    waiting ++> error;

    sequence = ["coin", "select", "dispense", "coin"];
    controller = VendingMachine(inputs=sequence);
    root spawn controller;

    print(f"Final state after sequence: {sequence}");
}

