}

edge SocialLink {
    has edge_type: str = "";
}

walker SocialProofWalker {
    has candidate_title: str = "";
    has anchor_title: str = "";
    has edge_verbs: dict[str, str] = {};
    has seen_titles: list[str] = [];
    has steps: list[SocialProofStep] = [];
    has description: str = "";
    has previous_node: GraphEntity | None = None;
    has previous_title: str = "";
    has stopped_on_cycle: bool = False;
    has confidence: float = 0.85;

