            self.description = self.description + " -> [...]";
            self.stopped_on_cycle = True;
            disengage;
        }

        self.seen_titles.append(here.title);
        if self.anchor_title == "" {
            self.anchor_title = here.title;
        }

        if here.title == self.candidate_title {
