        print("Anchor=" + self.anchor_title + ", Candidate=" + self.candidate_title);
        print("Steps=" + str(len(self.steps)));
        print("Confidence=" + str(self.confidence));

        for step in self.steps {
            print(step.source_title + " --[" + step.edge_type + "/" + step.verb + "]--> " + step.target_title);
        }

        if self.stopped_on_cycle {
            print("Cycle policy: truncated with [...]");
        }
    }
}

