"""LIRE (Local Incremental Rebalancing) for vector index clusters.

Models the essential scenario from apache/hudi issue #19500: after Tier-1
vector compaction, local cluster geometry drifts and must be rebalanced.
LIRE evaluates ClusterStats triggers, splits oversized clusters via local
balanced 2-means, merges undersized ones into surviving centroids, and
publishes replacement centroids/postings/tombstones in one MDT delta
commit.  Cache identity is keyed by index partition + generation + pinned
MDT instant; no centroid epoch is persisted.
"""

node Cluster {
    has cluster_id: str = "";
    has centroid: list[float] = [0.0, 0.0];
    has size: int = 0;
    has residual_budget: int = 64;
}

node Vector {
    has vector_id: str = "";
    has coords: list[float] = [0.0, 0.0];
}

node Replacement {
    has replacement_id: str = "";
    has source_id: str = "";
    has centroid: list[float] = [0.0, 0.0];
}

node Tombstone {
    has victim_id: str = "";
    has reason: str = "";
}

node ClusterStats {
    has split_threshold: int = 0;
    has merge_threshold: int = 0;
    has skew: float = 0.0;
    has mismatches: int = 0;
}

node IndexPartition {
    has partition_name: str = "";
    has generation: int = 0;
    has pinned_instant: str = "";
}

edge TouchedByMaintenance { has op: str = ""; }
edge Owns { }
edge ReplacedBy { }
edge Surfaces { }

walker LireRebalancer {
    has op_label: str = "maintenance";
    has visited: list[str] = [];
    has rebalances: int = 0;
    has splits: int = 0;
    has merges: int = 0;
    has mismatches: int = 0;

    can start with Root entry {
        print("== LIRE rebalance pass ==");
        visit [-->];
    }

    can inspect_partition with IndexPartition entry {
        print(
            f"partition={here.partition_name} gen={here.generation} "
            f"pinned={here.pinned_instant}"
        );
        visit [-->];
    }

    can collect_stats with ClusterStats entry {
        here.skew = 1.7;
        here.split_threshold = 8;
        here.merge_threshold = 2;
        print(
            f"ClusterStats skew={here.skew} "
            f"split>={here.split_threshold} merge<{here.merge_threshold}"
        );
        visit [-->];
    }

    can consider_cluster with Cluster entry {
        if here.cluster_id in self.visited {
            visit [-->];
            return;
        }
        self.visited.append(here.cluster_id);

        if here.size >= 8 {
            self.splits += 1;
            self.rebalances += 1;
            tag = "SPLIT";
        } elif here.size <= 2 and here.size > 0 {
            self.merges += 1;
            self.rebalances += 1;
            tag = "MERGE";
        } else {
            tag = "KEEP";
        }
        print(f"cluster={here.cluster_id} size={here.size} -> {tag}");
        visit [-->];
    }

    can observe_replacement with Replacement entry {
        here.centroid = [-3.0, -3.0];
        print(
            f"  replacement={here.replacement_id} "
            f"src={here.source_id} centroid={here.centroid}"
        );
        visit [-->];
    }

    can observe_tombstone with Tombstone entry {
        print(
            f"  tombstone victim={here.victim_id} reason={here.reason}"
        );
        visit [-->];
    }
}

walker MismatchObserver {
    has report: dict[str, int] = {};

    can start with Root entry {
        visit [-->];
    }

    can inspect_stats with ClusterStats entry {
        here.mismatches = 4;
        self.report["mismatches"] = here.mismatches;
        print(
            f"coarse-routing mismatches={here.mismatches} "
            f"-> trigger rebuild"
        );
    }
}

with entry {
    part = IndexPartition(
        partition_name="vec-part-0", generation=3, pinned_instant="mdt-20240501"
    );
    stats = ClusterStats();
    big = Cluster(cluster_id="C-big", size=11, centroid=[9.0, 9.0]);
    mid = Cluster(cluster_id="C-mid", size=5, centroid=[0.0, 0.0]);
    small = Cluster(
        cluster_id="C-small", size=1, centroid=[7.0, -2.0]
    );

    rep_big = Replacement(
        replacement_id="C-big-A", source_id="C-big", centroid=[9.0, 9.0]
    );
    rep_big_b = Replacement(
        replacement_id="C-big-B", source_id="C-big", centroid=[10.0, 10.0]
    );
    tomb_big = Tombstone(victim_id="C-big", reason="split-replaced");

    rep_small = Replacement(
        replacement_id="C-mid-merge", source_id="C-small",
        centroid=[0.0, 0.0]
    );
    tomb_small = Tombstone(victim_id="C-small", reason="merge-absorbed");

    root +>:TouchedByMaintenance(op="compaction"):+> part;
    part +>:Surfaces:+> stats;
    part +>:Owns:+> big;
    part +>:Owns:+> mid;
    part +>:Owns:+> small;

    big +>:ReplacedBy:+> rep_big;
    big +>:ReplacedBy:+> rep_big_b;
    rep_big +>:Surfaces:+> tomb_big;
    rep_big_b +>:Surfaces:+> tomb_big;

    small +>:ReplacedBy:+> rep_small;
    rep_small +>:Surfaces:+> tomb_small;

    rebalancer = LireRebalancer();
    root spawn rebalancer;
    print(
        f"rebalances={rebalancer.rebalances} "
        f"splits={rebalancer.splits} merges={rebalancer.merges}"
    );

    observer = MismatchObserver();
    root spawn observer;
    print(f"mismatch_report={observer.report}");
}
```

