Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.

```jac
"""Wayfinder: skill-aware Agent fleet control plane (idiomatic OSP model).

Models the core scenario from issue #267:
- A replaceable Controller issues Delegation Contracts to child Agents.
- Each child is bound by task/attempt lineage, goals, snapshot identity,
  skill/tool grants, effects, and resource/recursion limits.
- Workers execute inside those contracts and emit skill-use attestations.
- The Controller arbitrates evidence: results are accepted only when the
  required attestations verify; cache reuse may stand in for admissible
  evidence but never replaces fresh skill/tool activation.
- Cache entries can become stale; stale cache is acceleration, never
  authority, so it must be invalidated before authority is granted.
- High-risk conflicts freeze only the affected branch (subtree isolation).
- Recursion is bounded; cycles in the delegation graph are a domain error
  and the walker disengages on detection.
"""

# ---------- Entity archetypes ----------

node Skill {
    has name: str = "";
    has version: str = "0.0.0";
    has local_only: bool = False;
}

node Evidence {
    has kind: str = "";            # "skill_use", "tool_call", "cache_hit"
    has source: str = "";          # which skill/tool produced it
    has verified: bool = False;
}

node Agent {
    has badge: str = "";
    has depth_budget: int = 0;
    has spent_depth: int = 0;
    has status: str = "idle";      # idle | running | blocked | frozen | done
}

# ---------- Typed edges ----------

# Delegation Contract issued by a Controller to a child Agent.
edge Delegates {
    has goal: str = "";
    has attempt_id: str = "";
    has snapshot_id: str = "";
    has effects: str = "read";     # read | write | escalate
    has max_depth: int = 3;
}

# Evidence / attestation emitted by an Agent (or a cache adapter) for a skill.
edge Attests {
    has admissible: bool = True;   # cache_hit evidence must be admissible
}

# A Controller freezes a branch on high-risk conflict.
edge Freezes { }

# ---------- Walker ----------

walker FleetController {
    has visited_ids: list[str] = [];
    has accepted: int = 0;
    has rejected: int = 0;
    has frozen: int = 0;
    has cycle_detected: bool = False;

    can begin with Root entry {
        # Walk the delegation tree one step at a time.
        visit [->:Delegates:->] else { disengage; }
    }

    # A single union ability arbitrates an Agent OR a cache-style Evidence
    # node: both produce attestations the Controller must verify. Only the
    # fields shared by every type in the union are touched here.
    can arbitrate with Agent | Evidence entry {
        # ---------- cycle policy (explicit, domain logic) ----------
        # Walker traversal has no built-in dedupe in jac 0.36.x; we carry
        # the lineage explicitly and treat a revisit as a cycle error.
        node_id = f"{here.badge}{here.kind}";
        already = False;
        for vid in self.visited_ids {
            if vid == node_id {
                already = True;
            }
        }
        if already {
            self.cycle_detected = True;
            print(f"[CYCLE] delegation revisits {node_id}; disengaging");
            disengage;
        }
        self.visited_ids.append(node_id);
        # --------------------------------------------------

        # ---------- evidence arbitration ----------
        # An Agent node is accepted only if its attestations verify.
        if here.kind == "agent" {
            if here.spent_depth >= here.depth_budget {
                here.status = "blocked";
                self.rejected += 1;
                print(f"[BLOCK] {here.badge} exhausted depth budget");
                visit [->:Delegates:->] else { disengage; }
            }
            if here.status == "frozen" {
                # Subtree isolation: high-risk conflict freezes only this branch.
                self.frozen += 1;
                print(f"[FROZEN] {here.badge} branch isolated");
                visit [->:Delegates:->] else { disengage; }
            }
            here.status = "running";
        } elif here.kind == "evidence" {
            # Cache reuse is admissible evidence only when it has been
            # re-validated; unverified cache never grants authority.
            if here.source == "cache" and not here.verified {
                self.rejected += 1;
                print(f"[REJECT] stale cache '{here.source}' is not authority");
                visit [->:Attests:->] else { disengage; }
            }
            if here.verified {
                self.accepted += 1;
                print(f"[ACCEPT] {here.kind} from {here.source} verified");
            } else {
                self.rejected += 1;
                print(f"[REJECT] unverified {here.kind} from {here.source}");
            }
        }
        # Continue traversing delegated children and attestations.
        visit [->:Delegates:->] else { visit [->:Attests:->] else { disengage; } };
    }
}

