deactivation across every connected party when a doctor leaves.
"""

node Person {
    has name: str = "";
    has active: bool = True;
}

node Patient(Person) {
    has condition: str = "";
}

node Doctor(Person) {
    has specialty: str = "";

    # Union-trigger ability: when a Patient lands here, both node kinds
    # respond cooperatively through the same ability body.
    can greet with Patient entry {
        if here.active and self.active {
            print(f"Dr. {self.name} ({self.specialty}) sees patient {here.name} for {here.condition}");
        }
    }
}

