    has name: str = "";
    has version: str = "";
    has vulnerable: bool = False;
    has fixed_version: str = "";
    has cve_id: str = "";
}

edge DependsOn {
    has scope: str = "compile";
}

walker SecurityAudit {
    has visited: list[str] = [];
    has fixed_count: int = 0;

    can start with Root entry {
        print("Starting dependency audit from root");
        visit [->:DependsOn:->];
    }

    can traverse with Artifact entry {
        coord = f"{here.group}:{here.name}";
        if coord in self.visited {
            visit [->:DependsOn:->] else { disengage; }
        }
        self.visited.append(coord);
        if here.vulnerable {
            self.fixed_count += 1;
            old_label = here.version;
            here.version = here.fixed_version;
            here.vulnerable = False;
            print(
                f"[FIXED] {coord}: {old_label} -> {here.version} "
                f"(CVE {here.cve_id})"
            );
        } else {
            print(f"[OK] {coord}:{here.version}");
        }
        visit [->:DependsOn:->];
    }

    can summarize with Root entry {
        print(f"Audit complete: {self.fixed_count} vulnerable artifact(s) patched");
    }
}

with entry {
    # Direct dependency chain: app -> spring-boot-starter-web -> spring-webmvc
    app = Artifact(group="com.example", name="app", version="1.0.0");
    starter_web = Artifact(
        group="org.springframework.boot",
        name="spring-boot-starter-web",
        version="3.0.3"
    );
    webmvc = Artifact(
        group="org.springframework",
        name="spring-webmvc",
        version="6.0.5",
        vulnerable=True,
        fixed_version="6.2.18",
        cve_id="CVE-2026-22745"
    );
    # Sibling tree branch under the same starter
    jackson = Artifact(
        group="com.fasterxml.jackson.core",
        name="jackson-databind",
        version="2.15.2"
    );

    root +>:DependsOn:+> app;
    app +>:DependsOn:+> starter_web;
    starter_web +>:DependsOn:+> webmvc;
    starter_web +>:DependsOn:+> jackson;

    root spawn SecurityAudit();
}

