Task:
A maintainer on the project Chris-Wolfgang/IAsyncEnumerable-Extensions (unknown) filed this issue about hand-rolled graph machinery causing pain:

Issue #243: [Maintenance] CI/CD: License audit on transitive dependencies (dotnet-licenses / FOSSA)

## Scope

Dependabot tracks dependency *versions* (and CVE alerts). It does not check the *licenses* of transitive dependencies. A new transitive dependency with an incompatible license (GPL, AGPL, OSL, business-source) silently leaks into a derivative work distributed under MIT — a real procurement / legal exposure for downstream consumers.

The deferred work is a license-audit workflow using `dotnet-licenses` / FOSSA / Snyk Open Source / similar that enumerates every transitive package, captures its declared license, and fails the build on incompatible / unknown licenses.

## Acceptance criteria

- A `license-audit.yaml` workflow runs on PR + scheduled.
- Findings produce a `THIRD-PARTY-NOTICES.md` (or similar) generated automatically per release; license attribution is shipped in the NuGet package per the licenses' requirements.
- A documented allowlist (MIT / Apache-2.0 / BSD-2-Clause / BSD-3-Clause / similar) gates new packages; anything else needs explicit reviewer approval recorded in the PR.
- A baseline scan of the current `main` documents current dependencies + licenses.

## Notes

- Tier-1 follow-up. Required for procurement at most enterprises; goes beyond Dependabot's surface.
- Originated as part of the IAsyncEnumerable-Extensions thorough-review pass; tracked fleet-wide.
- Board: https://github.com/users/Chris-Wolfgang/projects/6

Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.

```jac
"""License audit over a transitive-dependency graph.

Models the issue's core scenario: a project ships under a permissive
license (MIT) but pulls in a tree of transitive dependencies whose
licenses must be audited. A walker performs the traversal that the
issue says is hand-rolled in CI — recursive descent over the
dependency tree, with explicit cycle protection (jac 0.36.1 walkers
have no built-in visited-set), and emits a single audit report that
classifies each package as OK / REVIEW / BLOCKED.

The compatibility façade of plain `def`s preserves the public API
(`add_package`, `add_dep`, `audit`) so callers see the same surface
the hand-rolled version exposed.
"""

# ---- Edge archetypes ----------------------------------------------------

edge DependsOn {
    has version_range: str = "";
}

# ---- Node archetypes ----------------------------------------------------

node Package {
    has name: str = "";
    has version: str = "";
    has license: str = "";
    has origin: str = "transitive";

    def label() -> str {
        return f"{self.name}@{self.version}";
    }

    def license_kind() -> str {
        n = self.license.lower();
        ok_markers = ["mit", "apache-2.0", "bsd-2-clause", "bsd-3-clause", "isc", "mpl-2.0"];
        blocked_markers = ["gpl", "agpl", "osl", "sspl", "bsl", "business-source", "source-available"];
        for m in blocked_markers {
            if n.find(m) != -1 {
                return "blocked";
            }
        }
        for m in ok_markers {
            if n.find(m) != -1 {
                return "ok";
            }
        }
        return "unknown";
    }
}

# A Project is the root artifact whose own license gates the audit.
node Project {
    has name: str = "";
    has license: str = "MIT";
}

# ---- Walker: descends the dependency tree, deduplicating by package ----

walker LicenseAuditor {
    has visited: list[str] = [];
    has report: list[dict] = [];
    has policy_license: str = "MIT";

    can start with Project entry {
        self.policy_license = here.license;
        print(f"Auditing transitive deps of {here.name} (shipped under {here.license})");
        # Walk direct dependencies of the project.
        visit [->:DependsOn:->];
    }

    can descend with Package entry {
        key = here.label();
        # Explicit cycle / repeat guard — walkers do not dedupe on their own.
        if key in self.visited {
            visit [->:DependsOn:->];
            return;
        }
        self.visited.append(key);

        kind = here.license_kind();
        verdict = "OK" if kind == "ok" else ("REVIEW" if kind == "unknown" else "BLOCKED");
        entry = {
            "name": here.name,
            "version": here.version,
            "license": here.license,
            "origin": here.origin,
            "verdict": verdict,
        };
        self.report.append(entry);
        marker = " " if verdict == "OK" else ("?" if verdict == "REVIEW" else "!");
        print(f"  {marker} {here.label()} [{here.license}] -> {verdict}");

        visit [->:DependsOn:->];
    }
}

# ---- Walker: cascades a removal of a blocked package --------------------

walker Invalidate {
    has target: str = "";
    has removed: list[str] = [];

    can start with Project entry {
        visit [->:DependsOn:->];
    }

    can purge with Package entry {
        if here.name == self.target {
            print(f"INVALIDATE: removing {here.label()} (license={here.license})");
            self.removed.append(here.label());
            del here;
            return;
        }
        visit [->:DependsOn:->];
    }
}

# ---- Public-API façade --------------------------------------------------

def add_package(graph_root: Project, name: str, version: str, license: str) -> Package {
    p = Package(name=name, version=version, license=license, origin="transitive");
    graph_root +>:DependsOn(version_range="*") :+> p;
    return p;
}

def add_dep(parent: Package, name: str, version: str, license: str) -> Package {
    p = Package(name=name, version=version, license=license, origin="transitive");
    parent +>:DependsOn(version_range="^" + version) :+> p;
    return p;
}

def audit(graph_root: Project) -> dict {
    auditor = LicenseAuditor();
    graph_root spawn auditor;
    summary = {"ok": 0, "review": 0, "blocked": 0};
    for row in auditor.report {
        v = row["verdict"];
        if v == "OK" {
            summary["ok"] += 1;
        } elif v == "REVIEW" {
            summary["review"] += 1;
        } else {
            summary["blocked"] += 1;
        }
    }
    return {"summary": summary, "findings": auditor.report};
}

def invalidate(graph_root: Project, package_name: str) -> list[str] {
    inv = Invalidate(target=package_name);
    graph_root spawn inv;
    return inv.removed;
}

# ---- Demo ---------------------------------------------------------------

with entry {
    # The shipped project: MIT.
    proj = Project(name="IAsyncEnumerable.Extensions", license="MIT");
    root ++> proj;

    # Direct deps.
    system_text_json = add_package(proj, "System.Text.Json", "8.0.0", "MIT");
    newtonsoft       = add_package(proj, "Newtonsoft.Json",   "13.0.3", "MIT");
    serilog          = add_package(proj, "Serilog",           "3.1.1", "Apache-2.0");

    # Transitive tree under System.Text.Json — mostly clean.
    text_json_buffers = add_dep(system_text_json, "System.Text.Encodings.Web", "8.0.0", "MIT");
    add_dep(text_json_buffers, "System.Memory", "4.5.5", "MIT");
    add_dep(text_json_buffers, "System.Buffers", "4.5.1", "MIT");

    # Transitive tree under Serilog — introduces an unknown license and a blocked one.
    serilog_sinks_file = add_dep(serilog, "Serilog.Sinks.File", "5.0.0", "Apache-2.0");
    add_dep(serilog_sinks_file, "PortableIO", "1.0.2", "MIT");

