Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.

```jac
"""Airflow ECS instance: model OOM cross-contamination across co-resident tasks.

The instance has a small fixed RAM budget (~3.7GiB usable). Four ECS tasks
(scheduler, triggerer, dag-processor, api-server) each reserve a cgroup
memory limit, summing to ~2.5GiB. When any task spikes past its limit the
kernel hard-kills it. Without swap, that pressure spills across to
unrelated tasks on the same host. A sweeper walker audits every task's
allocation against the remaining slack and flags the ones that would
OOM-kill the whole instance if they breached their slice.
"""

node Task {
    has name: str = "";
    has memory_mib: int = 0;
    has oom_kills: int = 0;
}

node Instance {
    has name: str = "";
    has usable_mib: int = 0;
    has reserved_mib: int = 0;
    has swap_mib: int = 0;
}

edge HostedOn { }
edge Blast { has severity: int = 0; }

walker OOMAuditor {
    has findings: list = [];

    can start with Root entry {
        visit [->:HostedOn:->];
    }

    can audit_instance with Instance entry {
        slack = here.usable_mib - here.reserved_mib;
        degraded = "degraded (swap absorbs)" if here.swap_mib > 0 else "hard-killed";
        print(f"[{here.name}] usable={here.usable_mib}MiB reserved={here.reserved_mib}MiB "
              f"slack={slack}MiB swap={here.swap_mib}MiB -> {degraded}");
        visit [->:HostedOn:->];
    }

    can audit_task with Task entry {
        can list: list = [];
        for (neighbor, e) in [->:HostedOn:->] {
            can list.append((neighbor, e));
        }
    }
}

walker PressureSweep {
    can start with Root entry {
        visit [->:HostedOn:->];
    }

    can scan_instance with Instance entry {
        print(f"scanning {here.name}: slack={here.usable_mib - here.reserved_mib}MiB");
        visit [->:HostedOn:->];
    }

    can scan_task with Task entry {
        slack = 0;
        for (neighbor, e) in [->:Blast:->] {
            slack = slack + e.severity;
        }
        risk = "HIGH" if slack > 3 else "ok";
        print(f"  task {here.name} mem={here.memory_mib}MiB oom_kills={here.oom_kills} blast_sum={slack} risk={risk}");
        visit [->:Blast:->];
    }
}

with entry {
    inst = Instance(name="t3.medium", usable_mib=3700, reserved_mib=2500, swap_mib=0);

    scheduler = Task(name="scheduler", memory_mib=900, oom_kills=5);
    triggerer = Task(name="triggerer", memory_mib=400, oom_kills=0);
    dag_proc = Task(name="dag-processor", memory_mib=500, oom_kills=0);
    api = Task(name="api-server", memory_mib=700, oom_kills=3);

    inst +>:HostedOn:+> scheduler;
    inst +>:HostedOn:+> triggerer;
    inst +>:HostedOn:+> dag_proc;
    inst +>:HostedOn:+> api;

    scheduler +>:Blast(severity=2):+> api;
    scheduler +>:Blast(severity=1):+> triggerer;
