Task:
A maintainer on the project temporalio/deputy (Go) filed this issue about hand-rolled graph machinery causing pain:

Issue #97: Composite action recursion has no manifest dedup or work budget, so scan time grows exponentially

In `internal/inventory/plugins/github/actionsx/actions.go`, `parseWorkflow` records visited files via `markVisited` (`:94`), but `parseActionManifest` (`:151`) does not, and there is no global budget on total work. The only bound is `maxRecursionDepth = 8`.

So a composite action whose steps reference the same manifests re-parses them once per path, and the work is `fanout^depth` rather than proportional to the number of files. Measured at depth 9, one `action.yml` per level:

| fanout | time |
| --- | --- |
| 2 | 11 ms |
| 3 | 181 ms |
| 4 | 1.59 s |
| 5 | 8.72 s |

Roughly 8x per increment, from about ten files of a few hundred bytes each. `ctx` is threaded through the recursion but never checked, so a caller's timeout or cancellation does not stop the work once it starts.

This runs wherever Deputy inventories a repository it did not write, which includes `deputy scan` on an arbitrary target and PR CI on a fork's changes.

## Proposal

- Extend the visited set to cover action manifests, not just workflows. A manifest parsed once should not be parsed again within the same extraction, regardless of how many steps reference it. This alone converts the growth from exponential to linear in file count.
- Add a global node/work budget for the extraction, independent of depth, and stop with a partial result plus a warning rather than running to completion.
- Check `ctx.Err()` at each recursion step so cancellation and deadlines take effect.

Worth confirming whether the same shape exists in other recursive extractors while fixing this one.

## Preventing recurrence

- A benchmark or bounded-time test built from a synthetic fan-out fixture, asserting the extraction completes within a fixed budget. A depth-9, fanout-5 fixture is a few hundred bytes and currently takes ~9 seconds, so the assertion is unambiguous.
- The rule worth stating for extractors generally: any traversal over attacker-supplied file structure needs (a) memoization keyed on the resource, (b) a global work budget, and (c) context checks. Depth limits alone do not bound work when the branching factor is attacker-controlled.

Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.

```jac
"""Composite action manifest traversal: exponential work in fanout*depth.

Models the temporalio/deputy issue where parseActionManifest re-parses
the same manifests once per referencing step. A walker descends the
manifest graph via typed Step/Subaction edges; a guard set memoizes
already-parsed manifests so work becomes linear in file count, a
global node budget caps total visited work, and ctx cancellation is
checked at each step. The unsafe walker (without dedup/budget) runs
to the user-imposed depth cap and reports exponential fan-out, while
the safe walker converges quickly with a partial report on budget
exhaustion.
"""

# ---------- nodes ----------

node Manifest {
    has path: str = "";
    has size_bytes: int = 0;
    has parsed: bool = False;
    has visited_count: int = 0;
}

# ---------- typed edges (relationships carry meaning) ----------

edge Step {
    has order: int = 0;
}

edge Subaction {
}

# ---------- base walker context: cancellation + budget + memo ----------

node Ctx {
    has cancelled: bool = False;
    has budget: int = 1000;
    has spent: int = 0;
    has hits: int = 0;
    has misses: int = 0;
    has budget_exhausted: bool = False;

    def check() -> bool {
        if self.spent >= self.budget {
            self.budget_exhausted = True;
            return False;
        }
        if self.cancelled {
            return False;
        }
        self.spent += 1;
        return True;
    }
}

# ---------- unsafe walker: no dedup, no budget, no ctx checks ----------

walker NaiveCrawler {
    has max_depth: int = 4;
    has seen: list[str] = [];
    has depth: int = 0;
    has work: int = 0;

    can start with Root entry {
        print(f"[naive] starting descent to depth {self.max_depth}");
        visit [-->];
    }

    can descend with Manifest entry {
        self.work += 1;
        already_seen = False;
        for s in self.seen {
            if s == here.path {
                already_seen = True;
                break;
            }
        }
        # Naive: still counts the "work" of arriving even if seen,
        # and does NOT short-circuit the recursive expansion.
        report_path = here.path;
        label = "REPARSE" if already_seen else "parse  ";
        print(f"[naive] d={self.depth} {label} {report_path}");
        if self.depth >= self.max_depth {
            return;
        }
        child_depth = self.depth + 1;
        self.depth = child_depth;
        visit [->:Step:->];
        self.depth = child_depth - 1;
    }
}

# ---------- safe walker: guard set + budget + ctx, typed-edge visit ----------

walker SafeCrawler {
    has max_depth: int = 4;
    has depth: int = 0;
    has ctx: Ctx = None;

    can start with Root entry {
        print(f"[safe ] ctx budget={self.ctx.budget}, "
              f"cancelled={self.ctx.cancelled}");
        visit [-->];
    }

    can descend with Manifest entry {
        if not self.ctx.check() {
            reason = "budget" if self.ctx.budget_exhausted else "cancel";
            print(f"[safe ] STOP ({reason}) at d={self.depth} "
                  f"after {self.ctx.spent} work");
            disengage;
        }
        if here.parsed {
            self.ctx.hits += 1;
            print(f"[safe ] d={self.depth} HIT    {here.path} "
                  f"(parse skipped)");
            visit [->:Step:->];
        } else {
            self.ctx.misses += 1;
            here.parsed = True;
            here.visited_count += 1;
            print(f"[safe ] d={self.depth} PARSE  {here.path}");
            if self.depth >= self.max_depth {
                visit [->:Step:->];
            } else {
                child_depth = self.depth + 1;
                self.depth = child_depth;
                visit [->:Step:->];
                self.depth = child_depth - 1;
            }
        }
    }
}

# ---------- demo wiring ----------

with entry {
    # Build a synthetic depth-3, fanout-3 composite action tree:
    # root --> M0, and each manifest references 3 subactions.
    def fanout(parent: Manifest, prefix: str, depth: int) -> None {
        if depth == 0 {
            return;
        }
        for i in range(3) {
            child_path = f"{prefix}/{i}.yml";
            child = Manifest(path=child_path, size_bytes=200);
            parent +>:Step(order=i):+> child;
            fanout(child, child_path, depth - 1);
        }
    }

    root_manifest = Manifest(path="action.yml", size_bytes=300);
    root ++> root_manifest;
    fanout(root_manifest, "action.yml", depth=3);

    print("=== naive (no dedup, no budget) ===");
    naive = NaiveCrawler(max_depth=9);
    root spawn naive;
    print(f"[naive] total parse-arrivals: {naive.work}");

    print("");
    print("=== safe  (typed-edge + memo + budget + ctx) ===");
    ctx = Ctx(budget=120, cancelled=False);
    safe = SafeCrawler(max_depth=99, ctx=ctx);
    root spawn safe;
    print(f"[safe ] unique parsed={ctx.misses}, "
