"""Sync dependency graph for the drt project.

Models a multi-sync DAG where each SyncFile declares its `depends_on`
neighbors via DependsOn edges. A walker walks the graph to:
  1. detect cycles that would break topological ordering,
  2. produce a level-by-level execution plan (independent syncs share
     a level and may run in parallel),
  3. report reachability from a given root sync.

Everything is in-memory and declarative: ordering is discovered by a
walker, not hard-coded.
"""

node SyncFile {
    has name: str = "";
    has loaded: bool = False;
}

edge DependsOn {
    has reason: str = "";
}

walker TopologicalSort {
    has visiting: dict[str, str] = {};
    has done: set[str]  = {};
    has order: list[str] = [];
    has cycle_path: list[str] = [];
    has cycle_target: str = "";

    can start with Root entry {
        visit [-->];
    }

    can sort with SyncFile entry {
        here_name = here.name;
        if cycle_target != "" {
            visit [-->];
            return;
        }
        if here_name in done {
            visit [-->];
            return;
        }
        if here_name in visiting {
            cycle_target = here_name;
            cycle_path.append(here_name);
            visit [-->];
            return;
        }
        visiting[here_name] = here_name;
        visit [->:DependsOn:->];
        # Reached a sink: pop the DFS frame and record the order.
        _ = visiting.pop(here_name);
        done.add(here_name);
        order.append(here_name);
    }

    can descend with SyncFile entry {
        visit [->:DependsOn:->];
    }

    can ascend with SyncFile entry {
        if cycle_target != "" {
            if cycle_path == [] or cycle_path[-1] != here.name {
                cycle_path.append(here.name);
            }
            visit [<--];
            return;
        }
        here_name = here.name;
        _ = visiting.pop(here_name);
        done.add(here_name);
        order.append(here_name);
        visit [<--];
    }

    can back_with_cycle with Root entry {
        # Walker bubbles back up after detecting a cycle; disengage
        # so the cycle_path is preserved on self.
        disengage;
    }
}

walker ExecutionLevels {
    has levels: dict[int, list[str]] = {};
    has pending: dict[str, int] = {};
    has visited: set[str] = {};
    has cycle_target: str = "";

    can start with Root entry {
        visit [-->];
    }

    can schedule with SyncFile entry {
        here_name = here.name;
        if here_name in visited {
            visit [-->];
            return;
        }
        # DFS post-order: compute the level of this sync as 1 + max
        # level of its dependencies, then store it in pending so the
        # dependency edges can be collapsed into per-level buckets.
        max_dep_level = -1;
        cycle_seen = False;
        for dep in [->:DependsOn:->] {
            dep_name = dep[0].name;
            if dep_name == here_name {
                cycle_target = here_name;
                cycle_seen = True;
                break;
            }
            if dep_name not in pending {
                visit dep[0];
            }
            dep_level = pending.get(dep_name, 0);
            if dep_level > max_dep_level {
                max_dep_level = dep_level;
            }
        }
        if cycle_seen {
            visit [-->];
            return;
        }
        my_level = max_dep_level + 1;
        pending[here_name] = my_level;
        visited.add(here_name);
        visit [-->];
    }
}

walker Reachability {
    has from_name: str = "";
    has reachable: set[str] = set();
    has visited: set[str] = set();

    can start with Root entry {
        visit [-->];
    }

    can walk with SyncFile entry {
        here_name = here.name;
        if from_name == "" {
            from_name = here_name;
            reachable.add(here_name);
        }
        if here_name in visited {
            visit [-->];
            return;
        }
        visited.add(here_name);
        if here_name != from_name {
            reachable.add(here_name);
        }
        visit [->:DependsOn:->];
    }
}

with entry {
    company_lookup  = SyncFile(name="company_lookup.yaml");
    region_lookup   = SyncFile(name="region_lookup.yaml");
    user_sync       = SyncFile(name="user_sync.yaml");
    contact_sync    = SyncFile(name="contact_sync.yaml");
    report_sync     = SyncFile(name="report_sync.yaml");

    root ++> company_lookup
        ++> region_lookup
        ++> user_sync
        ++> contact_sync
        ++> report_sync;

    # contact_sync depends on both lookup tables.
    contact_sync +>:DependsOn(reason="destination_lookup"):+> company_lookup;
    contact_sync +>:DependsOn(reason="destination_lookup"):+> region_lookup;
    # user_sync also depends on company_lookup (independent from contact_sync
    # in terms of ordering — they share the same level).
    user_sync +>:DependsOn(reason="destination_lookup"):+> company_lookup;
    # report_sync depends on both downstream syncs.
    report_sync +>:DependsOn(reason="downstream"):+> user_sync;
    report_sync +>:DependsOn(reason="downstream"):+> contact_sync;

    # ---- 1. Topological sort ----------------------------------------------
    topo = TopologicalSort() spawn root;
    if topo.cycle_target != "" {
        print(f"CYCLE detected involving {topo.cycle_target}: "
              f"{topo.cycle_path}");
    } else {
        print("Topological execution order:");
        for i, name in enumerate(topo.order) {
            print(f"  {i+1}. {name}");
        }
    }
    topo disengage;

    # ---- 2. Level-by-level plan (parallel-ready) ---------------------------
    levels_walker = ExecutionLevels() spawn root;
    if levels_walker.cycle_target != "" {
        print(f"CYCLE detected at {levels_walker.cycle_target}");
    } else {
        bucket: dict[int, list[str]] = {};
        for (name, lvl) in levels_walker.pending.items() {
            if lvl not in bucket { bucket[lvl] = []; }
            bucket[lvl].append(name);
        }
        print("\nExecution levels (each level may run in parallel):");
        level_keys = sorted(bucket.keys());
        for lvl in level_keys {
            names = bucket[lvl];
            joined = ", ".join(sorted(names));
            print(f"  level {lvl}: {joined}");
        }
    }
    levels_walker disengage;

    # ---- 3. Reachability from contact_sync --------------------------------
    reach = Reachability() spawn root;
    print(f"\nReachable from {reach.from_name}: "
          f"{sorted(reach.reachable)}");
    reach disengage;
}
