```jac
"""Pagination with CTE: model a paginated article catalog and walk pages as a walker.

The source issue hand-rolls windowed pagination on top of an articles table
(WITH ... ROW_NUMBER() OVER ... BETWEEN ...). The natural shape is: articles
ordered by created_at DESC, partitioned into fixed-size pages, with each page
holding a slice of articles and an ordinal. A walker steps page -> article ->
next page, the graph equivalent of a window-function cursor.
"""

node Article {
    has title: str = "";
    has published: bool = True;
}

node Page {
    has number: int = 0;
    has size: int = 0;
    has total: int = 0;
    has from_row: int = 0;
    has to_row: int = 0;
}

edge Holds {
    has slot: int = 0;
}

edge NextPage {
    has cursor: int = 0;
}

walker Reader {
    has current_page: int = 1;
    has total_pages: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can open with Page entry {
        print(
            f"Page {here.number}/{self.total_pages} "
            f"({here.from_row}..{here.to_row} of {here.total})"
        );
        visit [->:Holds:->];
    }

    can read with Article entry {
        status = "PUB" if here.published else "DRAFT";
        print(f"  [{status}] {here.title}");
    }

    can turn with Article entry {
        visit [here ->:NextPage:->];
    }

    can advance with Article entry {
        next_node = [here ->:NextPage:->][0] if [here ->:NextPage:->] else None;
        if next_node is not None {
            visit [here ->:NextPage:->];
        } else {
            print("end of catalog");
        }
    }
}

with entry {
    # Article pool: titles, newest first
    articles = [
        Article(title="CTE pagination patterns"),
        Article(title="Window functions in practice"),
        Article(title="Recursive walks without recursion"),
        Article(title="Graph thinking for SQL minds", published=False),
        Article(title="Edges as first-class joins"),
        Article(title="Why typed edges help"),
    ];
    total_count = len(articles);
    page_size = 2;
    total_pages = (total_count + page_size - 1) // page_size;

    # Build page -> article -> next_page chain (oldest page first; reader starts at 1)
    prev_page: object = None;
    for page_idx in range(total_pages - 1, -1, -1) {
        page_num = page_idx + 1;
        start = page_idx * page_size;
        end = start + page_size;
        if end > total_count {
            end = total_count;
        }
        page_node = Page(
            number=page_num,
            size=page_size,
            total=total_count,
            from_row=start + 1,
            to_row=end,
        );
        root ++> page_node;
        for slot_offset in range(end - start) {
            article = articles[start + slot_offset];
            page_node +>:Holds(slot=slot_offset):+> article;
        }
        if prev_page is not None {
            page_node +>:NextPage(cursor=page_num + 1):+> prev_page;
        }
        prev_page = page_node;
    }

    reader = Reader(total_pages=total_pages);
    root spawn reader;
}
