```jac
"""Application.Idle stack-overflow scenario modeled as walker self-recursion.

The osu!stable crash is a single handler recursively calling itself until
the guard page is hit. We model the handler as a walker that re-enters the
same Application.Idle node from its own ability -- the equivalent of a
direct self-recursive event handler. A depth limit and an explicit
``visited`` guard set turn the infinite recursion into a finite, observable
walk that still preserves the domain semantics (cycle policy, max depth,
invalidation on exit) of the failing handler.
"""

node Handler {
    has name: str = "";
    has depth: int = 0;
    has payload: str = "";
}

node Dispatcher {
    has idle_count: int = 0;
}

edge Idle {
    has weight: int = 1;
}

walker IdleWalker {
    has max_depth: int = 10;
    has visited: list[str] = [];
    has log: list[str] = [];

    can start with Root entry {
        print("IdleWalker: entering dispatch loop from root");
        visit [->:Idle:->];
    }

    can dispatch with Dispatcher entry {
        here.idle_count += 1;
        self.log.append(f"dispatch[{here.idle_count}] -> handler");
        visit [->:Idle:->];
    }

    can invoke with Handler entry {
        # Cycle guard: explicit visited set, since jac 0.36.1 walkers
        # have no built-in once-per-node visitation on cyclic graphs.
        if here.name in self.visited {
            self.log.append(f"skip  {here.name} (cycle guard)");
            visit [->:Idle:->] else { disengage; }
        }
        self.visited.append(here.name);

        # Domain rule: max depth mirrors the failing stack guard page.
        if here.depth >= self.max_depth {
            self.log.append(f"halt  {here.name} at depth {here.depth} (would have overflowed)");
            disengage;
        }

        self.log.append(f"enter {here.name} depth={here.depth} payload={here.payload}");
        here.depth += 1;

        # Self-recursion: the handler re-enters the same Idle node.
        visit [->:Idle:->] else {
            self.log.append(f"end   {here.name} no further idle targets");
            disengage;
        }
    }

    can report with Root entry {
        print("--- IdleWalker trace ---");
        for line in self.log {
            print(line);
        }
        print(f"total idle dispatches observed: {len(self.log)}");
    }
}

with entry {
    app_idle = Dispatcher();
    frame_handler = Handler(name="Frame", depth=0, payload="tick");

    # The Dispatcher emits an Idle edge to the Handler, and the Handler
    # re-emits Idle back to itself -- this is the structural cause of the
    # infinite self-recursion in the original Application.Idle handler.
    root +>:Idle:+> app_idle +>:Idle:+> frame_handler +>:Idle:+> frame_handler;

    walker_instance = IdleWalker(max_depth=12);
    root spawn walker_instance;
}
