```jac
"""Waste-collection API: list serialization causes N+1 query storms.

The original DRF serializer hand-rolled a per-object walk over RegionAttribute
values, Property lookups, and CPV/ACPV aggregations for every collection in a
list response. We model the worst-case traversal natively: a Collection walks
its Region, and the Region fans out to all of its RegionAttributeValues (one
per property). An Auditor walker fans out across those attribute values, the
way a DRF list response would, and reports the total work performed — exactly
the pattern that timed out the production worker.
"""

node Collection {
    has title: str = "";
    has year: int = 0;
}

node Region {
    has name: str = "";
}

node RegionAttributeValue {
    has property_name: str = "";
    has display_value: str = "";
}

# Typed edge archetypes capture the relationships the original code traversed.
edge BelongsTo {
    has since: str = "";
}

edge HasAttribute {
}

edge ExportsTo {
}

walker Auditor {
    has total_lookups: int = 0;

    can start with Root entry {
        # Kick off the fan-out: from root, traverse Collection -> Region.
        visit [-->];
    }

    can step_collection with Collection entry {
        # A real serializer would also touch related objects here
        # (sources, flyers, allowed/forbidden materials, catchment, NUTS).
        # We visit BelongsTo to land on the Region, then continue.
        visit [->:BelongsTo:->];
    }

    can fan_region with Region entry {
        # This is the explosive line: for every attribute value attached to
        # the region, the legacy serializer did:
        #   * Property.objects.filter(name=...).first()
        #   * collectionpropertyvalues_for_display(user=user)
        #   * aggregatedcollectionpropertyvalues_for_display(user=user)
        # We model one "lookup" per attribute to count the work.
        for av in [->:HasAttribute:->] {
            self.total_lookups += 1;
            print(
                f"  lookup#{self.total_lookups} "
                f"property={av.property_name} value={av.display_value}"
            );
        }
        # After fanning across the region's attributes, no further
        # forward edges remain — disengage so the walker exits cleanly.
        disengage;
    }
}

# A second walker models the lightweight, list-friendly serializer that the
# remediation proposes: it walks Collection -> Region but does NOT explode
# across RegionAttributeValue edges. This is what should run on the broad
# /waste_collection/api/collection/ list endpoint.
walker LeanAuditor {
    has collections_seen: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can step_collection with Collection entry {
        self.collections_seen += 1;
        print(f"  lean serialize: {here.title} ({here.year})");
        visit [->:BelongsTo:->];
    }

    can step_region with Region entry {
        # Stop at the region; do NOT follow HasAttribute edges. This bounds
        # the query count per collection to a constant.
        print(f"  reached region {here.name} (no attribute fan-out)");
        disengage;
    }
}

with entry {
    # Build a representative list payload: a few collections, each pointing
    # at a region that owns many attribute values — the shape that timed out.
    north = Region(name="North");
    south = Region(name="South");

    north +>:HasAttribute:+> RegionAttributeValue(property_name="population", display_value="120000");
    north +>:HasAttribute:+> RegionAttributeValue(property_name="recycling_rate", display_value="0.42");
    north +>:HasAttribute:+> RegionAttributeValue(property_name="contamination_pct", display_value="3.1");

    c1 = Collection(title="North Q1", year=2026);
    c2 = Collection(title="North Q2", year=2026);
    c3 = Collection(title="South Q1", year=2026);

    c1 +>:BelongsTo(since="2026-01"):+> north;
    c2 +>:BelongsTo(since="2026-04"):+> north;
    c3 +>:BelongsTo(since="2026-01"):+> south;

    root ++> c1 ++> c2 ++> c3;

    print("--- heavy (legacy export-style) walk ---");
    root spawn Auditor();

    print("\n--- lean (list-style) walk ---");
    root spawn LeanAuditor();
    print(f"lean collections visited: {root spawn LeanAuditor() and 0}");
}
