```jac
"""AI routing benchmark & failure evaluation suite.

Models the core Slipwell routing/eval scenario as a graph:
test cases -> routed to providers -> produce benchmark results.
A walker walks the case graph, routes each through providers
(measuring timeout/malformed/fallback), and emits a benchmark
report. Cycle-prone dependency edges keep an explicit guard
(cycle policy is domain logic and must not be removed).
"""

node Case {
    has case_id: str = "";
    has category: str = "";
    has consented: bool = False;
    has expected_intent: str = "";
    has latency_ms: int = 0;
    has malformed: bool = False;
    has ambiguous: bool = False;
}

node Provider {
    has name: str = "";
    has model: str = "";
    has prompt_version: str = "";
    has schema_version: str = "";
    has timeout_ms: int = 0;
    has cost_per_call: float = 0.0;
    has alive: bool = True;
}

node Result {
    has type_correct: bool = False;
    has field_valid: bool = False;
    has date_exact: bool = False;
    has entity_linked: bool = False;
    has safe_review: bool = False;
    has false_update: bool = False;
    has fallback_used: bool = False;
    has failed: bool = False;
}

edge Requires { }       # Case -> Provider dependency
edge Routed { }        # Case -> Result produced by some provider
edge Fallback { }      # Result -> Provider (next fallback chain link)
edge DependsOn { }      # Case -> Case (dependency ordering, may cycle)

walker Auditor {
    has report: dict = {};
    has budget_ms: int = 0;
    has guard: set = {};

    can start with Root entry {
        visit [->:Requires:->];
    }

    can audit with Case entry {
        # Cycle policy: explicit visited set (walkers don't dedupe in 0.36.1).
        if here.case_id in self.guard {
            return;
        }
        self.guard.add(here.case_id);

        # Reject unconsented private beta data.
        if not here.consented {
            self.report[here.case_id] = {"status": "REJECTED_UNCONSENTED"};
            return;
        }

        # Walk dependency edges first (Cases may depend on other Cases).
        visit [here->:DependsOn:->] else {
            # no deps; fall through to routing
        }

        self._route(here);
    }

    can record with Provider entry {
        # Provider-level ability: nothing to do here; routing happens in audit.
        visit [-->] else { disengage; }
    }

    can summarize with Result entry {
        # Reached via Routed edges from a Case.
        cid = here.parent_case_id if hasattr(here, "parent_case_id") else "?";
        self.report[cid] = {
            "type_correct": here.type_correct,
            "field_valid": here.field_valid,
            "date_exact": here.date_exact,
            "entity_linked": here.entity_linked,
            "safe_review": here.safe_review,
            "false_update": here.false_update,
            "fallback_used": here.fallback_used,
            "failed": here.failed,
        };
        visit [here->:Fallback:->] else { disengage; }
    }

    def _route(c: Case) -> None {
        # Simulate routing: pick the first Requires provider, simulate
        # timeout / malformed / success / fallback, and attach a Result.
        # In a real benchmark this would call the model; here we use
        # field flags on the case as the synthetic outcome.
        result = Result(
            type_correct=not c.ambiguous,
            field_valid=not c.malformed,
            date_exact=not c.ambiguous,
            entity_linked=not c.ambiguous,
            safe_review=c.category == "people" or c.category == "retainer",
            false_update=False,
            fallback_used=False,
            failed=False,
        );
        # If the case flags a malformed output, mark failed + fallback.
        if c.malformed {
            result.failed = True;
            result.field_valid = False;
            result.fallback_used = True;
        }
        c +>:Routed:+> result;
    }
}

# Wire the demo: cases with a couple of dependency edges (one a chain,
# one a self-loop guarded by the Auditor's visited set).
with entry {
    # Providers
    p_primary = Provider(
        name="openai", model="gpt-4", prompt_version="v3",
        schema_version="s2", timeout_ms=800, cost_per_call=0.03,
    );
    p_fallback = Provider(
        name="anthropic", model="claude-3", prompt_version="v3",
        schema_version="s2", timeout_ms=1200, cost_per_call=0.025,
    );
    root ++> p_primary ++> p_fallback;

    # Cases
    c1 = Case(
        case_id="C-001", category="ambiguity", consented=True,
        expected_intent="reschedule", ambiguous=True,
    );
    c2 = Case(
        case_id="C-002", category="malformed", consented=True,
        expected_intent="cancel", malformed=True,
    );
    c3 = Case(
        case_id="C-003", category="people", consented=True,
        expected_intent="lookup",
    );
    c4 = Case(
        case_id="C-004", category="private-beta", consented=False,
        expected_intent="retainer",
    );

    root ++> c1 ++> c2 ++> c3 ++> c4;

    # Requires edges: each case depends on a provider.
    c1 +>:Requires:+> p_primary;
    c2 +>:Requires:+> p_primary;
    c3 +>:Requires:+> p_primary;
    c4 +>:Requires:+> p_primary;

    # Fallback chain: primary -> fallback (modeled as a Provider node).
    p_primary +>:Fallback:+> p_fallback;

    # Dependency ordering between cases. C-002 depends on C-001.
    c2 +>:DependsOn:+> c1;
    # Cycle test: C-001 also depends on C-002 (guard set breaks the loop).
    c1 +>:DependsOn:+> c2;

    auditor = Auditor(budget_ms=5000);
    root spawn auditor;

    print("Benchmark report:");
    for (cid, row) in auditor.report.items() {
        print(f"  {cid}: {row}");
    }
}
