"""Demonstrate running a flow from a selected task with cycle protection."""

node Flow {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Task {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has task_id: str = "";
    has needs_skipped_output: bool = False;
    has output_ready: bool = False;
}

edge NextTask {
    has ordinal: int = 0;
}

walker RunFromHere {
    has visited_ids: list[str] = [];
    has started: bool = False;

    can execute with Task entry {
        if not self.started {
            print(f"Run from here: {here.title}");
            self.started = True;
        }

        if here.task_id in self.visited_ids {
            print(f"Cycle detected at {here.title}; stopping");
            disengage;
        }

        self.visited_ids.append(here.task_id);

        if here.needs_skipped_output and not here.output_ready {
            print(f"Warning: {here.title} expects output from skipped upstream tasks");
        }

        if not here.available {
            print(f"Skipped unavailable task: {here.title}");
        } else {
            print(f"Executing {here.title}");
            here.output_ready = True;
        }

        visit [->:NextTask:->] else {
            print("Downstream traversal complete");
            disengage;
        }
    }
}

