"""Signal Matrix Static Dashboard V1 — OSP model.

Demonstrates the core reporting scenario from issue #297: a per-timeframe
primitive signal inventory that exposes asset × timeframe conflicts without
collapsing them into a hidden final-advice label. The walker traverses the
matrix by asset then by timeframe, surfacing regime context, freshness,
replay-readiness, and local pattern candidate flags.
"""

# ---------- Edge archetypes (typed relationships carry meaning) ----------

edge HasTimeframe {
    has label: str = "";
}

edge FramesAsset {
    has role: str = "primary";
}

edge HasRegime {
    has kind: str = "";
}

# ---------- Node archetypes ----------

node Asset {
    has symbol: str = "";
    has family: str = "";
}

node Timeframe {
    has name: str = "";            # e.g. "1D", "4H", "15m"
    has tier: str = "";            # "HTF" or "LTF"
    has frame: str = "";           # "Breath" or "Fibo"
    has bias: str = "neutral";     # primitive signal: bullish/bearish/neutral
    has strength: float = 0.0;     # primitive signal magnitude
    has freshness: str = "stale";  # fresh / recent / stale
    has replay_ready: bool = False;
}

node RegimeContext {
    has kind: str = "";            # "trending", "ranging", "volatile"
    has confidence: float = 0.0;
}

node PatternCandidate {
    has name: str = "";            # local pattern label
    has active: bool = False;
}

