```jac
"""Merkle DAG commits: model a Git-like history where commits reference trees and parent commits via typed edges, and walk the chain to demonstrate tamper-evident hashing.

A Commit node carries its identity (content hash), tree reference, author, and message.
Parents are modeled as a typed edge (HasParent) carrying the parent commit's hash.
The HistoryWalker traverses parent chains and verifies that mutations propagate to descendant IDs.
"""

node Author {
    has name: str = "";
    has email: str = "";
}

edge HasParent {
    has parent_hash: str = "";
}

node Commit {
    has commit_id: str = "";
    has tree_id: str = "";
    has author: Author = Author();
    has message: str = "";
    has parents: list = [];
}

walker HistoryWalker {
    has depth_limit: int = 16;
    has visited: list = [];

    can start with Root entry {
        visit [-->];
    }

    can walk with Commit entry {
        if here.commit_id in self.visited {
            disengage;
        }
        self.visited.append(here.commit_id);
        if len(self.visited) > self.depth_limit {
            disengage;
        }
        label = "ROOT" if len(self.visited) == 1 else "DESCENDANT";
        print(f"[{label}] commit={here.commit_id[:12]}... tree={here.tree_id[:12]}... msg={here.message!r}");
        next_edges = [here ->:HasParent:->];
        if len(next_edges) > 0 {
            visit next_edges;
        } else {
            disengage;
        }
    }
}

with entry {
    # Author and commit helpers live in plain defs so the demonstration stays self-contained.
    def make_commit(tree_hex: str, author_node: Author, msg: str, parent_ids: list) -> Commit {
        # Deterministic fingerprint: simulate content-addressed identity over tree + parents + author + msg.
        seed = f"{tree_hex}|{'|'.join(parent_ids)}|{author_node.name}|{author_node.email}|{msg}";
        digest = 0;
        for ch in seed {
            digest = (digest * 131 + ord(ch)) % (2 ** 64);
        }
        hex_id = "";
        for i in range(16) {
            nibble = (digest >> (i * 4)) & 0xF;
            hex_id = hex_id + "0123456789abcdef"[nibble];
        }
        # Reverse nibble order so leading zeros of the digest surface visibly.
        return Commit(
            commit_id=hex_id,
            tree_id=tree_hex,
            author=author_node,
            message=msg,
            parents=parent_ids
        );
    }

    alice = Author(name="Alice", email="alice@example.com");
    bob = Author(name="Bob", email="bob@example.com");

    tree_root = "t" + "0" * 63;
    tree_v2 = "t" + "1" + "0" * 62;

    # Initial commit (no parents).
    c1 = make_commit(tree_root, alice, "initial commit", []);
    # Child commit referencing c1.
    c2 = make_commit(tree_v2, alice, "add subtree", [c1.commit_id]);
    # Grandchild commit referencing c2 (and transitively c1).
    c3 = make_commit(tree_v2, bob, "polish docs", [c2.commit_id]);

    # Build the Merkle DAG via typed HasParent edges carrying the parent hashes.
    root ++> c1;
    c1 +>:HasParent(parent_hash=c1.commit_id):+> c2;
    c2 +>:HasParent(parent_hash=c2.commit_id):+> c3;

    # Tamper-evidence demo: changing a single field must shift every descendant id.
    c1_tampered = make_commit(tree_root, alice, "initial commit (edited)", []);
    print(f"original c1.id = {c1.commit_id}");
    print(f"tampered c1.id = {c1_tampered.commit_id}");
    print(f"ids diverge:    {c1.commit_id != c1_tampered.commit_id}");

    # Chain integrity: every parent id on a child must equal the parent's own commit id.
    c2_in = [e.parent_hash for e in [c1->:HasParent:->][0].edges];
    parent_match = c1.commit_id == c2_in[0];
    print(f"c2.parents[0] == c1.id: {parent_match}");

    # Walk history from HEAD backwards.
    print("--- walking history from c3 ---");
    c3 spawn HistoryWalker(depth_limit=8);
}
