```jac
"""Code call-graph explorer modeled after Codemogger issue #12.

Models TypeScript symbol call graphs as nodes (Symbol, Call) connected by
typed ``Calls`` edges (carrying call type + line numbers). A walker explores
neighbors to a chosen depth and reports what it finds.
"""

node Symbol {
    has id: str = "";
    has name: str = "";
    has kind: str = "function";        # function | method | constructor
    has file_path: str = "";
    has start_line: int = 0;
    has end_line: int = 0;
    has exported: bool = False;
    has resolved: bool = True;
}

node UnresolvedCall {
    has id: str = "";
    has name: str = "";
    has resolution: str = "unresolved";  # unresolved | external
}

edge Calls {
    has call_type: str = "function";    # function | method | constructor
    has lines: list[int] = [];
}

node Repo {
    has name: str = "";
}

walker Explore {
    has target_name: str = "";
    has max_depth: int = 2;
    has depth: int = 0;
    has visited: list[str] = [];

    can start with Repo entry {
        # Find the requested symbol on the repo root, then walk from it.
        for child in --> {
            if isinstance(child, Symbol) and child.name == self.target_name {
                self.visit_symbol(child);
                report {"root": self.target_name,
                        "depth": self.max_depth,
                        "found": True};
                disengage;
            }
        }
        report {"root": self.target_name,
                "depth": self.max_depth,
                "found": False};
    }

    can visit_symbol with Symbol entry {
        if here.id in self.visited {
            disengage;
        }
        self.visited.append(here.id);
        if self.depth >= self.max_depth {
            report {"node": here.id,
                    "name": here.name,
                    "kind": here.kind,
                    "file": here.file_path,
                    "lines": [here.start_line, here.end_line],
                    "resolved": here.resolved,
                    "depth": self.depth,
                    "truncated": True};
            disengage;
        }
        report {"node": here.id,
                "name": here.name,
                "kind": here.kind,
                "file": here.file_path,
                "lines": [here.start_line, here.end_line],
                "resolved": here.resolved,
                "depth": self.depth,
                "truncated": False};
        self.depth = self.depth + 1;
        visit [->:Calls:->];
    }

    can visit_unresolved with UnresolvedCall entry {
        report {"node": here.id,
                "name": here.name,
                "resolution": here.resolution,
                "depth": self.depth};
        # No further traversal from synthetic nodes.
        disengage;
    }
}

with entry {
    repo = Repo(name="isecure-ws-channel-poller");

    handler = Symbol(id="src/lambda/handler.ts#createHandler",
