                  end_line=130,
                  exported=True,
                  resolved=True);

    s3_ctor = Symbol(id="src/adapters/s3.ts#S3FileStore",
                     name="S3FileStore",
                     kind="constructor",
                     file_path="src/adapters/s3.ts",
                     start_line=10,
                     end_line=30,
