```jac
"""Order auditor: invalid orders are skipped, fraudulent orders halt the walk.

Demonstrates two flavors of early return side by side:
  - ``continue``-like: re-enter traversal after reporting a skipped order.
  - ``disengage``-like: bail out of the entire walk on fraud.
"""

node Order {
    has label: str = "";
    has amount: float = 0.0;
    has valid: bool = True;
    has fraud: bool = False;
}

walker OrderAuditor {
    has audited: int = 0;
    has skipped: int = 0;
    has halted_on: str = null;

