    bos +>:leg_bos_jfk:+> jfk;

    leg_jfk_ord = FlightLeg(
        ticket_price=510.0, origin_code="JFK", dest_code="ORD"
    );
    jfk +>:leg_jfk_ord:+> ord;

    scout = Scout();
    root spawn scout;

    peak = scout.report;
