A maintainer on the project crate/crate (Java) filed this issue about hand-rolled graph machinery causing pain:

Issue #12544: Add `RECURSIVE` support to common table expressions (WITH)

Continuation of https://github.com/crate/crate/issues/11757


Basic `WITH` got implemented in https://github.com/crate/crate/pull/12540
We should extend it with support for the `RECURSIVE` clause to support the query mentioned in https://github.com/crate/crate/issues/11757. A simpler version looks like this:

```sql
WITH RECURSIVE t(n) AS (
    VALUES (1)
  UNION ALL
    SELECT n+1 FROM t WHERE n < 100
)
SELECT sum(n) FROM t;
```

```
                               QUERY PLAN
-------------------------------------------------------------------------
 Aggregate  (cost=3.65..3.66 rows=1 width=8)
   CTE t
     ->  Recursive Union  (cost=0.00..2.95 rows=31 width=4)
           ->  Result  (cost=0.00..0.01 rows=1 width=4)
           ->  WorkTable Scan on t t_1  (cost=0.00..0.23 rows=3 width=4)
                 Filter: (n < 100)
   ->  CTE Scan on t  (cost=0.00..0.62 rows=31 width=4)
```

See [PostgreSQL recursive queries](https://www.postgresql.org/docs/current/queries-with.html#QUERIES-WITH-RECURSIVE)


## Resources and references

- https://github.com/cockroachdb/cockroach/commit/7bc04d7eacc4392ea569f83bde251e52a4cbb33a
- https://calcite.apache.org/docs/algebra.html#recursive-queries
- https://calcite.apache.org/javadocAggregate/org/apache/calcite/rel/core/RepeatUnion.html


## Out of scope

- Usage of intermediate tables (only in-memory buffering of the working table with ram accounting)
- Syntax sugar (SEARCH clause) for Search Order (depth- or breadth-first sort column)
- CYCLE clause to simplify cycle detection
- Correlations (with other WITHS or outside relations)


## Discussion

- 20+ for now because implementation wasn't clear to everyone

Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.

```jac
"""Recursive CTE (WITH RECURSIVE) modeling in idiomatic Jac.

The original Crate issue (crate/crate #12544) describes the hand-rolled
machinery that a SQL engine must perform to evaluate a recursive common
table expression:

    WITH RECURSIVE t(n) AS (
        VALUES (1)
      UNION ALL
        SELECT n+1 FROM t WHERE n < 100
    )
    SELECT sum(n) FROM t;

Three roles are involved:

    1. The seed (non-recursive) SELECT, called once.
    2. The recursive SELECT, fed by the previous iteration's working table,
       guarded by a termination predicate.
    3. The working table, accumulated across iterations.

We model those roles as Jac node archetypes connected by typed edges, and
let a walker iterate over the work-table -> recursive-step loop until the
working table stops growing, exactly like a real recursive CTE would.
"""

# ----- Typed edges ----------------------------------------------------------
# A non-recursive SELECT contributes rows to the working table once.
edge Seeds {
    has initial: int = 1;
}

# A recursive SELECT reads from the previous iteration's working table and
# emits rows for the next iteration, guarded by a termination predicate.
edge Produces {
    has step: int = 1;
    has limit: int = 100;
}

# The working table buffer: each iteration appends to it; the recursive
# step consumes from it.
edge Feeds {}

# ----- Node archetypes ------------------------------------------------------
node RecursiveCTE {
    has name: str = "";
    has sum_value: int = 0;
}

# A non-recursive seed SELECT — analogous to the VALUES (1) half of the CTE.
node Seed {
    has value: int = 1;
}

# A recursive SELECT step — analogous to "SELECT n+1 FROM t WHERE n < 100".
node RecursiveStep {
    has step: int = 1;
    has limit: int = 100;
}

# A working-table row. Many of these accumulate across iterations.
node WorkRow {
    has n: int = 0;
}

# ----- Walker ---------------------------------------------------------------
walker RecursiveEvaluator {
    has anchor: RecursiveCTE = None;
    has working_rows: list[int] = [];
    has changed: bool = True;

    can begin with Root entry {
        # Find the CTE anchor we are evaluating.
        ctes = [c for c in [-->] if isinstance(c, RecursiveCTE)];
        if not ctes {
            print("No recursive CTE found.");
            disengage;
        }
        self.anchor = ctes[0];
        print(f"Evaluating recursive CTE '{self.anchor.name}'");
        visit [-->];
    }

    # Land on the CTE itself: take one row from the seed SELECT and prime
    # the working table.
    can seed with RecursiveCTE entry {
        seed_node = [s for s in [-->] if isinstance(s, Seed)][0];
        seed_value = seed_node.value;
        self.working_rows = [seed_value];
        self.anchor.sum_value = seed_value;
        print(f"  seed: working_table = {self.working_rows}");
        visit [-->];
    }

    # Land on a recursive step: iterate until the working table stops
    # growing (the row count is unchanged after a full pass).
    can iterate with RecursiveStep entry {
        step = here.step;
        limit = here.limit;
        self.changed = True;
        rounds = 0;
        while self.changed {
            self.changed = False;
            rounds += 1;
            next_rows: list[int] = [];
            for v in self.working_rows {
                nxt = v + step;
                if nxt <= limit {
                    next_rows.append(nxt);
                    self.anchor.sum_value += nxt;
                    self.changed = True;
                }
            }
            if self.changed {
                self.working_rows = next_rows;
                print(
                    f"  round {rounds}: working_table (head) = "
                    f"{self.working_rows[:5]}"
                    + (" ..." if len(self.working_rows) > 5 else "")
                );
            } else {
                print(f"  stabilized after {rounds - 1} round(s)");
            }
        }
        visit [-->];
    }

    # Land on a working-table row: print the materialized row count.
    can tally with WorkRow entry {
        # No-op placeholder so the walker can be triggered on rows too.
        visit [-->];
    }
}

# ----- Demonstration graph --------------------------------------------------
with entry {
    cte = RecursiveCTE(name="t");
    seed = Seed(value=1);
    rec_step = RecursiveStep(step=1, limit=100);

    # Connect the graph: root -> CTE -> (seed, rec_step)
    root ++> cte;
    cte +>:Seeds(initial=1):+> seed;
    cte +>:Produces(step=1, limit=100):+> rec_step;
    # The recursive step reads the working-table rows back.
    rec_step +>:Feeds:+> WorkRow(n=0);
    # The CTE also holds materialized working-table rows.
    cte ++> WorkRow(n=0);

    # Spawn the walker on root and have it descend.
    root spawn RecursiveEvaluator();

    print(f"Final sum(n) over CTE '{cte.name}' = {cte.sum_value}");
    print("Expected: 1 + 2 + ... + 100 = 5050");
}
```

