node Pin {
    has name: str = "";
    has version: str = "";
    has status: str = "proposed";
}

node Constraint {
    has rule: str = "";
    has satisfied: bool = True;
}

edge Requires {
    has note: str = "";
}

edge Approves {
    has approver: str = "";
}

edge Blocks {
    has reason: str = "";
