# A compatibility probe: applies to either side of the dependency graph.
can check_pin with Pin | Constraint entry {
    if here.status == "rejected" {
        print(f"  [REJECTED] {here.name} {here.version} -- dropped from approved set");
    } elif here.status == "approved" {
        print(f"  [OK]       {here.name} {here.version}");
    } else {
