"""Package reachability walker: models the AOT reachability walk that
overflows the stack when a package graph contains a cycle (e.g. a
subpath that resolves back to its own root). Walker carries an explicit
visited-set so the cycle is bounded and reported."""

node Package {
    has name: str = "";
    has aot_promoted: bool = False;
}

edge DependsOn {
    has kind: str = "static";
}

walker Reachability {
    has visited: list[str] = [];
    has reachable: list[Package] = [];

    can start with Root entry {
        visit [-->];
    }

    can walk with Package entry {
        if here.name in self.visited {
            print(f"[CYCLE] re-entering {here.name} -> stopping branch");
            disengage;
        }
        self.visited = self.visited + [here.name];
        self.reachable = self.reachable + [here];
        tag = "PROMOTE" if here.aot_promoted else "skip   ";
        print(f"[{tag}] reachable package: {here.name}");
        visit [->:DependsOn:->];
    }
}

with entry {
    app = Package(name="@app/root", aot_promoted=True);
    ui = Package(name="@app/ui", aot_promoted=True);
    util = Package(name="@app/util", aot_promoted=False);
    cycle = Package(name="@app/cycle", aot_promoted=False);

    # Linear chain: root -> ui -> util
    root ++> app;
    app +>:DependsOn(kind="static"):+> ui;
    ui +>:DependsOn(kind="static"):+> util;

    # Back-edge from cycle leaf up to app closes the loop:
    # cycle -> app would re-enter @app/root -> cycle -> ...
    cycle +>:DependsOn(kind="static"):+> app;

    print("Walking reachable trusted packages from root:\n");
    walker = Reachability();
    root spawn walker;

    print("\n--- summary ---");
    print(f"visited nodes ({len(walker.visited)}): {walker.visited}");
    print(f"reachable + AOT-promoted: "
          f"{[p.name for p in walker.reachable if p.aot_promoted]}");
}
