```jac
"""Branch Recommendations: model restaurants, branches, evidence, and recs.

Demonstrates a recommendation walker that:
  1. Traverses from a root scope (Organization) down through Restaurants and
     Branches via typed `Operates` edges (replacing hand-rolled parent_id walks).
  2. Walks evidence (sales, traffic, ops) collected per branch via typed
     `Supports` edges, accumulating integer minor-unit revenue impact.
  3. Detects dependency cycles among recommendations via typed `DependsOn`
     edges (the recursion the issue complained about) and refuses to apply
     recs whose evidence lineage is broken.
  4. Marks out-of-scope branches (role boundary violation) as skipped.

Two walker abilities -- `gather` (sub-tree + evidence) and `audit` (dependency
ordering + cycle detection) -- correspond to the two phases described in the
issue ("scope items" + "deterministic, evidence-backed outputs").

All monetary figures use integer minor units (cents), never floats.
"""

# ---------- Edge archetypes -------------------------------------------------
edge Operates   { has since: str = ""; }
edge Supports   { has weight: int = 0; }
edge DependsOn  { has kind: str = ""; }

# ---------- Node archetypes -------------------------------------------------
node Organization {
    has name: str = "";
    has scope_ok: bool = True;
}

node Restaurant {
    has name: str = "";
    has role_boundary: str = "viewer";  # viewer | manager | admin
}

node Branch {
    has name: str = "";
    has city: str = "";
    has revenue_minor: int = 0;         # integer minor units
    has available: bool = True;
}

node Evidence {
    has kind: str = "";                 # sales | traffic | ops
    has minor_delta: int = 0;           # expected impact, integer minor units
    has intact: bool = True;            # lineage flag
}

node Recommendation {
    has title: str = "";
    has target_minor: int = 0;
    has applied: bool = False;
}

# ---------- Walker ---------------------------------------------------------
walker RecommendationEngine {
    has total_impact: int = 0;
    has skipped: int = 0;
    has applied: int = 0;
    has cycle_seen: bool = False;

    can start with Organization entry {
        print(f"scope: org={here.name} ok={here.scope_ok}");
        if not here.scope_ok {
            self.skipped += 1;
            disengage;
        }
        visit [->:Operates:->];
    }

    can gather with Restaurant entry {
        print(f"  restaurant={here.name} role={here.role_boundary}");
        if here.role_boundary == "viewer" {
            # role boundary violated: do not descend into branches
            self.skipped += 1;
            disengage;
        }
        visit [->:Operates:->];
    }

    can branch_visit with Branch entry {
        if not here.available {
            self.skipped += 1;
        } else {
            print(f"    branch={here.name} city={here.city} "
                  f"baseline={here.revenue_minor}c");
        }
        visit [->:Supports:->];
    }

    can evidence_collect with Evidence entry {
        lineage_ok = here.intact and here.minor_delta >= 0;
        if lineage_ok {
            self.total_impact += here.minor_delta;
            print(f"      evidence={here.kind} delta={here.minor_delta}c ok");
        } else {
            self.skipped += 1;
            print(f"      evidence={here.kind} BROKEN lineage");
        }
        # cycle detection across recommendation dependency edges
        visit [->:DependsOn:->];
    }

    can audit with Recommendation entry {
        # Visit siblings first (the "DependsOn" cycle probe), then decide
        # whether the rec is apply-able based on whether the walker ever
        # looped back onto the same recommendation node.
        visited: set = {};
        visit [->:DependsOn:->] else { disengage; }
        # If we get here, no outgoing DependsOn -- treat as leaf
        if self.cycle_seen {
            self.skipped += 1;
            print(f"      rec '{here.title}' REJECTED (cycle)");
        } else if here.target_minor > 0 {
            here.applied = True;
            self.applied += 1;
            print(f"      rec '{here.title}' APPLIED "
                  f"(target={here.target_minor}c)");
        } else {
            self.skipped += 1;
            print(f"      rec '{here.title}' SKIP (no target)");
        }
    }

    # Cycle probe: if DependsOn edges lead back to a Recommendation we've
    # already entered, mark the walker as cycle_seen. This is the explicit
    # cycle policy required because jac 0.36 walkers have no built-in
    # dedupe on cyclic graphs.
    can cycle_check with Recommendation entry {
        if here.applied {
            self.cycle_seen = True;
        }
        visit [->:DependsOn:->] else { disengage; }
    }
}

# ---------- Demo graph -----------------------------------------------------
with entry {
    org = Organization(name="Restrova", scope_ok=True);

    r1 = Restaurant(name="Spice Route", role_boundary="manager");
    r2 = Restaurant(name="Bao House", role_boundary="viewer");

    b1 = Branch(name="Spice-Dubai",  city="Dubai",  revenue_minor=2_400_00);
    b2 = Branch(name="Spice-AbuDhabi", city="AbuDhabi", revenue_minor=1_100_00);
    b3 = Branch(name="Bao-Sharjah", city="Sharjah", revenue_minor=0, available=False);

    e1 = Evidence(kind="sales",   minor_delta=150_00, intact=True);
    e2 = Evidence(kind="traffic", minor_delta= 60_00, intact=True);
    e3 = Evidence(kind="ops",     minor_delta= 30_00, intact=False);  # broken
    e4 = Evidence(kind="sales",   minor_delta= 90_00, intact=True);

    rec_a = Recommendation(title="Lunch combo",      target_minor=200_00);
    rec_b = Recommendation(title="Late-night menu",  target_minor=120_00);

    # Organization -> Restaurants -> Branches (Operates)
    org +>:Operates(since="2024-01"):+> r1;
    org +>:Operates(since="2024-03"):+> r2;
    r1 +>:Operates:+> b1;
    r1 +>:Operates:+> b2;
    r2 +>:Operates:+> b3;

    # Branches -> Evidence (Supports, integer minor-unit weight)
    b1 +>:Supports(weight=10):+> e1;
    b1 +>:Supports(weight=5):+>  e2;
    b2 +>:Supports(weight=7):+>  e3;
    b3 +>:Supports(weight=1):+>  e4;

    # Recommendations linked to a branch (Supports) and dependent on each
    # other (DependsOn). rec_a -> rec_b forms a chain; rec_b -> rec_a would
    # be a cycle but we deliberately leave it as a one-way chain here.
    b1 +>:Supports(weight=1):+> rec_a;
    rec_a +>:DependsOn(kind="blocking"):+> rec_b;

    org spawn RecommendationEngine();
    print("---- summary ----");
}
