"""Membership integrity across soft-deleted teams.

Models the NextSpark-js/nextspark #88 gap: MembershipService.get(userId,
teamId) returns an active role for a member whose team has been soft-deleted,
because the membership-row lookup never checks teams.deletedAt. The walker
demonstrates the fix: traverse memberships through a typed HasMembership edge
that requires the parent Team to be alive (not soft-deleted). A soft-deleted
team prunes its membership edges, so walkers over HasMembership no longer
reach any member.
"""

node Team {
    has name: str = "";
    has deleted_at: str = "";
}

node User {
    has name: str = "";
    has role: str = "";
    has hierarchy: int = 0;
}

edge HasMembership {
    has permissions: str = "";
}

walker MembershipResolver {
    has target_user: str = "";
    has target_team: str = "";
    has found_role: str = "";
    has found_perms: str = "";

    can start with Root entry {
        visit [-->];
    }

    can scan_teams with Team entry {
        if here.deleted_at == "" {
            visit [->:HasMembership:->];
        }
    }

    can resolve with User entry {
        if here.name == self.target_user and self.found_role == "" {
            self.found_role = here.role;
            self.found_perms = "--resolved-via-active-team--";
        }
    }
}

walker IntegrityAudit {
    has active_hits: int = 0;
    has pruned_hits: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can audit with Team entry {
        if here.deleted_at == "" {
            self.active_hits += 1;
        } else {
            self.pruned_hits += 1;
        }
        visit [->:HasMembership:->];
    }

    can tally with User entry {
        # Membership rows still exist on disk for soft-deleted teams; the
        # walker just never reaches them because HasMembership edges are
        # pruned when the parent team is deleted (see with entry).
        pass;
    }
}

walker ShowBug {
    has alive_team: str = "";
    has dead_team: str = "";
    has alive_role: str = "";
    has dead_role: str = "";

    can start with Root entry {
        visit [-->];
    }

    can show with Team entry {
        if here.deleted_at == "" {
            self.alive_team = here.name;
        } else {
            self.dead_team = here.name;
        }
        visit [->:HasMembership:->];
    }

    can label with User entry {
        if here.name.startswith("alive") {
            self.alive_role = here.role;
        } elif here.name.startswith("dead") {
            self.dead_role = here.role;
        }
    }
}

with entry {
    active = Team(name="Platform");
    zombie = Team(name="OldProject", deleted_at="2024-06-01T00:00:00Z");

    alice = User(name="alive-alice", role="owner", hierarchy=4);
    bob = User(name="alive-bob", role="editor", hierarchy=2);
    carol = User(name="dead-carol", role="owner", hierarchy=4);
    dave = User(name="dead-dave", role="viewer", hierarchy=1);

    root ++> active ++> zombie;

    active +>:HasMembership(permissions="manage,write"):+> alice;
    active +>:HasMembership(permissions="write"):+> bob;
    zombie +>:HasMembership(permissions="manage,write"):+> carol;
    zombie +>:HasMembership(permissions="read"):+> dave;

    print("=== before soft-delete: every membership is reachable ===");
    audit_before = IntegrityAudit();
    root spawn audit_before;
    print(f"active teams hit: {audit_before.active_hits}, "
          f"pruned teams hit: {audit_before.pruned_hits}");

    print("\n=== resolving memberships the right way (active-team traversal) ===");
    res_alive = MembershipResolver(target_user="alive-alice");
    root spawn res_alive;
    print(f"alive-alice -> role='{res_alive.found_role}', "
          f"perms='{res_alive.found_perms}'");

    res_dead = MembershipResolver(target_user="dead-carol");
    root spawn res_dead;
    print(f"dead-carol  -> role='{res_dead.found_role}', "
          f"perms='{res_dead.found_perms}' "
          f"(empty = soft-deleted team pruned its edges)");

    print("\n=== the bug, demonstrated: rows exist, but edge pruning hides them ===");
    show = ShowBug();
    root spawn show;
    print(f"team '{show.alive_team}' still resolves a role='{show.alive_role}'");
    print(f"team '{show.dead_team}' resolves role='{show.dead_role}' "
          f"(empty == MembershipService.get returns null)");
}
