    pkg_sc = Package(
        name="@ethang/schemas",
        uses_effect=True,
        effect_version="3.22.0",
        plugin_enabled=True,
        diagnostics=["missingEffectContext at src/user.ts:7"]
    );
    pkg_st = Package(
        name="@ethang/store",
        uses_effect=True,
        effect_version="3.22.0",
        plugin_enabled=False,
        diagnostics=["classSelfMismatch at src/db.ts:1"]
    );
    pkg_plain = Package(
        name="@ethang/utils",
        uses_effect=False,
        effect_version="",
        plugin_enabled=False,
        diagnostics=[]
    );

    root +>:DependsOn(kind="dev"):+> pkg_mg;
    root +>:DependsOn(kind="dev"):+> pkg_sc;
    root +>:DependsOn(kind="dev"):+> pkg_st;
    root +>:DependsOn(kind="dev"):+> pkg_plain;

    # Cross-package dependency: schemas -> markdown-generator.
    pkg_sc +>:DependsOn(kind="runtime"):+> pkg_mg;

    # Cyclic edge to exercise the guard (utils depends on itself).
    pkg_plain +>:DependsOn(kind="runtime"):+> pkg_plain;

    root spawn Diagnostician();
}
