"""Recursive 30-day dependency age gate.

Walks the resolved dependency graph and rejects packages newer than the
30-day policy threshold. A Developer Mode bypass disables the gate.
"""

node Package {
    has name: str = "";
    has age_days: int = 0;
    has available: bool = True;
}

edge DependsOn {
    has via: str = "";
}

walker DependencyAgeChecker {
    has threshold_days: int = 30;
    has developer_mode: bool = False;
    has rejected: list[str] = [];
    has accepted: list[str] = [];

    can start with Root entry {
        print(f"Age gate threshold = {self.threshold_days} days "
              f"(developer_mode={self.developer_mode})");
        visit [-->];
    }

    can check with Package entry {
        status = "ACCEPTED" if here.available else "REJECTED";
        if here.available {
            if self.developer_mode {
                self.accepted.append(here.name);
                status = "BYPASSED";
            } elif here.age_days <= self.threshold_days {
                self.accepted.append(here.name);
            } else {
                self.rejected.append(here.name);
                status = "REJECTED";
            }
        } else {
            self.rejected.append(here.name);
        }
        print(f"[{status}] {here.name} (age={here.age_days}d, "
              f"available={here.available})");
        visit [->:DependsOn:->];
    }
}

walker StrictChecker {
    has threshold_days: int = 30;
    has rejected: list[str] = [];
    has accepted: list[str] = [];

    can start with Root entry {
        print(f"Strict age gate threshold = {self.threshold_days} days");
        visit [-->];
    }

    can check with Package entry {
        status = "ACCEPTED" if here.available else "REJECTED";
        if here.available {
            if here.age_days <= self.threshold_days {
                self.accepted.append(here.name);
            } else {
                self.rejected.append(here.name);
                status = "REJECTED";
            }
        } else {
            self.rejected.append(here.name);
        }
        print(f"[{status}] {here.name} (age={here.age_days}d)");
        visit [->:DependsOn:->];
    }
}

