"""Factory floor supervision: dynamic child regions under a supervisor.

Models the essential scenario from issue #38 — supervisor/child-region
relationships with explicit supervision, cancellation propagation,
recovery, and an atomic commit boundary for child outputs.
"""

node Region {
    has name: str = "";
    has epoch: int = 0;
    has blocked: bool = False;
    has cancelled: bool = False;
    has succeeded: bool = False;
    has failed: bool = False;
    has abandoned: bool = False;
    has has_output: bool = False;
    has output_value: str = "";
}

node Worker {
    has name: str = "";
    has work_done: str = "";
}

edge Supervises { has budget: int = 3; }
edge Assigned { has slot: str = ""; }
edge CommitEdge { }

walker Cascade {
    can start with Root entry {
        visit [->:Supervises:->];
    }

    can supervise with Region entry {
        report_count = 0;
        for child in [->:Supervises:->:Region] {
            report_count += 1;
            here.cancelled = True;
            here.epoch += 1;
            child.cancelled = True;
            child.epoch += 1;
        }
        print(f"supervisor {here.name} cancelled {report_count} descendant(s)");
    }
}

walker Auditor {
    has total_regions: int = 0;
    has terminal_count: int = 0;
    has published_count: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can tally with Region entry {
        self.total_regions += 1;
        if here.succeeded or here.failed or here.cancelled or here.abandoned {
            self.terminal_count += 1;
        }
        if here.has_output {
            self.published_count += 1;
        }
        visit [-->];
    }
}

walker Commit {
    can start with Root entry {
        visit [->:CommitEdge:->];
    }

    can finalize with Region entry {
        for child in [->:Supervises:->] {
            if child.has_output and not child.cancelled and not child.abandoned {
                here.output_value = child.output_value;
                here.has_output = True;
                print(f"committed {child.output_value} -> {here.name}");
            } else {
                print(f"rejected {child.name} (history preserved, no stale publish)");
            }
        }
    }
}

with entry {
    parent = Region(name="floor-A");
    line1 = Region(name="line-1");
    line2 = Region(name="line-2");

    parent +>:Supervises(budget=3):+> line1;
    parent +>:Supervises(budget=3):+> line2;

    line1 +>:CommitEdge:+> Region(name="line-1-output", has_output=True, output_value="batch-7");
    line2 +>:CommitEdge:+> Region(name="line-2-output");

    root ++> parent ++> line1 ++> line2;

    worker_a = Worker(name="alice");
    worker_b = Worker(name="bob");
    line1 +>:Assigned(slot="alpha"):+> worker_a;
    line2 +>:Assigned(slot="beta"):+> worker_b;
    root ++> worker_a ++> worker_b;

    line1.failed = True;
    line2.abandoned = True;

    parent spawn Cascade();
    root spawn Auditor();
    parent spawn Commit();

    print("supervision/cancellation/atomic-commit demo complete");
}
