"""Restaurant kitchen line health-inspection walker.

The walker visits each station on the kitchen line (grill, fryer, cold prep)
and performs two checks at every station:
  1. Temperature check — flag any station whose temperature exceeds 40 C.
  2. Visit log — record every station visited along the line.

Both checks must run at every station, so they are expressed as separate
walker abilities that each trigger on every station type via a union
trigger (``with Grill | Fryer | ColdPrep entry``).
"""

node Station {
    has name: str = "";
    has temperature: float = 0.0;
    has violation: bool = False;
}

node Grill(Station) {}
node Fryer(Station) {}
node ColdPrep(Station) {}

edge NextStation {}

walker HealthInspector {
    has violations: list = [];
    has visit_log: list = [];

    can start with Root entry {
        print(f"Inspector starting kitchen line check at {self.visit_log.__len__()} prior visits");
        visit [->:NextStation:->];
    }

    can check_temp with Grill | Fryer | ColdPrep entry {
        flag = here.temperature > 40.0;
        here.violation = flag;
        if flag {
            self.violations.append(here.name);
            print(f"[VIOLATION] {here.name} at {here.temperature} C exceeds 40 C");
        } else {
            print(f"[OK] {here.name} at {here.temperature} C");
        }
    }

    can log_visit with Grill | Fryer | ColdPrep entry {
        self.visit_log.append(here.name);
        print(f"  -> logged visit to {here.name}");
    }

    can advance with Grill | Fryer | ColdPrep entry {
        visit [->:NextStation:->] else { disengage; }
    }
}

with entry {
    grill = Grill(name="Grill", temperature=85.0);
    fryer = Fryer(name="Fryer", temperature=175.0);
    cold = ColdPrep(name="ColdPrep", temperature=4.0);
