Issue #138: The eslint pin is end-of-life and no dependency tooling can see it

## Description

`eslint.yml` installs its linter with `npm install --no-save --no-package-lock
--no-audit --no-fund eslint@8.57.1`. That version is end of life.

Nothing will ever report it. This repository ships no `package.json` — a
deliberate choice — so Dependabot's npm ecosystem has no manifest to read, and
the `dependabot.yml` npm entry cannot see a version pinned inside a workflow
`run:` line. The repository has a test asserting that Dependabot watches every
manifest kind the repo tracks, and it passes, because this pin is not in a
manifest.

So the JavaScript linter is frozen at an unsupported release and the staleness
is invisible to every mechanism here that exists to surface staleness.

## Expected Behavior

Either the linter is on a supported release, or its version is visible to
something that reports when it moves — the same way `scripts/check_versions.py`
makes the project's own version drift visible.

## Environment / Context

- `main` at `07f19aba8ae7b5acd50b224c2c5aab4f8a07effd`
- `.github/workflows/eslint.yml` line 72 pins `eslint@8.57.1`
- `.eslintrc.json` is eslintrc format, which eslint 9 does not read by default
- No `package.json` anywhere in the tree

## Discovered During

A CI coverage review by the maintainer, 2026-08-24.

## Suggested Fix

Unverified, and these are alternatives rather than steps: migrate to **eslint
10** with a flat `eslint.config.js`, or keep a pin and make it visible to the
version-consistency checking so a stale pin is reported.

Target 10 rather than 9: eslint 9.x reached end of life on 2026-08-06, so a
migration to 9 would land on an unsupported release the day it merged. eslint
10 does not read `.eslintrc.json` at all — flat config is the only format —
so the migration is a config rewrite rather than a version bump, which is what
the difficulty on this issue reflects.

Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.

```jac
"""CI tooling version-pinning audit: a dependency-tool blind spot demo.

Models the eslint version-pin visibility problem as a graph. Workflows,
dependency manifests, and version-check scripts are nodes; the relationships
(pins, watches, audits) are typed edges. An auditor walker traverses the
graph, reports which pins are watched by version-consistency tooling, and
flags any pin that is invisible — the same blind spot Dependabot and
``scripts/check_versions.py`` would have for ``eslint@8.57.1``.
"""

node Workflow {
    has name: str = "";
    has runner: str = "github-actions";
    has has_manifest: bool = False;
}

node Manifest {
    has kind: str = "";
    has present: bool = False;
}

node VersionCheck {
    has name: str = "";
    has ecosystems: list[str] = [];
    has active: bool = True;
}

node Pin {
    has tool: str = "";
    has version: str = "";
    has host: str = "";
    has end_of_life: bool = False;
    has supported: bool = True;
}

# A workflow that runs a tool with a pinned version. Carries the pin's host.
edge PinnedIn {
    has line: int = 0;
}

# A manifest that a version-check script watches.
edge WatchedBy {
    has since: str = "";
}

# A pin that a version-check script can actually see.
edge AuditedBy {
    has confidence: float = 0.0;
}

# A pin that no version-check script can see.
edge InvisibleTo {
    has reason: str = "";
}

walker Auditor {
    has report: list[str] = [];
    has discovered_pins: int = 0;
    has invisible_pins: int = 0;

    can begin with Root entry {
        visit [-->];
    }

    can land with Workflow entry {
        here_reports: list[str] = [];
        for pin in [-->](?:Pin) {
            self.discovered_pins += 1;
            line = -1;
            for e in [edge -->](?:PinnedIn) {
                if e._jac_edge_src is pin {
                    line = e.line;
                }
            }
            host_msg = f"workflow '{here.name}' pins {pin.tool}@{pin.version}";
            if line > 0 {
                host_msg += f" (line {line})";
            }
            if pin.end_of_life {
                host_msg += " [EOL]";
            }
            here_reports.append(host_msg);
        }
        for msg in here_reports {
            self.report.append(msg);
        }
        visit [-->];
    }

    can catalog with Manifest entry {
        visit [-->];
    }

    can trace with VersionCheck entry {
        visit [-->];
    }

    can pin_inspect with Pin entry {
        watched = [-->](?:AuditedBy);
        if not watched {
            self.invisible_pins += 1;
            warn = (f"BLIND SPOT: {here.tool}@{here.version} "
                    f"on {here.host} is invisible to every "
                    f"version-consistency checker");
            self.report.append(warn);
        } else {
            seen = f"OK: {here.tool}@{here.version} on {here.host} is audited";
            self.report.append(seen);
        }
    }
}

with entry {
    # Workflows in the repo.
    eslint_wf = Workflow(name="eslint.yml", has_manifest=False);
    ci_wf = Workflow(name="ci.yml", has_manifest=True);
    root ++> eslint_wf ++> ci_wf;

    # The two manifests the repo does track.
    pyproject = Manifest(kind="pyproject.toml", present=True);
    jac_toml = Manifest(kind="jac.toml", present=True);
    ci_wf ++> pyproject ++> jac_toml;

    # A version-check script that only sees the manifests — never workflow run lines.
    checker = VersionCheck(
        name="check_versions.py",
        ecosystems=["python", "jac"],
    );
    root ++> checker;

    # The blind spot: eslint is pinned inside a workflow run, no manifest,
    # so nothing watches it.
    eslint_pin = Pin(
        tool="eslint",
        version="8.57.1",
        host="eslint.yml",
        end_of_life=True,
        supported=False,
    );
    eslint_wf +>:PinnedIn(line=72):+> eslint_pin;

    # A second pin, also inside a workflow, but a fresh version.
    actionlint_pin = Pin(
        tool="actionlint",
        version="1.6.27",
        host="ci.yml",
        end_of_life=False,
        supported=True,
    );
    ci_wf +>:PinnedIn(line=18):+> actionlint_pin;

    # The version-check script audits the manifests it can see.
    checker +>:WatchedBy(since="2026-01-01"):+> pyproject;
    checker +>:WatchedBy(since="2026-01-01"):+> jac_toml;

    # Even if checker tried to audit a pin directly, it cannot — it has no
    # edge archetype that connects it to a Pin, only WatchedBy to Manifests.
    # So the pins remain InvisibleTo checker.
    eslint_pin +>:InvisibleTo(reason="pinned in workflow run, no manifest"):+> checker;
    actionlint_pin +>:InvisibleTo(reason="pinned in workflow run, no manifest"):+> checker;

    # Run the audit.
    auditor = Auditor();
    root spawn auditor;

    print("=== CI tooling version-pin audit ===");
    for line in auditor.report {
        print(line);
    }
    print(f"\ndiscovered pins: {auditor.discovered_pins}");
    print(f"invisible to version checks: {auditor.invisible_pins}");
    print("a stale pin is now visible to a tool that reports when it moves");
}
