"""Dependency pin linter: model linter tooling as graph nodes and walk the
chain to surface stale version pins that nothing else can see.

The issue: a CI workflow pins `eslint@8.57.1` inline inside a `run:` step,
but no `package.json` exists so Dependabot's npm ecosystem has nothing to
read. The staleness is invisible. We model that visibility gap as a graph:
the manifest registry knows about package.json pins, the workflow registry
knows about inline `run:` pins, and a walker audits both to report which
linter tools are EOL.
"""

node Tool {
    has name: str = "";
    has version: str = "";
    has eol: bool = False;
}

node ManifestPin {
    has ecosystem: str = "npm";

    def tool() -> Tool | None {
        return self.hosted_tool;
    }

    has hosted_tool: Tool | None = None;
}

node WorkflowPin {
    has workflow: str = "";
    has run_line: int = 0;
    has pinned_version: str = "";

    has hosted_tool: Tool | None = None;

    def tool() -> Tool | None {
        return self.hosted_tool;
    }
}

node VersionCheck {
    has last_seen: str = "";
}

edge VersionOf { }
edge AuditedBy { }

walker StalePinAuditor {
    has findings: list[str] = [];
    has seen: list[Tool] = [];
    has depth: int = 0;
    has max_depth: int = 32;

    can start with Root entry {
        visit [-->];
    }

    can scan with Tool entry {
        if self.depth > self.max_depth {
            disengage;
        }
        for t in self.seen {
            if t.name == here.name and t.version == here.version {
                disengage;
            }
        }
        self.seen.append(here);
        label = "STALE" if here.eol else "OK";
        msg = f"[{label}] {here.name}@{here.version}";
        self.findings.append(msg);
        if here.eol {
            print(f"  -> reporting: {msg}");
        }
        visit [->:VersionOf:->];
    }

    can inspect_pin with ManifestPin | WorkflowPin entry {
        tool_ref = here.tool();
        if tool_ref is None {
            disengage;
        }
        self.depth += 1;
        visit [tool_ref];
    }

    can finish with VersionCheck entry {
        print("audit complete; no version-check entries reachable");
        disengage;
    }
}

with entry {
    eslint_8 = Tool(name="eslint", version="8.57.1", eol=True);
    eslint_10 = Tool(name="eslint", version="10.0.0", eol=False);

    pkg_manifest = ManifestPin(ecosystem="npm", hosted_tool=eslint_10);
    workflow_inline = WorkflowPin(
        workflow="eslint.yml",
        run_line=72,
        pinned_version="8.57.1",
        hosted_tool=eslint_8
    );
    version_check = VersionCheck(last_seen="2026-08-24");

    root +>:VersionOf:+> pkg_manifest;
    root +>:VersionOf:+> workflow_inline;
    root +>:AuditedBy:+> version_check;

    print("=== stale-pin auditor over manifest + workflow pins ===");
    auditor = StalePinAuditor();
    root spawn auditor;

    print("\nfindings:");
    for f in auditor.findings {
        print(f"  {f}");
    }
}

