"""Wake delivery audit: instant no-receipt failure on live-but-quiet tmux panes.

Models the #1032 scenario. Two delivery paths (primary + watchdog) share a
live pane; both fire instant-no-receipt because the pane is connected but
quiescent. An independent recovery probe runs from a separate session path
and stamps the pane alive, mirroring the gomez :15 cross-session design
note. A walker audits the failure surface by traversing the durable queue.
"""

node ScheduleSource {
    has label: str = "";
    has last_delivered: str = "never";
}

node TmpPane {
    has pane_id: str = "";
    has connected: bool = True;
    has quiet: bool = True;
    has wake_attempts: int = 0;
    has instant_failures: int = 0;
    has recovered: bool = False;
}

node RecoveryProbe {
    has origin_session: str = "cross-session";
    has successes: int = 0;
}

edge FiresInto {
    has window: str = "";
}

edge WakesPane {
    has attempts: int = 0;
}

edge StampsPane {
    has session: str = "";
}

walker Auditor {
    has findings: list[str] = [];

    can begin with Root entry {
        print(f"Auditor starting across {len([-->])} sources");
        visit [-->];
    }

    can inspect_source with ScheduleSource entry {
        print(f"source {here.label}: last_delivered={here.last_delivered}");
        visit [->:FiresInto:->];
    }

    can inspect_pane with TmpPane entry {
        here.wake_attempts += 1;
        # (b) instant-no-receipt path: connected-but-quiet pane
        if here.connected and here.quiet {
            here.instant_failures += 1;
            verdict = "INSTANT_NO_RECEIPT";
        } else {
            verdict = "OK";
        }
        self.findings.append(
            f"pane={here.pane_id} attempts={here.wake_attempts} "
            f"failures={here.instant_failures} verdict={verdict}"
        );
        print(f"[{verdict}] pane {here.pane_id} (quiet={here.quiet})");
        visit [-->];
    }

    can inspect_probe with RecoveryProbe entry {
        print(f"probe origin={here.origin_session} successes={here.successes}");
        visit [-->];
    }
}

walker IndependentDrain {
    has session: str = "gomez-cross-session";

    can begin with Root entry {
        print(f"Independent drain from {self.session}");
        visit [-->];
    }

    can drain_source with ScheduleSource entry {
        # Find live-but-quiet panes on this source and stamp them
        for pane in [->:FiresInto:->][?:TmpPane] {
            if pane.connected and pane.quiet and not pane.recovered {
                pane.recovered = True;
                self.session = f"{self.session}->{pane.pane_id}";
                print(f"indep drain stamped {pane.pane_id} alive");
                visit [->:StampsPane:->];
                return;
            }
        }
        visit [-->];
    }

    can stamp_pane with TmpPane entry {
        print(f"  recovery stamp applied to {here.pane_id}");
    }
}

with entry {
    p5  = TmpPane(pane_id="pane-5am",  connected=True, quiet=True);
    p6  = TmpPane(pane_id="pane-6am",  connected=True, quiet=True);
    p10 = TmpPane(pane_id="pane-10am", connected=True, quiet=True);

    s = ScheduleSource(label="hourly-wake");
    s +>:FiresInto(window="05:00"):+> p5;
    s +>:FiresInto(window="06:00"):+> p6;
    s +>:FiresInto(window="10:00"):+> p10;

    probe = RecoveryProbe(origin_session="gomez:15");
    s +>:StampsPane(session="gomez:15"):+> probe;

    root ++> s ++> probe;

    root spawn Auditor();
    print("--- independent drain (different session path) ---");
    root spawn IndependentDrain();
    print("--- re-audit after independent drain ---");
    root spawn Auditor();
}
