"""Build system dependency graph: audit tasks once even if reachable by multiple paths.

Demonstrates explicit visited-set cycle policy in a walker (jac 0.36.1
walkers have no built-in once-per-node visitation), then sums the
minutes every task consumes while preserving the "audit exactly once"
domain rule.
"""

node Task {
    has name: str = "";
    has minutes: int = 0;
}

walker Auditor {
    has visited: set = {};
    has total_minutes: int = 0;

    can start with Root entry {
        print("Auditing build graph from root");
        visit [-->];
    }

    can audit with Task entry {
        if here.name in self.visited {
            print(f"[skip already audited] {here.name}");
            visit [-->];
            return;
        }
        self.visited.add(here.name);
        label = "COUNTED" if here.minutes > 0 else "ZERO";
        print(f"[{label}] {here.name} ({here.minutes} min)");
        self.total_minutes = self.total_minutes + here.minutes;
        visit [-->];
    }
}

with entry {
    # Diamond shape:
    #   root -> A -> C -> D
    #   root -> B -> C (same C as above, different path)
    #   root -> B -> E
    root ++> Task(name="A", minutes=5)
        ++> Task(name="C", minutes=10)
        ++> Task(name="D", minutes=2);
    root ++> Task(name="B", minutes=7);
    Task(name="B") ++> Task(name="C");
    Task(name="B") ++> Task(name="E", minutes=3);

    auditor = Auditor();
    root spawn auditor;
    print(f"Total build minutes (audited exactly once per task): {auditor.total_minutes}");
}
