Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.

```jac
"""Multiplex orderbook: model the trader ↔ kx_orderbooks coupling audit.

The kx_orderbooks engine fans a single broadcast feed out to per-channel
orderbooks. The trader subscribes to those books and reacts. The original
project hand-rolled the wiring with parent_id maps and ad-hoc recursion;
here we lift the relationship into typed edges and let a walker do the
audit the issue asks for: enumerate call sites, flag duplicated protocol
code, and detect cross-channel dependency cycles.
"""

# ---------------------------------------------------------------------------
# Entity archetypes
# ---------------------------------------------------------------------------

node Module {
    has name: str = "";
    has loc: int = 0;
    has duplicates_protocol: bool = False;
}

node Book {
    has channel: str = "";
    has kind: str = "snapshot";
    has stale: bool = False;
}

edge Imported {
    has from_module: str = "";
    has to_module: str = "";
}

edge Subscribes {
    has channel: str = "";
}

edge DependsOn {
    has weight: int = 1;
}

# ---------------------------------------------------------------------------
# Walker: CouplingAuditor
# ---------------------------------------------------------------------------

walker CouplingAuditor {
    has report_lines: list[str] = [];
    has visited: list[str] = [];
    has cycle_found: bool = False;
    has dup_sites: list[str] = [];

    can start with Root entry {
        print("=== Coupling audit: trader ↔ kx_orderbooks ===");
        visit [-->];
    }

    can audit_module with Module entry {
        key = here.name;
        already = False;
        for v in self.visited {
            if v == key {
                already = True;
            }
        }
        if already {
            return;
        }
        self.visited.append(key);
        self.report_lines.append(
            f"module {here.name} ({here.loc} LOC)"
        );
        if here.duplicates_protocol {
            site = f"{here.name} re-implements WS protocol handling";
            self.dup_sites.append(site);
            self.report_lines.append(f"  ! {site}");
        }
        visit [->:Imported:->];
    }

    can audit_book with Book entry {
        line = f"book channel={here.channel} kind={here.kind}";
        if here.stale {
            line = line + " STALE";
        }
        self.report_lines.append(f"  -> {line}");
        visit [->:Subscribes:->];
    }

    can find_cycles with Module entry {
        nexts = here->:DependsOn:->;
        for n in nexts {
            edge_line = f"{here.name} --{n.name}--";
            self.report_lines.append(f"  cycle probe: {edge_line}");
            if n.name == self.visited[0] and len(self.visited) > 1 {
                self.cycle_found = True;
                self.report_lines.append(
                    f"  CYCLE: {' -> '.join(self.visited)} -> {n.name}"
                );
            }
        }
        visit [->:DependsOn:->];
    }
}

# ---------------------------------------------------------------------------
# Demo wiring
# ---------------------------------------------------------------------------

with entry {
    # Engine + trader modules.
    engine = Module(name="kx_orderbooks", loc=1200, duplicates_protocol=False);
    trader = Module(name="kalshi_broadcast_word_trader", loc=8000,
        duplicates_protocol=True);
    feed = Module(name="feed_adapter", loc=300, duplicates_protocol=True);

    # Per-channel books the engine maintains.
    book_fast = Book(channel="fast", kind="delta");
    book_snap = Book(channel="snap", kind="snapshot");

    # Typed edges.
    engine +>:Imported((
        from_module="kx_orderbooks", to_module="feed_adapter"
    )):+> feed;
    trader +>:Imported((
        from_module="kalshi_broadcast_word_trader", to_module="kx_orderbooks"
    )):+> engine;
    trader +>:Imported((
        from_module="kalshi_broadcast_word_trader", to_module="feed_adapter"
    )):+> feed;

    engine +>:Subscribes(channel="fast"):+> book_fast;
    engine +>:Subscribes(channel="snap"):+> book_snap;
    trader +>:Subscribes(channel="fast"):+> book_fast;

    # Cross-channel dependency that closes a cycle: fast depends on snap,
    # snap depends on fast. This is the issue's "recommend single source
    # of truth" warning sign.
    book_fast +>:DependsOn(weight=2):+> book_snap;
    book_snap +>:DependsOn(weight=2):+> book_fast;

    root spawn CouplingAuditor();

    auditor = CouplingAuditor();
    root spawn auditor;

    print("\n--- import map ---");
    for line in auditor.report_lines {
        print(line);
    }
    print("\n--- recommendation ---");
    if auditor.dup_sites {
        print("single source of truth: route all WS frames through "
              "kx_orderbooks; remove duplicated protocol code at:");
        for line in auditor.dup_sites {
            print(f"  - {line}");
        }
    }
    if auditor.cycle_found {
        print("WARNING: circular book dependency detected -- break the "
              "cycle before P1 perf work.");
    } else {
        print("no cross-channel cycles observed");
    }
}
