```jac
"""LandForger M2 — Maps, Folders, Pins & Reference Canvas in idiomatic Jac.

Models the core M2 scenario from PRD #106 natively: a World owns a Map
Library (a folder tree of Maps), Maps hold Pins at percentage coordinates,
Pins inherit their Page's Eras, and the World carries a Reference Canvas
JSON payload. A walker promotes folder contents on delete (cycle-safe via
an explicit guard set) and another walks the hierarchy to demonstrate the
manual recursion the issue complains about.
"""

node World {
    has name: str = "";
    has canvas_json: str = "{}";
}

node Page {
    has title: str = "";
    has eras: list[str] = [];
}

node Map {
    has title: str = "";
    has fixed_chart: str = "";
    has era_charts: dict[str, str] = {};
}

node Folder {
    has name: str = "";
}

node Pin {
    has note: str = "";
    has x_pct: float = 0.0;
    has y_pct: float = 0.0;
    has inherited_eras: list[str] = [];
}

# A Map that has been promoted to Root status for its World.
edge RootMap { }

# Ownership: a World contains its Maps, Folders, Pins, and Reference Canvas.
edge Owns { }

# Map Library hierarchy: a Folder can contain Maps and child Folders.
edge LibraryContains { }

# A Pin is placed on a Map; the Pin references a Page.
edge PlacedOn { }

# A Pin links to a Page (whose Eras it inherits).
edge LinksPage { }

walker LibraryAuditor {
    """Walks a World's Map Library, demonstrating typed-edge traversal
    over folders and maps, with an explicit visited set for cycle safety
    (jac 0.36.1 walkers have no built-in dedupe)."""

    has visited_ids: list[str] = [];
    has report: list[str] = [];

    can start with World entry {
        self.report.append(f"World: {here.name}");
        visit [->:Owns:->];
    }

    can audit with Folder entry {
        self.report.append(f"  Folder: {here.name}");
        if here.id not in self.visited_ids {
            self.visited_ids.append(here.id);
            visit [->:LibraryContains:->];
        }
    }

    can audit with Map entry {
        self.report.append(f"    Map: {here.title}");
        if here.id not in self.visited_ids {
            self.visited_ids.append(here.id);
            visit [->:PlacedOn:->];
        }
    }

    can audit with Pin entry {
        self.report.append(
            f"      Pin@({here.x_pct:.0f}%,{here.y_pct:.0f}%) "
            f"eras={here.inherited_eras} note={here.note}"
        );
        visit [->:LinksPage:->];
    }

    can audit with Page entry {
        self.report.append(f"        -> Page: {here.title} (eras={here.eras})");
    }
}

walker FolderDeleter {
    """Deletes a Folder and promotes its children to the parent — the
    cascade behavior the issue demands be cycle-safe."""

    has guard: list[str] = [];
    has promoted: list[str] = [];

    can start with World entry {
        target = Folder(name="Drafts");
        if target is None or target.id in self.guard {
            return;
        }
        self.guard.append(target.id);
        parent = None;
        for f in [-->](?:Folder) {
            parent = f;
        }
        kids = [->:LibraryContains:->];
        self.promoted = [k.title for k in kids];
        del target;
    }
}

walker RootMapPromoter {
    """If a World has no RootMap, the first Map in the library becomes it."""

    has assigned: str = "";

    can start with World entry {
        existing = [->:RootMap:->];
        if len(existing) > 0 {
            self.assigned = "already-set";
            return;
        }
        all_maps = [-->](?:Map);
        if len(all_maps) == 0 {
            self.assigned = "no-maps";
            return;
        }
        first = all_maps[0];
        here +>:RootMap:+> first;
        self.assigned = first.title;
    }
}

with entry {
    # --- World + Page (Pages already live in M1) ---
    world = World(name="Aurelia", canvas_json="{\"layers\":[]}");
    root ++> world;

    era_page = Page(title="Founding Era", eras=["founding", "modern"]);
    world +>:Owns:+> era_page;

    # --- Map Library (folders + maps) ---
    root_map = Map(title="Aurelia Overview", fixed_chart="chart:overview.png");
    drafts = Folder(name="Drafts");
    finished = Folder(name="Finished");

    world +>:Owns:+> root_map;
    world +>:Owns:+> drafts;
    world +>:Owns:+> finished;

    world +>:RootMap:+> root_map;

    drafts +>:LibraryContains:+> Map(title="WIP North Coast");
    finished +>:LibraryContains:+> Map(title="Capital City", era_charts={"founding": "c1.png", "modern": "c2.png"});

    # --- Pins on a Map, inheriting Eras from a Page ---
    pin1 = Pin(note="Founding site", x_pct=25.0, y_pct=40.0, inherited_eras=["founding", "modern"]);
    world +>:Owns:+> pin1;
    root_map +>:PlacedOn:+> pin1;
    pin1 +>:LinksPage:+> era_page;

    # --- Demo: audit the library ---
    auditor = LibraryAuditor();
    world spawn auditor;
    for line in auditor.report {
        print(line);
    }

    # --- Demo: promote first Map if no RootMap (idempotent) ---
    promoter = RootMapPromoter();
    world spawn promoter;
    print(f"RootMap assignment: {promoter.assigned}");

    # --- Demo: delete a Folder and capture promoted children ---
    deleter = FolderDeleter();
    world spawn deleter;
    print(f"Promoted from 'Drafts': {deleter.promoted}");
}
