"""Cost-ceiling plan approval: model the missing assistant message append.

Models the issue where the final assistant message is lost because it is not
appended to the transcript before awaiting plan approval. A walker traverses
the plan transcript and proves that persistence order matters.
"""

node Message {
    has role: str = "";
    has content: str = "";
    has persisted: bool = False;
}

node PlanStep {
    has title: str = "";
    has est_cost: float = 0.0;
}

node Transcript {
    has name: str = "";
    has approved: bool = False;
    has over_budget: bool = False;
}

edge Follows {}
edge StepOf {}
edge OwnedBy {}

walker ApprovalWalk {
    has path: list = [];
    has transcript_seen: str = "";

    can start with Root entry {
        visit [->:OwnedBy:->];
    }

    can enter_transcript with Transcript entry {
        self.transcript_seen = here.name;
        print(f"Entering transcript: {here.name} (approved={here.approved})");
        # Walk the messages first (chronological), then the plan steps.
        visit [->:Follows:->];
    }

    can collect_message with Message entry {
        label = "PERSISTED" if here.persisted else "LOST";
        print(f"  msg[{here.role}] {label}: {here.content}");
        self.path.append((here.role, here.persisted));
        visit [-->];
    }

    can review_step with PlanStep entry {
        if here.est_cost > 500.0 {
            here.est_cost = 500.0;
            print(f"  cost-ceiling clamped step '{here.title}' to 500.0");
        }
        self.path.append(("step", here.title));
        visit [-->];
    }

    can finalize with Transcript exit {
        last_role = "";
        last_persisted = True;
        for item in self.path {
            last_role = item[0];
            last_persisted = item[1];
        }
        if last_role == "assistant" and not last_persisted {
            print("BUG: final assistant message was NEVER appended before approval");
        } else {
            print("OK: final assistant message persisted before approval");
        }
        report self.path;
    }
}

