"""Reports module: published reports are world-readable; unpublished ones
fall back to per-instance grants. A Report archetype overrides a hook to
return a READ level when published and None otherwise. A Publish walker
flips the flag and drops the now-redundant grant."""

node Report {
    has title: str = "";
    has published: bool = False;
    has owner: str = "";

    # The archetype hook. Returns a READ level when published,
    # None otherwise so drafts stay closable while owners can still
    # share them selectively via grants.
    def access_level() -> str | None {
        level: str | None = None;
        if self.published {
            level = "READ";
        }
        return level;
    }
}

edge Grant {
    has grantee: str = "";
    has level: str = "READ";
}

walker Publish {
    has grant_target: str = "owner";

    can start with Root entry {
        visit [-->];
    }

    can consider with Report entry {
        if not here.published {
            here.published = True;
            print(f"Published: {here.title} (owner={here.owner})");

            # Drop the now-redundant grant, if one exists.
            edges_to_drop = [edge here ->:Grant:-> grantee: str];
            for ed in edges_to_drop {
                # typed disconnect on the Grant edge
                here del ->:Grant:-> grantee;
                print(f"  dropped grant for {grantee}");
            }
        }
        visit [-->] else { disengage; }
    }
}

walker Auditor {
    can start with Root entry {
        visit [-->];
    }

    can inspect with Report entry {
        level = here.access_level();
        if level is None {
            label = "CLOSED";
        } else {
            label = level;
        }
        print(f"[{label}] {here.title} (published={here.published})");
        visit [-->] else { disengage; };
    }
}

with entry {
    draft = Report(title="Q1 financials", published=False, owner="alice");
    live = Report(title="Q4 retrospective", published=True, owner="bob");

    root ++> draft;
    root ++> live;

    # Pre-existing selective share for the draft owner — becomes
    # redundant once the report is published.
    draft +>:Grant(grantee="alice", level="READ"):+> draft;

    root spawn Auditor();
    root spawn Publish();
    print("--- after publishing ---");
    root spawn Auditor();
}
