```jac
"""Scene-graph render-time traversal: model the issue's hot path in native Jac.

The original pygfx problem is that every render call walks the whole scene
graph to bucket objects into lights / shadow casters / renderables and to
propagate ``group_order`` from each Group ancestor. The traversal itself is
the cost the issue complains about. We model that traversal as a native
walker over typed edges so the cost is paid by the language, not by
hand-rolled recursion.
"""

# A bare renderable object: the leaves of the scene graph.
node Object {
    has name: str = "";
    has geometry_kind: str = "mesh";
    has casts_shadow: bool = False;
}

# A Group is a container. Its ``order`` is propagated down to every
# renderable descendant during the render-time walk -- the exact cost the
# issue calls out as the bottleneck on deep hierarchies.
node Group {
    has name: str = "";
    has order: int = 0;
}

# A Light is bucketed separately from regular objects.
node Light {
    has name: str = "";
    has light_kind: str = "point";
}

# Typed edges carry the relationship. ``ParentOf`` models a Group holding
# children; ``VisibleIn`` models a renderable being a leaf of a subtree.
# Keeping them typed lets the walker traverse with a single typed visit
# rather than a manual isinstance + queue.
edge ParentOf { }
edge VisibleIn { }

# Renderer: builds a flat scene by walking the graph once. This is the
# O(N) per-frame cost the issue wants to eliminate -- we model it as the
# walker doing one explicit pass per spawn.
walker FlatSceneBuilder {
    has report: dict = {};

    can begin with Root entry {
        # First pass: visit the top-level scene nodes via the parent edge.
        visit [->:ParentOf:->] else { disengage; }
    }

    # Group ability: recurse into children, recording the current
    # ``order`` so every descendant below this point can inherit it.
    # This is the propagation the issue says is paid every frame.
    can descend with Group entry {
        print(f"enter Group {here.name} (order={here.order})");
        visit [here ->:ParentOf:->];
    }

    # Object ability: leaf node, contributes to the renderables bucket.
    # The cycle guard is explicit because Jac 0.36.1 walkers do not
    # dedupe by default on cyclic graphs (probe-verified).
    can collect_object with Object entry {
        status = "shadow" if here.casts_shadow else "draw";
        print(f"  [object/{status}] {here.name} kind={here.geometry_kind}");
        visit [here ->:VisibleIn:->] else { disengage; }
    }

    # Light ability: bucketed separately from Object leaves.
    can collect_light with Light entry {
        print(f"  [light/{here.light_kind}] {here.name}");
        visit [here ->:VisibleIn:->] else { disengage; }
    }
}

with entry {
    # Build a small scene:
    #   root
    #     Group "sky"        order=0
    #       Light "sun"      light_kind="directional"
    #       Light "ambient"  light_kind="ambient"
    #     Group "actors"     order=10
    #       Group "hero"     order=20
    #         Object "body"  geometry_kind="mesh", casts_shadow=True
    #         Object "cape"  geometry_kind="mesh", casts_shadow=True
    #       Object "ground"  geometry_kind="plane", casts_shadow=False

    sky = Group(name="sky", order=0);
    actors = Group(name="actors", order=10);
    hero = Group(name="hero", order=20);

    sun = Light(name="sun", light_kind="directional");
    ambient = Light(name="ambient", light_kind="ambient");

    body = Object(name="body", geometry_kind="mesh", casts_shadow=True);
    cape = Object(name="cape", geometry_kind="mesh", casts_shadow=True);
    ground = Object(name="ground", geometry_kind="plane", casts_shadow=False);

    # Typed parent edges: each Group holds its children via ParentOf.
    root +>:ParentOf:+> sky;
    root +>:ParentOf:+> actors;
    actors +>:ParentOf:+> hero;

    # Lights sit under the sky group.
    sky +>:ParentOf:+> sun;
    sky +>:ParentOf:+> ambient;

    # Leaves are reached from their parent Group via VisibleIn.
    sun +>:VisibleIn:+> sun;
    ambient +>:VisibleIn:+> ambient;
    hero +>:VisibleIn:+> body;
    hero +>:VisibleIn:+> cape;
    actors +>:VisibleIn:+> ground;

    print("=== render-time flatscene build (one walker pass) ===");
    root spawn FlatSceneBuilder();
}
