"""Repo health audit: walk a repository graph and surface dependency / redacted-secret / dead-code findings.

Models the scenario from the issue: a repo with source files (some of which import
external packages, some contain secret tokens, some have unused imports). A
``RepoAuditor`` walker traverses the file tree and reports findings — replacing
the hand-rolled recursion over ``parent_id`` / adjacency maps with native Jac
walker traversal over typed ``ContainsFile`` edges.
"""

node File {
    has path: str = "";
    has imports: list[str] = [];
    has secrets: list[str] = [];
    has has_unused_import: bool = False;
    has size_lines: int = 0;
}

node Repo {
    has name: str = "";
}

edge ContainsFile {
    has order: int = 0;
}

edge DependsOn {
    has package: str = "";
}

walker RepoAuditor {
    has missing_deps: list[str] = [];
    has leaked_secrets: list[str] = [];
    has dead_imports: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can audit_repo with Repo entry {
        print(f"Auditing repo: {here.name}");
        visit [->:ContainsFile:->];
    }

    can inspect_file with File entry {
        # Dependency check — model the "missing numpy/openai/json_repair" finding.
        required = ["numpy", "openai", "json_repair"];
        for (pkg) in required {
            if pkg in here.imports {
                missing_dep = f"{here.path} imports {pkg}";
                self.missing_deps.append(missing_dep);
            }
        }
        # Redacted-secret detection — model the "DEEPSEEK_API_KEY" leak concern.
        risky_tokens = ["DEEPSEEK_API_KEY", "GITHUB_TOKEN", "LLM_BASE_URL"];
        for (tok) in risky_tokens {
            if tok in here.secrets {
