```jac
"""Docker doctor MCP: diagnostic scenario corpus modelled as a typed graph.

Core entities from the issue (subset):
  - ComposeProject / Service / Network / Dependency / ProbeFinding / RedactionFinding.

Relationships:
  - Project OWNS Service, Network
  - Service CONNECTS_TO Network
  - Service DEPENDS_ON Dependency (the dep can be Reachable, Refused, TimedOut,
    or DnsFailure; same edge archetype carries a status payload)
  - Service / Network / Dependency emit ProbeFinding (typed, has severity,
    category, evidence)

The ``DiagnosticAuditor`` walker is the OSP analogue of the hand-rolled
regression suite: it traverses the project graph over typed edges, applies
the rules (no external I/O), and collects verdicts into a single report.
"""

# ----------------------------- edge archetypes -----------------------------

edge Owns { }
edge ConnectsTo { has interface_name: str = ""; }
edge DependsOn { has status: str = "Reachable"; has latency_ms: int = 0; }
edge Emits { }

# ----------------------------- node archetypes -----------------------------

node Project {
    has name: str = "";
    has network_mode: str = "bridge";
}

node Service {
    has title: str = "";
    has image_tag: str = "";
    has has_digest: bool = False;
    has restart_count: int = 0;
    has stale_fatal_in_history: bool = False;
    has http_status: int = 200;
    has host_sensitive: bool = False;
    has origin_sensitive: bool = False;
}

node Network { has name: str = ""; }

node Dependency {
    has title: str = "";
    # status mirrors DependsOn.status semantics, kept here for direct lookup
    has status: str = "Reachable";
}

node Finding {
    has category: str = "";
    has severity: str = "info";   # info | warn | error
    has evidence: str = "";
}

# --------------------------- auditor walker --------------------------------

walker DiagnosticAuditor {
    has findings: list = [];
    has visited: list = [];

    can start with Project entry {
        self.visited.append(here.name);
        print(f"audit: project {here.name} mode={here.network_mode}");
        # First visit the networks owned by the project (typed edge).
        visit [->:Owns:->];
    }

    # Union trigger: same audit step for Service and Dependency so we touch
    # only fields shared by both (Finding-bearing node categories).
    can audit_artifact with Service | Dependency entry {
        label = here.title;
        findings = self.findings;

        # --- restart loop with real blocking error ---
        if label and here.restart_count >= 3 {
            findings.append(
                Finding(
                    category="restart_loop",
                    severity="error",
                    evidence=f"{label} restarted {here.restart_count}x",
                )
            );
        }

        # --- stale fatal in pre-restart history ---
        if label and here.stale_fatal_in_history {
            findings.append(
                Finding(
                    category="stale_fatal",
                    severity="info",
                    evidence=f"{label} history contains pre-restart fatal",
                )
            );
        }

        # --- HTTP behavior: 4xx / 5xx flagged ---
        if here.http_status >= 500 {
            findings.append(
                Finding(
                    category="http_5xx",
                    severity="error",
                    evidence=f"{label} HTTP {here.http_status}",
                )
            );
        } elif here.http_status >= 400 {
            findings.append(
                Finding(
                    category="http_4xx",
                    severity="warn",
                    evidence=f"{label} HTTP {here.http_status}",
                )
            );
        }

        # --- Host / Origin sensitivity regression scenarios ---
        if here.host_sensitive {
            findings.append(
                Finding(
                    category="host_header",
                    severity="warn",
                    evidence=f"{label} is host-sensitive",
                )
            );
        }
        if here.origin_sensitive {
            findings.append(
                Finding(
                    category="origin_header",
                    severity="warn",
                    evidence=f"{label} is origin-sensitive",
                )
            );
        }

        # --- dependency status (Reachable / Refused / TimedOut / DnsFailure) ---
        if here.status == "Refused" {
            findings.append(
                Finding(
                    category="tcp_refused",
                    severity="error",
                    evidence=f"dep {label} refused",
                )
            );
        } elif here.status == "TimedOut" {
            findings.append(
                Finding(
                    category="tcp_timeout",
                    severity="error",
                    evidence=f"dep {label} timed out",
                )
            );
        } elif here.status == "DnsFailure" {
            findings.append(
                Finding(
                    category="dns_resolution",
                    severity="error",
                    evidence=f"dep {label} DNS failed",
                )
            );
        } elif here.status == "Missing" {
            findings.append(
                Finding(
                    category="missing_dependency",
                    severity="error",
                    evidence=f"dep {label} missing",
                )
            );
        }

        visit [->:DependsOn:->];
    }

    can collect with Network entry {
        self.visited.append(here.name);
        print(f"audit: network {here.name}");
        visit [-->];
    }

    can finalize with Root entry {
        print(f"audit: complete, {len(self.findings)} findings");
        for f in self.findings {
            print(f"  [{f.severity}] {f.category}: {f.evidence}");
        }
        report self.findings;
    }
}

# ----------------------------- demo wiring ---------------------------------

with entry {
    proj = Project(name="shop", network_mode="bridge");

    # Healthy bridge-network Compose stack
    web = Service(title="web", image_tag="nginx:1.27", has_digest=True);
    api = Service(title="api", image_tag="api@sha256:deadbeef", has_digest=True);

    # Healthy host-network service
    host_svc = Service(title="agent", image_tag="agent:1.0", has_digest=True);

    # Current restart loop with a real blocking error
    worker = Service(
        title="worker",
        image_tag="worker:latest",
        has_digest=False,
        restart_count=5,
    );

    # Healthy service with a stale fatal in its pre-restart logs
    cache = Service(
        title="cache",
        image_tag="redis:7",
        has_digest=True,
        stale_fatal_in_history=True,
    );

    net_bridge = Network(name="shop_bridge");
    net_host = Network(name="host");

    dep_ok = Dependency(title="postgres", status="Reachable");
    dep_refused = Dependency(title="billing", status="Refused");
    dep_timeout = Dependency(title="legacy", status="TimedOut");
    dep_dns = Dependency(title="inventory", status="DnsFailure");
    dep_missing = Dependency(title="mailer", status="Missing");

    # Project owns services and networks.
    proj +>:Owns:+> web;
    proj +>:Owns:+> api;
    proj +>:Owns:+> worker;
    proj +>:Owns:+> cache;
    proj +>:Owns:+> host_svc;
    proj +>:Owns:+> net_bridge;
    proj +>:Owns:+> net_host;

    # Service → Network (typed ConnectsTo with interface name payload).
    web +>:ConnectsTo(interface_name="eth0"):+> net_bridge;
    api +>:ConnectsTo(interface_name="eth0"):+> net_bridge;
    cache +>:ConnectsTo(interface_name="eth1"):+> net_bridge;
    host_svc +>:ConnectsTo(interface_name="lo"):+> net_host;

    # Service → Dependency (typed DependsOn carries status payload).
    api +>:DependsOn(status="Reachable", latency_ms=3):+> dep_ok;
    api +>:DependsOn(status="Refused"):+> dep_refused;
    worker +>:DependsOn(status="TimedOut", latency_ms=30000):+> dep_timeout;
    worker +>:DependsOn(status="DnsFailure"):+> dep_dns;
    web +>:DependsOn(status="Missing"):+> dep_missing;

    # Each finding becomes an Emits edge from the source node so the
    # report relationship is also graph-shaped, mirroring the audit log.
    proj +>:Emits:+> Finding(
        category="healthy_bridge",
        severity="info",
        evidence="bridge stack healthy",
    );

    root ++> proj;
    auditor = DiagnosticAuditor();
    proj spawn auditor;
}
