"""Recursive synthesis lineage: a ConditionStore walked by a lineage walker.

The flock's synthesis layer used to query flat cluster membership
(`WHERE cluster_id = ?`) and never traversed `parent_id` chains. The
fix replaces that with a walker that walks the ancestry DAG up to a
depth cap, exactly the behaviour the recursive CTE was meant to
emulate. A second walker then promotes the deepest reachable ancestor
so the synthesizer can prefer second-order syntheses.
"""

node Finding {
    has title: str = "";
    has cluster_id: int = 0;
    has synthesis_depth: int = 0;
}

node Synthesis {
    has title: str = "";
    has cluster_id: int = 0;
    has synthesis_depth: int = 0;
}

edge ParentLink {
    has hop: int = 0;
}

walker Lineage {
    has max_depth: int = 10;
    has origin_id: str = "";
    has seen: list[str] = [];
    has chain: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can descend with Finding | Synthesis entry {
        here_id = str(id(here));
        if here_id in self.seen {
            disengage;
        }
        self.seen.append(here_id);
        self.chain.append(here.title);
        if len(self.chain) > self.max_depth {
            disengage;
        }
        visit [->:ParentLink:->] else {
            disengage;
        }
    }
}

walker PromoteAncestor {
    has max_depth: int = 10;
    has seen: list[str] = [];
    has deepest_title: str = "";
    has deepest_depth: int = -1;

    can start with Root entry {
        visit [-->];
    }

    can scan with Finding | Synthesis entry {
        here_id = str(id(here));
        if here_id in self.seen {
            disengage;
        }
        self.seen.append(here_id);
        if here.synthesis_depth > self.deepest_depth {
            self.deepest_depth = here.synthesis_depth;
            self.deepest_title = here.title;
        }
        if self.deepest_depth >= self.max_depth {
            disengage;
        }
        visit [->:ParentLink:->] else {
            disengage;
        }
    }
}

