"""Vote-state-pill cross-spec ordering: a walker audits the votes graph.

Models the essence of issue #785 — two e2e specs (UserProfile, VoteStatePill)
share a mutable votes table on the same season target. A cast-then-retract
chain from UserProfile silently empties the votes, so the next spec's
"anon viewer" assertion fails. We model the cast/retract lifecycle as a
walker over a votes graph and audit reachability + non-empty coverage
before the downstream pill spec runs.
"""

node Season {
    has target: str = "";
    has title: str = "";
}

node Vote {
    has voter: str = "";
    has value: int = 0;
}

node Spec {
    has name: str = "";
    has targets: list[str] = [];
}

edge CastOn {
    has at_tick: int = 0;
}

edge Audits {
    has order_index: int = 0;
}

walker AuditTrail {
    has cast_order: list[str] = [];
    has retract_count: int = 0;
    has visited_targets: list[str] = [];

    can start with Root entry {
        visit [->:Audits:->];
    }

    can pick_spec with Spec entry {
        print(f"[spec] {here.name} targets {here.targets}");
        visit [->:CastOn:->];
    }

    can record_vote with Vote entry {
        action = "CAST" if here.value == 1 else "RETRACT";
        self.cast_order.append(f"{action} by {here.voter} value={here.value}");
        if here.value == 0 {
            self.retract_count += 1;
        }
        visit [-->];
    }

    can summarize with Season entry {
        if here.target not in self.visited_targets {
            self.visited_targets.append(here.target);
        }
        has_any = len(self.cast_order) > 0;
        verdict = "OK" if has_any and self.retract_count < len(self.cast_order) else "PILL_BROKEN";
        print(f"[{verdict}] season={here.target} casts={len(self.cast_order)} retracts={self.retract_count}");
        print(f"  cast trail: {self.cast_order}");
    }
}

walker Reachability {
    has seen: list[str] = [];
    has has cycle: bool = False;

    can start with Season entry {
        self.seen.append(here.target);
        visit [->:CastOn:->];
    }

    can walk_vote with Vote entry {
        label = f"{here.voter}:{here.value}";
        if label in self.seen {
            self.has_cycle = True;
            disengage;
        }
        self.seen.append(label);
        visit [-->];
    }
}

with entry {
    survivor20 = Season(target="survivor:20", title="Survivor S20");
    root ++> survivor20;

    user_profile = Spec(name="user-profile", targets=["survivor:20"]);
    vote_pill = Spec(name="vote-state-pill", targets=["survivor:20"]);

    root +>:Audits(order_index=0):+> user_profile;
    root +>:Audits(order_index=1):+> vote_pill;

    user_profile +>:CastOn(at_tick=1):+> Vote(voter="e2e_user", value=1);
    user_profile +>:CastOn(at_tick=2):+> Vote(voter="e2e_user", value=0);
    user_profile +>:CastOn(at_tick=3):+> Vote(voter="e2e_user", value=1);

    vote_pill +>:CastOn(at_tick=1):+> Vote(voter="e2e_user", value=0);

    user_profile +>:CastOn:+> survivor20;
    vote_pill +>:CastOn:+> survivor20;

    print("=== AuditTrail walker: traces cast/retract across specs ===");
    root spawn AuditTrail();

    print("\n=== Reachability walker: detects cycle / voter reuse ===");
    survivor20 spawn Reachability();
}
