"""Tree storage: configurable depth walk over a parent-child graph.

Models the essence of TreeStorageService.find: a tree table with rows
linked by a parent_id column, walked by recursive CTE to a configurable
max depth. We lift the hand-rolled recursion into a typed-edge walker
that honors both the depth limit and a cycle guard (the recursive CTE
implicitly terminates because rows cannot re-parent themselves, but the
walker makes that policy explicit since Jac 0.36 has no built-in
visited-set dedup).
"""

node TreeRow {
    has row_id: int = 0;
    has slug: str = "";
    has payload: str = "";
    has depth: int = 0;
    has path: list[int] = [];
}

edge ParentLink {
    # Parent column equivalent. Carries no payload beyond identity.
}

walker DepthWalker {
    has max_depth: int = 3;
    has collected: list[TreeRow] = [];
    has seen: list[int] = [];

    can start with Root entry {
        # Anchor query: pick the seed row(s) by slug-equivalent.
        # In this demo the anchor is the row hanging off root with
        # slug "album:rock-101".
        visit [-->];
    }

    can descend with TreeRow entry {
        # Cycle guard: walker has no built-in visited dedup, so we
        # track row ids explicitly before recursing into children.
        if here.row_id in self.seen {
            disengage;
        }
        self.seen.append(here.row_id);
        self.collected.append(here);

        # Depth limit (the "make depth configurable" complaint).
        if here.depth >= self.max_depth {
            disengage;
        }

        # Recursive step: the CTE's `join cte on parent = cte.id`.
        # In Jac this is just `visit [->:ParentLink:->]`.
        visit [->:ParentLink:->];
    }
}

walker CascadeDelete {
    # Companion walker: when the source deletes a node, all transitive
    # children must be purged. Hand-rolled in SQL via recursive CTE;
    # in Jac the node deletion auto-purges remaining edges.
    has purged: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can collect with TreeRow entry {
        self.purged.append(here.slug);
        # No visit: deleting here is the side effect; the orchestrator
        # (the with entry block) tears down the node.
    }
}

with entry {
    # Build a small album tree:
    #   rock-101 (depth 0)
    #     -> hits (depth 1)
    #          -> 1985 (depth 2)
    #               -> track-a (depth 3)
    #                    -> remix (depth 4)   <-- beyond max_depth=3
    rock   = TreeRow(row_id=1, slug="album:rock-101", payload="Rock 101");
    hits   = TreeRow(row_id=2, slug="collection:hits", payload="Greatest Hits");
    y1985  = TreeRow(row_id=3, slug="year:1985", payload="1985 singles");
    trackA = TreeRow(row_id=4, slug="track:track-a", payload="Track A");
    remix  = TreeRow(row_id=5, slug="track:remix", payload="Remix EP");

    root ++> rock +>:ParentLink:+> hits +>:ParentLink:+> y1985
        +>:ParentLink:+> trackA +>:ParentLink:+> remix;

    # Find-walk: collect rows up to max_depth=3 starting from the anchor.
    root spawn DepthWalker(max_depth=3);

    print("Collected (slug, depth, path):");
    for row in DepthWalker.collected {
        path_str = ",".join([str(p) for p in row.path]);
        print(f"  {row.slug}  depth={row.depth}  path=[{path_str}]");
    }
    print(f"Walker halted at depth={DepthWalker.collected[-1].depth}, "
          f"max_depth=3 (the remix at depth 4 was not visited)");

    # Cascade-delete demo: spawn a CascadeDelete walker that gathers
    # slugs in deletion order, then the orchestrator tears the tree down.
    root spawn CascadeDelete();
    print("Cascade-delete order:");
    for slug in CascadeDelete.purged {
        print(f"  purge {slug}")
    }
    rock.del;
    print("Tree torn down; remaining edges auto-purged with rock");
}
