"""Blast-radius review: model contract changes and which downstream modules are affected.

The graph mirrors the connected-type diagram tooling: each Type is a node; edges
carry how one type uses another (creates, param, returns, field, extends, uses).
A ContractChange node records the dirty signature/field/method/export per type.
A walker traverses the graph, identifies every consumer (Y) of every changed
type (X), checks whether Y (or its tests) is in the changeset, and reports the
blast radius — distinguishing pure consumers (untested module is risky) from
glue consumers (untested module is expected, ask for e2e confirmation).
"""

node Type {
    has name: str = "";
    has kind: str = "class";
    has is_pure: bool = True;
    has in_changeset: bool = False;
    has tests_in_changeset: bool = False;
}

node ContractChange {
    has member_kind: str = "field";
    has member_name: str = "";
}

edge Creates { }
edge Param { }
edge Returns { }
edge Field { }
edge Extends { }
edge Uses { }
edge OwnsChange { }

walker BlastRadius {
    has report_lines: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can inspect_change with ContractChange entry {
        self.report_lines.append(f"Contract change: {here.member_kind} '{here.member_name}'");
        visit [->:OwnsChange:->];
    }

    can scan_consumers with Type entry {
        self.report_lines.append(f"  consumer Type '{here.name}' "
            f"(pure={here.is_pure}, in_changeset={here.in_changeset}, "
            f"tests_in_changeset={here.tests_in_changeset})");
        if not here.in_changeset {
            if here.is_pure {
                self.report_lines.append(
                    f"    -> PURE consumer not in changeset: confirm still covered.");
            } else {
                self.report_lines.append(
                    f"    -> GLUE consumer not in changeset: confirm an e2e still covers this path.");
            }
        }
    }
}

walker Architecture {
    can start with Root entry {
        audit = BlastRadius();
        for n in [-->(?:Type)] {
            audit spawn n;
        }
        audit.spawn root;
        print("Blast-radius report:");
        for line in audit.report_lines {
            print(line);
        }
    }
}

with entry {
    user = Type(name="User", kind="class", is_pure=True);
    session = Type(name="Session", kind="class", is_pure=True);
    scene = Type(name="Scene", kind="class", is_pure=False);
    sync_engine = Type(name="SyncEngine", kind="class", is_pure=False);
    user_view = Type(name="UserView", kind="class", is_pure=False, in_changeset=False, tests_in_changeset=False);

    change_user_field = ContractChange(member_kind="field", member_name="email");
