    root ++> scene;
    root ++> sync_engine;
    root ++> user_view;

    change_user_field +>:OwnsChange:+> user;
    change_session_method +>:OwnsChange:+> session;

    user +>:Field:+> session;
    session +>:Creates:+> user;
    scene +>:Uses:+> sync_engine;
    user_view +>:Returns:+> user;

