Issue #137: [Build performance] Reduce univers-ark-cli monolithic compile blast radius

## Problem

At source snapshot `43bf85a6d8e3`, `univers-ark-cli` contains about 129,527 Rust lines. The command tree is a single compilation unit, so changes to one module can force codegen across unrelated command families.

## Required investigation

- Measure clean and incremental command-family edit builds through `univers-dev`.
- Separate generated/schema metadata and independently owned command families only where the boundary reduces actual rebuild work.
- Keep the released binary named `ark`; do not create user-visible helper binaries merely to reduce source size.
- Avoid moving router/service implementations into CLI support crates.

## Acceptance criteria

- A representative command-family edit rebuilds only its owned library plus the thin CLI assembly.
- Global command schema/help behavior remains unchanged.
- No new cross-domain implementation dependency is introduced.
- `univers-dev check --full` passes with before/after timing and artifact evidence.


Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.

```jac
"""univers-ark-cli compile blast radius: model the monolithic command tree and
audit how much of it must be rebuilt when one command family changes.

Nodes:    CommandFamily (owns a library), Command (the leaf CLI surface)
Edges:    Owns (CommandFamily -> Command), Depends (Command -> Command)
Walker:   BuildAuditor walks the graph from root, counts cross-family deps
          and flags the cascade that would force a wide rebuild.
"""

node Command {
    has name: str = "";
    has is_schema_generated: bool = False;
}

node CommandFamily {
    has name: str = "";
    has library_name: str = "";
    has is_cli_assembly: bool = False;
}

edge Owns {
    has since: str = "";
}

edge Depends {
    has reason: str = "";
}

# Tracks which family ids the auditor has already inspected so a cyclic
# Depends graph cannot loop the walker forever (jac 0.36.1 has no built-in
# once-per-node visitation).
edge Audited { }

walker BuildAuditor {
    has visited_families: list[str] = [];
    has cross_family_edges: int = 0;
    has within_family_edges: int = 0;
    has schema_hits: int = 0;
    has report_lines: list[str] = [];

    can start with Root entry {
        self.report_lines.append(
            f"starting blast-radius audit at {here}"
        );
        # Hop from Root to the CommandFamily forest via Owns edges.
        visit [->:Owns:->];
    }

    can descend with CommandFamily entry {
        if here.name in self.visited_families {
            # Cycle guard: a CommandFamily we already audited must not
            # be traversed again. Mark it and disengage cleanly.
            self.report_lines.append(
                f"cycle guard hit on family {here.name}; disengaging"
            );
            disengage;
        }
        self.visited_families.append(here.name);

        kind = "CLI assembly" if here.is_cli_assembly else "library";
        self.report_lines.append(
            f"[{kind}] family={here.name} library={here.library_name}"
        );

        # Mark the node so a cyclic Owns chain cannot re-enter either.
        here +>:Audited:+> here;

        # Walk the commands owned by this family.
        visit [->:Owns:->];
    }

    can classify with Command entry {
        if here.is_schema_generated {
            self.schema_hits += 1;
            self.report_lines.append(
                f"  schema-generated command: {here.name} "
                f"(belongs to a family, not free-floating)"
            );
        }

        # Classify every outgoing Depends edge by whether it stays inside
        # the same owning family (cheap rebuild) or crosses families
        # (expensive blast radius).
        edges = [here ->:Depends:->];
        for e in edges {
            owner_family = e._owner_family if e._owner_family else "unknown";
            if owner_family in self.visited_families {
                self.within_family_edges += 1;
            } else {
                self.cross_family_edges += 1;
                self.report_lines.append(
                    f"  CROSS-FAMILY dep: {here.name} -> {e.name} "
                    f"(forces {owner_family} rebuild)"
                );
            }
        }

        visit [->:Depends:->];
    }

    can finish with Root entry {
        self.report_lines.append("---");
        self.report_lines.append(
            f"families audited: {len(self.visited_families)}"
        );
        self.report_lines.append(
            f"within-family edges (cheap): {self.within_family_edges}"
        );
        self.report_lines.append(
            f"cross-family edges (blast radius): {self.cross_family_edges}"
        );
        self.report_lines.append(
            f"schema-generated commands: {self.schema_hits}"
        );
    }

    # The union ability fires for both Command and CommandFamily; it
    # delegates to the typed ability whose `with X entry` matches `here`.
    can inspect with Command | CommandFamily entry {
        # Body intentionally empty: the typed abilities above do the work.
        # Union triggers are only used to satisfy the structural requirement
        # that one ability can handle several node types.
    }

    can report with Root exit {
        # Single exit report: dump every accumulated line.
        for line in self.report_lines {
            print(line);
        }
    }
}

with entry {
    # Three independent command families. The 'cli' one is the thin
    # assembly crate that links the others into the `ark` binary.
    cli = CommandFamily(
        name="cli", library_name="ark_cli", is_cli_assembly=True
    );
    ingest = CommandFamily(
        name="ingest", library_name="ark_ingest"
    );
    export = CommandFamily(
        name="export", library_name="ark_export"
    );

    # Attach owner metadata to each Owns edge by giving it a payload
    # field via a follow-up typed edge: we model "owner family" on the
    # Depends edge instead, by attaching an extra small edge. The walker
    # reads `e._owner_family` from this payload.
    root +>:Owns(since="v1"):+> cli;
    root +>:Owns(since="v1"):+> ingest;
    root +>:Owns(since="v1"):+> export;

    # Commands owned by each family. Some are schema-generated (counted
    # separately: they must stay with their owning family, not be moved).
    cmd_ingest_a = Command(name="ingest.run", is_schema_generated=True);
    cmd_ingest_b = Command(name="ingest.status");
    cmd_export_a = Command(name="export.to_parquet", is_schema_generated=True);
    cmd_export_b = Command(name="export.to_csv");
    cmd_cli_root = Command(name="ark", is_schema_generated=True);

    cli +>:Owns(since="v1"):+> cmd_cli_root;
    ingest +>:Owns(since="v1"):+> cmd_ingest_a;
    ingest +>:Owns(since="v1"):+> cmd_ingest_b;
    export +>:Owns(since="v1"):+> cmd_export_a;
    export +>:Owns(since="v1"):+> cmd_export_b;

    # Within-family dep: cheap rebuild when ingest.run changes.
    cmd_ingest_a +>:Depends(reason="ingest"):+> cmd_ingest_b;

    # Cross-family dep: this is the blast radius the issue is worried
    # about. Exporting to parquet requires ingest to run first; editing
    # ingest forces a rebuild of the export family.
    cmd_export_a +>:Depends(reason="export"):+> cmd_ingest_a;

    # A back-edge that creates a cycle between export and the CLI root,
    # exercising the cycle guard on the family traversal.
    cmd_cli_root +>:Depends(reason="cli"):+> cmd_export_a;

    # Tag each Depends edge with the owning family of its source so the
    # auditor can classify without a second traversal.
    for e in [cmd_ingest_a->:Depends:->cmd_ingest_b] {
        e._owner_family = "ingest";
    }
    for e in [cmd_export_a->:Depends:->cmd_ingest_a] {
        e._owner_family = "export";
    }
    for e in [cmd_cli_root->:Depends:->cmd_export_a] {
        e._owner_family = "cli";
    }

    root spawn BuildAuditor();
}
