Scenario: a built-in review turn inherits a local "review skill" whose broad
description matches the review task. The skill's helper launches another
``codex review``, the child review inherits the same skill, and the chain
recurses without bound. This demo models the recursion natively as a walker
traversing typed edges and shows what a depth-limited, cycle-guarded review
walker looks like — the host-level guard the issue asks for.
"""

node Skill {
    has name: str = "";
    has description: str = "";
    # True if this skill is eligible for review tasks (broad description match).
    has matches_review: bool = False;
    # True if invoking this skill launches another review turn.
    has launches_review: bool = False;
}

node ReviewTurn {
    has task: str = "";
    # Depth in the review chain. The root review is depth 0.
    has depth: int = 0;
    # Parent depth cap; exceeding it must abort the chain.
    has max_depth: int = 3;
}

# The inheritance edge: a child review turn inherits a snapshot of skills
# from its parent. This is the exact path described in the source evidence
# (review.rs copies the parent skill snapshot into the child turn).
edge InheritsSkill {
    has origin: str = "parent";
}

# The invocation edge: a review turn selected a skill and is about to run it.
edge Invokes {
    has command: str = "";
}

walker ReviewSession {
    # Mirror of the cycle guard the maintainer asks for. Walkers in jac 0.36
    # have no built-in once-per-node dedupe, so we carry it explicitly.
    has seen: list[str] = [];
    # Tracks the worst depth observed; reported on exit.
    has deepest: int = 0;
    # The recursion cap that turns unbounded recursion into a clean refusal.
    has max_depth: int = 3;

    can start with Root entry {
        visit [-->(?:ReviewTurn)];
    }

    can run with ReviewTurn entry {
        here.depth += 1;
        if here.depth > self.max_depth {
            print(f"[REFUSED] review depth {here.depth} exceeds cap {self.max_depth}; stopping chain");
            disengage;
        }
        if here.task in self.seen {
            print(f"[CYCLE] review task '{here.task}' already seen; refusing re-entry");
            disengage;
        }
        self.seen.append(here.task);
        if here.depth > self.deepest {
            self.deepest = here.depth;
        }
        print(f"[depth {here.depth}] review turn running: {here.task}");
        visit [-->(?:Skill)];
    }

    can select_skill with Skill entry {
        if not here.matches_review {
            print(f"  skill '{here.name}' ignored (not a review match)");
