            child +>:InheritsSkill(origin="inherited"):+> here;
            print(f"  -> launched child review from skill '{here.name}'");
        }
        visit [-->];
    }

    def report -> str {
        return f"deepest depth reached: {self.deepest} (cap {self.max_depth})";
    }
