## What to build

Wire all pipeline notebooks into a Databricks Workflow job definition with a daily schedule, retry logic on the file arrival sensor, and dependency ordering between tasks. Free tier compatible — no Delta Live Tables or SQL Warehouse.

## Acceptance criteria

- [ ] Workflow job definition in `workflows/` covering the full pipeline: file sensor → Raw ingestion → Enriched → IDS → Curated
- [ ] File arrival sensor task configured to retry every 10 minutes up to a 2-hour timeout
- [ ] Daily schedule triggers 30 minutes after expected file delivery time
- [ ] Task dependencies between pipeline stages correctly set (each stage waits for the prior to succeed)
- [ ] All notebooks parameterised for `catalog`, `schema`, and `run_date` so the workflow can be tested against a `test_` catalog without touching production
- [ ] Historical backfill job definition separate from the daily incremental job, accepting a date range parameter
- [ ] Cluster configured to start before Workflow begins and remain running during business hours (for Power BI refresh)

## Blocked by

- #9 Curated Layer Pipeline

Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.

```jac
"""Databricks Workflow orchestration model.

Models the essential scenario from issue #10: a daily pipeline workflow
(file_sensor -> Raw -> Enriched -> IDS -> Curated) with retry policy,
dependency ordering, and a separate historical backfill job that walks the
same stages over a date range. A walker enforces the schedule, retry, and
backfill semantics without any hand-rolled graph machinery.
"""

# ---------- Edge archetypes (relationships that carry meaning) ----------

edge StageLink {
    # Carries the ordering payload between pipeline stages.
    has ordinal: int = 0;
}

# ---------- Node archetypes ----------

node Workflow {
    has title: str = "";
    has schedule_offset_min: int = 30;
    has business_hours_only: bool = True;
    has catalog: str = "prod";
    has schema: str = "main";
}

node BackfillJob {
    has title: str = "";
    has start_date: str = "";
    has end_date: str = "";
}

node Sensor {
    has title: str = "";
    has retry_minutes: int = 10;
    has timeout_minutes: int = 120;
}

node Stage {
    has title: str = "";
    has stage_name: str = "";
    has catalog: str = "prod";
    has schema: str = "main";
    has run_date: str = "";
}

# ---------- Walker: daily pipeline runner ----------

walker DailyRunner {
    has log: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can run_workflow with Workflow entry {
        self.log.append(
            f"[{here.title}] schedule: daily, fires "
            f"{here.schedule_offset_min}min after expected file delivery, "
            f"catalog={here.catalog}, schema={here.schema}"
        );
        visit [->:StageLink:->];
    }

    can trigger_sensor with Sensor entry {
        attempts = here.timeout_minutes // here.retry_minutes;
        self.log.append(
            f"[{here.title}] file arrival sensor: retry every "
            f"{here.retry_minutes}min, timeout {here.timeout_minutes}min "
            f"({attempts} attempts)"
        );
        visit [->:StageLink:->];
    }

    can run_stage with Stage entry {
        self.log.append(
            f"[{here.stage_name}] {here.title} "
            f"(catalog={here.catalog}, schema={here.schema}, "
            f"run_date={here.run_date})"
        );
        visit [->:StageLink:->];
    }
}

# ---------- Walker: historical backfill over a date range ----------

walker BackfillRunner {
    has log: list[str] = [];
    has dates: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can dispatch with BackfillJob entry {
        self.log.append(
            f"[{here.title}] backfill range {here.start_date}..{here.end_date}"
        );
        visit [->:StageLink:->];
    }

    can fill_stage with Stage entry {
        for d in self.dates {
            self.log.append(
                f"[{here.stage_name}] {here.title} run_date={d}"
            );
        }
        # Backfill terminates after one pass; no forward edges from a leaf.
        disengage;
    }
}

# ---------- Walker: dependency-order audit (catches missing/extra edges) ----------

walker OrderAuditor {
    has seen_ordinals: list[int] = [];
    has ordered: bool = True;

    can start with Root entry {
        visit [-->];
    }

    can audit_workflow with Workflow entry {
        visit [->:StageLink:->];
    }

    can audit_sensor with Sensor entry {
        visit [->:StageLink:->];
    }

    can audit_stage with Stage entry {
        ordinal = 0;
        for e in [->:StageLink:->] {
            ordinal = e.ordinal;
        }
        self.seen_ordinals.append(ordinal);
        # No forward visit: a Stage is a leaf in the chain.
    }
}

# ---------- Demo wiring ----------

with entry {
    # Build the daily pipeline chain.
    daily = Workflow(
        title="daily-incremental",
        schedule_offset_min=30,
        catalog="prod",
        schema="main"
    );
    sensor = Sensor(title="file-arrival-sensor");
    raw = Stage(title="Raw ingestion", stage_name="RAW", run_date="2025-01-15");
    enriched = Stage(title="Enriched layer", stage_name="ENRICHED", run_date="2025-01-15");
    ids = Stage(title="IDS layer", stage_name="IDS", run_date="2025-01-15");
    curated = Stage(title="Curated layer", stage_name="CURATED", run_date="2025-01-15");

    root +>:StageLink(ordinal=0):+> daily;
    daily +>:StageLink(ordinal=1):+> sensor;
    sensor +>:StageLink(ordinal=2):+> raw;
    raw +>:StageLink(ordinal=3):+> enriched;
    enriched +>:StageLink(ordinal=4):+> ids;
    ids +>:StageLink(ordinal=5):+> curated;

    runner = DailyRunner();
    root spawn runner;
    for line in runner.log {
        print(line);
    }

    # Build a separate backfill job sharing the stage topology.
    backfill = BackfillJob(
        title="historical-backfill",
        start_date="2024-12-01",
        end_date="2024-12-03"
    );
    backfill +>:StageLink(ordinal=1):+> sensor;
    sensor +>:StageLink(ordinal=2):+> raw;

    bf = BackfillRunner(dates=["2024-12-01", "2024-12-02", "2024-12-03"]);
    root spawn bf;
    for line in bf.log {
        print(line);
    }

    # Audit ordinal ordering across the daily chain.
    auditor = OrderAuditor();
    root spawn auditor;
    ordinals_str = ",".join(str(o) for o in auditor.seen_ordinals);
    print(f"audit ordinals: [{ordinals_str}] ordered={auditor.ordered}");
}
