"""GitHub Actions CI pipeline modeled as a typed-edge graph.

Entities: Stage (CI steps), Job (parallel job containers), Runner (execution
hosts), and the Workflow root. The walker walks the workflow graph in the
order the CI pipeline must execute, enforces the dependency rules, detects
cycles, and reports which stage blocked the build.
"""

node Stage {
    has title: str = "";
    has command: str = "";
    has passed: bool = False;
    has critical: bool = True;
}

node Job {
    has name: str = "";
    has parallel: bool = False;
}

node Runner {
    has label: str = "";
    has online: bool = True;
}

edge DependsOn {
    has order: int = 0;
}

edge AssignedTo {
    has slot: int = 0;
}

edge RunsOn {
    has lane: int = 0;
}

walker CIPipeline {
    has blocked: bool = False;
    has visited: list[str] = [];

    can start with Root entry {
        print("git push received -> GitHub Actions triggered");
        visit [-->];
    }

    can enter_job with Job entry {
        if here.parallel {
            print(f"  [parallel] entering job: {here.name}");
        } else {
            print(f"  [sequential] entering job: {here.name}");
        }
        visit [-->];
    }

    can enter_runner with Runner entry {
        runner_state = "READY" if here.online else "OFFLINE";
        print(f"    runner {here.label}: {runner_state}");
        if not here.online {
            self.blocked = True;
            disengage;
        }
        visit [-->];
    }

    can run_stage with Stage entry {
        # Cycle guard: stages are tracked by title; revisit = cycle.
        for tag in self.visited {
            if tag == here.title {
                cycle_msg = f"    CYCLE detected at stage '{here.title}'";
                print(cycle_msg);
                self.blocked = True;
                disengage;
            }
        }
        self.visited.append(here.title);

        if not here.passed {
            outcome = "FAIL";
            print(f"    [{outcome}] {here.title}: {here.command}");
            if here.critical {
                self.blocked = True;
                print("    critical stage failed -> workflow halted");
                disengage;
            }
        } else {
            print(f"    [PASS] {here.title}: {here.command}");
        }
        visit [-->];
    }
}

with entry {
    tests = Job(name="tests");
    lint = Job(name="lint");
    build = Job(name="build");

    test_stage = Stage(title="tests", command="pytest", passed=True, critical=True);
    lint_stage = Stage(title="lint", command="ruff check", passed=False, critical=True);
    build_stage = Stage(title="build", command="python -m build", passed=True, critical=True);

    hosted = Runner(label="ubuntu-22.04", online=True);

    root ++> tests ++> lint ++> build;
    tests +>:AssignedTo(slot=0):+> test_stage;
    lint +>:AssignedTo(slot=1):+> lint_stage;
    build +>:AssignedTo(slot=2):+> build_stage;

    test_stage +>:RunsOn(lane=0):+> hosted;
    lint_stage +>:RunsOn(lane=0):+> hosted;
    build_stage +>:RunsOn(lane=0):+> hosted;

    print("=== CI run #1: lint fails ===");
    runner_one = CIPipeline();
    root spawn runner_one;
    verdict_one = "FAILED" if runner_one.blocked else "PASSED";
