"""Dynamic schema prefix traversal — idiomatic Jac demo.

Models the Arbor issue: a tree of records may live under different schema
prefixes, and a walker that walks ancestors/descendants must respect the
prefix stored on the given record's metadata rather than a compile-time
constant. We use a typed ``Parent`` edge whose ``prefix`` payload is
consulted at walk time so the traversal adapts to each record's schema.
"""

# ---------- edge archetype: carries the schema prefix as payload ----------
edge Parent {
    has prefix: str = "";
}

# ---------- node archetype: the table rows living under a prefix ----------
node Record {
    has title: str = "";
    has prefix: str = "";   # analogous to :__meta__.prefix
    has primary_key: str = "";
}

# ---------- walker: walks descendants, threading the current prefix ----------
walker DescendantWalker {
    has start_key: str = "";
    has max_depth: int = 32;
    has seen: list[str] = [];   # explicit cycle guard (jac 0.36 has no built-in)
    has found: list[Record] = [];

    can begin with Root entry {
        # Kick off by finding the root record that matches the start key.
        visit [-->];
    }

    can scan with Record entry {
        if here.primary_key == self.start_key {
            # Found the seed; now follow Parent edges respecting each
            # node's own prefix (the whole point of the issue).
            self.found.append(here);
            visit [->:Parent:->];
            disengage;
        }
        visit [-->];
    }

    can descend with Record entry {
        # Cycle policy: explicit visited-by-key guard, survives the lift.
        if here.primary_key in self.seen {
            disengage;
        }
        self.seen.append(here.primary_key);

        # Show that the prefix payload on the edge matches the child's
        # own schema prefix — this is the "dynamic schema" behaviour the
        # issue is asking for.
        next_edges = [here ->:Parent:->];
        if next_edges {
            edge_prefix = here.prefix;
            print(f"descend into {here.title} under prefix='{edge_prefix}'");
            self.found.append(here);
            if len(self.seen) >= self.max_depth {
                disengage;
            }
            visit [->:Parent:->];
        } else {
            print(f"leaf: {here.title} (prefix='{here.prefix}')");
        }
    }
}

# ---------- walker: walks ancestors via the same typed edges ----------
walker AncestorWalker {
    has start_key: str = "";
    has max_depth: int = 32;
    has seen: list[str] = [];
    has found: list[Record] = [];

    can begin with Root entry {
        visit [-->];
    }

    can scan with Record entry {
        if here.primary_key == self.start_key {
            self.found.append(here);
            # Walk ancestors — backward through Parent edges (the edge
            # itself models "this node's parent", so [<--] would give
            # siblings/parents of parents in untyped form; we explicitly
            # traverse forward following the typed edge's prefix payload).
            visit [->:Parent:->];
            disengage;
        }
        visit [-->];
    }

    can ascend with Record entry {
        if here.primary_key in self.seen {
            disengage;
        }
        self.seen.append(here.primary_key);

        edges_out = [here ->:Parent:->];
        if edges_out {
            print(f"ancestor: {here.title} (prefix='{here.prefix}')");
            self.found.append(here);
            if len(self.seen) >= self.max_depth {
                disengage;
            }
            visit [->:Parent:->];
        } else {
            print(f"root ancestor reached: {here.title} (prefix='{here.prefix}')");
        }
    }
}

# ---------- walker: cascade-delete a subtree under a given prefix ----------
walker CascadeInvalidator {
    has start_key: str = "";
    has target_prefix: str = "";
    has seen: list[str] = [];
    has purged: list[str] = [];

    can begin with Root entry {
        visit [-->];
    }

    can locate with Record entry {
        if here.primary_key == self.start_key and here.prefix == self.target_prefix {
            print(f"invalidating subtree rooted at {here.title} (prefix='{here.prefix}')");
            visit [->:Parent:->];
            disengage;
        }
        visit [-->];
    }

    can purge with Record entry {
        if here.primary_key in self.seen {
            disengage;
        }
        self.seen.append(here.primary_key);
        self.purged.append(here.primary_key);
        print(f"  purged: {here.title} (prefix='{here.prefix}')");
        nxt = [->:Parent:->];
        if nxt {
            visit [->:Parent:->];
        } else {
            disengage;
        }
    }
}

# ---------- demo: wire a small graph spanning two schema prefixes ----------
with entry {
    # Two schemas ("tenant_a", "tenant_b") — same tree shape, different
    # prefixes, just like the issue describes.
    root ++> Record(title="users:1", prefix="tenant_a", primary_key="a1")
        +>:Parent(prefix="tenant_a"):+> Record(title="users:2", prefix="tenant_a", primary_key="a2")
        +>:Parent(prefix="tenant_a"):+> Record(title="users:3", prefix="tenant_a", primary_key="a3");

