    print("=== descendants of a1 (tenant_a) ===");
    d = DescendantWalker(start_key="a1", max_depth=8);
    root spawn d;
    print(f"found: {[r.title for r in d.found]}");

    # Descendants of b1 under tenant_b
    print("=== descendants of b1 (tenant_b) ===");
    d2 = DescendantWalker(start_key="b1", max_depth=8);
    root spawn d2;
    print(f"found: {[r.title for r in d2.found]}");

