    print(f"found: {[r.title for r in a.found]}");

    # Cascade invalidation under tenant_b starting at b1
    print("=== cascade invalidate tenant_b from b1 ===");
    c = CascadeInvalidator(start_key="b1", target_prefix="tenant_b");
