Task:
A maintainer on the project cupidthatbtc/panelcast (unknown) filed this issue about hand-rolled graph machinery causing pain:

Issue #419: validate completed ledger records before skipping them on resume

## Problem

On sweep resume, a ledger record whose status is `completed` (or `timeout`) short-circuits at `select/runner.py:958-967` with no check that `run_dir` still exists, that its manifest succeeded, or that its scoring artifacts still match recorded hashes. If a completed reference run's directory was deleted or moved between sessions, `reference_runs` is still populated with the now-missing path.

Downstream that becomes a quiet scoring hole rather than a hard stop: the scorer raises per arm, the exception is swallowed at `runner.py:1039`, and the arm is nonetheless marked `completed` at `runner.py:1041` with `score=None`. Rung survivors and promotion decisions then proceed from stale score dictionaries retained in the ledger, or from an arm set where several entries carry no ELPD at all.

## Acceptance criteria

- Before treating a ledger record as terminal, validate that `run_dir` exists, is contained under the sweep root, and has a manifest recording success with matching identity.
- Verify the required scoring artifacts against their recorded hashes.
- Demote unverifiable `completed` records to a retryable/stale status instead of skipping them, and recompute their scores from verified snapshots.
- Do not mark an arm `completed` when its scorer raised; surface the failure so rung decisions cannot silently run on `score=None`.
- Regression test: delete a completed reference run directory, resume the sweep, assert the arm is re-run or the sweep aborts with an explicit error.

Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.

```jac
"""Sweep ledger resume validator: detect stale completed records before skipping them.

Models the core scenario from issue #419: a ledger holds sweep records
that mark arms as `completed`. On resume, we walk the ledger and verify
each completed record's run_dir exists under the sweep root, its
manifest declares success, and its scoring artifacts match their
recorded hashes. Unverifiable completed records are demoted to a
retryable stale status instead of being skipped.
"""

enum LedgerStatus {
    PENDING = "pending",
    RUNNING = "running",
    COMPLETED = "completed",
    TIMEOUT = "timeout",
    STALE = "stale",
    FAILED = "failed",
}

node RunDir {
    has path: str = "";
    has exists: bool = True;
}

node Manifest {
    has succeeded: bool = True;
    has identity: str = "";
}

node Artifact {
    has name: str = "";
    has recorded_hash: str = "";
    has actual_hash: str = "";
    has present: bool = True;
}

node LedgerRecord {
    has arm_name: str = "";
    has status: str = "pending";
    has run_dir_path: str = "";
}

edge LivesUnder {
    has sweep_root: str = "";
}

edge HasManifest {}

edge HasArtifact {}

edge RecordedAt {}

walker ResumeValidator {
    has sweep_root: str = "/sweeps/root";
    has demoted: list[str] = [];
    has kept: list[str] = [];

    can start with Root entry {
        print(f"Resuming sweep under {self.sweep_root}");
        visit [->:RecordedAt:->];
    }

    can inspect with LedgerRecord entry {
        rec = here;
        print(f"-- arm: {rec.arm_name} status={rec.status} --");

        if rec.status != "completed" and rec.status != "timeout" {
            print(f"   non-terminal, skipping validation");
            self.kept.append(rec.arm_name);
            visit [-->];
            return;
        }

        rd = [-->];
        ok_dir = False;
        ok_manifest = False;
        ok_artifacts = True;

        if len(rd) > 0 {
            run_dir = rd[0];
            contained = run_dir.path.startswith(self.sweep_root + "/");
            ok_dir = run_dir.exists and contained;
            print(f"   run_dir exists={run_dir.exists} under_root={contained}");
        } else {
            print(f"   no run_dir attached");
        }

        if ok_dir {
            mf = [-->];
            if len(mf) > 0 {
                manifest = mf[0];
                ok_manifest = manifest.succeeded and manifest.identity == rec.arm_name;
                print(f"   manifest succeeded={manifest.succeeded} identity={manifest.identity}");
            } else {
                print(f"   no manifest attached");
            }
        }

        if ok_manifest {
            arts = [-->];
            for a in arts {
                ok_artifacts = ok_artifacts and a.present and (a.actual_hash == a.recorded_hash);
                if not (a.present and a.actual_hash == a.recorded_hash) {
                    print(f"   artifact {a.name} hash mismatch (recorded={a.recorded_hash} actual={a.actual_hash})");
                }
            }
        }

        verdict = ok_dir and ok_manifest and ok_artifacts;
        if verdict {
            print(f"   VERIFIED: keep as completed");
            self.kept.append(rec.arm_name);
        } else {
            print(f"   STALE: demoting completed -> stale, will re-run");
            rec.status = "stale";
            self.demoted.append(rec.arm_name);
        }

        visit [-->];
    }
}

with entry {
    root_sweep = RunDir(path="/sweeps/root");
    root +>:LivesUnder(sweep_root="/sweeps/root"):+> root_sweep;

