"""Build system dependency graph: audit tasks exactly once even if reachable by many paths.

Models build tasks as nodes connected by a typed ``DependsOn`` edge (carrying
the per-edge build-minute cost). The ``BuildAuditor`` walker traverses the
dependency graph, accumulating each task's minutes on first encounter and
ignoring repeats. The explicit visited guard replaces what would otherwise
be a memo cache around a manual recursion.
"""

node Task {
    has title: str = "";
    has minutes: int = 0;
}

edge DependsOn {
    has minutes: int = 0;
}

walker BuildAuditor {
    has visited: set = {};
    has total: int = 0;

    can start with Root entry {
        visit [->:DependsOn:->];
    }

    can audit with Task entry {
        if here.title in self.visited {
            visit [->:DependsOn:->];
        } else {
            self.visited.add(here.title);
            self.total += here.minutes;
            print(f"audited {here.title} ({here.minutes} min) — running total {self.total} min");
            visit [->:DependsOn:->];
        }
    }
}

with entry {
    # Diamond: core_lib is needed by both ui_module and api_module;
    # both of those feed into app_bin. core_lib must be audited once.
    core_lib = Task(title="core_lib", minutes=5);
    ui_module = Task(title="ui_module", minutes=8);
    api_module = Task(title="api_module", minutes=12);
    db_driver = Task(title="db_driver", minutes=3);
    app_bin = Task(title="app_bin", minutes=2);

    root +>:DependsOn(minutes=1):+> core_lib;
    root +>:DependsOn(minutes=1):+> db_driver;
    core_lib +>:DependsOn(minutes=1):+> ui_module;
    core_lib +>:DependsOn(minutes=1):+> api_module;
    db_driver +>:DependsOn(minutes=1):+> api_module;
    ui_module +>:DependsOn(minutes=1):+> app_bin;
    api_module +>:DependsOn(minutes=1):+> app_bin;

    auditor = BuildAuditor();
    root spawn auditor;

    print(f"TOTAL BUILD MINUTES: {auditor.total}");
}
