```jac
"""TiKV-PHP observability gap model.

Models the core scenario from GAP-20: an in-memory ``MetricsInterface`` records
six hooks across RPC lifecycle, region cache lookups, and cache invalidations,
but ships no Prometheus adapter and no tracing integration. Here the recorder
becomes a ``MetricsRecorder`` walker that traverses stores, regions, and
commands along typed edges, accumulating per-store backoff, RPC latency,
region cache hit/miss/invalidated, and 2PC phase timings in a single exit
``report``. A separate ``Tracer`` walker mirrors client-go's
``TraceEventFunc`` callback surface so callers can bridge to OpenTelemetry.
"""

node Store {
    has address: str = "";
    has rpc_started: int = 0;
    has rpc_completed: int = 0;
    has rpc_errors: int = 0;
    has backoff_total_ms: float = 0.0;
    has prewrite_ms: float = 0.0;
    has commit_ms: float = 0.0;
    has lock_resolution_count: int = 0;
}

node Region {
    has region_id: int = 0;
    has cache_hit: int = 0;
    has cache_miss: int = 0;
    has invalidated: int = 0;
    has invalidated_reason: str = "";
}

node Command {
    has kind: str = "";
    has latency_ms: float = 0.0;
    has retry_attempt: int = 0;
    has phase2pc: str = "";
}

node KeyRange {
    has start_key: str = "";
    has end_key: str = "";
}

edge Replicates { }
edge Invalidates { }
edge Targets { }
edge Spans { }

walker MetricsRecorder {
    has report: dict = {};
    has phase_timing: dict = {};

    can start with Root entry {
        visit [-->];
    }

    can record_store with Store entry {
        # Aggregate per-store counters and 2PC phase timings onto the walker.
        self.report[here.address] = {
            "rpc_started": here.rpc_started,
            "rpc_completed": here.rpc_completed,
            "rpc_errors": here.rpc_errors,
            "backoff_total_ms": here.backoff_total_ms,
            "lock_resolution_count": here.lock_resolution_count,
        };
        self.phase_timing[here.address] = {
            "prewrite_ms": here.prewrite_ms,
            "commit_ms": here.commit_ms,
        };
        visit [->:Replicates:->];
    }

    can record_region with Region entry {
        cache_snapshot = {
            "region_id": here.region_id,
            "cache_hit": here.cache_hit,
            "cache_miss": here.cache_miss,
            "invalidated": here.invalidated,
            "invalidated_reason": here.invalidated_reason,
        };
        existing = self.report.get("regions", []);
        existing.append(cache_snapshot);
        self.report["regions"] = existing;
        visit [->:Invalidates:->];
    }

    can record_command with Command entry {
        command_snapshot = {
            "kind": here.kind,
            "latency_ms": here.latency_ms,
            "retry_attempt": here.retry_attempt,
            "phase2pc": here.phase2pc,
        };
        existing = self.report.get("commands", []);
        existing.append(command_snapshot);
        self.report["commands"] = existing;
        visit [-->];
    }

    can ignore_keyrange with KeyRange entry {
        # KeyRange is a structural anchor on the graph; metrics don't collect
        # from it directly, but traversal must still be able to leave it.
        visit [-->];
    }

    can finish with Root entry {
        print("Prometheus export payload:");
        for (store_addr, counters) in self.report.items() {
            if store_addr == "regions" or store_addr == "commands" {
                continue;
            }
            print(f"  store {store_addr}: {counters}");
        }
        for (store_addr, timings) in self.phase_timing.items() {
            print(f"  store {store_addr} 2pc: {timings}");
        }
        print(f"  region_cache: {self.report['regions']}");
        print(f"  commands: {self.report['commands']}");
    }
}

walker Tracer {
    has spans: list = [];

    can start with Root entry {
        visit [-->];
    }

    can trace_store with Store entry {
        self.spans.append(f"span(store={here.address}, rpc_started={here.rpc_started})");
        visit [->:Replicates:->];
    }

    can trace_region with Region entry {
        self.spans.append(f"span(region={here.region_id}, hit={here.cache_hit}, miss={here.cache_miss})");
        visit [->:Invalidates:->];
    }

    can trace_command with Command entry {
        self.spans.append(f"span(command={here.kind}, latency_ms={here.latency_ms})");
        visit [-->];
    }

    can ignore_keyrange with KeyRange entry {
        visit [-->];
    }

    can finish with Root entry {
        print("Tracing callbacks (bridge to OpenTelemetry yourself):");
        for s in self.spans {
            print(f"  {s}");
        }
    }
}

with entry {
    pd_store = Store(
