```jac
"""Type-parameter erasure cycle: bounded wildcards and executable lookups.

Models the essential scenario from INRIA/spoon issue #6802: a wildcard
reference is resolved by looking up its bound's declaration, which in
turn requires matching the enclosing executable, whose erasure re-enters
the same wildcard lookup. We reproduce the cycle natively with typed
edges and a walker that mirrors that recursive lookup, then show that
introducing a direct erasure rule breaks the cycle.
"""

# --- Entities -------------------------------------------------------------

node TypeRef {
    has name: str = "";
    has kind: str = "";       # "WILDCARD_UP", "WILDCARD_LO", "TYPE_PARAM", "DECL"
    has upper_bound: str = ""; # free-form bound name (e.g. "E", "Object")
}

node Executable {
    has signature: str = "";
}

# --- Typed relationships --------------------------------------------------

# A wildcard/type-parameter reference is bounded by another type reference.
edge BoundedBy { }

# An executable references its type parameters (and the wildcards they own).
edge OwnsParam { }

# A type reference is contained in / declared by an executable.
edge DeclaredIn { }

# --- Walker: replicate the buggy recursive lookup -------------------------

walker ErasureLookup {
    # Cycle guard: jac 0.36.1 walkers have NO built-in once-per-node
    # visitation on cyclic graphs, so we carry the guard explicitly.
    # This is the domain logic that MUST survive the lift.
    has guard: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can traverse_executable with Executable entry {
        self.guard = self.guard + [here.signature];
        print(f"resolving executable: {here.signature}");
        # follow declaring-type -> owning params -> bounded refs
        visit [->:DeclaredIn:->];
    }

    can traverse_decl with TypeRef entry {
        if here.kind == "DECL" {
            print(f"  -> declaration hit: {here.name}");
            return;
        }
        if here.name in self.guard {
            print(f"  ! cycle on ref {here.name}; would overflow");
            disengage;
        }
        # for wildcards, the bug re-enters via the bound AND via the
        # enclosing executable's parameter list. Both are typed edges.
        visit [->:BoundedBy:->];
        visit [->:OwnsParam:->];
    }

    can traverse_anything with TypeRef | Executable entry {
        # shared no-op fan-out (both archetypes are in the traversal set)
        visit [-->];
    }
}

# --- Walker: the fix — direct erasure rule, no re-entry -------------------

walker DirectErasure {
    can start with Root entry {
        visit [-->];
    }

    can compute with TypeRef entry {
        erased: str = "";
        if here.kind == "WILDCARD_UP" {
            erased = here.upper_bound if here.upper_bound else "Object";
        } elif here.kind == "WILDCARD_LO" {
            erased = "Object";
        } else {
            erased = here.name;
        }
        print(f"erasure({here.name} [{here.kind}]) -> {erased}");
        visit [-->];
    }

    can skip with Executable entry {
        # Executables no longer force a re-lookup of their parameters
        # for erasure purposes — the rule is local to the reference.
        visit [-->];
    }
}

# --- Demo graph ----------------------------------------------------------

with entry {
    # The bug graph: a wildcard `? extends E` whose bound `E` is a type
    # parameter of an executable, whose own parameter list re-references
    # the same wildcard through erasure.
    e_param = TypeRef(name="E", kind="TYPE_PARAM", upper_bound="Object");
    wildcard = TypeRef(name="?", kind="WILDCARD_UP", upper_bound="E");
    method = Executable(signature="m(A): ? extends E");
    decl_e = TypeRef(name="E", kind="DECL", upper_bound="Object");

    root +>:DeclaredIn:+> method;
    method +>:OwnsParam:+> e_param;
    method +>:OwnsParam:+> wildcard;
    wildcard +>:BoundedBy:+> e_param;

    # The cycle that causes the overflow: matching the executable
    # re-erases the wildcard, which re-enters the lookup.
    e_param +>:DeclaredIn:+> method;
    wildcard +>:DeclaredIn:+> method;
    decl_e +>:DeclaredIn:+> method;

    print("=== Buggy recursive lookup (cycle guard trips) ===");
    root spawn ErasureLookup();

    print("\n=== Fixed direct erasure (no re-entry needed) ===");
    DirectErasure() spawn root;
}
