    r1b = Comment(body="Global, with a small grid over [0.3, 0.7].",
                  author="bob",
                  depth=2);
    r1 +>:ReplyTo(ordinal=1):+> r1b;

    r2 = Comment(body="Stacking beat blending for me by ~0.002 AUC.",
                 author="dave",
                  depth=1);
    top +>:ReplyTo(ordinal=1):+> r2;

    r2a = Comment(body="What meta-learner did you use?",
                  author="eve",
                  depth=2);
