```jac
"""Profiler capability expansion — model a profiler's flag catalog where
enabling a parent flag must imply its descendants (or the leaf is a silent
no-op), and where stalled spans need to be attributed to root causes
(Typhon code, GC, runtime suspension, lock contention, scheduling).

Entities (nodes):
  Flag         — a profiler flag (e.g. "Runtime:ThreadScheduling")
  CaptureSource— a cause emitter (GC, ETW scheduling, contention, ...)
  Stall        — an observed multi-millisecond span with no child spans
  Cause        — a classified attribution for a stall

Relationships (typed edges):
  Implies      — Flag -> Flag (parent-implies-child in the flag tree)
  Emits        — CaptureSource -> Cause (this source can produce this cause)
  Observed     — Stall -> Flag (stall was seen while this flag was on)
  AttributedTo — Stall -> Cause (walker's verdict: which cause best fits)

The flag-config walker enforces the parent-implies-children rule on the catalog
and rejects orphan leaves. The stall-attribution walker reaches from a Stall
through Observed -> Flag -> Implies (ancestor flag tree) -> CaptureSource ->
Emits -> Cause, and reports the best-matching cause (or NONE). A guard set
prevents the back-edge on the Implies cycle from looping forever.
"""

node Flag {
    has key: str = "";
    has enabled: bool = False;
}

node CaptureSource {
    has name: str = "";
}

node Cause {
    has label: str = "";
    has priority: int = 0;
}

node Stall {
    has label: str = "";
    has duration_ms: float = 0.0;
}

edge Implies {
    has weight: int = 1;
}

edge Emits {
    has cadence: str = "";
}

edge Observed {
    has depth_ms: float = 0.0;
}

edge AttributedTo {
    has confidence: float = 0.0;
}

walker FlagAuditor {
    """Walk the Implies tree from every enabled flag and confirm no leaf
    is enabled while an ancestor is disabled. Reports orphan leaves and
    dead (disabled) subtrees."""
    can start with Root entry {
        visit [-->];
    }

    can audit_flag with Flag entry {
        print(f"[flag] {here.key} enabled={here.enabled}");
        # Ancestors of this flag through Implies (walking UP the tree).
        ancestor_ok = self._ancestors_all_enabled(here);
        if here.enabled and not ancestor_ok {
            print(f"  ORPHAN LEAF: '{here.key}' enabled but an "
                  f"ancestor is disabled — silent no-op in trace");
            self.orphan_count += 1;
        }
        # Continue into children (forward along Implies).
        visit [->:Implies:->];
    }

    def _ancestors_all_enabled(self, start: Flag) -> bool {
        # Walk backward along Implies, with a visited-set guard so the
        # parent walk can't loop on a malformed tree.
        guard: set = set();
        cur = start;
        while cur is not None {
            if cur in guard {
                break;
            }
            guard.add(cur);
            parents = [p for p in (cur <-:Implies:--) if isinstance(p, Flag)];
            if not parents {
                break;
            }
            cur = parents[0];
            if not cur.enabled {
                return False;
            }
        }
        return True;
    }
}

walker StallAttributor {
    """From a Stall, reach through Observed -> Flag, climb the Implies tree
    to ancestor flags, hop to CaptureSources that Emit causes, and pick
    the cause with the highest priority as the attribution. Uses a guard
    set so cycles in the Implies graph don't hang the walker."""
    has verdict: str = "NONE";
    has best_priority: int = -1;
    has best_label: str = "NONE";

    can start with Root entry {
        visit [-->];
    }

    can inspect_stall with Stall entry {
        print(f"[stall] {here.label} duration={here.duration_ms}ms");
        # Reset per-stall verdict.
        self.verdict = "NONE";
        self.best_priority = -1;
        self.best_label = "NONE";
        # Walk into flags observed under this stall.
        visit [->:Observed:->];
    }

    can climb with Flag entry {
        print(f"  observed flag: {here.key}");
        # From this flag, climb ancestors via Implies and from each
        # reachable flag, hop to CaptureSources that Emit causes.
        ancestors = self._collect_ancestors(here);
        for anc in ancestors {
            for src in [s for s in (anc --> ?[?:CaptureSource]) if isinstance(s, CaptureSource)] {
                for c in [c2 for c2 in (src -[?:Emits]-> ?[?:Cause]) if isinstance(c2, Cause)] {
                    if c.priority > self.best_priority {
                        self.best_priority = c.priority;
                        self.best_label = c.label;
                    }
                }
            }
        }
        if self.best_label != "NONE" {
            self.verdict = self.best_label;
            print(f"  -> attributed to: {self.verdict} "
                  f"(priority={self.best_priority})");
        } else {
            print(f"  -> NO matching cause found in the catalog");
        }
    }

    def _collect_ancestors(self, start: Flag) -> list {
        guard: set = set();
        out: list = [start];
        cur = start;
        while cur is not None {
            if cur in guard {
                break;
            }
            guard.add(cur);
            parents = [p for p in (cur <-:Implies:--) if isinstance(p, Flag)];
            if not parents {
                break;
            }
            cur = parents[0];
            out.append(cur);
        }
        return out;
    }
}

with entry {
    # ---- Build the flag catalog (Implies tree) ----
    runtime = Flag(key="Runtime", enabled=True);
    thread_sched = Flag(key="Runtime:ThreadScheduling", enabled=True);
    tiered = Flag(key="Runtime:TieredCompilation", enabled=True);
