Guests at our hotel walk past service desks (spa session, room-service dinner, express laundry); each desk adds its price to whichever guest is currently passing by. Print each charge as it happens and what each guest owes at checkout.

```jac
"""Hotel service desks: guests walk past desks and each desk charges them."""

node Guest {
    has name: str = "";
    has total: float = 0.0;
}

node Desk {
    has service: str = "";
    has price: float = 0.0;
}

walker ChargeGuest {
    has guest_name: str = "";
    has owed: float = 0.0;

    can start with Root entry {
        visit [-->];
    }

    can visit_desk with Desk entry {
        charge = here.price;
        self.owed = self.owed + charge;
        print(f"{self.guest_name} charged ${charge:.2f} for {here.service} (running total: ${self.owed:.2f})");
        visit [-->];
    }

    can visit_guest with Guest entry {
        # Walker arrived at the guest's perch after walking the desk chain.
        # Nothing more to do; this ability just terminates the walk.
        pass;
    }
}

walker Checkout {
    can start with Root entry {
        visit [-->];
    }

    can tally with Guest entry {
        here.total = here.total;
        print(f"Checkout: {here.name} owes ${here.total:.2f}");
        visit [-->];
    }
}

with entry {
    alice = Guest(name="Alice");
    bob = Guest(name="Bob");

    spa = Desk(service="Spa session", price=45.00);
    dinner = Desk(service="Room-service dinner", price=32.50);
    laundry = Desk(service="Express laundry", price=18.75);

    root ++> alice ++> spa ++> dinner ++> laundry;
    root ++> bob   ++> spa ++> dinner ++> laundry;

    a = ChargeGuest(guest_name="Alice");
    alice spawn a;
    b = ChargeGuest(guest_name="Bob");
    bob spawn b;

