"""GHCR cleanup: reachability-based pruning of unreferenced image versions.

Models a container-image package's tag → manifest list → child manifests
as a graph, then walks it with a walker that distinguishes safe-to-delete
(orphan untagged) versions from live ones (tagged indices and their
multi-arch child descriptors). The cleanup walker demonstrates the
reachability traversal the issue requires.
"""

# ---------- node archetypes ----------

node Manifest {
    has digest: str = "";
    has age_days: int = 0;
    has tagged: bool = False;
    has referenced: bool = True;
}

node ManifestList {
    has tag: str = "";
    has digest: str = "";
}

node Package {
    has name: str = "";
    has allowlisted: bool = True;
}

# ---------- typed edges ----------
# IndexOf: a ManifestList points to a Manifest it references (child or self).
edge IndexOf { }

# HoldsTag: a Package holds a ManifestList by tag.
edge HoldsTag { }

# BelongsTo: a Manifest belongs to a Package.
edge BelongsTo { }

# ---------- walker: per-package reachability probe ----------

walker ReachabilityAuditor {
    has package_name: str = "";
    has min_age_days: int = 0;
    has deletable: list[str] = [];
    has retained: list[str] = [];

    can start with Root entry {
        visit [-->;
    }

    can enter_package with Package entry {
        if not here.allowlisted {
            print(f"[skip] {here.name} not in allowlist");
            disengage;
        }
        self.package_name = here.name;
        visit [->:BelongsTo:->];
    }

    can probe_manifest with Manifest entry {
        if here.tagged {
            self.retained.append(here.digest);
            return;
        }
        if here.age_days < self.min_age_days {
            self.retained.append(here.digest);
            return;
        }
        if not here.referenced {
            self.deletable.append(here.digest);
        } else {
            self.retained.append(here.digest);
        }
    }

    can summarize with Package entry {
        print(f"package {self.package_name}: "
              f"retained={self.retained}, "
              f"deletable={self.deletable}");
    }
}

# ---------- walker: tag → manifest list → child traversal ----------

walker TagReachability {
    has package_name: str = "";
    has visited: set[str] = set();
    has order: list[str] = [];

    can start with Root entry {
        visit [-->;
    }

    can pick_package with Package entry {
        self.package_name = here.name;
        visit [->:HoldsTag:->];
    }

    can walk_list with ManifestList entry {
        self.order.append(f"tag:{here.tag}");
        if here.digest not in self.visited {
            self.visited.add(here.digest);
            visit [->:IndexOf:->];
        }
    }

    can walk_manifest with Manifest entry {
        if here.digest in self.visited {
            return;
        }
        self.visited.add(here.digest);
        self.order.append(f"manifest:{here.digest}");
    }
}

# ---------- demo wiring ----------

with entry {
    jamovi = Package(name="jamovi-ubi9", allowlisted=True);
    rbase = Package(name="r-base-ubi9", allowlisted=True);
    excluded = Package(name="some-other-pkg", allowlisted=False);

    # jamovi-ubi9: tagged manifest list `latest` points at a multi-arch index
    # whose children (amd64, arm64) are untagged but live.
    jam_latest = ManifestList(tag="latest", digest="sha256:index-jamovi");
    jam_amd64 = Manifest(digest="sha256:amd64-jamovi", age_days=30,
                         tagged=False, referenced=True);
    jam_arm64 = Manifest(digest="sha256:arm64-jamovi", age_days=30,
                         tagged=False, referenced=True);
    jam_old = Manifest(digest="sha256:old-jamovi", age_days=120,
                       tagged=False, referenced=False);

    # r-base-ubi9: tagged `1.2.3` plus an orphan untagged version old enough
    # to be safe to delete.
    rb_123 = ManifestList(tag="1.2.3", digest="sha256:index-rbase");
    rb_amd64 = Manifest(digest="sha256:amd64-rbase", age_days=10,
                        tagged=False, referenced=True);
    rb_orphan = Manifest(digest="sha256:orphan-rbase", age_days=200,
                         tagged=False, referenced=False);

    jamovi +>:BelongsTo:+> jam_amd64;
    jamovi +>:BelongsTo:+> jam_arm64;
    jamovi +>:BelongsTo:+> jam_old;
    rbase +>:BelongsTo:+> rb_amd64;
    rbase +>:BelongsTo:+> rb_orphan;

    jamovi +>:HoldsTag:+> jam_latest;
    jam_latest +>:IndexOf:+> jam_amd64;
    jam_latest +>:IndexOf:+> jam_arm64;

    rbase +>:HoldsTag:+> rb_123;
    rb_123 +>:IndexOf:+> rb_amd64;

    root ++> jamovi;
    root ++> rbase;
    root ++> excluded;

    print("=== TagReachability: walk tag → manifest list → children ===");
    root spawn TagReachability();
    root spawn TagReachability();

    print("=== ReachabilityAuditor: min-age=60, allowlist enforced ===");
    auditor = ReachabilityAuditor(min_age_days=60);
    root spawn auditor;
}
