        if not in_allowlist {
            return;
        }
        # Minimum-age threshold for untagged deletion.
        if here.age_days < self.cutoff_days {
            return;
        }
        # Skip digests retained by the reachability audit.
        retained = False;
        for d in self.keep_digests {
            if d == here.digest {
                retained = True;
            }
        }
        if retained {
            print(f"  keep   {here.digest} (reachable, platform={here.platform})");
        } else {
            print(f"  DELETE {here.digest} (untagged, age={here.age_days}d, "
