```jac
"""Task dependency graph with memoization and cycle detection.

Models pyinvoke/invoke issue #461: tasks depend on other tasks, each task
memoizes its work so re-entry short-circuits, and the dependency walk must
detect cycles and execute prerequisites before their dependents.

Entities:
  Task     — a unit of work with memoized output.
  Config   — a cached configuration value that some tasks populate.
  Step     — a sub-step a task performs (build, fetch, validate, ...).
Edges:
  Requires   — task -> task (this task needs that task to run first).
  Produces   — task -> config / step (this task generates that artifact).
"""

node Config {
    has key: str = "";
    has value: str = "";
    has filled: bool = False;
}

node Step {
    has label: str = "";
    has done: bool = False;
}

node Task {
    has name: str = "";
    has memo: str = "";
    has ran: bool = False;
}

edge Requires { }
edge Produces { }

walker Executor {
    has visited: list = [];
    has log: list = [];

    can start with Root entry {
        visit [-->];
    }

    # Union trigger: a Task enters its prerequisite list through typed
    # Requires edges; a Config or Step entry is also valid because the
    # walker may step onto produced artifacts between tasks.
    can run with Task | Config | Step entry {
        if here in self.visited {
            # Cycle guard: the visited set is explicit because jac 0.36.1
            # walkers do not dedupe revisits on cyclic graphs.
            self.log.append(f"CYCLE detected at {here}");
            disengage;
        }
        self.visited.append(here);

        if here <: Task {
            t: Task = here;
            if t.ran {
                self.log.append(f"  memo hit: {t.name} -> {t.memo}");
                visit [-->];
            } else {
                # First: satisfy prerequisites (Requires edges).
                # We must walk the typed Requires edges out of this task
                # BEFORE running it, so dependents only run after deps.
                for (i, n) in enumerate([->:Requires:->]) {
                    # Recursive descent via spawn: the child walker walks
                    # its own prereqs, memoizes, then returns. This is
                    # the "BFS over requires" the issue describes, lifted
                    # into a walker instead of a hand-rolled queue.
                    child = Executor(visited=self.visited, log=self.log);
                    child spawn n;
                    self.visited = child.visited;
                    self.log = child.log;
                }
                # After deps, execute this task and memoize.
                t.memo = f"work({t.name})";
                t.ran = True;
                self.log.append(f"  ran: {t.name}");
                visit [-->];
            }
        } else {
            # Artifact nodes: just walk onward.
            visit [-->];
        }
    }
}

walker Auditor {
    can start with Root entry {
        self.audit();
    }

    def audit() -> None {
        # Reachability / dependency-ordering probe: walk every reachable
        # task via typed Requires edges and report visited order. Used
        # to confirm the topo-like order Executor produced.
        seen: list = [];
        stack: list = [->:Requires:->];
        while stack {
            n = stack.pop();
            if n in seen {
                continue;
            }
            seen.append(n);
            if n <: Task {
                t: Task = n;
                print(f"reachable task: {t.name} ran={t.ran} memo={t.memo}");
            }
            for (i, nx) in enumerate([n->:Requires:->]) {
                stack.append(nx);
            }
        }
    }
}

with entry {
    # Build a small task graph that mirrors the issue's "build_my_env
    # depends on ~half a dozen tasks" scenario. Tasks produce Config /
    # Step artifacts via typed Produces edges, and depend on each other
    # via typed Requires edges.
    t_read_cfg = Task(name="read_config");
    t_connect_api = Task(name="connect_api");
    t_fetch_vpc = Task(name="fetch_vpc");
    t_fetch_db = Task(name="fetch_db");
    t_provision = Task(name="provision_env");
    t_build_env = Task(name="build_my_env");

    cfg_vpc = Config(key="aws.vpc");
    cfg_db = Config(key="aws.db");
    st_client = Step(label="api_client");

    # Produces edges: tasks generate artifacts.
    t_read_cfg +>:Produces:+> cfg_vpc;
    t_fetch_vpc +>:Produces:+> cfg_vpc;
    t_fetch_db +>:Produces:+> cfg_db;
    t_connect_api +>:Produces:+> st_client;
    t_provision +>:Produces:+> cfg_vpc;
    t_provision +>:Produces:+> cfg_db;

    # Requires edges: build_my_env needs many tasks, which themselves
    # need other tasks. This is the "make-like" dep graph from the issue.
    t_build_env +>:Requires:+> t_provision;
    t_build_env +>:Requires:+> t_connect_api;
    t_provision +>:Requires:+> t_fetch_vpc;
    t_provision +>:Requires:+> t_fetch_db;
    t_fetch_vpc +>:Requires:+> t_read_cfg;
    t_fetch_db +>:Requires:+> t_read_cfg;
    t_connect_api +>:Requires:+> t_read_cfg;

    # A cycle to demonstrate the guard: validate depends on build_env,
    # and build_env depends on validate. The Executor must detect this.
    t_validate = Task(name="validate");
    t_build_env +>:Requires:+> t_validate;
    t_validate +>:Requires:+> t_build_env;

    # Wire everything to root and run.
    root ++> t_build_env;
    root spawn Executor();
    root spawn Auditor();

    print("execution log:");
    e = Executor();
    e spawn t_build_env;
    for line in e.log {
        print(f"  {line}");
    }
}
