    pipeline +>:Contains(position=1):+> build;
    pipeline +>:Contains(position=2):+> test;
    pipeline +>:Contains(position=3):+> publish;

    build +>:DependsOn(via_port="artifacts"):+> test;
    test +>:DependsOn(via_port="release"):+> publish;
    publish +>:DependsOn(via_port="rollback-check"):+> build;

    root spawn PipelineAudit();
}
