Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.

```jac
"""Channel performance analysis: walk restaurant order channels and aggregate evidence-backed revenue.

Models the scenario from Issue #45 (Task 5.6: Channel Performance): restaurants
operate across multiple channels (Dine-in, Takeaway, Delivery, Aggregators), and
each channel carries a stream of orders. A walker traverses the org hierarchy
(org -> restaurant -> branch -> channel) along typed edges, accumulates per-channel
performance from order nodes, and produces a single evidence-backed report with
integer-cents revenue totals.
"""

node Org {
    has name: str = "";
}

node Restaurant {
    has name: str = "";
    has cuisine: str = "";
}

edge Operates {}

node Branch {
    has name: str = "";
    has city: str = "";
}

edge BelongsTo {}

node Channel {
    has kind: str = "";
    has base_fee_cents: int = 0;
}

edge Serves {}

node Order {
    has order_id: str = "";
    has subtotal_cents: int = 0;
    has completed: bool = True;
}

edge Placed {}

walker ChannelAuditor {
    has report: dict = {};
    has visited: list = [];
    has max_depth: int = 12;

    can begin with Root entry {
        print(f"=== Channel Performance Audit ===");
        print(f"Scanning org graph (max_depth={self.max_depth})");
        self.report = {
            "channels": {},
            "orders_seen": 0,
            "orders_completed": 0,
            "orders_pending": 0,
            "channels_total": 0,
            "channels_with_revenue": 0,
        };
        visit [-->] else { disengage; };
    }

    can descend with Org entry {
        print(f"Org: {here.name}");
        self.visited.append(here.name);
        if self.visited.length > self.max_depth {
            disengage;
        }
        visit [-->] else { disengage; };
    }

    can descend with Restaurant entry {
        print(f"  Restaurant: {here.name} ({here.cuisine})");
        if self.visited.length > self.max_depth {
            disengage;
        }
        visit [-->] else { disengage; };
    }

    can descend with Branch entry {
        print(f"    Branch: {here.name} in {here.city}");
        if self.visited.length > self.max_depth {
            disengage;
        }
        visit [-->] else { disengage; };
    }

    can audit with Channel entry {
        self.report["channels_total"] += 1;
        if here.kind not in self.report["channels"] {
            self.report["channels"][here.kind] = {
                "order_count": 0,
                "revenue_cents": 0,
                "completed_count": 0,
                "pending_count": 0,
                "branch_count": 0,
            };
        }
        bucket = self.report["channels"][here.kind];
        bucket["branch_count"] += 1;
        print(f"      Channel[{here.kind}] base_fee={here.base_fee_cents}c");
        visit [-->] else { disengage; };
    }

    can tally with Order entry {
        self.report["orders_seen"] += 1;
        if here.completed {
            self.report["orders_completed"] += 1;
        } else {
            self.report["orders_pending"] += 1;
        }
        # Identify the channel kind by walking back one Placed edge
        # (Order -> Channel) — here.channel is not stored; we infer
        # via the single inbound Placed neighbor.
        parent_channels = [here <-:Placed:-];
        if parent_channels.length > 0 {
            ch = parent_channels[0];
            bucket = self.report["channels"][ch.kind];
            bucket["order_count"] += 1;
            if here.completed {
                bucket["completed_count"] += 1;
                bucket["revenue_cents"] += here.subtotal_cents;
                self.report["channels_with_revenue"] += 1;
            } else {
                bucket["pending_count"] += 1;
            }
            print(f"        Order#{here.order_id} "
                  f"{here.subtotal_cents}c "
                  f"{'OK' if here.completed else 'PENDING'}");
        }
    }
}

walker ChannelInvalidator {
    # Demonstrates cascade invalidation: when a Channel is invalidated,
    # every Order reachable via Placed edges is marked incomplete.
    has invalidated_kinds: list = [];

    can start with Root entry {
        visit [-->] else { disengage; };
    }

    can descend with Org entry {
        visit [-->] else { disengage; };
    }

    can descend with Restaurant entry {
        visit [-->] else { disengage; };
    }

    can descend with Branch entry {
        visit [-->] else { disengage; };
    }

    can invalidate with Channel entry {
        self.invalidated_kinds.append(here.kind);
        print(f"[INVALIDATE] channel kind={here.kind} (branch={here.name})");
        visit [-->] else { disengage; };
    }

    can mark with Order entry {
        if here.completed {
            here.completed = False;
            print(f"  -> order#{here.order_id} marked pending");
        }
    }
}

with entry {
    # Build the org -> restaurant -> branch -> channel graph
    acme = Org(name="Acme Hospitality");

    r1 = Restaurant(name="Acme Downtown", cuisine="Levantine");
    r2 = Restaurant(name="Acme Riverside", cuisine="Pan-Asian");

    b1 = Branch(name="DT-01", city="Dubai");
    b2 = Branch(name="RS-01", city="Dubai");

    # Channels per branch
    dine_in = Channel(kind="dine_in", base_fee_cents=0);
    takeaway = Channel(kind="takeaway", base_fee_cents=50);
    delivery = Channel(kind="delivery", base_fee_cents=200);
    aggregator = Channel(kind="aggregator", base_fee_cents=1500);

    # Wire graph: Org -> Restaurant (Operates) -> Branch (BelongsTo)
    #                                   -> Channel (Serves) -> Order (Placed)
    acme +>:Operates:+> r1;
    acme +>:Operates:+> r2;
    r1 +>:BelongsTo:+> b1;
    r2 +>:BelongsTo:+> b2;
    b1 +>:Serves:+> dine_in;
    b1 +>:Serves:+> takeaway;
    b1 +>:Serves:+> delivery;
    b2 +>:Serves:+> aggregator;
    b2 +>:Serves:+> delivery;

    # Orders under each channel (kept short for the demo)
    dine_in +>:Placed:+> Order(order_id="O-1001", subtotal_cents=12500);
    dine_in +>:Placed:+> Order(order_id="O-1002", subtotal_cents=8400, completed=False);
    takeaway +>:Placed:+> Order(order_id="O-2001", subtotal_cents=4300);
    takeaway +>:Placed:+> Order(order_id="O-2002", subtotal_cents=6100);
    delivery +>:Placed:+> Order(order_id="O-3001", subtotal_cents=9900);
    delivery +>:Placed:+> Order(order_id="O-3002", subtotal_cents=22000);
    aggregator +>:Placed:+> Order(order_id="O-4001", subtotal_cents=18500);
    aggregator +>:Placed:+> Order(order_id="O-4002", subtotal_cents=7400, completed=False);

    # 1) Audit: walk the graph, tally per-channel revenue & order counts
    root spawn ChannelAuditor();

