Our build system's dependency graph contains diamonds: shared libraries are needed by several modules. Count total build minutes across all tasks, making sure a task reachable by multiple paths is audited exactly once even though traversal reaches it more than once.

```jac
"""Build dependency graph: walk a diamond DAG once per task, summing build minutes."""

node Task {
    has title: str = "";
    has minutes: int = 0;
}

walker BuildAuditor {
    has total: int = 0;
    has visited: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can audit with Task entry {
        if here.title not in self.visited {
            self.visited.append(here.title);
            self.total += here.minutes;
            print(f"  auditing {here.title} (+{here.minutes} min)");
        } else {
            print(f"  skipping {here.title} (already counted)");
        }
        visit [-->];
    }
}

with entry {
    # Diamond: core <-> utils, shared by compiler and packager.
    core = Task(title="compile-core", minutes=10);
    utils = Task(title="compile-utils", minutes=8);
    compiler = Task(title="build-compiler", minutes=15);
    packager = Task(title="build-packager", minutes=12);

    root ++> core
        ++> utils
        ++> compiler
        ++> packager;

    # Wire the diamond: both compiler and packager depend on core and utils.
    compiler +>:Dep:+> core;
    compiler +>:Dep:+> utils;
    packager +>:Dep:+> core;
    packager +>:Dep:+> utils;

    auditor = BuildAuditor();
    root spawn auditor;
    print(f"Total build minutes (each task counted once): {auditor.total}");
}
