Task:
Patrol two factory zones with one monitoring routine that handles both temperature sensors (alert above 75 C) and smoke sensors (alert above 50 ppm). Print every reading as nominal or an alert, and summarize the alert list at the end.

```jac
"""Factory zone patrol: monitor temperature and smoke sensors across zones.

One monitoring routine handles both sensor types via a union trigger, prints
each reading as nominal or alert, and the walker summarizes the alert list
at the end.
"""

node Sensor {
    has label: str = "";

    def is_alert() -> bool;
}

node TempSensor(Sensor) {
    has celsius: float = 0.0;

    override def is_alert() -> bool {
        return self.celsius > 75.0;
    }
}

node SmokeSensor(Sensor) {
    has ppm: float = 0.0;

    override def is_alert() -> bool {
        return self.ppm > 50.0;
    }
}

node Zone {
    has name: str = "";
}

edge DeployedIn {
    has since: str = "";
}

walker Patrol {
    has alerts: list[str] = [];

    can start with Root entry {
        visit [->:DeployedIn:->];
    }

    can sweep with Zone entry {
        visit [->:DeployedIn:->];
    }

    can inspect with TempSensor | SmokeSensor entry {
        kind = "TEMP" if isinstance(here, TempSensor) else "SMOKE";
        reading = here.celsius if isinstance(here, TempSensor) else here.ppm;
        unit = "C" if isinstance(here, TempSensor) else "ppm";
        if here.is_alert() {
            label = f"[ALERT {kind}] {here.label} reading {reading}{unit}";
            print(label);
            self.alerts.append(label);
        } else {
            print(f"nominal {kind}: {here.label} at {reading}{unit}");
        }
    }
}

with entry {
    zone_a = Zone(name="Zone A");
    zone_b = Zone(name="Zone B");
    root +>:DeployedIn(since="Mon"):+> zone_a;
    root +>:DeployedIn(since="Mon"):+> zone_b;

    zone_a +>:DeployedIn:+> TempSensor(label="Boiler-1", celsius=91.5);
    zone_a +>:DeployedIn:+> SmokeSensor(label="Vent-1", ppm=12.0);
    zone_b +>:DeployedIn:+> TempSensor(label="Boiler-2", celsius=62.0);
    zone_b +>:DeployedIn:+> SmokeSensor(label="Vent-2", ppm=73.0);

    patrol = Patrol();
    root spawn patrol;

    print("--- Alert summary ---");
    if len(patrol.alerts) == 0 {
        print("All sensors nominal.");
    } else {
        print(f"{len(patrol.alerts)} alert(s):");
        for alert_label in patrol.alerts {
            print(alert_label);
        }
    }
}
