Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.

```jac
"""Recursive macro expansion chain: gccrs #3703.

Models a chain of macro expansions where each macro takes the previous
type as an argument and produces a new type that nests the prior one
four levels deep. The compiler blows up traversing the recursive type
structure. We model the macro chain as a walker walking typed edges.
"""

# Each enum produced by the macro is a Type node with a name.
node Type {
    has name: str = "";
    has depth: int = 0;
    # A type contains up to four nested payload variants of its previous type.
    has payload_count: int = 0;
}

# MacroDefinition: a macro_rules! declaration that takes one ident + one ty
# and emits an enum whose variants wrap that ty four times.
node MacroDef {
    has macro_name: str = "";
    has arity: int = 2;
}

# ExpansionStep: the typed relationship from a MacroDef to the Type it
# produces, recording how deep we are in the recursive chain.
edge ExpansionStep {
    has level: int = 0;
}

# Nesting: the typed relationship from a produced Type back to the
# previous Type it nests inside its four payload variants.
edge Nests {
    has slot: int = 0;
}

walker MacroExpander {
    # Per-walker state: how many expansions we have performed and
    # the deepest chain length reached so far.
    has expansions: int = 0;
    has max_depth: int = 0;
    has visited: list[str] = [];

    can start with Root entry {
        # Begin by walking every MacroDef hung off the root.
        visit [-->];
    }

    # A MacroDef expands into a fresh Type. We must record the visit so
    # cycles in the chain (if a later macro referenced an earlier type
    # we already produced) do not loop forever — this is the explicit
    # cycle policy the issue's recursion machinery needed.
    can expand with MacroDef entry {
        if here.macro_name in self.visited {
            print(f"[cycle-guard] skipping already-expanded {here.macro_name}");
            disengage;
        }
        self.visited.append(here.macro_name);
        self.expansions += 1;
        if self.max_depth < here.arity {
            self.max_depth = here.arity;
        }
        print(f"expanding {here.macro_name} (total so far: {self.expansions})");
        visit [->:ExpansionStep:->];
    }

    # At each produced Type, walk the Nesting edges back into the
    # payload variants. This models the compiler walking the recursive
    # type structure: 4 variants × N nested levels = the explosion.
    can walk_payload with Type entry {
        slots = here.payload_count;
        if slots > 0 {
            print(f"  walking {slots} nested variants of {here.name} (depth {here.depth})");
        }
        visit [->:Nests:->];
    }
}

with entry {
    # The macro_rules! declaration itself.
    fooN = MacroDef(macro_name="fooN", arity=27);

    # Each FooK type nests the previous Foo(K-1) four levels deep.
    # We model the chain with Nesting edges so the walker can recurse.
    prev = root ++> Type(name="()", depth=0, payload_count=0) ++> fooN;

    # Build Foo0 .. Foo27 with typed Nesting edges back to their parent type.
    names = [
        "Foo0", "Foo1", "Foo2", "Foo3", "Foo4", "Foo5", "Foo6", "Foo7",
        "Foo8", "Foo9", "Foo10", "Foo11", "Foo12", "Foo13", "Foo14",
        "Foo15", "Foo16", "Foo17", "Foo18", "Foo19", "Foo20", "Foo21",
        "Foo22", "Foo23", "Foo24", "Foo25", "Foo26", "Foo27",
    ];

    # Macro expansion: produce a Type per invocation and link it back.
    cur_type = Type(name="()", depth=0, payload_count=0);
    fooN +>:ExpansionStep(level=0):+> cur_type;

    i = 0;
    while i < 28 {
        new_type = Type(name=names[i], depth=i + 1, payload_count=4);
        # The four payload variants of new_type nest the previous type.
        s = 0;
        while s < 4 {
            cur_type +>:Nests(slot=s):+> new_type;
            s += 1;
        }
        # Each macro invocation produces this type.
        fooN +>:ExpansionStep(level=i + 1):+> new_type;
        cur_type = new_type;
        i += 1;
    }

    print("=== MacroExpander walking the recursive chain ===");
    root spawn MacroExpander();
    print(f"done: {MacroExpander().expansions} expansions, "
          f"max nesting observed: {MacroExpander().max_depth}");
}
