Task:
I'm writing a small blogging service in Jac. Authors keep unpublished drafts private on their own root; publishing moves the text onto the shared public graph where even anonymous readers can list articles and leave comments; deleting an article removes its comments too. Give me the whole thing: public feed, article view, and comment endpoints, private draft tools, and cascade deletion -- runnable standalone and under `jac start`.

```jac
"""Tiny blogging service: private drafts on the author's root, public articles
on the shared graph, cascade delete of comments when an article is removed,
and walkers for the public feed, article view, comments, drafts, and cleanup."""

# ---------- Edge archetypes (relationships) ----------

edge Drafts { has since: str = ""; }       # Root --> Draft
edge Publishes { has at: str = ""; }       # Root --> Article
edge CommentsOn { has body: str = ""; }    # Article --> Comment

# ---------- Node archetypes ----------

node Draft {
    has title: str = "";
    has body: str = "";
}

node Article {
    has title: str = "";
    has body: str = "";
    has published: bool = True;
}

node Comment {
    has author: str = "";
    has body: str = "";
}

# ---------- Public walkers (shared graph) ----------

walker PublicFeed {
    has feed: list = [];

    can start with Root entry {
        self.feed = [];
        visit [-->[?:Article]];
    }

    can collect with Article entry {
        self.feed.append({
            "title": here.title,
            "preview": here.body[:40],
        });
        visit [-->];
    }
}

walker ArticleView {
    has found: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can read with Article entry {
        if here.title == self.title_query {
            self.found = True;
            print(f"=== {here.title} ===");
            print(here.body);
            print(f"--- {len([-->])} comment(s) ---");
            visit [-->];
        } else {
            visit [-->];
        }
    }
}

walker CommentPoster {
    has success: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can find_article with Article entry {
        if here.title == self.title_query {
            self.success = True;
            here ++> Comment(author=self.author_name, body=self.comment_body);
            print(f"Comment by {self.author_name} added to '{here.title}'");
            disengage;
        } else {
            visit [-->];
        }
    }
}

walker ArticleDeleter {
    has removed: bool = False;
    has comment_count: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can find_target with Article entry {
        if here.title == self.title_query {
            # Cascade: count comments first, then delete the article.
            # `del Article` destroys the node and auto-purges its edges,
            # so the connected Comment nodes become orphans and disappear too.
            for c in [-->] {
                self.comment_count += 1;
                del c;
            }
            article_ref = here;
            del article_ref;
            self.removed = True;
            print(f"Deleted '{self.title_query}' "
                  f"({self.comment_count} comment(s) cascaded)");
            disengage;
        } else {
            visit [-->];
        }
    }
}

# ---------- Private walkers (author's own root) ----------

walker DraftManager {
    has action: str = "list";          # "list", "create", "edit", "delete"
    has title_query: str = "";
    has new_body: str = "";
    has result: list = [];
    has draft: object = None;

    can start with Root entry {
        if self.action == "create" {
            d = Draft(title=self.title_query, body=self.new_body);
            root ++> d;
            self.draft = d;
            print(f"Draft '{self.title_query}' saved privately");
        } else {
            visit [-->];
        }
    }

    can manage with Draft entry {
        if self.action == "list" {
            self.result.append({
                "title": here.title,
