Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.

```jac
"""Segmented layer DOM pairing: model the Highcharts v10 vs v11+ asymmetry.

A `SegmentedTrace` selects its row/column pairing strategy based on the
SVG tag of the first resolved element. The path branch defaults to
row-major when nothing is declared, while the rect branch defaults to
column-major for the *same* absent `domMapping`. We model the two
branches explicitly as node archetypes so a walker can audit which
branch was actually taken for a given layer and report any silent
mis-pairing before the layer ships.
"""

node Layer {
    has name: str = "";
    has declared_order: str = "";
}

# Mark types mirror the SVG tags the selector cares about. Each mark
# carries the dominant orientation the library actually uses on the
# wire so the pairing decision is observable, not implicit.
node PathMark {
    has series_count: int = 0;
    has point_count: int = 0;
}

node RectMark {
    has series_count: int = 0;
    has point_count: int = 0;
}

# The pairing strategy each branch chooses when `domMapping` is absent.
# Keeping the branches as distinct node archetypes exposes the asymmetry
# instead of hiding it inside a single conditional.
node PathBranch {
    has label: str = "path";
    has default_order: str = "row";
}

node RectBranch {
    has label: str = "rect";
    has default_order: str = "column";
}

# An element that matches neither branch — the third case the issue
# calls out, where the layer silently gets no highlight at all.
node UntaggedElement {
    has label: str = "other";
}

# Typed edges carry the relationship meaning: a layer declares which
# branch it relies on, and the marks that branch pairs against.
edge BranchOf { }
edge Pairs { }

# Walker that visits a layer, consults its declared branch, and walks
# every mark reachable through the branch's `Pairs` edges to compute
# the row/column order the layer will actually use at runtime. The
# issue's central complaint — the two branches disagree about the
# default — surfaces here as a single auditable report per layer.
walker PairingAuditor {
    has findings: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can audit_layer with Layer entry {
        branch = [-->](?:PathBranch);
        declared = here.declared_order;
        actual = "";
        if branch {
            actual = branch.default_order;
        }
        # When the adapter declared nothing, the issue is precisely
        # that path and rect pick opposite defaults. We record what
        # this layer will silently default to.
        effective = actual if declared == "" else declared;
        report_line = (
            f"layer={here.name} declared='{declared}' "
            f"branch={branch.label if branch else 'none'} "
            f"effective={effective}"
        );
        self.findings.append(report_line);
        if branch {
            visit [->:Pairs:->];
        } else {
            visit [-->] else { disengage; }
        }
    }

    can audit_mark with PathMark | RectMark | UntaggedElement entry {
        kind = "path" if isinstance(here, PathMark) else (
            "rect" if isinstance(here, RectMark) else "other"
        );
        series = here.series_count if isinstance(here, PathMark) else (
            here.series_count if isinstance(here, RectMark) else 0
        );
        points = here.point_count if isinstance(here, PathMark) else (
            here.point_count if isinstance(here, RectMark) else 0
        );
        self.findings.append(
            f"  mark kind={kind} series={series} points={points}"
        );
        visit [-->] else { disengage; }
    }
}

# Walker that mirrors the issue's third case: an element that matches
# neither branch. The layer silently emits an empty highlight set,
# which we report as an explicit "no pairing" finding.
walker MissingBranchAuditor {
    has findings: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can scan with Layer entry {
        branch = [-->](?:PathBranch);
        rect_branch = [-->](?:RectBranch);
        if not branch and not rect_branch {
            self.findings.append(
                f"layer={here.name} has NO branch — pairing will be empty"
            );
            visit [-->] else { disengage; };
        } else {
            self.findings.append(
                f"layer={here.name} routed to "
                f"{branch.label if branch else rect_branch.label}"
            );
            visit [-->] else { disengage; };
        }
    }
}

with entry {
    # Highcharts v10-style layer: rect mark, column-major default.
    # The issue measures this combination as a wrong pairing.
    v10_branch = RectBranch();
    v10_layer = Layer(name="stacked-bar-v10", declared_order="");
    rect_mark = RectMark(series_count=3, point_count=5);
    root ++> v10_branch;
    v10_branch +>:BranchOf:+> v10_layer;
    v10_layer +>:Pairs:+> rect_mark;

    # Highcharts v11+ layer: path mark, row-major default. Correct.
    v11_branch = PathBranch();
    v11_layer = Layer(name="stacked-bar-v11", declared_order="");
    path_mark = PathMark(series_count=3, point_count=5);
    root ++> v11_branch;
    v11_branch +>:BranchOf:+> v11_layer;
    v11_layer +>:Pairs:+> path_mark;

    # Diverging bar that explicitly declares row-major. Should pair
    # correctly on both v10 and v11+ because the declaration wins.
    diverging_layer = Layer(name="diverging-bar", declared_order="row");
    diverging_mark = PathMark(series_count=2, point_count=4);
    root ++> diverging_layer;
    diverging_layer +>:Pairs:+> diverging_mark;

    # Orphan layer with no branch at all — the third silent case.
    orphan_layer = Layer(name="orphan", declared_order="");
    root ++> orphan_layer;

    auditor = PairingAuditor();
    root spawn auditor;
    print("=== pairing audit ===");
    for line in auditor.findings {
        print(line);
    }

    missing = MissingBranchAuditor();
    root spawn missing;
    print("=== missing-branch audit ===");
    for line in missing.findings {
        print(line);
    }

    # Summarize the asymmetry the issue is about: with identical
    # `declared_order=""` the two branches report different effective
    # orders, which is the root cause of the silent mis-pairing.
    print("=== summary ===");
    print(
        "v10 rect branch defaults to column; v11 path branch defaults "
        "to row — same undeclared domMapping, opposite pairing."
    );
}
