```jac
"""Versioned naming orderings: model sibling-disambiguation ranks as a walker
that assigns versioned tokens to geometric rank points, and migrates older
tokens in place when the ordering version advances.

The original code stamped an unversioned lexicographic rank into every saved
document, so silently changing the comparator renumbered everything. Here the
rank is a typed edge carrying a versioned token (version + key), and a walker
walks the sibling group, assigns fresh tokens, and migrates old versions on
load.
"""

node Point {
    has x: float = 0.0;
    has y: float = 0.0;
    has z: float = 0.0;
}

node Curve {
    has title: str = "";
    has mid: Point = Point();
}

# A parent groups sibling curves; its set is the "parent set" used to
# disambiguate names within a namespace.
node Group {
    has label: str = "";
}

# Versioned rank edge: carries the ordering version and the rank key.
# Migrating an old document means rewriting this edge in place.
edge Ranked {
    has rank_version: int = 0;
    has rank_key: int = 0;
    has mid_x: float = 0.0;
    has mid_y: float = 0.0;
    has mid_z: float = 0.0;
    has curve_title: str = "";
}

# Bumps the on-disk rank token version. Anything older is migrated on load.
walker Ordering {
    has new_version: int = 0;

    can start with Root entry {
        visit [->:Group:->];
    }

    can pick_siblings with Group entry {
        # Walk every sibling Curve connected by a Ranked edge and stamp a
        # fresh versioned token. The current comparator is lexicographic
        # on (x, y, z); the version is what guards callers against silent
        # renumbering.
        visit [here ->:Ranked:->];
    }

    can stamp with Curve entry {
        # Collect this sibling's mid-point (shared by both old and new
        # tokens) so the ranker is reproducible.
        pt = here.mid;
        new_key = compute_key(pt.x, pt.y, pt.z);
        here +>:Ranked(
            rank_version=self.new_version,
            rank_key=new_key,
            mid_x=pt.x,
            mid_y=pt.y,
            mid_z=pt.z,
            curve_title=here.title
        ):+> here;
    }
}

# The migration walker: when an old token is encountered, it is rewritten
# in place to the current ordering version. Domain logic preserved.
walker Migrate {
    has target_version: int = 0;
    has migrated: int = 0;

    can start with Root entry {
        visit [->:Ranked:->];
    }

    can rewrite with Curve entry {
        old = [-->];
        for (_, node) in enumerate(old) {
            if isinstance(node, Ranked) {
                if node.rank_version < self.target_version {
                    node.rank_version = self.target_version;
                    self.migrated += 1;
                }
            }
        }
        visit [here ->:Ranked:->];
    }
}

# Helper: lexicographic key on (x, y, z), scaled to int so the token is
# stable across saves. This is the comparator whose version we stamp.
def compute_key(x: float, y: float, z: float) -> int {
    ix = int(x * 1000);
    iy = int(y * 1000);
    iz = int(z * 1000);
    return ix * 1000000 + iy * 1000 + iz;
}

with entry {
    g = Group(label="parent_set_A");
    root +>:Group:+> g;

    c1 = Curve(title="alpha", mid=Point(x=1.0, y=2.0, z=3.0));
    c2 = Curve(title="beta",  mid=Point(x=1.0, y=2.0, z=4.0));
    c3 = Curve(title="gamma", mid=Point(x=2.0, y=0.0, z=0.0));

    g ++> c1 ++> c2 ++> c3;

    # Simulate an older saved document: stamp rank edges at version 1.
    root spawn Ordering(new_version=1);

    # Advance the ordering version and migrate in place.
    root spawn Ordering(new_version=2);

    mig = Migrate(target_version=2);
    root spawn mig;
    print(f"migrated {mig.migrated} rank edges to version 2");
}
