Core scenario: BigQuery-CLI jobs run as `job.requestedBy`, but sandbox env
resolution is gated by a role-tier hierarchy. A `member`-level owner asking
for an `admin`-scoped credential (e.g. `google_sa_key_b64`) gets an empty
value injected, so the CLI activation command silently fails with
`exit status 1`.

This demo models that mismatch with a typed-edge graph and walks it with a
walker that reports exactly the silent-empty-injection failure mode.
"""

node User {
    has name: str = "";
    has level: int = 0;  # member=0, power_user=1, admin=2
}

node Credential {
    has env_var: str = "";
    has scope_level: int = 0;  # minimum role tier required to see this var
}

node Job {
    has title: str = "";
    has requested_by: str = "";
}

edge Owns {}
edge Requires {}
edge Granted {}

walker CredentialAuditor {
    has findings: list[str] = [];
    has guard: set[str] = set();  # explicit cycle policy (jac 0.36.1 has none built-in)

    can start with Root entry {
        visit [-->];
    }

    can audit with Job entry {
        self.guard.add(here.title);
        # A job references some required credentials via typed `Requires` edges.
        visit [->:Requires:->];
    }

    can inspect with Credential entry {
        # Walk back to the User via `Owns`, then forward to `Granted` creds
        # the sandbox resolver would have picked for that user.
        visit [<--:Owns:--];
    }

    can compare with User entry {
        # Look at every Granted credential the sandbox would inject for
        # this user and check whether the Job's Required credentials are
        # all covered at the user's role tier.
        for granted in [->:Granted:->] {
            for required in [<--:Requires:--] {
                if granted.env_var == required.env_var {
                    if here.level < required.scope_level {
                        finding = (
                            f"[SILENT-EMPTY] job '{required.title}' "
                            f"requested by '{here.name}' (level={here.level}) "
                            f"needs '{granted.env_var}' "
                            f"(scope_level={required.scope_level})"
                        );
                        self.findings.append(finding);
                    } else {
                        ok = (
                            f"[OK] job '{required.title}' requested by "
                            f"'{here.name}' has '{granted.env_var}' "
                            f"at scope_level={required.scope_level}"
                        );
                        self.findings.append(ok);
                    }
                }
            }
        }
    }
}

