node StateSummary {
    has l3_bc_count: int = 0;
    has l4_vp_count: int = 0;
    has notes: str = "";
}

node StoryIndexSummary {
    has total_stories: int = 0;
    has total_points: int = 0;
}

edge TracksBC { }
edge TracksVP { }
edge TracksStory { }
edge OwnsSummary { }

walker RecomputeState {
    has seen_bc: list[str] = [];
    has seen_vp: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can enter_summary with StateSummary entry {
        self.seen_bc = [];
        self.seen_vp = [];
        visit [->:TracksBC:->];
        visit [->:TracksVP:->];
    }

    can count_bc with BC entry {
        if not here.bid in self.seen_bc {
            self.seen_bc.append(here.bid);
            here.l3_bc_count = len(self.seen_bc);
        }
        visit [->:TracksBC:->] else { disengage; }
    }

    can count_vp with VP entry {
        if not here.vid in self.seen_vp {
            self.seen_vp.append(here.vid);
            here.l4_vp_count = len(self.seen_vp);
        }
        visit [->:TracksVP:->] else { disengage; }
    }
}

walker RecomputeStories {
    has sids: list[str] = [];
    has points: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can enter_index with StoryIndexSummary entry {
        self.sids = [];
        self.points = 0;
        visit [->:TracksStory:->];
    }

    can tally with Story entry {
        if not here.sid in self.sids {
