    # Connect: stories split, BCs implement stories, VPs trace to BCs,
    # the summary sits beside everything and the auditor audits it.
    root +>:Audits:+> summary;
    s301a +>:SplitInto:+> s301b;
    s303  +>:SplitInto:+> s304;
    bc205008 +>:ImplementedBy:+> s303;
    vp058    +>:TracesTo:+> bc205008;

    # Also point HasPoints edges so the totals reconcile cleanly.
