"""Toll plaza collector for gate G-4.

Models a toll booth as a walker that visits each vehicle at the gate,
computes the per-vehicle fare, prints a payment line, and accumulates
total revenue collected during the sweep.
"""

node Vehicle {
    has name: str = "";
    has tons: float = 0.0;
}

node Car(Vehicle) {}
node Truck(Vehicle) {}
node Motorcycle(Vehicle) {}

walker TollCollector {
    has gate: str = "G-4";
    has revenue: float = 0.0;

    can announce with Root entry {
        print(f"== Toll gate {self.gate} opening ==");
        visit [-->] else { disengage; }
    }

    can charge with Car | Truck | Motorcycle entry {
        fare: float = 0.0;
        kind: str = "";
        if isinstance(here, Car) {
            kind = "Car";
            fare = 2.50;
        } elif isinstance(here, Truck) {
            kind = "Truck";
            fare = 2.50 + 0.50 * here.tons;
        } elif isinstance(here, Motorcycle) {
            kind = "Motorcycle";
            fare = 1.00;
        }
        self.revenue = self.revenue + fare;
        tons_note: str = f", {here.tons}t" if here.tons > 0.0 else "";
        print(f"{kind} {here.name}{tons_note} -> ${fare:.2f}");
        visit [-->] else { disengage; }
    }
