### Outcome

Create projects quickly without introducing a general custom-database builder.

### Acceptance criteria

- [ ] System templates are versioned and cannot be mutated by users.
- [ ] Applying a template copies structure and records template/version provenance.
- [ ] Initial templates cover a finite client project and a creator content project.
- [ ] Template application is idempotent.
- [ ] Existing projects do not change when a template version changes.
- [ ] A usability check creates a templated project in under two minutes.

### Dependencies

[#26](https://github.com/xuanhieu2611/Slipwell/issues/26).

### Spec references

PRJ-05, section 10.4, and section 21.

Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.

```jac
"""Versioned project templates.

Models SLIP-027: system templates are versioned and immutable, users
clone them into their own project tree via a walker that copies
structure and records template/version provenance. A reachability
walker also demonstrates the cascade-invalidation behaviour that the
issue motivates (deleting a template invalidates projects derived
from it).
"""

node Project {
    has name: str = "";
    has kind: str = "";
    has derived_from: str = "";
    has derived_version: str = "";
    has valid: bool = True;
}

node Template {
    has name: str = "";
    has version: str = "";
    has immutable: bool = True;
}

node Task {
    has title: str = "";
    has done: bool = False;
}

edge Suggests { }
edge DerivesFrom { has version: str = ""; }

walker Templater {
    has owner_name: str = "";

    can start with Root entry {
        print(f"Templater '{self.owner_name}' is browsing system templates");
        visit [-->];
    }

    can pick with Template entry {
        print(f"  applying template {here.name} v{here.version} (immutable={here.immutable})");
        # Clone the template tree into a project, preserving version provenance.
        new_project = Project(name=self.owner_name + "-" + here.name,
                             kind="templated",
                             derived_from=here.name,
                             derived_version=here.version);
        here +>:Suggests::+> new_project;
        # Copy every task reachable from the template under typed edges,
        # recording template provenance on each copy.
        new_project spawn Copier(template_name=here.name,
                                 template_version=here.version);
        visit [-->];
    }

    can inspect with Project entry {
        status = "valid" if here.valid else "INVALIDATED";
        print(f"  project {here.name} kind={here.kind} [{status}] "
              f"from {here.derived_from}@{here.derived_version}");
        visit [-->];
    }
}

walker Copier {
    has template_name: str = "";
    has template_version: str = "";

    can copy with Project entry {
        visit [->:Suggests:->];
    }

    can place with Task entry {
        copied = Task(title=here.title, done=False);
        here +>:Suggests::+> copied;
    }
}

walker Reachability {
    # Demonstrates cascade invalidation: walk every project and
    # mark it invalid when its source template is gone.
    can start with Root entry {
        visit [-->];
    }

    can traverse with Project | Task entry {
        visit [-->];
    }

    can finish with Template entry {
        # If a project derives from this template version, mark it invalid.
        for proj in [here +>:DerivesFrom:+>] {
            proj.valid = False;
        }
    }
}

walker ApplyAgain {
    # Idempotence check: applying the same template twice should not
    # create duplicate projects.
    has owner_name: str = "";
    has applied: bool = False;

    can start with Root entry {
        for t in [-->] {
            if isinstance(t, Template) and t.name == "creator-content" {
                existing = [t +>:Suggests:+>];
                if len(existing) > 0 {
                    self.applied = True;
                    print(f"idempotent: '{self.owner_name}' already has "
                          f"{len(existing)} project(s) from creator-content; "
                          f"skipping re-apply");
                }
            }
        }
        visit [-->];
    }
}

with entry {
    # Two immutable system templates at distinct versions.
    tpl_finite = Template(name="finite-client", version="1.0.0");
    tpl_creator_v1 = Template(name="creator-content", version="1.0.0");
    tpl_creator_v2 = Template(name="creator-content", version="1.2.0");

    # A template's suggested task structure (copied into a project on apply).
    root +>:Suggests::+> tpl_finite +>:Suggests::+> Task(title="brief")
        +>:Suggests::+> Task(title="milestones")
        +>:Suggests::+> Task(title="deliverables");
    root +>:Suggests::+> tpl_creator_v1 +>:Suggests::+> Task(title="outline")
        +>:Suggests::+> Task(title="draft");
    root +>:Suggects::+> tpl_creator_v2 +>:Suggests::+> Task(title="outline")
        +>:Suggests::+> Task(title="draft")
        +>:Suggests::+> Task(title="publish");

    print("--- applying templates ---");
    root spawn Templater(owner_name="alice");

    print("--- idempotence check (re-apply creator-content v1.2.0) ---");
    ApplyAgain(owner_name="alice") spawn root;

    print("--- cascade invalidation if a template is removed ---");
    Reachability() spawn root;
}
