walker Certifier {
    has visited: list[str] = [];
    has order: list[str] = [];
    has cycle_flag: bool = False;

    can start with Root entry {
        print(f"[Certifier] platform={self.platform_name} starting stage sweep");
        visit [->:Prereq:->];
