```jac
"""Dependency audit walker: traverse the dependency graph and flag vulnerable packages.

Models the scenario from issue #9 — a hand-rolled dependency walker that
recursively visits each package's transitive dependencies, accumulates
vulnerability findings, and reports packages that should be patched or
migrated off. Uses typed edges for the depends-on relationship and a
walker with an explicit visited-set (Jac 0.36.1 has no built-in cycle
guard) to traverse without infinite loops on circular dependencies.
"""

node Package {
    has name: str = "";
    has version: str = "";
    has available: bool = True;
}

# A package may pull in known advisories. Multiple findings per package.
node Advisory {
    has cve: str = "";
    has severity: str = "low";
    has title: str = "";
}

# Typed edge: the source package depends on the target package.
edge DependsOn {
    has kind: str = "runtime";
}

# Typed edge: a package ships a particular advisory finding.
edge HasAdvisory {
}

walker DependencyAuditor {
    # Cycle guard: jac 0.36.1 walkers do not dedupe nodes on cycles.
    has visited: list[str] = [];
    # Accumulated findings, reported at the end.
    has findings: list[dict] = [];

    can start with Root entry {
        print("Starting dependency audit from root");
        visit [-->];
    }

    # Union ability: one routine serves both Package and Advisory nodes
    # because both carry a name field we record in the visited set.
    can audit with Package | Advisory entry {
        if here.name in self.visited {
            disengage;
        }
        self.visited.append(here.name);

        if isinstance(here, Package) {
            status = "OK" if here.available else "BLOCKED";
            print(f"[pkg] {here.name}@{here.version} -> {status}");
            visit [->:DependsOn:->];
        } else {
            finding = {
                "cve": here.cve,
                "severity": here.severity,
                "title": here.title,
