```jac
"""Observation chain inspector: model nested observation models as a node
chain and walk it with a reflective walker that finds components by type
and traverses wrappers the way EpiSewer.jl does by reflection.
"""

# ---- Core entity archetypes --------------------------------------------------

node ErrorModel {
    has name: str = "BaseError";
}

node LatentDelay {
    has delay: int = 0;
    has inner: ErrorModel | LatentDelay | Split = None;
}

node NegBinomError {
    has disp: float = 1.0;
    has inner: ErrorModel | LatentDelay | Split = None;
}

node Split {
    has branches: list = [];
}

# Edge archetypes: every "holds an inner model" relationship is typed so the
# walker can traverse it explicitly instead of by reflection.
edge Wraps {
    has slot: str = "";
}

edge BranchesInto {
    has index: int = 0;
}

# ---- Walker: reflectively walk the chain, accumulate lead-in, find by type ---

walker ChainInspector {
    has total_lead_in: int = 0;
    has targets_found: list = [];
    has target_type: str = "LatentDelay";
    has max_depth: int = 32;
    has depth: int = 0;

    can start with Root entry {
        self.depth = 0;
        self.total_lead_in = 0;
        self.targets_found = [];
        visit [-->];
    }

    can descend with ErrorModel | LatentDelay | NegBinomError entry {
        # Guard against cycles the same way a hand-rolled walker would
        # (jac 0.36.1 has no built-in visited-set on walkers).
        self.depth += 1;
        if self.depth > self.max_depth {
            print(f"[guard] max depth {self.max_depth} reached, disengaging");
            disengage;
        }

        # Match-by-type, equivalent to a reflective _lead_in dispatch.
        if self.target_type == "LatentDelay" and here.type == LatentDelay {
            lead = here.delay - 1;
            inner_lead = 0;
            for inner_node in [-->] {
                if inner_node.type == LatentDelay {
                    # We will recurse and let the ability accumulate
                    # the rest; we only contribute the direct delay here.
                    pass;
                }
            }
            self.targets_found.append({
                "type": "LatentDelay",
                "delay": here.delay,
                "contribution": lead,
            });
            self.total_lead_in += lead;
        }

        print(f"  " + "  " * self.depth + f"-> {type_name(here)} "
              + (f"(delay={here.delay})" if here.type == LatentDelay else "")
              + (f"(disp={here.disp})" if here.type == NegBinomError else ""));

        visit [-->];
    }

    can split_visit with Split entry {
        self.depth += 1;
        if self.depth > self.max_depth {
            print(f"[guard] max depth reached inside Split, disengaging");
            disengage;
        }
        print(f"  " + "  " * self.depth + f"-> Split with "
              f"{len(here.branches)} branch(es)");
        # Walk every named branch. Hand-rolled code recurses into Tuple /
        # Vector / NamedTuple separately; here the edge carries the index.
        visit [-->];
    }
}

walker CascadeInvalidator {
    # Demonstrates the inverse traversal the issue hints at: a cascade
    # delete / invalidation walker that walks the chain the same way the
    # inspector does, but mutates state as it goes.
    has invalidated: int = 0;

    can start with Root entry {
        self.invalidated = 0;
        visit [-->];
    }

    can invalidate with ErrorModel | LatentDelay | NegBinomError | Split entry {
        self.invalidated += 1;
        tag = type_name(here);
        print(f"[cascade] invalidating {tag}");
        visit [-->];
    }
}

# ---- Tiny helper (kept as a method on the walker module-via-def) -------------
# A def returning a type name works in jac 0.36.1; we use it for readable
# prints and for the type-keyed match above. `type_name` is a built-in on
# node instances.

with entry {
    # Build a chain that mirrors the issue's nesting:
    #   LatentDelay(delay=4) -> NegBinomError(disp=2.0)
    #                       -> LatentDelay(delay=2)
    #                       -> Split with two branches:
    #                            base ErrorModel
    #                            LatentDelay(delay=3) -> ErrorModel
    leaf_a = ErrorModel(name="BaseError");
    leaf_b1 = ErrorModel(name="AltError");
    leaf_b2 = LatentDelay(delay=3, inner=leaf_a);

    split_node = Split(branches=[leaf_b1, leaf_b2]);
    inner_delay = LatentDelay(delay=2, inner=split_node);
    nb_error = NegBinomError(disp=2.0, inner=inner_delay);
    outer_delay = LatentDelay(delay=4, inner=nb_error);

    root ++> outer_delay;

    print("=== ChainInspector: sum of (delay - 1) over every LatentDelay ===");
    inspector = ChainInspector(target_type="LatentDelay");
    root spawn inspector;
    print(f"\nTotal lead-in consumed by chain: {inspector.total_lead_in}");
    print(f"LatentDelay nodes found: {len(inspector.targets_found)}");
    for hit in inspector.targets_found {
        print(f"  - {hit}");
    }

    print("\n=== CascadeInvalidator: walk and invalidate the same chain ===");
    invalidator = CascadeInvalidator();
    root spawn invalidator;
    print(f"\nNodes invalidated: {invalidator.invalidated}");
}
