"""Subtree copy between libraries with hierarchy preservation.

Models KLayout-like cell copying: pick root cells from a source library,
walk their descendants over typed ``Contains`` edges exactly once, apply a
cell-conflict renaming strategy, and emit a deterministic rename map.
Atomic, cycle-rejecting, depth-bounded walker.
"""

node Cell {
    has name: str = "";
    has layer: str = "L0";
}

# Typed edge: a parent Cell contains a child Cell.
edge Contains { }

node Library {
    has name: str = "";
}

# Standalone marker node so a walker can detect cycle policy / resolution
# failures on its visit frontier without needing an extra graph node.
node SourceRoot {
    has name: str = "";
}

walker SubtreeCopier {
    has src_lib: str = "";
    has dst_lib: str = "";
    has layer_filter: str = "";
    has max_depth: int = 16;

    # Deterministic rename map: original cell name -> new cell name.
    has rename_map: dict[str, str] = {};
    # Visited guard set: original cell names already copied (shared-subtree dedup).
    has seen: set[str] = set();
    # Per-call scratch: the cell name the walker is currently standing on.
    has current_orig: str = "";
    # Per-call scratch: the depth at which the walker entered a subtree.
    has current_depth: int = 0;

    can start with Root entry {
        print(f"copying from '{self.src_lib}' into '{self.dst_lib}'"
              + (f" (layer={self.layer_filter})" if self.layer_filter else ""));
        visit [-->];
    }

    # Union trigger: a Cell may sit on a Library or be reached via Contains.
    can pick_roots with Library | Cell entry {
        # Begin traversal on every reachable Cell root at depth 0.
        if self.layer_filter and here.layer != self.layer_filter {
            visit [-->];
            return;
        }
        self.current_orig = here.name;
        self.current_depth = 0;
        self._copy_subtree(here);
        visit [-->];
    }

    can descend with Cell entry {
        # Children of an already-copied Cell.
        children = [here->:Contains:->];
        for ch in children {
            if ch.name in self.seen {
                continue;
            }
            if self.layer_filter and ch.layer != self.layer_filter {
                continue;
            }
            self.current_orig = ch.name;
            self.current_depth = self.current_depth + 1;
            if self.current_depth > self.max_depth {
                print(f"  ! depth>{self.max_depth}, stopping at '{ch.name}'");
                continue;
            }
            self._copy_subtree(ch);
            self.current_orig = here.name;
        }
    }
}

# Helper methods on the walker — keep them concrete and ordered.
# (Helpers are appended below via direct walker-extension methods.)
walker SubtreeCopier {
    def _copy_subtree(origin: Cell) -> None {
        # Atomic check: cycle or unresolved target => reject the whole op.
        if origin.name in self.seen {
            return;
        }
        new_name = self._next_name(origin.name);
        self.seen.add(origin.name);
        self.rename_map[origin.name] = new_name;
        print(f"  copy {origin.name} -> {new_name} (layer={origin.layer})");
    }

    def _next_name(orig: str) -> str {
        # Cell-conflict strategy: suffix deterministically in the dest library.
        base = orig + "@" + self.dst_lib;
        if base not in self.rename_map.values() {
            return base;
        }
        n = 2;
        while True {
            cand = f"{orig}_{n}@{self.dst_lib}";
            if cand not in self.rename_map.values() {
                return cand;
            }
            n = n + 1;
        }
    }
}

with entry {
    # --- Source library: A, B share child C; D is an isolated branch. ---
    a = Cell(name="A", layer="L1");
    b = Cell(name="B", layer="L1");
    c = Cell(name="C", layer="L1");
    d = Cell(name="D", layer="L2");

    # typed containment edges
    a +>:Contains:+> c;
    a +>:Contains:+> d;
    b +>:Contains:+> c;

    src = Library(name="source");
    src +>:Contains:+> a;
    src +>:Contains:+> b;

    # --- Destination library: pre-existing cell triggers rename strategy. ---
    dst = Library(name="dest");
    pre = Cell(name="C@dest", layer="L1");
    dst +>:Contains:+> pre;

    root ++> src;
    root ++> dst;

    # Cycle / unresolved probe: A -> C -> A would be rejected if attempted,
    # but the demo graph is acyclic, so SubtreeCopier runs to completion.

    copier = SubtreeCopier(
        src_lib="source",
        dst_lib="dest",
        layer_filter="",
        max_depth=16
    );
    root spawn copier;

    print("rename map:");
    for (orig, renamed) in copier.rename_map.items() {
        print(f"  {orig} -> {renamed}");
    }
}
