    root ++> intent
        ++> design
        ++> task_a
        ++> task_b
        ++> summary;

    auditor = PipelineAuditor();
    root spawn auditor;

    print(f"\nValidated tasks: {auditor.validated_count}");
    print(f"Gaps found: {auditor.gaps}");
}
