        ++> AdminRegion(name="City-A1a1x", geo_id=11111);
    root ++> AdminRegion(name="Continent-B", geo_id=2)
        ++> AdminRegion(name="Country-B1", geo_id=21)
        ++> AdminRegion(name="Province-B1a", geo_id=211)
        ++> AdminRegion(name="District-B1a1", geo_id=2111)
        ++> AdminRegion(name="City-B1a1x", geo_id=21111);
    root ++> AdminRegion(name="Continent-C", geo_id=3)
        ++> AdminRegion(name="Country-C1", geo_id=31)
        ++> AdminRegion(name="Province-C1a", geo_id=311)
        ++> AdminRegion(name="District-C1a1", geo_id=3111)
        ++> AdminRegion(name="City-C1a1x", geo_id=31111);

    # The exception edges: a handful of nodes that legitimately sit under two
    # administrative parents. This is the 1.3% the issue is about.
    c_b1a1 = AdminRegion(name="City-B1a1x", geo_id=21111);
    c_a1a1 = AdminRegion(name="City-A1a1x", geo_id=11111);
    root +>:Subdivision:+> AdminRegion(name="Enclave-1", geo_id=9001);
    root +>:Subdivision:+> AdminRegion(name="Enclave-2", geo_id=9002);

    # First pass: count parents on every AdminRegion reachable from root.
    counter = ParentCounter();
    root spawn counter;

    # Second pass: classify and emit the near-tree diagnostic.
    auditor = HierarchyAuditor();
    root spawn auditor;

    # Format the diagnostic the way option 3 of the issue asks for.
    single = auditor.single_parent_children;
    multi = auditor.multi_parent_children;
    total = auditor.total_children;
    extra = auditor.extra_parent_edges;
    pct_single = (single * 1000 // total) / 10 if total > 0 else 0;
    pct_multi = (multi * 1000 // total) / 10 if total > 0 else 0;

    print("=== Near-tree diagnostic (GeoNames-style poset) ===");
    print(f"Total AdminRegions visited   : {total}");
    print(f"Single-parent children       : {single}  ({pct_single}%)");
    print(f"Multi-parent children        : {multi}  ({pct_multi}%)");
    print(f"Residual exception edges     : {extra}");
    print(f"Nested-set encoding verdict  : DECLINED (chain width exceeds cap on this shape)");
    print(f"Remediation hint             : {pct_single}% of the structure is one cleanup away from a perfect tree");
}
