node Issue {
    has title: str = "";
    has open: bool = True;
}

edge ParentChild { }
edge Blocks { }

walker TreeRenderer {
    has path: list[str] = [];
    has visited: list[str] = [];
    has max_depth: int = 32;
    has rendered: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can descend with Issue entry {
        self.rendered += 1;
        cycle_hit = here.title in self.visited;
        marker = " \u21ba" if cycle_hit else "";
        print(f"{'  ' * len(self.path)}- {here.title} (open={here.open}){marker}");
        if cycle_hit {
            return;
