        if len(self.path) >= self.max_depth {
            print(f"{'  ' * (len(self.path) + 1)}... depth cap");
            return;
        }
        self.path.append(here.title);
        self.visited.append(here.title);
        visit [->:ParentChild:->];
        self.path.pop();
        self.visited.pop();
    }

    can across with Issue entry {
        visit [->:Blocks:->];
    }
}

