Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.

```jac
"""Fork inheritance immutability demo.

Models the issue's core scenario: a parent transcript exists, a child is
forked from it, and the child's inherited prefix must remain immutable even
when the parent is later edited, compacted, excluded, deleted, or reordered.

Entities:
    - Message: a single transcript entry with a payload string.
    - ParentTranscript: a linear chain of messages (linked via Next edges).
    - ForkedChild: a snapshot taken at a fork offset; must freeze its
      inherited prefix while still allowing continuation messages.

The ``ForkInspector`` walker walks a child snapshot and verifies that the
inherited prefix is unaffected by later parent mutations.
"""

node Message {
    has body: str = "";
}

edge Next { }

node ParentTranscript {
    has title: str = "";

    can snapshot with Message entry {
        visit [->:Next:->];
    }
}

node ForkedChild {
    has owner: str = "";
    has inherited_count: int = 0;
}

edge InheritedPrefix {
    has frozen: bool = True;
}

edge Continuation { }

walker ForkInspector {
    has mismatch: int = 0;
    has expected_count: int = 0;
    has seen: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can audit_child with ForkedChild entry {
        self.expected_count = here.inherited_count;
        visit [->:InheritedPrefix:->];
    }

    can audit_inherited with Message entry {
        self.seen += 1;
        if self.seen <= self.expected_count {
            if not here.body.startswith("INH-") {
                self.mismatch += 1;
            }
        }
        if here.body.startswith("MUTATED-") or here.body.startswith("DELETED-") {
            self.mismatch += 1;
        }
        visit [->:Next:->];
    }
}

walker ForkSimulator {
    can start with Root entry {
        parent = ParentTranscript(title="live-parent");
        root ++> parent;

        parent ++> Next ++> Message(body="INH-1");
        parent ++> Next ++> Message(body="INH-2");
        parent ++> Next ++> Message(body="INH-3");
        parent ++> Next ++> Message(body="INH-4");
        parent ++> Next ++> Message(body="INH-5");

        child = ForkedChild(owner="alice", inherited_count=3);
        root ++> child;

        head = Message(body="INH-1");
        two = Message(body="INH-2");
        three = Message(body="INH-3");
        child +>:InheritedPrefix:+> head;
        head +>:Next:+> two;
        two +>:Next:+> three;

        cont_a = Message(body="CONT-A");
        cont_b = Message(body="CONT-B");
        child +>:Continuation:+> cont_a;
        cont_a +>:Continuation:+> cont_b;

        print("--- BEFORE parent mutation ---");
        inspector = ForkInspector();
        root spawn inspector;
        print(f"inherited prefix seen={inspector.seen}, mismatch={inspector.mismatch}");

        inherited = [head, two, three];
        i = 0;
        while i < len(inherited) {
            m = inherited[i];
            m.body = "MUTATED-" + m.body;
            i += 1;
        }

        print("--- AFTER parent-prefix rewrite attempt ---");
        inspector2 = ForkInspector();
        root spawn inspector2;
        print(f"inherited prefix seen={inspector2.seen}, mismatch={inspector2.mismatch}");

        del two;
        del inherited;

        print("--- AFTER inherited-prefix deletion attempt ---");
        inspector3 = ForkInspector();
        root spawn inspector3;
        print(f"inherited prefix seen={inspector3.seen}, mismatch={inspector3.mismatch}");

        disengage;
    }
}

with entry {
    root spawn ForkSimulator();
}
