normalized view deterministically from sources, so a mapping bug is
fixed by recomputation, not by re-OCR.
"""

node SourceValue {
    has analyte_label: str = "";
    has value_text: str = "";
    has value_num: float = 0.0;
    has unit: str = "";
    has reference_text: str = "";
    has page: int = 0;
}

node Analyte {
    has analyte_code: str = "";
    has mapping_version: str = "";
}

node Conversion {
    has from_unit: str = "";
    has to_unit: str = "";
    has factor: float = 1.0;
    has conversion_version: str = "";
