"""Mutual-recursion detection across derived JsonSchema types.

Models the essential scenario from the goddtriffin/json-schema-rs issue:
two user structs (`A { b: B }` and `B { a: A }`) form a cycle. The naive
walk recurses forever; the walker here threads a visited-set through
traversal so any cycle (direct or mutual) is detected and stops with a
'$ref' report instead of overflowing.
"""

node SchemaDef {
    has type_name: str = "";
    has refs: list[str] = [];
    has factored: bool = True;
}

edge FieldRef {
    has field_name: str = "";
}

walker SchemaBuilder {
    has type_name: str = "";
    has on_stack: list[str] = [];
    has visited: list[str] = [];
    has defs: dict[str, str] = {};
    has overflow: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can build with SchemaDef entry {
        if self.overflow {
            return;
        }
        if here.type_name in self.on_stack {
            self.defs[here.type_name] = f"{'$'}ref";
            self.overflow = True;
            disengage;
        }
        if here.type_name in self.visited {
            return;
        }
        self.on_stack.append(here.type_name);
        self.visited.append(here.type_name);
        self.defs[here.type_name] = f"def:{here.type_name}";
        visit [->:FieldRef:->];
        if self.on_stack and self.on_stack[-1] == here.type_name {
            self.on_stack.pop();
        }
    }
}

with entry {
    a = SchemaDef(type_name="A");
    b = SchemaDef(type_name="B");
    root ++> a;
    a +>:FieldRef(field_name="b"):+> b;
    b +>:FieldRef(field_name="a"):+> a;

    builder = SchemaBuilder(type_name="A");
    root spawn builder;

    print(f"defs collected: {builder.defs}");
    print(f"visited order: {builder.visited}");
    print(f"on_stack residue: {builder.on_stack}");
    print(f"overflow detected: {builder.overflow}");
}
