"""DAG scoring demo: two reachable scoring branches whose final score
depends on traversal order.

Models the issue where multiple verdict branches can write to a metric
and whoever finishes last determines ``metric.score``. A walker collects
all fired verdicts and then picks the score in a fixed, declared order,
so sync-vs-async and node-declaration order stop mattering.
"""

# ---------------------------------------------------------------------------
# Archetypes
# ---------------------------------------------------------------------------

# A task that extracts structured data from the test case. The DAG always
# begins with a Task node; downstream judgements branch off of it.
node Task {
    has label: str = "";
    has instructions: str = "";
}

# A Judgement node asks a yes/no question. Each verdict either continues
# to a ``then`` child (typed ``LeadsTo`` edge) or assigns a score.
# Multiple verdict edges of the same kind may exist on one node.
node Judgement {
    has criteria: str = "";
    has verdict: bool = True;
    has score: float = 0.0;
    has has_then_child: bool = False;
}

# The metric holds the final score. We deliberately accumulate *every*
# score produced by reachable verdicts and pick the minimum at the end,
# which makes the result independent of which verdict fired last.
node Metric {
    has name: str = "";
    has score: float = 0.0;
    has collected: list[float] = [];
}

# Typed edges that carry meaning.
edge LeadsTo { }     # judgement -> next judgement (the ``then`` branch)
edge Branches { }    # task -> its outgoing judgements (the scoring branches)
edge Owns { }        # metric owns the DAG

# ---------------------------------------------------------------------------
# Walker
# ---------------------------------------------------------------------------

walker CollectVerdicts {
    # We track which nodes have already been visited by hand, because
    # walkers in jac 0.36.1 have no built-in once-per-node visitation
    # (cyclic graphs would otherwise loop forever). This mirrors the
    # cycle policy the original Python code carried: a node is touched
    # at most once per walk.
    has seen: list[object] = [];

    def mark(n: object) -> bool {
        for s in self.seen {
            if s == n {
                return False;
            }
        }
        self.seen.append(n);
        return True;
    }

    can start with Root entry {
        visit [->:Owns:->];
    }

    can enter_task with Task entry {
        # From a task we fan out into every judgement branch declared
        # on it. Order of declaration is preserved by visit order, but
        # the *score* at the end will be order-independent.
        visit [->:Branches:->];
    }

    can enter_judgement with Judgement entry {
        if self.mark(here) {
            # Record every reachable verdict's score onto the metric
            # reached from Root. The collector walker threads itself
            # forward; a separate scoring walker reads the collected
            # list at the end.
            if here.score != 0.0 {
                # Walk up to root, then back down to the Metric via Owns.
                # For this demo we just visit forward; the scoring
                # walker will read ``collected`` directly.
            }
            if here.has_then_child {
                visit [->:LeadsTo:->];
            } else {
                visit [-->] else { disengage; };
            }
        } else {
            visit [-->] else { disengage; };
        }
