walker ReleaseAuditor {
    has visited_ids: list = [];
    has report_lines: list = [];

    can start with Root entry {
        waves = [-->(?:Wave)];
        for w in waves {
            visit [-->];
        }
    }

    can audit_wave with Wave entry {
        line = f"Wave {here.ordinal}: {here.name}";
        self.report_lines.append(line);
        print(line);
        visit [-->];
