        blockers = [->:DependsOn:->];
        blocker_titles = [b.title for b in blockers];
        unblocked = len(blocker_titles) == 0;
        status = "DONE" if here.done else ("READY" if unblocked else "BLOCKED");
        owner_ok = here.owner != "";
