```jac
"""Fleet user-access differentiation: normal vs API-restricted users.

Models the core scenario from issue #51602:
  - Users have roles; some users are restricted to specific API endpoints.
  - The IT admin wants a single view listing every user with an indicator of
    whether the user has normal (full) access or is API-restricted.
  - Endpoints form a graph of allowed paths; restricted users only traverse
    the endpoints reachable from their assigned starting endpoint.

This demo replaces hand-rolled traversal machinery (id-keyed maps, manual
recursion, separate grant lists) with native Jac archetypes: nodes for
entities, typed edges for "can access" and "restricted to", and a walker
that traverses the typed-edge graph once per user, reporting a single
per-user access verdict.
"""

node Endpoint {
    has path: str = "";
    has method: str = "GET";
}

node User {
    has name: str = "";
    has email: str = "";
    has role: str = "observer";  # "admin", "maintainer", "observer", etc.
    has restricted: bool = False;
}

# Normal users get a blanket grant rooted on the API surface.
edge FullAccess {}

# Restricted users enter the API through a single starting endpoint;
# subsequent reachable endpoints are discovered by walker traversal.
edge RestrictedTo {
    has scope: str = "read";
}

# Typed edges that connect one endpoint to the next reachable endpoint.
# This is the relationship the original code represented as an adjacency
# dict keyed by endpoint id; here it is a first-class typed edge.
edge LinksTo {}

walker AccessAuditor {
    # Accumulates visited endpoints so the walker never re-enters a
    # cycle in the LinksTo graph (jac 0.36 has no built-in dedupe).
    has seen: list[str] = [];
    # The user being audited — populated when we land on a User node.
    has current_user: str = "";
    # Counters reported at the end of the walk.
    has full_users: int = 0;
    has restricted_users: int = 0;

    can start with Root entry {
        visit [-->];
    }

    # Audit each user exactly once.
    can audit_user with User entry {
        self.current_user = here.name;
        if here.restricted {
            # Restricted user: report and continue past them; the
            # restricted endpoints are traversed separately.
            print(f"[API-RESTRICTED] {here.name} <{here.email}> "
                  f"(role={here.role})");
            self.restricted_users += 1;
            visit [-->] else { disengage; }
        } else {
            # Normal user: blanket full access.
            print(f"[NORMAL ACCESS]  {here.name} <{here.email}> "
                  f"(role={here.role})");
            self.full_users += 1;
            visit [-->] else { disengage; }
        }
    }

    # Walk the API surface reachable from a restricted user's starting
    # endpoint. The typed LinksTo edges carry the relationship; the
    # guard list carries the cycle policy that the original code
    # implemented as a `set` passed through a recursive function.
    can walk_endpoint with Endpoint entry {
        if here.path in self.seen {
            # Cycle guard: domain logic preserved verbatim from the
            # original id-keyed visited set.
            visit [-->] else { disengage; }
        }
        self.seen.append(here.path);
        print(f"    reachable: {here.method} {here.path}");
        # Typed-edge traversal — replaces manual adjacency lookup.
        visit [->:LinksTo:->] else { disengage; }
    }
}

with entry {
    # Build the API endpoint graph.
    list_hosts = Endpoint(path="/api/v1/hosts", method="GET");
    get_host = Endpoint(path="/api/v1/hosts/{id}", method="GET");
    list_software = Endpoint(path="/api/v1/software/versions", method="GET");
    list_policies = Endpoint(path="/api/v1/policies", method="GET");

    # LinksTo edges define the API surface traversal.
    list_hosts +>:LinksTo:+> get_host;
    list_hosts +>:LinksTo:+> list_software;
    list_hosts +>:LinksTo:+> list_policies;

    # Users with their access pattern.
    admin = User(name="Alice Admin", email="alice@corp",
                 role="admin", restricted=False);
    maintainer = User(name="Bob Maintainer", email="bob@corp",
                      role="maintainer", restricted=False);
    observer = User(name="Cara Observer", email="cara@corp",
                    role="observer", restricted=False);

    # Restricted user: scoped to the /hosts surface only.
    host_auditor = User(name="Dan HostAuditor", email="dan@corp",
                        role="custom", restricted=True);

    # Attach users under root so the walker sees them.
    root ++> admin;
    root ++> maintainer;
    root ++> observer;
    root ++> host_auditor;

    # Normal users receive a FullAccess grant; the restricted user
    # receives a RestrictedTo grant rooted at a single endpoint.
    root +>:FullAccess:+> admin;
    root +>:FullAccess:+> maintainer;
    root +>:FullAccess:+> observer;
    host_auditor +>:RestrictedTo(scope="read"):+> list_hosts;

    # Spawn the auditor on root and report final counts.
    auditor = AccessAuditor();
    root spawn auditor;
    print(f"\naudit summary: "
          f"{auditor.full_users} normal-access users, "
          f"{auditor.restricted_users} API-restricted users");
}
