```jac
"""Model-bakery style bulk vs per-row persistence cost.

The real issue is about a Django ORM detail (bulk_create returning PKs),
but the *shape* of the problem is OSP: a parent node owns many child rows
that get saved one at a time.  We model the two persistence strategies as
walkers over a ``Main -> Related`` typed-edge chain so the contrast between
N row-saves and a single bulk save is visible at a glance.
"""

node Related {
    has label: str = "";
}

node Main {
    has name: str = "";
}

edge Owns {
    has position: int = 0;
}

walker SaveAllRelated {
    """Simulate ``bulk_create`` for the related rows: one save call total."""
    has saved: int = 0;
    has visited: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can collect with Main entry {
        # Walk all related rows reachable through the typed edge and
        # persist them in a SINGLE batch (the O(1) the issue asks for).
        relateds = [->:Owns:->];
        batch = [];
        for r in relateds {
            batch.append(r.label);
        }
        saved = len(batch);
        print(
            f"[bulk] main={here.name}: 1 save() of "
            f"{saved} related rows -> {[l for l in batch]}"
        );
    }
}

walker SaveEachRelated {
    """Simulate the old per-row behaviour: one ``save()`` per related row."""
    has saves: int = 0;
    has visited: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can per_row with Main entry {
        # Same set of related rows, but the walker descends into each
        # one individually so every entry triggers its own ability —
        # the O(N) cost the issue complains about.
        visit [->:Owns:->];
    }

    can row_save with Related entry {
        saves += 1;
        print(f"[per-row] save #{saves} for related={here.label}");
    }
}

walker ReachabilityProbe {
    """Walk the same chain from every Main, report which relateds are seen."""
    has seen: list[str] = [];
    has mains_seen: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can at_main with Main entry {
        mains_seen.append(here.name);
        visit [->:Owns:->];
    }

    can at_related with Related entry {
        seen.append(here.label);
    }
}

with entry {
    # Two main objects, each owning three related rows.  This is the
    # minimal shape of "a parent with N children" that the issue hinges on.
    root ++> Main(name="M1")
        +>:Owns(position=1):+> Related(label="r1a")
        +>:Owns(position=2):+> Related(label="r1b")
        +>:Owns(position=3):+> Related(label="r1c");
    root ++> Main(name="M2")
        +>:Owns(position=1):+> Related(label="r2a")
        +>:Owns(position=2):+> Related(label="r2b")
        +>:Owns(position=3):+> Related(label="r2c");

    # 1. Demonstrate the O(1) bulk path.
    print("--- bulk_create path (1 save per main) ---");
    bulk = root spawn SaveAllRelated();
    print(f"total save() calls in bulk path: {bulk.saved}");

    # 2. Demonstrate the O(N) per-row path the issue flags.
    print("--- per-row path (N save() per main) ---");
    per_row = root spawn SaveEachRelated();
    print(f"total save() calls in per-row path: {per_row.saves}");

    # 3. Show that the typed edge preserves the parent/child relationship
    #    when a traversal walker simply enumerates reachability.
    print("--- reachability via typed edge ---");
    probe = root spawn ReachabilityProbe();
    print(f"mains discovered: {probe.mains_seen}");
    print(f"relateds reachable: {probe.seen}");
}
