# --- Walker 2: status-banner re-export probe --------------------------------
# Models failure #2: `const props: LoginFormStatusProps = { message: 'ok' }`.
# Under vitest the type annotation is erased, so the variable is just a
# plain object. Deleting the `LoginFormStatusProps` re-export leaves the
# test green. We mirror that by checking the re-export at runtime only
# through the banner's existence.

walker ReexportProbe {
    can start with Root entry {
        print("=== Re-export probe ===");
        banner = [-->](?:LoginFormStatus);
        if banner {
            print("  LoginFormStatus re-export present at runtime.");
        } else {
            print("  LoginFormStatus re-export MISSING (test stayed green).");
        }
    }
}

# --- Walker 3: side-effect import walker ------------------------------------
# Models failure #4: the import-graph regex misses bare
# `import "./chunk-X.js"` lines. We represent chunks as nodes connected
# by typed edges. A walker that only follows edges (and not bare nodes
# with no outgoing typed edge) misses side-effect imports exactly the
# way the regex does.

edge ChunkLink { has weight: int = 0; }

walker SideEffectAware {
    has visited: list[str] = [];
    has followed_edges: int = 0;
    has missed_side_effects: int = 0;

    can start with Root entry {
        print("=== Side-effect import walk ===");
        self._follow();
    }

    def _follow() {
        for n in [-->] {
            self.followed_edges += 1;
            self.visited.append(str(n));
        }
        # Bare node with NO outgoing typed edge == side-effect import.
        bare = [-->];
        for n in bare {
            typed = n-->;
            if not typed {
                self.missed_side_effects += 1;
                print(f"  MISSED bare import: {n}");
            }
        }
        print(
            f"  Followed {self.followed_edges} typed edges, "
            f"missed {self.missed_side_effects} side-effect imports."
        );
    }
}

# --- Demo graph -------------------------------------------------------------
with entry {
    root ++> LoginFormRoot()
        ++> LoginFormSubmit()
        ++> LoginFormRemember()
        ++> LoginFormStatus(message="ok");

    root spawn PropAuditor();
    root spawn ReexportProbe();

