    chunk_a = root ++> LoginFormSubmit(label="Edge-A");
    chunk_b = chunk_a +>:ChunkLink(weight=1):+> LoginFormRemember();
    # Bare side-effect "import" — no outgoing typed edge.
    root ++> LoginFormStatus(message="bare");

    root spawn SideEffectAware();
}
