Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.

```jac
"""Parallel pipeline stage execution modeled with a dependency graph.

Stages are nodes; declared `depends_on` relationships become typed edges.
A scheduler walker walks the graph in dependency order (topological order
by depth in the dependency DAG), respecting the source rule that a stage
must wait for its prerequisites before running. A cycle-detection walker
flags cycles that would deadlock the parallel executor.
"""

# ---------- Edge archetypes --------------------------------------------------

edge DependsOn {
    # Payload: the declared prerequisite stage name. Keeps the typed edge
    # useful as a debugging/introspection surface (the dependency list is
    # observable on the edge itself).
    has prerequisite: str = "";
}

# ---------- Node archetypes --------------------------------------------------

node Stage {
    has name: str = "";
    has duration: float = 0.0;     # simulated work units
    has depends_on: list[str] = []; # declared prerequisites (kept on node)
    has status: str = "pending";    # pending | ready | running | done | failed
    has depth: int = 0;             # longest path from a root stage (dep-depth)
}

node Pipeline {
    has title: str = "";
    has template_flag: str = "";   # e.g. "parallel-eligible"
}

# ---------- Walker: dependency-aware scheduler -------------------------------

walker Scheduler {
    has log: list[str] = [];

    # Start at the root, hop to the pipeline, then fan out along its stages.
    can begin with Root entry {
        visit [-->];
    }

    can enter_pipeline with Pipeline entry {
        self.log.append(f"pipeline[{self.title}] template={self.template_flag}");
        visit [-->];
    }

    # Walk stages via the typed `DependsOn` edges. The set of outgoing
    # DependsOn edges from a stage IS its dependency list, so we traverse
    # prerequisites first and only then mark the current stage ready.
    can schedule with Stage entry {
        # Wait for prerequisites: walk every DependsOn edge to the
        # prerequisite stage, log it, then come back. Visiting a stage
        # via typed-edge traversal is the native equivalent of "for each
        # depends_on[name], look it up in the registry and recurse".
        visit [->:DependsOn:->];

        prereq_count = len([->:DependsOn:->]);
        self.log.append(
            f"stage[{here.name}] depth={here.depth} prereqs={prereq_count} status={here.status}"
        );
        here.status = "ready";
    }

    # After visiting all prerequisites of a stage, mark the stage done
    # and continue forward to the next stage in the chain.
    can finish with Stage exit {
        here.status = "done";
        visit [-->];
    }
}

# ---------- Walker: cycle detection -----------------------------------------

walker CycleFinder {
    has stack: list[str] = [];
    has cycle: list[str] = [];

    can begin with Root entry {
        visit [-->];
    }

    can enter_pipeline with Pipeline entry {
        visit [-->];
    }

    # DFS along DependsOn edges with an explicit cycle guard. Jac 0.36
    # walkers do NOT dedupe cyclic graphs on their own, so this guard set
    # is required domain logic — not scaffolding.
    can trace with Stage entry {
        if here.name in self.stack {
            self.cycle = [here.name] + [s for s in self.stack];
            disengage;
        }
        self.stack.append(here.name);
        # Recurse into prerequisites. If a cycle is found mid-walk,
        # disengage so the walker halts cleanly.
        visit [->:DependsOn:->];
        self.stack.pop();
    }
}

# ---------- Walker: parallel executor simulator ------------------------------

walker ParallelExecutor {
    # Simulates the "spawn independent stages in their own tmux pane"
    # behavior: groups stages by dependency depth and "runs" every stage
    # at depth N concurrently. This is the wall-clock shortcut the issue
    # is asking for.
    has wall_clock: float = 0.0;
    has lanes: list[list[str]] = [];   # each lane = stages running in parallel
    has failures: list[str] = [];

    can begin with Root entry {
        visit [-->];
    }

    can enter_pipeline with Pipeline entry {
        # Bucket stages by depth (parallel lane = depth bucket).
        bucketed: dict[int, list[str]] = {};
        for st in [-->] {
            if here.status == "failed" {
                self.failures.append(st.name);
                continue;
            }
            existing = bucketed.get(st.depth, []);
            existing.append(st.name);
            bucketed[st.depth] = existing;
        }
        max_depth = -1;
        for d in bucketed.keys() {
            max_depth = d if d > max_depth else max_depth;
        }
        # The longest stage at each depth drives that lane's wall-clock cost.
        d = 0;
        while d <= max_depth {
            lane = bucketed.get(d, []);
            self.lanes.append(lane);
            lane_cost = 0.0;
            for name in lane {
                dur = 0.0;
                for st in [-->] {
                    if st.name == name {
                        dur = st.duration;
                    }
                }
                lane_cost = dur if dur > lane_cost else lane_cost;
            }
            self.wall_clock = self.wall_clock + lane_cost;
            d = d + 1;
        }
    }
}

# ---------- Demo wiring -----------------------------------------------------

with entry {
    # Build the issue's example: three independent pairs that can run in
    # parallel (intake+intelligence, review+security-audit, test+docs).
    pipe = Pipeline(title="shipwright-ci", template_flag="parallel-eligible");

    intake       = Stage(name="intake",         duration=10.0);
    intelligence = Stage(name="intelligence",   duration=12.0, depends_on=["intake"]);
    review       = Stage(name="review",         duration=15.0, depends_on=["intelligence"]);
    sec_audit    = Stage(name="security-audit", duration=8.0,  depends_on=["intelligence"]);
    test         = Stage(name="test",           duration=20.0, depends_on=["review"]);
    docs         = Stage(name="docs",           duration=6.0,  depends_on=["review"]);

    # Compute dep-depth: longest path of DependsOn from any root stage.
    # Roots have depth 0; children = max(parent depth) + 1.
    ordered = [intake, intelligence, review, sec_audit, test, docs];
    remaining = len(ordered);
    progress = 0;
    while progress < remaining {
        for st in ordered {
            if not st.depends_on {
                st.depth = 0;
            } else {
                max_parent = -1;
                for parent_name in st.depends_on {
                    for parent in ordered {
                        if parent.name == parent_name and parent.depth > max_parent {
                            max_parent = parent.depth;
                        }
                    }
                }
                st.depth = max_parent + 1;
            }
        }
        progress = progress + 1;
    }

    # Wire dependencies as typed edges (the relationship carries meaning).
    pipe ++> intake ++> intelligence ++> review ++> test;
    pipe ++> sec_audit;
    pipe ++> docs;
    intelligence +>:DependsOn(prerequisite="intake"):+> intake;
    review +>:DependsOn(prerequisite="intelligence"):+> intelligence;
    sec_audit +>:DependsOn(prerequisite="intelligence"):+> intelligence;
    test +>:DependsOn(prerequisite="review"):+> review;
    docs +>:DependsOn(prerequisite="review"):+> review;

    # 1. Scheduler walker: traverses the DAG in dependency order and
    #    prints a readiness log.
    root spawn Scheduler();

    # 2. Cycle finder: confirms the demo graph is acyclic.
    finder = CycleFinder();
    root spawn finder;
    cycle_found = finder.cycle;
    print(f"cycle detected: {cycle_found}");

    # 3. Parallel executor: groups stages by depth and sums wall-clock
    #    cost as the max duration per lane (independent stages parallel).
    executor = ParallelExecutor();
    root spawn executor;
    seq = 0.0;
    for st in ordered {
        seq = seq + st.duration;
    }
    saved = seq - executor.wall_clock;
    pct = (saved / seq) * 100.0 if seq > 0.0 else 0.0;
    print(f"lanes (parallel): {executor.lanes}");
    print(f"sequential wall-clock = {seq}");
    print(f"parallel   wall-clock = {executor.wall_clock}");
    print(f"saved {saved:.1f} units ({pct:.1f}%) — target is >25%");
}
