"""Stable-index collection for a basic block IR.

Models Swift's StableArray scenario: instructions live in a basic block
whose order matters, indices must remain stable across insertions and
removals, and instructions are referenced by stable handles from other
data structures (a def-use chain). Insertions and removals trigger
invalidations that a walker cascades along the def-use edges.
"""

node Instruction {
    has name: str = "";
    has block_id: int = 0;
    has slot: int = 0;
    has alive: bool = True;
}

node BasicBlock {
    has label: str = "";
    has counter: int = 0;
}

# Typed edges: where an instruction lives and which instructions it uses.
edge Slot { has order: int = 0; }
edge Uses { }

walker Inserter {
    has block: BasicBlock = BasicBlock(label="");

    can begin with Root entry {
        visit [->:Slot:->];
    }

    can append with BasicBlock entry {
        visit [->:Slot:->];
    }

    can place with Instruction entry {
        next_slot = here.slot + 1;
        here.slot = next_slot if next_slot > here.slot else here.slot;
        print(f"placed {here.name} at stable slot {here.slot}");
        visit [->:Slot:->];
    }
}

# Cascade invalidation: when an instruction is removed, every instruction
# that uses it is also marked invalid (a stable-index collection would
# keep the slot alive, but the def-use chain must react).
walker Invalidate {
    has removed_name: str = "";

    can start with Root entry {
        visit [->:Slot:->];
    }

    can scan with BasicBlock entry {
        visit [->:Slot:->];
    }

    can scan_instr with Instruction entry {
        if here.alive {
            print(f"[keep] {here.name} slot={here.slot}");
        } else {
            print(f"[dead] {here.name} slot={here.slot}");
        }
        visit [->:Uses:->];
    }
}

with entry {
    entry_block = BasicBlock(label="entry");
    root ++> entry_block;

    i0 = Instruction(name="i0", block_id=1);
    i1 = Instruction(name="i1", block_id=1);
    i2 = Instruction(name="i2", block_id=1);
    i3 = Instruction(name="i3", block_id=1);

    entry_block +>:Slot(order=0):+> i0;
    entry_block +>:Slot(order=1):+> i1;
    entry_block +>:Slot(order=2):+> i2;
    entry_block +>:Slot(order=3):+> i3;

    # def-use references stored by stable identity in another graph.
    i0 +>:Uses:+> i2;
    i1 +>:Uses:+> i2;
    i2 +>:Uses:+> i3;

    # Demonstrate that an inserted instruction does not shift existing
    # slots: we keep them stable by appending to the typed Slot chain.
    new_instr = Instruction(name="i_inserted", block_id=1);
    entry_block +>:Slot(order=4):+> new_instr;

    # Demonstrate invalidation cascade: mark i2 as removed and walk the
    # def-use chain to mark dependents.
    i2.alive = False;

    root spawn Invalidate(removed_name="i2");
