"""Gallery security console: log every visitor, but for curators also record an official inspection and count rooms they inspected."""

node Room {
    has name: str = "";
    has log: list[str] = [];
    has inspections: list[dict] = [];
}

walker Visitor {
    has visitor_name: str = "";

    can start with Root entry {
        visit [-->];
