Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.

```jac
"""Employee hierarchy traversal: walking parent/child links the way WITH RECURSIVE would.

Models the sqlc issue scenario where recursive CTE traversal walks an employee
manager chain. A walker descends the parent_id edges to gather the whole
reporting subtree, mirroring the UNION ALL recursive query. A second walker
demonstrates cascade soft-delete: invalidating one employee propagates the
"deleted" flag to every descendant reachable through the ReportsTo edges.
"""

node Employee {
    has name: str = "";
    has employee_id: int = 0;
    has parent_id: int | None = None;
    has deleted: str | None = None;
}

edge ReportsTo {
    # The typed edge that replaces the manual parent_id recursion:
    # "this employee reports to that employee".
    has since: str = "";
}

# A walker that mirrors WITH RECURSIVE parent_tree: starting from a root
# employee, descend every ReportsTo edge to collect the full reporting
# subtree, then emit a single ordered report.
walker SubtreeCollector {
    has start_id: int = 0;
    has ordered: list[int] = [];
    has visited: list[int] = [];

    can begin with Root entry {
        print(f"Collecting subtree rooted at employee_id={self.start_id}");
        visit [-->];
    }

    can collect with Employee entry {
        if here.employee_id in self.visited {
            # Cycle policy: explicit guard against repeated visitation
            # (jac 0.36.1 walkers have no built-in dedup on cycles).
            return;
        }
        self.visited.append(here.employee_id);
        if here.deleted is not None {
            # Skip soft-deleted nodes: they are not part of the live tree.
            return;
        }
        self.ordered.append(here.employee_id);
        visit [->:ReportsTo:->] else { disengage; }
    }
}

# A walker that performs cascade soft-delete: starting from a target
# employee, mark every reachable descendant as deleted in one pass.
walker CascadeDeleter {
    has start_id: int = 0;
    has invalidations: list[int] = [];
    has visited: list[int] = [];

    can begin with Root entry {
        print(f"Cascade soft-delete starting at employee_id={self.start_id}");
        visit [-->];
    }

    can invalidate with Employee entry {
        if here.employee_id in self.visited {
            # Explicit cycle policy: guard against revisiting nodes.
            return;
        }
        self.visited.append(here.employee_id);
        here.deleted = "now";
        self.invalidations.append(here.employee_id);
        visit [->:ReportsTo:->] else { disengage; }
    }
}

with entry {
    # Build a small reporting tree:
    #   1 (CEO) -> 2 (Eng Lead) -> 3 (Eng IC)
    #                          -> 4 (Eng IC)
    #           -> 5 (Sales Lead) -> 6 (Sales IC)
    ceo = Employee(name="Alice", employee_id=1, parent_id=None);
    eng_lead = Employee(name="Bob", employee_id=2, parent_id=1);
    eng_ic_a = Employee(name="Carol", employee_id=3, parent_id=2);
    eng_ic_b = Employee(name="Dan", employee_id=4, parent_id=2);
    sales_lead = Employee(name="Eve", employee_id=5, parent_id=1);
    sales_ic = Employee(name="Frank", employee_id=6, parent_id=5);

    # Wire the tree using typed ReportsTo edges.
    ceo +>:ReportsTo(since="2020-01-01"):+> eng_lead;
    ceo +>:ReportsTo(since="2020-01-01"):+> sales_lead;
    eng_lead +>:ReportsTo(since="2021-06-15"):+> eng_ic_a;
    eng_lead +>:ReportsTo(since="2022-03-01"):+> eng_ic_b;
    sales_lead +>:ReportsTo(since="2022-09-10"):+> sales_ic;

    root ++> ceo;

    # First walker: gather the whole reporting subtree under the CEO,
    # mirroring the recursive CTE that joins on parent_id.
    collector = SubtreeCollector(start_id=1);
    root spawn collector;
    ids = collector.ordered;
    print(f"Subtree order under CEO: {ids}");

    # Second walker: cascade soft-delete the Eng Lead subtree and
    # show that descendants get the deleted flag propagated.
    deleter = CascadeDeleter(start_id=2);
    root spawn deleter;
    print(f"Cascade-deleted: {deleter.invalidations}");

    # Confirm the propagation by re-reading the affected employees.
    print(f"eng_lead.deleted = {eng_lead.deleted}");
    print(f"eng_ic_a.deleted = {eng_ic_a.deleted}");
    print(f"eng_ic_b.deleted = {eng_ic_b.deleted}");
    print(f"sales_lead.deleted = {sales_lead.deleted}");
}
```

