Build a toll plaza collector for gate G-4: cars pay $2.50, trucks pay $2.50 plus 50 cents per ton, motorcycles pay $1.00. Print one payment line per vehicle describing it, and report the revenue collected after the sweep.

```jac
"""Toll plaza G-4: collect per-vehicle tolls and report total revenue."""

node Vehicle {
    has kind: str = "";
    has tons: float = 0.0;
    has rate: float = 0.0;
}

edge Lane {
    has label: str = "";
}

walker TollCollector {
    has total: float = 0.0;

    can start with Root entry {
        print("Plaza G-4 open");
        visit [-->];
    }

    can enter_lane with Lane entry {
        print(f"  [{here.label}] sweeping");
        visit [-->];
    }

    can charge with Vehicle entry {
        # Trucks pay base $2.50 + $0.50/ton; cars and motorcycles flat.
        amount = here.rate + (0.50 * here.tons) if here.kind == "truck" else here.rate;
        self.total = self.total + amount;
        print(f"    {here.kind}: paid ${amount:.2f}");
        visit [-->];
    }
}

with entry {
    gate = Lane(label="G-4");
    root ++> gate;

    gate ++> Vehicle(kind="car", rate=2.50);
    gate ++> Vehicle(kind="truck", rate=2.50, tons=8.0);
    gate ++> Vehicle(kind="motorcycle", rate=1.00);
    gate ++> Vehicle(kind="truck", rate=2.50, tons=12.5);
    gate ++> Vehicle(kind="car", rate=2.50);

    collector = TollCollector();
    root spawn collector;
    print(f"Total revenue at G-4: ${collector.total:.2f}");
}
